INSERT INTO `judge_organization` VALUES
(1,'DMOJ: Modern Online Judge','dmoj','DMOJ','This is a sample organization. You can use organizations to split up your user base, host private contests, and more.','2017-12-02 08:50:25.199000',0,NULL,NULL,'',0),
(2,'Universidad Católica del Maule','universidad-catolica-del-maule','UCM','La Universidad Católica del Maule (UCM) es una institución de educación superior fundada el 10 de julio de 1991, derivada de la antigua Sede Regional de la Pontificia Universidad Católica de Chile, con orígenes que se remontan a las Escuelas Normales de la década de 1950. Su casa central se encuentra en Talca y cuenta con sedes en Curicó y Los Niches, integrándose al Consejo de Rectores de las Universidades Chilenas (CRUCH), a la Red G9 de universidades públicas no estatales y a la Agrupación de Universidades Regionales de Chile.','2025-08-05 19:56:21.352475',0,NULL,NULL,'',0),
(3,'Selección de Ingeniería Matemática ICPC','ima-icpc','IMA ICPC','Grupo de estudiantes de la selección de Ingeniería Mátemática que participa en la ICPC y TCP','2025-10-28 21:33:40.719895',0,NULL,NULL,'',0),
(4,'Doctorado en Modelamiento Matemático Aplicado','dm2a','DM2A','# Doctorado en Modelamiento Matemático Aplicado','2026-04-21 18:36:46.084585',0,NULL,NULL,'',0);
