(26,'while True:\r\n    tamo = input()\r\n    if tamo == \"0 0\":\r\n        break\r\n    else:\r\n        altura, ancho = map(int, tamo.split())\r\n        pintura1 = []\r\n        for _ in range(altura):\r\n            fila1 = input().split()\r\n            pintura1.append(fila1)\r\n        pintura2 = []\r\n        for _ in range(altura):\r\n            fila2 = input().split()\r\n            pintura2.append(fila2)\r\n        errores = 0\r\n        aciertos = 0\r\n        for i in range(altura):\r\n            for j in range(ancho):\r\n                if pintura1[i][j] == pintura2[i][j]:\r\n                    aciertos += 1\r\n                else:\r\n                    errores += 1\r\n        tamao = errores + aciertos\r\n        if tamao/10 >errores:\r\n            print(\"La pintura es original\")\r\n        else:\r\n            print(\"La pintura no es original\")','America/Toronto',93,92.96362232981328,93,'github','2026-09-02 16:27:23.516966','172.16.108.95','user',0,0,NULL,'','auto',0,NULL,NULL,NULL,8,30,'b10f0b754a9d4ae4aa0f8a2fe1adf5726f605976412a8f8ecee8ad1ee76caf01',0,NULL,'gAAAAABqPKWpvuyNqDSlN0r7a8Fy6eXkThia5mCTsoFIpgUeVWB_YaHF3N7HiFhmh4scXx-N-PGdfZsEJ-3RxT2v-27EX5nww7HoBjZQTqStTlN6TZb5XJv6uI3V-V1sui8fUpVo_w8Ed_VyKbEUHLXH6RTbaQW9ZZ22srGMcmCJsM8ilvyw3cY0UgfqCpv3rb8uwUO35ZpEfnXMzOi2Z4hoyRFREewDXA==',0,'',0),
