(1,'# Leer el número de problemas\r\nn = int(input().strip())\r\n\r\n# Procesar cada problema\r\nfor _ in range(n):\r\n    a, b = map(int, input().split())\r\n    print(a + b)',1),
(2,'import sys\r\n\r\ndef solve():\r\n    # π con 8 decimales\r\n    pi = 3.14159265\r\n\r\n    # Leer diámetro desde stdin\r\n    data = sys.stdin.readline().strip()\r\n    if not data:\r\n        return\r\n    d = float(data)\r\n\r\n    # Calcular radio y área\r\n    r = d / 2.0\r\n    area = pi * r * r\r\n\r\n    # Salida formateada con 2 decimales\r\n    sys.stdout.write(f\"{area:.2f}\")\r\n\r\nif __name__ == \"__main__\":\r\n    solve()',2),
(3,'pi = 3.14159265\r\nd = float(input())\r\nprint(f\"{pi*(d/2)**2:.2f}\")',3),
