(234,'for i in range(1,2):\r\n    entrada=input()\r\n    a,b=entrada.split(\" \")\r\n    a=int(a)\r\n    b=int(b)\r\n\r\n    if b<=40:\r\n      preciofinal=b*a\r\n      print(\"%.1f\"% preciofinal)\r\n    elif b>40:\r\n      precionormal=a*40\r\n      horasextra=b-40\r\n      pagaconhorasextra=(horasextra*a)*3/2\r\n      pagatotal=precionormal+pagaconhorasextra\r\n      print(\"%.1f\" % pagatotal)',234),
(235,'n=int(input())\r\nperfectos=[]\r\nfor i in range (1,n+1):\r\n    acumulador=0\r\n    for k in range (1,i):\r\n        if i%k==0:\r\n            acumulador=acumulador+k\r\n    if acumulador==i:\r\n        perfectos.append(i)\r\nlinea_f=\"\"\r\nfor j in range (len(perfectos)):\r\n    if j==0:\r\n        linea_f=linea_f+f\"{perfectos[j]}\"\r\n    else:\r\n        linea_f=linea_f+\" \"+f\"{perfectos[j]}\"\r\nprint(linea_f)',235),
(236,'for i in range (1,2):\r\n    entrada=input()\r\n    p,h=entrada.split (\" \")\r\n    p=int(p)\r\n    h=int(h)\r\n    if h<=40:\r\n        preciofinal= p*h \r\n        print (\"%.1f\" % preciofinal)\r\n    else: \r\n        precioinsano= p*40\r\n        horasplus= h-40\r\n        pagachinchin= precioinsano + 1.5*horasplus*precioinsano\r\n        print (\"%.1f\" % pagachinchin)',236),
(237,'n=int(input())\r\nif n<6:\r\n    print(\"Sin numeros perfectos\")\r\nelse:\r\n    acumulador=0\r\n    perfectos=[]\r\n    for i in range (1,n+1):\r\n        acumulador=0\r\n        for k in range (1,i):\r\n            if i%k==0:\r\n                acumulador=acumulador+k\r\n        if acumulador==i:\r\n            perfectos.append(i)\r\n    linea_f=\"\"\r\n    for j in range (len(perfectos)):\r\n        if j==0:\r\n            linea_f=linea_f+f\"{perfectos[j]}\"\r\n        else:\r\n            linea_f=linea_f+\" \"+f\"{perfectos[j]}\"\r\n    print(linea_f)',237),
(238,'for i in range (1,2):\r\n    entrada=input()\r\n    p,h=entrada.split (\" \")\r\n    p=int(p)\r\n    h=int(h)\r\n    if h<=40:\r\n        preciofinal= p*h \r\n        print (\"%.1f\" % preciofinal)\r\n    else: \r\n        precioinsano= p*40\r\n        horasplus= h-40\r\n        pagachinchin= precioinsano + (1.5*p*horasplus)\r\n        print (\"%.1f\" % pagachinchin)',238),
(239,'def es_perfecto(num):\r\n    if num < 2:\r\n        return False\r\n    suma = 1  # 1 siempre es divisor\r\n    for i in range(2, int(num**0.5) + 1):\r\n        if num % i == 0:\r\n            suma += i\r\n            if i != num // i:  # agregar el divisor complementario\r\n                suma += num // i\r\n    return suma == num\r\n\r\ndef main():\r\n    n = int(input().strip())\r\n    perfectos = [str(i) for i in range(2, n) if es_perfecto(i)]\r\n    \r\n    if perfectos:\r\n        print(\" \".join(perfectos))\r\n    else:\r\n        print(\"Sin numeros perfectos\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',239),
(240,'a,b,c=list(map(int,input().split()))\r\nwhile True:\r\n    try:\r\n        raiz1=(-b+(b**2-(4*a*c))**0.5)/(2*a)\r\n        raiz2=(-b-(b**2-4*a*c)**0.5)/(2*a)\r\n        if raiz1>raiz2:\r\n            print(\"%.6f\"%raiz2,\"%.6f\"%raiz1)\r\n            break\r\n        else:\r\n            print(\"%.6f\"%raiz1,\"%.6f\"%raiz2)\r\n            break\r\n    except TypeError:\r\n        print(\"No tiene raices reales\")\r\n        break',240),
(241,'n=int(input())\r\nif n<6:\r\n    print(\"Sin numeros perfectos\")\r\nelse:\r\n    perfectos=[]\r\n    for i in range (1,n+1):\r\n        acumulador=0\r\n        for k in range (1,i):\r\n            if i%k==0:\r\n                acumulador=acumulador+k\r\n        if acumulador==i:\r\n            perfectos.append(i)\r\n    linea_f=\"\"\r\n    for j in range (len(perfectos)):\r\n        if j==0:\r\n            linea_f=linea_f+f\"{perfectos[j]}\"\r\n        else:\r\n            linea_f=linea_f+\" \"+f\"{perfectos[j]}\"\r\n    print(linea_f)',241),
(242,'def es_perfecto(num):\r\n    if num < 2:\r\n        return False\r\n    suma = 1  # 1 siempre es divisor\r\n    for i in range(2, int(num**0.5) + 1):\r\n        if num % i == 0:\r\n            suma += i\r\n            if i != num // i:\r\n                suma += num // i\r\n    return suma == num\r\n\r\ndef main():\r\n    n = int(input().strip())\r\n    perfectos = [str(i) for i in range(2, n) if es_perfecto(i)]\r\n    \r\n    if perfectos:\r\n        print(\"\\n\".join(perfectos))\r\n    else:\r\n        print(\"Sin numeros perfectos\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',242),
(243,'import math\r\n\r\ndef main():\r\n    try:\r\n        A, B, C = map(int, input().split())\r\n    except:\r\n        return\r\n    \r\n    if A == 0:  # No es cuadrática\r\n        if B == 0:\r\n            print(\"No tiene raices reales\")\r\n        else:\r\n            root = -C / B\r\n            print(f\"{root:.6f} {root:.6f}\")\r\n        return\r\n    \r\n    discriminante = B * B - 4 * A * C\r\n    \r\n    if discriminante < 0:\r\n        print(\"No tiene raices reales\")\r\n    else:\r\n        sqrt_disc = math.sqrt(discriminante)\r\n        x1 = (-B - sqrt_disc) / (2 * A)\r\n        x2 = (-B + sqrt_disc) / (2 * A)\r\n        r1, r2 = sorted([x1, x2])\r\n        print(f\"{r1:.6f} {r2:.6f}\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',243),
(244,'n=int(input())\r\nif n<6:\r\n    print(\"Sin numeros perfectos\")\r\nelse:\r\n    perfectos=[]\r\n    for i in range (1,n+1):\r\n        acumulador=0\r\n        for k in range (1,i):\r\n            if i%k==0:\r\n                acumulador=acumulador+k\r\n        if acumulador==i:\r\n            print(i)',244),
