(263,'from itertools import combinations\r\n\r\nN=int(input())\r\n\r\nfor i in range (N):\r\n\r\n    contador=0\r\n    L=int(input())\r\n    lista=[]\r\n    lista=list(map(float,input().split()))\r\n\r\n    if L%2==0:\r\n        for k in range ((len(lista)+1)):\r\n            combinaciones=list(combinations(lista,k))\r\n            \r\n            for l in range(len(combinaciones)):\r\n\r\n                copia=lista.copy()\r\n\r\n                combinacion=list(combinaciones[l])\r\n\r\n                for j in range (len(combinacion)):\r\n                    \r\n                    if combinacion[j] in copia:\r\n\r\n                        copia.remove(combinacion[j])\r\n                \r\n                if sum(copia)==sum(combinacion):\r\n                    contador+=1\r\n    else:\r\n        for z in range (L):\r\n            nuevalista=lista.copy()\r\n            nuevalista.remove(nuevalista[z])\r\n            for k in range ((len(nuevalista)+1)):\r\n                combinaciones=list(combinations(nuevalista,k))\r\n            \r\n                for l in range(len(combinaciones)):\r\n\r\n                    copia=nuevalista.copy()\r\n\r\n                    combinacion=list(combinaciones[l])\r\n\r\n                    for j in range (len(combinacion)):\r\n                    \r\n                        if combinacion[j] in copia:\r\n\r\n                            copia.remove(combinacion[j])\r\n                \r\n                    if sum(copia)==sum(combinacion):\r\n                        contador+=1\r\n    print(contador*2)',263),
