(271,'from itertools import combinations\r\nN=int(input())\r\nfor i in range (N):\r\n    contador=0\r\n    L=int(input())\r\n    lista=[]\r\n    lista=list(map(float,input().split()))  \r\n    if L%2==0:\r\n        for k in range ((len(lista)+1)):\r\n            combinaciones=list(combinations(lista,k))\r\n            SUMA=sum(lista)/2\r\n            for l in range(len(combinaciones)):\r\n                combinacion=list(combinaciones[l])\r\n                if sum(combinacion)==SUMA:\r\n                    contador+=1\r\n\r\n    else:\r\n        for z in range (L):\r\n            \r\n            nuevalista=lista.copy()\r\n            nuevalista.remove(nuevalista[z])\r\n            SUMA=sum(nuevalista)/2\r\n            for k in range ((len(nuevalista)+1)):\r\n                combinaciones=list(combinations(nuevalista,k))           \r\n                for l in range(len(combinaciones)):   \r\n                    combinacion=list(combinaciones[l])\r\n                    if sum(combinacion)==SUMA:\r\n                        contador+=1\r\n    print(contador*2)',271),
(272,'from itertools import combinations\r\nfrom math import factorial\r\nN=int(input())\r\nfor i in range (N):\r\n    contador=0\r\n    L=int(input())\r\n    lista=[]\r\n    lista=list(map(float,input().split()))  \r\n    if L%2==0:\r\n        combinaciones=list(combinations(lista,(int(L/2))))\r\n        SUMA=sum(lista)/2\r\n        for j in range (len(combinaciones)):\r\n            combinacion=combinaciones[j]\r\n            if sum(combinacion)==SUMA:\r\n                contador=contador+factorial(len(combinacion))\r\n    else:\r\n        for z in range (L):\r\n            \r\n            nuevalista=lista.copy()\r\n            nuevalista.remove(nuevalista[z])\r\n            SUMA=sum(nuevalista)/2\r\n            combinaciones=list(combinations(nuevalista,(L//2)))\r\n            for l in range(len(combinaciones)):   \r\n                combinacion=combinaciones[l]\r\n                if sum(combinacion)==SUMA:\r\n                    contador=contador+factorial(len(combinacion))\r\n    print(contador*2)',272),
(273,'t=int(input())\r\ncontador=0\r\nfor i in range (t):\r\n    n=int(input()) #longitud arreglos\r\n    arreglo1=list(map(int,input().split()))\r\n    arreglo2=list(map(int,input().split()))\r\n    for i in range (n):\r\n        for j in range (i+1,n):\r\n            ai=arreglo1[i]\r\n            aj=arreglo1[j]\r\n            bi=arreglo2[i]\r\n            bj=arreglo2[j]\r\n            if (ai*aj)==(bi+bj):\r\n                print(f\"({i+1},{j+1})\")\r\n                contador+=1\r\n    print(contador)\r\n    contador=0',273),
(274,'from itertools import permutations\r\nn=int(input())\r\nparticipantes=list(map(int,input().split()))\r\npermutaciones=list(permutations(participantes))\r\npermutaciones.sort()\r\nfor i in range (len(permutaciones)):\r\n    permutacion=permutaciones[i]\r\n    bandera=\"1\"\r\n    for j in range (len(permutacion)):\r\n        if j==0:\r\n            if permutacion[j]<18:\r\n                if permutacion[j+1]<18:\r\n                    bandera=\"NO\"\r\n        elif j==(len(permutacion)-1):\r\n            if permutacion[j]<18:\r\n                if permutacion[j-1]<18:\r\n                    bandera=\"NO\"\r\n        else:\r\n            if permutacion[j]<18:\r\n                if permutacion[j-1]<18 and permutacion[j+1]<18:\r\n                    bandera=\"NO\"\r\n    if bandera!=\"NO\":\r\n        X=\"\"\r\n        for i in range (len(permutacion)):\r\n            if i==0:\r\n               X=f\"{permutacion[i]}\"\r\n            else:\r\n                X=X+\" \"+f\"{permutacion[i]}\"\r\n        print(X)',274),
(275,'conexiones=[]\r\nestrellas=[]\r\nn,m=map(int,input().split())\r\nbrillos=list(map(int,input().split()))\r\nMaximoBrillo=0\r\nfor i in range (m):\r\n    conexiones.append(list(map(int,input().split())))\r\n\r\n##misión: crear listas :D\r\nfor i in range (m):\r\n    conex=conexiones[i].copy()\r\n    conexiones_copy=conexiones.copy()\r\n    conexiones_copy.remove(conex)\r\n    for k in range (m-1): ## se busca la constelación a la que pertenece conex\r\n        for j in range(m-1):\r\n            X=conexiones_copy[j]\r\n            A=X[0]\r\n            B=X[1]\r\n            if A in conex and B not in conex:\r\n                conex.append(B)\r\n            if B in conex and A not in conex:\r\n                conex.append(A)\r\n    ## ahora que tengo la conexión, quiero conocer la cantidad de brillo de la constelación \"conex\"\r\n    for i in range(len(conex)):\r\n        conex.insert(i,brillos[conex[i]-1])\r\n        x=conex.pop(i+1)\r\n    BRILLO=sum(conex)\r\n    if BRILLO>=MaximoBrillo:\r\n        MaximoBrillo=BRILLO\r\nprint(MaximoBrillo)',275),
(276,'conexiones=[]\r\nestrellas=[]\r\nn,m=map(int,input().split())\r\nbrillos=list(map(int,input().split()))\r\nMaximoBrillo=0\r\nfor i in range (m):\r\n    conexiones.append(list(map(int,input().split())))\r\n\r\n##misión: crear listas :D\r\nfor i in range (m):\r\n    conex=conexiones[i].copy()\r\n    conexiones_copy=conexiones.copy()\r\n    conexiones_copy.remove(conex)\r\n    for k in range (m-1): ## se busca la constelación a la que pertenece conex\r\n        for j in range(m-1):\r\n            X=conexiones_copy[j]\r\n            A=X[0]\r\n            B=X[1]\r\n            if A in conex and B not in conex:\r\n                conex.append(B)\r\n            if B in conex and A not in conex:\r\n                conex.append(A)\r\n    ## ahora que tengo la conexión, quiero conocer la cantidad de brillo de la constelación \"conex\"\r\n    for i in range(len(conex)):\r\n        conex.insert(i,brillos[conex[i]-1])\r\n        x=conex.pop(i+1)\r\n    BRILLO=sum(conex)\r\n    if BRILLO>=MaximoBrillo:\r\n        MaximoBrillo=BRILLO\r\nprint(MaximoBrillo)',276),
(277,'conexiones=[]\r\nestrellas=[]\r\nn,m=map(int,input().split())\r\nbrillos=list(map(int,input().split()))\r\nMaximoBrillo=0\r\nfor i in range (m):\r\n    conexiones.append(list(map(int,input().split())))\r\n\r\n##misión: crear listas :D\r\nfor i in range (m):\r\n    conex=conexiones[i].copy()\r\n    conexiones_copy=conexiones.copy()\r\n    conexiones_copy.remove(conex)\r\n    for k in range (m-1): ## se busca la constelación a la que pertenece conex\r\n        for j in range(m-1):\r\n            X=conexiones_copy[j]\r\n            A=X[0]\r\n            B=X[1]\r\n            if A in conex and B not in conex:\r\n                conex.append(B)\r\n            if B in conex and A not in conex:\r\n                conex.append(A)\r\n    ## ahora que tengo la conexión, quiero conocer la cantidad de brillo de la constelación \"conex\"\r\n    for i in range(len(conex)):\r\n        conex.insert(i,brillos[conex[i]-1])\r\n        x=conex.pop(i+1)\r\n    BRILLO=sum(conex)\r\n    if BRILLO>=MaximoBrillo:\r\n        MaximoBrillo=BRILLO\r\nprint(MaximoBrillo)',277),
(278,'conexiones=[]\r\nestrellas=[]\r\nn,m=map(int,input().split())\r\nbrillos=list(map(int,input().split()))\r\nMaximoBrillo=0\r\nfor i in range (m):\r\n    conexiones.append(list(map(int,input().split())))\r\n\r\n##misión: crear listas :D\r\nfor i in range (m):\r\n    conex=conexiones[i].copy()\r\n    conexiones_copy=conexiones.copy()\r\n    conexiones_copy.remove(conex)\r\n    for k in range (m-1): ## se busca la constelación a la que pertenece conex\r\n        for j in range(m-1):\r\n            X=conexiones_copy[j]\r\n            A=X[0]\r\n            B=X[1]\r\n            if A in conex and B not in conex:\r\n                conex.append(B)\r\n            if B in conex and A not in conex:\r\n                conex.append(A)\r\n    ## ahora que tengo la conexión, quiero conocer la cantidad de brillo de la constelación \"conex\"\r\n    for i in range(len(conex)):\r\n        conex.insert(i,brillos[conex[i]-1])\r\n        x=conex.pop(i+1)\r\n    BRILLO=sum(conex)\r\n    if BRILLO>=MaximoBrillo:\r\n        MaximoBrillo=BRILLO\r\nprint(MaximoBrillo)',278),
(279,'for i in range (int(input())):\r\n    a,b=input().split()\r\n    a=int(a)\r\n    b=int(b)\r\n    print(a+b)',279),
(281,'andrea = 0\r\nbruno = 0\r\ncamila = 0\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    if entrada == \"Tiempo\":\r\n        break\r\n    elif entrada == \"A\":\r\n        andrea += 1\r\n    elif entrada == \"B\":\r\n        bruno += 1\r\n    elif entrada == \"C\":\r\n        camila += 1\r\n\r\n# Imprimir resultados en el orden solicitado\r\nprint(\"Andrea\", andrea)\r\nprint(\"Bruno\", bruno)\r\nprint(\"Camila\", camila)',281),
(282,'# Variable contador: lleva la cuenta del número de pareja evaluada\r\nnumero_pareja = 0  \r\n\r\n# Variable máximo: guarda el puntaje más alto encontrado hasta ahora\r\nmejor_puntaje = -1  \r\n\r\n# Variable acumuladora: en cada iteración guarda la suma de las notas de una pareja\r\ntotal = 0  \r\n\r\n# Variable para guardar el número de la pareja ganadora\r\npareja_ganadora = -1  \r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    a, b, c = map(int, entrada.split())\r\n\r\n    # Condición de fin: si las tres notas son 0\r\n    if a == 0 and b == 0 and c == 0:\r\n        break\r\n\r\n    # Incrementamos el contador porque llegó una nueva pareja\r\n    numero_pareja += 1\r\n\r\n    # Calculamos el acumulador: suma de las tres notas\r\n    total = a + b + c\r\n\r\n    # Verificamos si este total supera el máximo guardado\r\n    if total > mejor_puntaje:\r\n        mejor_puntaje = total       # actualizamos el máximo\r\n        pareja_ganadora = numero_pareja  # guardamos el número de la pareja ganadora\r\n\r\n# Al final, mostramos el número de la pareja ganadora y su puntaje máximo\r\nprint(pareja_ganadora, mejor_puntaje)',282),
(283,'# Variable contador: lleva la cuenta del número de pareja evaluada\r\nnumero_pareja = 0  \r\n\r\n# Variable máximo: guarda el puntaje más alto encontrado hasta ahora\r\nmejor_puntaje = -1  \r\n\r\n# Variable acumuladora: en cada iteración guarda la suma de las notas de una pareja\r\ntotal = 0  \r\n\r\n# Variable para guardar el número de la pareja ganadora\r\npareja_ganadora = -1  \r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    a, b, c = map(int, entrada.split())\r\n\r\n    # Condición de fin: si las tres notas son 0\r\n    if a == 0 and b == 0 and c == 0:\r\n        break\r\n\r\n    # Incrementamos el contador porque llegó una nueva pareja\r\n    numero_pareja += 1\r\n\r\n    # Calculamos el acumulador: suma de las tres notas\r\n    total = a + b + c\r\n\r\n    # Verificamos si este total supera el máximo guardado\r\n    if total > mejor_puntaje:\r\n        mejor_puntaje = total       # actualizamos el máximo\r\n        pareja_ganadora = numero_pareja  # guardamos el número de la pareja ganadora\r\n\r\n# Al final, mostramos el número de la pareja ganadora y su puntaje máximo\r\nprint(pareja_ganadora, mejor_puntaje)',283),
(284,'import sys\r\n\r\n# Variable contador: lleva la cuenta del número de pareja evaluada\r\nnumero_pareja = 0  \r\n\r\n# Variable máximo: guarda el puntaje más alto encontrado hasta ahora\r\nmejor_puntaje = -1  \r\n\r\n# Variable para guardar el número de la pareja ganadora\r\npareja_ganadora = -1  \r\n\r\n# Leemos toda la entrada y la separamos por líneas\r\nfor linea in sys.stdin:\r\n    linea = linea.strip()\r\n    if not linea:  # saltar líneas vacías si las hubiera\r\n        continue\r\n\r\n    a, b, c = map(int, linea.split())\r\n\r\n    # Condición de fin: si las tres notas son 0\r\n    if a == 0 and b == 0 and c == 0:\r\n        break\r\n\r\n    # Incrementamos el contador porque llegó una nueva pareja\r\n    numero_pareja += 1\r\n\r\n    # Calculamos el acumulador: suma de las tres notas\r\n    total = a + b + c\r\n\r\n    # Verificamos si este total supera el máximo guardado\r\n    if total > mejor_puntaje:\r\n        mejor_puntaje = total       # actualizamos el máximo\r\n        pareja_ganadora = numero_pareja  # guardamos el número de la pareja ganadora\r\n\r\n# Al final, mostramos el número de la pareja ganadora y su puntaje máximo\r\nprint(pareja_ganadora, mejor_puntaje)',284),
(285,'persona=\"e\"\r\nA=0\r\nB=0\r\nC=0\r\nwhile persona!=\"Tiempo\":\r\n	persona=input()\r\n	if persona==\"A\":\r\n		A+=1\r\n	elif persona==\"B\":\r\n		B+=1\r\n	elif persona==\"C\":\r\n		C+=1\r\nprint(\"Andrea\",A)\r\nprint(\"Bruno\",B)\r\nprint(\"Camila\",C)',285),
(286,'parejas=[]\r\na,b,c=map(int,input().split())\r\npuntaje=a+b+c\r\nparejas.append(puntaje)\r\nposicion=1\r\npareja_max=posicion\r\nwhile puntaje!=0:\r\n	posicion+=1\r\n	a,b,c=map(int,input().split())\r\n	puntaje=a+b+c\r\n	puntaje_max=max(parejas)\r\n	if puntaje!=0:\r\n		parejas.append(puntaje)\r\n		if puntaje>puntaje_max:\r\n			pareja_max=posicion\r\nprint(pareja_max,max(parejas))',286),
