(291,'for i in range(1,3):\r\n    entrada=input()\r\n    a,b,c=entrada.split(\" \")\r\n    a=int(a)\r\n    b=int(b)\r\n    c=int(c)\r\n    discriminante= b**2 + (-4*a*c)\r\n    discriminanteraiz=discriminante**(1/2)\r\n    print(discriminanteraiz)\r\n\r\n    if discriminante>=0:\r\n        raiz1=(-b + discriminanteraiz)/(2*a)\r\n        raiz2=(-b - discriminanteraiz)/(2*a)\r\n        print(raiz2,raiz1)\r\n    elif discriminante<0:\r\n        print(\"No tiene raices reales\")',291),
(292,'for i in range(1,3):\r\n    entrada=input()\r\n    a,b,c=entrada.split(\" \")\r\n    a=int(a)\r\n    b=int(b)\r\n    c=int(c)\r\n    discriminante= b**2 + (-4*a*c)\r\n    discriminanteraiz=discriminante**(1/2)\r\n    print(discriminanteraiz)\r\n\r\n    if discriminante>=0:\r\n        raiz1=(-b + discriminanteraiz)/(2*a)\r\n        raiz2=(-b - discriminanteraiz)/(2*a)\r\n    elif discriminante<0:\r\n        print(\"No tiene raices reales\")',292),
(293,'for i in range(1,3):\r\n    entrada=input()\r\n    a,b,c=entrada.split(\" \")\r\n    a=int(a)\r\n    b=int(b)\r\n    c=int(c)\r\n    discriminante= b**2 + (-4*a*c)\r\n    discriminanteraiz=discriminante**(1/2)\r\n\r\n\r\n    if discriminante>=0:\r\n        raiz1=(-b + discriminanteraiz)/(2*a)\r\n        raiz2=(-b - discriminanteraiz)/(2*a)\r\n        print(raiz2,raiz1)\r\n    elif discriminante<0:\r\n        print(\"No tiene raices reales\")',293),
(294,'for i in range(1,3):\r\n    entrada=input()\r\n    a,b,c=entrada.split(\" \")\r\n    a=int(a)\r\n    b=int(b)\r\n    c=int(c)\r\n    discriminante= b**2 + (-4*a*c)\r\n    discriminanteraiz=discriminante**(1/2)\r\n\r\n\r\n    if discriminante>=0:\r\n        raiz1=(-b + discriminanteraiz)/(2*a)\r\n        raiz2=(-b - discriminanteraiz)/(2*a)\r\n        print(\"%.6f\"%raiz2,\"%.6f\"%raiz1)\r\n    elif discriminante<0:\r\n        print(\"No tiene raices reales\")',294),
