(364,'cantidad=-1\r\nwhile True:\r\n    i=1\r\n    cantidad=int(input())\r\n    if cantidad==0:\r\n        break\r\n    while cantidad%2!=1:\r\n        cantidad=cantidad/2\r\n        cantidad=int(cantidad)\r\n        i+=1\r\n    print(f\"{cantidad} {i}\")\r\n    i=1',364),
(365,'# Variables para acumular la recaudación\r\ntotal_horizonte = 0\r\ntotal_misterio = 0\r\ntotal_suenos = 0\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    if entrada == \"FIN\":\r\n        break\r\n\r\n    pelicula, edad = entrada.split()\r\n    edad = int(edad)\r\n\r\n    # Horizonte Rojo (18+)\r\n    if pelicula == \"HorizonteRojo\":\r\n        if edad >= 18:\r\n            if edad < 12:\r\n                total_horizonte += 3000\r\n            else:\r\n                total_horizonte += 5000\r\n\r\n    # El Misterio del Lago (13+)\r\n    elif pelicula == \"ElMisterioDelLago\":\r\n        if edad >= 13:\r\n            if edad < 12:\r\n                total_misterio += 3000\r\n            else:\r\n                total_misterio += 5000\r\n\r\n    # Sueños de Papel (Todo espectador)\r\n    elif pelicula == \"SueñosDePapel\":\r\n        if edad < 12:\r\n            total_suenos += 3000\r\n        else:\r\n            total_suenos += 5000\r\n\r\n# Imprimir los resultados en el orden requerido\r\nprint(f\"HorizonteRojo: {total_horizonte}\")\r\nprint(f\"ElMisterioDelLago: {total_misterio}\")\r\nprint(f\"SueñosDePapel: {total_suenos}\")',365),
(366,'HorizonteRojo=0\r\nElMisterioDelLago=0\r\nSueñosDePapel=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\" and edad>=18:\r\n        HorizonteRojo+=5000\r\n    elif pelicula==\"ElMisterioDelLago\" and edad>=13:\r\n        ElMisterioDelLago+=5000\r\n    elif pelicula==\"SueñosDePapel\":\r\n        if edad<12:\r\n            SueñosDePapel+=3000\r\n        else:\r\n            SueñosDePapel+=5000\r\nprint(f\"Horizonterojo: {HorizonteRojo}\")\r\nprint(f\"ElMisterioDelLago: {ElMisterioDelLago}\")\r\nprint(f\"SueñosDePapel: {SueñosDePapel}\")',366),
(367,'HorizonteRojo=0\r\nElMisterioDelLago=0\r\nSueñosDePapel=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\" and edad>=18:\r\n        HorizonteRojo+=5000\r\n    elif pelicula==\"ElMisterioDelLago\" and edad>=13:\r\n        ElMisterioDelLago+=5000\r\n    elif pelicula==\"SueñosDePapel\":\r\n        if edad<12:\r\n            SueñosDePapel+=3000\r\n        else:\r\n            SueñosDePapel+=5000\r\nprint(f\"HorizonteRojo: {HorizonteRojo}\")\r\nprint(f\"ElMisterioDelLago: {ElMisterioDelLago}\")\r\nprint(f\"SueñosDePapel: {SueñosDePapel}\")',367),
(368,'x=0\r\ny=0\r\nz=0\r\nedad=\"a\"\r\nwhile True:\r\n    try:\r\n        pelicula ,edad=input().split()\r\n        edad=int(edad)\r\n        if pelicula==\"HorizonteRojo\" and edad>=18:\r\n            x+=5000\r\n        if pelicula==\"ElMisterioDelLago\" and edad>=13:\r\n            y+=5000\r\n        if pelicula==\"SueñosDePapel\":\r\n            if edad>=12:\r\n                z+=5000\r\n            else:\r\n                z+=3000\r\n    except ValueError:\r\n        break\r\nprint(\"HorizonteRojo:\",x)\r\nprint(\"ElMisterioDelLago:\",y)\r\nprint(\"SueñosDePapel:\",z)',368),
(369,'x=0\r\ny=0\r\nz=0\r\nedad=\"a\"\r\nwhile True:\r\n    try:\r\n        pelicula ,edad=input().split()\r\n        edad=int(edad)\r\n        if pelicula==\"HorizonteRojo\" and edad>=18:\r\n            x+=5000\r\n        if pelicula==\"ElMisterioDelLago\" and edad>=13:\r\n            y+=5000\r\n        if pelicula==\"SueñosDePapel\":\r\n            if edad>=12:\r\n                z+=5000\r\n            else:\r\n                z+=3000\r\n    except ValueError:\r\n        break\r\nprint(\"HorizonteRojo:\",x)\r\nprint(\"ElMisterioDelLago:\",y)\r\nprint(\"SueñosDePapel:\",z)',369),
(370,'n=1\r\np_new=1\r\nwhile n!=0:\r\n    n=int(input())\r\n    p=1\r\n    g=1\r\n    p_new=p\r\n    if n==0:\r\n        break\r\n    while p<=n:\r\n        p_new=p_new*2\r\n        g+=1\r\n        if p_new==n:\r\n            print(f\"{p} {g}\")\r\n            break\r\n        if p_new>n:\r\n            p+=2\r\n            p_new=p\r\n            g=1',370),
(371,'n=1\r\nwhile n!=0:\r\n    n=int(input())\r\n    for p in range (1,n+1,2):\r\n        poblacion=p\r\n        g=1\r\n        while poblacion<n:\r\n            poblacion=poblacion*2\r\n            g+=1\r\n            if poblacion==n:\r\n                print(f\"{p} {g}\")\r\n                break',371),
(372,'Poblacion_Final = -1\r\ncontador = 1\r\nresto = -1\r\nPoblacion_inicial = 0\r\nwhile Poblacion_Final != 0:\r\n    Poblacion_Final = int(input())\r\n    if Poblacion_Final != 0:\r\n        while True:\r\n            if Poblacion_Final != 1:\r\n                Poblacion_Final = Poblacion_Final // 2\r\n                contador = contador + 1\r\n                resto = Poblacion_Final % 2\r\n                if resto > 0:\r\n                    break\r\n            else:\r\n                break\r\n        print(int(Poblacion_Final), contador)\r\n        contador = 1',372),
(373,'x=0\r\ny=0\r\nz=0\r\nwhile True:\r\n    k = input()\r\n    if k == \"FIN\":\r\n        break\r\n    else:\r\n        a, b = k.split()\r\n        b = int(b)\r\n        if a == \"HorizonteRojo\":\r\n            if b>=18:\r\n                x += 5000\r\n        if a == \"SueñosDePapel\":\r\n            if b>=12:\r\n                z += 5000\r\n            if b<12:\r\n                z += 3000\r\n        if a == \"ElMisterioDelLago\":\r\n            if b>=13:\r\n                y += 5000\r\nprint(\"HorizonteRojo: \", x)\r\nprint(\"ElMisterioDelLago: \", y)\r\nprint(\"SueñoDePapel: \", z)',373),
(374,'x=0\r\ny=0\r\nz=0\r\nwhile True:\r\n    k = input()\r\n    if k == \"FIN\":\r\n        break\r\n    else:\r\n        a, b = k.split()\r\n        b = int(b)\r\n        if a == \"HorizonteRojo\":\r\n            if b>=18:\r\n                x += 5000\r\n        if a == \"SueñosDePapel\":\r\n            if b>=12:\r\n                z += 5000\r\n            if b<12:\r\n                z += 3000\r\n        if a == \"ElMisterioDelLago\":\r\n            if b>=13:\r\n                y += 5000\r\nprint(\"HorizonteRojo:\", x)\r\nprint(\"ElMisterioDelLago:\", y)\r\nprint(\"SueñoDePapel:\", z)',374),
(375,'Poblacion_Final = -1\r\ncontador = 1\r\nresto = -1\r\nPoblacion_inicial = 0\r\nwhile Poblacion_Final != 0:\r\n        Poblacion_Final = int(input())\r\n        if Poblacion_Final != 0:\r\n            while True:\r\n                resto = Poblacion_Final % 2\r\n                if resto == 0:\r\n                    Poblacion_Final = Poblacion_Final / 2\r\n                    contador = contador + 1\r\n                else:\r\n                    break\r\n\r\n            print(int(Poblacion_Final), contador)\r\n            contador = 1',375),
(376,'x=0\r\ny=0\r\nz=0\r\nwhile True:\r\n    k = input()\r\n    if k == \"FIN\":\r\n        break\r\n    else:\r\n        a, b = k.split()\r\n        b = int(b)\r\n        if a == \"HorizonteRojo\":\r\n            if b>=18:\r\n                x += 5000\r\n        if a == \"SueñosDePapel\":\r\n            if b>=12:\r\n                z += 5000\r\n            if b<12:\r\n                z += 3000\r\n        if a == \"ElMisterioDelLago\":\r\n            if b>=13:\r\n                y += 5000\r\nprint(\"HorizonteRojo:\", x)\r\nprint(\"ElMisterioDelLago:\", y)\r\nprint(\"SueñosDePapel:\", z)',376),
(377,'n=1\r\nwhile n!=0:\r\n    n=int(input())\r\n    g=1\r\n    if n==0:\r\n        break\r\n    while True:\r\n        n_old=n #Valor anterior de n\r\n        n=n/2\r\n        g+=1\r\n        if n%2!=0:\r\n            n_old=n_old/2\r\n            n_old=int(n_old)\r\n            print(f\"{n_old} {g}\")\r\n            break',377),
(378,'n=1\r\nwhile n!=0:\r\n    n=int(input())\r\n    g=1\r\n    if n==0:\r\n        break\r\n    while True:\r\n        n_old=n #Valor anterior de n\r\n        if n%2!=0:\r\n            n_old=int(n_old)\r\n            print(f\"{n_old} {g}\")\r\n            break\r\n        n=n/2\r\n        g+=1',378),
(379,'Peliculas=[]\r\nwhile True:\r\n    pelicula, edades =input().split()\r\n    if pelicula==\"FIN\" and edades:\r\n       break\r\n    \r\n\r\n    suma=0\r\n\r\n    if pelicula==\"ElMisterioDelLago\" and edades>=13:\r\n       suma+=1\r\n       total=500*suma\r\n       Peliculas.append(f\"ElMisterioDelLago: {total}\")\r\n    elif pelicula==\"ElMisterioDelLago\" and edades>=13:\r\n     print(\"echazado (12 < 13), no paga.\")\r\n    \r\n    elif pelicula==\"HorizonteRojo\" and edades>=18 :\r\n      suma +=1\r\n      total=5000*suma\r\n      Peliculas.append(f\"HorizonteRojo: {total}\")\r\n\r\n    elif pelicula==\"HorizonteRojo\" and 12<edades<18:\r\n       print(\" rechazado, no paga.\")\r\n\r\n    else:\r\n       sum+=1\r\n       total=2000*suma\r\n       Peliculas.append(f\"SueñosDePapel: {total} \")\r\n       \r\nfor Peliculas in Peliculas:\r\n   print(Peliculas)',379),
(380,'m = input(\"\")\r\nwhile True:\r\n    if m==0:\r\n        break\r\n    m=int(m)\r\n    if m>0:\r\n        P = m%2\r\n        for i in range (P-1,m,2*P):\r\n            G = print(i)\r\n            G = int(G)\r\n            (P,G) = int(input().split())\r\n            print(P,G)',380),
(381,'Peliculas=[]\r\nwhile True:\r\n    pelicula, edades =input().split()\r\n    if pelicula==\"FIN\" and edades:\r\n       break\r\n    \r\n\r\n    suma=0\r\n\r\n    if pelicula==\"ElMisterioDelLago\" and edades>=13:\r\n       suma+=1\r\n       total=500*suma\r\n       Peliculas.append(f\"ElMisterioDelLago: {total}\")\r\n    elif pelicula==\"ElMisterioDelLago\" and edades>=13:\r\n     print(\"echazado (12 < 13), no paga.\")\r\n    \r\n    elif pelicula==\"HorizonteRojo\" and edades>=18 :\r\n      suma +=1\r\n      total=5000*suma\r\n      Peliculas.append(f\"HorizonteRojo: {total}\")\r\n\r\n    elif pelicula==\"HorizonteRojo\" and 12<edades<18:\r\n       print(\" rechazado, no paga.\")\r\n\r\n    else:\r\n       sum+=1\r\n       total=2000*suma\r\n       Peliculas.append(f\"SueñosDePapel: {total} \")\r\n       \r\nfor Peliculas in Peliculas:\r\n   print(Peliculas)',381),
(382,'def main():\r\n    n = int(input())\r\n    for _ in range(n):\r\n        a, b = map(int, input().split())\r\n        print(a + b)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',382),
(383,'def claves_de_la_suerte(casos):\r\n    for x in casos:\r\n        for a in range(10):\r\n            for b in range(10):\r\n                for c in range(10):\r\n                    for d in range(10):\r\n                        if a + b + c + d == x:\r\n                            clave = f\"{a}{b}{c}{d}\"\r\n                            print(f\"{clave} es una clave da suerte que suma {x}\")\r\n\r\n# Ejemplo de uso:\r\nentrada = [0, 1, 36]\r\nclaves_de_la_suerte(entrada)',383),
(384,'def claves_de_la_suerte():\r\n    N = int(input(\"¿Cuántos números de la suerte quieres ingresar? \"))\r\n    casos = []\r\n    for _ in range(N):\r\n        x = int(input(\"Ingresa un número de la suerte (menor que 37): \"))\r\n        casos.append(x)\r\n\r\n    for x in casos:\r\n        for a in range(10):\r\n            for b in range(10):\r\n                for c in range(10):\r\n                    for d in range(10):\r\n                        if a + b + c + d == x:\r\n                            clave = f\"{a}{b}{c}{d}\"\r\n                            print(f\"{clave} es una clave da suerte que suma {x}\")\r\n\r\n# Ejecutar la función\r\nclaves_de_la_suerte()',384),
(385,'t = int(input().strip())\r\nfor _ in range(t):\r\n    X = int(input().strip())\r\n    w1, w2, w3, w4 = map(int, input().split())\r\n\r\n    best = 0\r\n\r\n    if w1 <= X and w1 > best:\r\n        best = w1\r\n    if w2 <= X and w2 > best:\r\n        best = w2\r\n    if w3 <= X and w3 > best:\r\n        best = w3\r\n    if w4 <= X and w4 > best:\r\n        best = w4\r\n\r\n    print(best)',385),
