(396,'def numroperfecto(n):\r\n    suma=0\r\n    for i in range(1,n):\r\n        if n%i==0:\r\n            suma +=i\r\n    return suma==n\r\n            \r\nn =int(input())\r\nfor elementos in range(1,n+1):\r\n    if numroperfecto(elementos):\r\n        print(elementos)',396),
(397,'def numroperfecto(n):\r\n    suma=0\r\n    for i in range(1,n):\r\n        if n%i==0:\r\n            suma +=i\r\n    return suma==n\r\n            \r\nn =int(input())\r\nfor elementos in range(1,n+1):\r\n    if numroperfecto(elementos):\r\n        print(elementos)\r\nelse:\r\n    print(\"Sin numeros perfectos\")',397),
(398,'def numroperfecto(n):\r\n    suma=0\r\n    for i in range(1,n):\r\n        if n%i==0:\r\n            suma +=i\r\n    return suma==n\r\n            \r\nn =int(input())\r\nfor elementos in range(1,n+1):\r\n    if numroperfecto(elementos):\r\n        print(elementos)\r\nif not numroperfecto(elementos):\r\n    print(\"Sin numeros perfectos\")',398),
(399,'casos=int(input())\r\nfor _ in range(1,casos+1):\r\n    peso_maximo=int(input())\r\n    numeros=list(map(int, input().split()))\r\n    pesos_filtro=[p for p in numeros if p<=peso_maximo]\r\n    print(max(pesos_filtro))',399),
(400,'for i in range(1,3):\r\n    entrada=input()\r\n    a,b,c=entrada.split(\" \")\r\n    a=int(a)\r\n    b=int(b)\r\n    c=int(c)\r\n    discriminante= b**2 + (-4*a*c)\r\n\r\n    if discriminante>=0 and not a==0:\r\n        discriminanteraiz=discriminante**(1/2)\r\n        raiz1=(-b + discriminanteraiz)/(2*a)\r\n        raiz2=(-b - discriminanteraiz)/(2*a)\r\n        print(\"%.6f\"%raiz2,\"%.6f\"%raiz1)\r\n    else:\r\n        print(\"No tiene raices reales\")',400),
(401,'entrada=input()\r\na,b,c=entrada.split(\" \")\r\na=int(a)\r\nb=int(b)\r\nc=int(c)\r\ndiscriminante= b**2 + (-4*a*c)\r\n\r\nif discriminante>=0 and not a==0:\r\n    discriminanteraiz=discriminante**(1/2)\r\n    raiz1=(-b + discriminanteraiz)/(2*a)\r\n    raiz2=(-b - discriminanteraiz)/(2*a)\r\n    print(\"%.6f\"%raiz2,\"%.6f\"%raiz1)\r\nelse:\r\n    print(\"No tiene raices reales\")',401),
