(403,'while True:\r\n    x=input().split()\r\n    a=float(x[0])\r\n    b=float(x[1])\r\n    c=float(x[2])\r\n    d=float(x[3])\r\n    e=float(x[4])\r\n    if a<=b<=c<=d<=e:\r\n        print(\'Creciente\')\r\n    elif a>=b>=c>=d>=e:\r\n        print(\'Decreciente\')\r\n    else:\r\n        print(\'Ninguno\')',403),
(404,'while True:\r\n    try:\r\n        x=input().split()\r\n        a=float(x[0])\r\n        b=float(x[1])\r\n        c=float(x[2])\r\n        d=float(x[3])\r\n        e=float(x[4])\r\n        if a<=b<=c<=d<=e:\r\n            print(\'Creciente\')\r\n        elif a>=b>=c>=d>=e:\r\n            print(\'Decreciente\')\r\n        else:\r\n            print(\'Ninguno\')\r\n    except EOFError:\r\n        break',404),
(405,'while True:\r\n    try:\r\n        alturas= input(\"\")\r\n        altura1, altura2, altura3, altura4, altura5 = alturas.split()\r\n        altura1= float(altura1)\r\n        altura2= float(altura2)\r\n        altura3= float(altura3)\r\n        altura4= float(altura4)\r\n        altura5= float(altura5)\r\n        if altura1>=altura2>=altura3>=altura4>=altura5:\r\n            print(\"Creciente\")\r\n        elif altura1<=altura2<=altura3<=altura4<=altura5:\r\n            print(\"Decreciente\")\r\n        else:\r\n            print(\"Ninguno\")\r\n    except EOFError:\r\n        break',405),
