(433,'Precio_niños = 3000\r\nPrecio_adulto = 5000\r\nPrecio_H = 0\r\nPrecio_S = 0\r\nPrecio_E = 0\r\nPrecio_H_Total = 0\r\nPrecio_S_Total = 0\r\nPrecio_E_Total = 0\r\na = \"\"\r\n\r\nwhile a != \"FIN\":\r\n    try:\r\n        a,b = map(str, input().split())\r\n        b = int(b)\r\n        if a == \"HorizonteRojo\":\r\n            if b >= 18:\r\n                Precio_H_Total = Precio_H + Precio_adulto\r\n            else:\r\n                Precio_H_Total = Precio_H + 0\r\n        elif a == \"SueñosDePapel\":\r\n            if b >= 13:\r\n                Precio_E_Total = Precio_E + Precio_adulto\r\n            else:\r\n                Precio_E_Total = Precio_E + 0\r\n        elif a == \"ElMisterioDelLago\":\r\n            if b >= 12:\r\n                Precio_S_Total = Precio_S + Precio_adulto\r\n            else:\r\n                Precio_S_Total = Precio_S + Precio_niños\r\n    except:\r\n        break\r\nprint(\"HorizoteRojo:\", Precio_H_Total)\r\nprint(\"SueñosDePapel:\", Precio_S_Total)\r\nprint(\"ElMisterioDelLago:\", Precio_E_Total)',433),
(434,'TEXTO = input()\r\na=0\r\nb=0\r\nc=0\r\nwhile TEXTO!=\"FIN\":\r\n    x, y = TEXTO.split()\r\n    y = float(y)\r\n    if x == \"HorizonteRojo\" and y>=18:\r\n        a+=5000\r\n    elif x == \"ElMisterioDelLago\" and y>=13:\r\n        b+=5000\r\n    elif x==\"SueñosDePapel\":\r\n        if y>12:\r\n            c+=5000\r\n        else:\r\n            c+=3000\r\n    TEXTO = input()\r\nprint(\"HorizonteRojo:\",a)\r\nprint(\"ElMisterioDelLago:\",b)\r\nprint(\"SueñosDePapel:\",c)',434),
(435,'TEXTO = input()\r\na=0\r\nb=0\r\nc=0\r\nwhile TEXTO!=\"FIN\":\r\n    x, y = TEXTO.split()\r\n    y = int(y)\r\n    if x == \"HorizonteRojo\" and y>=18:\r\n        a+=5000\r\n    elif x == \"ElMisterioDelLago\" and y>=13:\r\n        b+=5000\r\n    elif x==\"SueñosDePapel\":\r\n        if y>12:\r\n            c+=5000\r\n        else:\r\n            c+=3000\r\n    TEXTO = input()\r\nprint(\"HorizonteRojo:\",a)\r\nprint(\"ElMisterioDelLago:\",b)\r\nprint(\"SueñosDePapel:\",c)',435),
(436,'TEXTO = input()\r\na=0\r\nb=0\r\nc=0\r\nwhile TEXTO!=\"FIN\":\r\n    x, y = TEXTO.split()\r\n    y = int(y)\r\n    if x == \"HorizonteRojo\" and 160>=y>=18:\r\n        a+=5000\r\n    elif x == \"ElMisterioDelLago\" and 160>=y>=13:\r\n        b+=5000\r\n    elif x==\"SueñosDePapel\":\r\n        if 160>=y>12:\r\n            c+=5000\r\n        elif 0<=y<=12:\r\n            c+=3000\r\n    TEXTO = input()\r\nprint(\"HorizonteRojo:\",a)\r\nprint(\"ElMisterioDelLago:\",b)\r\nprint(\"SueñosDePapel:\",c)',436),
(437,'TEXTO = input()\r\na=0\r\nb=0\r\nc=0\r\nwhile TEXTO!=\"FIN\":\r\n    x, y = TEXTO.split()\r\n    y = int(y)\r\n    if x == \"HorizonteRojo\" and 160>=y>=18:\r\n        a+=5000\r\n    elif x == \"ElMisterioDelLago\" and 160>=y>=13:\r\n        b+=5000\r\n    elif x==\"SueñosDePapel\":\r\n        if 160>=y>12:\r\n            c+=5000\r\n        elif 0<=y<=12:\r\n            c+=3000\r\n    TEXTO = input()\r\nprint(\"HorizonteRojo: \",a)\r\nprint(\"ElMisterioDelLago: \",b)\r\nprint(\"SueñosDePapel: \",c)',437),
(438,'HorizonteRojo= 0\r\nElMisterioDelLago= 0\r\nSueñosDePapel= 0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula,edad=entrada.split()\r\n    edad =int(edad)\r\n    print(\"la pelicula es:\", pelicula, \",la edad es:\", edad)\r\n    if pelicula==\"HorizonteRojo\":\r\n        if edad>=18:\r\n            HorizonteRojo= HorizonteRojo + 5000\r\n            #print(\"la pelicula es:\", pelicula, \", la edad es:\", edad)\r\n    if pelicula== \"ElMisterioDelLago\":\r\n        if edad>=18:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n        elif edad>= 13:\r\n            ElMisterioDelLago= ElMisterioDelLago+5000\r\n        else:\r\n            pass\r\n    if pelicula== \"SueñosDePapel\":\r\n        if edad>=12:\r\n            SueñosDePapel=SueñosDePapel+5000\r\n        elif edad<12:\r\n            SueñosDePapel= SueñosDePapel+3000\r\n        else:\r\n            pass\r\n\r\n\r\n\r\n\r\nprint(\"HorizonteRojo: \", HorizonteRojo)    \r\nprint(\"ElMisterioDelLago:\",ElMisterioDelLago)\r\nprint(\"SueñosDePapel:\",SueñosDePapel)',438),
(439,'HorizonteRojo     = 0\r\nElMisterioDelLago = 0\r\nSueñosDePapel     = 0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\":\r\n        if edad>=18:\r\n            HorizonteRojo=HorizonteRojo+5000\r\n            # print(\"la pelicula es:\",pelicula,\",la edad es:\",edad)\r\n    if pelicula==\"ElMisterioDelLago\":\r\n        if edad>=18:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n        elif edad>=13:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n        else:\r\n            pass\r\n    if pelicula==\"SueñosDePapel\":\r\n        if edad>=12:\r\n            SueñosDePapel=SueñosDePapel+5000\r\n        elif edad<12:\r\n            SueñosDePapel=SueñosDePapel+3000\r\n        else:\r\n            pass\r\n      \r\nprint(\"HorizonteRojo:\",HorizonteRojo)\r\nprint(\"ElMisterioDelLago:\",ElMisterioDelLago)\r\nprint(\"SueñosDePapel:\",SueñosDePapel)',439),
