(443,'HorizonteRojo     = 0\r\nElMisterioDelLago = 0\r\nSueñosDePapel     = 0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\":\r\n        if edad>=18:\r\n           HorizonteRojo=HorizonteRojo+5000\r\n           # print\"La pelicula es:\", pelicula, \"La edad es:\", edad\r\n    if pelicula==\"ElMisterioDelLago\":\r\n        if edad>=18:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n        elif edad>=13:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n        else:\r\n            pass\r\n    if pelicula==\"SueñosDePapel\":\r\n        if edad>=12:\r\n            SueñosDePapel=SueñosDePapel+5000\r\n        elif edad<12:\r\n            SueñosDePapel=SueñosDePapel+3000\r\n        else:\r\n            pass\r\nprint(\"HorizonteRojo:\", HorizonteRojo)\r\nprint(\"ElMisterioDelLago:\", ElMisterioDelLago)\r\nprint(\"SueñosDePapel:\", SueñosDePapel)',443),
(444,'t=int(input())\r\nfor i in range(t):\r\n    x=int(input())\r\n    calabazas=[]\r\n    candidatos=[]\r\n    calabazas=list(map(int,input().split()))\r\n    for item in calabazas:\r\n        if item<=x:\r\n            candidatos.append(item)\r\n    while True:\r\n        try:\r\n            print(max(candidatos))\r\n            break\r\n        except ValueError:\r\n            print(\"0\")\r\n            break',444),
(445,'HorizonteRojo = 0\r\nElMisterioDelLago = 0\r\nSueñosDePapel = 0\r\n\r\nwhile True:\r\n        entrada = input()\r\n        if entrada == \"FIN\":\r\n                        break\r\n        pelicula,edad = entrada.split()\r\n        edad = int(edad)\r\n        if pelicula == \"HorizonteRojo\":\r\n                if edad >= 18:\r\n                        HorizonteRojo = HorizonteRojo + 5000\r\n        if pelicula == \"ElMisterioDelLago\":\r\n                if edad >= 18:\r\n                        ElMisterioDelLago = ElMisterioDelLago + 5000\r\n                elif edad >= 13:\r\n                        ElMisterioDelLago = ElMisterioDelLago + 5000\r\n                else:\r\n                        pass\r\n        if pelicula == \"SueñosDePapel\":\r\n                if edad < 12:\r\n                        SueñosDePapel = SueñosDePapel + 3000\r\n                else:\r\n                        SueñosDePapel = SueñosDePapel + 5000\r\nprint(\"HorzonteRojo\")\r\nprint(\"ElMisterioDelLago\", ElMisterioDelLago)\r\nprint(\"SueñosDePapel\", SueñosDePapel)',445),
