(523,'# Monitoreo de Fallas por Turno\r\n# Lee eventos hasta encontrar \'R\'.\r\n# Eventos: S = sin falla, F = con falla, T = cambio de turno, R = fin de lectura.\r\n\r\n\r\n# Contadores de fallas\r\nf1 = f2 = f3 = 0\r\n\r\nturno = 1  # turno actual (1, 2, 3)\r\n\r\nfor linea in sys.stdin:\r\n    evento = input()\r\n\r\n    if evento == \"R\":\r\n        break  # fin de la revisión\r\n\r\n    if evento == \"S\":\r\n        continue  # sin falla, no cambia nada\r\n\r\n    if evento == \"F\":\r\n        if turno == 1:\r\n            f1 += 1\r\n        elif turno == 2:\r\n            f2 += 1\r\n        else:\r\n            f3 += 1\r\n\r\n    if evento == \"T\":\r\n        if turno == 1:\r\n            turno = 2\r\n        elif turno == 2:\r\n            turno = 3\r\n        else:\r\n            turno = 1\r\n\r\n# Imprimir resultado\r\nprint(f1, f2, f3)',523),
(524,'# Monitoreo de Fallas por Turno\r\n# Lee eventos hasta encontrar \'R\'.\r\n# Eventos: S = sin falla, F = con falla, T = cambio de turno, R = fin de lectura.\r\n\r\n\r\n# Contadores de fallas\r\nf1 = f2 = f3 = 0\r\n\r\nturno = 1  # turno actual (1, 2, 3)\r\n\r\nwhile True:\r\n    evento = input()\r\n\r\n    if evento == \"R\":\r\n        break  # fin de la revisión\r\n\r\n    if evento == \"S\":\r\n        continue  # sin falla, no cambia nada\r\n\r\n    if evento == \"F\":\r\n        if turno == 1:\r\n            f1 += 1\r\n        elif turno == 2:\r\n            f2 += 1\r\n        else:\r\n            f3 += 1\r\n\r\n    if evento == \"T\":\r\n        if turno == 1:\r\n            turno = 2\r\n        elif turno == 2:\r\n            turno = 3\r\n        else:\r\n            turno = 1\r\n\r\n# Imprimir resultado\r\nprint(f1, f2, f3)',524),
