(601,'def claves_de_la_suerte():\r\n    N = int(input(\"¿Cuántos números de la suerte quieres ingresar? \"))\r\n    casos = []\r\n    for _ in range(N):\r\n        x = int(input(\"Ingresa un número de la suerte (menor que 37): \"))\r\n        if x < 37:\r\n            casos.append(x)\r\n        else:\r\n            print(\"El número debe ser menor que 37.\")\r\n    \r\n    for x in casos:\r\n        for a in range(10):\r\n            for b in range(10):\r\n                for c in range(10):\r\n                    for d in range(10):\r\n                        if a + b + c + d == x:\r\n                            clave = f\"{a}{b}{c}{d}\"\r\n                            print(f\"{clave} es una clave de la suerte que suma {x}\")\r\n\r\nclaves_de_la_suerte()',601),
(602,'def claves_de_la_suerte():\r\n    N = int(input(\"¿Cuántos números de la suerte quieres ingresar? \"))\r\n    casos = []\r\n    for _ in range(N):\r\n        x = int(input(\"Ingresa un número de la suerte (menor que 37): \"))\r\n        if x < 37:\r\n            casos.append(x)\r\n        else:\r\n            print(\"El número debe ser menor que 37.\")\r\n    \r\n    for x in casos:\r\n        for a in range(10):\r\n            for b in range(10):\r\n                for c in range(10):\r\n                    for d in range(10):\r\n                        if a + b + c + d == x:\r\n                            clave = f\"{a}{b}{c}{d}\"\r\n                            print(f\"{clave} es una clave de la suerte que suma {x}\")\r\n\r\nclaves_de_la_suerte()',602),
(603,'def puede_escapar(laberinto, N, M):\r\n    from collections import deque\r\n    visitado = [[False]*M for _ in range(N)]\r\n    cola = deque()\r\n    cola.append((0, 0))\r\n    visitado[0][0] = True\r\n\r\n    while cola:\r\n        x, y = cola.popleft()\r\n        if laberinto[x][y] == 2:\r\n            return True\r\n        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:\r\n            nx, ny = x+dx, y+dy\r\n            if 0 <= nx < N and 0 <= ny < M and not visitado[nx][ny] and laberinto[nx][ny] != 0:\r\n                visitado[nx][ny] = True\r\n                cola.append((nx, ny))\r\n    return False\r\n\r\nT = int(input())\r\nfor _ in range(T):\r\n    N, M = map(int, input().split())\r\n    laberinto = []\r\n    for _ in range(N):\r\n        laberinto.append(list(map(int, input().split())))\r\n    if puede_escapar(laberinto, N, M):\r\n        print(\"Escape exitoso\")\r\n    else:\r\n        print(\"No hay escapatoria\")',603),
(604,'n = int(input())\r\nif n % 2 == 0:\r\n    print(\"PAR\")\r\nelse:\r\n    print(\"IMPAR\")',604),
(605,'def min_conexiones(n, m, conexiones):\r\n    # Algoritmo de componentes conexas usando Union-Find\r\n    parent = list(range(n))\r\n    def find(x):\r\n        while parent[x] != x:\r\n            parent[x] = parent[parent[x]]\r\n            x = parent[x]\r\n        return x\r\n    def union(x, y):\r\n        px, py = find(x), find(y)\r\n        if px != py:\r\n            parent[py] = px\r\n\r\n    for a, b in conexiones:\r\n        union(a, b)\r\n    # Contar componentes\r\n    componentes = set(find(i) for i in range(n))\r\n    # Mínimo de conexiones necesarias = componentes - 1\r\n    return len(componentes) - 1\r\n\r\n# Ejemplo de uso:\r\nn, m = map(int, input().split())\r\nconexiones = []\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    conexiones.append((a, b))\r\nprint(min_conexiones(n, m, conexiones))',605),
(606,'def es_ruta_valida(grafo, ruta):\r\n    for i in range(len(ruta)-1):\r\n        if ruta[i+1] not in grafo[ruta[i]]:\r\n            return False\r\n    return True\r\n\r\nn, m = map(int, input().split())\r\ngrafo = {i: set() for i in range(1, n+1)}\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    grafo[a].add(b)\r\n    grafo[b].add(a)\r\n\r\nT = int(input())\r\nfor _ in range(T):\r\n    l = int(input())\r\n    ruta = list(map(int, input().split()))\r\n    if es_ruta_valida(grafo, ruta):\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")',606),
