(671,'HorizonteRojo=0\r\nElMisterioDelLago=0\r\nSueñosDePapel=0\r\nwhile True:\r\n    entrada=input()\r\nif entrada==\"FIN\":\r\n    pelicula ,edad=entrada.split()\r\nedad=int(edad)\r\nif pelicula==\"HorizonteRojo\":\r\n    if edad>=18:\r\n        HorizonteRojo=HorizonteRojo+5000\r\nelif pelicula==\"ElMisterioDelLago\":\r\n    if edad>=13:\r\n        ElMisterioDelLago=ElMisterioDelLago+5000\r\nelif pelicula==\"SueñosDePapel\":\r\n    if edad>=12:\r\n        SueñosDePapel=SueñosDePapel+5000\r\n    else: \r\n        SueñosDePapel=SueñosDePapel+3000\r\n    pass\r\n\r\nprint(\"HorizonteRojo\",HorizonteRojo)\r\nprint(\"ElMisterioDelLago\",ElMisterioDelLago)\r\nprint(\"SueñosDePapel\",SueñosDePapel)',671),
(672,'HorizonteRojo=0\r\nElMisterioDelLago=0\r\nSueñosDePapel=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula ,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\":\r\n        if edad>=18:\r\n            HorizonteRojo=HorizonteRojo+5000\r\n    elif pelicula==\"ElMisterioDelLago\":\r\n        if edad>=13:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n    elif pelicula==\"SueñosDePapel\":\r\n        if edad>=12:\r\n            SueñosDePapel=SueñosDePapel+5000\r\n        elif edad<=12: \r\n            SueñosDePapel=SueñosDePapel+3000\r\n        else:\r\n            pass\r\n\r\nprint(\"HorizonteRojo\",HorizonteRojo)\r\nprint(\"ElMisterioDelLago\",ElMisterioDelLago)\r\nprint(\"SueñosDePapel\",SueñosDePapel)',672),
(673,'HorizonteRojo=0\r\nElMisterioDelLago=0\r\nSueñosDePapel=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula ,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\":\r\n        if edad>=18:\r\n            HorizonteRojo=HorizonteRojo+5000\r\n    if pelicula==\"ElMisterioDelLago\":\r\n        if edad>=13:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n    if pelicula==\"SueñosDePapel\":\r\n        if edad>=12:\r\n            SueñosDePapel=SueñosDePapel+5000\r\n        elif edad<=12: \r\n            SueñosDePapel=SueñosDePapel+3000\r\n        else:\r\n            pass\r\n\r\nprint(\"HorizonteRojo\",HorizonteRojo)\r\nprint(\"ElMisterioDelLago\",ElMisterioDelLago)\r\nprint(\"SueñosDePapel\",SueñosDePapel)',673),
