(682,'T=int(input())\r\nfor i in range (T):\r\n     n,m= map(int,input().split())\r\n     laberinto=[]\r\n     for k in range (n):\r\n          fila=list(map(int,input().split()))\r\n          laberinto.append(fila)\r\n     visitado=[[False]*m for s in range(n)]\r\n     def puede_escapar(x,y):\r\n         if x<0 or x>=n or y<0 or y>=m:\r\n             return False\r\n         if laberinto[x][y] == 0 or visitado[x][y]:\r\n             return False\r\n         if laberinto[x][y] == 2:\r\n             return True\r\n         visitado[x][y] = True\r\n         if puede_escapar(x-1, y):\r\n             return True\r\n         if puede_escapar(x+1, y):\r\n             return True\r\n         if puede_escapar(x, y+1):\r\n             return True\r\n         if puede_escapar(x, y-1):\r\n             return True\r\n         return False\r\n     if puede_escapar(0,0):\r\n         print(\"Escape exitoso\")\r\n     else:\r\n         print(\"No hay escapatoria\")',682),
(683,'pareja_ganadora = 0\r\npuntaje_ganador = 0\r\nindice = 1\r\nwhile True:\r\n    notas = input().split()\r\n    if notas == [\'0\', \'0\', \'0\']:\r\n        break\r\n    total = sum(map(int, notas))\r\n    if total > puntaje_ganador:\r\n        puntaje_ganador = total\r\n        pareja_ganadora = indice\r\n    indice += 1\r\nprint(pareja_ganadora, puntaje_ganador)',683),
(684,'bruno = 0\r\ncamila = 0\r\n\r\n\r\nwhile True:\r\n    letra = input().strip()  \r\n    if letra == \"Tiempo\":    \r\n        break\r\n    if letra == \"A\":\r\n        andrea += 1          \r\n    elif letra == \"B\":\r\n        bruno += 1           \r\n        camila += 1          \r\n\r\n\r\nprint(\"Andrea\", andrea)\r\nprint(\"Bruno\", bruno)\r\nprint(\"Camila\", camila)',684),
