(699,'n, m = map(int, input().split())\r\nconectadas = set()\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    conectadas.add(a)\r\n    conectadas.add(b)\r\naisladas = []\r\nvisitadas = set()\r\ndef dfs(ciudad):\r\n    visitadas.add(ciudad)\r\n    for vecino in grafo.get(ciudad, []):\r\n        if vecino not in visitadas:\r\n            dfs(vecino)\r\ngrafo = {}\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    grafo.setdefault(a, []).append(b)\r\n    grafo.setdefault(b, []).append(a)\r\ndfs(1)\r\nfor ciudad in range(2, n+1):\r\n    if ciudad not in visitadas:\r\n        aisladas.append(ciudad)\r\nprint(*sorted(aisladas))',699),
(700,'# Leer n (ciudades) y m (caminos)\r\nn, m = map(int, input().split())\r\n# Crear el grafo como lista de adyacencia\r\ngrafo = {i: [] for i in range(1, n+1)}\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    grafo[a].append(b)\r\n    grafo[b].append(a)\r\n\r\n# DFS para marcar las ciudades alcanzables desde la ciudad 1\r\nvisitado = set()\r\ndef dfs(ciudad):\r\n    visitado.add(ciudad)\r\n    for vecino in grafo[ciudad]:\r\n        if vecino not in visitado:\r\n            dfs(vecino)\r\n\r\ndfs(1)\r\n\r\n# Las ciudades aisladas son las que no fueron visitadas (excepto la ciudad 1)\r\naisladas = [i for i in range(2, n+1) if i not in visitado]\r\nprint(*sorted(aisladas))',700),
(701,'# Leer n (ciudades) y m (caminos)\r\nn, m = map(int, input().split())\r\n# Crear el grafo como lista de adyacencia\r\ngrafo = {i: [] for i in range(1, n+1)}\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    grafo[a].append(b)\r\n    grafo[b].append(a)\r\n\r\nT = int(input())\r\nfor _ in range(T):\r\n    l = int(input())\r\n    ruta = list(map(int, input().split()))\r\n    es_valida = True\r\n    for i in range(len(ruta)-1):\r\n        if ruta[i+1] not in grafo[ruta[i]]:\r\n            es_valida = False\r\n            break\r\n    print(\'SI\' if es_valida else \'NO\')',701),
(702,'from itertools import permutations\r\nn = int(input())\r\nedades = list(map(int, input().split()))\r\nres = []\r\nfor perm in permutations(edades):\r\n    valido = True\r\n    for i in range(n):\r\n        if perm[i] < 18:\r\n            if (i > 0 and perm[i-1] >= 18) or (i < n-1 and perm[i+1] >= 18):\r\n                continue\r\n            else:\r\n                valido = False\r\n                break\r\n    if valido:\r\n        res.append(perm)\r\nfor fila in res:\r\n    print(*fila)',702),
(703,'from itertools import permutations\r\nn = int(input())\r\nedades = list(map(int, input().split()))\r\nres = []\r\nfor perm in permutations(edades):\r\n    valido = True\r\n    for i in range(n):\r\n        if perm[i] < 18:\r\n            if (i > 0 and perm[i-1] >= 18) or (i < n-1 and perm[i+1] >= 18):\r\n                continue\r\n            else:\r\n                valido = False\r\n                break\r\n    if valido:\r\n        res.append(perm)\r\n# Ordenar las filas válidas como en la foto (lexicográficamente)\r\nres.sort()\r\nfor fila in res:\r\n    print(*fila)',703),
(704,'a, b = map(int, input().split())\r\nfor t in range(a, b+1):\r\n    found = False\r\n    for x in range(1, t+1):\r\n        for y in range(x, t+1):\r\n            for z in range(y, t+1):\r\n                if x*x + y*y + z*z == t*t:\r\n                    print(x, y, z, t)\r\n                    found = True\r\n                    break\r\n            if found:\r\n                break\r\n        if found:\r\n            break',704),
(705,'T = int(input())\r\nfor _ in range(T):\r\n    n = int(input())\r\n    a = list(map(int, input().split()))\r\n    b = list(map(int, input().split()))\r\n    pares = []\r\n    for i in range(n):\r\n        for j in range(i+1, n):\r\n            if a[i] - a[j] == b[i] + b[j]:\r\n                pares.append((i+1, j+1))\r\n    for par in pares:\r\n        print(par)\r\n    print(len(pares))',705),
