(745,'T=int(input())\r\nacumulador=0\r\nfor i in range (T):\r\n    a,b=input().split()\r\n    b=int(b)\r\n    atraso=500*b\r\n    if a==\"B\":\r\n        multa=atraso\r\n    elif a==\"D\":\r\n        multa=2000+atraso\r\n    elif a==\"P\":\r\n        multa=5000+atraso\r\n    acumulador+=multa\r\nprint(acumulador)',745),
