(747,'cantidad_de_libros = int(input())\r\nmulta = 0\r\nfor i in range(cantidad_de_libros):\r\n    texto = input()\r\n    estado_del_libro, dias_atrasados = texto.split()\r\n    dias_atrasados  = int(dias_atrasados)\r\n    if estado_del_libro == \"B\" and dias_atrasados != 0:\r\n        multa += dias_atrasados*500\r\n    elif estado_del_libro == \"B\" and dias_atrasados == 0:\r\n        multa += 0\r\n    elif estado_del_libro == \"D\" and dias_atrasados !=0:\r\n        multa += 2000+(dias_atrasados*500)\r\n    elif estado_del_libro ==\"D\" and dias_atrasados == 0:\r\n        multa += 2000\r\n    elif estado_del_libro == \"P\" and dias_atrasados !=0:\r\n        multa += 5000(dias_atrasados*500)\r\n    elif estado_del_libro == \"P\" and dias_atrasados == 0:\r\n        multa +=5000\r\n\r\nprint(multa)',747),
(748,'E1=0\r\nE2=0\r\nE3=0\r\nturno=1\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"R\":\r\n        break\r\n    if entrada==\"F\" and turno==1:\r\n        E1+=1\r\n    if entrada==\"F\" and turno==2:\r\n        E2+=1\r\n    if entrada==\"F\" and turno==0:\r\n        E3+=1\r\n    if entrada==\"T\":\r\n        turno+=1\r\n        turno=turno%3\r\nprint(f\"{E1} {E2} {E3}\")',748),
