(753,'t=int(input())\r\nsuma=0\r\nfor i in range (t):\r\n    libro= input()\r\n    condición, atraso= libro.split()\r\n    atraso=int(atraso)\r\n    if condición==\"B\":\r\n        if atraso==0:\r\n            multa= 0\r\n        elif atraso> 0: \r\n            multa= 0 + atraso*500\r\n    if condición== \"D\":\r\n        if atraso==0:\r\n            multa=2000\r\n        elif atraso>0:\r\n            multa= 2000+atraso*500\r\n    if condición==\"P\":\r\n        if atraso==0:\r\n            multa= 5000\r\n        elif atraso>0:\r\n            pago=5000\r\n            multa=pago+atraso*500\r\n    suma=suma+multa\r\nprint(suma)',753),
(754,'x= 0\r\ny=0\r\nz=0\r\nt=1\r\nwhile True:\r\n    a = input()\r\n    if a == \"R\":\r\n        break\r\n    if a == \"T\":\r\n        t = t+1\r\n        if t == 4:\r\n            t=t-3\r\n    if a == \"F\":\r\n        if t == 1:\r\n            x=x+1\r\n        elif t==2:\r\n            y=y+1\r\n        else: \r\n            z=z+1\r\nprint(x, y, z)',754),
(755,'atraso=500\r\ntotal=0\r\ncasos=int(input())\r\nfor _ in range(casos):\r\n    entrada=input()\r\n    a,b=entrada.split()\r\n    b=int(b)\r\n    if a==\"B\":\r\n        total+=b*atraso\r\n    elif a==\"D\":\r\n        total_atraso=b*atraso\r\n        total+= 2000 + total_atraso\r\n    elif a==\"P\":\r\n        atraso1=b*atraso\r\n        total+= 5000 +atraso1\r\nprint(total)',755),
(756,'turno=1\r\nfallas1=0\r\nfallas2=0\r\nfallas3=0 #contador de fallas para cada turno\r\nevento=\"a\"\r\nwhile evento!=\"R\":\r\n    evento=input() #¿Que evento esta succediendo en el turno?\r\n    if evento==\"T\": #Cambio de turno\r\n        turno+=1\r\n    if turno==4: #Volvemos al turno 1\r\n        turno=1\r\n    if evento==\"F\":\r\n        if turno==1:\r\n            fallas1+=1\r\n        if turno==2:\r\n            fallas2+=1\r\n        if turno==3:\r\n            fallas3+=1\r\nprint(f\"{fallas1} {fallas2} {fallas3}\")',756),
(757,'r1,r2,r3,r4=map(int,input().split())\r\np1,p2,p3,p4=map(int,input().split())\r\npi=3.141592\r\ni=0\r\nc1=(pi*r1**2)/p1\r\nc2=(pi*r2**2)/p2\r\nc3=(pi*r3**2)/p3\r\nc4=(pi*r4**2)/p4\r\nmax=c1\r\npizza=\"pequeña\"\r\nif c2>max:\r\n    max=c2\r\n    pizza=\"mediana\"\r\nif c3>max:\r\n    max=c3\r\n    pizza=\"grande\"\r\nif c4>max:\r\n    max=c4\r\n    pizza=\"familiar\"\r\nprint(pizza)',757),
(758,'c=[]\r\n\r\nr1, r2, r3, r4 = map(int, input().split())\r\np1, p2, p3, p4 = map(int, input().split())\r\n\r\npr1 = (3.141592*r1**2)/p1\r\npr2 = (3.141592*r2**2)/p2\r\npr3 = (3.141592*r3**2)/p3\r\npr4 = (3.141592*r4**2)/p4\r\n\r\nc.append(pr1)\r\nc.append(pr2)\r\nc.append(pr3)\r\nc.append(pr4)\r\nif max(c)==pr1:\r\n    print(\"pequeña\")\r\nif max(c)==pr2:\r\n    print(\"mediana\")\r\nif max(c)==pr3:\r\n    print(\"grande\")\r\nif max(c)==pr4:\r\n    print(\"familiar\")',758),
(759,'pi=3.141592 #Valor aproximado de pi\r\npizza=\"\" #Pizza que mas rinde\r\nrendimiento=0 #Cuanto Vale la pizza en base a su area por metro cuadrado\r\nr1,r2,r3,r4=list(map(int,input().split()))\r\np1,p2,p3,p4=list(map(int,input().split()))\r\n#¿Cuanto rinde cada pizza?\r\n#Precio dividido en el area de la pizza\r\nif p1/(pi*r1**2)>rendimiento:\r\n    pizza=\"pequeña\"\r\n    rendimiento=p1/(pi*r1**2)\r\nif p2/(pi*r2**2)<rendimiento:\r\n    pizza=\"mediana\"\r\n    rendimiento=p2/(pi*r2**2)\r\nif p3/(pi*r3**2)<rendimiento:\r\n    pizza=\"grande\"\r\n    rendimiento=p3/(pi*r3**2)\r\nif p4/(pi*r4**2)<rendimiento:\r\n    pizza=\"familiar\"\r\n    rendimiento=p4/(pi*r4**2)\r\nprint(pizza)',759),
