(763,'turno1=0\r\nturno2=0\r\nturno3=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"R\":\r\n        break\r\n    if entrada==\"S\":\r\n        turno1=turno1\r\n    elif entrada==\"F\":\r\n        turno1+=1\r\n    if entrada==\"T\":\r\n        turno2=turno1-turno1\r\n        turno3=turno2-turno2\r\n    elif entrada==\"S\":\r\n        turno2=turno2\r\n    elif entrada==\"F\":\r\n        turno2+=1\r\n    if entrada==\"S\":\r\n        turno3=turno3\r\n    elif entrada==\"F\":\r\n        turno3+=1\r\nprint(turno1-turno2-turno3,turno2,turno3)',763),
(764,'turno1=0\r\nturno2=0\r\nturno3=0\r\nlista= []\r\nwhile True:\r\n    entrada= input()\r\n    if entrada==\"R\":\r\n        break\r\n    if entrada==\"F\":\r\n        turno1=turno1+1\r\n    elif entrada==\"T\":\r\n        turno2=turno1-turno1\r\n    else:\r\n        pass\r\n    if entrada== \"F\":\r\n        turno2=turno2+1\r\n    elif entrada==\"T\":\r\n        turno3=turno2-turno2\r\n    else:\r\n        pass\r\n    if entrada==\"F\":\r\n        turno3=turno3+1\r\n    elif entrada==\"T\":\r\n        turno1=turno3-turno3\r\n    else:\r\n        pass\r\nlista.append(turno1)\r\nlista.append(turno2)\r\nlista.append(turno3)\r\nprint(turno1, turno2, turno3)',764),
