(766,'primer_turno = 0\r\nsegundo_turno = 0\r\ntercer_turno = 0\r\nvariable_contador = 0\r\nwhile True:\r\n    evento_registrado = input()\r\n    if evento_registrado == \"F\":\r\n        primer_turno +=1\r\n    elif evento_registrado == \"S\":\r\n        primer_turno +=0\r\n    elif evento_registrado == \"T\":\r\n        variable_contador +=1\r\n        valor_de_cambio_1 = primer_turno\r\n        valor_de_cambio_2 = segundo_turno\r\n        valor_de_cambio_3 = tercer_turno\r\n        primer_turno += (valor_de_cambio_2)-(valor_de_cambio_1)\r\n        segundo_turno += (valor_de_cambio_3)-(valor_de_cambio_2)\r\n        tercer_turno += (valor_de_cambio_1)-(valor_de_cambio_3)\r\n    elif evento_registrado == \"R\":\r\n        break\r\n\r\nif variable_contador % 3 == 0 or variable_contador == 0:\r\n    print(primer_turno, segundo_turno, tercer_turno)\r\nelif variable_contador % 2 == 0:\r\n    print(tercer_turno,primer_turno,segundo_turno)\r\nelse:\r\n    print(segundo_turno,tercer_turno,primer_turno)',766),
(767,'primer_turno = 0\r\nsegundo_turno = 0\r\ntercer_turno = 0\r\nvariable_contador = 0\r\nwhile True:\r\n    evento_registrado = input()\r\n    if evento_registrado == \"F\":\r\n        primer_turno +=1\r\n    elif evento_registrado == \"S\":\r\n        primer_turno +=0\r\n    elif evento_registrado == \"T\":\r\n        variable_contador +=1\r\n        valor_de_cambio_1 = primer_turno\r\n        valor_de_cambio_2 = segundo_turno\r\n        valor_de_cambio_3 = tercer_turno\r\n        primer_turno += (valor_de_cambio_2)-(valor_de_cambio_1)\r\n        segundo_turno += (valor_de_cambio_3)-(valor_de_cambio_2)\r\n        tercer_turno += (valor_de_cambio_1)-(valor_de_cambio_3)\r\n    elif evento_registrado == \"R\":\r\n        break\r\n\r\nif variable_contador % 3 == 0 or variable_contador == 0:\r\n    print(primer_turno, segundo_turno, tercer_turno)\r\nelif variable_contador % 2 == 0 and variable_contador !=1:\r\n    print(tercer_turno,primer_turno,segundo_turno)\r\nelse:\r\n    print(segundo_turno,tercer_turno,primer_turno)',767),
(768,'a,b,c,d=map(int,input().split())\r\ne,f,g,h=map(int,input().split())\r\npi=3.141592\r\nw=e/(a*a*pi)\r\nx=f/(b*b*pi)\r\ny=g/(c*c*pi)\r\nz=h/(d*d*pi)\r\nif w>x:\r\n    i=w\r\nelse:\r\n    i=x\r\nif y>i:\r\n    j=y\r\nelse:\r\n    j=i\r\nif z>j:\r\n    print(\'familiar\')\r\nelse:\r\n    if j==y:\r\n        print(\'grande\')\r\n    elif j==x:\r\n        print(\'mediana\')\r\n    else:\r\n        print(\'pequeña\')',768),
(769,'a,b,c,d=map(int,input().split())\r\ne,f,g,h=map(int,input().split())\r\npi=3.141592\r\nw=(a*a*pi)/e\r\nx=(b*b*pi)/f\r\ny=(c*c*pi)/g\r\nz=(d*d*pi)/h\r\nif w>x:\r\n    i=w\r\nelse:\r\n    i=x\r\nif y>i:\r\n    j=y\r\nelse:\r\n    j=i\r\nif z>j:\r\n    print(\'familiar\')\r\nelse:\r\n    if j==y:\r\n        print(\'grande\')\r\n    elif j==x:\r\n        print(\'mediana\')\r\n    else:\r\n        print(\'pequeña\')',769),
(770,'radio_pizza = input()\r\nr_p, r_m, r_g, r_f = radio_pizza.split()\r\nprecio_de_las_pizzas = input()\r\np_p, p_m, p_g, p_f = precio_de_las_pizzas.split()\r\nr_p = float(r_p)\r\nr_m = float(r_m)\r\nr_g = float(r_g)\r\nr_f = float(r_f)\r\np_p = float(p_p)\r\np_m = float(p_m)\r\np_g = float(p_g)\r\np_f = float(p_f)\r\np = (((r_p)**2)*8)/p_p\r\nm = (((r_m)**2)*8)/p_m\r\ng = (((r_g)**2)*8)/p_g\r\nf = (((r_f)**2)*8)/p_f\r\nif p > m > g > f:\r\n    print(\"pequeña\")\r\nelif m > p > g > f:\r\n    print(\"mediana\")\r\nelif g > m > p > f:\r\n    print(\"grande\")\r\nelif f > m > g > p:\r\n    print(\"familiar\")',770),
(771,'sumat=1\r\nturno1=0\r\nturno2=0\r\nturno3=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"R\":\r\n        break\r\n\r\n    if entrada==\"T\":\r\n        sumat+=1\r\n        if sumat>3:\r\n            sumat=1\r\n    if sumat==1:\r\n        if entrada==\"S\":\r\n            turno1+=0\r\n        elif entrada==\"F\":\r\n            turno1+=1\r\n    elif sumat==2:\r\n        if entrada==\"S\":\r\n            turno2+=0\r\n        elif entrada==\"F\":\r\n            turno2+=1\r\n    elif sumat==3:\r\n        if entrada==\"S\":\r\n            turno3+=0\r\n        elif entrada==\"F\":\r\n            turno3+=1\r\nprint(turno1,turno2,turno3)',771),
(772,'a = 0\r\nb = 0\r\nc = 0\r\nT = 0\r\nrevision = \"S\"\r\nwhile T == 0:\r\n    if revision == \"R\":\r\n        break\r\n    revision = input(\"\")\r\n    if revision == \"S\":\r\n        a += 0\r\n    elif revision == \"F\":\r\n        a+=1\r\n    elif revision == \"T\":\r\n        T += 1\r\n        \r\n    while T == 1:\r\n        if revision == \"R\":\r\n            break\r\n        revision = input(\"\")\r\n        if revision == \"S\":\r\n            b += 0\r\n        elif revision == \"F\":\r\n            b += 1\r\n        elif revision == \"T\":\r\n            T +=1    \r\n            while T == 2:\r\n                if revision == \"R\":\r\n                    break   \r\n                revision = input(\"\")\r\n                if revision == \"S\":\r\n                    c += 0\r\n                elif revision == \"F\":\r\n                    c+=1\r\n                elif revision == \"T\":\r\n                    T += -2       \r\nprint(a,b,c)',772),
(773,'x = int(input())\r\nTOTAL = 0\r\nfor i in range(0,x):\r\n    texto = input()\r\n    C, A = texto.split()\r\n    C = str(C)\r\n    A = int(A)\r\n\r\n    B = str(C)\r\n    D = str(C)\r\n    P = str(C)\r\n\r\n    ATRASO = (500*A)\r\n    if C == \"B\" and A >=0:\r\n     multa = (ATRASO+0)\r\n    elif C == \"D\" and A >=0:\r\n     multa = (ATRASO+2000)\r\n    elif C == \"P\" and A >=0:\r\n      multa = ATRASO+5000\r\n    TOTAL += multa\r\nprint(TOTAL)',773),
(774,'S = 0 #No altera \r\nF = 0 #Se suma 1\r\nT = 1\r\nR = 0 #Fin de lectura\r\nF1 = 0\r\nF2 = 0\r\nF3 = 0\r\nletra = 0\r\n\r\nwhile letra != \"R\":\r\n    letra = input().strip()\r\n    if letra == \"S\":\r\n        F1 = F1 + 0\r\n    elif letra == \"F\":\r\n        F1 = F1 + 1\r\n    elif letra == \"T\":\r\n        while letra != \"R\":\r\n            letra = input().strip()\r\n            if letra == \"S\":\r\n                F2 = F2 + 0\r\n            elif letra == \"F\":\r\n                F2 = F2 + 1\r\n            elif letra == \"T\":\r\n                while letra != \"R\":\r\n                    letra = input().strip()\r\n                    if letra == \"S\":\r\n                        F3 = F3 + 0\r\n                    elif letra == \"F\":\r\n                        F3 = F3 + 1  \r\n                    elif letra == \"T\":\r\n                                  \r\nprint(F1, F2, F3)',774),
