(779,'radio_de_pizza = input()\r\nr1,r2,r3,r4 = radio_de_pizza.split()\r\nr1 = float(r1)\r\nr2 = float(r2)\r\nr3 = float(r3)\r\nr4 = float(r4)\r\nprecio_de_las_pizzas = input()\r\np1,p2,p3,p4= precio_de_las_pizzas.split()\r\np1 = float(p1)\r\np2 = float(p2)\r\np3 = float(p3)\r\np4 = float(p4)\r\npizza_pequeña = (r1)*(r1)/p1\r\npizza_mediana = (r2)*(r2)/p2\r\npizza_grande = (r3)*(r3)/p3\r\npizza_familiar = (r4)*(r4)/p4\r\nif pizza_pequeña>pizza_pequeña>=pizza_grande>=pizza_familiar:\r\n    print(\"pequeña\")\r\nelif pizza_pequeña>pizza_pequeña>=pizza_grande>=pizza_familiar:\r\n    print(\"mediana\")\r\nelif pizza_pequeña>pizza_pequeña>=pizza_grande>=pizza_familiar:\r\n    print(\"grande\")\r\nelif pizza_pequeña>pizza_pequeña>=pizza_grande>=pizza_familiar:\r\n    print(\"familiar\")',779),
