(782,'B=0\r\nD=2000\r\nP=5000\r\nC=0\r\n\r\nT=int(input())\r\nfor i in range (T):\r\n    print(i)\r\nentrada=int(input())\r\nif entrada==B:\r\n     C = C + B\r\nif entrada==D:\r\n     C = C + D \r\nelif entrada==P:\r\n    C = C + P\r\nelse:\r\n    entrada<=0\r\n    C = C + entrada*500\r\nprint (C)',782),
(783,'x = 1\r\nfor i in range(0,x):\r\n    texto = input()\r\na, b, c, d = texto.split()\r\na =int(a)\r\nb =int(b)\r\nc =int(c)\r\nd =int(d)\r\n\r\nx = 1\r\nfor i in range(0,x):\r\n    texto = input()\r\ne, f, g, h = texto.split()\r\ne =int(e)\r\nf =int(f)\r\ng =int(g)\r\nh =int(h)\r\n\r\nareaa = (3.14*(a**2))\r\nareab = (3.14*(b**2))\r\nareac = (3.14*(c**2))\r\naread = (3.14*(d**2))\r\n\r\nrent =(areaa/e)\r\nrent2 =(areab/f)\r\nrent3 =(areac/g)\r\nrent4 =(aread/h)\r\n\r\nif rent>rent2>rent3>rent4:\r\n    print(\"pequeña\")',783),
(784,'n,m=map(int,input().split())\r\nprerrequisitos=[]\r\nfor i in range (m):\r\n    a,b=map(int,input().split())\r\n    x=(a-1,b-1)\r\n    prerrequisitos.append(x)\r\nvisitado=[False]*n\r\ndef explorar(u):\r\n    visitado[u]=True\r\n    for k in range (len(prerrequisitos)):\r\n        r=prerrequisitos[k]\r\n        r1=r[0]\r\n        r2=r[1]\r\n        if visitado[r1]==False and visitado[r2]==True:\r\n            visitado[r1]=True\r\n            explorar(r1)\r\nexplorar(n-1)\r\nvisitado.pop()\r\nlinea=[]\r\nfor i in range(len(visitado)):\r\n    if visitado[i]==True:\r\n        linea.append(i+1)\r\nfinal=f\"{linea[0]}\"\r\nfor i in range(1,(len(linea))):\r\n    final=final+\" \"+f\"{linea[i]}\"\r\nprint(final)',784),
(785,'sumat=1\r\nturno1=0\r\nturno2=0\r\nturno3=0\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"R\":\r\n        break\r\n\r\n    if entrada==\"T\":\r\n        sumat+=1\r\n        if sumat>3:\r\n            sumat=1\r\n    if sumat==1:\r\n        if entrada==\"F\":\r\n            turno1+=1\r\n    elif sumat==2:\r\n        if entrada==\"F\":\r\n            turno2+=1\r\n    elif sumat==3:\r\n        if entrada==\"F\":\r\n            turno3+=1\r\nprint(turno1,turno2,turno3)',785),
(786,'n,m=map(int,input().split())\r\nX,Y=map(int,input().split())\r\nmatriz=[]\r\nfor i in range(n):\r\n    x=input()\r\n    lista=list(x)\r\n    matriz.append(lista)\r\nvisitado=[[False]*m for s in range (n)]\r\nplata=0\r\ndef explorar(x,y):\r\n    if (x>=0 and x<n and y>=0 and y<m):\r\n        if not(matriz[x][y] == \"M\" or visitado[x][y]):\r\n             if not visitado[x][y]:\r\n                 visitado[x][y]=True\r\n                 explorar(x+1,y)\r\n                 explorar(x-1,y)\r\n                 explorar(x,y+1)\r\n                 explorar(x,y-1)\r\nif not (X<0 or X>=m or Y<0 or Y>=n):\r\n     visitado[X][Y]=True\r\n     explorar(X+1,Y)\r\n     explorar(X-1,Y)\r\n     explorar(X,Y+1)\r\n     explorar(X,Y-1)\r\nfor i in range (n):\r\n    for k in range (m):\r\n        if visitado[i][k]:\r\n            if matriz[i][k]==\"T\":\r\n                plata+=100\r\n            if matriz[i][k]==\"D\":\r\n                plata+=10\r\nprint(plata)',786),
(787,'t=int(input()) \r\nfor k in range(t):\r\n	contador=0\r\n	pares=[]\r\n	n=int(input()) \r\n	arreglo_a=list(map(int,input().split()))\r\n	arreglo_b=list(map(int,input().split()))\r\n	for i in range(n):\r\n		for j in range (i+1,n):\r\n			if i!=j:\r\n				if arreglo_a[i]*arreglo_a[j]==arreglo_b[i]+arreglo_b[j]:\r\n					pares.append(f\"({i+1},{j+1})\")\r\n					contador+=1\r\n	for item in pares:\r\n		print(item)\r\n	print(contador)',787),
