(794,'import math\r\nradios = list(map(int, input().split()))     \r\nprecios = list(map(int, input().split()))     \r\nnombres = [\"pequena\", \"mediana\", \"grande\", \"familiar\"]\r\ncosto_por_area = []\r\nfor r, p in zip(radios, precios):\r\n    area = math.pi * r * r\r\n    costo_por_area.append(p / area)\r\nindice = costo_por_area.index(min(costo_por_area))\r\nprint(nombres[indice])',794),
(795,'import math\r\nradios = list(map(int, input().split()))     \r\nprecios = list(map(int, input().split()))     \r\nnombres = [\"pequeña\", \"mediana\", \"grande\", \"familiar\"]\r\ncosto_por_area = []\r\nfor r, p in zip(radios, precios):\r\n    area = math.pi * r * r\r\n    costo_por_area.append(p / area)\r\nindice = costo_por_area.index(min(costo_por_area))\r\nprint(nombres[indice])',795),
(796,'import sys\r\nsys.setrecursionlimit(10**6)\r\n\r\n# Leer entrada\r\nn, m = map(int, input().split())\r\nbrillos = [0] + list(map(int, input().split()))\r\n\r\ngrafo = [[] for _ in range(n+1)]\r\nfor _ in range(m):\r\n    u, v = map(int, input().split())\r\n    grafo[u].append(v)\r\n    grafo[v].append(u)\r\n\r\nvisitado = [False] * (n+1)\r\n\r\ndef dfs(u):\r\n    visitado[u] = True\r\n    total = brillos[u]\r\n    for v in grafo[u]:\r\n        if not visitado[v]:\r\n            total += dfs(v)\r\n    return total\r\n\r\nmax_brillo = 0\r\nfor i in range(1, n+1):\r\n    if not visitado[i]:\r\n        max_brillo = max(max_brillo, dfs(i))\r\n\r\nprint(max_brillo)',796),
(797,'def lexicograficamente_agradable(s, k):\r\n    n = len(s)\r\n    s = list(s)\r\n\r\n    grupos = [[] for _ in range(k)]\r\n    for i in range(n):\r\n        grupos[i % k].append(i)\r\n\r\n    for grupo in grupos:\r\n        chars = [s[i] for i in grupo]\r\n        # Ordenamos los caracteres\r\n        chars.sort()\r\n        for idx, pos in enumerate(sorted(grupo)):\r\n            s[pos] = chars[idx]\r\n\r\n    return \"\".join(s)\r\n\r\nif __name__ == \"__main__\":\r\n    S = input().strip()\r\n    K = int(input().strip())\r\n    print(lexicograficamente_agradable(S, K))',797),
(798,'n = int(input())\r\npisos = []\r\n\r\nfor _ in range(n):\r\n    entrada = list(map(int, input().split()))\r\n    k = entrada[0]           \r\n    bloques = entrada[1:]    \r\n    pisos.append(bloques)\r\n\r\n\r\npisos_ordenados = sorted(pisos, key=lambda x: len(x))\r\n\r\nfor piso in pisos_ordenados:\r\n    piso.sort(reverse=True)\r\n\r\nfor piso in pisos_ordenados:\r\n    print(\' \'.join(map(str, piso)))',798),
(799,'# Importamos \'permutations\' del módulo \'itertools\'. \r\n# Es la forma más fácil y eficiente de generar todas las secuencias posibles.\r\nfrom itertools import permutations\r\n\r\n# Definimos la lista de los 6 colores disponibles.\r\nCOLORES = [\'R\', \'G\', \'B\', \'Y\', \'O\', \'V\']\r\n\r\ndef calcular_pistas(suposicion, solucion):\r\n    \"\"\"\r\n    Calcula las pistas (n1, n2) de una forma más visual.\r\n    n1: Aciertos de color y posición.\r\n    n2: Aciertos de solo color.\r\n    \"\"\"\r\n    n1 = 0\r\n    n2 = 0\r\n    \r\n    # Copiamos las cadenas a listas, que son más fáciles de modificar.\r\n    suposicion_restante = list(suposicion)\r\n    solucion_restante = list(solucion)\r\n\r\n    # --- PASO 1: Buscar aciertos exactos (n1) ---\r\n    # Recorremos las 4 posiciones.\r\n    for i in range(4):\r\n        # Si el color y la posición coinciden...\r\n        if suposicion_restante[i] == solucion_restante[i]:\r\n            n1 += 1\r\n            # \"Tachamos\" los colores ya contados para no volver a usarlos.\r\n            # Los marcamos con un valor único (como None o un número).\r\n            suposicion_restante[i] = \'usado_sup\'\r\n            solucion_restante[i] = \'usado_sol\'\r\n\r\n    # --- PASO 2: Buscar aciertos de solo color (n2) ---\r\n    # Recorremos los colores restantes de la suposición.\r\n    for color_sup in suposicion_restante:\r\n        # Si este color no fue un acierto exacto...\r\n        if color_sup != \'usado_sup\':\r\n            # ...y además existe en los colores restantes de la solución...\r\n            if color_sup in solucion_restante:\r\n                n2 += 1\r\n                # Lo eliminamos de la solución para no contarlo de nuevo.\r\n                solucion_restante.remove(color_sup)\r\n                \r\n    return n1, n2\r\n\r\ndef resolver_un_caso():\r\n    \"\"\"\r\n    Lee las dos suposiciones y busca una solución que encaje con ambas.\r\n    \"\"\"\r\n    # Leemos la primera suposición y sus pistas (ej: \"OYBG 3 1\")\r\n    linea1 = input().split()\r\n    suposicion1 = linea1[0]\r\n    n1_dado1 = int(linea1[1])\r\n    n2_dado1 = int(linea1[2])\r\n\r\n    # Leemos la segunda suposición y sus pistas\r\n    linea2 = input().split()\r\n    suposicion2 = linea2[0]\r\n    n1_dado2 = int(linea2[1])\r\n    n2_dado2 = int(linea2[2])\r\n\r\n    # Generamos TODAS las 360 secuencias de 4 colores posibles.\r\n    for posible_solucion_tupla in permutations(COLORES, 4):\r\n        posible_solucion = \"\".join(posible_solucion_tupla)\r\n        \r\n        # Comprobamos si esta secuencia candidata funciona para la PISTA 1\r\n        pistas_calculadas1 = calcular_pistas(suposicion1, posible_solucion)\r\n        \r\n        # Si las pistas coinciden con las que le dieron al Sr. Fruit...\r\n        if pistas_calculadas1 == (n1_dado1, n2_dado1):\r\n            \r\n            # ...ahora comprobamos si TAMBIÉN funciona para la PISTA 2\r\n            pistas_calculadas2 = calcular_pistas(suposicion2, posible_solucion)\r\n            \r\n            if pistas_calculadas2 == (n1_dado2, n2_dado2):\r\n                # ¡Bingo! Encontramos una solución que es consistente con ambas pistas.\r\n                print(\"Possible\")\r\n                return # Terminamos, ya no necesitamos seguir buscando.\r\n\r\n    # Si el bucle termina y no encontramos ninguna solución, es imposible.\r\n    print(\"Cheat\")\r\n\r\n\r\n# --- PROGRAMA PRINCIPAL ---\r\n\r\n# Leemos el número de casos de prueba\r\nnum_casos_prueba = int(input())\r\n\r\n# Leemos y descartamos la línea en blanco que hay después del número de casos\r\ninput()\r\n\r\n# Un bucle para ejecutar la solución para cada caso de prueba\r\nfor i in range(num_casos_prueba):\r\n    resolver_un_caso()\r\n    # Si no es el último caso, leemos y descartamos la línea en blanco entre casos\r\n    if i < num_casos_prueba - 1:\r\n        input()',799),
(800,'from itertools import permutations\r\n\r\n\r\nCOLORES = [\'R\', \'G\', \'B\', \'Y\', \'O\', \'V\']\r\n\r\ndef calcular_pistas(suposicion, solucion):\r\n    \"\"\"\r\n    Calcula las pistas (n1, n2) de una forma más visual.\r\n    n1: Aciertos de color y posición.\r\n    n2: Aciertos de solo color.\r\n    \"\"\"\r\n    n1 = 0\r\n    n2 = 0\r\n    \r\n\r\n    suposicion_restante = list(suposicion)\r\n    solucion_restante = list(solucion)\r\n\r\n    for i in range(4):\r\n    \r\n        if suposicion_restante[i] == solucion_restante[i]:\r\n            n1 += 1\r\n\r\n            suposicion_restante[i] = \'usado_sup\'\r\n            solucion_restante[i] = \'usado_sol\'\r\n\r\n\r\n    for color_sup in suposicion_restante:\r\n\r\n        if color_sup != \'usado_sup\':\r\n\r\n            if color_sup in solucion_restante:\r\n                n2 += 1\r\n\r\n                solucion_restante.remove(color_sup)\r\n                \r\n    return n1, n2\r\n\r\ndef resolver_un_caso():\r\n    \"\"\"\r\n    Lee las dos suposiciones y busca una solución que encaje con ambas.\r\n    \"\"\"\r\n\r\n    linea1 = input().split()\r\n    suposicion1 = linea1[0]\r\n    n1_dado1 = int(linea1[1])\r\n    n2_dado1 = int(linea1[2])\r\n\r\n\r\n    linea2 = input().split()\r\n    suposicion2 = linea2[0]\r\n    n1_dado2 = int(linea2[1])\r\n    n2_dado2 = int(linea2[2])\r\n\r\n    for posible_solucion_tupla in permutations(COLORES, 4):\r\n        posible_solucion = \"\".join(posible_solucion_tupla)\r\n        \r\n      \r\n        pistas_calculadas1 = calcular_pistas(suposicion1, posible_solucion)\r\n        \r\n   \r\n        if pistas_calculadas1 == (n1_dado1, n2_dado1):\r\n            \r\n  \r\n            pistas_calculadas2 = calcular_pistas(suposicion2, posible_solucion)\r\n            \r\n            if pistas_calculadas2 == (n1_dado2, n2_dado2):\r\n \r\n                print(\"Possible\")\r\n                return\r\n\r\n   \r\n    print(\"Cheat\")\r\n\r\n\r\n\r\nnum_casos_prueba = int(input())\r\n\r\n\r\ninput()\r\n\r\n\r\nfor i in range(num_casos_prueba):\r\n    resolver_un_caso()\r\n\r\n    if i < num_casos_prueba - 1:\r\n        input()',800),
(801,'a,b,c=0,0,0\r\nwhile True:\r\n    x=input()\r\n    if x==\"-1\":\r\n        break\r\n    elif x==\"P\":\r\n        a+=1\r\n        y=input()\r\n    else:\r\n        y=input()\r\n        if y==\"A\":\r\n            c+=1\r\n        else:\r\n            b+=1\r\nprint(a)\r\nprint(c)\r\nprint(b)',801),
