(824,'def prim(w,n,s):\r\n    v=[0]*n\r\n    v[s]=1\r\n    E = []\r\n    for i in range(n-1):\r\n        min = 1001\r\n        agregar_vertice=0\r\n        e = []\r\n        for j in range (n):\r\n            if (v[j]==1):\r\n                for k in range (n):\r\n                    if(v[k]==0 and w[j][k]<min):\r\n                        agregar_vertice = k\r\n                        e=[j,k]\r\n                        min = w[j][k]\r\n        v[agregar_vertice]=1\r\n        E.append(e)\r\n    return E\r\n\r\nn,m=map(int,input().split()) \r\ns=0\r\nw=[[1001]*n for _ in range(n)]\r\nfor i in range(m):\r\n    x,y,c=map(int,input().split())\r\n    w[x][y]=c\r\n    w[y][x]=c\r\n\r\narbol=prim(w,n,s)\r\nc=0\r\nfor i in range (len(arbol)):\r\n    r1=arbol[i][0]\r\n    r2=arbol[i][1]\r\n    x=w[r1][r2]\r\n    c+=x\r\n\r\nprint(c)',824),
(825,'from itertools import permutations\r\nN=int(input())\r\nfor i in range(N):\r\n    L=int(input())\r\n    lista=list(map(float,input().split()))\r\n    P=list(permutations(lista))\r\n    lp=len(P)\r\n    L=L//2\r\n    c=0\r\n    for j in range (lp):\r\n        c1=0\r\n        c2=0\r\n        for w in range (L):\r\n            c1+=P[j][w]\r\n        for l in range(L,2*L):\r\n            c2+=P[j][l]\r\n        if c1==c2:\r\n            c+=1\r\n    print(c)',825),
