(871,'# Programa: Control de Calidad IMA125\r\n\r\n# Entrada de datos\r\nN = int(input().strip())\r\nT = int(input().strip())\r\n\r\n# Inicialización de variables\r\nold = int(input().strip())  # primera medición\r\nalertas = 0\r\nsuma_diferencias = 0\r\n\r\n# Procesamiento de mediciones\r\nfor _ in range(N - 1):\r\n    new = int(input().strip())\r\n    diferencia = abs(new - old)\r\n    \r\n    if diferencia > T:\r\n        print(\"ALERTA\")\r\n        alertas += 1\r\n        suma_diferencias += diferencia\r\n    else:\r\n        print(\"OK\")\r\n    \r\n    old = new  # actualizar el valor previo\r\n\r\n# Cálculo final y salida\r\nif alertas > 0:\r\n    promedio = suma_diferencias / alertas\r\nelse:\r\n    promedio = 0.0\r\n\r\nprint(alertas)\r\nprint(f\"{promedio:.2f}\")',871),
(872,'while True:\r\n    try:\r\n        a,b,c,d,e = map(float, input(). split())\r\n        if a >= b >= c >= d >= e:\r\n            print (\"Decreciente\")\r\n        elif a <= b <= c <= d <= e:\r\n            print (\"Creciente\")\r\n        else:\r\n            print (\"Ninguno\")\r\n    except EOFError:\r\n        break',872),
(873,'# Solución al problema \"Secuencia de Collatz\"\r\n\r\ndef collatz(n):\r\n    \"\"\"Imprime directamente la secuencia de Collatz para un número n.\"\"\"\r\n    print(n)\r\n    while n != 1:\r\n        if n % 2 == 0:\r\n            n //= 2\r\n        else:\r\n            n = 3 * n + 1\r\n        print(n)\r\n\r\ndef main():\r\n    T = int(input())  # número de casos de prueba\r\n    for _ in range(T):\r\n        n = int(input())\r\n        print(f\"# Collatz para n = {n}\")\r\n        collatz(n)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',873),
(874,'t = int(input())\r\nfor i in range(0,t):\r\n    x = int(input())\r\n    texto =input()\r\n    w1, w2,w3,w4 = texto.split()\r\n    w1 = int((w1))\r\n    w2 = int((w2))\r\n    w3 = int((w3))\r\n    w4 = int((w4))\r\n    if w1<=x or w2<=x or w3<=x or w4<=x:\r\n        lista = [w1,w2,w3,w4]\r\n        nuevalist =[]\r\n        for n in lista:\r\n            if n<=x:\r\n                nuevalist.append(n)\r\n                most= (max(nuevalist))\r\n                print(most)\r\n    elif w1>x and w2>x and w3>x and w4>x:\r\n        print(0)',874),
(875,'t = int(input())\r\nfor i in range(0,t):\r\n    x = int(input())\r\n    texto =input()\r\n    w1, w2,w3,w4 = texto.split()\r\n    w1 = int((w1))\r\n    w2 = int((w2))\r\n    w3 = int((w3))\r\n    w4 = int((w4))\r\n    if w1<=x or w2<=x or w3<=x or w4<=x:\r\n        lista = [w1,w2,w3,w4]\r\n        nuevalist =[]\r\n        for n in lista:\r\n            if n<=x:\r\n                nuevalist.append(n)\r\n        most= max(nuevalist)\r\n        print(most)\r\n    elif w1>x and w2>x and w3>x and w4>x:\r\n        print(0)',875),
(876,'# Solución al problema \"El ajuste de Gregorio\"\r\n\r\ndef es_bisiesto(anio):\r\n    # Regla del calendario gregoriano\r\n    if (anio % 400 == 0) or (anio % 4 == 0 and anio % 100 != 0):\r\n        return \"BISIESTO\"\r\n    else:\r\n        return \"NO BISIESTO\"\r\n\r\ndef main():\r\n    n = int(input().strip())  # cantidad de años\r\n    for _ in range(n):\r\n        anio = int(input().strip())\r\n        print(es_bisiesto(anio))\r\n\r\nif __name__ == \"__main__\":\r\n    main()',876),
(877,'import sys\r\nn1, n2, k = map(int,  sys.stdin.readline().split())\r\n\r\nif 2 * n1 >= k:\r\n    sys.stdout.write(\"SI\")\r\nelif 2 * n2 < k:\r\n    sys.stdout.write(\"SI\")\r\nelse:\r\n    sys.stdout.write(\"NO\")',877),
(878,'n = int(input())\r\nt = int(input())\r\nk_old=int(input())\r\nalertas=0\r\npromedio=0\r\nfor i in range(n-1):\r\n    k_new=int(input())\r\n    if abs(k_old-k_new)>t:\r\n        alertas+=1\r\n        promedio=promedio+abs(k_old-k_new)\r\n        print(\"ALERTA\")\r\n    else:\r\n        print(\"OK\")\r\n    try:\r\n        promedio=promedio/alertas\r\n    except ZeroDivisionError:\r\n        promedio=0\r\n    k_old=k_new\r\nprint(alertas)\r\nprint(f\"%.2f\" % promedio)',878),
