(1026,'cadena =\r\n\r\nlista_alturas = []\r\nfor valor in cadena:\r\n    numero = float(valor)\r\n    lista_alturas.append(numero)\r\n\r\nif lista_alturas == sorted(lista_alturas):\r\n    print(\"creciente\")\r\nelif lista_alturas == sorted(lista_alturas, reverse=True):\r\n    print(\"decreciente\")\r\nelse:\r\n    print(\"ninguno\")',1026),
(1027,'cadena = 1.70, 1.74, 1.90, 1.01, 2.02\r\n\r\nlista_alturas = []\r\nfor valor in cadena:  # Iterate directly over the tuple\r\n    numero = float(valor)\r\n    lista_alturas.append(numero)\r\n\r\nif lista_alturas == sorted(lista_alturas):\r\n    print(\"creciente\")\r\nelif lista_alturas == sorted(lista_alturas, reverse=True):\r\n    print(\"decreciente\")\r\nelse:\r\n    print(\"ninguno\")',1027),
(1028,'# Lista de secuencias de altura\r\nsecuencias = [\r\n    [1.70, 1.80, 1.81, 2.01, 2.02]\r\n    [2.03, 2.01, 1.99, 1.98, 1.97]\r\n    [1.73, 1.72, 1.71, 1.74, 1.75]\r\n]\r\n\r\n# Recorremos cada secuencia\r\nfor secuencia in secuencias:\r\n    # Verificamos si es creciente\r\n    es_creciente = True\r\n    es_decreciente = True\r\n\r\n    for i in range(4):  # Solo hasta el penúltimo elemento\r\n        if secuencia[i] >= secuencia[i + 1]:\r\n            es_creciente = False\r\n        if secuencia[i] <= secuencia[i + 1]:\r\n            es_decreciente = False\r\n\r\n    # Imprimimos el resultado\r\n    if es_creciente:\r\n        print(\"Creciente\")\r\n    elif es_decreciente:\r\n        print(\"Decreciente\")\r\n    else:\r\n        print(\"Ninguno\")',1028),
(1029,'a,b=map(int, input().split())\r\nmy_set=set()\r\nfor x in range(a,b+1):\r\n    for y in range(a,b+1):\r\n        for z in range(a,b+1):\r\n            for t in range(a,b+1):\r\n                if x**2 + y**2 +z**2 == t**2:\r\n                   if t not in my_set:\r\n                       print(f\"{x} {y} {z} {t}\")\r\n                       my_set.add(t)',1029),
(1030,'a, b = map(int, input().split())\r\nmy_set = set()\r\n\r\nfor t in range(a, b+1):\r\n    if t not in my_set:\r\n        for x in range(a, b+1):\r\n            for y in range(a, b+1):\r\n                for z in range(a, b+1):\r\n                    if x**2 + y**2 + z**2 == t**2:\r\n                      if t not in my_set:\r\n                        print(f\"{x} {y} {z} {t}\")\r\n                        my_set.add(t)',1030),
(1031,'h=int(input())\r\nfor o in range(h):\r\n    a,e=map(int,input().split())\r\n    b=[]\r\n    f=[]\r\n    for n in range(a):\r\n        g=list(map(int,input().split()))\r\n        g.append(0)\r\n        b.append(g)\r\n    for n in range(e+1):\r\n        f.append(0)\r\n    b.append(f)\r\n    b[0][0]=3\r\n    d=0\r\n    while d!=1:\r\n        c=0\r\n        for n in range(a):\r\n            for m in range(e):\r\n                if b[n][m]==3:\r\n                    if b[n-1][m]==2 or b[n+1][m]==2 or b[n][m-1]==2 or b[n][m+1]==2:\r\n                        print(\'Escape exitoso\')\r\n                        d=1\r\n                    if b[n-1][m]==1:\r\n                        b[n-1][m]=3\r\n                        c+=1\r\n                    if b[n+1][m]==1:\r\n                        b[n+1][m]=3\r\n                        c+=1\r\n                    if b[n][m-1]==1:\r\n                        b[n][m-1]=3\r\n                        c+=1\r\n                    if b[n][m+1]==1:\r\n                        b[n][m+1]=3\r\n                        c+=1\r\n        if c==0:\r\n            print(\'No hay escapatoria\')\r\n            break',1031),
