(1039,'h=int(input())\r\nfor o in range(h):\r\n    e,a=map(int,input().split())\r\n    b=[]\r\n    f=[]\r\n    for n in range(a):\r\n        g=list(map(int,input().split()))\r\n        g.append(0)\r\n        b.append(g)\r\n    for n in range(e+1):\r\n        f.append(0)\r\n    b.append(f)\r\n    b[0][0]=3\r\n    d=0\r\n    while d!=1:\r\n        try:\r\n            c=0\r\n            for n in range(a):\r\n                for m in range(e):\r\n                    if b[n][m]==3:\r\n                        if b[n-1][m]==2 or b[n+1][m]==2 or b[n][m-1]==2 or b[n][m+1]==2:\r\n                            print(\'Escape exitoso\')\r\n                            d=1\r\n                        if b[n-1][m]==1:\r\n                            b[n-1][m]=3\r\n                            c+=1\r\n                        if b[n+1][m]==1:\r\n                            b[n+1][m]=3\r\n                            c+=1\r\n                        if b[n][m-1]==1:\r\n                            b[n][m-1]=3\r\n                            c+=1\r\n                        if b[n][m+1]==1:\r\n                            b[n][m+1]=3\r\n                            c+=1\r\n            if c==0:\r\n                print(\'No hay escapatoria\')\r\n                break\r\n        except EOFError:\r\n            break',1039),
(1040,'h=int(input())\r\nfor o in range(h):\r\n    e,a=map(int,input().split())\r\n    b=[]\r\n    f=[]\r\n    for n in range(a):\r\n        g=list(map(int,input().split()))\r\n        g.append(0)\r\n        b.append(g)\r\n    for n in range(e+1):\r\n        f.append(0)\r\n    b.append(f)\r\n    b[0][0]=3\r\n    d=0\r\n    while d!=1:\r\n        try:\r\n            c=0\r\n            for n in range(a):\r\n                for m in range(e):\r\n                    if b[n][m]==3:\r\n                        if b[n-1][m]==2 or b[n+1][m]==2 or b[n][m-1]==2 or b[n][m+1]==2:\r\n                            print(\'Escape exitoso\')\r\n                            d=1\r\n                        if b[n-1][m]==1:\r\n                            b[n-1][m]=3\r\n                            c+=1\r\n                        if b[n+1][m]==1:\r\n                            b[n+1][m]=3\r\n                            c+=1\r\n                        if b[n][m-1]==1:\r\n                            b[n][m-1]=3\r\n                            c+=1\r\n                        if b[n][m+1]==1:\r\n                            b[n][m+1]=3\r\n                            c+=1\r\n            if c==0:\r\n                print(\'No hay escapatoria\')\r\n                break\r\n        except ValueError:\r\n            break',1040),
(1041,'bloques=[]\r\nn=int(input())\r\nfor i in range(n):\r\n    lista=list(map(int,input().split()))\r\n    lista_copy=lista.copy()\r\n    lista_copy.pop(0)\r\n    for i in range(len(lista_copy)):\r\n        bloques.append(lista_copy[i])\r\nmaximo=max(bloques)\r\nmatriz=[]\r\nfor i in range(maximo,0,-1):\r\n    lista=[]\r\n    for k in range(len(bloques)):\r\n        if bloques[k]==i:\r\n            lista.append(bloques[k])\r\n    matriz.append(lista)\r\nx=len(matriz[len(matriz)-1])\r\nfor i in range(x-1,-1,-1):\r\n    piso=\"\"\r\n    for k in range(x-1,-1,-1):\r\n        try:\r\n            if piso==\"\":\r\n                piso=f\"{matriz[k][i]}\"\r\n            else:\r\n                piso=piso+\" \"f\"{matriz[k][i]}\"\r\n        except IndexError:\r\n            pass\r\n    print(piso)',1041),
(1042,'n=int(input())\r\nmatriz=[]\r\n\r\nfor i in range(n):\r\n    lista=list(map(int,input().split()))\r\n    lista.pop(0)\r\n    lista.sort(reverse=True)\r\n    matriz.append(lista)\r\nmatriz.sort(key=len)\r\nprint(matriz)\r\n\r\nfor i in matriz:\r\n    print(*i)',1042),
