(1052,'for i in range(3):\r\n    coso = input()\r\n    a, b = coso.split()\r\n    a = int(a)\r\n    b = int(b)\r\n    c = a+b\r\n    print(c)',1052),
(1053,'# Los Secretos del ADN Palíndromo (Código: secretosdeladn)\r\n\r\ndef es_palindromo(s: str) -> bool:\r\n    \"\"\"Verifica si una cadena de ADN es un palíndromo.\"\"\"\r\n    return s == s[::-1]\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    \r\n    # Si es 0, se termina la lectura\r\n    if entrada == \"0\":\r\n        break\r\n    \r\n    # Dividir la entrada en longitud y cadena\r\n    partes = entrada.split()\r\n    if len(partes) != 2:\r\n        continue  # Ignora entradas inválidas\r\n    \r\n    longitud, cadena = partes\r\n    longitud = int(longitud)\r\n    \r\n    # Validar que la longitud coincida\r\n    if len(cadena) != longitud:\r\n        print(\"Error: la longitud indicada no coincide con la cadena.\")\r\n        continue\r\n    \r\n    # Determinar si es palíndromo\r\n    if es_palindromo(cadena):\r\n        print(\"Eureka! Es un palindromo genetico\")\r\n    else:\r\n        print(\"Lo siento, no es un palindromo genetico\")',1053),
(1054,'# El Libro de las Notas Ordenadas (Código: granlibrodelasnotas)\r\n\r\nnotas_alumnos = []\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    \r\n    if entrada == \"0\":\r\n        break  # fin de lectura\r\n    \r\n    partes = entrada.split()\r\n    nota = int(partes[0])\r\n    nombre = partes[1]\r\n    \r\n    notas_alumnos.append((nota, nombre))\r\n\r\n# Ordenar por la nota, respetando el orden original en caso de empate\r\nnotas_alumnos.sort(key=lambda x: x[0])\r\n\r\n# Imprimir nombres ordenados\r\nfor _, nombre in notas_alumnos:\r\n    print(nombre)',1054),
(1055,'def ruta_minima(n,w,s):\r\n    distancia=[1000000000]*n\r\n    visitado=[False]*n\r\n    distancia[s]=0 \r\n    for i in range(n): \r\n        u=-1\r\n        minimo=1000000000\r\n        for k in range(n):\r\n            if not visitado[k] and distancia[k]<minimo:\r\n                minimo = distancia[k]\r\n                u=k\r\n        if u==-1:\r\n            break\r\n        visitado[u]=True\r\n        for t,p in w[u]:\r\n            if distancia[t]>distancia[u]+p:\r\n                distancia[t]=distancia[u]+p\r\n    return distancia\r\n        \r\nn,m=map(int,input().split())\r\n\r\nmatriz=[[] for _ in range(n)]\r\naristas = []\r\nfor i in range(m):\r\n    a,b,c=map(int,input().split())\r\n    a=a-1\r\n    b=b-1\r\n    matriz[a].append((i,b,c))\r\n    matriz[b].append((i,a,c))\r\n    aristas.append((a,b,c))\r\n\r\nfor i in range(m):\r\n    aa, bb, cc = aristas[i]\r\n    matriz_copy = [[] for _ in range(n)]\r\n    for nodo in range(n):\r\n        for I,B,C in matriz[nodo]:\r\n            if I!=i:\r\n                matriz_copy[nodo].append((B,C))\r\n    x=ruta_minima(n,matriz_copy,aa)\r\n    if x[bb]<1000000000:\r\n        print(x[bb])\r\n    else:\r\n        print(-1)',1055),
(1056,'from itertools import permutations\r\nfrom itertools import combinations\r\n\r\nt=int(input())\r\ncolores=[\"R\",\"G\",\"B\",\"Y\",\"O\",\"V\"]\r\nx=list(permutations(colores,4))\r\nl=len(x)\r\n\r\ndef casos(i,le,st,x_c):\r\n    for s in range(le):\r\n        ci=0\r\n        cm=0\r\n        for k in range(4):\r\n            if x_c[s][k]==st[k]:\r\n                ci+=1\r\n            elif s1[k] in x[i]:\r\n                cm+=1\r\n        x_c[s]=(ci,cm)\r\n\r\nfor i in range(t):\r\n    bandera=\"\"\r\n    input()\r\n    s1,a,b=input().split()\r\n    s2,c,d=input().split()\r\n    a=int(a)\r\n    b=int(b)\r\n    c=int(c)\r\n    d=int(d)\r\n    s1=list(s1)\r\n    s2=list(s2)\r\n    x_copy1=x.copy()\r\n    casos(i,l,s1,x_copy1)\r\n    x_copy2=x.copy()\r\n    casos(i,l,s2,x_copy2)\r\n    for z in range(l):\r\n        if x_copy1[z][0]==a and x_copy1[z][1]==b and x_copy2[z][0]==c and x_copy2[z][1]==d:\r\n            bandera=\"!\"\r\n    if bandera==\"!\":\r\n        print(\"Possible\")\r\n    else:\r\n        print(\"Cheat\")',1056),
(1057,'def explorar(x,y,n,m):\r\n    if not visitado[y][x] and plano[y][x]==\"-\":\r\n        visitado[y][x]=True\r\n        if y==n-1:\r\n            visitado[x][x]=True\r\n        else:\r\n            if plano[y+1][x]==\"-\":\r\n                explorar(x,y+1,n,m)\r\n            elif x==0:\r\n                explorar(x+1,y,n,m)\r\n            elif x==m-1:\r\n                explorar(x-1,y,n,m)\r\n            else:\r\n                explorar(x+1,y,n,m)\r\n                explorar(x-1,y,n,m)\r\n\r\nn,m=map(int,input().split())\r\nplano=[]\r\nfor i in range(n):\r\n    x=list(input())\r\n    plano.append(x)\r\n\r\nvisitado=[[False]*m for _ in range(n)]\r\n\r\nfor i in range(m):\r\n    for r in range(n):\r\n        if plano[r][i]==\"*\":\r\n            x=i\r\n            y=r\r\n\r\nvisitado[y][x]=True\r\nif y==n:\r\n    visitado[x][x]=True\r\nelse:\r\n    if plano[y+1][x]==\"-\":\r\n        explorar(x,y+1,n,m)\r\n    elif x==0:\r\n        explorar(x+1,y,n,m)\r\n    elif x==m:\r\n        explorar(x-1,y,n,m)\r\n    else:\r\n        explorar(x+1,y,n,m)\r\n        explorar(x-1,y,n,m)\r\nprint(\"Plano:\")\r\nfor i in range(m):\r\n    for r in range(n):\r\n        if visitado[r][i]:\r\n            plano[r][i]=\"*\"\r\nfor i in range(n):\r\n    print(\"\".join(plano[i]))',1057),
(1058,'def explorar(x,y,n,m):\r\n    if not visitado[y][x] and plano[y][x]==\"-\":\r\n        visitado[y][x]=True\r\n        if y==n-1:\r\n            visitado[y][x]=True\r\n        else:\r\n            if plano[y+1][x]==\"-\":\r\n                explorar(x,y+1,n,m)\r\n            elif x==0:\r\n                explorar(x+1,y,n,m)\r\n            elif x==m-1:\r\n                explorar(x-1,y,n,m)\r\n            else:\r\n                explorar(x+1,y,n,m)\r\n                explorar(x-1,y,n,m)\r\n\r\nn,m=map(int,input().split())\r\nplano=[]\r\nfor i in range(n):\r\n    x=list(input())\r\n    plano.append(x)\r\n\r\nvisitado=[[False]*m for _ in range(n)]\r\n\r\nfor i in range(m):\r\n    for r in range(n):\r\n        if plano[r][i]==\"*\":\r\n            x=i\r\n            y=r\r\n\r\nvisitado[y][x]=True\r\nif y==n-1:\r\n    visitado[x][x]=True\r\nelse:\r\n    if plano[y+1][x]==\"-\":\r\n        explorar(x,y+1,n,m)\r\n    elif x==0:\r\n        explorar(x+1,y,n,m)\r\n    elif x==m-1:\r\n        explorar(x-1,y,n,m)\r\n    else:\r\n        explorar(x+1,y,n,m)\r\n        explorar(x-1,y,n,m)\r\nprint(\"Plano:\")\r\nfor i in range(m):\r\n    for r in range(n):\r\n        if visitado[r][i]:\r\n            plano[r][i]=\"*\"\r\nfor i in range(n):\r\n    print(\"\".join(plano[i]))',1058),
(1059,'def prim(w,n,s):\r\n    v=[0]*n\r\n    v[s]=1\r\n    E = []\r\n    for i in range(n-1):\r\n        min = 1001\r\n        agregar_vertice=0\r\n        e = []\r\n        for j in range (n):\r\n            if (v[j]==1):\r\n                for k in range (n):\r\n                    if(v[k]==0 and w[j][k]<min):\r\n                        agregar_vertice = k\r\n                        e=[j,k]\r\n                        min = w[j][k]\r\n        v[agregar_vertice]=1\r\n        E.append(e)\r\n    return E\r\n\r\nn,m,s=map(int,input().split())\r\ncontador=0\r\nx=0\r\nw=w=[[10000]*n for _ in range(n)]\r\nfor i in range(m):\r\n    u,v,l=map(int,input().split())\r\n    if contador<s:\r\n        l=0\r\n        x=u\r\n    w[u][v]=l\r\n    w[v][u]=l\r\n    contador+=1\r\n\r\narbol=prim(w,n,x)\r\nL=len(arbol)\r\nTotal=0\r\nfor i in range(L):\r\n    x=arbol[i][0]\r\n    y=arbol[i][1]\r\n    Total+=w[x][y]\r\nprint(Total)',1059),
(1060,'import copy\r\n\r\ndef conectados(z,w):\r\n    L=[z]\r\n    for _ in range(len(w)):\r\n        for i in range(len(w)):\r\n            a=w[i][0]\r\n            b=w[i][1]\r\n            if a in L and b not in L:\r\n                L.append(b)\r\n            elif b in L and a not in L:\r\n                L.append(a)\r\n    L.sort()\r\n    return L\r\n\r\nL=[]\r\nn,m=map(int,input().split())\r\nmatriz=[]*n\r\nfor i in range(m):\r\n    a,b=map(int,input().split())\r\n    matriz.append([a,b])    \r\n    matriz.append([b,a])\r\n    if a not in L:\r\n        L.append(a)\r\n    if b not in L:\r\n        L.append(b)\r\n    L.sort()\r\nlargoL=len(L)\r\nlargoM=len(matriz)\r\n\r\nconex=[]\r\nfor i in L:\r\n    x=conectados(i,matriz)\r\n    conex.append(x)\r\nfor i in L:\r\n    conex_copy=copy.deepcopy(conex)\r\n    for k in range(largoL):\r\n        r=conex_copy[k].index(i)\r\n        conex_copy[k].pop(r)\r\n    L_copy=L.copy()\r\n    x=L.index(i)\r\n    L_copy.pop(x)\r\n    matriz_copy=matriz.copy()\r\n    for k in range(len(matriz)-1,-1,-1):\r\n        if matriz[k][0]==i or matriz[k][1]==i:\r\n            matriz_copy.pop(k)\r\n    conexi=[]\r\n    for s in L:\r\n        if s!=i:\r\n            T=conectados(s,matriz_copy)\r\n            conexi.append(T)\r\n    conex_copy.pop(len(conex_copy)-1)\r\n    if conexi!=conex_copy:\r\n        print(f\"{i} es critico\")',1060),
(1061,'# Noentiendo Co (Código: tpc2025noentiendo)\r\nimport sys\r\n\r\ndef solve():\r\n    # Leer toda la entrada y limpiar líneas vacías\r\n    lines = [line.strip() for line in sys.stdin.read().splitlines() if line.strip() != \"\"]\r\n    if not lines:\r\n        return\r\n\r\n    n = int(lines[0])\r\n    s = lines[1]\r\n\r\n    # Posiciones de A y T\r\n    a = s.find(\'A\')\r\n    t = s.find(\'T\')\r\n\r\n    # Asegurar orden (a < t)\r\n    if a > t:\r\n        a, t = t, a\r\n\r\n    # Si hay un \'#\' entre A y T, entonces no es alcanzable\r\n    segment = s[a+1:t]\r\n    if \'#\' in segment:\r\n        print(\"perdiste\")\r\n    else:\r\n        print(\"ganaste\")\r\n\r\nif __name__ == \"__main__\":\r\n    solve()',1061),
(1062,'lista=[]\r\nwhile True:\r\n    x=input()\r\n    if x==\"0\":\r\n        break\r\n    a,b=x.split()\r\n    a=int(a)\r\n    lista.append((a,b))\r\nlista.sort()\r\nfor i in range(len(lista)):\r\n    print(lista[i][1])',1062),
(1063,'lista=[]\r\ni=0\r\nwhile True:\r\n    x=input()\r\n    if x==\"0\":\r\n        break\r\n    a,b=x.split()\r\n    a=int(a)\r\n    lista.append((a,i,b))\r\n    i+=1\r\nlista.sort()\r\nfor i in range(len(lista)):\r\n    print(lista[i][2])',1063),
