(1065,'n=int(input())\r\ncadena=list(input())\r\nA=cadena.index(\"A\")\r\nprint(A)\r\nprint(cadena)\r\nBandera=\"perdiste\"\r\nB=A\r\nwhile True:\r\n    B=B+1\r\n    if B==n:\r\n        break\r\n    if cadena[B]==\"#\":\r\n        break\r\n    elif cadena[B]==\"T\":\r\n        Bandera=\"ganaste\"\r\n\r\nwhile True:\r\n    B=B-1\r\n    if B==-1:\r\n        break\r\n    if cadena[B]==\"#\":\r\n        break\r\n    elif cadena[B]==\"T\":\r\n        Bandera=\"ganaste\"\r\n\r\nprint(Bandera)',1065),
(1066,'n=int(input())\r\ncadena=list(input())\r\nA=cadena.index(\"A\")\r\nBandera=\"perdiste\"\r\nB=A\r\nwhile True:\r\n    B=B+1\r\n    if B==n:\r\n        break\r\n    if cadena[B]==\"#\":\r\n        break\r\n    elif cadena[B]==\"T\":\r\n        Bandera=\"ganaste\"\r\n\r\nwhile True:\r\n    B=B-1\r\n    if B==-1:\r\n        break\r\n    if cadena[B]==\"#\":\r\n        break\r\n    elif cadena[B]==\"T\":\r\n        Bandera=\"ganaste\"\r\n\r\nprint(Bandera)',1066),
(1067,'while True:\r\n    z=True\r\n    bases = []\r\n    c = input()\r\n    if c==\"0\":\r\n        break\r\n    a, b = c.split()\r\n    a= int(a)\r\n    for i in b:\r\n        bases.append(i)\r\n    if len(bases)%2==0:\r\n        for i in range(len(bases)//2):\r\n            if bases[i]!=bases[len(bases)-1-i]:\r\n                z = False\r\n    else:\r\n        for i in range((len(bases)//2)-1):\r\n            if bases[i]!=bases[len(bases)-1-i]:\r\n                z = False\r\n    if z == True:\r\n        print(\"Eureka! Es un palindromo genetico\")\r\n    else:\r\n        print(\"Lo siento, no es un palindromo genetico\")',1067),
(1068,'while True:\r\n    try:\r\n        adn1=[]\r\n        adn2=[]\r\n        l,p=input().split()\r\n        palabra=list(p)\r\n        l=int(l)\r\n        if l%2==0:\r\n            for i in range(l//2):\r\n                adn1.append(palabra[i])\r\n            palabra.reverse()\r\n            for k in range(l//2):\r\n                adn2.append(palabra[k])\r\n        else:\r\n            for i in range(l//2+1):\r\n                adn1.append(palabra[i])\r\n            palabra.reverse()\r\n            for k in range(l//2+1):\r\n                adn2.append(palabra[k])\r\n        if adn1==adn2:\r\n            print(\"Eureka! Es un palindromo genetico\")\r\n        else:\r\n            print(\"Lo siento, no es un palindromo genetico\")\r\n    except ValueError:\r\n        break',1068),
