(1108,'h=int(input())\r\nfor o in range(h):\r\n    a,e=map(int,input().split())\r\n    b=[]\r\n    f=[]\r\n    for n in range(a):\r\n        g=list(map(int,input().split()))\r\n        g.append(0)\r\n        b.append(g)\r\n    for n in range(e+1):\r\n        f.append(0)\r\n    b.append(f)\r\n    if b[0][0]==2:\r\n        print(\'Escape exitoso\')\r\n    else:\r\n        b[0][0]=3\r\n        d=0\r\n        while d!=1:\r\n            c=0\r\n            for n in range(a):\r\n                for m in range(e):\r\n                    if b[n][m]==3:\r\n                        if b[n-1][m]==2 or b[n+1][m]==2 or b[n][m-1]==2 or b[n][m+1]==2:\r\n                            print(\'Escape exitoso\')\r\n                            d=1\r\n                        if b[n-1][m]==1:\r\n                            b[n-1][m]=3\r\n                            c+=1\r\n                        if b[n+1][m]==1:\r\n                            b[n+1][m]=3\r\n                            c+=1\r\n                        if b[n][m-1]==1:\r\n                            b[n][m-1]=3\r\n                            c+=1\r\n                        if b[n][m+1]==1:\r\n                            b[n][m+1]=3\r\n                            c+=1\r\n            if c==0:\r\n                print(\'No hay escapatoria\')\r\n                break',1108),
