(1134,'# Programa para determinar si una matriz es simétrica\r\n\r\ndef es_simetrica(matriz, n):\r\n    for i in range(n):\r\n        for j in range(n):\r\n            if matriz[i][j] != matriz[j][i]:\r\n                return False\r\n    return True\r\n\r\ndef main():\r\n    n = int(input().strip())\r\n    matriz = [list(map(int, input().split())) for _ in range(n)]\r\n    \r\n    if es_simetrica(matriz, n):\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1134),
