(1153,'#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    int n;\r\n    cin >> n;\r\n    int matriz[n][n];\r\n    for (int x = 0; x<n ; x++){\r\n        for (int y = 0; y<n ; y++){\r\n            cin >> matriz[x][y];\r\n        }\r\n    }\r\n    bool bandera;\r\n    bandera = true;\r\n    for (int x=0; x<n ; x++){\r\n        for (int y= 0; y<n; y++){\r\n            if (matriz[x][y] != matriz[y][x]){\r\n                bandera = false;\r\n                break;\r\n            }\r\n        }\r\n        if (!bandera){\r\n            break;\r\n        }\r\n    }\r\n\r\n    if (bandera){\r\n        cout << \"SI\";\r\n    } else {\r\n        cout << \"NO\";\r\n    }\r\n\r\n    return 0;\r\n}',1153),
(1154,'#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nclass explorar{\r\n    public:\r\n        void derecha(int x, int y, int m, int n, int matriz[][100], bool visitado[][100], int& c, int celdas){\r\n            if (y<m-1 && !visitado[x][y+1]){\r\n                visitado[x][y+1]=true;\r\n                c++;\r\n                cout << matriz[x][y+1];\r\n                if (c!=celdas){\r\n                    cout << \" \";\r\n                }\r\n                if (c== celdas){\r\n                    return;\r\n                }\r\n                derecha(x,y+1,m, n, matriz, visitado, c, celdas);\r\n            } else { \r\n                abajo(x ,y, m ,n, matriz, visitado, c, celdas);\r\n            }\r\n        }\r\n        void abajo(int x, int y, int m, int n, int matriz[][100], bool visitado[][100], int& c, int celdas){\r\n            if (x<n-1 && !visitado[x+1][y]){\r\n                visitado[x+1][y]=true;\r\n                c++;\r\n                cout << matriz[x+1][y];\r\n                if (c!=celdas){\r\n                    cout << \" \";\r\n                }\r\n                if (c==celdas){\r\n                    return;\r\n                }\r\n                abajo(x+1,y,m, n, matriz, visitado, c, celdas);\r\n            } else { \r\n                izquierda(x ,y, m ,n, matriz, visitado, c, celdas);\r\n            }\r\n        }\r\n        void izquierda(int x, int y, int m, int n, int matriz[][100], bool visitado[][100], int& c, int celdas){\r\n            if (y-1>=0 && !visitado[x][y-1]){\r\n                visitado[x][y-1]=true;\r\n                c++;\r\n                cout << matriz[x][y-1];\r\n                if (c!=celdas){\r\n                    cout << \" \";\r\n                }\r\n                if (c== celdas){\r\n                    return;\r\n                }\r\n                izquierda(x,y-1,m, n, matriz, visitado, c, celdas);\r\n            } else { \r\n                arriba(x ,y, m ,n, matriz, visitado, c, celdas);\r\n            }\r\n        }\r\n        void arriba(int x, int y, int m, int n, int matriz[][100], bool visitado[][100], int& c, int celdas){\r\n            if (x-1>=0 && !visitado[x-1][y]){\r\n                visitado[x-1][y]=true;\r\n                c++;\r\n                cout << matriz[x-1][y];\r\n                if (c!=celdas){\r\n                    cout << \" \";\r\n                }\r\n                if (c==celdas){\r\n                    return;\r\n                }\r\n                arriba(x-1, y, m, n, matriz, visitado, c, celdas);\r\n            } else { \r\n                derecha(x ,y, m ,n, matriz, visitado, c, celdas);\r\n            }\r\n        }\r\n};\r\n\r\nint main()\r\n{\r\n    int n;\r\n    int m;\r\n    cin >> n;\r\n    cin >> m;\r\n    int celdas = n*m;\r\n    int c=1;\r\n    bool visitado[100][100]={false};\r\n    int matriz[100][100];\r\n    for (int x = 0; x<n ; x++){\r\n        for (int y = 0; y<m ; y++){\r\n            cin >> matriz[x][y];\r\n        }\r\n    }\r\n    explorar bo;\r\n    visitado[0][0] = true,\r\n    cout << matriz[0][0] << \" \";\r\n    bo.derecha(0,0,m,n,matriz,visitado,c,celdas);\r\n    return 0;\r\n}',1154),
