(1156,'#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    int n;\r\n    int m;\r\n    cin >> n >> m;\r\n    bool visitado[100][100]={false};\r\n    int matriz[100][100];\r\n    for (int x = 0; x<n ; x++){\r\n        for (int y = 0; y<m ; y++){\r\n            cin >> matriz[x][y];\r\n        }\r\n    }\r\n    int c = 1;\r\n    int i = 0;\r\n    int direcx [4] = {0, 1, 0,-1}; //derecha, abajo, izquierda, arriba\r\n    int direcy [4] = {1, 0, -1,0};\r\n    visitado[0][0]=true;\r\n    cout << matriz[0][0];\r\n    if (n!=1 or m!=1){\r\n        cout << \" \";\r\n    }\r\n    int x=0;\r\n    int y=0;\r\n    while (c!=n*m){\r\n        if (0<=x+direcx[i] && x+direcx[i]<n &&  0<=y+direcy[i] && y+direcy[i]<m && !visitado[x+direcx[i]][y+direcy[i]]){\r\n            x+=direcx[i];\r\n            y+=direcy[i];\r\n            visitado[x][y] = true;\r\n            cout << matriz[x][y];\r\n            if (c+1!=n*m){\r\n                cout << \" \";\r\n            }\r\n            c++;\r\n        } else {\r\n            i++;\r\n            i=i%4;\r\n        }\r\n    }\r\n    return 0;\r\n}',1156),
