(1161,'#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    int n;\r\n    cin >> n;\r\n    for(int i=0; i<n; i++){\r\n        int z;\r\n        cin >> z;\r\n        for (int a=0; a<10; a++){\r\n            for (int b=0; b<10; b++){\r\n                for (int c=0; c<10; c++){\r\n                    for (int d=0; d<10; d++){\r\n                        if (a+b+c+d==z){\r\n                            cout << a << b << c << d << \" es una clave de la suerte que suma \" << z << endl;\r\n                        }\r\n                    }\r\n                }\r\n            \r\n            }\r\n        }\r\n    }\r\n    return 0;\r\n}',1161),
