(1163,'#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nvoid explorar(bool visitados[100][100], int matriz[100][100], int n, int m, int x, int y){\r\n    if (x>=0 &&  x<n && y>=0 && y<m && matriz[x][y]!=0 && !visitados[x][y]){\r\n        visitados[x][y]=true;\r\n        explorar(visitados,matriz,n,m,x+1,y);\r\n        explorar(visitados,matriz,n,m,x-1,y);\r\n        explorar(visitados,matriz,n,m,x,y-1);\r\n        explorar(visitados,matriz,n,m,x,y+1);\r\n    }\r\n}\r\n\r\n\r\nint main()\r\n{\r\n    int T;\r\n    cin >> T;\r\n    for (int p = 0; p<T; p++){\r\n        int n;\r\n        int m;\r\n        cin >> n >> m;\r\n        int matriz[100][100];\r\n        for (int x = 0; x<n ; x++){\r\n            for (int y = 0; y<m ; y++){\r\n                cin >> matriz[x][y];\r\n            }\r\n        }\r\n        bool visitados[100][100]={false};\r\n        visitados[0][0]=true;\r\n        explorar(visitados,matriz,n,m,1,0);\r\n        explorar(visitados,matriz,n,m,0,1);\r\n        string bandera=\"No hay escapatoria\";\r\n        bool encontrado=false;\r\n        for (int x = 0; x<n && !encontrado; x++){\r\n            for (int y = 0; y<m && !encontrado; y++){\r\n                if (visitados[x][y]==true && matriz[x][y]==2){\r\n                    bandera=\"Escape exitoso\";\r\n                    encontrado=true;\r\n                    break;\r\n                }\r\n            } \r\n        }\r\n        cout << bandera << endl; \r\n    }\r\n    return 0;\r\n}',1163),
(1164,'#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nvoid explorar(bool visitados[100][100], int matriz[100][100], int n, int m, int x, int y){\r\n    if (x>=0 &&  x<n && y>=0 && y<m && matriz[x][y]!=0 && !visitados[x][y]){\r\n        visitados[x][y]=true;\r\n        explorar(visitados,matriz,n,m,x+1,y);\r\n        explorar(visitados,matriz,n,m,x-1,y);\r\n        explorar(visitados,matriz,n,m,x,y-1);\r\n        explorar(visitados,matriz,n,m,x,y+1);\r\n    }\r\n}\r\n\r\n\r\nint main()\r\n{\r\n    int T;\r\n    cin >> T;\r\n    for (int p = 0; p<T; p++){\r\n        int n;\r\n        int m;\r\n        cin >> n >> m;\r\n        int matriz[100][100];\r\n        for (int x = 0; x<n ; x++){\r\n            for (int y = 0; y<m ; y++){\r\n                cin >> matriz[x][y];\r\n            }\r\n        }\r\n        bool visitados[100][100]={false};\r\n        visitados[0][0]=true;\r\n        explorar(visitados,matriz,n,m,1,0);\r\n        explorar(visitados,matriz,n,m,0,1);\r\n        string bandera=\"No hay escapatoria\";\r\n        bool encontrado=false;\r\n        for (int x = 0; x<n && !encontrado; x++){\r\n            for (int y = 0; y<m && !encontrado; y++){\r\n                if (visitados[x][y]==true && matriz[x][y]==2){\r\n                    bandera=\"Escape exitoso\";\r\n                    encontrado=true;\r\n                    break;\r\n                }\r\n            } \r\n        }\r\n        cout << bandera << endl; \r\n    }\r\n    return 0;\r\n}',1164),
