(1170,'int main()\r\n{\r\n    int a,b;\r\n    cin >> a >> b;\r\n    for (int t = a; t<=b ; t++){\r\n        bool c=true;\r\n        int z=a;\r\n        for (int x = a; x<=t && c; x++){\r\n             for (int y = x; y<=t && c; y++){\r\n                 for (int z = y; z<=t && c; z++){\r\n                    if (pow(x,2)+pow(y,2)+pow(z,2)==pow(t,2)){\r\n                        cout << x << y << z << t << endl;\r\n                        c=false;\r\n                    }\r\n                }   \r\n             }\r\n        }\r\n    }\r\n    cin.ignore();\r\n    cin.get();\r\n    return 0;\r\n}',1170),
