(1178,'#include <iostream>\r\n#include <string>\r\n#include <algorithm>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n\r\n    string palabra;\r\n    cin >> palabra;\r\n    int largo = palabra.size();\r\n    int k;\r\n    cin >> k;\r\n    vector<string> m(k);\r\n    for (int i=0; i<largo ; i++){\r\n        m[i%k]+=palabra[i];\r\n    }\r\n    for (int i=0; i<k; i++){\r\n        sort(m[i].begin(),m[i].end());\r\n    }\r\n    string final = \"\";\r\n    int c=0;\r\n    for (int i=0; i<largo; i++){\r\n        final+=m[i%k][c];\r\n        if (i%k==k-1){\r\n            c++;\r\n        }\r\n    }\r\n    cout << final;\r\n    cin.ignore();\r\n    cin.get();\r\n    return 0;\r\n}',1178),
(1179,'#include <iostream>\r\n#include <string>\r\n#include <algorithm>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    int n;\r\n    cin >> n;\r\n    vector<int> num(n);\r\n    for (int i = 0; i< n; i++){\r\n        cin >> num[i];\r\n    }\r\n    sort(num.begin(),num.end());\r\n    int k = n-1;\r\n    do{\r\n        bool bandera=false;\r\n        for (int i = 0; i<n && !bandera; i++){\r\n            if (num[i]<18){\r\n                if (i==0){\r\n                    if (num[1]<18){\r\n                        bandera=true;\r\n                    }\r\n                    break;\r\n                }\r\n                if (i==n-1){\r\n                    if (num[n-2]<18){\r\n                        bandera=true;\r\n                    }\r\n                    break;\r\n                }\r\n                if(num[i-1]<18 && num[i+1]<18){\r\n                    bandera=true;\r\n                    break;\r\n                }\r\n            }\r\n        }\r\n        if (!bandera){\r\n            for (int i = 0; i< n; i++){\r\n            cout << num[i];\r\n            if (i!=n-1){\r\n                cout << \" \";\r\n            }\r\n            }\r\n            cout << endl;\r\n        }\r\n    } while (next_permutation(num.begin(), num.end()));\r\n    cin.ignore();\r\n    cin.get();\r\n    return 0;\r\n}',1179),
(1180,'#include <iostream>\r\n#include <string>\r\n#include <algorithm>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    int n;\r\n    cin >> n;\r\n    vector<int> num(n);\r\n    for (int i = 0; i< n; i++){\r\n        cin >> num[i];\r\n    }\r\n    sort(num.begin(),num.end());\r\n    do{\r\n        bool bandera=false;\r\n        for (int i = 0; i<n && !bandera; i++){\r\n            if (num[i]<18){\r\n                if (i==0){\r\n                    if (num[1]<18){\r\n                        bandera=true;\r\n                        \r\n                    }\r\n                }\r\n                else if (i==n-1){\r\n                    if (num[n-2]<18){\r\n                        bandera=true;\r\n                    }\r\n                }\r\n                else if(num[i-1]<18 && num[i+1]<18){\r\n                    bandera=true;\r\n                }\r\n            }\r\n        }\r\n        if (!bandera){\r\n            for (int i = 0; i< n; i++){\r\n            cout << num[i];\r\n            if (i!=n-1){\r\n                cout << \" \";\r\n            }\r\n            }\r\n            cout << endl;\r\n        }\r\n    } while (next_permutation(num.begin(), num.end()));\r\n    return 0;\r\n}',1180),
(1181,'def prim(w,n,s):\r\n    v=[0]*n\r\n    v[s]=1\r\n    E = []\r\n    for i in range(n-1):\r\n        min = float(\'inf\')\r\n        agregar_vertice=0\r\n        e = []\r\n        for j in range (n):\r\n            if (v[j]==1):\r\n                for k in range (n):\r\n                    if(v[k]==0 and w[j][k]<min):\r\n                        agregar_vertice = k\r\n                        e=[j,k]\r\n                        min = w[j][k]\r\n        v[agregar_vertice]=1\r\n        E.append(e)\r\n    return E\r\n\r\nt=int(input())\r\nfor R in range(t):\r\n    input()\r\n    m=int(input())\r\n    n=int(input())\r\n    conexiones=[]\r\n    ciudades=[]\r\n    for i in range(n):\r\n        a,b,c=input().split()\r\n        c=int(c)\r\n        if a not in ciudades:\r\n            ciudades.append(a)\r\n        if b not in ciudades:\r\n            ciudades.append(b)\r\n        conexiones.append([a,b,c])\r\n        conexiones.append([b,a,c])\r\n    for i in range(len(conexiones)):\r\n        for k in range(2):\r\n            conexiones[i][k]=ciudades.index(conexiones[i][k])\r\n    w=[[float(\'inf\')]*m for _ in range(m)]\r\n    for i in range(len(conexiones)):\r\n        w[conexiones[i][0]][conexiones[i][1]]=conexiones[i][2]\r\n        w[conexiones[i][0]][conexiones[i][1]]=conexiones[i][2]\r\n    x=prim(w,m,0)\r\n    c=0\r\n    for i in range (len(x)):\r\n        r1=x[i][0]\r\n        r2=x[i][1]\r\n        z=w[r1][r2]\r\n        c+=z\r\n    if (R!=t-1):\r\n        print(f\"{c}\\n\")\r\n    else:\r\n        print(c)',1181),
