(1262,'for i in range (3):\r\n    altura = input()\r\n    a,b,c,d,e = altura.split()\r\n    a = float(a)\r\n    b = float(b)\r\n    c = float(c)\r\n    d = float(d)\r\n    e = float(e)\r\n    lista = [a,b,c,d,e]\r\n    coso = [a,b,c,d,e]\r\n    algo = [a,b,c,d,e]\r\n    coso.sort()\r\n    algo.sort()\r\n    algo.reverse()\r\n    if lista == algo:\r\n        print(\"Decreciente\")\r\n    elif lista == coso:\r\n        print(\"Creciente\")\r\n    else:\r\n        print(\"Ninguno\")',1262),
(1263,'for i in range (3):\r\n    altura = input()\r\n    a,b,c,d,e = altura.split()\r\n    a = float(a)\r\n    b = float(b)\r\n    c = float(c)\r\n    d = float(d)\r\n    e = float(e)\r\n    lista = [a,b,c,d,e]\r\n    coso = [a,b,c,d,e]\r\n    algo = [a,b,c,d,e]\r\n    coso.sort()\r\n    algo.sort()\r\n    algo.reverse()\r\n    if lista == algo and lista == coso:\r\n         print(\"Ninguno\")       \r\n    elif lista == algo:\r\n        print(\"Decreciente\")\r\n    elif lista == coso:\r\n        print(\"Creciente\")\r\n    else:\r\n         print(\"Ninguno\")',1263),
(1264,'# Solución en Python para \"Entrenando con Gepeto\"\r\n# Busca la sigla \"TCP\" en una sopa de letras NxN en tres direcciones:\r\n# horizontal hacia la derecha (→), vertical hacia abajo (↓) y diagonal ↘.\r\n\r\n\r\nN = int(input())\r\ngrid = [input().strip() for _ in range(N)]\r\ntarget = \"TCP\"\r\n\r\nfor i in range(N):\r\n    for j in range(N):\r\n        # Horizontal →\r\n        if j + 2 < N and grid[i][j:j+3] == target:\r\n            print(\"SI\")\r\n            exit()\r\n        # Vertical ↓\r\n        if i + 2 < N and grid[i][j] == \'T\' and grid[i+1][j] == \'C\' and grid[i+2][j] == \'P\':\r\n            print(\"SI\")\r\n            exit()\r\n        # Diagonal ↘\r\n        if i + 2 < N and j + 2 < N and grid[i][j] == \'T\' and grid[i+1][j+1] == \'C\' and grid[i+2][j+2] == \'P\':\r\n            print(\"SI\")\r\n            exit()\r\n\r\nprint(\"NO\")',1264),
(1265,'import sys\r\n\r\ndef main():\r\n    data = [line.rstrip(\"\\n\") for line in sys.stdin if line.strip() != \"\" or line == \"\\n\"]\r\n    if not data:\r\n        print(\"NO\")\r\n        return\r\n\r\n    N = int(data[0])\r\n    grid = []\r\n    # Aseguramos leer exactamente N filas de la sopa (ignorando líneas vacías intermedias)\r\n    i = 1\r\n    while len(grid) < N and i < len(data):\r\n        row = data[i].strip()\r\n        # Si por alguna razón la línea es más larga/corta, la normalizamos a N (problemas reales no deberían requerirlo)\r\n        if len(row) < N:\r\n            # Relleno defensivo (no debería ocurrir según el enunciado)\r\n            row = row + (\" \" * (N - len(row)))\r\n        elif len(row) > N:\r\n            row = row[:N]\r\n        grid.append(row)\r\n        i += 1\r\n\r\n    if len(grid) != N:\r\n        print(\"NO\")\r\n        return\r\n\r\n    target = \"TCP\"\r\n    L = 3  # longitud de \"TCP\"\r\n\r\n    # Recorremos cada celda y verificamos las tres direcciones válidas.\r\n    for r in range(N):\r\n        for c in range(N):\r\n            # → horizontal\r\n            if c + L <= N and grid[r][c:c+L] == target:\r\n                print(\"SI\")\r\n                return\r\n            # ↓ vertical\r\n            if r + L <= N and grid[r][c] == \'T\' and grid[r+1][c] == \'C\' and grid[r+2][c] == \'P\':\r\n                print(\"SI\")\r\n                return\r\n            # ↘ diagonal\r\n            if r + L <= N and c + L <= N:\r\n                if grid[r][c] == \'T\' and grid[r+1][c+1] == \'C\' and grid[r+2][c+2] == \'P\':\r\n                    print(\"SI\")\r\n                    return\r\n\r\n    print(\"NO\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1265),
(1266,'def contar_vocales(palabra):\r\n    vocales = \"aeiou\"\r\n    return sum(1 for c in palabra if c in vocales)\r\n\r\ndef main():\r\n    N = int(input())  # cantidad de idiomas\r\n    for _ in range(N):\r\n        M = int(input())  # cantidad de palabras en el idioma\r\n        total_vocales = 0\r\n        for _ in range(M):\r\n            palabra = input().strip().rstrip(\'.\')  # quitar punto final\r\n            total_vocales += contar_vocales(palabra)\r\n        promedio = total_vocales / M\r\n        print(f\"{promedio:.2f}\")\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1266),
(1267,'# Solución simple: lee múltiples casos hasta EOF y compara dos matrices A y B.\r\n# Imprime \"La pintura es original\" si las diferencias son <= 10%,\r\n# en caso contrario imprime \"La pintura no es original\".\r\n\r\nimport sys\r\n\r\ndatos = sys.stdin.read().split()\r\ni = 0\r\n\r\nwhile i < len(datos):\r\n    n = int(datos[i]); m = int(datos[i+1]); i += 2\r\n    total = n * m\r\n    diferentes = 0\r\n\r\n    # Leer A completa\r\n    A = []\r\n    for _ in range(n):\r\n        fila = []\r\n        for _ in range(m):\r\n            fila.append(int(datos[i])); i += 1\r\n        A.append(fila)\r\n\r\n    # Leer B y comparar contra A\r\n    for r in range(n):\r\n        for c in range(m):\r\n            b = int(datos[i]); i += 1\r\n            if A[r][c] != b:\r\n                diferentes += 1\r\n\r\n    # Decisión usando enteros para evitar flotantes\r\n    if diferentes * 100 > total * 10:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1267),
(1268,'simetria = True\r\ncolumna = []\r\nfilas = []\r\ncolumnas = []\r\na = int(input())\r\nfor i in range(a):\r\n    b = list(input().split())\r\n    filas.append(b)\r\nfor i in range(a):\r\n    for j in filas:\r\n        c = j[i]\r\n        columna.append(c)\r\n    columnas.append(columna)\r\n    columna = []\r\nfor i in range(a):\r\n    if columnas[i]!=filas[i]:\r\n        simetria = False\r\n        break\r\nif simetria == True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1268),
(1269,'def ruta_minima(n,w,s):\r\n    distancia=[float(\'inf\')]*n\r\n    visitado=[False]*n\r\n    distancia[s]=0 \r\n    for i in range(n): \r\n        u=-1\r\n        minimo=float(\'inf\')\r\n        for k in range(n):\r\n            if not visitado[k] and distancia[k]<minimo:\r\n                minimo = distancia[k]\r\n                u=k\r\n        if u==-1:\r\n            break\r\n        visitado[u]=True\r\n        for t,p in w[u]:\r\n            if distancia[t]>distancia[u]+p:\r\n                distancia[t]=distancia[u]+p\r\n    return distancia\r\n\r\nn,m=map(int,input().split())\r\nmatriz=[[] for i in range(n)]\r\n\r\nfor i in range(m):\r\n    a,b,c=map(int,input().split())\r\n    matriz[a].append((b,c))\r\n    matriz[b].append((a,c))\r\n\r\nE=ruta_minima(n,matriz,0)\r\nE.pop(0)\r\n\r\nprint(*E)',1269),
(1270,'#include <iostream>\r\n#include <string>\r\n#include <algorithm>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nvector<long long> dijkstra(int n, vector<vector<pair<int,int>>> &w,int s){\r\n    vector<long long> distancia(n,LLONG_MAX);\r\n    vector<bool> visitado(n,false);\r\n    distancia[s]=0;\r\n    for (int i = 0; i<n ; i++){\r\n        int u = -1;\r\n        long long minimo = LLONG_MAX;\r\n        for (int k = 0; k<n ; k++){\r\n            if (!visitado[k] && distancia[k]<minimo){\r\n                minimo = distancia[k];\r\n                u=k;\r\n            }\r\n        }\r\n        if (u==-1){\r\n            break;\r\n        }\r\n        visitado[u]=true;\r\n        for (auto edge : w[u]){\r\n            int t = edge.first;\r\n            int p = edge.second;\r\n            if (distancia[t]>distancia[u]+p){\r\n                distancia[t]=distancia[u]+p;\r\n            }\r\n        }\r\n    }\r\n    return distancia;\r\n}\r\n\r\n\r\nint main()\r\n{\r\n    int n,m;\r\n\r\n    cin >> n >> m;\r\n\r\n    vector<vector<pair<int,int>>> matriz(n);\r\n\r\n    for (int i = 0; i<m ; i++){\r\n        int a,b,c;\r\n        cin >> a >> b >> c;\r\n        matriz[a].push_back({b,c});\r\n        matriz[b].push_back({a,c});\r\n    }\r\n\r\n    vector<long long> E = dijkstra(n,matriz,0);\r\n    \r\n    for (int i = 1; i < n ; i++){\r\n        if (i!=n-1){\r\n            cout << E[i] << \" \";\r\n        } else {\r\n            cout << E[i] << endl;\r\n        }\r\n    }\r\n\r\n\r\n    cin.ignore();\r\n    cin.get();\r\n    return 0;\r\n}',1270),
(1271,'#include <iostream>\r\n#include <string>\r\n#include <algorithm>\r\n#include <vector>\r\n#include <climits>\r\n\r\nusing namespace std;\r\n\r\nvector<long long> dijkstra(int n, vector<vector<pair<int,int>>> &w,int s){\r\n    vector<long long> distancia(n,LLONG_MAX);\r\n    vector<bool> visitado(n,false);\r\n    distancia[s]=0;\r\n    for (int i = 0; i<n ; i++){\r\n        int u = -1;\r\n        long long minimo = LLONG_MAX;\r\n        for (int k = 0; k<n ; k++){\r\n            if (!visitado[k] && distancia[k]<minimo){\r\n                minimo = distancia[k];\r\n                u=k;\r\n            }\r\n        }\r\n        if (u==-1){\r\n            break;\r\n        }\r\n        visitado[u]=true;\r\n        for (auto edge : w[u]){\r\n            int t = edge.first;\r\n            int p = edge.second;\r\n            if (distancia[t]>distancia[u]+p){\r\n                distancia[t]=distancia[u]+p;\r\n            }\r\n        }\r\n    }\r\n    return distancia;\r\n}\r\n\r\n\r\nint main()\r\n{\r\n    int n,m;\r\n\r\n    cin >> n >> m;\r\n\r\n    vector<vector<pair<int,int>>> matriz(n);\r\n\r\n    for (int i = 0; i<m ; i++){\r\n        int a,b,c;\r\n        cin >> a >> b >> c;\r\n        matriz[a].push_back({b,c});\r\n        matriz[b].push_back({a,c});\r\n    }\r\n\r\n    vector<long long> E = dijkstra(n,matriz,0);\r\n    \r\n    for (int i = 1; i < n ; i++){\r\n        if (i!=n-1){\r\n            cout << E[i] << \" \";\r\n        } else {\r\n            cout << E[i] << endl;\r\n        }\r\n    }\r\n\r\n    return 0;\r\n}',1271),
(1272,'puntajes = []\r\nwhile True:\r\n    a, b, c = map(int, input().split())\r\n    if a == 0 and b == 0 and c == 0:\r\n        break\r\n    else:\r\n        puntaje = a + b + c\r\n        puntajes.append(puntaje)\r\n    ganador = max(puntajes)\r\nposicion_ganador = puntajes.index(ganador) + 1\r\nprint(posicion_ganador, ganador)',1272),
(1273,'Cantidad_casos = int(input())\r\ncalabazas = []\r\nfor _ in range(Cantidad_casos):\r\n    Casos = int(input())\r\n    a,b,c,d = map(int, input().split())\r\n    calabazas.extend([a, b, c, d])\r\n    calabazas = [x for x in calabazas if x <= Casos]\r\n    calabaza_max = max(calabazas)\r\n    print(calabaza_max)',1273),
(1274,'Cantidad_casos = int(input())\r\ncalabazas = []\r\nfor _ in range(Cantidad_casos):\r\n    Casos = int(input())\r\n    a,b,c,d = map(int, input().split())\r\n    calabazas.extend([a, b, c, d])\r\n    calabazas = [x for x in calabazas if x <= Casos]\r\n    calabaza_max = max(calabazas)\r\n    print(calabaza_max)\r\n    if calabazas == []:\r\n        print(\"0\")',1274),
(1275,'Cantidad_casos = int(input())\r\ncalabazas = []\r\nfor _ in range(Cantidad_casos):\r\n    Casos = int(input())\r\n    a,b,c,d = map(int, input().split())\r\n    calabazas.extend([a, b, c, d])\r\n    calabazas = [x for x in calabazas if x <= Casos]\r\n    if calabazas == []:\r\n        calabazas = [0]\r\n    calabaza_max = max(calabazas)\r\n    print(calabaza_max)',1275),
(1276,'Cantidad_casos = int(input())\r\ncalabazas = []\r\nfor _ in range(Cantidad_casos):\r\n    Casos = int(input())\r\n    a,b,c,d = map(int, input().split())\r\n    calabazas.extend([a, b, c, d])\r\n    calabazas = [x for x in calabazas if x <= Casos]\r\n    if calabazas == []:\r\n        calabazas = [0]\r\n    calabaza_max = max(calabazas)\r\n    print(calabaza_max)\r\n    calabazas.clear()',1276),
