(1287,'lista=[] \r\nwhile True:\r\n    p = input()\r\n    if p ==\"0\":\r\n        break\r\n    nota, nombre = p.split()\r\n    nota = int(nota)\r\n    lista2=[nota,nombre]\r\n    lista.append(lista2)\r\nlista.sort(key=lambda x : x[0])\r\nfor i in lista:\r\n    print(i[1])',1287),
(1288,'for i in range(3):\r\n    x = input()\r\n    a,b,c,d,e = x.split()\r\n    a = float(a)\r\n    b = float(b)\r\n    c = float(c)\r\n    d = float(d)\r\n    e = float(e)\r\n    lista = [a,b,c,d,e]\r\n    coso = lista.copy()\r\n    algo = lista.copy()\r\n    coso.sort()\r\n    algo.sort()\r\n    algo.reverse()\r\n    if lista == coso:\r\n        print(\"Creciente\")\r\n    elif lista == algo:\r\n        print(\"Decreciente\")\r\n    else:\r\n        print(\"Ninguno\")',1288),
(1289,'for i in range(3):\r\n    x = input()\r\n    a,b,c,d,e = x.split()\r\n    a = float(a)\r\n    b = float(b)\r\n    c = float(c)\r\n    d = float(d)\r\n    e = float(e)\r\n    lista = [a,b,c,d,e]\r\n    coso = lista.copy()\r\n    algo = lista.copy()\r\n    coso.sort()\r\n    algo.sort()\r\n    algo.reverse()\r\n    if a==b==c==d==e:\r\n        print(\"Ninguno\")\r\n    elif lista == coso:\r\n        print(\"Creciente\")\r\n    elif lista == algo:\r\n        print(\"Decreciente\")\r\n    else:\r\n        print(\"Ninguno\")',1289),
