(1293,'filas=[]\r\ncolunas=[]\r\ncoluna = []\r\ng = int(input())\r\nfor i in range(g):\r\n    k = list(input().split())\r\n    filas.append(k)\r\nfor i in range(g):\r\n    for j in filas:\r\n        elemento = j[i]\r\n        coluna.append(elemento)\r\n    colunas.append(coluna)\r\n    coluna=[]\r\nfor i in range(g):\r\n    if colunas[i]!=filas[i]:\r\n        print(\"NO\")\r\n        break\r\n    else:\r\n        print(\"SI\")\r\n        break',1293),
(1294,'vocxpal = 0\r\nidiomas = int(input())\r\nfor i in range(idiomas):\r\n    palabras = int(input())\r\n    for j in range(palabras):\r\n        palabra = input()\r\n        for h in palabra:\r\n            if h==\"a\" or h==\"e\" or h==\"i\" or h==\"o\" or h==\"u\":\r\n                vocxpal = vocxpal+1\r\n    promedio = vocxpal/palabras\r\n    vocxpal = 0\r\n    print(\"{:.2f}\".format(promedio))',1294),
(1295,'a=int(input())\r\nd=[]\r\ne=[]\r\nf=0\r\nfor n in range(a+2):\r\n    e.append(\'A\')\r\nfor n in range(a):\r\n    b=input()\r\n    b=b.replace(\'\',\' \')\r\n    c=b.split()\r\n    c.append(\'A\')\r\n    c.append(\'A\')\r\n    d.append(c)\r\nd.append(e)\r\nd.append(e)\r\nfor n in range(a):\r\n    for m in range(a):\r\n        if d[n][m]==\'T\':\r\n            if d[n+1][m]==\'C\':\r\n                if d[n+2][m]==\'P\':\r\n                    f+=1\r\n            if d[n][m+1]==\'C\':\r\n                if d[n][m+2]==\'P\':\r\n                    f+=1\r\n            if d[n+1][m+1]==\'C\':\r\n                if d[n+2][m+2]==\'P\':\r\n                    f+=1\r\nif f>0:\r\n    print(\'SI\')\r\nelse:\r\n    print(\'NO\')',1295),
(1296,'while True:\r\n    try:\r\n        Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().split()))\r\n            matriz1.append(entrada1)\r\n        print(matriz1)\r\n\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().split()))\r\n            matriz2.append(entrada2)\r\n        print(matriz2)\r\n\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\")\r\n        else:\r\n            print(\"La pintura no es original\")\r\n    except EOFError:\r\n        break',1296),
(1297,'Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    matriz1 = []\r\n    for i in range(Tamaño_matriz1):\r\n        entrada1 = list(map(int, input().split()))\r\n        matriz1.append(entrada1)\r\n    matriz2 = []\r\n    for _ in range(Tamaño_matriz2):\r\n        entrada2 = list(map(int, input().split()))\r\n        matriz2.append(entrada2)\r\n    if matriz1 == matriz2:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',1297),
