(1299,'while True:\r\n    try:\r\n        Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().split()))\r\n            matriz2.append(entrada2)\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\")\r\n        else:\r\n            print(\"La pintura no es original\")\r\n    except EOFError:\r\n        break',1299),
(1300,'while True:\r\n    try:\r\n        Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().split()))\r\n            matriz2.append(entrada2)\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\")\r\n        else:\r\n            print(\"La pintura no es original\")\r\n    except EOFError:\r\n        break',1300),
(1301,'# Solución modificada: la lectura de casos termina cuando se lee \"0 0\".\r\n# Compara dos matrices A y B y determina si la pintura es original o no.\r\n\r\nwhile True:\r\n    # Leer dimensiones\r\n    entrada = input().strip()\r\n    if not entrada:\r\n        continue\r\n    n, m = map(int, entrada.split())\r\n\r\n    # Condición de terminación\r\n    if n == 0 and m == 0:\r\n        break\r\n\r\n    total = n * m\r\n    diferentes = 0\r\n\r\n    # Leer matriz A\r\n    A = []\r\n    for _ in range(n):\r\n        fila = list(map(int, input().split()))\r\n        A.append(fila)\r\n\r\n    # Leer matriz B y comparar\r\n    for r in range(n):\r\n        filaB = list(map(int, input().split()))\r\n        for c in range(m):\r\n            if A[r][c] != filaB[c]:\r\n                diferentes += 1\r\n\r\n    # Evaluar diferencia\r\n    if diferentes * 100 > total * 10:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1301),
(1302,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    matriz1 = []\r\n    for i in range(Tamaño_matriz1):\r\n        entrada1 = list(map(int, input().split()))\r\n        matriz1.append(entrada1)\r\n    matriz2 = []\r\n    for _ in range(Tamaño_matriz2):\r\n        entrada2 = list(map(int, input().split()))\r\n        matriz2.append(entrada2)\r\n    if matriz1 == matriz2:\r\n        print(\"La pintura es original\") \r\n    else:\r\n        print(\"La pintura no es original\")',1302),
(1303,'contador=0\r\nvocales=[\"a\",\"e\",\"i\",\"o\",\"u\"]\r\nn=int(input())\r\nfor i in range(n):\r\n    m=int(input())\r\n    contador=0\r\n    for j in range(m):\r\n        palabra=input()\r\n        palabra=palabra[0:len(palabra)-1]\r\n        for vocal in vocales:\r\n            contador+=palabra.count(vocal)\r\n    print(\"{:.2f}\".format(contador/m))',1303),
(1304,'idiomas = int(input())\r\nfor i in range(idiomas):\r\n    palabras_por_idioma = int(input())\r\n    lista = []\r\n    vocales = 0\r\n    for _ in range(palabras_por_idioma):\r\n        palabra = input()\r\n        lista = list(palabra)\r\n        a = lista.count(\"a\")\r\n        e = lista.count(\"e\")\r\n        i = lista.count(\"i\")\r\n        o = lista.count(\"o\")\r\n        u = lista.count(\"u\")\r\n        vocales += (a+e+i+o+u)\r\n    promedio = vocales/palabras_por_idioma\r\n    print(f\"{promedio:.2f}\")',1304),
(1305,'x = int(input())\r\nfor i in range(x):\r\n    z = int(input())\r\n    vocales = 0\r\n    for i in range(z):\r\n        palabra = input()\r\n        palabra.count(\"a\")\r\n        palabra.count(\"e\")\r\n        palabra.count(\"i\")\r\n        palabra.count(\"o\")\r\n        palabra.count(\"u\")\r\n        suma = palabra.count(\"a\") +palabra.count(\"e\")+palabra.count(\"i\")+palabra.count(\"o\")+palabra.count(\"u\")\r\n        vocales = vocales+ suma\r\n    promedio = vocales/z\r\n    print(\"%.2f\" %promedio)',1305),
(1306,'f=int(input())\r\nfor o in range(f):\r\n   a=int(input())\r\n   d=0\r\n   e=0\r\n   for n in range(a):\r\n      b=input()\r\n      b=b.replace(\'\',\' \')\r\n      c=b.split()\r\n      for m in c:\r\n         if m==\'a\' or m==\'e\' or m==\'i\' or m==\'o\' or m==\'u\':\r\n            d+=1\r\n      e+=1\r\n   g=d/e\r\n   print(f\'{g:.2f}\')',1306),
(1307,'resolver = False\r\nfilas = []\r\nfila = []\r\nn = int(input())\r\nfor i in range(n):\r\n    a = input()\r\n    for j in a:\r\n        fila.append(j)\r\n    filas.append(fila)\r\n    fila =[]\r\nwhile resolver==False:\r\n    for y in range(n):\r\n        for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y][x+1]==\"C\" and filas[y][x+2]:\r\n                resolver =  True\r\n                break\r\n    for y in range(n-2):\r\n        for x in range(n):\r\n            if filas[y][x]==\"T\" and filas[y+1][x]==\"C\" and filas[y+2][x]:\r\n                resolver =  True\r\n                break\r\n    for y in range(n-2):\r\n         for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y+1][x+1]==\"C\" and filas[y+2][x+2]:\r\n                break\r\nif resolver==True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1307),
(1308,'original=\"La pintura es original\"\r\nwhile True:\r\n    n,m=list(map(int,input().split()))\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            if (abs(matriz1[c][d]-matriz2[c][d]))/255>0.1:\r\n                original=\"La pintura no es original\"\r\n    print(original)',1308),
(1309,'resolver = False\r\nfilas = []\r\nfila = []\r\nn = int(input())\r\nfor i in range(n):\r\n    a = input()\r\n    for j in a:\r\n        fila.append(j)\r\n    filas.append(fila)\r\n    fila =[]\r\nwhile resolver==False:\r\n    for y in range(n):\r\n        for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y][x+1]==\"C\" and filas[y][x+2]:\r\n                resolver =  True\r\n                break\r\n    for y in range(n-2):\r\n        for x in range(n):\r\n            if filas[y][x]==\"T\" and filas[y+1][x]==\"C\" and filas[y+2][x]:\r\n                resolver =  True\r\n                break\r\n    for y in range(n-2):\r\n         for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y+1][x+1]==\"C\" and filas[y+2][x+2]:\r\n                break\r\nif resolver==True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1309),
(1310,'original=\"La pintura es original\"\r\nwhile True:\r\n    n,m=list(map(int,input().split()))\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            if ((abs(matriz1[c][d]-matriz2[c][d]))/255)>0.1:\r\n                original=\"La pintura no es original\"\r\n    print(original)',1310),
(1311,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    matriz1 = []\r\n    for i in range(Tamaño_matriz1):\r\n        entrada1 = list(map(int, input().split()))\r\n        matriz1.append(entrada1)\r\n    matriz2 = []\r\n    for _ in range(Tamaño_matriz2):\r\n        entrada2 = list(map(int, input().split()))\r\n        matriz2.append(entrada2)\r\n    if matriz1 == matriz2:\r\n        print(\"La pintura es original\") \r\n    else:\r\n        print(\"La pintura no es original\")\r\n    matriz1.clear\r\n    matriz2.clear',1311),
(1312,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().split()))\r\n            matriz2.append(entrada2)\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1312),
(1313,'original=\"La pintura es original\"\r\ndiferencia=0\r\nwhile True:\r\n    n,m=list(map(int,input().split()))\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            diferencia+=((abs(matriz1[c][d]-matriz2[c][d]))/255)\r\n    if (diferencia/(n*m))>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1313),
(1314,'idiomas= int(input())\r\nfor i in range(idiomas): #cuantos idiomas\r\n    cuantas_palabras= int(input())\r\n    lista=[]\r\n    for j in range(cuantas_palabras): #cuantas palabras\r\n        contador=0\r\n        palabras= input()\r\n        lista.append(palabras)\r\n        palabras=\"\".join(lista)\r\n        for x in range(len(palabras)):\r\n            if palabras[x]==\"a\" or palabras[x]==\"e\" or palabras[x]==\"i\" or palabras[x]==\"o\" or palabras[x]==\"u\":\r\n                contador=contador+1\r\n    print(contador)\r\n    \r\n    promedio= (contador/(j+1))\r\n    print(contador)\r\n    print(\"%.2f\" % promedio)',1314),
(1315,'idiomas= int(input())\r\nfor i in range(idiomas): #cuantos idiomas\r\n    cuantas_palabras= int(input())\r\n    lista=[]\r\n    for j in range(cuantas_palabras): #cuantas palabras\r\n        contador=0\r\n        palabras= input()\r\n        lista.append(palabras)\r\n        palabras=\"\".join(lista)\r\n        for x in range(len(palabras)):\r\n            if palabras[x]==\"a\" or palabras[x]==\"e\" or palabras[x]==\"i\" or palabras[x]==\"o\" or palabras[x]==\"u\":\r\n                contador=contador+1\r\n    promedio= (contador/(j+1))\r\n    print(\"%.2f\" % promedio)',1315),
(1316,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==\'0\' and b==\'0\':\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<0.9:\r\n        print(\'La pintura es original\')\r\n    else:\r\n        print(\'La pintura no es original\')',1316),
