(1318,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<0.9:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1318),
(1319,'import sys\r\nimport os\r\nprint(\"directorio\", os.getcwd())\r\n\r\nsys.stdin = open(f\"Prueba3/P_3/entry.txt\", \"r\")\r\nsys.stdout = open(f\"Prueba3/P_3/output.txt\", \"w\")\r\n\r\n#############\r\n\r\nwhile True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(str, input().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(str, input().split()))\r\n            matriz2.append(entrada2)\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1319),
(1320,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(str, input().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(str, input().split()))\r\n            matriz2.append(entrada2)\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1320),
(1321,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<=0.9:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1321),
(1322,'while True:\r\n    try:\r\n        Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n        if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n            break\r\n        else:\r\n            matriz1 = []\r\n            for i in range(Tamaño_matriz1):\r\n                entrada1 = list(map(str, input().split()))\r\n                matriz1.append(entrada1)\r\n            matriz2 = []\r\n            for _ in range(Tamaño_matriz2):\r\n                entrada2 = list(map(str, input().split()))\r\n                matriz2.append(entrada2)\r\n            if matriz1 == matriz2:\r\n                print(\"La pintura es original\") \r\n            else:\r\n                print(\"La pintura no es original\")\r\n    except ValueError:\r\n        break',1322),
(1323,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().strip().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().strip().split()))\r\n            matriz2.append(entrada2)\r\n        if matriz1 == matriz2:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1323),
(1324,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<0.1:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1324),
(1325,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f>0.1:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1325),
(1326,'n=int(input())\r\nSigla=list(\"TCP\")\r\nexiste_sigla=\"NO\"\r\nmatriz=[[0]*n for i in range(n)]\r\nfor k in range(n):\r\n    letras=input()\r\n    matriz[k]=list(letras)\r\n\r\ndef horizontal(): #Busqueda en horizontal\r\n    for l in range(n): #fila\r\n        inicio=0\r\n        for m in range(0,n-2): #columnas\r\n            if matriz[l][inicio:m+3]==Sigla:\r\n                return \"SI\"\r\n            inicio+=1\r\n    return\r\n\r\ndef vertical():\r\n    for a in range(n): #columna\r\n        for r in range(0,n-2): #filas\r\n            frase=[]\r\n            frase.append(matriz[r][a])\r\n            frase.append(matriz[r+1][a])\r\n            frase.append(matriz[r+2][a])\r\n            if frase==Sigla:\r\n                return \"SI\"\r\n            frase=[]\r\n    return\r\n\r\ndef diagonal():\r\n    for b in range(n-2): #columna actual\r\n        for c in range(n-2): #fila actual\r\n            frase_diagonal=[]\r\n            frase_diagonal.append(matriz[c][b])\r\n            frase_diagonal.append(matriz[c+1][b+1])\r\n            frase_diagonal.append(matriz[c+2][b+2])\r\n            if frase_diagonal==Sigla:\r\n                return \"SI\"\r\n            frase_diagonal=[]\r\n    return\r\nif (existe_sigla:=horizontal())==\"SI\" or (existe_sigla:=vertical())==\"SI\" or (existe_sigla:=diagonal())==\"SI\":\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1326),
(1327,'resolver = False\r\nfilas = []\r\nfila = []\r\nn = int(input())\r\nfor i in range(n):\r\n    a = input()\r\n    for j in a:\r\n        fila.append(j)\r\n    filas.append(fila)\r\n    fila =[]\r\nwhile resolver==False:\r\n    for y in range(n):\r\n        for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y][x+1]==\"C\" and filas[y][x+2]==\"P\":\r\n                resolver =  True\r\n                break\r\n    for y in range(n-2):\r\n        for x in range(n):\r\n            if filas[y][x]==\"T\" and filas[y+1][x]==\"C\" and filas[y+2][x]==\"P\":\r\n                resolver =  True\r\n                break\r\n    for y in range(n-2):\r\n         for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y+1][x+1]==\"C\" and filas[y+2][x+2]==\"P\":\r\n                break\r\nif resolver==True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1327),
(1328,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<0.1:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1328),
