(1339,'original=\"La pintura es original\"\r\ndiferencia=0\r\nwhile True:\r\n    n,m=list(map(int,input().split()))\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            diferencia+=((abs(matriz1[c][d]-matriz2[c][d]))/255)\r\n    if diferencia>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1339),
(1340,'resolver = False\r\nfilas = []\r\nfila = []\r\nn = int(input())\r\nfor i in range(n):\r\n    a = input()\r\n    for j in a:\r\n        fila.append(j)\r\n    filas.append(fila)\r\n    fila =[]\r\nfor y in range(n):\r\n    for x in range(n-2):\r\n        if filas[y][x]==\"T\" and filas[y][x+1]==\"C\" and filas[y][x+2]==\"P\":\r\n            resolver =  True\r\n            break\r\nif resolver == False:\r\n    for y in range(n-2):\r\n        for x in range(n):\r\n            if filas[y][x]==\"T\" and filas[y+1][x]==\"C\" and filas[y+2][x]==\"P\":\r\n                resolver =  True\r\n                break\r\nif resolver == False:\r\n    for y in range(n-2):\r\n         for x in range(n-2):\r\n            if filas[y][x]==\"T\" and filas[y+1][x+1]==\"C\" and filas[y+2][x+2]==\"P\":\r\n                resolver = True\r\n                break\r\nif resolver==True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1340),
(1341,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<=0.1:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1341),
(1342,'original=\"La pintura es original\"\r\nwhile True:\r\n    n,m=list(map(int,input().split()))\r\n    diferencia=0\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            diferencia+=((abs(matriz1[c][d]-matriz2[c][d]))/255)\r\n    print(diferencia)\r\n    if diferencia>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1342),
(1343,'original=\"La pintura es original\"\r\nwhile True:\r\n    n,m=list(map(int,input().split()))\r\n    diferencia=0\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            diferencia+=((abs(matriz1[c][d]-matriz2[c][d]))/255)\r\n    if diferencia>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1343),
(1344,'x = int(input())\r\nx = x-2\r\ncontador_para_T = 0\r\ncontador_para_C = 0\r\ncontador_para_P = 0\r\nSI_O_NO = False\r\nfor i in range(x):\r\n    lista = []\r\n    letras = input()\r\n    lista = list(letras)\r\n    if \"T\" in lista:\r\n        contador_para_T = lista.index(\"T\")\r\n        contador_para_T_2 = contador_para_T+1\r\n        if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n            if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                SI_O_NO = True\r\n            else:\r\n                pass\r\n        if \"T\" in lista and (\"C\" not in lista or \"P\" not in lista):\r\n            letras = input()\r\n            lista = list(letras)\r\n            i = i+1\r\n            if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n                if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                    SI_O_NO = True\r\n                else:\r\n                    pass\r\n            if \"C\" in lista and (\"T\" not in lista or \"P\" not in lista):\r\n                    contador_para_C = lista.index(\"C\")\r\n                    if contador_para_C == contador_para_T:\r\n                        letras = input()\r\n                        i = i+1\r\n                        lista = list(letras)\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_C:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    elif contador_para_C == contador_para_T+1:\r\n                        letras == input()\r\n                        lista = list(letras)\r\n                        i = i+1\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_T+2:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    else:\r\n                        pass\r\n            else:\r\n                 pass\r\n    else:\r\n         pass\r\n    \r\n\r\nif SI_O_NO == True:\r\n    print(\"SI\")\r\nelif SI_O_NO == False:\r\n    print(\"NO\")',1344),
(1345,'x = int(input())\r\nif x >2:\r\n    x = x-2\r\nelse:\r\n    pass\r\ncontador_para_T = 0\r\ncontador_para_C = 0\r\ncontador_para_P = 0\r\nSI_O_NO = False\r\nfor i in range(x):\r\n    lista = []\r\n    letras = input()\r\n    lista = list(letras)\r\n    if \"T\" in lista:\r\n        contador_para_T = lista.index(\"T\")\r\n        contador_para_T_2 = contador_para_T+1\r\n        if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n            if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                SI_O_NO = True\r\n            else:\r\n                pass\r\n        if \"T\" in lista and (\"C\" not in lista or \"P\" not in lista):\r\n            letras = input()\r\n            lista = list(letras)\r\n            i = i+1\r\n            if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n                if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                    SI_O_NO = True\r\n                else:\r\n                    pass\r\n            if \"C\" in lista and (\"T\" not in lista or \"P\" not in lista):\r\n                    contador_para_C = lista.index(\"C\")\r\n                    if contador_para_C == contador_para_T:\r\n                        letras = input()\r\n                        i = i+1\r\n                        lista = list(letras)\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_C:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    elif contador_para_C == contador_para_T+1:\r\n                        letras == input()\r\n                        lista = list(letras)\r\n                        i = i+1\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_T+2:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    else:\r\n                        pass\r\n            else:\r\n                 pass\r\n    else:\r\n         pass\r\n    \r\n\r\nif SI_O_NO == True:\r\n    print(\"SI\")\r\nelif SI_O_NO == False:\r\n    print(\"NO\")',1345),
(1346,'casos=int(input())\r\ncontador=0\r\nfor i in range(casos):\r\n    n=int(input())#numero entero que dice la cantiad de idiomas\r\n    lista=[]\r\n    for y in range(n):\r\n      entrada=input()\r\n      filtro=[p for p in entrada if p ==\"a\" or p ==\"e\" or p ==\"i\" or p ==\"o\" or p ==\"u\"]  # ve palabra por palabra y toma la canridad de palabras que hay\r\n      vocales=len(filtro)\r\n      lista.append(vocales)\r\n      sumas=sum(lista)\r\n      promedio=sumas/n\r\n    print(\"%.2f\"%promedio)',1346),
(1347,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<=0.9:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')\r\n    print(f)',1347),
(1348,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f<=0.9:\r\n        print(\'La pintura no es original\')\r\n    else:\r\n        print(\'La pintura es original\')',1348),
(1349,'while True:\r\n    n,m=list(map(int,input().split()))\r\n    diferencia=0\r\n    original=\"La pintura es original\"\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            diferencia+=((abs(matriz1[c][d]-matriz2[c][d]))/255)\r\n    if (diferencia/(n*m))>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1349),
(1350,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f>0.9:\r\n        print(\'La pintura es original\')\r\n    else:\r\n        print(\'La pintura no es original\')',1350),
(1351,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f>=0.9:\r\n        print(\'La pintura es original\')\r\n    else:\r\n        print(\'La pintura no es original\')',1351),
(1352,'x = int(input())\r\ncontador_para_T = 0\r\ncontador_para_C = 0\r\ncontador_para_P = 0\r\nSI_O_NO = False\r\ncontador = 0\r\nwhile contador != x:\r\n    contador +=1\r\n    lista = []\r\n    letras = input()\r\n    lista = list(letras)\r\n    if \"T\" in lista:\r\n        contador_para_T = lista.index(\"T\")\r\n        contador_para_T_2 = contador_para_T+1\r\n        if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n            if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                SI_O_NO = True\r\n            else:\r\n                pass\r\n        if \"T\" in lista and (\"C\" not in lista or \"P\" not in lista):\r\n            letras = input()\r\n            contador +=1\r\n            lista = list(letras)\r\n            if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n                if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                    SI_O_NO = True\r\n                else:\r\n                    pass\r\n            if \"C\" in lista and (\"T\" not in lista or \"P\" not in lista):\r\n                    contador_para_C = lista.index(\"C\")\r\n                    if contador_para_C == contador_para_T:\r\n                        letras = input()\r\n                        contador +=1\r\n                        lista = list(letras)\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_C:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    elif contador_para_C == contador_para_T+1:\r\n                        letras == input()\r\n                        contador +=1\r\n                        lista = list(letras)\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_T+2:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    else:\r\n                        pass\r\n            else:\r\n                 pass\r\n    else:\r\n         pass\r\n\r\nif SI_O_NO == True:\r\n    print(\"SI\")\r\nelif SI_O_NO == False:\r\n    print(\"NO\")',1352),
(1353,'while True:\r\n    sublista = []\r\n    c = 0\r\n    filas1 = []\r\n    filas2 = []\r\n    n,m = map(int, input().split())\r\n    if n == 0:\r\n        break\r\n    min = (m*n)/1000\r\n    for j in range(n):\r\n        A = input()\r\n        for i in A:\r\n            sublista.append(i)\r\n        filas1.append(sublista)\r\n        sublista= []\r\n    for j in range(n):\r\n        B = input()\r\n        for i in B:\r\n            sublista.append(i)\r\n        filas2.append(sublista)\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if filas1[j][i] == filas2[j][i]:\r\n                c= c+1\r\n    if c/(m*n)<min:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1353),
(1354,'while True:\r\n    sublista = []\r\n    c = 0\r\n    filas1 = []\r\n    filas2 = []\r\n    n,m = map(int, input().split())\r\n    if n == 0:\r\n        break\r\n    min = (m*n)/1000\r\n    for j in range(n):\r\n        A = input()\r\n        for i in A:\r\n            sublista.append(i)\r\n        filas1.append(sublista)\r\n        sublista= []\r\n    for j in range(n):\r\n        B = input()\r\n        for i in B:\r\n            sublista.append(i)\r\n        filas2.append(sublista)\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if filas1[j][i] == filas2[j][i]:\r\n                c= c+1\r\n    if c/(m*n)<=min:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1354),
(1355,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        contador = 0\r\n        contador1 = 0\r\n        matriz1 = []\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().strip().split()))\r\n            matriz1.append(entrada1)\r\n        matriz2 = []\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().strip().split()))\r\n            matriz2.append(entrada2)\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz1):\r\n                if matriz1[i][j] == matriz2[i][j]:\r\n                    contador += 1\r\n                    break\r\n                elif matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n                    break\r\n        if (contador1/Tamaño_matriz1)*100 <= 90:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1355),
(1356,'entrada = input().strip()\r\n\r\nn, m = map(int, entrada.split())\r\nwhile n != 0 and m != 0:\r\n    matrizO = []\r\n    matrizN = []\r\n    for i in range(n):\r\n        fila = list(map(int, input().strip().split()))\r\n        # print(fila)\r\n        matrizO.append(fila)\r\n    for i in range(n):\r\n        fila = list(map(int, input().strip().split()))\r\n        matrizN.append(fila)\r\n\r\n    dif = 0\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if matrizO[i][j] != matrizN[i][j]:\r\n                dif += 1\r\n\r\n    if dif > n*m*0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")\r\n    entrada = input().strip()\r\n    n, m = map(int, entrada.split())',1356),
(1357,'x = int(input())\r\ncontador_para_T = 0\r\ncontador_para_C = 0\r\ncontador_para_P = 0\r\nSI_O_NO = False\r\ncontador = 0\r\nwhile contador != x:\r\n    contador +=1\r\n    lista = []\r\n    letras = input()\r\n    lista = list(letras)\r\n    if \"T\" in lista:\r\n        contador_para_T = lista.index(\"T\")\r\n        contador_para_T_2 = contador_para_T+1\r\n        if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n            if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                SI_O_NO = True\r\n            else:\r\n                pass\r\n        if \"T\" in lista:\r\n            letras = input()\r\n            contador +=1\r\n            lista = list(letras)\r\n            if (\"T\" in lista) and (\"C\" in lista) and (\"P\" in lista):\r\n                if lista.index(\"T\") == lista.index(\"C\")-1 == lista.index(\"P\")-2:\r\n                    SI_O_NO = True\r\n                else:\r\n                    pass\r\n            if \"C\" in lista:\r\n                    contador_para_C = lista.index(\"C\")\r\n                    if contador_para_C == contador_para_T:\r\n                        letras = input()\r\n                        contador +=1\r\n                        lista = list(letras)\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_C:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    elif contador_para_C == contador_para_T+1:\r\n                        letras == input()\r\n                        contador +=1\r\n                        lista = list(letras)\r\n                        if \"P\" in lista:\r\n                            contador_para_P = lista.index(\"P\")\r\n                            if contador_para_P == contador_para_T+2:\r\n                                SI_O_NO = True\r\n                            else:\r\n                                pass\r\n                        else:\r\n                            pass\r\n                    else:\r\n                        pass\r\n            else:\r\n                 pass\r\n    else:\r\n         pass\r\n\r\nif SI_O_NO == True:\r\n    print(\"SI\")\r\nelif SI_O_NO == False:\r\n    print(\"NO\")',1357),
(1358,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        x=x.replace(\'\',\' \')\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        v=v.replace(\'\',\' \')\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f>0.9:\r\n        print(\'La pintura es original\')\r\n    else:\r\n        print(\'La pintura no es original\')',1358),
(1359,'y = int(input())\r\naver = []\r\nfor i in range (y):\r\n    soup = []\r\n    for i in range (y):\r\n        z = input()\r\n        soup.append(z)\r\n    aver.append(soup)\r\nprint(aver)\r\nfor i in range (0,y):\r\n    if aver[0][i]==\"T\" and aver[0][i+1]==\"C\" and aver [0][i+2]==\"P\":\r\n        Boleano = True\r\n    elif aver [i][0]==\"T\" and aver[i+1][0]==\"C\" and aver [i+2][0]==\"P\":\r\n        print(\"SI\")\r\n        Boleano= True\r\n    elif aver [i][i]==\"T\" and aver[i+1][i+1]==\"C\" and aver[i+2][2+2]==\"P\":\r\n        print(\"SI\")\r\n        Boleano=True\r\nif Boleano == True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1359),
(1360,'while True:\r\n    n,m=list(map(int,input().split()))\r\n    diferencia=0\r\n    original=\"La pintura es original\"\r\n    matriz1=[]\r\n    matriz2=[]\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            diferencia+=((abs(matriz1[c][d]-matriz2[c][d]))/255)\r\n    if (diferencia/(n*m))>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1360),
(1361,'Boleano = False\r\ny = int(input())\r\naver = []\r\nfor i in range (y):\r\n    soup = []\r\n    for i in range (y):\r\n        z = input()\r\n        soup.append(z)\r\n    aver.append(soup)\r\nprint(aver)\r\nfor i in range (0,y):\r\n    if aver[0][i]==\"T\" and aver[0][i+1]==\"C\" and aver [0][i+2]==\"P\":\r\n        Boleano = True\r\n    elif aver [i][0]==\"T\" and aver[i+1][0]==\"C\" and aver [i+2][0]==\"P\":\r\n        print(\"SI\")\r\n        Boleano= True\r\n    elif aver [i][i]==\"T\" and aver[i+1][i+1]==\"C\" and aver[i+2][2+2]==\"P\":\r\n        print(\"SI\")\r\n        Boleano=True\r\nif Boleano == True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1361),
(1362,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        contador = 0\r\n        contador1 = 0\r\n        matriz1 = []\r\n        matriz2 = []\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().strip().split()))\r\n            matriz1.append(entrada1)\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().strip().split()))\r\n            matriz2.append(entrada2)\r\n        \"\"\"Calculadora de originalidad\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz1):\r\n                if matriz1[i][j] == matriz2[i][j]:\r\n                    contador += 1\r\n                    break\r\n                elif matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n                    break\r\n        if (contador1/Tamaño_matriz1)*100 < 90:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1362),
(1363,'while True:\r\n    try:\r\n        Boleano = False\r\n        y = int(input())\r\n        aver = []\r\n        for i in range (y):\r\n            soup = []\r\n            for i in range (y):\r\n                z = input()\r\n                soup.append(z)\r\n            aver.append(soup)\r\n        print(aver)\r\n        for i in range (0,y):\r\n            if aver[0][i]==\"T\" and aver[0][i+1]==\"C\" and aver [0][i+2]==\"P\":\r\n                Boleano = True\r\n            elif aver [i][0]==\"T\" and aver[i+1][0]==\"C\" and aver [i+2][0]==\"P\":\r\n                print(\"SI\")\r\n                Boleano= True\r\n            elif aver [i][i]==\"T\" and aver[i+1][i+1]==\"C\" and aver[i+2][2+2]==\"P\":\r\n                print(\"SI\")\r\n                Boleano=True\r\n        if Boleano == True:\r\n            print(\"SI\")\r\n        else:\r\n            print(\"NO\")\r\n    except EOFError:\r\n        break',1363),
(1364,'boleano=False\r\nentrada=int(input())\r\nmatriz=[[0 for j in range(entrada)]for i in range(entrada)]\r\nfor y in range(entrada):\r\n    n=list(input())\r\n    matriz[y]= n\r\narriba=0\r\nabajo=entrada-1\r\nderecha=0\r\nizquierda=entrada-1\r\nfor y in range(len(n)):\r\n    for x in range(entrada):\r\n        if matriz[arriba][derecha]==\"T\" and matriz[arriba-1][derecha] ==\"C\" and  matriz[arriba-2][derecha]:\r\n            boleano=True\r\n        elif matriz[arriba][derecha]==\"T\" and matriz[arriba][derecha+1] ==\"C\" and  matriz[arriba][derecha+2]:\r\n            boleano=True\r\n        else:\r\n            if derecha<=izquierda:\r\n                derecha+=1\r\n            elif arriba<=abajo:\r\n                arriba+=-1\r\nif boleano==True:\r\n    print(\"SI\")\r\nelif boleano==False:\r\n    print(\"NO\")',1364),
(1365,'while True:\r\n    try:\r\n        Boleano = False\r\n        y = int(input())\r\n        aver = []\r\n        for i in range (y):\r\n            soup = []\r\n            for i in range (y):\r\n                z = input()\r\n                soup.append(z)\r\n            aver.append(soup)\r\n        print(aver)\r\n        for i in range (0,y):\r\n            if aver[0][i]==\"T\" and aver[0][i+1]==\"C\" and aver [0][i+2]==\"P\":\r\n                Boleano = True\r\n            elif aver [i][0]==\"T\" and aver[i+1][0]==\"C\" and aver [i+2][0]==\"P\":\r\n                print(\"SI\")\r\n                Boleano= True\r\n            elif aver [i][i]==\"T\" and aver[i+1][i+1]==\"C\" and aver[i+2][2+2]==\"P\":\r\n                print(\"SI\")\r\n                Boleano=True\r\n            else:\r\n                Boleano=False\r\n        if Boleano == True:\r\n            print(\"SI\")\r\n        else:\r\n            print(\"NO\")\r\n    except EOFError:\r\n        break',1365),
(1366,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 != 0 and Tamaño_matriz2 != 0:\r\n        exit\r\n    else:\r\n        contador = 0\r\n        contador1 = 0\r\n        matriz1 = []\r\n        matriz2 = []\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().strip().split()))\r\n            matriz1.append(entrada1)\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().strip().split()))\r\n            matriz2.append(entrada2)\r\n        \"\"\"Calculadora de originalidad\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz1):\r\n                if matriz1[i][j] == matriz2[i][j]:\r\n                    contador += 1\r\n                    break\r\n                elif matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n                    break\r\n        if (contador1/Tamaño_matriz1)*100 < 90:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1366),
