(1373,'n=int(input())\r\nvocales = [\"a\",\"e\",\"i\",\"o\",\"u\"]\r\nfor _ in range (n):\r\n    k=int(input())\r\n    promedio=0\r\n    for i in range(k):\r\n        c=0\r\n        x=list(input())\r\n        for i in range(len(x)):\r\n            if x[i] in vocales:\r\n                c+=1\r\n        promedio+=c\r\n    promedio=promedio/k\r\n    print(f\"%.2f\" % promedio)',1373),
(1374,'while True:\r\n    n,m=map(int,input().split())\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[]\r\n    matriz2=[]\r\n    for i in range(n):\r\n        a=list(input().split())\r\n        matriz1.append(a)\r\n    for i in range(n):\r\n        a=list(input().split())\r\n        matriz2.append(a)\r\n    c=0\r\n    for i in range(n):\r\n        for k in range(m):\r\n            if matriz1[i][k]!=matriz2[i][k]:\r\n                c+=1\r\n    if (c/(n*m))<=0.1:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',1374),
(1375,'boleano=False\r\nn=int(input())\r\nmatriz=[]\r\nfor  i in range(n):\r\n    valor=list(input())\r\n    matriz.append(valor)\r\nfor y in range(n):\r\n    for x in range(n):\r\n        if x+2<n:\r\n         if matriz[y][x] == \"T\" and matriz[y][x+1] == \"C\" and matriz[y][x+2] == \"P\":\r\n            boleano=True\r\n            break\r\n        elif y+2<n:\r\n           if matriz[y][x]==\"T\" and matriz[y][x+1] ==\"C\" and  matriz[y][x+2] ==\"P\":\r\n            boleano=True\r\n            break\r\n        if boleano:\r\n           break\r\nif boleano==True:\r\n   print(\"SI\")',1375),
(1376,'n, N, k= map(int,input().split())\r\nif n + N < k:  \r\n    print(\"NO\")\r\nelif n + N >= k:   \r\n    print(\"SI\")\r\nelse:  \r\n    print(\"NO\")',1376),
(1377,'n, N, k= map(int,input().split())\r\nif n + N <= k:  \r\n    print(\"NO\")\r\nelif n + N >= k:   \r\n    print(\"SI\")\r\nelse:  \r\n    print(\"NO\")',1377),
(1378,'from collections import deque\r\n\r\ndef busqueda_en_anchura(n,m,w,x,y,movimientos): ## (x,y) coordenada del inicio\r\n    distancias = [[-1] * m for _ in range(n)] ## matriz de distancias\r\n    cola = deque([(x,y,0)])\r\n    distancias[x][y] = 0\r\n    visitado = set([(x,y)])\r\n\r\n    if w[x][y] ==1:\r\n        return [[-1]*m for _ in range(n)] # no se puede ir a ningún lado\r\n    \r\n    while cola:\r\n        r, c, dist = cola.popleft()\r\n        for dr,dc in movimientos:\r\n            nr, nc= r+dr, c+dc\r\n            ndist = dist + 1\r\n            es_valida=False\r\n            if 0<=nr<n and 0<=nc<m:\r\n                es_valida=True\r\n            if es_valida:\r\n                no_es_obstaculo = w[nr][nc] == 0\r\n                no_ha_sido_visitada = (nr, nc) not in visitado\r\n                if w[nr][nc]==0 and (nr, nc) not in visitado:\r\n                    visitado.add((nr,nc))\r\n                    distancias[nr][nc] = ndist\r\n                    cola.append((nr,nc,ndist))\r\n\r\n    return distancias\r\n\r\nMovimientos = [(-2,1),(-2,-1),(1,-2),(1,2),(-1,2),(-1,-2),(2,-1),(2,1)]\r\n\r\nn,m=map(int,input().split())\r\nw=[[0]*m for _ in range(n)]\r\na,b=map(int,input().split())\r\np,q=map(int,input().split())\r\ny,z=map(int,input().split())\r\n\r\nk = int(input())\r\n\r\nfor i in range(k):\r\n    j,h=map(int,input().split())\r\n    w[j][h] = 1\r\n\r\ndistancias_blanco=busqueda_en_anchura(n,m,w,a,b,Movimientos)\r\n\r\ndistancias_negro=busqueda_en_anchura(n,m,w,p,q,Movimientos)\r\n\r\nif distancias_blanco[y][z] == -1 and distancias_negro[y][z] == -1:\r\n    print(\"Empate\")\r\nelif distancias_blanco[y][z] == -1:\r\n    print(\"Negro\")\r\nelif distancias_negro[y][z] == -1:\r\n    print(\"Blanco\")\r\nelif distancias_negro[y][z] < distancias_blanco[y][z]:\r\n    print(\"Negro\")\r\nelif distancias_negro[y][z] == distancias_blanco[y][z]:\r\n    print(\"Empate\")\r\nelse:\r\n    print(\"Blanco\")',1378),
(1379,'while True:\r\n    a,b=map(int,input().split())\r\n    if a==0 or b==0:\r\n        break\r\n    c=[]\r\n    d=[]\r\n    e=0\r\n    for n in range(a):\r\n        x=input()\r\n        y=x.split()\r\n        c.append(y)\r\n    for n in range(a):\r\n        v=input()\r\n        w=v.split()\r\n        d.append(w)\r\n    for o in range(a):\r\n        for p in range(b):\r\n            if c[o][p]==d[o][p]:\r\n                e+=1\r\n    f=e/(a*b)\r\n    if f>0.9:\r\n        print(\'La pintura es original\')\r\n    else:\r\n        print(\'La pintura no es original\')',1379),
(1380,'from collections import deque\r\n\r\ndef busqueda_en_anchura(n,m,w,x,y,movimientos): ## (x,y) coordenada del inicio\r\n    distancias = [[-1] * m for _ in range(n)] ## matriz de distancias\r\n    cola = deque([(x,y,0)])\r\n    distancias[x][y] = 0\r\n    visitado = set([(x,y)])\r\n\r\n    if w[x][y] ==1:\r\n        return [[-1]*m for _ in range(n)] # no se puede ir a ningún lado\r\n    \r\n    while cola:\r\n        r, c, dist = cola.popleft()\r\n        for dr,dc in movimientos:\r\n            nr, nc= r+dr, c+dc\r\n            ndist = dist + 1\r\n            es_valida=False\r\n            if 0<=nr<n and 0<=nc<m:\r\n                es_valida=True\r\n            if es_valida:\r\n                no_es_obstaculo = w[nr][nc] == 0\r\n                no_ha_sido_visitada = (nr, nc) not in visitado\r\n                if w[nr][nc]==0 and (nr, nc) not in visitado:\r\n                    visitado.add((nr,nc))\r\n                    distancias[nr][nc] = ndist\r\n                    cola.append((nr,nc,ndist))\r\n\r\n    return distancias\r\n\r\nmovimientos=[(1,0),(0,1),(-1,0),(0,-1)]\r\n\r\nn,m=map(int,input().split())\r\na,b=map(int,input().split())\r\np,q=map(int,input().split())\r\nw=[]\r\nfor i in range(n):\r\n    z=list(map(int,input().split()))\r\n    w.append(z)\r\n\r\nE=busqueda_en_anchura(n,m,w,a,b,movimientos)\r\n\r\nfinal=E[p][q]\r\nprint(final)',1380),
