(1391,'z=[]\r\ny=[]\r\nwhile True:\r\n    a=input()\r\n    if a==\'0\':\r\n        break\r\n    b,c=a.split()\r\n    int(b)\r\n    y.append(int(b))\r\n    z.append(c)\r\ny.append(1000)\r\nfor m in range(len(y)-1):\r\n    for n in range(len(y)-1):\r\n        if y[n+1]<=y[n]:\r\n            v=y[n+1]\r\n            w=y[n]\r\n            y[n+1]=w\r\n            y[n]=v\r\n            v=z[n+1]\r\n            w=z[n]\r\n            z[n+1]=w\r\n            z[n]=v\r\nfor p in z:\r\n    print(p)',1391),
(1392,'while True:\r\n    n,m=list(map(int,input().split()))\r\n    diferencia=0\r\n    original=\"La pintura es original\"\r\n    if n==0 and m==0:\r\n        break\r\n    matriz1=[[0]*m for i in range(n)]\r\n    matriz2=[[0]*m for k in range(n)]\r\n    for a in range(n): #para cada fila\r\n        matriz1[a]=list(map(int,input().split()))\r\n    for b in range(n):\r\n        matriz2[b]=list(map(int,input().split()))\r\n    \r\n    for c in range(n):\r\n        for d in range(m):\r\n            if matriz1[c][d]!=matriz2[c][d]:\r\n                diferencia+=1\r\n    if (diferencia/(n*m))>0.1:\r\n        original=\"La pintura no es original\"\r\n    print(original)',1392),
(1393,'import copy\r\n\r\ndef ruta_minima(n,w,s):\r\n    distancia=[float(\'inf\')]*n\r\n    visitado=[False]*n\r\n    distancia[s]=0\r\n    padres=[-1 for _ in range(n)]\r\n    for i in range(n): \r\n        u=-1\r\n        minimo=float(\'inf\')\r\n        for k in range(n):\r\n            if not visitado[k] and distancia[k]<minimo:\r\n                minimo = distancia[k]\r\n                u=k\r\n        if u==-1:\r\n            break\r\n        visitado[u]=True\r\n        for t,p in w[u]:\r\n            if distancia[t]>distancia[u]+p:\r\n                padres[t]=u\r\n                distancia[t]=distancia[u]+p\r\n    return distancia, padres\r\n\r\nn,m=map(int,input().split())\r\nady = [[] for _  in range (n)]\r\nfor i in range(m):\r\n    a,b,c=map(int,input().split())\r\n    ady[a].append((b,c))\r\n    ady[b].append((a,c))\r\n\r\ndistancia,padres=ruta_minima(n,ady,0)\r\n\r\n## crear la ruta óptima para cada una, 1,2,3,4,5\r\nlista_rutas=[[] for _ in range(n)]\r\nfor i in range(1,n):\r\n    r=i\r\n    lista_rutas[i].append(r)\r\n    while True:\r\n        x=padres[r]\r\n        if x==-1:\r\n            break\r\n        lista_rutas[i].append(x)\r\n        r=x\r\n\r\n## haga un nuevo prim y verifique\r\n## si hay una nueva ruta al nodo i del mismo peso que la que aparece en distancia[i]\r\nfor i in range(1,n):\r\n    ady_c = copy.deepcopy(ady)\r\n\r\n    ## ahora crear un programa que me todas las conexiones de la ruta minima para i\r\n    for k in range(len(lista_rutas[i])-1):\r\n        ## quitar la ruta (lista_rutas[i][k],lista_rutas[i][k+1]) de ady_c\r\n        for a,b in ady[lista_rutas[i][k]]: ## a es la conex, b es el peso\r\n            if a==lista_rutas[i][k+1]:\r\n                ady_c[lista_rutas[i][k]].remove((lista_rutas[i][k+1],b))\r\n        for a,b in ady[lista_rutas[i][k+1]]: ## a es la conex, b es el peso\r\n            if a==lista_rutas[i][k]:\r\n                ady_c[lista_rutas[i][k+1]].remove((lista_rutas[i][k],b))\r\n    ## \r\n    distancia_copy,padres_copy=ruta_minima(n,ady_c,0)\r\n    if distancia_copy[i]==distancia[i]:\r\n        print(f\"El camino a optimo a {i} es de largo {distancia[i]} y es robusto\")\r\n    else:\r\n        print(f\"El camino a optimo a {i} es de largo {distancia[i]} y no es robusto\")',1393),
(1394,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        contador = 0\r\n        contador1 = 0\r\n        matriz1 = []\r\n        matriz2 = []\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for _ in range(Tamaño_matriz1):\r\n            entrada1 = list(map(int, input().strip().split()))\r\n            matriz1.append(entrada1)\r\n        \"\"\"Creador de Matriz 2\"\"\"\r\n        for _ in range(Tamaño_matriz2):\r\n            entrada2 = list(map(int, input().strip().split()))\r\n            matriz2.append(entrada2)\r\n        \"\"\"Calculadora de originalidad\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz1):\r\n                if matriz1[i][j] == matriz2[i][j]:\r\n                    contador += 1\r\n                    break\r\n                elif matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n                    break\r\n        if (contador1/Tamaño_matriz1)*100 < 90:\r\n            print(\"La pintura es original\") \r\n        else:\r\n            print(\"La pintura no es original\")',1394),
