(1406,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        contador1 = 0\r\n        matriz1 = []\r\n        matriz2 = []\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for _ in range(Tamaño_matriz1):\r\n            matriz1.append(list(map(int, input().strip().split())))\r\n        \"\"\"Creador de Matriz 2\"\"\"\r\n        for _ in range(Tamaño_matriz2):\r\n            matriz2.append(list(map(int, input().strip().split())))\r\n        \"\"\"Calculadora de originalidad\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz1):\r\n                if matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n        if (contador1/(Tamaño_matriz1*Tamaño_matriz2)) >= 0.1:\r\n            print(\"La pintura no es original\")\r\n        else:\r\n            print(\"La pintura es original\")',1406),
(1407,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        contador1 = 0\r\n        matriz1 = []\r\n        matriz2 = []\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for _ in range(Tamaño_matriz1):\r\n            matriz1.append(list(map(int, input().strip().split())))\r\n        \"\"\"Creador de Matriz 2\"\"\"\r\n        for _ in range(Tamaño_matriz2):\r\n            matriz2.append(list(map(int, input().strip().split())))\r\n        \"\"\"Calculadora de originalidad\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz1):\r\n                if matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n        if (contador1/(Tamaño_matriz1*Tamaño_matriz2)) > 0.1:\r\n            print(\"La pintura no es original\")\r\n        else:\r\n            print(\"La pintura es original\")',1407),
(1408,'def prim (n,w,s):\r\n    distancia=[float(\'inf\')]*n\r\n    visitado=[False]*n\r\n    distancia[s]=0\r\n    for i in range(n): \r\n        u=-1\r\n        minimo=float(\'inf\')\r\n        for k in range(n):\r\n            if not visitado[k] and distancia[k]<minimo:\r\n                minimo = distancia[k]\r\n                u=k\r\n        if u==-1:\r\n            break\r\n        visitado[u]=True\r\n        for t,p in w[u]:\r\n            if distancia[t]>distancia[u]+p:\r\n                distancia[t]=distancia[u]+p\r\n    return distancia\r\n\r\nn,m=map(int,input().split())\r\ncoordenadas=[]\r\nfor i in range(n):\r\n    x,y=list(map(int,input().split()))\r\n    coordenadas.append((x,y))\r\n\r\n\r\nady=[[] for _ in range(n)]\r\n\r\nfor i in range(m):\r\n    a,b=map(int,input().split())\r\n    x1,y1=coordenadas[a][0], coordenadas[a][1]\r\n    x2,y2=coordenadas[b][0], coordenadas[b][1]\r\n    distancia=((x2-x1)**2+(y2-y1)**2)**(1/2)\r\n    ady[a].append((b,distancia))\r\n    ady[b].append((a,distancia))\r\n\r\nx=prim(n,ady,0)\r\nfinal=\"\"\r\nfor i in range(1,len(x)):\r\n    if i!=len(x)-1:\r\n        final=final+f\"{\"%.4f\" % x[i]}\"+\" \"\r\n    else:\r\n        final+=f\"{\"%.4f\" % x[i]}\"\r\nprint(final)',1408),
(1409,'def prim (n,w,s):\r\n    distancia=[float(\'inf\')]*n\r\n    visitado=[False]*n\r\n    distancia[s]=0\r\n    for i in range(n): \r\n        u=-1\r\n        minimo=float(\'inf\')\r\n        for k in range(n):\r\n            if not visitado[k] and distancia[k]<minimo:\r\n                minimo = distancia[k]\r\n                u=k\r\n        if u==-1:\r\n            break\r\n        visitado[u]=True\r\n        for t,p in w[u]:\r\n            if distancia[t]>distancia[u]+p:\r\n                distancia[t]=distancia[u]+p\r\n    return distancia\r\n\r\nn,m=map(int,input().split())\r\ncoordenadas=[]\r\nfor i in range(n):\r\n    x,y=list(map(int,input().split()))\r\n    coordenadas.append((x,y))\r\n\r\n\r\nady=[[] for _ in range(n)]\r\n\r\nfor i in range(m):\r\n    a,b=map(int,input().split())\r\n    x1,y1=coordenadas[a][0], coordenadas[a][1]\r\n    x2,y2=coordenadas[b][0], coordenadas[b][1]\r\n    distancia=((x2-x1)**2+(y2-y1)**2)**(1/2)\r\n    ady[a].append((b,distancia))\r\n    ady[b].append((a,distancia))\r\n\r\nx=prim(n,ady,0)\r\nfinal=\"\"\r\nfor i in range(1,len(x)):\r\n    if i!=len(x)-1:\r\n        final=final+\"%.4f\" % x[i]+\" \"\r\n    else:\r\n        final+=\"%.4f\" % x[i]\r\nprint(final)',1409),
(1410,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    else:\r\n        contador1 = 0\r\n        matriz1 = []\r\n        matriz2 = []\r\n        \"\"\"Creador de Matriz 1\"\"\"\r\n        for _ in range(Tamaño_matriz1):\r\n            matriz1.append(list(map(int, input().strip().split())))\r\n        \"\"\"Creador de Matriz 2\"\"\"\r\n        for _ in range(Tamaño_matriz2):\r\n            matriz2.append(list(map(int, input().strip().split())))\r\n        \"\"\"Calculadora de originalidad\"\"\"\r\n        for i in range(Tamaño_matriz1):\r\n            for j in range(Tamaño_matriz2):\r\n                if matriz1[i][j] != matriz2[i][j]:\r\n                    contador1 += 1\r\n        if (contador1/(Tamaño_matriz1*Tamaño_matriz2)) > 0.1:\r\n            print(\"La pintura no es original\")\r\n        else:\r\n            print(\"La pintura es original\")',1410),
(1411,'while True:\r\n    n, m = map(int, input().split())\r\n    if n == 0 and m == 0:\r\n        break\r\n\r\n    # Creador de matrices\r\n    matrizA = []\r\n    matrizB = []\r\n\r\n    # Lector de matriz A\r\n    for _ in range(n):\r\n        matrizA.append(list(map(int, input().split())))\r\n\r\n    # Lector de matriz B\r\n    for _ in range(n):\r\n        matrizB.append(list(map(int, input().split())))\r\n\r\n    # Contador de píxeles diferentes\r\n    diferentes = 0\r\n    total_pixeles = n * m\r\n\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if matrizA[i][j] != matrizB[i][j]:\r\n                diferentes += 1\r\n\r\n    # Calculador de porcentaje de diferencia\r\n    porcentaje_diferencia = diferentes / total_pixeles\r\n\r\n    if porcentaje_diferencia > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1411),
(1412,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    contador1 = 0\r\n    matriz1 = []\r\n    matriz2 = []\r\n    \"\"\"Creador de Matriz 1\"\"\"\r\n    for _ in range(Tamaño_matriz1):\r\n        matriz1.append(list(map(int, input().strip().split())))\r\n    \"\"\"Creador de Matriz 2\"\"\"\r\n    for _ in range(Tamaño_matriz2):\r\n        matriz2.append(list(map(int, input().strip().split())))\r\n    \"\"\"Calculadora de originalidad\"\"\"\r\n    for i in range(Tamaño_matriz1):\r\n        for j in range(Tamaño_matriz2):\r\n            if matriz1[i][j] != matriz2[i][j]:\r\n                contador1 += 1\r\n    if (contador1/(Tamaño_matriz1*Tamaño_matriz2)) > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1412),
(1413,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n    contador1 = 0\r\n    matriz1 = []\r\n    matriz2 = []\r\n    pixeles = (Tamaño_matriz1*Tamaño_matriz2)\r\n    \"\"\"Creador de Matriz 1\"\"\"\r\n    for _ in range(Tamaño_matriz1):\r\n        matriz1.append(list(map(int, input()..split())))\r\n    \"\"\"Creador de Matriz 2\"\"\"\r\n    for _ in range(Tamaño_matriz2):\r\n        matriz2.append(list(map(int, input()..split())))\r\n    \"\"\"Calculadora de originalidad\"\"\"\r\n    for i in range(Tamaño_matriz1):\r\n        for j in range(Tamaño_matriz2):\r\n            if matriz1[i][j] != matriz2[i][j]:\r\n                contador1 += 1\r\n    if (contador1/diferencia) > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1413),
