(1416,'while True:\r\n    Tamaño_matriz1, Tamaño_matriz2 = map(int, input().split())\r\n    if Tamaño_matriz1 == 0 and Tamaño_matriz2 == 0:\r\n        break\r\n\r\n    matriz1 = []\r\n    matriz2 = []\r\n\r\n    \"\"\"Creador de Matriz 1\"\"\"\r\n    for _ in range(Tamaño_matriz1):\r\n        matriz1.append(list(map(int, input().split())))\r\n        \r\n    \"\"\"Creador de Matriz 2\"\"\"\r\n    for _ in range(Tamaño_matriz1):\r\n        matriz2.append(list(map(int, input().split())))\r\n        \r\n    contador1 = 0\r\n    pixeles = (Tamaño_matriz1*Tamaño_matriz2)\r\n    \r\n    \"\"\"Calculadora de originalidad\"\"\"\r\n    for i in range(Tamaño_matriz1):\r\n        for j in range(Tamaño_matriz2):\r\n            if matriz1[i][j] != matriz2[i][j]:\r\n                contador1 += 1\r\n                \r\n    if (contador1/pixeles) > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1416),
(1417,'n = int(input())\r\nmatriz = []\r\nTCP_encontrado = False\r\nfor _ in range(n):\r\n    fila = list(map(int, input().split()))\r\n    matriz.append(fila)\r\nfor i in range(n):\r\n    for j in range(n):\r\n        if \"TCP\" in matriz[i][j]:\r\n            TCP_encontrado = True\r\n            break\r\nif TCP_encontrado:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1417),
(1418,'n = int(input())\r\nmatriz = []\r\nTCP_encontrado = False\r\nfor _ in range(n):\r\n    fila = list(input().split())\r\n    matriz.append(fila)\r\nfor i in range(n):\r\n    for j in range(n):\r\n        if \"TCP\" in matriz[i][j]:\r\n            TCP_encontrado = True\r\n            break\r\nif TCP_encontrado:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1418),
(1419,'N = int(input().strip())\r\nM = []\r\nt = \"TCP\"\r\nencontrado = False\r\n\r\nfor _ in range(N):\r\n    fila = input().strip()\r\n    M.append(fila)\r\n\r\nfor fila in M:\r\n    if t in fila:\r\n        encontrado = True\r\n        break\r\n\r\nif not encontrado:\r\n    for j in range(N):\r\n        columna = \"\"\r\n        for i in range(N):\r\n            columna += M[i][j]\r\n        if t in columna:\r\n            encontrado = True\r\n            break\r\n\r\nif not encontrado:\r\n    for i in range(N - 2):\r\n        for j in range(N - 2):\r\n            diagonal = M[i][j] + M[i + 1][j + 1] + M[i + 2][j + 2]\r\n            if diagonal == t:\r\n                encontrado = True\r\n                break\r\n        if encontrado:\r\n            break\r\n\r\nif encontrado:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1419),
(1420,'N = int(input().strip())\r\nvocales = {\'a\', \'e\', \'i\', \'o\', \'u\'}\r\n\r\nfor _ in range(N):\r\n    total_vocales = 0\r\n    M = int(input().strip())\r\n    for _ in range(M):\r\n        palabra = input().strip().rstrip(\'.\')\r\n        for letra in palabra:\r\n            if letra in vocales:\r\n                total_vocales += 1\r\n    promedio = total_vocales / M\r\n    print(f\"{promedio:.2f}\")',1420),
(1421,'n = int(input())\r\n\r\nequipos= []\r\nvecinos= []\r\n\r\nfor i in range(n):\r\n    x=input().split()\r\n    letra = x.pop(0)\r\n    l = x.pop(0)\r\n    x=list(map(int,x))\r\n    vecinos.append(x)\r\n    equipos.append(letra)\r\nXP=False\r\nfor i in range(n):\r\n    c_enemigos = 0\r\n    v=vecinos[i]\r\n    e=equipos[i]\r\n    XX=0\r\n    for k in v:\r\n        if equipos[k-1]!=e:\r\n            c_enemigos +=1\r\n            XX+=1\r\n    if c_enemigos/len(v)>0.5 and not XP:\r\n        print(end=f\"{i+1}\")\r\n        XP=True\r\n    elif c_enemigos/len(v)>0.5:\r\n        print(end=\" \"+f\"{i+1}\")',1421),
(1422,'boleano=False\r\nn=int(input())\r\nmatriz=[]\r\nfor  i in range(n):\r\n    valor=list(input())\r\n    matriz.append(valor)\r\nfor y in range(n):\r\n    for x in range(n):\r\n       if x+2<n:\r\n        if matriz[y][x] == \"T\" and matriz[y][x+1] == \"C\" and matriz[y][x+2] == \"P\":\r\n            boleano=True\r\n            break\r\n       if y+2<n:\r\n        if matriz[y][x]==\"T\" and matriz[y+1][x] ==\"C\" and  matriz[y+2][x] ==\"P\":\r\n            boleano=True\r\n            break\r\n       if  x+2<n and y+2<n:\r\n        if matriz[y][x]==\"T\" and matriz[y+1][x+1] ==\"C\" and  matriz[y+2][x+2] ==\"P\":\r\n              boleano=True\r\n              break  \r\n        if boleano:\r\n           break\r\nif boleano==True:\r\n   print(\"SI\")\r\nelse:\r\n   print(\"No\")',1422),
