(1426,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    int n;\r\n    cin >> n;\r\n    for (int i = 0 ; i < n ; i++){\r\n        int k;\r\n        cin >> k;\r\n        for (int a = 0; a < 10 ; a++){\r\n            for (int b = 0; b < 10 ; b++){\r\n                for (int c = 0; c < 10 ; c++){\r\n                    for (int d = 0; d < 10 ; d++){\r\n                        if (a+b+c+d==k){\r\n                            cout << a << b << c << d << \" es una clave de la suerte que suma \" << k << endl;\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n        }\r\n    }\r\n    return 0;\r\n}',1426),
(1427,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nvoid dfs_grafos(int s, vector<vector<int>> &ady, vector<int> &visitado, vector<int> &cx){\r\n    visitado[s] = true;\r\n    cx.push_back(s);\r\n    for (int vecino : ady[s]){\r\n        if (!visitado[vecino]){\r\n            dfs_grafos(vecino,ady,visitado,cx);\r\n        }\r\n    }\r\n}\r\n\r\n\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<int>> ady(n);\r\n\r\n    for (int i = 0; i < m ; i++){\r\n        int x,y;\r\n        cin >> x >> y;\r\n        ady[x].push_back(y);\r\n        ady[y].push_back(x);\r\n    }\r\n\r\n    vector<int> visitado(n,false);\r\n    vector<vector<int>> cxs;\r\n\r\n    for (int i = 0; i<n ; i++){\r\n        if (!visitado[i]){\r\n            vector <int> cx;\r\n            dfs_grafos(i,ady,visitado,cx);\r\n            cxs.push_back(cx);\r\n        }\r\n    }\r\n\r\n    cout << cxs.size()-1 << endl;\r\n    return 0;\r\n}',1427),
(1428,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nvoid dfs_grafos(int s, vector<vector<int>> &ady, vector<int> &visitado, vector<int> &cx){\r\n    visitado[s] = true;\r\n    cx.push_back(s);\r\n    for (int vecino : ady[s]){\r\n        if (!visitado[vecino]){\r\n            dfs_grafos(vecino,ady,visitado,cx);\r\n        }\r\n    }\r\n}\r\n\r\n\r\n\r\nint main()\r\n{    \r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<int>> ady(n);\r\n\r\n    for (int i = 0; i < m ; i++){\r\n        int x,y;\r\n        cin >> x >> y;\r\n        ady[x].push_back(y);\r\n        ady[y].push_back(x);\r\n    }\r\n\r\n    vector<int> visitado(n,false);\r\n    vector<vector<int>> cxs;\r\n\r\n    for (int i = 0; i<n ; i++){\r\n        if (!visitado[i]){\r\n            vector <int> cx;\r\n            dfs_grafos(i,ady,visitado,cx);\r\n            cxs.push_back(cx);\r\n        }\r\n    }\r\n\r\n    cout << cxs.size()-1 << endl;\r\n    return 0;\r\n}',1428),
(1429,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    //code\r\n    int n,m,k;\r\n    cin >> n >> m >> k;\r\n    vector<int> seg(n,0);\r\n    for (int i = 0 ; i<m ; i++){\r\n        int a,b;\r\n        cin >> a >> b;\r\n        seg[a]++;\r\n    }\r\n    int c = 0;\r\n    for (int i = 1;i<n ; i++){\r\n        if (seg[i]>=k){\r\n            c++;\r\n        }\r\n    }\r\n    cout << c << endl;\r\n    return 0;\r\n}',1429),
(1430,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n,m,k;\r\n    cin >> n >> m >> k;\r\n    vector<int> seg(n,0);\r\n    for (int i = 0 ; i<m ; i++){\r\n        int a,b;\r\n        cin >> a >> b;\r\n        seg[b]++;\r\n    }\r\n    int c = 0;\r\n    for (int i = 0;i<n ; i++){\r\n        if (seg[i]>=k){\r\n            c++;\r\n        }\r\n    }\r\n    cout << c << endl;\r\n    return 0;\r\n}',1430),
(1431,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\n\r\nvoid dfs_grafos(int s, vector<vector<int>> &ady, vector<bool> &visitado, vector<int> &cx){\r\n    visitado[s] = true;\r\n    cx.push_back(s);\r\n    for (int vecino : ady[s]){\r\n        if (!visitado[vecino]){\r\n            dfs_grafos(vecino,ady,visitado,cx);\r\n        }\r\n    }\r\n}\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<int>> ady(n+1);\r\n    for (int i = 0; i<m ; i++){\r\n        int a,b;\r\n        cin >> a >> b;\r\n        ady[a].push_back(b);\r\n        ady[b].push_back(a);\r\n    }\r\n\r\n    vector<bool> visitado(n+1,false);\r\n    vector<int> cx;\r\n    dfs_grafos(1,ady,visitado,cx);\r\n\r\n    std::unordered_set<int> s(cx.begin(), cx.end());\r\n    bool primero = false;\r\n    for (int i = 1; i<=n ; i++){\r\n        if (s.find(i) == s.end() && !primero){\r\n            cout << i;\r\n            primero=true;\r\n        } else if (s.find(i) == s.end()) {\r\n            cout << \" \" << i;\r\n        }\r\n    }\r\n    cout << endl;\r\n    return 0;\r\n}',1431),
(1432,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\n\r\nvoid dfs_grafos(int s, vector<vector<int>> &ady, vector<bool> &visitado, vector<int> &cx){\r\n    visitado[s] = true;\r\n    cx.push_back(s);\r\n    for (int vecino : ady[s]){\r\n        if (!visitado[vecino]){\r\n            dfs_grafos(vecino,ady,visitado,cx);\r\n        }\r\n    }\r\n}\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<int>> ady(n+1);\r\n    for (int i = 0; i<m ; i++){\r\n        int a,b;\r\n        cin >> a >> b;\r\n        ady[a].push_back(b);\r\n        ady[b].push_back(a);\r\n    }\r\n\r\n    vector<bool> visitado(n+1,false);\r\n    vector<int> cx;\r\n    dfs_grafos(1,ady,visitado,cx);\r\n\r\n    std::unordered_set<int> s(cx.begin(), cx.end());\r\n    bool primero = false;\r\n    for (int i = 1; i<=n ; i++){\r\n        if (s.find(i) == s.end() && !primero){\r\n            cout << i;\r\n            primero=true;\r\n        } else if (s.find(i) == s.end()) {\r\n            cout << \" \" << i;\r\n        }\r\n    }\r\n    cout << endl;\r\n    return 0;\r\n}',1432),
(1433,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<int>> aristas;\r\n\r\n    for (int i = 0; i<m ; i++){\r\n        int a,b;\r\n        cin >> a >> b;\r\n        aristas.push_back({a,b});\r\n    }\r\n    int t;\r\n    cin >> t;\r\n    for (int i = 0 ; i<t ; i++){\r\n        bool bandera=false;\r\n        int l;\r\n        cin >> l;\r\n        vector<int> ruta;\r\n        for (int k = 0; k < l; k++){\r\n            int x;\r\n            cin >> x;\r\n            ruta.push_back(x);\r\n        }\r\n\r\n        for (int k = 0; k<l-1; k++){\r\n            vector<int> conex = {ruta[k],ruta[k+1]};\r\n            if (!(find(aristas.begin(), aristas.end(), conex) != aristas.end())) {\r\n                bandera=true;\r\n                break;\r\n            }\r\n        }\r\n        if (!bandera){\r\n            cout << \"SI\" << endl;\r\n        } else {\r\n            cout << \"NO\" << endl;\r\n        }\r\n\r\n    }\r\n    return 0;\r\n}',1433),
(1434,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nbool myfunction (int i,int j)\r\n{\r\n    if (i>j)\r\n    return true;\r\n    else\r\n    return false;\r\n}\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    //código\r\n\r\n    int n;\r\n    cin >> n;\r\n    vector<pair<int,vector<int>>> niveles;\r\n\r\n    for (int i = 0; i<n; i++){\r\n        int num;\r\n        cin >> num;\r\n        vector<int> niv;\r\n        for (int k = 0; k < num ; k++){\r\n            int peso;\r\n            cin >> peso;\r\n            niv.push_back(peso);\r\n        }\r\n        sort(niv.begin(),niv.end(),myfunction);\r\n        niveles.push_back({num,niv});\r\n    }\r\n\r\n    sort(niveles.begin(),niveles.end());\r\n    \r\n    for (int i = 0; i<n ; i++){\r\n        for (int xd : niveles[i].second){\r\n            cout << xd << \" \";\r\n        }\r\n        cout << endl;\r\n    }\r\n    return 0;\r\n}',1434),
(1435,'n=int(input())\r\nfor i in range(n):\r\n    lol=input()\r\n    a,b=map(int,input().split())\r\n    conjunto=set()\r\n    for k in range(b):\r\n        x,y=map(int,input().split())\r\n        conjunto.add(frozenset({x,y}))\r\n    print(len(conjunto)*2)',1435),
(1436,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nvoid dfs_grafos(int s, vector<set<int>> &ady, vector<bool> &visitado, vector<int> &cx){\r\n    visitado[s] = true;\r\n    cx.push_back(s);\r\n    for (int vecino : ady[s]){\r\n        if (!visitado[vecino]){\r\n            dfs_grafos(vecino,ady,visitado,cx);\r\n        }\r\n    }\r\n}\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int n;\r\n    cin >> n;\r\n    for (int _ = 0; _<n; _++){\r\n        int s;\r\n        cin >> s;\r\n        int v,a;\r\n        cin >> v >> a;\r\n        vector<set<int>> ady(v);\r\n        for (int i = 0; i<a ; i++){\r\n            int x,y;\r\n            cin >> x >> y;\r\n            ady[x].insert(y);\r\n            ady[y].insert(x);\r\n        }\r\n        vector<bool> visitado(v,false);\r\n        vector<int> cx;\r\n        dfs_grafos(s,ady,visitado,cx);\r\n        int contador = 0;\r\n        for (int nodo : cx){\r\n            contador+=ady[nodo].size();\r\n        }\r\n        cout << contador << endl;\r\n    }\r\n    return 0;\r\n}',1436),
