(1452,'x = int(input())\r\nmatriz =[]\r\nfor i in range (x):\r\n    fila = []\r\n    texto = input().split()\r\n    for z in texto:\r\n        fila.append(z)\r\n    matriz.append(fila)\r\nsimet = True\r\nfor i in range(x):\r\n    for j in range(x):\r\n        if matriz[i][j] != matriz[j][i]:\r\n            simet = False\r\nif simet:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1452),
(1453,'def anti_prim(w,n,s):\r\n    visitado=[False]*n\r\n    visitado[s] = True\r\n    mst = []\r\n    edges_heap = []\r\n\r\n    for k in range(n):\r\n        if not visitado[k] and w[s][k] != float(\'inf\'):\r\n            heapq.heappush(edges_heap, (-w[s][k], s, k))\r\n\r\n    while edges_heap:\r\n        neg_peso, u, v = heapq.heappop(edges_heap)\r\n        peso_real=-neg_peso\r\n        if not visitado[v]:\r\n            visitado[v]=True\r\n            mst.append((u,v,peso_real))\r\n            for k in range(n):\r\n                if not visitado[k] and w[v][k] != float (\'inf\'):\r\n                    heapq.heappush(edges_heap, (-w[v][k], v, k))\r\n    return mst\r\n\r\nn,m=map(int,input().split())\r\nw = [[float(\'inf\')]*n for _ in range(n)]\r\n\r\nfor i in range(m):\r\n    a,b,c=map(int,input().split())\r\n    w[a][b]=c\r\n    w[b][a]=c\r\n\r\nmst = anti_prim(w,n,0)\r\nc=0\r\nfor i in range(len(mst)):\r\n    c+=mst[i][2]\r\nprint(c)',1453),
(1454,'import heapq\r\n\r\ndef anti_prim(w,n,s):\r\n    visitado=[False]*n\r\n    visitado[s] = True\r\n    mst = []\r\n    edges_heap = []\r\n\r\n    for k in range(n):\r\n        if not visitado[k] and w[s][k] != float(\'inf\'):\r\n            heapq.heappush(edges_heap, (-w[s][k], s, k))\r\n\r\n    while edges_heap:\r\n        neg_peso, u, v = heapq.heappop(edges_heap)\r\n        peso_real=-neg_peso\r\n        if not visitado[v]:\r\n            visitado[v]=True\r\n            mst.append((u,v,peso_real))\r\n            for k in range(n):\r\n                if not visitado[k] and w[v][k] != float (\'inf\'):\r\n                    heapq.heappush(edges_heap, (-w[v][k], v, k))\r\n    return mst\r\n\r\nn,m=map(int,input().split())\r\nw = [[float(\'inf\')]*n for _ in range(n)]\r\n\r\nfor i in range(m):\r\n    a,b,c=map(int,input().split())\r\n    w[a][b]=c\r\n    w[b][a]=c\r\n\r\nmst = anti_prim(w,n,0)\r\nc=0\r\nfor i in range(len(mst)):\r\n    c+=mst[i][2]\r\nprint(c)',1454),
(1455,'import math\r\nimport heapq\r\n\r\ndef dfs_grafos(s,ady,n,visitado):\r\n    if not visitado[s]:\r\n        visitado[s]=True\r\n        for vecino in ady[s]:\r\n            dfs_grafos(vecino,ady,n,visitado)\r\n\r\ndef distancia_grupos(grup1,grup2,rv):\r\n    min = float(\'inf\')\r\n    for i in range(len(grup1)):\r\n        for k in range(len(grup2)):\r\n            x = grup1[i]\r\n            y = grup2[k]\r\n            coorx1=x//rv\r\n            coory1=x%rv\r\n            coorx2=y//rv\r\n            coory2=y%rv\r\n            dist_x_y=abs(coorx1-coorx2)+abs(coory1-coory2)\r\n            if min > dist_x_y:\r\n                min=dist_x_y\r\n    return min\r\n\r\ndef prim(w, n, s):\r\n    visitado=[False]*n\r\n    visitado[s] = True\r\n    mst = []\r\n    edges_heap = []\r\n\r\n    for k in range(n):\r\n        if not visitado[k] and w[s][k] != float(\'inf\'):\r\n            heapq.heappush(edges_heap, (w[s][k], s, k))\r\n\r\n    while edges_heap:\r\n        peso, u, v = heapq.heappop(edges_heap)\r\n        if not visitado[v]:\r\n            visitado[v]=True\r\n            mst.append((u,v,peso))\r\n            for k in range(n):\r\n                if not visitado[k] and w[v][k] != float(\'inf\'):\r\n                    heapq.heappush(edges_heap, (w[v][k], v, k))\r\n    return mst\r\n\r\nT=int(input())\r\nfor _ in range(T):\r\n    s=int(input())\r\n    v,a=map(int,input().split())\r\n    rv = math.sqrt(v)\r\n    rv = int(rv)\r\n    ady=[[] for _  in range(v)]\r\n    for i in range(a):\r\n        x,y=map(int,input().split())\r\n        ady[x].append(y)\r\n        ady[y].append(x)\r\n\r\n\r\n    for i in range(v):\r\n        ady[i]=set(ady[i])\r\n        ady[i]=list(ady[i])\r\n    aristas=0\r\n    for i in range(len(ady)):\r\n        aristas+=len(ady[i])\r\n\r\n    grupos=set()\r\n\r\n    for i in range(v):\r\n        visitado=[False for _  in range(v)]\r\n        dfs_grafos(i,ady,v,visitado)\r\n        grup=[]\r\n        for i in range(v):\r\n            if visitado[i]:\r\n                grup.append(i)\r\n        if len(grup)!=1:\r\n            grup=tuple(grup)\r\n            grupos.add(grup) \r\n\r\n    grupos=list(grupos)\r\n\r\n    w = [[float(\'inf\')]*len(grupos) for _ in range(len(grupos))]\r\n\r\n    for i in range(len(grupos)-1):\r\n        for k in range(i+1,len(grupos)):\r\n            grup1=grupos[i]\r\n            grup2=grupos[k]\r\n\r\n            dist_grupos=distancia_grupos(grup1,grup2,rv)\r\n\r\n            w[i][k]=dist_grupos\r\n            w[k][i]=dist_grupos\r\n\r\n    mst_grupos=prim(w,len(grupos),0)\r\n\r\n    acumulador_puentes=0\r\n    for i in range(len(mst_grupos)):\r\n        acumulador_puentes+=mst_grupos[i][2]\r\n    acumulador_puentes=int(acumulador_puentes)\r\n    acumulador_puentes*=2\r\n    acumulador_puentes+=aristas\r\n    print(acumulador_puentes)',1455),
(1456,'import math\r\nimport heapq\r\n\r\ndef dfs_grafos(s,ady,n,visitado):\r\n    if not visitado[s]:\r\n        visitado[s]=True\r\n        for vecino in ady[s]:\r\n            dfs_grafos(vecino,ady,n,visitado)\r\n\r\ndef distancia_grupos(grup1,grup2,rv):\r\n    min = float(\'inf\')\r\n    for i in range(len(grup1)):\r\n        for k in range(len(grup2)):\r\n            x = grup1[i]\r\n            y = grup2[k]\r\n            coorx1=x//rv\r\n            coory1=x%rv\r\n            coorx2=y//rv\r\n            coory2=y%rv\r\n            dist_x_y=abs(coorx1-coorx2)+abs(coory1-coory2)\r\n            if min > dist_x_y:\r\n                min=dist_x_y\r\n    return min\r\n\r\ndef prim(w, n, s):\r\n    visitado=[False]*n\r\n    visitado[s] = True\r\n    mst = []\r\n    edges_heap = []\r\n\r\n    for k in range(n):\r\n        if not visitado[k] and w[s][k] != float(\'inf\'):\r\n            heapq.heappush(edges_heap, (w[s][k], s, k))\r\n\r\n    while edges_heap:\r\n        peso, u, v = heapq.heappop(edges_heap)\r\n        if not visitado[v]:\r\n            visitado[v]=True\r\n            mst.append((u,v,peso))\r\n            for k in range(n):\r\n                if not visitado[k] and w[v][k] != float(\'inf\'):\r\n                    heapq.heappush(edges_heap, (w[v][k], v, k))\r\n    return mst\r\n\r\nT=int(input())\r\nfor _ in range(T):\r\n    s=int(input())\r\n    v,a=map(int,input().split())\r\n    rv = math.sqrt(v)\r\n    rv = int(rv)\r\n    ady=[[] for _  in range(v)]\r\n    for i in range(a):\r\n        x,y=map(int,input().split())\r\n        ady[x].append(y)\r\n        ady[y].append(x)\r\n\r\n\r\n    for i in range(v):\r\n        ady[i]=set(ady[i])\r\n        ady[i]=list(ady[i])\r\n    aristas=0\r\n    for i in range(len(ady)):\r\n        aristas+=len(ady[i])\r\n\r\n    grupos=set()\r\n\r\n    for i in range(v):\r\n        visitado=[False for _  in range(v)]\r\n        dfs_grafos(i,ady,v,visitado)\r\n        grup=[]\r\n        for i in range(v):\r\n            if visitado[i]:\r\n                grup.append(i)\r\n        if len(grup)!=1:\r\n            grup=tuple(grup)\r\n            grupos.add(grup) \r\n    grupos=list(grupos)\r\n    bandera = True ## está o no está s en grupos\r\n    for i in range(len(grupos)):\r\n        for k in range(len(grupos[i])):\r\n            if s==grupos[i][k]:\r\n                bandera=False\r\n\r\n    if bandera:\r\n        grupos.append((s,))\r\n\r\n    w = [[float(\'inf\')]*len(grupos) for _ in range(len(grupos))]\r\n\r\n    for i in range(len(grupos)-1):\r\n        for k in range(i+1,len(grupos)):\r\n            grup1=grupos[i]\r\n            grup2=grupos[k]\r\n\r\n            dist_grupos=distancia_grupos(grup1,grup2,rv)\r\n\r\n            w[i][k]=dist_grupos\r\n            w[k][i]=dist_grupos\r\n\r\n    mst_grupos=prim(w,len(grupos),0)\r\n\r\n    acumulador_puentes=0\r\n    for i in range(len(mst_grupos)):\r\n        acumulador_puentes+=mst_grupos[i][2]\r\n    acumulador_puentes=int(acumulador_puentes)\r\n    acumulador_puentes*=2\r\n    acumulador_puentes+=aristas\r\n    print(acumulador_puentes)',1456),
(1457,'n = int(input().strip())\r\n\r\n# Conjunto para almacenar las palabras sin repetir\r\npalabras = set()\r\n\r\n# Lectura de las n líneas\r\nfor _ in range(n):\r\n    linea = input().strip().split()\r\n    for palabra in linea:\r\n        palabras.add(palabra)\r\n\r\n# Convertimos el conjunto a lista y la ordenamos alfabéticamente\r\nlista_palabras = list(palabras)\r\nlista_palabras.sort()\r\n\r\n# Imprimimos las palabras ordenadas\r\nfor palabra in lista_palabras:\r\n    print(palabra)',1457),
(1458,'n = int(input().strip())\r\n\r\n# Lista para almacenar las palabras sin repetir\r\npalabras = []\r\n\r\n# Lectura de las n líneas\r\nfor _ in range(n):\r\n    linea = input().strip().split()\r\n    for palabra in linea:\r\n        # Solo agregamos si no está ya en la lista\r\n        if palabra not in palabras:\r\n            palabras.append(palabra)\r\n\r\n# Ordenamos la lista alfabéticamente\r\npalabras.sort()\r\n\r\n# Imprimimos las palabras ordenadas\r\nfor palabra in palabras:\r\n    print(palabra)',1458),
(1459,'n = int(input().strip())\r\nnotas_por_alumno = {}\r\n\r\nfor _ in range(n):\r\n    nombre, nota = input().split()\r\n    nota = float(nota)\r\n    if nombre not in notas_por_alumno:\r\n        notas_por_alumno[nombre] = []\r\n    notas_por_alumno[nombre].append(nota)\r\n\r\nfor nombre in sorted(notas_por_alumno):\r\n    notas = notas_por_alumno[nombre]\r\n    if len(notas) == 3:\r\n        promedio = sum(notas) / 3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n        print(f\"{nombre} p\")',1459),
(1460,'# Solución con SOLO LISTAS\r\n# No usa diccionarios ni conjuntos\r\n\r\nn = int(input().strip())\r\n\r\nnombres = []      # Lista con los nombres\r\nnotas_por_alumno = []  # Lista paralela con listas de notas\r\n\r\nfor _ in range(n):\r\n    nombre, nota_str = input().split()\r\n    nota = float(nota_str)\r\n\r\n    if nombre not in nombres:\r\n        # Si el nombre no está, se agrega y se inicia su lista de notas\r\n        nombres.append(nombre)\r\n        notas_por_alumno.append([nota])\r\n    else:\r\n        # Si ya existe, se agrega la nota en el índice correspondiente\r\n        idx = nombres.index(nombre)\r\n        notas_por_alumno[idx].append(nota)\r\n\r\n# Crear lista final de resultados [nombre, promedio/p]\r\nresultados = []\r\nfor i in range(len(nombres)):\r\n    notas = notas_por_alumno[i]\r\n    if len(notas) == 3:\r\n        promedio = sum(notas) / 3\r\n        resultados.append([nombres[i], f\"{promedio:.2f}\"])\r\n    else:\r\n        resultados.append([nombres[i], \"p\"])\r\n\r\n# Ordenar alfabéticamente por nombre\r\nresultados.sort(key=lambda x: x[0])\r\n\r\n# Mostrar salida\r\nfor nombre, promedio in resultados:\r\n    print(nombre, promedio)',1460),
(1461,'n = int(input().strip())\r\nnotas_por_alumno = {}\r\n\r\nfor _ in range(n):\r\n    nombre, nota = input().split()\r\n    nota = float(nota)\r\n    notas_por_alumno.setdefault(nombre,[nota]).append(nota)\r\n    \r\nfor nombre in sorted(notas_por_alumno):\r\n    notas = notas_por_alumno[nombre]\r\n    if len(notas) == 3:\r\n        promedio = sum(notas) / 3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n        print(f\"{nombre} p\")',1461),
(1462,'n = int(input().strip())\r\nnotas_por_alumno = {}\r\n\r\nfor _ in range(n):\r\n    nombre, nota = input().split()\r\n    nota = float(nota)\r\n    notas_por_alumno.setdefault(nombre,[]).append(nota)\r\nfor nombre in sorted(notas_por_alumno):\r\n    notas = notas_por_alumno[nombre]\r\n    if len(notas) == 3:\r\n        promedio = sum(notas) / 3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n        print(f\"{nombre} p\")',1462),
(1463,'# Leer n y m\r\nn, m = map(int, input().split())\r\n\r\n# Leer esquinas encuestadas por Ana\r\nana = set()\r\nfor _ in range(n):\r\n    x, y = map(int, input().split())\r\n    ana.add((x, y))  # cada esquina como una tupla\r\n\r\n# Leer esquinas encuestadas por Beto\r\nbeto = set()\r\nfor _ in range(m):\r\n    x, y = map(int, input().split())\r\n    beto.add((x, y))\r\n\r\n# Calcular intersección de esquinas\r\ncomunes = ana.intersection(beto)\r\n\r\n# Imprimir cantidad de esquinas encuestadas por ambos\r\nprint(len(comunes))',1463),
(1464,'# Solución solo con LISTAS\r\n# Encuentra cuántas esquinas fueron encuestadas por ambos\r\n\r\n# Leer n y m\r\nn, m = map(int, input().split())\r\n\r\n# Leer esquinas encuestadas por Ana\r\nana = []\r\nfor _ in range(n):\r\n    x, y = map(int, input().split())\r\n    par = [x, y]\r\n    if par not in ana:      # evitar repetidos en la lista de Ana\r\n        ana.append(par)\r\n\r\n# Leer esquinas encuestadas por Beto\r\nbeto = []\r\nfor _ in range(m):\r\n    x, y = map(int, input().split())\r\n    par = [x, y]\r\n    if par not in beto:     # evitar repetidos en la lista de Beto\r\n        beto.append(par)\r\n\r\n# Calcular cuántas esquinas están en ambas listas\r\ncomunes = 0\r\nfor esquina in ana:\r\n    if esquina in beto:\r\n        comunes += 1\r\n\r\n# Mostrar resultado\r\nprint(comunes)',1464),
(1465,'class Grafo:\r\n  def __init__(self, vertices):\r\n      self.V = vertices\r\n      self.E =0\r\n      self.adj_list = [[] for _ in range(self.V)]\r\n\r\n  def add_edge(self, u, v):\r\n      self.E =self.E +1\r\n      self.adj_list[u].append(v)\r\n      self.adj_list[v].append(u)\r\n\r\n\r\ndef DFS(start_vertex):\r\n  visited = [False] * mi_grafo.V\r\n  stack = []\r\n\r\n  # Iniciar la busqueda en profundidad desde el vertice inicial\r\n  stack.append(start_vertex)\r\n  visited[start_vertex] = 1\r\n\r\n  while stack:\r\n      current_vertex = stack.pop()\r\n      # Puedes cambiar adj_list por adj_matrix\r\n      for neighbor in mi_grafo.adj_list[current_vertex]:\r\n          if not visited[neighbor]:\r\n              stack.append(neighbor)\r\n              visited[neighbor] = True\r\n  return(sum(visited))\r\n\r\nif __name__ == \"__main__\":\r\n    t = int(input())\r\n    for _ in range(t):\r\n        N = int(input())\r\n        n,m = [int(a) for a in input().split()]\r\n        mi_grafo = Grafo(n)  # Crear un grafo con 5 vertices\r\n\r\n        # agregar aristas al grafo\r\n        for _ in range(m):\r\n            u,v = [int(a) for a in input().split()]\r\n            mi_grafo.add_edge(u, v)\r\n        print(2*(DFS(N)-1))',1465),
(1466,'z = int(input())\r\njug = input()\r\njuego =[]\r\ndats =[]\r\nfor i in jug:\r\n    juego.append(i)\r\nif \"#\" in juego:\r\n    for i in juego:\r\n        if i ==\"#\" or i ==\"A\" or i==\"T\":\r\n            dats.append(i)\r\n    lugA = dats.index(\"A\")\r\n    lugat = dats.index(\"#\")\r\n    if lugat< lugA:\r\n        print(\"ganaste\")\r\n    elif lugat< lugA:\r\n        print(\"perdiste\")\r\nelse:\r\n    print(\"ganaste\")',1466),
(1467,'z = int(input())\r\njug = input()\r\njuego =[]\r\ndats =[]\r\nfor i in jug:\r\n    juego.append(i)\r\nif \"#\" in juego:\r\n    for i in juego:\r\n        if i ==\"#\" or i ==\"A\" or i==\"T\":\r\n            dats.append(i)\r\n    lugA = dats.index(\"A\")\r\n    lugat = dats.index(\"#\")\r\n    if lugat< lugA:\r\n        print(\"ganaste\")\r\n    elif lugat> lugA:\r\n        print(\"perdiste\")\r\nelse:\r\n    print(\"ganaste\")',1467),
(1468,'z = int(input())\r\njug = input()\r\njuego =[]\r\ndats =[]\r\nfor i in jug:\r\n    juego.append(i)\r\nif \"#\" in juego:\r\n    for i in juego:\r\n        if i ==\"#\" or i ==\"A\" or i==\"T\":\r\n            dats.append(i)\r\n    lugA = dats.index(\"A\")\r\n    lugat = dats.index(\"#\")\r\n    lugT = dats.index(\"T\")\r\n    if lugT < lugA:\r\n        lugT = lugA\r\n        lugA = lugT\r\n    if lugat< lugA:\r\n        print(\"ganaste\")\r\n    elif lugat> lugA:\r\n        print(\"perdiste\")\r\nelse:\r\n    print(\"ganaste\")',1468),
