(1475,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nvoid dfs_grafos(int s, vector<set<int>> &ady, vector<bool> &visitado, vector<int> &cx){\r\n    visitado[s] = true;\r\n    cx.push_back(s);\r\n    for (int vecino : ady[s]){\r\n        if (!visitado[vecino]){\r\n            dfs_grafos(vecino,ady,visitado,cx);\r\n        }\r\n    }\r\n}\r\n\r\nint main()\r\n{\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int n;\r\n    cin >> n;\r\n    for (int _ = 0; _<n; _++){\r\n        int s;\r\n        cin >> s;\r\n        int v,a;\r\n        cin >> v >> a;\r\n        vector<set<int>> ady(v);\r\n        for (int i = 0; i<a ; i++){\r\n            int x,y;\r\n            cin >> x >> y;\r\n            ady[x].insert(y);\r\n            ady[y].insert(x);\r\n        }\r\n        vector<bool> visitado(v,false);\r\n        vector<int> cx;\r\n        dfs_grafos(s,ady,visitado,cx);\r\n        int contador = 0;\r\n        for (int nodo : cx){\r\n            contador++;\r\n        }\r\n        cout << 2*(contador-1) << endl;\r\n    }\r\n    cin.ignore();\r\n    cin.get();\r\n    return 0;\r\n}',1475),
