(1477,'import math\r\nk = math.pi\r\nx = input()\r\na , b , c , d = x.split()\r\na = int(a)\r\nb = int(b)\r\nc = int(c)\r\nd = int(d)\r\ny = input()\r\ne , f , g , h = y.split()\r\ne = int(e)\r\nf = int(f)\r\ng = int(g)\r\nh = int(h)\r\nm = e/(a*a*k)\r\nn = f/(b*b*k)\r\no = g/(c*c*k)\r\np = h/(d*d*k)\r\nif m>n>=o>=p:\r\n    print(\"pequeña\")\r\nelif n>m>=o>=p:\r\n    print(\"mediana\")\r\nelif o>n>=m>=p:\r\n    print(\"grande\")\r\nelif p>n>=m>=o:\r\n    print(\"familiar\")',1477),
