(1487,'import math\r\npi = math.pi\r\nradios = input()\r\nrp , rm , rg , rf = radios.split()\r\nrp = float(rp)\r\nrm = float(rm)\r\nrg = float(rg)\r\nrf = float(rf)\r\nprecios = input()\r\npp , pm, pg , pf = precios.split()\r\npp = float(pp)\r\npm = float(pm)\r\npg = float(pg)\r\npf = float(pf)\r\npequeña = pp/(rp*rp*pi)\r\nmediana = pm/(rm*rm*pi)\r\ngrande = pg/(rg*rg*pi)\r\nfamiliar = pf/(rf*rf*pi)\r\nlista = [pequeña,mediana,grande,familiar]\r\nlista.sort()\r\nif lista.index(pequeña) == 0:\r\n    print(\"pequeña\")\r\nelif lista.index(mediana) == 0:\r\n    print(\"mediana\")\r\nelif lista.index(grande) == 0:\r\n    print(\"grande\")\r\nelif lista.index(familiar) == 0:\r\n    print(\"familiar\")',1487),
(1488,'for i in range(3):\r\n    alturas = input()\r\n    a,b,c,d,e = alturas.split()\r\n    a = float(a)\r\n    b = float(b)\r\n    c = float(c)\r\n    d = float(d)\r\n    e = float(e)\r\n    lista = [a,b,c,d,e]\r\n    coso = [a,b,c,d,e]\r\n    algo = [a,b,c,d,e]\r\n    coso.sort()\r\n    algo.sort()\r\n    algo.reverse()\r\n    if lista == coso:\r\n        print(\"Creciente\")\r\n    elif lista == algo:\r\n        print(\"Decreciente\")\r\n    else:\r\n        print(\"Ninguno\")',1488),
