(1504,'n = int(input())\r\nnotas=[]\r\nfor i in range(n):\r\n    a,b=input().split()\r\n    b=float(b)\r\n    notas.append((a,b))\r\n\r\nsumas,cont = {} , {}\r\n\r\nfor nombre,nota in notas:\r\n    sumas[nombre] = sumas.get(nombre, 0) + nota\r\n    cont[nombre] = cont.get(nombre, 0) + 1\r\n\r\nprom1 = {k: sumas[k]/cont[k] for k in sumas if cont[k]>2}\r\nprom2 = {k: \"p\" for k in sumas if cont[k]<=2}\r\nfinales1=[]\r\nfinales2=[]\r\nfor x in prom1:\r\n    finales1.append((x,prom1[x]))\r\nfor x in prom2:\r\n    finales2.append((x,prom2[x]))\r\nfinales = finales1+finales2\r\nfinales.sort(key=lambda t: (t[0]))\r\nfor nombre,nota in finales:\r\n    if nota !=\"p\":\r\n        print(nombre,f\"%.2f\" % nota)\r\n    else:\r\n        print(nombre,\"p\")',1504),
