(1518,'n=int(input())\r\nregistro={}\r\npersonas=[]\r\nfor i in range(n):\r\n	nombre,nota=input().split()\r\n	personas.append(nombre)\r\n	if nombre in registro.keys():\r\n		registro[nombre]=registro[nombre]+float(nota)\r\n	registro.setdefault(nombre,float(nota))\r\npersonas_new=sorted(set(personas))\r\nfor item in personas_new:\r\n	if personas.count(item)>=3:\r\n		print(f\"{item} %.2f\"%(registro[nombre]/3))\r\n	else:\r\n		print(f\"{item} p\")',1518),
(1519,'n=int(input())\r\nregistro={}\r\npersonas=[]\r\nfor i in range(n):\r\n	nombre,nota=input().split()\r\n	personas.append(nombre)\r\n	if nombre in registro.keys():\r\n		registro[nombre]=registro[nombre]+float(nota)\r\n	registro.setdefault(nombre,float(nota))\r\npersonas_new=sorted(set(personas))\r\nfor item in personas_new:\r\n	if personas.count(item)>=3:\r\n		print(f\"{item} %.2f\"%(registro[item]/3))\r\n	else:\r\n		print(f\"{item} p\")',1519),
(1520,'def es_vertical(mat):\r\n    D = len(mat)\r\n    for i in range(D):\r\n        for j in range(D):\r\n            # comparar con el espejo horizontalmente: (i, j) vs (i, D-1-j)\r\n            if mat[i][j] != mat[i][D - 1 - j]:\r\n                return False\r\n    return True\r\n\r\ndef es_horizontal(mat):\r\n    D = len(mat)\r\n    for i in range(D):\r\n        for j in range(D):\r\n            # comparar con el espejo verticalmente: (i, j) vs (D-1-i, j)\r\n            if mat[i][j] != mat[D - 1 - i][j]:\r\n                return False\r\n    return True\r\n\r\ndef es_diag_principal(mat):\r\n    D = len(mat)\r\n    for i in range(D):\r\n        for j in range(D):\r\n            # simetría en diagonal principal: (i,j) vs (j,i)\r\n            if mat[i][j] != mat[j][i]:\r\n                return False\r\n    return True\r\n\r\ndef es_diag_secundaria(mat):\r\n    D = len(mat)\r\n    for i in range(D):\r\n        for j in range(D):\r\n            # simetría en diagonal secundaria: (i,j) vs (D-1-j, D-1-i)\r\n            if mat[i][j] != mat[D - 1 - j][D - 1 - i]:\r\n                return False\r\n    return True\r\n\r\ndef main():\r\n    import sys\r\n    data = sys.stdin.read().strip().split()\r\n    p = 0\r\n\r\n    N = int(data[p]); p += 1  # número de vitrales\r\n\r\n    for caso in range(N):\r\n        D = int(data[p]); p += 1\r\n\r\n        # leemos la matriz D x D\r\n        mat = []\r\n        for _ in range(D):\r\n            fila = list(map(int, data[p:p+D]))\r\n            p += D\r\n            mat.append(fila)\r\n\r\n        # chequeos\r\n        v = es_vertical(mat)\r\n        h = es_horizontal(mat)\r\n        dp = es_diag_principal(mat)\r\n        ds = es_diag_secundaria(mat)\r\n\r\n        # salida según reglas\r\n        hubo_algo = False\r\n        if v:\r\n            print(f\"El vitral {caso} tiene simetria vertical\")\r\n            hubo_algo = True\r\n        if h:\r\n            print(f\"El vitral {caso} tiene simetria horizontal\")\r\n            hubo_algo = True\r\n        if dp:\r\n            print(f\"El vitral {caso} tiene simetria en la diagonal principal\")\r\n            hubo_algo = True\r\n        if ds:\r\n            print(f\"El vitral {caso} tiene simetria en la diagonal secundaria\")\r\n            hubo_algo = True\r\n        if not hubo_algo:\r\n            print(f\"El vitral {caso} no tiene simetrias\")\r\n\r\n        # línea en blanco entre casos\r\n        if caso != N - 1:\r\n            print()\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1520),
(1521,'n=int(input())\r\nregistro={}\r\npersonas=[]\r\npromedio=0\r\nfor i in range(n):\r\n    nombre,nota=input().split()\r\n    registro.setdefault(nombre,[]).append(float(nota))\r\n    personas.append(nombre)\r\npersonas_new=sorted(set(personas))\r\nfor nombre in personas_new:\r\n    if len(registro[nombre])>=3:\r\n        for nota in registro[nombre]:\r\n            promedio+=nota\r\n        print(f\"{nombre} %.2f\" % (promedio/3))\r\n    else:\r\n        print(f\"{nombre} p\")',1521),
(1522,'n=int(input())\r\nregistro={}\r\npersonas=[]\r\nfor i in range(n):\r\n    nombre,nota=input().split()\r\n    registro.setdefault(nombre,[]).append(float(nota))\r\n    personas.append(nombre)\r\npersonas_new=sorted(set(personas))\r\nfor nombre in personas_new:\r\n    if len(registro[nombre])>=3:\r\n        promedio=0\r\n        for nota in registro[nombre]:\r\n            promedio+=nota\r\n        print(f\"{nombre} %.2f\" % (promedio/3))\r\n    else:\r\n        print(f\"{nombre} p\")',1522),
(1523,'registro={}\r\nwhile True:\r\n    try:\r\n        nota,nombre=input().split()\r\n        registro.setdefault(float(nota),[]).append(nombre)\r\n    except ValueError:\r\n        break\r\nfor nota in sorted(registro):\r\n    for persona in registro[nota]:\r\n        print(persona)',1523),
(1524,'def simular_gravedad(matriz_sin_paredes):\r\n    \"\"\"\r\n    Aplica gravedad sobre el INTERIOR (sin las paredes).\r\n    matriz_sin_paredes: lista de strings de largo m\r\n    Retorna nueva lista de strings (mismo tamaño) tras caer.\r\n    \"\"\"\r\n    n = len(matriz_sin_paredes)\r\n    m = len(matriz_sin_paredes[0]) if n > 0 else 0\r\n\r\n    # Convertimos cada fila (string) en lista mutable de chars\r\n    grid = [list(fila) for fila in matriz_sin_paredes]\r\n\r\n    # Procesar cada columna de 0..m-1 (sin paredes porque no existen aquí)\r\n    for col in range(m):\r\n        write_row = n - 1  # posición donde debe caer la próxima letra\r\n        # Recorremos desde abajo hacia arriba\r\n        for row in range(n - 1, -1, -1):\r\n            if grid[row][col] != \' \':\r\n                grid[write_row][col] = grid[row][col]\r\n                if write_row != row:\r\n                    grid[row][col] = \' \'\r\n                write_row -= 1\r\n        # Rellenar el resto con espacios por encima\r\n        for row in range(write_row, -1, -1):\r\n            grid[row][col] = \' \'\r\n\r\n    # Volvemos a strings\r\n    return [\"\".join(fila) for fila in grid]\r\n\r\n\r\n# Lectura de la entrada estándar y escritura de la salida estándar\r\nif __name__ == \"__main__\":\r\n    import sys\r\n\r\n    data = sys.stdin.read().splitlines()\r\n\r\n    # 1. Leer n y m\r\n    n_m = data[0].split()\r\n    n = int(n_m[0])\r\n    m = int(n_m[1])\r\n\r\n    # 2. Leer las siguientes n líneas CON paredes, formato: |.....|\r\n    #    Debemos extraer solo el contenido interior (sin el primer y último char)\r\n    interior = []\r\n    for i in range(1, 1 + n):\r\n        linea_cruda = data[i]\r\n\r\n        # Aseguramos que exista al menos el formato |...|\r\n        # y que el interior tenga largo m.\r\n        # Si faltan espacios al final dentro de las paredes, los rellenamos.\r\n        if len(linea_cruda) < m + 2:\r\n            linea_cruda = linea_cruda + \" \" * (m + 2 - len(linea_cruda))\r\n\r\n        # quitamos la primera y última columna (paredes)\r\n        # ejemplo: \"|A  B |\" -> \"A  B \"\r\n        sin_pared = linea_cruda[1:-1]\r\n\r\n        # normalizamos longitud del interior exactamente a m\r\n        if len(sin_pared) < m:\r\n            sin_pared = sin_pared + \" \" * (m - len(sin_pared))\r\n        sin_pared = sin_pared[:m]\r\n\r\n        interior.append(sin_pared)\r\n\r\n    # 3. Simular gravedad solo sobre el interior\r\n    interior_final = simular_gravedad(interior)\r\n\r\n    # 4. Volver a agregar paredes al imprimir\r\n    #    Cada línea debe salir como |......|\r\n    for fila in interior_final:\r\n        print(f\"|{fila}|\")',1524),
(1525,'a=int(input())\r\nz={}\r\nd=[]\r\nfor n in range(a):\r\n    e=0\r\n    b,c=input().split()\r\n    z.setdefault(b,[]).append(float(c))\r\n    if len(z[b])==3:\r\n        for m in z[b]:\r\n            e+=m\r\n        e/=3\r\n        d.append(z[b])\r\n        d=sorted(d)\r\nprint(f\'{d} {e}\')',1525),
(1526,'def vertical(w,d,num):\r\n    bandera = True\r\n    for i in range(d):\r\n        for k in range(d):\r\n            if w[k][i] != w[k][d-1-i]:\r\n                bandera = False\r\n    if bandera:\r\n        print(f\"El vitral {num} tiene simetria vertical\")\r\n        return True\r\n\r\ndef horizontal(w,d,num):\r\n    bandera = True\r\n    for i in range(d):\r\n        for k in range(d):\r\n            if w[i][k] != w[d-1-i][k]:\r\n                bandera = False\r\n    if bandera:\r\n        print(f\"El vitral {num} tiene simetria horizontal\")\r\n        return True\r\n\r\ndef secundaria(w,d,num):\r\n    bandera = True\r\n    for i in range(d):\r\n        for k in range(d):\r\n            if w[i][k] != w[d-1-k][d-1-i]:\r\n                bandera = False\r\n    if bandera:\r\n        print(f\"El vitral {num} tiene simetria en la diagonal secundaria\")\r\n        return True\r\n\r\ndef principal(w,d,num):\r\n    bandera = True\r\n    for i in range(d):\r\n        for k in range(d):\r\n            if w[i][k] != w[k][i]:\r\n                return \"\"\r\n    if bandera:\r\n        print(f\"El vitral {num} tiene simetria en la diagonal principal\")\r\n        return True\r\n\r\nn  = int(input())\r\nfor num in range(n):\r\n    d = int(input())\r\n    matriz=[]\r\n    for i in range(d):\r\n        x = input().split()\r\n        matriz.append(x)\r\n    es = False\r\n    es = vertical(matriz,d,num)\r\n    if es:\r\n        ignore = horizontal(matriz,d,num)\r\n    else:\r\n        es = horizontal(matriz,d,num)\r\n    if es:\r\n        ignore = principal(matriz,d,num)\r\n    else:\r\n        es = principal(matriz,d,num)\r\n    if es:\r\n        ignore = secundaria(matriz,d,num)\r\n    else:\r\n        es = secundaria(matriz,d,num)\r\n    if not es:\r\n        print(f\"El vitral {num} no tiene simetrias\")\r\n    print(\"\")',1526),
(1527,'def colocar_letra(w,fila,letra,columna):\r\n    if w[fila][columna] != \" \":\r\n        colocar_letra(w,fila-1,letra,columna)\r\n    else:\r\n        w[fila][columna] = letra\r\n\r\nn,m=map(int,input().split())\r\nw = []\r\nfor i in range(n):\r\n    x = list(input())\r\n    w.append(x)\r\nfinal = []\r\nfor x in range(1,m+1): ## mira cada columna\r\n    for y in range(n-1,-1,-1):\r\n        xd = w[y][x]\r\n        if xd !=\" \":\r\n            final.append((xd,x))\r\nmatriz_final=[[\" \"]*(m+2) for _ in range(n)]\r\nfor i in range(n):\r\n    matriz_final[i][0] = \"|\"\r\n    matriz_final[i][m+1] = \"|\"\r\nfor letra,columna in final:\r\n    colocar_letra(matriz_final,n-1,letra,columna)\r\nfor i in range(len(matriz_final)):\r\n    print(*matriz_final[i], sep=\"\")',1527),
(1528,'contador = int(input())\r\n\r\nfor _ in range(contador):\r\n    Tamaño_matriz = int(input())\r\n    matriz = []\r\n\r\n\r\n    for i in range(Tamaño_matriz):\r\n        entrada = list(map(int, input().strip().split()))\r\n        matriz.append(entrada)\r\n\r\n    \"Vertical\"\r\n    Simetrica_Vertical = True\r\n    for i in matriz:\r\n        if i != i[::-1]:\r\n            Simetrica_Vertical = False\r\n\r\n        \r\n    \"horizontal\"\r\n    Simetrica_Horizontal = True\r\n    if matriz != matriz[::-1]:\r\n        Simetrica_Horizontal = False\r\n\r\n\r\n    \"\"\"Diagonal principal\"\"\"\r\n    Simetrica_Diag_Principal = True\r\n    for i in range(Tamaño_matriz):\r\n        for j in range(Tamaño_matriz):\r\n            if matriz[i][j] != matriz[j][i]:\r\n                Simetrica_Diag_Principal = False\r\n                break\r\n\r\n\r\n    \"\"\"Diagonal secundaria\"\"\"\r\n    Simetrica_Diag_Sec = True\r\n    for i in range(Tamaño_matriz):\r\n        for j in range(Tamaño_matriz):\r\n            if matriz[i][j] != matriz[Tamaño_matriz - 1 - j][Tamaño_matriz - 1 - i]:\r\n                Simetrica_Diag_Sec = False\r\n                break\r\n    \"\"\"Salidas\"\"\"        \r\n    if Simetrica_Vertical:\r\n        print(f\"El vitral {contador} no tiene simetrias\")\r\n    if Simetrica_Horizontal:\r\n        print(f\"El vitral {contador} no tiene simetrias\")\r\n    if Simetrica_Diag_Principal:\r\n        print(f\"El vitral {contador} no tiene simetrias\")\r\n    if Simetrica_Diag_Sec:\r\n        print(f\"El vitral {contador} no tiene simetrias\")',1528),
