(1539,'filas, columnas = map(int, input().split())\r\n\r\nMatriz = [list(input()) for _ in range(filas)]\r\n\r\nfor c in range(columnas+1):\r\n    Matriz_caidos= []\r\n    for f in range(filas):\r\n        if Matriz[f][c] != \" \" and Matriz[f][c] != \"|\":\r\n            Matriz_caidos.append(Matriz[f][c])\r\n            Matriz[f][c] = \" \"\r\n    \r\n    fila_actual = filas - 1\r\n    for t in reversed(Matriz_caidos):\r\n        while fila_actual >= 0 and Matriz[fila_actual][c] == \"|\":\r\n            fila_actual -= 1\r\n        if fila_actual >= 0:\r\n            Matriz[fila_actual][c] = t\r\n            fila_actual -= 1\r\nfor fila in Matriz:\r\n    print(\"\".join(fila))\r\na,b,c = map(int, input().split())\r\nif a or b > c:\r\n    if a < b:\r\n        if a+a >= c:\r\n            print(\"SI\")\r\n        else:\r\n            print(\"NO\")\r\n    else:\r\n        if b+b >= c:\r\n            print(\"SI\")\r\n        else:\r\n            print(\"NO\")\r\nelse:\r\n    print(\"NO\")',1539),
(1540,'filas, columnas = map(int, input().split())\r\n\r\nMatriz = [list(input()) for _ in range(filas)]\r\n\r\nfor c in range(columnas+1):\r\n    Matriz_caidos= []\r\n    for f in range(filas):\r\n        if Matriz[f][c] != \" \" and Matriz[f][c] != \"|\":\r\n            Matriz_caidos.append(Matriz[f][c])\r\n            Matriz[f][c] = \" \"\r\n    \r\n    fila_actual = filas - 1\r\n    for t in reversed(Matriz_caidos):\r\n        while fila_actual >= 0 and Matriz[fila_actual][c] == \"|\":\r\n            fila_actual -= 1\r\n        if fila_actual >= 0:\r\n            Matriz[fila_actual][c] = t\r\n            fila_actual -= 1\r\nfor fila in Matriz:\r\n    print(\"\".join(fila))',1540),
(1541,'def vertical(cantidad,vitral): #cantidad de filas y columnas\r\n    vertical1=[]\r\n    vertical2=[]\r\n    for columna in range(cantidad//2):\r\n        for fila in range(cantidad):\r\n            vertical1.append(matriz[fila][columna])\r\n            #primeras columnas\r\n            vertical2.append(matriz[fila][cantidad-columna-1])\r\n            #Ultimas columnas\r\n    if vertical1==vertical2:\r\n        print(f\"El vitral {vitral} tiene simetria vertical\")\r\n    return\r\n\r\ndef horizontal(cantidad,vitral):\r\n    horizontal1=[]\r\n    horizontal2=[]\r\n    for fila in range(cantidad//2):\r\n        for columna in range(cantidad):\r\n            horizontal1.append(matriz[fila][columna])\r\n            horizontal2.append(matriz[cantidad-fila-1][columna])\r\n    if horizontal1==horizontal2:\r\n        print(f\"El vitral {vitral} tiene simetria horizontal\")\r\n    return\r\n\r\ndef diagonalP(cantidad,vitral):\r\n    for fila in range(cantidad):\r\n        for columna in range(cantidad):\r\n            if matriz[fila][columna]!=matriz[columna][fila]:\r\n                return\r\n    print(f\"El vitral {vitral} tiene simetria en la diagonal principal\")\r\n\r\ndef diagonalS(cantidad,vitral):\r\n    #????????\r\n    return\r\nn=int(input()) #casos de prueba\r\nfor i in range(n):\r\n    d=int(input()) #dimensiones de la matriz (vitral)\r\n    matriz=[[0]*d for i in range(d)]\r\n    for j in range(d): #que colores tiene el vitral?\r\n        matriz[j]=list(map(int,input().split()))\r\n        #los colores van desde 0 hasta 255\r\n    vertical(d,i)\r\n    horizontal(d,i)\r\n    diagonalP(d,i)\r\n    diagonalS(d,i)',1541),
(1542,'while True:\r\n    sublista = []\r\n    c = 0\r\n    filas1 = []\r\n    filas2 = []\r\n    n,m = map(int, input().split())\r\n    if n == 0:\r\n        break\r\n    min = (m*n)/1000\r\n    for j in range(n):\r\n        A = input().split()\r\n        filas1.append(A)\r\n    for j in range(n):\r\n        B = input().split()\r\n        filas2.append(B)\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if filas1[j][i] == filas2[j][i]:\r\n                c= c+1\r\n    if c/(m*n)<0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1542),
(1543,'while True:\r\n    c = 0\r\n    filas1 = []\r\n    filas2 = []\r\n    n,m = map(int, input().split())\r\n    if n == 0:\r\n        break\r\n    for j in range(n):\r\n        A = input().split()\r\n        filas1.append(A)\r\n    for j in range(n):\r\n        B = input().split()\r\n        filas2.append(B)\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if filas1[i][j] == filas2[i][j]:\r\n                c= c+1\r\n    if c/(m*n)<0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1543),
(1544,'while True:\r\n    c = 0\r\n    filas1 = []\r\n    filas2 = []\r\n    n,m = map(int, input().split())\r\n    if n == 0:\r\n        break\r\n    for j in range(n):\r\n        A = input().split()\r\n        filas1.append(A)\r\n    for j in range(n):\r\n        B = input().split()\r\n        filas2.append(B)\r\n    for i in range(n):\r\n        for j in range(m):\r\n            if filas1[i][j] != filas2[i][j]:\r\n                c= c+1\r\n    if c/(m*n)>0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1544),
(1545,'x = int(input().strip())\r\nsopa= [input().strip() for _ in range(x)]\r\nTCPEXIST = False\r\nfor i in range(x):\r\n    for j in range(x):\r\n        if j+2<x and sopa[i][j:j+3]== \"TCP\":\r\n            TCPEXIST = True\r\n            break\r\n        if i +2 < x and sopa[i][j]==\"T\" and sopa[i+1][j]==\"C\" and sopa[i+2][j]==\"P\":\r\n            TCPEXIST = True\r\n            break\r\n        if i+2< x and j+2<x and sopa[i][j]==\"T\" and sopa[i+1][j+1]==\"C\" and sopa [i+2][j+2]==\"P\":\r\n            TCPEXIST = True\r\n            break\r\n    if TCPEXIST== True:\r\n        break\r\nif TCPEXIST== True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1545),
