(1549,'notass=[]\r\nnumero=0\r\nwhile True:\r\n    dato = input().strip()\r\n    if dato == \"0\":\r\n        break\r\n    nota, alumno = dato.split()\r\n    nota = int(nota)\r\n    notass.append((nota, numero, alumno))\r\n    numero+=1\r\nnotass.sort()\r\nfor nota, _ , alumno in notass:\r\n    print(alumno)',1549),
(1550,'n = int(input())\r\nnotasxalum = {}\r\nfor i in range(n):\r\n    nom, nota = input().split()\r\n    nota=float(nota)\r\n    notasxalum.setdefault(nom, []).append(nota)\r\nfor nom in sorted(notasxalum):\r\n    notas = notasxalum[nom]\r\n    if len(notas)==3:\r\n        p = sum(notas)/3\r\n        print(f\"{nom} {p:.2f}\")\r\n    else:\r\n        print(f\"{nom} p\")',1550),
(1551,'n = int(input())\r\nfor w in range(n):\r\n    vertical = True\r\n    horizontal = True\r\n    d1 = True\r\n    d2 = True\r\n    l = int(input())\r\n    matriz = [list(map(int, input().split())) for _ in range(l)]\r\n    for i in range(l):\r\n        for j in range(l//2):\r\n            if matriz[i][j]!=matriz[i][l-1-j]:\r\n                vertical = False\r\n                break\r\n    for j in range(l):\r\n        for i in range(l//2):\r\n            if matriz[i][j]!=matriz[l-i-1][j]:\r\n                horizontal = False\r\n                break\r\n    for i in range(l//2):\r\n        for j in range(l//2):\r\n            if matriz[i][l-1-j]!=matriz[l-1-i][j]:\r\n                d1 = False\r\n                break\r\n    for i in range(l//2):\r\n        for j in range(l//2):\r\n            if matriz[l-1-i][j]!=matriz[i][l-1-j]:\r\n                d2 = False\r\n                break\r\n    sim = [vertical, horizontal, d1, d2]\r\n    if any(sim)==True:\r\n        if vertical==True:\r\n            print(f\"El vitral {w} tiene simetria vertical\")\r\n        if horizontal==True:\r\n            print(f\"El vitral {w} tiene simetria horizontal\")\r\n        if d1==True:\r\n            print(f\"El vitral {w} tiene simetria en la diagonal principal\")\r\n        if d2==True:\r\n            print(f\"El vitral {w} tiene simetria en la diagonal secundaria\")\r\n    else:\r\n        print(f\"El vitral {w} no tiene simetrias\")',1551),
(1552,'n = int(input())\r\nfor w in range(n):\r\n    vertical = True\r\n    horizontal = True\r\n    d1 = True\r\n    d2 = True\r\n    l = int(input())\r\n    matriz = [list(map(int, input().split())) for _ in range(l)]\r\n    for i in range(l):\r\n        for j in range(l//2):\r\n            if matriz[i][j]!=matriz[i][l-1-j]:\r\n                vertical = False\r\n                break\r\n    for j in range(l):\r\n        for i in range(l//2):\r\n            if matriz[i][j]!=matriz[l-i-1][j]:\r\n                horizontal = False\r\n                break\r\n    for i in range(l):\r\n        for j in range(i):\r\n            if matriz[i][j]!=matriz[j][i]:\r\n                d1 = False\r\n                break\r\n    for i in range(l):\r\n        for j in range(l):\r\n            if matriz[i][j]!=matriz[l-1-j][l-1-i]:\r\n                d2 = False\r\n                break\r\n    sim = [vertical, horizontal, d1, d2]\r\n    if any(sim)==True:\r\n        if vertical==True:\r\n            print(f\"El vitral {w} tiene simetria vertical\")\r\n        if horizontal==True:\r\n            print(f\"El vitral {w} tiene simetria horizontal\")\r\n        if d1==True:\r\n            print(f\"El vitral {w} tiene simetria en la diagonal principal\")\r\n        if d2==True:\r\n            print(f\"El vitral {w} tiene simetria en la diagonal secundaria\")\r\n    else:\r\n        print(f\"El vitral {w} no tiene simetrias\")',1552),
(1553,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n        break\r\n    matriz=[]\r\n    for i in range(f):\r\n        n=list(map(int, input().strip().split()))\r\n        matriz.append(n)\r\n    matriz_2=[]\r\n    for i in range(f):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz_2.append(m)\r\n    contador=0\r\n    for y in range(f):\r\n      for x in range(c):\r\n        if matriz[y][x]!=matriz_2[y][x]:\r\n            contador+=1\r\n    total_caracteres=f*c\r\n    porcentaje=(contador/total_caracteres)*100\r\nif contador<10:\r\n   print(\"La pintura es original\")\r\nelse:\r\n   print(\"La pintura no es original\")',1553),
(1554,'lista = []\r\nfilas, columnas = map(int, input().split())\r\nmatriz = [list(map(int, input().split())) for _ in range(filas)]\r\n\r\narriba, abajo= 0, filas-1\r\nizq, der = 0, columnas-1\r\n\r\nwhile arriba<=abajo and izq<=der:\r\n    for j in range(izq, der+1):\r\n       lista.append(matriz[arriba][j])\r\n    arriba +=1 \r\n    for i in range(arriba, abajo+1):\r\n        lista.append(matriz[i][der])\r\n    der -=1\r\n    if arriba <= abajo:\r\n        for j in range(der, izq - 1, -1):\r\n            lista.append(matriz[abajo][j])\r\n        abajo -= 1\r\n    if izq<=der:\r\n        for i in range(abajo, arriba-1, -1):\r\n            lista.append(matriz[i][izq])\r\n        izq +=1\r\nprint(*lista)',1554),
(1555,'n,m=list(map(int,input().split())) #filas y columnas de la matriz\r\nterreno=[[0]*m for i in range(n)]\r\nvisitados=[]\r\nparcelas=[]\r\nfor j in range(n):\r\n    #añadir los valores a la matriz\r\n    terreno[j]=list(map(int,input().split()))\r\n\r\ndef Recorrido(iteracion,filas,columnas):\r\n    try:\r\n        for i in range(iteracion,columnas):\r\n            # i es columna final\r\n            visitados.append([iteracion,i])\r\n        for j in range(iteracion+1,filas):\r\n            # j es la fila final\r\n            visitados.append([j,i])\r\n        for k in range(i-1,iteracion-1,-1):\r\n            # k es la columna extremo izquierda de la iteracion\r\n            visitados.append([j,k])\r\n        for l in range(j-1,iteracion,-1):\r\n            visitados.append([l,k])\r\n    except UnboundLocalError:\r\n        return\r\n    return Recorrido(iteracion+1,filas-1,columnas-1)\r\n    \r\nRecorrido(0,n,m)\r\nfor fila in range(len(visitados)):\r\n    parcelas.append(terreno[visitados[fila][0]][visitados[fila][1]])\r\nprint(\" \".join(list(map(str,parcelas))))',1555),
(1556,'n,m=list(map(int,input().split())) #filas y columnas de la matriz\r\nterreno=[[0]*m for i in range(n)]\r\nvisitados=[]\r\nparcelas=[]\r\nfor j in range(n):\r\n    #añadir los valores a la matriz\r\n    terreno[j]=list(map(int,input().split()))\r\n    \r\ndef Recorrido(iteracion,filas,columnas):\r\n    try:\r\n        for i in range(iteracion,columnas):\r\n            if [iteracion,i] in visitados:\r\n                return\r\n            # i es columna final\r\n            visitados.append([iteracion,i])\r\n        for j in range(iteracion+1,filas):\r\n            if [j,i] in visitados:\r\n                return \r\n            # j es la fila final\r\n            visitados.append([j,i])\r\n        for k in range(i-1,iteracion-1,-1):\r\n            if [j,k] in visitados:\r\n                break\r\n            # k es la columna extremo izquierda de la iteracion\r\n            visitados.append([j,k])\r\n        for l in range(j-1,iteracion,-1):\r\n            if [l,k] in visitados:\r\n                break\r\n            visitados.append([l,k])\r\n    except UnboundLocalError:\r\n        return\r\n    return Recorrido(iteracion+1,filas-1,columnas-1)\r\n    \r\nRecorrido(0,n,m)\r\nfor fila in range(len(visitados)):\r\n    parcelas.append(terreno[visitados[fila][0]][visitados[fila][1]])\r\nprint(\" \".join(list(map(str,parcelas))))',1556),
(1557,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n        break\r\n    matriz=[]\r\n    for i in range(f):\r\n        n=list(map(int, input().strip().split()))\r\n        matriz.append(n)\r\n    matriz_2=[]\r\n    for i in range(f):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz_2.append(m)\r\n    contador=0\r\n    for y in range(f):\r\n      for x in range(c):\r\n        if matriz[y][x]!=matriz_2[y][x]:\r\n            contador+=1\r\n    total_caracteres=f*c\r\n    porcentaje=(contador/total_caracteres)*100\r\nif matriz:\r\n   print(\"La pintura es original\")\r\nif contador<10:\r\n   print(\"La pintura es original\")\r\nelse:\r\n   print(\"La pintura no es original\")',1557),
(1558,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n        break\r\n    matriz=[]\r\n    for i in range(f):\r\n        n=list(map(int, input().strip().split()))\r\n        matriz.append(n)\r\n    matriz_2=[]\r\n    for i in range(f):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz_2.append(m)\r\n    contador=0\r\n    for y in range(f):\r\n      for x in range(c):\r\n        if matriz[y][x]!=matriz_2[y][x]:\r\n            contador+=1\r\n    total_caracteres=f*c\r\n    porcentaje=(contador/total_caracteres)*100\r\nif matriz:\r\n   print(\"La pintura es original\")\r\nif contador<=10:\r\n   print(\"La pintura es original\")\r\nelse:\r\n   print(\"La pintura no es original\")',1558),
(1559,'n1,n2=map(int, input().strip().split())\r\nconjunto_1=set()\r\nconjunto_2=set()\r\nfor _ in range(n1):\r\n    a=map(int, input().strip().split())\r\n    conjunto_1.update(a)\r\nfor _ in range(n2):\r\n    b=map(int, input().strip().split())\r\n    conjunto_2.update(b)\r\ninterseccion= conjunto_1 & conjunto_2\r\nprint(len(interseccion))',1559),
(1560,'n1,n2=map(int, input().strip().split())\r\nconjunto_1=set()\r\nconjunto_2=set()\r\nfor _ in range(n1):\r\n    a,b=map(int, input().strip().split())\r\n    conjunto_1.add((a,b))\r\nfor _ in range(n2):\r\n    c,d=map(int, input().strip().split())\r\n    conjunto_2.add((c,d))\r\ninterseccion= conjunto_1 & conjunto_2\r\nprint(len(interseccion))',1560),
(1561,'n = []\r\nwhile True:\r\n    c = input()\r\n    if c==\"0\":\r\n        break\r\n    a,b = c.split()\r\n    a = int(a)\r\n    g = [a,b]\r\n    n.append(g)\r\nn.sort(key=lambda x:x[0])\r\nfor i in n:\r\n    print(i[1])',1561),
(1562,'entrada= int(input())\r\nmatriz=[]\r\nfor _ in range(entrada):\r\n    letras= list(int(input))\r\n    matriz.append(letras)\r\n    for i in range(entrada):\r\n        for j in range (entrada):\r\n            if matriz[i][j-2] == \"T\" and matriz[i][j-1]== \"C\" and matriz[i][j]== \"P\":\r\n                print(\"SI\")\r\n            elif matriz[i-2][j]== \"T\" and matriz[i-1][j]==\"C\" and matriz[i][j]:\r\n                print(\"SI\")\r\n            elif matriz[i-2][j-2]== \"T\" and matriz[i-1][j-1]==\"C\" and matriz[i][j]== \"P\":\r\n                print(\"SI\")\r\n            else:\r\n                print(\"NO\")',1562),
(1563,'entrada= int(input())\r\nmatriz=[]\r\nbooleano= False\r\nfor _ in range(entrada):\r\n    letras= list(input())\r\n    matriz.append(letras)\r\nfor i in range(entrada):\r\n    for j in range (entrada):\r\n        if i>=2 and j>=2:\r\n            if matriz[i][j-2] == \"T\" and matriz[i][j-1]== \"C\" and matriz[i][j]== \"P\":\r\n                booleano=True\r\n                break\r\n            elif matriz[i-2][j]== \"T\" and matriz[i-1][j]==\"C\" and matriz[i][j]==\"P\":\r\n                booleano=True\r\n                break\r\n            elif matriz[i-2][j-2]== \"T\" and matriz[i-1][j-1]==\"C\" and matriz[i][j]== \"P\":\r\n                booleano=True\r\n                break\r\nif booleano==True:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1563),
(1564,'while True:\r\n    filas, columnas= map(int,input().split())\r\n    if filas==0 and columnas==0:\r\n        break\r\n    matrizog=[]\r\n    matrizfake=[]\r\n    contador=0\r\n    for _ in range(filas):\r\n        pixelesog= map(int,input().split())\r\n        matrizog.append(pixelesog)#introduzco datos a matriz real\r\n        pixelesfake=map(int,input().split())\r\n        matrizfake.append(pixelesfake)#introduzco datos a matriz chopechocha\r\n    for i in range(filas):\r\n        for j in range(columnas):\r\n            if matrizog[i][j]!=matrizfake[i][j]:\r\n                contador=contador+1\r\n    total= filas*columnas\r\n    porcentaje= (contador*100)/total\r\n    if porcentaje<=10:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',1564),
(1565,'while True:\r\n    filas, columnas= map(int,input().split())\r\n    if filas==0 and columnas==0:\r\n        break\r\n\r\n    matrizog=[]\r\n    matrizfake=[]\r\n    contador=0\r\n\r\n    for _ in range(filas):\r\n        pixelesog= list(map(int,input().split()))\r\n        matrizog.append(pixelesog)#introduzco datos a matriz real\r\n        pixelesfake= list(map(int,input().split()))\r\n        matrizfake.append(pixelesfake)#introduzco datos a matriz chopechocha\r\n\r\n    for i in range(filas):\r\n        for j in range(columnas):\r\n            if matrizog[i][j]!=matrizfake[i][j]:\r\n                contador=contador+1\r\n\r\n    total= filas*columnas\r\n    porcentaje= (contador*100)/total\r\n    \r\n    if porcentaje<=10:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',1565),
(1566,'while True:\r\n    filas, columnas= map(int,input().split())\r\n    if filas==0 and columnas==0:\r\n        break\r\n\r\n    matrizog=[]\r\n    matrizfake=[]\r\n\r\n    for _ in range(filas):\r\n        pixelesog= list(map(int,input().split()))\r\n        matrizog.append(pixelesog)#introduzco datos a matriz real\r\n        pixelesfake= list(map(int,input().split()))\r\n        matrizfake.append(pixelesfake)#introduzco datos a matriz chopechocha\r\n    contador=0\r\n    for i in range(filas):\r\n        for j in range(columnas):\r\n            if matrizog[i][j]!=matrizfake[i][j]:\r\n                contador=contador+1\r\n\r\n    total= filas*columnas\r\n    porcentaje= (contador*100)/total\r\n\r\n    if porcentaje<=10:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',1566),
(1567,'while True:\r\n    filas, columnas= map(int,input().split())\r\n    if filas==0 and columnas==0:\r\n        break\r\n\r\n    matrizog=[]\r\n    matrizfake=[]\r\n\r\n    for _ in range(filas):\r\n        pixelesog= list(map(int,input().strip().split()))\r\n        matrizog.append(pixelesog)#introduzco datos a matriz real\r\n        pixelesfake= list(map(int,input().strip().split()))\r\n        matrizfake.append(pixelesfake)#introduzco datos a matriz chopechocha\r\n    \r\n    contador = sum(1 for i in range(filas) for j in range(columnas) if matrizog[i][j] != matrizfake[i][j])\r\n\r\n    total= filas*columnas\r\n    porcentaje= (contador*100)/(filas*columnas)\r\n\r\n    if porcentaje<=10:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',1567),
(1568,'texto= input()\r\nn, m = texto.split()\r\nn = int(n)\r\nm = int(m)\r\nesquinas_ana =[]\r\nesquinas_beto = []\r\nfor i in  range (n):\r\n    cosa = input()\r\n    x , y = cosa.split()\r\n    x = int(x)\r\n    y = int(y)\r\n    esquinas_ana.append((x,y))\r\nfor i in range(m):\r\n    coso = input()\r\n    x , y = coso.split()\r\n    x = int(x)\r\n    y = int(y)\r\n    esquinas_beto.append((x,y))\r\nana = set(esquinas_ana)\r\nbeto = set(esquinas_beto)\r\ncomun = ana & beto\r\nprint(len(comun))',1568),
(1569,'while True:\r\n    n , m = map(int, input().split())\r\n    if n == 0 and m == 0:\r\n        break\r\n    pintura = []\r\n    for i in range (n):\r\n        pixeles = []\r\n        z = map(int, input().split())\r\n        for num in z:\r\n            pixeles.append(num)\r\n        pintura.append(pixeles)\r\n    pintura_b = []\r\n    for i in range (n):\r\n        pixeles_b = []\r\n        z = map(int, input().split())\r\n        for num in z:\r\n            pixeles_b.append(num)\r\n        pintura_b.append(pixeles_b)\r\n    error = 0\r\n    for i in range (n):\r\n        for j in range (m):\r\n            if pintura [i][j] !=  pintura_b [i][j]:\r\n                error += 1\r\n    pixeles_totales = n*m\r\n    rango = pixeles_totales/10\r\n    if error <= rango:\r\n        print(\"La pintura es original\")\r\n    elif error > rango:\r\n        print(\"La pintura no es original\")',1569),
