(1575,'entrada= int(input())\r\nfor l in range (entrada):\r\n    matriz=[]\r\n    booleano= True\r\n    booleano2= True\r\n    tamaño= int(input())\r\n\r\n    for i in range(tamaño):\r\n        datos= list(map(int,input().split()))\r\n        matriz.append(datos)     \r\n    zirtam= matriz[::-1]\r\n    zirtam2= [datos[::-1] for datos in matriz]\r\n    \r\n    if matriz== zirtam:\r\n        print(\"el vitral\", l, \"tiene simetria horizontal\")\r\n\r\n    if matriz==zirtam2:\r\n        print(\"el vitral\", l, \"tiene simetria vertical\")\r\n\r\n    for x in range (tamaño):\r\n        for y in range (tamaño):\r\n            if matriz[x][y]!=matriz[y][x]:\r\n                booleano=False\r\n    if booleano==True:\r\n        print(\"el vitral\", l, \"tiene simetria en la diagonal principal\")\r\n\r\n    for x in range (tamaño):\r\n        for y in range (tamaño):\r\n            if matriz[y][x]!=matriz[tamaño - x - 1][tamaño - y - 1]:\r\n                booleano2= False\r\n    if booleano2== True:\r\n        print(\"el vitral\", l, \"tiene simetria en la diagonal secundaria\")\r\n\r\n    if not any ([matriz== zirtam, matriz ==zirtam2, booleano== True, booleano2==True]):\r\n        print (\"el vitral\", l, \"no tiene simetrias\")',1575),
(1576,'entrada= int(input())\r\nfor l in range (entrada):\r\n    matriz=[]\r\n    booleano= True\r\n    booleano2= True\r\n    tamaño= int(input())\r\n\r\n    for i in range(tamaño):\r\n        datos= list(map(int,input().split()))\r\n        matriz.append(datos)     \r\n    zirtam= matriz[::-1]\r\n    zirtam2= [datos[::-1] for datos in matriz]\r\n    \r\n    if matriz== zirtam:\r\n        print(\"El vitral\", l, \"tiene simetria horizontal\")\r\n\r\n    if matriz==zirtam2:\r\n        print(\"El vitral\", l, \"tiene simetria vertical\")\r\n\r\n    for x in range (tamaño):\r\n        for y in range (tamaño):\r\n            if matriz[x][y]!=matriz[y][x]:\r\n                booleano=False\r\n    if booleano==True:\r\n        print(\"El vitral\", l, \"tiene simetria en la diagonal principal\")\r\n\r\n    for x in range (tamaño):\r\n        for y in range (tamaño):\r\n            if matriz[y][x]!=matriz[tamaño - x - 1][tamaño - y - 1]:\r\n                booleano2= False\r\n    if booleano2== True:\r\n        print(\"El vitral\", l, \"tiene simetria en la diagonal secundaria\")\r\n\r\n    if not any ([matriz== zirtam, matriz ==zirtam2, booleano== True, booleano2==True]):\r\n        print (\"El vitral\", l, \"no tiene simetrias\")',1576),
(1577,'entrada= int(input())\r\nfor l in range (entrada):\r\n    matriz=[]\r\n    booleano= True\r\n    booleano2= True\r\n    tamaño= int(input())\r\n\r\n    for i in range(tamaño):\r\n        datos= list(map(int,input().split()))\r\n        matriz.append(datos)     \r\n    zirtam= matriz[::-1]\r\n    zirtam2= [datos[::-1] for datos in matriz]\r\n\r\n    if matriz==zirtam2:\r\n        print(\"El vitral\", l, \"tiene simetria vertical\")\r\n\r\n    if matriz== zirtam:\r\n        print(\"El vitral\", l, \"tiene simetria horizontal\")\r\n\r\n    for x in range (tamaño):\r\n        for y in range (tamaño):\r\n            if matriz[x][y]!=matriz[y][x]:\r\n                booleano=False\r\n    if booleano==True:\r\n        print(\"El vitral\", l, \"tiene simetria en la diagonal principal\")\r\n\r\n    for x in range (tamaño):\r\n        for y in range (tamaño):\r\n            if matriz[y][x]!=matriz[tamaño - x - 1][tamaño - y - 1]:\r\n                booleano2= False\r\n    if booleano2== True:\r\n        print(\"El vitral\", l, \"tiene simetria en la diagonal secundaria\")\r\n\r\n    if not any ([matriz== zirtam, matriz ==zirtam2, booleano== True, booleano2==True]):\r\n        print (\"El vitral\", l, \"no tiene simetrias\")',1577),
(1578,'alumnos = []\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    if entrada == \"0\":\r\n        break\r\n    nota_str, nombre = entrada.split(maxsplit=1)\r\n    nota = int(nota_str)\r\n    alumnos.append((nota, nombre))\r\n\r\nalumnos.sort(key=lambda x: x[0])\r\n\r\nfor nota, nombre in alumnos:\r\n    print(nombre)',1578),
(1579,'import sys\r\ndef contar_primos(n):\r\n    if n < 2:\r\n        return 0\r\n    es_primo = [True] * (n + 1)\r\n    es_primo[0] = es_primo[1] = False\r\n\r\n    p = 2\r\n    while p * p <= n:\r\n        if es_primo[p]:\r\n            for i in range(p * p, n + 1, p):\r\n                es_primo[i] = False\r\n        p += 1\r\n\r\n    return sum(es_primo)\r\n\r\n# Lectura de la entrada estándar y escritura de la salida estándar\r\nif __name__ == \"__main__\":\r\n\r\n    n = int(sys.stdin.read())\r\n    resultado = contar_primos(n)\r\n    print(resultado)',1579),
(1580,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    contador=0\r\n    total_pixeles=f*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    matriz2=[]\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n      for x in range(c):\r\n       if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje<10:\r\n       print(\"La pintura es original\")\r\n    else:\r\n     print(\"La pintura no es original\")',1580),
(1581,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    contador=0\r\n    total_pixeles=f*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    matriz2=[]\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n       for x in range(c):\r\n        if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje>10:\r\n       print(\"La pintura no es original\")\r\n    else:\r\n     print(\"La pintura es original\")',1581),
(1582,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    matriz2=[]\r\n    contador=0\r\n    total_pixeles=f*f + c*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n      for x in range(c):\r\n       if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    print(contador)\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje<10:\r\n       print(\"La pintura es original\")\r\n    else:\r\n     print(\"La pintura no es original\")',1582),
(1583,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    matriz2=[]\r\n    contador=0\r\n    total_pixeles=f*f + c*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n      for x in range(c):\r\n       if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje<10:\r\n       print(\"La pintura es original\")\r\n    else:\r\n     print(\"La pintura no es original\")',1583),
(1584,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    matriz2=[]\r\n    contador=0\r\n    total_pixeles=f*f + c*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n      for x in range(c):\r\n       if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje>10:\r\n       print(\"La pintura es original\")\r\n    else:\r\n     print(\"La pintura no es original\")',1584),
(1585,'# Leer entradas\r\nletras_disponibles = input().strip()\r\nletras_obligatorias = input().strip()\r\nletras_prohibidas = input().strip()\r\nn = int(input().strip())\r\n\r\n# Convertir a conjuntos\r\nL = set(letras_disponibles)\r\nO = set(letras_obligatorias)\r\nP = set(letras_prohibidas)\r\n\r\n# Procesar palabras\r\nvalidas = []\r\nfor _ in range(n):\r\n    palabra = input().strip()\r\n    s = set(palabra)\r\n\r\n    # Verificar condiciones\r\n    if s.issubset(L) and O.issubset(s) and not (s & P):\r\n        validas.append(palabra)\r\n\r\n# Salida\r\nif validas:\r\n    for v in validas:\r\n        print(v)\r\nelse:\r\n    print(\"-\")',1585),
(1586,'# Leer entradas\r\nletras_disponibles = list(input().strip())\r\nletras_obligatorias = list(input().strip())\r\nletras_prohibidas = list(input().strip())\r\nn = int(input().strip())\r\n\r\n# Procesar palabras\r\nvalidas = []\r\nfor _ in range(n):\r\n    palabra = input().strip()\r\n    letras_palabra = list(palabra)\r\n\r\n    # 1) todas las letras de la palabra deben estar en las disponibles\r\n    todas_en_disponibles = all(letra in letras_disponibles for letra in letras_palabra)\r\n\r\n    # 2) todas las letras obligatorias deben estar en la palabra\r\n    contiene_obligatorias = all(letra in letras_palabra for letra in letras_obligatorias)\r\n\r\n    # 3) ninguna letra prohibida puede estar en la palabra\r\n    sin_prohibidas = all(letra not in letras_palabra for letra in letras_prohibidas)\r\n\r\n    if todas_en_disponibles and contiene_obligatorias and sin_prohibidas:\r\n        validas.append(palabra)\r\n\r\n# Salida\r\nif validas:\r\n    for v in validas:\r\n        print(v)\r\nelse:\r\n    print(\"-\")',1586),
(1587,'filas, columnas = map(int, input().split())\r\nmatriz = [list(map(int, input().split())) for _ in range(filas)]\r\n\r\ntop = 0\r\nbottom = filas - 1\r\nleft = 0\r\nright = columnas - 1\r\n\r\nresultado = []\r\n\"\"\"Recorredor profesional de matrices en espiral\"\"\"\r\nwhile top <= bottom and left <= right:\r\n    \r\n    \"\"\"Recorrer hacia derecha\"\"\"\r\n    for i in range(left, right + 1):\r\n        resultado.append(matriz[top][i])\r\n    top += 1\r\n\r\n    \"\"\"Recorrer hacia abajo\"\"\"\r\n    for i in range(top, bottom + 1):\r\n        resultado.append(matriz[i][right])\r\n    right -= 1\r\n\r\n    \"\"\"Recorrer hacia la izquierda\"\"\"\r\n    if top <= bottom:\r\n        for i in range(right, left - 1, -1):\r\n            resultado.append(matriz[bottom][i])\r\n        bottom -= 1\r\n\r\n    \"\"\"Recorrer hacia arriba\"\"\"\r\n    if left <= right:\r\n        for i in range(bottom, top - 1, -1):\r\n            resultado.append(matriz[i][left])\r\n        left += 1\r\nprint(*resultado)',1587),
(1588,'n_casos= int(input())\r\nfor caso in range(n_casos):\r\n    matriz=[]\r\n    dimensiones= int(input())\r\n    for i in range(dimensiones):\r\n        filas = []\r\n        fila = input().split()\r\n        for num in fila:\r\n            filas.append(num)\r\n        matriz.append(filas)\r\n    vertical = True\r\n    horizontal = True\r\n    diagonal = True\r\n    diagonal_second= True\r\n    for i in range(dimensiones):\r\n        for j in range(dimensiones//2):\r\n            if matriz[i][j]!=matriz[i][dimensiones-1-j]:\r\n                vertical = False\r\n    for i in range(dimensiones):\r\n        for j in range(dimensiones//2):\r\n            if matriz[i][j]!=matriz[dimensiones-1-i][j]:\r\n                horizontal = False\r\n    for i in range(dimensiones):\r\n        for j in range(i+1, dimensiones):\r\n            if matriz[i][j]!=matriz[j][i]:\r\n                diagonal = False\r\n    for i in range(dimensiones):\r\n        for j in range(dimensiones):\r\n            if matriz[i][j]!=matriz[dimensiones-1-j][dimensiones-1-i]:\r\n                diagonal_second = False\r\n    if vertical:\r\n        print(f\"El vitral {caso} tiene simetria vertical\")\r\n    if horizontal:\r\n        print(f\"El vitral {caso} tiene simetria horizontal\")\r\n    if diagonal:\r\n        print(f\"El vitral {caso} tiene simetria diagonal principal\")\r\n    if diagonal_second:\r\n        print(f\"El vitral {caso} tiene simetria diagonal secundaria\")\r\n    if vertical == False and horizontal == False and diagonal== False and diagonal_second ==False:\r\n        print(f\"El vitral {caso} no tiene simetrias\")\r\n    print()',1588),
(1589,'n_casos= int(input())\r\nfor caso in range(n_casos):\r\n    matriz=[]\r\n    dimensiones= int(input())\r\n    for i in range(dimensiones):\r\n        filas = []\r\n        fila = input().split()\r\n        for num in fila:\r\n            filas.append(num)\r\n        matriz.append(filas)\r\n    vertical = True\r\n    horizontal = True\r\n    diagonal = True\r\n    diagonal_second= True\r\n    for i in range(dimensiones):\r\n        for j in range(dimensiones//2):\r\n            if matriz[i][j]!=matriz[i][dimensiones-1-j]:\r\n                vertical = False\r\n    for i in range(dimensiones):\r\n        for j in range(dimensiones//2):\r\n            if matriz[i][j]!=matriz[dimensiones-1-i][j]:\r\n                horizontal = False\r\n    for i in range(dimensiones):\r\n        for j in range(i+1, dimensiones):\r\n            if matriz[i][j]!=matriz[j][i]:\r\n                diagonal = False\r\n    for i in range(dimensiones):\r\n        for j in range(dimensiones):\r\n            if matriz[i][j]!=matriz[dimensiones-1-j][dimensiones-1-i]:\r\n                diagonal_second = False\r\n    if vertical:\r\n        print(f\"El vitral {caso} tiene simetria vertical\")\r\n    if horizontal:\r\n        print(f\"El vitral {caso} tiene simetria horizontal\")\r\n    if diagonal:\r\n        print(f\"El vitral {caso} tiene simetria en la diagonal principal\")\r\n    if diagonal_second:\r\n        print(f\"El vitral {caso} tiene simetria en la diagonal secundaria\")\r\n    if vertical == False and horizontal == False and diagonal== False and diagonal_second ==False:\r\n        print(f\"El vitral {caso} no tiene simetrias\")\r\n    print()',1589),
(1590,'n, m, d = map(int, input().split())\r\n\r\nseguidores = [0] * n\r\n\r\nfor _ in range(m):\r\n    a, b = map(int, input().split())\r\n    seguidores[b] += 1\r\n\r\ncontador = 0\r\nfor i in range(n):\r\n    if seguidores[i] >= d:\r\n        contador += 1\r\nprint(contador)',1590),
(1591,'A = int(input())\r\nNegativo= 0\r\nPositivo= 0\r\n\r\nfor i in range(A):\r\n    B = int(input())\r\n    if B < 0:\r\n        Negativo += 1\r\n    elif B > 0:\r\n        Positivo += 1\r\n    \r\n        \r\nprint(f\"{Positivo} {Negativo}\")',1591),
(1592,'entrada=int(input())\r\nlista=[]\r\ntodo= {}\r\nfor _ in range(entrada):\r\n    nombre, notas= input().split()\r\n    notas= float(notas)\r\n    if nombre in todo.keys():\r\n        todo[nombre].append(notas)\r\n    else:\r\n        todo[nombre]= [notas]\r\n    \r\n    \r\n\r\nfor k in sorted(todo):\r\n    if len(todo[k])==3:\r\n        promedio= sum(todo[k])/3\r\n        print(k, f\'{promedio:.2f}\')\r\n    else:\r\n        print(k,\"p\")',1592),
(1593,'a, b = map(int, input().split())\r\nfilas = [list(input()) for _ in range(a)]\r\n\r\ncambio=True\r\nwhile cambio:\r\n    cambio = False\r\n    for i in range(a-2, -1, -1):\r\n        for j in range(b+2):\r\n            if filas[i][j]!=\" \" and filas[i+1][j]==\" \":\r\n                filas[i+1][j]=filas[i][j]\r\n                filas[i][j]=\" \"\r\n                cambio=True\r\nfor i in filas:\r\n    print(\"\".join(i))',1593),
(1594,'N = int(input())\r\n\r\ncasos = [int(input()) for _ in range(N)]\r\n\r\nsuma = {s: [] for s in range(37)}\r\n\r\nfor n in range(9999 + 1):\r\n    s = (n // 1000) + (n // 100 % 10) + (n // 10 % 10) + (n % 10)\r\n    clave = f\"{n:04d}\"\r\n    suma[s].append(clave)\r\n    print(suma)\r\n    print(clave, s)\r\n\r\nfor x in casos:\r\n    if 0 <= x <= 36:\r\n        for clave in suma[x]:\r\n            print(f\"{clave} es una clave de la suerte que suma {x}\")',1594),
(1595,'N = int(input())\r\n\r\ncasos = [int(input()) for _ in range(N)]\r\n\r\nsuma = {s: [] for s in range(37)}\r\n\r\nfor n in range(9999 + 1):\r\n    s = (n // 1000) + (n // 100 % 10) + (n // 10 % 10) + (n % 10)\r\n    clave = f\"{n:04d}\"\r\n    suma[s].append(clave)\r\n\r\nfor x in casos:\r\n    if 0 <= x <= 36:\r\n        for clave in suma[x]:\r\n            print(f\"{clave} es una clave de la suerte que suma {x}\")',1595),
(1596,'# Aqui estoy leyendo la matriz\r\nfilas, columnas = map(int, input().split())\r\n\r\n# despues la construyo como una lista de listas, cabe destacar que cada caracter se guarda individualmente\r\nMatriz = [list(input()) for _ in range(filas)]\r\n\r\n# Aqui tengo un print para ver como se ve la matriz inicial, pero se puede quitar despues para que no interfuiera en la salida\r\n#print(Matriz)\r\n\r\n# Ahora hago la simulacion de la gravedad, el for recorre cada columna de la matriz el +1 es para incluir la ultima columna porque si no no la incluye por alguna razon\r\nfor c in range(columnas+1):\r\n    \r\n    #Aqui creo una lista temporal para guardar los elementos que caen en esa columna\r\n    Matriz_caidos= []\r\n    \r\n    #despues recorro cada fila de la columna actual\r\n    for f in range(filas):\r\n        #aqui verifico si el elemento en la posicion actual no es un espacio vacio ni una barra vertical, ya que las barras no caen y el espacio vacio es donde caen los elementos\r\n        if Matriz[f][c] != \" \" and Matriz[f][c] != \"|\":\r\n            #aqui guardo el elemento que cae en la lista temporal\r\n            Matriz_caidos.append(Matriz[f][c])\r\n            #aqui dejo el espacio vacio en la posicion actual ya que el elemento cayo\r\n            Matriz[f][c] = \" \"\r\n            \r\n    #aqui digo que la fila actual es la ultima fila de la matriz\r\n    fila_actual = filas - 1\r\n    \r\n    #aqui recorro la lista de elementos **caidos* en orden inverso para que el primero que cayo quede en la parte inferior, importante que *t es el elemento que esta cayendo.\r\n    #lo de el orden inverso es porque si no el primero que cae quedaria en la parte superior y el ultimo en la parte inferior\r\n    #y esto se puede verificar con el print que tengo abajo ya que muestra como se van guardando los elementos de forma inversa a la que queremos mostrar\r\n    #print(f\"*{Matriz_caidos}*\")\r\n    for t in reversed(Matriz_caidos):\r\n        #aqui tengo un print para ver como van cayendo los elementos, se puede quitar despues\r\n        #print(fila_actual, c, t)\r\n        \r\n        #aqui tengo un while que verifica que la fila actual no tenga una barra vertical, si tiene una barra vertical significa que el elemento no puede caer ahi\r\n        while fila_actual >= 0 and Matriz[fila_actual][c] == \"|\":\r\n            #aqui resto 1 a la fila actual para seguir buscando una posicion valida\r\n            fila_actual -= 1\r\n            \r\n        #aqui tengo un if que verifica que la fila actual no sea negativa, porque si es negativa significa que el elemento se salio de la matriz\r\n        if fila_actual >= 0:\r\n            #aqui coloco el elemento en la posicion actual de la matriz **ORIGINAL**\r\n            Matriz[fila_actual][c] = t\r\n            #aqui resto 1 a la fila actual para poder seguir colocando elementos en la fila de arriba\r\n            fila_actual -= 1\r\n            \r\n# Finalmente imprimo la matriz resultante despues de aplicar la gravedad\r\nfor fila in Matriz:\r\n    #el \"\".join(fila) es para unir los elementos de la fila en una sola cadena de texto sin espacios entre ellos\r\n    print(\"\".join(fila))',1596),
(1597,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    matriz2=[]\r\n    contador=0\r\n    total_pixeles=f*f + c*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n      for x in range(c):\r\n       if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje<0.1:\r\n       print(\"La pintura es original\")\r\n    else:\r\n     print(\"La pintura no es original\")',1597),
(1598,'while True:\r\n    f,c=map(int, input().strip().split())\r\n    if f==0 and c==0:\r\n       break\r\n    matriz=[]\r\n    matriz2=[]\r\n    contador=0\r\n    total_pixeles=f*f + c*c\r\n    for y in range(f):\r\n     n=list(map(int, input().strip().split()))\r\n     matriz.append(n)\r\n    for x in range(c):\r\n      m=list(map(int, input().strip().split()))\r\n      matriz2.append(m)\r\n    for y in range(f):\r\n      for x in range(c):\r\n       if matriz[y][x]!=matriz2[y][x]:\r\n          contador+=1\r\n    porcentaje = (contador/total_pixeles)*100\r\n    if porcentaje>0.1:\r\n       print(\"La pintura es original\")\r\n    else:\r\n     print(\"La pintura no es original\")',1598),
(1599,'Diccionario={}\r\nA=int(input())\r\nfor i in range(A)\r\n   Nombre, Nota_0 = input().split()\r\n   Nota = int(Nota_0)\r\n   if Nombre in Diccionario:\r\n       Diccionario[Nombre].append(Nota)\r\n   else:\r\n       Diccionario[Nombre] = [Nota]\r\nfor Nombre, Notas in Diccionario.items():\r\n    if len(Notas) == 3:\r\n        promedio = sum(Notas) / len(Notas)\r\n        print(f\"{Nombre} {promedio:.2f}\")\r\n    else:\r\n        print(f\"{Nombre} P\")',1599),
