(1612,'N=int(input())\r\nedades = 0\r\nfor _ in range (N):\r\n    edad=int(input())\r\n    edades += edad\r\nprom = edades / N \r\n\r\nprint (f\"{prom:.2f}\")',1612),
(1613,'def buscar_TCP(sopa, N):\r\n    palabra = \"TCP\"\r\n    largo = len(palabra)\r\n\r\n    for fila in range(N):\r\n        for columna in range(N):\r\n            if columna + largo <= N:\r\n                texto = \"\"\r\n                for k in range(largo):\r\n                    texto += sopa[fila][columna + k]\r\n                    if texto == palabra:\r\n                        return True\r\n            if fila + largo <= N:\r\n                texto = \"\"\r\n                for k in range(largo):\r\n                    texto += sopa[fila + k][columna]\r\n                if texto == palabra:\r\n                    return True\r\n            if fila + largo <= N and columna + largo <= N:\r\n                texto = \"\"\r\n                for k in range(largo):\r\n                    texto += sopa[fila + k][columna + k]\r\n                if texto == palabra:\r\n                    return True\r\n    return False\r\ndef main():\r\n    N = int(input().strip())\r\n    sopa = []\r\n    for _ in range(N):\r\n        linea = input().strip()\r\n        sopa.append(linea)\r\n    encontrado = buscar_TCP(sopa, N)\r\n\r\n    if encontrado:\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")\r\nif __name__ == \"__main__\":\r\n    main()',1613),
(1614,'pesos = 0\r\n\r\nwhile True:\r\n    moneda = int(input())\r\n    if moneda == 0 :\r\n        break\r\n    pesos += moneda\r\n\r\nprint(\"Juanito ha ahorrado:\")\r\nprint(pesos)\r\nprint(\"pesos\")',1614),
(1615,'# Solución simple al problema \r\n\r\n# Leer n y m\r\nn, m = map(int, input().split())\r\n\r\n# Crear tablero vacío\r\ntablero = [[\'.\' for _ in range(n)] for _ in range(n)]\r\n\r\n# Leer marcas\r\nfor _ in range(m):\r\n    T, x, y = input().split()\r\n    x = int(x)\r\n    y = int(y)\r\n    tablero[x][y] = T\r\n\r\n# Función para obtener vecinos válidos (ahora usando return)\r\ndef vecinos(x, y):\r\n    resultado = []\r\n    direcciones = [(-1,0),(1,0),(0,-1),(0,1)]  # N, S, O, E\r\n    for dx, dy in direcciones:\r\n        nx, ny = x + dx, y + dy\r\n        if 0 <= nx < n and 0 <= ny < n:   # Solo se agregan vecinos dentro del tablero\r\n            resultado.append(tablero[nx][ny])\r\n    return resultado\r\n\r\nPX = 0\r\nPO = 0\r\n\r\n# Recorrer tablero\r\nfor i in range(n):\r\n    for j in range(n):\r\n        c = tablero[i][j]\r\n        v = vecinos(i, j)\r\n\r\n        # Regla 1: celda vacía con 3 vecinos iguales\r\n        if c == \'.\':\r\n            if v.count(\'X\') == 3:\r\n                PX += 2\r\n            elif v.count(\'O\') == 3:\r\n                PO += 2\r\n\r\n        # Regla 2: celda marcada rodeada completamente por la contraria\r\n        else:\r\n            if len(v) == 4:  # Solo celdas interiores pueden estar encerradas\r\n                if c == \'X\' and v.count(\'O\') == 4:\r\n                    PO += 1\r\n                elif c == \'O\' and v.count(\'X\') == 4:\r\n                    PX += 1\r\n\r\n# Determinar ganador\r\nif PX > PO:\r\n    ganador = \'X\'\r\nelif PO > PX:\r\n    ganador = \'O\'\r\nelse:\r\n    ganador = \'Empate\'\r\n\r\nprint(PX, PO, ganador)',1615),
(1616,'diccionarios={}\r\ncasos=int(input())\r\nfor _ in range(casos):\r\n    n=input()\r\n    nombre,nota=n.split()\r\n    nota=float(nota)\r\n    if nombre not in diccionarios:\r\n        diccionarios[nombre]=[]\r\n    diccionarios[nombre].append(nota)\r\n    nombre_ordenados=sorted(diccionarios.keys())\r\nfor nombre in nombre_ordenados:\r\n    cantidad_notas=diccionarios[nombre]\r\n    if len(cantidad_notas)==3:\r\n        suma_nota=sum(cantidad_notas)\r\n        promedio=suma_nota/3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n          print(f\"{nombre}, p\")',1616),
(1617,'diccionarios={}\r\ncasos=int(input())\r\nfor _ in range(casos):\r\n    n=input()\r\n    nombre,nota=n.split()\r\n    nota=float(nota)\r\n    if nombre not in diccionarios:\r\n        diccionarios[nombre]=[]\r\n    diccionarios[nombre].append(nota)\r\n    nombre_ordenados=sorted(diccionarios.keys())\r\nfor nombre in nombre_ordenados:\r\n    cantidad_notas=diccionarios[nombre]\r\n    if len(cantidad_notas)==3:\r\n        suma_nota=sum(cantidad_notas)\r\n        promedio=suma_nota/3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n          print(f\"{nombre} p\")',1617),
(1618,'import sys\r\ndiccionarios={}\r\ncasos=int(input())\r\nfor _ in range(casos):\r\n    n=sys.stdin.readline()\r\n    nombre,nota=n.split()\r\n    nota=float(nota)\r\n    if nombre not in diccionarios:\r\n        diccionarios[nombre]=[]\r\n    diccionarios[nombre].append(nota)\r\n    nombre_ordenados=sorted(diccionarios.keys())\r\nfor nombre in nombre_ordenados:\r\n    cantidad_notas=diccionarios[nombre]\r\n    if len(cantidad_notas)==3:\r\n        suma_nota=sum(cantidad_notas)\r\n        promedio=suma_nota/3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n          print(f\"{nombre} p\")',1618),
(1619,'import sys\r\ndiccionarios={}\r\ncasos=int(input())\r\nfor _ in range(casos):\r\n    n=sys.stdin.readline()\r\n    nombre,nota=n.split()\r\n    nota=float(nota)\r\n    if nombre not in diccionarios:\r\n        diccionarios[nombre]=[]\r\n    diccionarios[nombre].append(nota)\r\n    nombre_ordenados=sorted(diccionarios.keys())\r\nfor nombre in nombre_ordenados:\r\n    cantidad_notas=diccionarios[nombre]\r\n    if len(cantidad_notas)==3:\r\n        suma_nota=sum(cantidad_notas)\r\n        promedio=suma_nota/3\r\n        respuesta=f\"{nombre} {promedio:.2f}\"\r\n    else:\r\n        respuesta=f\"{nombre} p\"\r\n    sys.stdout.write(respuesta+\"\\n\")',1619),
(1620,'T=int(input())\r\n\r\ntotal_a_pagar = 0\r\n\r\nfor _ in range (T):\r\n    daño, retraso = input().split()\r\n    retraso = int(retraso)\r\n    if daño == \"B\":\r\n        deuda = 0\r\n    if daño == \"D\":\r\n        deuda = 2000\r\n    elif daño == \"P\":\r\n        deuda = 5000\r\n\r\npago = deuda + (retraso*500)\r\n\r\ntotal_a_pagar += pago\r\n\r\nprint (total_a_pagar)',1620),
(1621,'T=int(input())\r\n\r\ntotal_a_pagar = 0\r\n\r\nfor _ in range (T):\r\n    estado, retraso = input().split()\r\n    retraso = int(retraso)\r\n\r\n    if estado == \"B\":\r\n        deuda = 0\r\n    elif estado == \"D\":\r\n        deuda = 2000\r\n    elif estado == \"P\":\r\n        deuda = 5000\r\n    pago = deuda + (retraso*500)\r\n\r\n    total_a_pagar += pago\r\n\r\nprint (total_a_pagar)',1621),
(1622,'n = int(input())\r\n\r\npalabra = set()                             # se integra todo en un conjunto\r\n\r\nfor _ in range (n):\r\n    conceptos = input().split()             \r\n    for palabras in conceptos:              \r\n        palabra.add(palabras)               # se añade palabras al conjunto\r\n\r\npalabras_en_orden = sorted(palabra)         # se ordenan las palabras \r\n\r\nfor C in palabras_en_orden:\r\n    print(C)',1622),
(1623,'T = int(input())                          # cantidad de idiomas\r\n\r\nfor _ in range(T):   \r\n    N = int(input())                      # palabras en cada idioma\r\n    vocales = 0\r\n                                          \r\n    for _ in range(N):\r\n        palabra = input().strip()\r\n        for letra in palabra:\r\n            if letra in \'aeiou\':          # si la palabra contiene a aeiou suma 1\r\n                vocales += 1\r\n\r\n    promedio = vocales / N\r\n\r\n    print(f\"{promedio:.2f}\")',1623),
(1624,'Contador=0\r\nwhile True:\r\n b,c = map(int, input().split())\r\nif b == 0:\r\n  break   \r\nMatriz=[list(input()) for _ in range(b).split()]\r\nMatriz2=[list(input()) for _ in range(b).split()]\r\nfor i in range(b):\r\nfor j in range(c):\r\n   if Matriz[i][j] != Matriz2 [i][j]:\r\n      Contador+=1\r\nif Contador/(b*c) > 0.1:\r\nprint(\"La pintura no es original\")\r\nelse:\r\nprint(\"La pintura es original\")',1624),
(1625,'Contador=0\r\nwhile True:\r\n b,c = map(int, input().split())\r\nif b == 0:\r\n  break   \r\nMatriz=[list(input()) for _ in range(b).split()]\r\nMatriz2=[list(input()) for _ in range(b).split()]\r\nfor i in range(b):\r\n for j in range(c):\r\n   if Matriz[i][j] != Matriz2 [i][j]:\r\n      Contador+=1\r\nif Contador/(b*c) > 0.1:\r\nprint(\"La pintura no es original\")\r\nelse:\r\nprint(\"La pintura es original\")',1625),
(1626,'Contador=0\r\nwhile True:\r\n b,c = map(int, input().split())\r\n if b == 0:\r\n  break   \r\n Matriz=[list(input()) for _ in range(b).split()]\r\n Matriz2=[list(input()) for _ in range(b).split()]\r\n for i in range(b):\r\n  for j in range(c):\r\n   if Matriz[i][j] != Matriz2 [i][j]:\r\n      Contador+=1\r\n if Contador/(b*c) > 0.1:\r\n  print(\"La pintura no es original\")\r\n else:\r\n  print(\"La pintura es original\")',1626),
(1627,'Contador=0\r\nwhile True:\r\n b,c = map(int, input().split())\r\n if b == 0:\r\n  break   \r\n Matriz=[list(input()) for _ in range(b).split()]\r\n Matriz2=[list(input()) for _ in range(b).split()]\r\n for i in range(b):\r\n    for j in range(c):\r\n        if Matriz[i][j] != Matriz2 [i][j]:\r\n        Contador+=1\r\n if Contador/(b*c) > 0.1:\r\n    print(\"La pintura no es original\")\r\n else:\r\n    print(\"La pintura es original\")',1627),
(1628,'contador = int(input())\r\n\r\nfor a in range(contador):\r\n    Tamaño_matriz = int(input())\r\n    matriz = []\r\n\r\n\r\n    for i in range(Tamaño_matriz):\r\n        entrada = list(map(int, input().strip().split()))\r\n        matriz.append(entrada)\r\n\r\n    \"Vertical\"\r\n    Simetrica_Vertical = True\r\n    for i in matriz:\r\n        if i != i[::-1]:\r\n            Simetrica_Vertical = False\r\n\r\n        \r\n    \"horizontal\"\r\n    Simetrica_Horizontal = True\r\n    if matriz != matriz[::-1]:\r\n        Simetrica_Horizontal = False\r\n\r\n\r\n    \"\"\"Diagonal principal\"\"\"\r\n    Simetrica_Diag_Principal = True\r\n    for i in range(Tamaño_matriz):\r\n        for j in range(Tamaño_matriz):\r\n            if matriz[i][j] != matriz[j][i]:\r\n                Simetrica_Diag_Principal = False\r\n                break\r\n\r\n\r\n    \"\"\"Diagonal secundaria\"\"\"\r\n    Simetrica_Diag_Sec = True\r\n    for i in range(Tamaño_matriz):\r\n        for j in range(Tamaño_matriz):\r\n            if matriz[i][j] != matriz[Tamaño_matriz - 1 - j][Tamaño_matriz - 1 - i]:\r\n                Simetrica_Diag_Sec = False\r\n                break\r\n    \"\"\"Salidas\"\"\"\r\n    if not any([Simetrica_Diag_Principal, Simetrica_Diag_Sec, Simetrica_Horizontal, Simetrica_Vertical]):\r\n        print(f\"El vitral {a} no tiene simetrias\")\r\n    else:\r\n        if Simetrica_Vertical:\r\n            print(f\"El vitral {a} tiene simetria vertical\")\r\n\r\n        if Simetrica_Horizontal:\r\n            print(f\"El vitral {a} tiene simetria horizontal\")\r\n\r\n        if Simetrica_Diag_Principal:\r\n            print(f\"El vitral {a} tiene simetria en la diagonal principal\")\r\n\r\n        if Simetrica_Diag_Sec:\r\n            print(f\"El vitral {a} tiene simetria en la diagonal secundaria\")',1628),
(1629,'# Solución en Python para integrandoalianzas\r\n\r\ntotales = {}\r\nidx = 0\r\n\r\nwhile True:\r\n    linea = input().strip()\r\n    if linea == \"Fin de los juegos\":\r\n        break\r\n    \r\n    alianza, puntaje_str = linea.split()\r\n    puntaje = int(puntaje_str)\r\n\r\n    totales[alianza] = totales.get(alianza, 0) + puntaje\r\n\r\n# Determinar el puntaje máximo y las alianzas campeonas\r\nmax_total = max(totales.values())\r\nganadores = [a for a, total in totales.items() if total == max_total]\r\nganadores.sort()\r\n\r\n# Imprimir resultados\r\nfor a in ganadores:\r\n    print(f\"{a} es la alianza campeona con {max_total} puntos!\")',1629),
(1630,'Contador=0\r\nwhile True:\r\n    b,c = map(int, input().split())\r\n    if b == 0:\r\n    break   \r\n    Matriz=[list(input()) for _ in range(b).split()]\r\n    Matriz2=[list(input()) for _ in range(b).split()]\r\n    for i in range(b):\r\n        for j in range(c):\r\n            if Matriz[i][j] != Matriz2 [i][j]:\r\n                Contador+=1\r\n    if Contador/(b*c) > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1630),
(1631,'Contador=0\r\nwhile True:\r\n    b,c = map(int, input().split())\r\n    if b == 0:\r\n    break   \r\n    Matriz=[list(input()) for _ in range(b).split()]\r\n    Matriz2=[list(input()) for _ in range(c).split()]\r\n    for i in range(b):\r\n        for j in range(c):\r\n            if Matriz[i][j] != Matriz2 [i][j]:\r\n                Contador+=1\r\n    if Contador/(b*c) > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1631),
(1632,'Contador=0\r\nwhile True:\r\n    b,c = map(int, input().split())\r\n    if b == 0:\r\n     break   \r\n    Matriz=[list(input()) for _ in range(b).split()]\r\n    Matriz2=[list(input()) for _ in range(c).split()]\r\n    for i in range(b):\r\n        for j in range(c):\r\n            if Matriz[i][j] != Matriz2 [i][j]:\r\n                Contador+=1\r\n    if Contador/(b*c) > 0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")',1632),
(1633,'entrada = input().strip()\r\n\r\nn,m = map(int, entrada.split())\r\nwhile n != 0 and m != 0:\r\n    matriz0 = []\r\n    matrizN = []\r\n    for i in range(n):\r\n        fila = list(map(int, input().strip().split()))\r\n        \r\n        matriz0.append(fila)\r\n    for i in range (n):\r\n        fila = list(map(int, input().strip().split()))\r\n        matrizN.append(fila)\r\n\r\n    dif = 0\r\n    for i in range (n):\r\n        for j in range(m):\r\n            if matriz0 [i][j] != matrizN[i][j]:\r\n                dif += 1\r\n\r\n    if dif > n*m*0.1:\r\n        print(\"La pintura no es original\")\r\n    else:\r\n        print(\"La pintura es original\")\r\n    entrada = input().strip()\r\n    n,m = map(int, entrada.split())',1633),
(1634,'contador = int(input())\r\n\r\nfor a in range(contador):\r\n    Tamaño_matriz = int(input())\r\n    matriz = []\r\n\r\n\r\n    for i in range(Tamaño_matriz):\r\n        entrada = list(map(int, input().strip().split()))\r\n        matriz.append(entrada)\r\n\r\n    \"Vertical\"\r\n    Simetrica_Vertical = True\r\n    for i in matriz:\r\n        if i != i[::-1]:\r\n            Simetrica_Vertical = False\r\n\r\n        \r\n    \"horizontal\"\r\n    Simetrica_Horizontal = True\r\n    if matriz != matriz[::-1]:\r\n        Simetrica_Horizontal = False\r\n\r\n\r\n    \"\"\"Diagonal principal\"\"\"\r\n    Simetrica_Diag_Principal = True\r\n    for i in range(Tamaño_matriz):\r\n        for j in range(Tamaño_matriz):\r\n            if matriz[i][j] != matriz[j][i]:\r\n                Simetrica_Diag_Principal = False\r\n                break\r\n\r\n\r\n    \"\"\"Diagonal secundaria\"\"\"\r\n    Simetrica_Diag_Sec = True\r\n    for i in range(Tamaño_matriz):\r\n        for j in range(Tamaño_matriz):\r\n            if matriz[i][j] != matriz[Tamaño_matriz - 1 - j][Tamaño_matriz - 1 - i]:\r\n                Simetrica_Diag_Sec = False\r\n                break\r\n    \"\"\"Salidas\"\"\"\r\n    if not any([Simetrica_Diag_Principal, Simetrica_Diag_Sec, Simetrica_Horizontal, Simetrica_Vertical]):\r\n        print(f\"El vitral {a} no tiene simetrias\")\r\n    else:\r\n        if Simetrica_Vertical:\r\n            print(f\"El vitral {a} tiene simetria vertical\")\r\n\r\n        if Simetrica_Horizontal:\r\n            print(f\"El vitral {a} tiene simetria horizontal\")\r\n\r\n        if Simetrica_Diag_Principal:\r\n            print(f\"El vitral {a} tiene simetria en la diagonal principal\")\r\n\r\n        if Simetrica_Diag_Sec:\r\n            print(f\"El vitral {a} tiene simetria en la diagonal secundaria\")',1634),
