(1643,'disponibles= input()\r\nobligatorias= input()\r\nprohibidas= input()\r\nconjunto_disponibles= set(disponibles)\r\nconjunto_obligatorias= set(obligatorias)\r\nconjunto_prohibidas= set(prohibidas)\r\ncantidad= int(input())\r\nconjunto_vacio= set()\r\ncontador= 0\r\nfor i in range(cantidad):\r\n    palabras= input()\r\n    conjunto_palabras= set(palabras)\r\n    if conjunto_disponibles | conjunto_palabras == conjunto_disponibles and conjunto_palabras | conjunto_obligatorias== conjunto_palabras and conjunto_palabras & conjunto_prohibidas == conjunto_vacio:\r\n        print(palabras)\r\n    elif conjunto_disponibles | conjunto_palabras != conjunto_disponibles and conjunto_palabras | conjunto_obligatorias != conjunto_palabras and conjunto_palabras & conjunto_prohibidas != conjunto_vacio:\r\n        contador = contador +1\r\nif contador == cantidad:\r\n    print(\"-\")\r\nelse:\r\n    pass',1643),
(1644,'puntajes = {}\r\nwhile True:\r\n    x = input()\r\n    if x == \"Fin de los juegos\":\r\n        break\r\n    nombre,puntaje = x.split()\r\n    puntaje=int(puntaje)\r\n    puntajes[nombre] = puntajes.setdefault(nombre,0) + puntaje\r\nmax = 0\r\nfor i in puntajes.keys():\r\n    if puntajes[i]>max:\r\n        max = puntajes[i]\r\nganadores = []\r\nfor i in puntajes.keys():\r\n    if puntajes[i]==max:\r\n        ganadores.append(i)\r\nganadores.sort()\r\nfor i in ganadores:\r\n    print(f\"{i} es la alianza campeona con {max} puntos!\")',1644),
(1645,'conjunto_disponibles= set(input())\r\nconjunto_obligatorias= set(input())\r\nconjunto_prohibidas= set(input())\r\nconjunto_vacio= set()\r\ncontador= 0\r\n\r\ncantidad= int(input())\r\n\r\nfor i in range(cantidad):\r\n    palabras= input()\r\n    conjunto_palabras= set(palabras)\r\n    if conjunto_disponibles | conjunto_palabras == conjunto_disponibles and conjunto_palabras | conjunto_obligatorias== conjunto_palabras and conjunto_palabras & conjunto_prohibidas == conjunto_vacio:\r\n        print(palabras)\r\n\r\n    elif conjunto_disponibles | conjunto_palabras != conjunto_disponibles or conjunto_palabras | conjunto_obligatorias != conjunto_palabras or conjunto_palabras & conjunto_prohibidas != conjunto_vacio:\r\n        contador = contador +1\r\n\r\nif contador == cantidad:\r\n    print(\"-\")\r\nelse:\r\n    pass',1645),
(1646,'equipos={}\r\nganadores=[]\r\nwhile True:\r\n    evento=input().split()\r\n    if len(evento)>2:\r\n        break\r\n    alianza,puntaje=evento[0],evento[1]\r\n    puntaje=int(puntaje)\r\n    equipos.setdefault(alianza,[]).append(puntaje)\r\n\r\nfor equipo in equipos:\r\n    puntaje=0\r\n    for nota in equipos[equipo]:\r\n        puntaje=puntaje+nota\r\n    equipos[equipo]=puntaje\r\n    #el diccionario tiene el equipo con su calificacion final\r\nnota_max=max(equipos.values()) #calificacion mas alta\r\nfor equipo in sorted(equipos):\r\n    if equipos[equipo]==nota_max:\r\n        ganadores.append(equipo)\r\nfor equipo in ganadores:\r\n    print(f\"{equipo} es la alianza campeona con {nota_max} puntos!\")',1646),
(1647,'conjunto_disponibles= set(input())\r\nconjunto_obligatorias= set(input())\r\nconjunto_prohibidas= set(input())\r\nconjunto_vacio= set()\r\nbooleano= False\r\n\r\ncantidad= int(input())\r\n\r\nfor i in range(cantidad):\r\n    palabras= input()\r\n    conjunto_palabras= set(palabras)\r\n    if conjunto_disponibles | conjunto_palabras == conjunto_disponibles and conjunto_palabras | conjunto_obligatorias== conjunto_palabras and conjunto_palabras & conjunto_prohibidas == conjunto_vacio:\r\n        booleano=True\r\n        print(palabras)\r\n\r\nif booleano == False:\r\n    print(\"-\")',1647),
(1648,'conjunto_disponibles= set(input())\r\nconjunto_obligatorias= set(input())\r\nconjunto_prohibidas= set(input())\r\nconjunto_vacio= set()\r\nbooleano= False\r\n\r\ncantidad= int(input())\r\n\r\nfor i in range(cantidad):\r\n    palabras= input()\r\n    conjunto_palabras= set(palabras)\r\n    if conjunto_disponibles | conjunto_palabras == conjunto_disponibles:\r\n        if conjunto_palabras | conjunto_obligatorias== conjunto_palabras: \r\n            if conjunto_palabras & conjunto_prohibidas == conjunto_vacio:\r\n                booleano=True\r\n                print(palabras)\r\n\r\nif booleano == False:\r\n    print(\"-\")',1648),
