(1679,'n,m = input().split()\r\nn = int(n)\r\nm = int(m)\r\nw = [[\".\"]*n for _ in range(n)]\r\nfor i in range(m):\r\n    t,x,y = input().split()\r\n    x = int(x)\r\n    y = int(y)\r\n    w[x][y] = t\r\n#no en los bordes\r\nPX = 0\r\nPO = 0\r\n\r\nfor i in range(1,n-1):\r\n    for k in range(1,n-1):\r\n        if w[i][k]==\".\":\r\n            co = 0\r\n            cx = 0\r\n            if w[i+1][k]==\"O\":\r\n                co+=1\r\n            if w[i-1][k]==\"O\":\r\n                co+=1\r\n            if w[i][k+1]==\"O\":\r\n                co+=1\r\n            if w[i][k-1]==\"O\":\r\n                co+=1\r\n            if w[i+1][k]==\"X\":\r\n                cx+=1\r\n            if w[i-1][k]==\"X\":\r\n                cx+=1\r\n            if w[i][k+1]==\"X\":\r\n                cx+=1\r\n            if w[i][k-1]==\"X\":\r\n                cx+=1\r\n            if cx == 3:\r\n                PX+=2\r\n            elif co == 3:\r\n                PO+=2\r\n        else:\r\n            co = 0\r\n            cx = 0\r\n            if w[i][k]==\"X\":\r\n                if w[i+1][k]==\"O\":\r\n                    co+=1\r\n                if w[i-1][k]==\"O\":\r\n                    co+=1\r\n                if w[i][k+1]==\"O\":\r\n                    co+=1\r\n                if w[i][k-1]==\"O\":\r\n                    co+=1\r\n                if co == 4:\r\n                    PO +=1\r\n            else:\r\n                if w[i+1][k]==\"X\":\r\n                    cx+=1\r\n                if w[i-1][k]==\"X\":\r\n                    cx+=1\r\n                if w[i][k+1]==\"X\":\r\n                    cx+=1\r\n                if w[i][k-1]==\"X\":\r\n                    cx+=1\r\n                if co == 4:\r\n                    PX +=1\r\n## Esquinas no puede pasar nada\r\n## aristas\r\n## izquierda\r\nfor i in range(1,n-1):\r\n    if w[i][0]==\".\" and w[i+1][0] == \"X\" and w[i-1][0] == \"X\" and w[i][1] == \"X\":\r\n        PX += 2\r\n    if w[i][0]==\".\" and w[i+1][0] == \"O\" and w[i-1][0] == \"O\" and w[i][1] == \"O\":\r\n        PO += 2\r\n## arriba\r\nfor i in range(1,n-1):\r\n    if w[0][i]==\".\" and w[1][i] == \"X\" and w[0][i-1] == \"X\" and w[0][i+1] == \"X\":\r\n        PX += 2\r\n    if w[0][i]==\".\" and w[1][i] == \"O\" and w[0][i-1] == \"O\" and w[0][i+1] == \"O\":\r\n        PO += 2\r\n## abajo\r\nfor i in range(1,n-1):\r\n    if w[n-1][i]==\".\" and w[n-2][i] == \"X\" and w[n-1][i-1] == \"X\" and w[n-1][i+1] == \"X\":\r\n        PX += 2\r\n    if w[n-1][i]==\".\" and w[n-2][i] == \"O\" and w[n-1][i-1] == \"O\" and w[n-1][i+1] == \"O\":\r\n        PO += 2\r\n## Derecha\r\nfor i in range(1,n-1):\r\n    if w[i][n-1]==\".\" and w[i+1][n-1] == \"X\" and w[i-1][n-1] == \"X\" and w[i][n-2] == \"X\":\r\n        PX += 2\r\n    if w[i][n-1]==\".\" and w[i+1][n-1] == \"O\" and w[i-1][n-1] == \"O\" and w[i][n-2] == \"O\":\r\n        PO += 2\r\nif PO < PX:\r\n    print(f\"{PX} {PO} X\")\r\nif PX < PO:\r\n    print(f\"{PX} {PO} O\")\r\nelse:\r\n    print(f\"{PX} {PO} Empate\")',1679),
