(1706,'N, M = map(int, input().split())\r\n\r\ntablero = [[\'.\' for _ in range(N)] for _ in range(N)]\r\n\r\nfor _ in range(M):\r\n    T, x, y = input().split()\r\n    x, y = int(x), int(y)\r\n    tablero[x][y] = T\r\n\r\ndirs = [(-1, 0), (1, 0), (0, 1), (0, -1)]\r\n\r\nPX = 0\r\nPO = 0\r\n\r\n# Recorrer todas las celdas\r\nfor i in range(N):\r\n    for j in range(N):\r\n        vecinos = []\r\n        for dx, dy in dirs:\r\n            ni, nj = i + dx, j + dy\r\n            if 0 <= ni < N and 0 <= nj < N:\r\n                vecinos.append(tablero[ni][nj])\r\n\r\n        if tablero[i][j] == \'.\':\r\n            if vecinos.count(\'X\') == 3:\r\n                PX += 2\r\n            elif vecinos.count(\'O\') == 3:\r\n                PO += 2\r\n\r\n        elif tablero[i][j] == \'X\':\r\n            if len(vecinos) == 4 and vecinos.count(\'O\') == 4:\r\n                PO += 1\r\n        elif tablero[i][j] == \'O\':\r\n            if len(vecinos) == 4 and vecinos.count(\'X\') == 4:\r\n                PX += 1\r\n\r\nif PX > PO:\r\n    ganador = \'X\'\r\nelif PO > PX:\r\n    ganador = \'O\'\r\nelse:\r\n    ganador = \'Empate\'\r\n\r\nprint(PX, PO, ganador)',1706),
(1707,'def contar(n):\r\n    es_primo = [True] * (n-1)\r\n    es_primo[0] = es_primo[1] = False\r\n\r\n    for i in range(2, int(math.isqrt(n)) + 1):\r\n        if es_primo[i]:\r\n            for j in range(i * j, n + 1, i):\r\n                es_primo[j] = False\r\n    return sum(es_primo)\r\n\r\nif __name__ == \"__main__\":\r\n    n = int(input().strip())\r\n    print(contar(n))',1707),
(1708,'entrada= int(input())\r\nlista=[]\r\ndos=[]\r\ntres=[]\r\ncinco=[]\r\nsiete=[]\r\ncontador=0\r\nfor i in range(entrada):\r\n    lista.append(i+1)\r\nlista.remove(1)\r\n\r\nfor r in range (2, entrada+1, 2):\r\n    dos.append(r)\r\ndos.remove(2)\r\n\r\nfor j in range (3, entrada+1, 3):\r\n    tres.append(j)\r\ntres.remove(3)\r\n\r\nfor h in range(5, entrada+1, 5):\r\n    cinco.append(h)\r\ncinco.remove(5)\r\n\r\nfor p in range(7, entrada+1, 7):\r\n    siete.append(p)\r\nsiete.remove(7)\r\n\r\n\r\nconjunto_total= set(lista)\r\nconjunto_dos= set(dos)\r\nconjunto_tres= set(tres)\r\nconjunto_cinco= set(cinco)\r\nconjunto_siete= set(siete)\r\n\r\n\r\n\r\ncompuestos= conjunto_dos | conjunto_tres | conjunto_cinco | conjunto_siete\r\nprimos= conjunto_total-compuestos\r\n\r\nrecorre= list(primos)\r\nfor _ in range(len(recorre)):\r\n    contador=contador+1\r\nprint(contador)',1708),
(1709,'def palabra_valida(palabra, disponibles, obligatorias, prohibidas):\r\n    \r\n    if not all(c in disponibles for c in palabra):\r\n        return False\r\n    \r\n    if not all(c in palabra for c in obligatorias):\r\n        return False\r\n\r\n    if any(c in palabra for c in prohibidas):\r\n        return False\r\n    \r\n    return True\r\n\r\n\r\ndef main():\r\n    disponibles = input().strip()\r\n    obligatorias = input().strip()\r\n    prohibidas = input().strip()\r\n    n = int(input().strip())\r\n    \r\n    palabras_validas = []\r\n    \r\n    for _ in range(n):\r\n        palabra = input().strip()\r\n        if palabra_valida(palabra, disponibles, obligatorias, prohibidas):\r\n            palabras_validas.append(palabra)\r\n    \r\n    if palabras_validas:\r\n        for p in palabras_validas:\r\n            print(p)\r\n    else:\r\n        print(\"-\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1709),
(1710,'import math\r\n\r\ndef contar(n):\r\n    es_primo = [True] * (n-1)\r\n    es_primo[0] = es_primo[1] = False\r\n\r\n    for i in range(2, int(math.isqrt(n)) + 1):\r\n        if es_primo[i]:\r\n            for j in range(i * j, n + 1, i):\r\n                es_primo[j] = False\r\n    return sum(es_primo)\r\n\r\nif __name__ == \"__main__\":\r\n    n = int(input().strip())\r\n    print(contar(n))',1710),
(1711,'N, M = map(int, input().split())\r\n\r\ntablero = [[\'.\' for _ in range(N)] for _ in range(N)]\r\n\r\nfor _ in range(M):\r\n    T, x, y = input().split()\r\n    x, y = int(x), int(y)\r\n    tablero[x][y] = T\r\n\r\ndirs = [(-1, 0), (1, 0), (0, 1), (0, -1)]\r\n\r\nPX = 0\r\nPO = 0\r\n\r\nfor i in range(N):\r\n    for j in range(N):\r\n        vecinos = []\r\n        for dx, dy in dirs:\r\n            ni, nj = i + dx, j + dy\r\n            if 0 <= ni < N and 0 <= nj < N:\r\n                vecinos.append(tablero[ni][nj])\r\n\r\n        if tablero[i][j] == \'.\':\r\n            if vecinos.count(\'X\') == 3:\r\n                PX += 2\r\n            elif vecinos.count(\'O\') == 3:\r\n                PO += 2\r\n\r\n        elif tablero[i][j] == \'X\':\r\n            if len(vecinos) == 4 and vecinos.count(\'O\') == 4:\r\n                PO += 1\r\n        elif tablero[i][j] == \'O\':\r\n            if len(vecinos) == 4 and vecinos.count(\'X\') == 4:\r\n                PX += 1\r\n\r\nif PX > PO:\r\n    ganador = \'X\'\r\nelif PO > PX:\r\n    ganador = \'O\'\r\nelse:\r\n    ganador = \'Empate\'\r\n\r\nprint(PX, PO, ganador)',1711),
(1712,'num = int(input())\r\ncontador = num+1\r\ncontador_1 = num-1\r\ncantidad_de_prinos = 0\r\nfor i in range(contador_1):\r\n    j = 2\r\n    bandera = False\r\n    i += 3\r\n    while True:\r\n        if i == j:\r\n            break\r\n        elif i%j == 0:\r\n            bandera = True\r\n            break\r\n        else:\r\n            pass\r\n        j +=1\r\n    if bandera == False:\r\n        cantidad_de_prinos+=1\r\n    else:\r\n        pass\r\nprint(cantidad_de_prinos)',1712),
(1713,'entrada= int(input())\r\nlista=[]\r\ndos=[]\r\ntres=[]\r\ncinco=[]\r\nsiete=[]\r\nonce=[]\r\ntrece=[]\r\ndiecisiete= []\r\ndiecinueve= []\r\nveintitres=[]\r\ncontador=0\r\nfor i in range(entrada):\r\n    lista.append(i+1)\r\nlista.remove(1)\r\n\r\nfor r in range (2, entrada+1, 2):\r\n    dos.append(r)\r\ndos.remove(2)\r\n\r\nfor j in range (3, entrada+1, 3):\r\n    tres.append(j)\r\ntres.remove(3)\r\n\r\nfor h in range(5, entrada+1, 5):\r\n    cinco.append(h)\r\ncinco.remove(5)\r\n\r\nfor p in range(7, entrada+1, 7):\r\n    siete.append(p)\r\nsiete.remove(7)\r\n\r\nfor k in range(11, entrada+1, 11):\r\n    siete.append(k)\r\nsiete.remove(11)\r\n\r\nfor a in range(13, entrada+1, 13):\r\n    siete.append(a)\r\nsiete.remove(13)\r\n\r\nfor x in range(17, entrada+1, 17):\r\n    siete.append(x)\r\nsiete.remove(17)\r\n\r\nfor d in range(23, entrada+1, 23):\r\n    siete.append(d)\r\nsiete.remove(23)\r\n\r\n\r\nconjunto_total= set(lista)\r\nconjunto_dos= set(dos)\r\nconjunto_tres= set(tres)\r\nconjunto_cinco= set(cinco)\r\nconjunto_siete= set(siete)\r\nconjunto_once= set(once)\r\nconjunto_trece= set(trece)\r\nconjunto_diecisiete= set(diecisiete)\r\nconjunto_diecinueve= set(diecinueve)\r\nconjunto_veintitres= set(veintitres)\r\n\r\n\r\n\r\ncompuestos= conjunto_dos | conjunto_tres | conjunto_cinco | conjunto_siete | conjunto_once | conjunto_trece | conjunto_diecisiete | conjunto_diecinueve | conjunto_veintitres\r\nprimos= conjunto_total-compuestos\r\n\r\nrecorre= list(primos)\r\nfor _ in range(len(recorre)):\r\n    contador=contador+1\r\nprint(contador)',1713),
