(1716,'c=0\r\nn= int(input())\r\np=2\r\nm=round(n**0.5)\r\nlista = [i for i in range(2,n+1)]\r\nprimos= [i for i in range(2,n+1)]\r\nwhile True:\r\n    if p**2>=n:\r\n        break\r\n    for i in range(p-2, n-1):\r\n        if (i+2)*p in primos:\r\n            primos.remove((i+2)*p)\r\n    c=c+1\r\n    p=primos[c]\r\nprint(len(primos))',1716),
(1717,'entrada= int(input())\r\nlista=[]\r\ndos=[]\r\ntres=[]\r\ncinco=[]\r\nsiete=[]\r\nonce=[]\r\ntrece=[]\r\ndiecisiete= []\r\ndiecinueve= []\r\nveintitres=[]\r\ncontador=0\r\nfor i in range(entrada):\r\n    lista.append(i+1)\r\nlista.remove(1)\r\n\r\nfor r in range (2, entrada+1, 2):\r\n    dos.append(r)\r\ndos.remove(2)\r\n\r\nfor j in range (3, entrada+1, 3):\r\n    tres.append(j)\r\ntres.remove(3)\r\n\r\nfor h in range(5, entrada+1, 5):\r\n    cinco.append(h)\r\ncinco.remove(5)\r\n\r\nfor p in range(7, entrada+1, 7):\r\n    siete.append(p)\r\nsiete.remove(7)\r\n\r\nfor k in range(11, entrada+1, 11):\r\n    once.append(k)\r\nonce.remove(11)\r\n\r\nfor a in range(13, entrada+1, 13):\r\n    trece.append(a)\r\ntrece.remove(13)\r\n\r\nfor x in range(17, entrada+1, 17):\r\n    diecisiete.append(x)\r\ndiecisiete.remove(17)\r\n\r\nfor d in range(23, entrada+1, 23):\r\n    veintitres.append(d)\r\nveintitres.remove(23)\r\n\r\n\r\nconjunto_total= set(lista)\r\nconjunto_dos= set(dos)\r\nconjunto_tres= set(tres)\r\nconjunto_cinco= set(cinco)\r\nconjunto_siete= set(siete)\r\nconjunto_once= set(once)\r\nconjunto_trece= set(trece)\r\nconjunto_diecisiete= set(diecisiete)\r\nconjunto_diecinueve= set(diecinueve)\r\nconjunto_veintitres= set(veintitres)\r\n\r\n\r\n\r\ncompuestos= conjunto_dos | conjunto_tres | conjunto_cinco | conjunto_siete | conjunto_once | conjunto_trece | conjunto_diecisiete | conjunto_diecinueve | conjunto_veintitres\r\nprimos= conjunto_total-compuestos\r\n\r\nrecorre= list(primos)\r\nfor _ in range(len(recorre)):\r\n    contador=contador+1\r\nprint(contador)',1717),
(1718,'entrada= int(input())\r\nlista=[]\r\ncompuestos=[]\r\n\r\ncontador=0\r\nfor i in range(entrada):\r\n    lista.append(i+1)\r\nlista.remove(1)\r\n\r\nfor r in range (2, entrada+1, 2):\r\n    compuestos.append(r)\r\ncompuestos.remove(2)\r\n\r\nfor j in range (3, entrada+1, 3):\r\n    compuestos.append(j)\r\ncompuestos.remove(3)\r\n\r\nfor h in range(5, entrada+1, 5):\r\n    compuestos.append(h)\r\ncompuestos.remove(5)\r\n\r\nfor p in range(7, entrada+1, 7):\r\n    compuestos.append(p)\r\ncompuestos.remove(7)\r\n\r\nfor k in range(11, entrada+1, 11):\r\n    compuestos.append(k)\r\ncompuestos.remove(11)\r\n\r\nfor a in range(13, entrada+1, 13):\r\n    compuestos.append(a)\r\ncompuestos.remove(13)\r\n\r\nfor x in range(17, entrada+1, 17):\r\n    compuestos.append(x)\r\ncompuestos.remove(17)\r\n\r\nfor d in range(23, entrada+1, 23):\r\n    compuestos.append(d)\r\ncompuestos.remove(23)\r\n\r\n\r\nconjunto_total= set(lista)\r\ncompuestos= set(compuestos)\r\n\r\n\r\nprimos= conjunto_total-compuestos\r\n\r\nrecorre= list(primos)\r\nfor _ in range(len(recorre)):\r\n    contador=contador+1\r\nprint(contador)',1718),
(1719,'def es_primo(n):\r\n    if n<2:\r\n        return False\r\n    for i in range(2, int(n**0.5)+1):\r\n        if n%i==0:\r\n            return False\r\n    return True\r\nnumero = int(input())\r\ncant = sum(1 for i in range(2, numero+1) if es_primo(i))\r\nprint(cant)',1719),
(1720,'c=0\r\nn= int(input())\r\np=2\r\nm=round(n**0.5)\r\nprimos= [i for i in range(2,n+1)]\r\nwhile True:\r\n    if p**2>=n:\r\n        break\r\n    for i in range(p-2, n//2):\r\n        if (i+2)*p in primos:\r\n            primos.remove((i+2)*p)\r\n    c=c+1\r\n    p=primos[c]\r\nprint(len(primos))',1720),
(1721,'A={}\r\nB=[]\r\nwhile True:\r\n    z=input()\r\n    if z==\'Fin de los juegos\':\r\n        break\r\n    y,x=z.split()\r\n    x=int(x)\r\n    B.append(y)\r\n    if len(B)==len(set(B)):\r\n        A[y]=x\r\n    else:\r\n        A[y]+=x\r\nf=0\r\nfor n in A:\r\n    if A[n]>f:\r\n        f=A[n]\r\nC=[]\r\nD=list(A)\r\nfor n in A:\r\n    C.append(A[n])\r\nfor m in range(len(C)):\r\n    if int(C[m])==f:\r\n        print(f\'{D[m]} es la alianza campeona con {C[m]} puntos!\')',1721),
(1722,'Contador=0\r\nwhile True:\r\n b,c = map(int, input().split())\r\nif b == 0:\r\n  break\r\n Matriz=[list(input()) for _ in range(b)]\r\n Matriz2=[list(input()) for _ in range(b)]\r\nfor i in range(b):\r\n  for j in range(c):\r\n   if Matriz[i][j] != Matriz2 [i][j]:\r\n      Contador+=1\r\nif Contador/(b*c) > 0.1:\r\n  print(\"La pintura no es original\")\r\nelse:\r\n  print(\"La pintura es original\")',1722),
