(1729,'Contador=0\r\nwhile True:\r\n    try:\r\n        b,c = map(int, input().split())\r\n        if b == 0 and c == 0:\r\n            break\r\n        else:\r\n            Matriz=[list(input()) for _ in range(b)]\r\n            Matriz2=[list(input()) for _ in range(b)]\r\n            Contador = 0\r\n            for i in range(b):\r\n                for j in range(c):\r\n                    if Matriz[i][j] != Matriz2 [i][j]:\r\n                        Contador+=1\r\n            if Contador/(b*c) > 0.1:\r\n                print(\"La pintura no es original\")\r\n            else:\r\n                print(\"La pintura es original\")\r\n    \r\n    except EOFError:\r\n        break',1729),
(1730,'Disponibles=set(input())\r\nObligatorias=set(input())\r\nProhibidas=set(input())\r\nCantidad=int(input())\r\n\r\nfor i in range(Cantidad):\r\n    palabra_original = input()\r\n    Palabras = set(palabra_original)\r\n    if Obligatorias.issubset(Palabras):\r\n        print(palabra_original)',1730),
