(1740,'A={}\r\nB=[]\r\nwhile True:\r\n    z=input()\r\n    if z==\'Fin de los juegos\':\r\n        break\r\n    y,x=z.split()\r\n    x=int(x)\r\n    B.append(y)\r\n    if len(B)==len(set(B)):\r\n        A[y]=x\r\n    else:\r\n        A[y]+=x\r\nf=0\r\nfor n in A:\r\n    if A[n]>f:\r\n        f=A[n]\r\nC=[]\r\nD=list(A)\r\nfor n in A:\r\n    C.append(A[n])\r\nfor m in range(len(C)):\r\n    if int(C[m])==f:\r\n        print(f\'{D[m]} es la alianza campeona con {C[m]} puntos!\')',1740),
(1741,'#include <bits/stdc++.h>\r\n\r\nusing namespace std;\r\n\r\nvoid primos(int n){\r\n    vector<bool> primos(n+1,true);\r\n    primos[0]= false;\r\n    primos[1]= false;\r\n    int p;\r\n    p=2;\r\n    while (p*p<=n){\r\n        if (primos[p]){\r\n            for (int i = p*p; i<n+1 ; i+=p){\r\n                primos[i] = false;\r\n            }\r\n        }\r\n        p++;\r\n    }\r\n    int c=0;\r\n    for (bool x : primos){\r\n        if (x){\r\n            c++;\r\n        }\r\n    }\r\n    cout << c << endl;\r\n}\r\n\r\nint main()\r\n{   \r\n    std::ios::sync_with_stdio(false);\r\n    std::cin.tie(nullptr);\r\n    int n;\r\n    cin >> n;\r\n    primos(n);\r\n    return 0;\r\n}',1741),
