(1758,'lista = []\r\nusados = set()\r\na, b = map(int, input().split())\r\nfor i in range(a, b+1):\r\n    for j in range(i, b+1):\r\n        for h in range(j, b+1):\r\n            z= i**2+j**2+h**2\r\n            k = int(z**0.5)\r\n            if k**2==z and k <= b and k not in usados:\r\n                lista0 = [i, j, h, k]\r\n                lista.append(lista0)\r\n                usados.add(k)\r\nlista = sorted(lista, key=lambda x: x[-1])\r\nfor i in lista:\r\n    print(*i)',1758),
(1759,'import math\r\n\r\nlista = []\r\nusados = set()\r\na, b = map(int, input().split())\r\nfor i in range(a, b+1):\r\n    for j in range(i, b+1):\r\n        for h in range(j, b+1):\r\n            z= i**2+j**2+h**2\r\n            k = math.isqrt(z)\r\n            if k*k==z and k <= b and k not in usados:\r\n                lista0 = [i, j, h, k]\r\n                lista.append(lista0)\r\n                usados.add(k)\r\nlista = sorted(lista, key=lambda x: x[-1])\r\nfor i in lista:\r\n    print(*i)',1759),
(1760,'import math\r\n\r\nlista = []\r\nusados = set()\r\na, b = map(int, input().split())\r\nfor i in range(a, b+1):\r\n    for j in range(i, b+1):\r\n        for h in range(j, b+1):\r\n            z= i**2+j**2+h**2\r\n            k = math.isqrt(z)\r\n            if k*k==z and k <= b and k not in usados and k>h:\r\n                lista0 = [i, j, h, k]\r\n                lista.append(lista0)\r\n                usados.add(k)\r\nlista = sorted(lista, key=lambda x: x[-1])\r\nfor i in lista:\r\n    print(*i)',1760),
(1761,'import math\r\n\r\nlista = []\r\na, b = map(int, input().split())\r\nfor i in range(a, b+1):\r\n    for j in range(i, b+1):\r\n        for h in range(j, b+1):\r\n            z= i**2+j**2+h**2\r\n            k = math.isqrt(z)\r\n            if k*k==z and k <= b and k>h>=j>=i:\r\n                lista0 = [i, j, h, k]\r\n                lista.append(lista0)\r\nlista = sorted(lista, key=lambda x: x[-1])\r\nfor i in lista:\r\n    print(*i)',1761),
(1762,'import math\r\n\r\nlista = []\r\nusados = set()\r\na, b = map(int, input().split())\r\nfor i in range(a, b+1):\r\n    for j in range(i, b+1):\r\n        for h in range(j, b+1):\r\n            z= i**2+j**2+h**2\r\n            k = math.isqrt(z)\r\n            if k*k==z and k <= b and k not in usados:\r\n                lista0 = [i, j, h, k]\r\n                lista.append(lista0)\r\n                usados.add(k)\r\nlista = sorted(lista, key=lambda x: x[-1])\r\nfor i in lista:\r\n    print(*i)',1762),
(1763,'import sys\r\n\r\ndef ask(x, y):\r\n    \"\"\"Imprime una consulta \'? x y\', hace flush y lee la respuesta entera.\"\"\"\r\n    print(f\"? {x} {y}\", flush=True)\r\n    d = sys.stdin.readline()\r\n    if not d:\r\n        # Interactor cerró la tubería (protocolo roto)\r\n        sys.exit(0)\r\n    return int(d.strip())\r\n\r\ndef finish(r, c):\r\n    \"\"\"Entrega la respuesta final y termina.\"\"\"\r\n    print(f\"{r} {c}\", flush=True)\r\n\r\ndef main():\r\n    # 1) Leer N que envía el interactor al inicio\r\n    line = sys.stdin.readline()\r\n    if not line:\r\n        return\r\n    N = int(line.strip())\r\n\r\n    # 2) Dos consultas:\r\n    #    d00 = r + c                (desde (0,0))\r\n    #    dN0 = |r - N| + c = (N - r) + c   (porque 0 <= r <= N)\r\n    d00 = ask(0, 0)\r\n    dN0 = ask(N, 0)\r\n\r\n    # 3) Despejar:\r\n    #    d00 + dN0 = N + 2c  =>  c = (d00 + dN0 - N)/2\r\n    #    r = d00 - c\r\n    #    (tanto r como c deben quedar enteros y dentro de [0, N])\r\n    num = d00 + dN0 - N\r\n    # Fallback si por algún motivo la paridad no cuadra (muy raro):\r\n    if num % 2 != 0:\r\n        # Hacemos una 3ra consulta para estabilizar: d0N = r + (N - c)\r\n        d0N = ask(0, N)\r\n        # Ahora: d0N + d00 = (r + N - c) + (r + c) = 2r + N  => r = (d0N + d00 - N)/2\r\n        r = (d0N + d00 - N) // 2\r\n        # Y c = d00 - r\r\n        c = d00 - r\r\n    else:\r\n        c = num // 2\r\n        r = d00 - c\r\n\r\n    # Seguridad: si por floating/entrada rara quedaran fuera de rango,\r\n    # usamos otra consulta para corregir (no debería ocurrir con un interactor correcto).\r\n    if not (0 <= r <= N and 0 <= c <= N):\r\n        # Consulta extra (4ta) para corregir usando d0N\r\n        d0N = ask(0, N)\r\n        r = (d0N + d00 - N) // 2\r\n        c = d00 - r\r\n        # Asegurar límites\r\n        r = max(0, min(N, r))\r\n        c = max(0, min(N, c))\r\n\r\n    finish(r, c)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1763),
(1764,'# solver.py\r\nimport sys\r\n\r\ndef ask(x, y):\r\n    print(f\"? {x} {y}\", flush=True)\r\n    d = sys.stdin.readline()\r\n    if not d:\r\n        sys.exit(0)\r\n    return int(d.strip())\r\n\r\ndef main():\r\n    # Leer N que envía el interactor\r\n    N_line = sys.stdin.readline()\r\n    if not N_line:\r\n        return\r\n    N = int(N_line.strip())\r\n\r\n    # Dos consultas determinísticas\r\n    d00 = ask(0, 0)   # = r + c\r\n    dN0 = ask(N, 0)   # = (N - r) + c  (porque 0 <= r <= N)\r\n\r\n    # Despeje exacto (sin fallback, siempre es par):\r\n    # d00 + dN0 - N = 2c  -> c\r\n    c = (d00 + dN0 - N) // 2\r\n    r = d00 - c\r\n\r\n    # Terminar\r\n    print(f\"{r} {c}\", flush=True)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1764),
(1765,'# solver.py\r\nimport sys\r\n\r\ndef ask(x, y):\r\n    print(f\"? {x} {y}\", flush=True)\r\n    d = sys.stdin.readline()\r\n    if not d:\r\n        sys.exit(0)\r\n    return int(d.strip())\r\n\r\ndef main():\r\n    N_line = sys.stdin.readline()\r\n    if not N_line:\r\n        return\r\n    N = int(N_line.strip())\r\n\r\n    d00 = ask(0, 0)    # r + c\r\n    dN0 = ask(N, 0)    # (N - r) + c\r\n\r\n    c = (d00 + dN0 - N) // 2\r\n    r = d00 - c\r\n\r\n    print(f\"{r} {c}\", flush=True)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1765),
(1766,'# solver.py (versión \"compatible\" que finaliza con \"! r c\")\r\nimport sys\r\n\r\ndef ask(x, y):\r\n    # Imprime la consulta y hace flush\r\n    print(f\"? {x} {y}\", flush=True)\r\n    d = sys.stdin.readline()\r\n    if not d:\r\n        # Si el interactor cerró, salimos sin ruido\r\n        sys.exit(0)\r\n    # Convertir a int (ignorando espacios/lineas)\r\n    return int(d.strip())\r\n\r\ndef finish(r, c):\r\n    # Final con prefijo \"!\" para máxima compatibilidad\r\n    print(f\"! {r} {c}\", flush=True)\r\n\r\ndef main():\r\n    # Leer N del interactor (primera línea)\r\n    N_line = sys.stdin.readline()\r\n    if not N_line:\r\n        return\r\n    N = int(N_line.strip())\r\n\r\n    # Dos consultas determinísticas\r\n    d00 = ask(0, 0)    # = r + c\r\n    dN0 = ask(N, 0)    # = (N - r) + c  (porque 0 <= r <= N)\r\n\r\n    # Despeje exacto\r\n    c = (d00 + dN0 - N) // 2\r\n    r = d00 - c\r\n\r\n    # Entregar la respuesta final\r\n    finish(r, c)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',1766),
(1767,'letras_disponibles= input()\r\nletras_obligatorias= input()\r\nletras_prohibidas= input()\r\nL = set(letras_disponibles)\r\nO =set(letras_obligatorias)\r\nP =set(letras_prohibidas)\r\nprint(P)\r\nvalidas = []\r\ncant = int(input())\r\nfor _ in range (cant):\r\n    palabra = input()\r\n    PAL = set(palabra)\r\n    if PAL.issubset(L) and PAL & O == set () and P & PAL == PAL:\r\n        validas.append(palabra)\r\nif validas:\r\n    for i in validas:\r\n        print(i)\r\nelse:\r\n    print(\"-\")',1767),
(1768,'letras_disponibles= input()\r\nletras_obligatorias= input()\r\nletras_prohibidas= input()\r\nL = set(letras_disponibles)\r\nO =set(letras_obligatorias)\r\nP =set(letras_prohibidas)\r\n\r\nvalidas = []\r\ncant = int(input())\r\nfor _ in range (cant):\r\n    palabra = input()\r\n    PAL = set(palabra)\r\n    if PAL.issubset(L) and PAL & O == set () and P & PAL == PAL:\r\n        validas.append(palabra)\r\nif validas:\r\n    for i in validas:\r\n        print(i)\r\nelse:\r\n    print(\"-\")',1768),
(1769,'letras_disponibles= input()\r\nletras_obligatorias= input()\r\nletras_prohibidas= input()\r\nL = set(letras_disponibles)\r\nO =set(letras_obligatorias)\r\nP =set(letras_prohibidas)\r\n\r\nvalidas = []\r\ncant = int(input())\r\nfor _ in range (cant):\r\n    palabra = input()\r\n    PAL = set(palabra)\r\n    if PAL.issubset(L) and PAL & P == set () and O & PAL == PAL:\r\n        validas.append(palabra)\r\nif validas:\r\n    for i in validas:\r\n        print(i)\r\nelse:\r\n    print(\"-\")',1769),
(1770,'letras_disponibles= input()\r\nletras_obligatorias= input()\r\nletras_prohibidas= input()\r\nL = set(letras_disponibles)\r\nO =set(letras_obligatorias)\r\nP =set(letras_prohibidas)\r\n\r\nvalidas = []\r\ncant = int(input())\r\nfor _ in range (cant):\r\n    palabra = input()\r\n    PAL = set(palabra)\r\n    if PAL.issubset(L) and PAL & P == set () and O.issubset(PAL):\r\n        validas.append(palabra)\r\nif validas:\r\n    for i in validas:\r\n        print(i)\r\nelse:\r\n    print(\"-\")',1770),
(1771,'# Script Criba de Eratóstenes\r\n# Lee un entero n por stdin y escribe el resultado por stdout.\r\n\r\nimport sys\r\n\r\n# Leer n (permite espacios/saltos de línea)\r\ndata = sys.stdin.read().strip()\r\nn = int(data) if data else 0\r\n\r\n# Caso trivial: no hay primos menores que 2\r\nif n < 2:\r\n    print(0)\r\n    sys.exit(0)\r\n\r\n# es_primo[i] indica si i es primo\r\nes_primo = [True] * (n + 1)\r\nes_primo[0] = False\r\nes_primo[1] = False\r\n\r\n# Solo necesitamos probar p hasta floor(sqrt(n))\r\nlimite = int(n ** 0.5)\r\nfor p in range(2, limite + 1):\r\n    if es_primo[p]:\r\n        # Tachar múltiplos de p comenzando en p*p\r\n        i = p * p\r\n        while i <= n:\r\n            es_primo[i] = False\r\n            i += p\r\n\r\n# Contar cuántos True quedaron (primos ≤ n)\r\ncontador = 0\r\nfor v in es_primo:\r\n    if v:\r\n        contador += 1\r\n\r\nprint(contador)',1771),
(1772,'# Script simple: cuenta cuántos números primos hay ≤ n (Criba de Eratóstenes)\r\n# Lee un entero n por stdin y escribe el resultado por stdout.\r\n\r\nimport sys\r\n\r\n# Leer n (permite espacios/saltos de línea)\r\ndata = sys.stdin.read().strip()\r\nn = int(data) if data else 0\r\n\r\n# es_primo[i] indica si i es primo\r\nes_primo = [True] * (n + 1)\r\nes_primo[0] = False\r\nes_primo[1] = False\r\n\r\n# Solo necesitamos probar p hasta floor(sqrt(n))\r\n\r\np = 2\r\nwhile p**p <= n:\r\n    if es_primo[p]:\r\n        # Tachar múltiplos de p comenzando en p*p\r\n        i = p * p\r\n        while i <= n:\r\n            es_primo[i] = False\r\n            i += p\r\n    p += 1\r\n\r\n# Contar cuántos True quedaron (primos ≤ n) usando while\r\ncontador = 0\r\nidx = 0\r\nwhile idx <= n:\r\n    if es_primo[idx]:\r\n        contador += 1\r\n    idx += 1\r\n\r\nprint(contador)',1772),
(1773,'# Script simple: cuenta cuántos números primos hay ≤ n (Criba de Eratóstenes)\r\n# Lee un entero n por stdin y escribe el resultado por stdout.\r\n\r\nimport sys\r\n\r\n# Leer n (permite espacios/saltos de línea)\r\ndata = sys.stdin.read().strip()\r\nn = int(data) if data else 0\r\n\r\n# es_primo[i] indica si i es primo\r\nes_primo = [True] * (n + 1)\r\nes_primo[0] = False\r\nes_primo[1] = False\r\n\r\n# Solo necesitamos probar p hasta floor(sqrt(n))\r\n\r\np = 2\r\nwhile p**p < n:\r\n    if es_primo[p]:\r\n        # Tachar múltiplos de p comenzando en p*p\r\n        i = p * p\r\n        while i <= n:\r\n            es_primo[i] = False\r\n            i += p\r\n    p += 1\r\n\r\n# Contar cuántos True quedaron (primos ≤ n) usando while\r\ncontador = 0\r\nidx = 0\r\nwhile idx <= n:\r\n    if es_primo[idx]:\r\n        contador += 1\r\n    idx += 1\r\n\r\nprint(contador)',1773),
(1774,'import sys\r\n\r\n# Leemos un entero n desde la entrada estándar (posibles espacios/saltos de línea)\r\nn = int(sys.stdin.read())\r\n\r\n# es_primo[i] indicará si i es primo. Inicialmente asumimos True para 0..n\r\nes_primo = [True] * (n + 1)\r\n# Por definición, 0 y 1 no son primos\r\nes_primo[0] = es_primo[1] = False\r\n\r\n# Criba de Eratóstenes:\r\n# Solo necesitamos probar p hasta p*p <= n (equivalente a p <= sqrt(n))\r\np = 2\r\nwhile p * p <= n:\r\n    # Si p sigue marcado como primo, \"tachamos\" sus múltiplos\r\n    if es_primo[p]:\r\n        # Empezamos desde p*p (los múltiplos menores ya fueron tachados por primos menores)\r\n        for i in range(p * p, n + 1, p):\r\n            es_primo[i] = False\r\n    p += 1  # probamos el siguiente p\r\n\r\n# La cantidad de primos ≤ n es el número de True en es_primo\r\nprint(sum(es_primo))',1774),
(1775,'# Solución en Python para “integrandoalianzas”\r\n# Objetivo (según enunciado):\r\n# - Leer pares \"ALIANZA PUNTAJE\" (la alianza es una palabra sin espacios; el puntaje es entero y puede ser negativo).\r\n# - Acumular el puntaje total por alianza (una alianza puede aparecer múltiples veces).\r\n# - Al terminar (línea exacta \"Fin de los juegos\"), encontrar la(s) alianza(s) con mayor total.\r\n# - Si hay empate en el total máximo, ganan todas esas alianzas (en orden alfabético).\r\n# - Imprimir una línea por cada campeona: \"<ALIANZA> es la alianza campeona con X puntos!\"\r\n\r\ntotales = {}   # Diccionario: nombre_alianza -> puntaje_total_acumulado\r\nidx = 0        # Variable no utilizada en esta solución; puede eliminarse sin afectar la lógica.\r\n\r\nwhile True:\r\n    linea = input().strip()  # Leemos una línea y quitamos espacios de los extremos\r\n    if linea == \"Fin de los juegos\":\r\n        # Condición de término exacta \r\n        break\r\n    \r\n    # La entrada válida tiene el formato: ALIANZA PUNTAJE\r\n    # Donde ALIANZA no tiene espacios; por eso un split() simple en dos partes es suficiente.\r\n    alianza, puntaje_str = linea.split()\r\n    puntaje = int(puntaje_str)  # Puede ser negativo (penalizaciones heroicas)\r\n\r\n    # Acumulamos el puntaje de la alianza:\r\n    # - Si la alianza no existe aún, partimos en 0.\r\n    # - Sumamos el puntaje (positivo o negativo) al total ya registrado.\r\n    totales[alianza] = totales.get(alianza, 0) + puntaje\r\n\r\n# Al salir del bucle, ya tenemos los totales por alianza.\r\n\r\n# 1) Hallamos el valor máximo de puntaje total alcanzado por alguna alianza.\r\nmax_total = max(totales.values())\r\n\r\n# 2) Recolectamos todas las alianzas cuyo total == max_total (para manejar empates).\r\nganadores = [a for a, total in totales.items() if total == max_total]\r\n\r\n# 3) En caso de empate, se imprimen todas en orden alfabético.\r\nganadores.sort()\r\n\r\n# 4) Salida: una línea por ganadora, exactamente con el formato pedido.\r\nfor a in ganadores:\r\n    print(f\"{a} es la alianza campeona con {max_total} puntos!\")',1775),
(1776,'# CompletaPalabras — Validador de palabras para el aniversario de Ingeniería de Matemática\r\n# Enunciado (resumen operativo):\r\n# - Dado un conjunto de letras disponibles (L), un conjunto de letras obligatorias (O) y un conjunto de letras prohibidas (P),\r\n#   debemos filtrar una lista de palabras candidatas y mostrar solo las que:\r\n#   (1) usan exclusivamente letras de L,\r\n#   (2) contienen todas las letras de O al menos una vez,\r\n#   (3) no contienen ninguna letra de P.\r\n# - Si no hay palabras válidas, imprimir un guion \"-\".\r\n\r\n# --- Entrada ---\r\n# 1) Cadena con letras disponibles (no vacía).\r\nletras_disponibles = input().strip()\r\n# 2) Cadena con letras obligatorias (puede ser vacía).\r\nletras_obligatorias = input().strip()\r\n# 3) Cadena con letras prohibidas (puede ser vacía).\r\nletras_prohibidas = input().strip()\r\n# 4) Entero n: cantidad de palabras candidatas.\r\nn = int(input().strip())\r\n\r\n# --- Normalización a conjuntos ---\r\n# Usamos \'set\' para operaciones de pertenencia y contención en tiempo eficiente.\r\n# L: universo permitido; O: debe estar contenido en cada palabra; P: letras vetadas.\r\nL = set(letras_disponibles)\r\nO = set(letras_obligatorias)\r\nP = set(letras_prohibidas)\r\n\r\n# --- Procesamiento de palabras ---\r\nvalidas = []\r\nfor _ in range(n):\r\n    palabra = input().strip()\r\n    s = set(palabra)  # Conjunto de letras efectivamente usadas en la palabra\r\n\r\n    # Condición (1): todas las letras de la palabra están en L  → s ⊆ L\r\n    # Condición (2): todas las obligatorias están presentes     → O ⊆ s\r\n    # Condición (3): no incluye prohibidas                      → s ∩ P = ∅  (equivale a \"not (s & P)\")\r\n    if s.issubset(L) and O.issubset(s) and not (s & P):\r\n        validas.append(palabra)\r\n\r\n# --- Salida ---\r\n# Imprimir cada palabra válida en su propia línea; si no hay, imprimir \"-\"\r\nif validas:\r\n    for v in validas:\r\n        print(v)\r\nelse:\r\n    print(\"-\")',1776),
(1777,'Lista_1=[]\r\nLista_2=[]\r\nA,  B =map(int, input().split ())\r\nfor i in range(A):\r\n j=input()\r\n Lista_1.append(j)\r\nfor i in range(B):\r\n k=input()\r\n Lista_2.append(k)\r\n\r\ncontador = 0\r\nfor item in Lista_1:\r\n    if item in Lista_2:\r\n        contador += 1\r\n        \r\nprint (contador)',1777),
(1778,'Lista_1=[]\r\npotter=[]\r\nA,  B =map(int, input().split ())\r\nfor i in range(A):\r\n j=input()\r\n Lista_1.append(j)\r\nfor i in range(B):\r\n k=input()\r\n potter.append(k)\r\n\r\nset_Lista_1 = set(Lista_1)\r\nset_potter = set(potter)\r\n\r\nDementores = set_Lista_1.intersection(set_potter)\r\n\r\ncontador = len(Dementores)\r\n\r\nprint(contador)',1778),
(1779,'puntajes = {}\r\nwhile True:\r\n    linea = input()\r\n    if linea  == \"Fin de los juegos\":\r\n        break\r\n    nombre, puntaje = linea.split()\r\n    puntaje = int(puntaje)\r\n    puntajes[nombre]= puntajes.get(nombre, 0) +puntaje\r\npuntaje_max = max(puntajes.values())\r\nganadores = [nombre for nombre, total in puntajes.items() if total==puntaje_max]\r\nfor _ in ganadores:\r\n    print(f\"{_} es la alianza campeona con {puntaje_max} puntos!\")',1779),
(1780,'puntajes = {}\r\nwhile True:\r\n    linea = input()\r\n    if linea  == \"Fin de los juegos\":\r\n        break\r\n    nombre, puntaje = linea.split()\r\n    puntaje = int(puntaje)\r\n    puntajes[nombre]= puntajes.get(nombre, 0) +puntaje\r\npuntaje_max = max(puntajes.values())\r\nganadores = sorted([nombre for nombre, total in puntajes.items() if total==puntaje_max])\r\n\r\nfor _ in ganadores:\r\n    print(f\"{_} es la alianza campeona con {puntaje_max} puntos!\")',1780),
(1781,'Contador0=0\r\nContador1=0\r\nContador2=0\r\nwhile True:\r\n J=input()\r\nif J == \"Tiempo\":\r\n   break\r\nif J == \"A\":\r\n  Contador0+=1\r\nelif J ==\"B\":\r\n  Contador1+= 1\r\nelif J ==\"C\":\r\n  Contador2+=1\r\nprint(f\"Andrea {Contador0}\")\r\nprint(f\"Bruno {Contador1}\")\r\nprint(f\"Camila {Contador2}\")',1781),
(1782,'Contador0=0\r\nContador1=0\r\nContador2=0\r\nwhile True:\r\n J=input()\r\n if J == \"Tiempo\":\r\n   break\r\nif J == \"A\":\r\n  Contador0+=1\r\nelif J ==\"B\":\r\n  Contador1+= 1\r\nelif J ==\"C\":\r\n  Contador2+=1\r\nprint(f\"Andrea {Contador0}\")\r\nprint(f\"Bruno {Contador1}\")\r\nprint(f\"Camila {Contador2}\")',1782),
(1783,'Contador0=0\r\nContador1=0\r\nContador2=0\r\nwhile True:\r\n    J=input()\r\n    if J == \"Tiempo\":\r\n       break\r\n    if J == \"A\":\r\n       Contador0+=1\r\n    elif J ==\"B\":\r\n       Contador1+= 1\r\n    elif J ==\"C\":\r\n       Contador2+=1\r\nprint(f\"Andrea {Contador0}\")\r\nprint(f\"Bruno {Contador1}\")\r\nprint(f\"Camila {Contador2}\")',1783),
(1784,'Contador=0\r\nwhile True:\r\n    try:\r\n        b,c = map(int, input().split())\r\n        if b == 0 and c == 0:\r\n            break\r\n        else:\r\n            Matriz=[list(input()) for _ in range(b)]\r\n            Matriz2=[list(input()) for _ in range(b)]\r\n            Contador = 0\r\n            for i in range(b):\r\n                for j in range(c):\r\n                    if Matriz[i][j] != Matriz2 [i][j]:\r\n                        Contador+=1\r\n        if Contador/(b*c) > 0.1:\r\n                print(\"La pintura no es original\")\r\n        else:\r\n                print(\"La pintura es original\")\r\n    \r\n    except EOFError:\r\n        break',1784),
(1785,'Cap=int(input())\r\nJugo=int(input())\r\nVaso = Jugo // Cap\r\nSobrante = Jugo % Cap\r\nprint(f\"{Vaso} {Sobrante}\")',1785),
(1786,'lista=[]\r\n\r\npi=3.141592\r\n\r\nr1, r2, r3, r4= map(float,input().split())\r\n\r\np1, p2, p3, p4= map(float, input().split())\r\n\r\na1= pi*r1**2\r\n\r\na2= pi*r2**2\r\n\r\na3= pi*r3**2\r\n\r\na4= pi*r4**2\r\n\r\nv1= p1/a1\r\n\r\nv2= p2/a2\r\n\r\nv3= p3/a3\r\n\r\nv4= p4/a4\r\n\r\nlista.append(v1)\r\n\r\nlista.append(v2)\r\n\r\nlista.append(v3)\r\n\r\nlista.append(v4)\r\n\r\nlista.sort(reverse=True)\r\n\r\nif lista[-1] == v1:\r\n    print(\"Pequeña\")\r\nelif lista[-1] == v2:\r\n    print(\"Mediana\")\r\nelif lista[-1] == v3:\r\n    print(\"Grande\")\r\nelif lista[-1] == v4:\r\n    print(\"Familiar\")',1786),
(1787,'lista=[]\r\n\r\npi=3.141592\r\n\r\nr1, r2, r3, r4= map(float,input().split())\r\n\r\np1, p2, p3, p4= map(float, input().split())\r\n\r\na1= pi*r1**2\r\n\r\na2= pi*r2**2\r\n\r\na3= pi*r3**2\r\n\r\na4= pi*r4**2\r\n\r\nv1= p1/a1\r\n\r\nv2= p2/a2\r\n\r\nv3= p3/a3\r\n\r\nv4= p4/a4\r\n\r\nlista.append(v1)\r\n\r\nlista.append(v2)\r\n\r\nlista.append(v3)\r\n\r\nlista.append(v4)\r\n\r\nlista.sort(reverse=True)\r\n\r\nif lista[-1] == v1:\r\n    print(\"pequeña\")\r\nelif lista[-1] == v2:\r\n    print(\"mediana\")\r\nelif lista[-1] == v3:\r\n    print(\"grande\")\r\nelif lista[-1] == v4:\r\n    print(\"familiar\")',1787),
(1788,'Diccionario = {}\r\nwhile True:\r\n    try:\r\n        Light = input()\r\n        if Light = \"Fin de los juegos\":\r\n            break\r\n        \r\n        Equipo, Puntos = Light.split()\r\n        Puntos_sr = float(Puntos)\r\n        if Equipo in Diccionario:\r\n            Diccionario[Equipo].append(Puntos_sr)\r\n        else:\r\n            Diccionario[Equipo] = [Puntos_sr]\r\n        except ValueError:\r\n        pass\r\n\r\n\r\n\r\n\r\n\r\nalianza_totales = {}\r\nfor Equipo, Puntos_list in Diccionario.items():\r\n    alianza_totales[Equipo] = sum(Puntos_list)\r\n\r\n\r\nif alianza_totales:\r\n    max_puntos = max(alianza_totales.values())\r\n\r\n\r\n    alianzas_ganadoras = [Equipo for Equipo, total in alianza_totales.items() if total == max_puntos]\r\n\r\n\r\n    alianzas_ganadoras.sort()\r\n\r\n\r\n    for Equipo in alianzas_ganadoras:\r\n        print(f\"{Equipo} es la alianza campeona con {max_puntos} puntos\")',1788),
(1789,'Diccionario = {}\r\nwhile True:\r\n    try:\r\n        Light = input()\r\n        if Light == \"Fin de los juegos\":\r\n            break\r\n        \r\n        Equipo, Puntos = Light.split()\r\n        Puntos_sr = float(Puntos)\r\n        if Equipo in Diccionario:\r\n            Diccionario[Equipo].append(Puntos_sr)\r\n        else:\r\n            Diccionario[Equipo] = [Puntos_sr]\r\n        except ValueError:\r\n        pass\r\n\r\n\r\n\r\n\r\n\r\nalianza_totales = {}\r\nfor Equipo, Puntos_list in Diccionario.items():\r\n    alianza_totales[Equipo] = sum(Puntos_list)\r\n\r\n\r\nif alianza_totales:\r\n    max_puntos = max(alianza_totales.values())\r\n\r\n\r\n    alianzas_ganadoras = [Equipo for Equipo, total in alianza_totales.items() if total == max_puntos]\r\n\r\n\r\n    alianzas_ganadoras.sort()\r\n\r\n\r\n    for Equipo in alianzas_ganadoras:\r\n        print(f\"{Equipo} es la alianza campeona con {max_puntos} puntos\")',1789),
(1790,'Diccionario = {}\r\nwhile True:\r\n\r\n        Light = input()\r\n        if Light == \"Fin de los juegos\":\r\n            break\r\n\r\n        Equipo, Puntos = Light.split()\r\n        Puntos_sr = float(Puntos)\r\n        if Equipo in Diccionario:\r\n            Diccionario[Equipo].append(Puntos_sr)\r\n        else:\r\n            Diccionario[Equipo] = [Puntos_sr]\r\n\r\n\r\n\r\nalianza_totales = {}\r\nfor Equipo, Puntos_list in Diccionario.items():\r\n    alianza_totales[Equipo] = sum(Puntos_list)\r\n\r\n\r\nif alianza_totales:\r\n    max_puntos = max(alianza_totales.values())\r\n\r\n\r\n    alianzas_ganadoras = [Equipo for Equipo, total in alianza_totales.items() if total == max_puntos]\r\n\r\n\r\n    alianzas_ganadoras.sort()\r\n\r\n    \r\n    for Equipo in alianzas_ganadoras:\r\n        print(f\"{Equipo} es la alianza campeona con {max_puntos} puntos!\")',1790),
(1791,'Diccionario = {}\r\nwhile True:\r\n\r\n        Light = input()\r\n        if Light == \"Fin de los juegos\":\r\n            break\r\n\r\n        Equipo, Puntos = Light.split()\r\n        Puntos_sr = float(Puntos)\r\n        if Equipo in Diccionario:\r\n            Diccionario[Equipo].append(Puntos_sr)\r\n        else:\r\n            Diccionario[Equipo] = [Puntos_sr]\r\n\r\n\r\n\r\nalianza_totales = {}\r\nfor Equipo, Puntos_list in Diccionario.items():\r\n    alianza_totales[Equipo] = sum(Puntos_list)\r\n\r\n\r\nif alianza_totales:\r\n    max_puntos = max(alianza_totales.values())\r\n\r\n\r\n    alianzas_ganadoras = [Equipo for Equipo, total in alianza_totales.items() if total == max_puntos]\r\n\r\n\r\n    alianzas_ganadoras.sort()\r\n\r\n    \r\n    for Equipo in alianzas_ganadoras:\r\n        print(f\"{Equipo} es la alianza campeona con {int(max_puntos)} puntos\")',1791),
(1792,'Diccionario = {}\r\nwhile True:\r\n\r\n        Light = input()\r\n        if Light == \"Fin de los juegos\":\r\n            break\r\n\r\n        Equipo, Puntos = Light.split()\r\n        Puntos_sr = float(Puntos)\r\n        if Equipo in Diccionario:\r\n            Diccionario[Equipo].append(Puntos_sr)\r\n        else:\r\n            Diccionario[Equipo] = [Puntos_sr]\r\n\r\n\r\n\r\nalianza_totales = {}\r\nfor Equipo, Puntos_list in Diccionario.items():\r\n    alianza_totales[Equipo] = sum(Puntos_list)\r\n\r\n\r\nif alianza_totales:\r\n    max_puntos = max(alianza_totales.values())\r\n\r\n\r\n    alianzas_ganadoras = [Equipo for Equipo, total in alianza_totales.items() if total == max_puntos]\r\n\r\n\r\n    alianzas_ganadoras.sort()\r\n\r\n    \r\n    for Equipo in alianzas_ganadoras:\r\n        print(f\"{Equipo} es la alianza campeona con {int(max_puntos)} puntos!\")',1792),
(1793,'Contador=0\r\nwhile True:\r\n        b,c = map(int, input().split())\r\n        if b == 0 and c == 0:\r\n            break\r\n        else:\r\n            Matriz=[list(input()) for _ in range(b)]\r\n            Matriz2=[list(input()) for _ in range(b)]\r\n            Contador = 0\r\n            for i in range(b):\r\n                for j in range(c):\r\n                    if Matriz[i][j] != Matriz2 [i][j]:\r\n                        Contador+=1\r\n        if Contador/(b*c) > 0.1:\r\n                print(\"La pintura no es original\")\r\n        else:\r\n                print(\"La pintura es original\")',1793),
