(1798,'Disponibles=set(input())\r\nObligatorias=set(input())\r\nProhibidas=set(input())\r\nCantidad=int(input())\r\nVacio=set()\r\nfor i in range(Cantidad):\r\n    palabra_original = input()\r\n    Palabras = set(palabra_original)\r\n    if Obligatorias.issubset(Palabras):\r\n        print(palabra_original)\r\n    elif Obligatorias==Vacio:\r\n        Disponibles.issubset(Palabras)\r\n        print(palabra_original)\r\n    else:\r\n        print(\"-\")',1798),
(1799,'filas = []\r\ncolunas = []\r\ng = int(input())\r\nfor i in range(g):\r\n    k = list(input().split())\r\n    filas.append(k)\r\nfor i in range(g):\r\n    coluna = []\r\n    for j in range(g):\r\n        elemento = filas[j][i]\r\n        coluna.append(elemento)\r\n    colunas.append(coluna)\r\nigual = True\r\nfor i in range(g):\r\n    if colunas[i] != filas[i]:\r\n        igual = False\r\n        break\r\nif igual:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1799),
