(1801,'x = int(input())\r\nlibro = {}\r\nfor i in range(x):\r\n    linea=input()\r\n    nombre, nota = linea.split()\r\n    nota = float(nota)\r\n    libro.setdefault(nombre, []).append(nota)\r\nfor nombre in sorted(libro):\r\n    notas = libro[nombre]\r\n    if len(notas)==3:\r\n        prom=sum(notas)/3\r\n        print(f\"{nombre} {prom:.2f}\")\r\n    else:\r\n        print(f\"{nombre} p\")',1801),
(1802,'diccionario=dict()\r\nlista=[]\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"Fin de los juegos\":\r\n        break\r\n    alianza,puntos=entrada.split()\r\n    puntos=int(puntos)\r\n\r\n    diccionario[alianza]= diccionario.setdefault(alianza, 0) + puntos\r\n\r\npuntaje_maximo=max(diccionario.values())\r\n   \r\nfor nombre,punto in diccionario.items():\r\n    if punto==puntaje_maximo:\r\n        lista.append(nombre)\r\nfor ganador in lista:\r\n    print(f\"{ganador} es la alianza campeona con {puntaje_maximo} puntos!\")',1802),
(1803,'diccionario=dict()\r\nlista=[]\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"Fin de los juegos\":\r\n        break\r\n    alianza,puntos=entrada.split()\r\n    puntos=int(puntos)\r\n\r\n    diccionario[alianza]= diccionario.setdefault(alianza, 0) + puntos\r\n\r\npuntaje_maximo=max(diccionario.values())\r\n   \r\nfor nombre,punto in diccionario.items():\r\n    if punto==puntaje_maximo:\r\n        lista.append(nombre)\r\nlista.sort()\r\nfor ganador in lista:\r\n    print(f\"{ganador} es la alianza campeona con {puntaje_maximo} puntos!\")',1803),
(1804,'puntosxequipo = {}\r\nequipos = set()\r\nwhile True:\r\n    a = input()\r\n    if a == \"Fin de los juegos\":\r\n        break\r\n    equipo, puntos = a.split()\r\n    equipos.add(equipo)\r\n    puntos = int(puntos)\r\n    puntosxequipo[equipo] = puntosxequipo.get(equipo, 0) + puntos\r\nequipos = list(equipos)\r\nequipos = sorted(equipos)\r\nmax = max(puntosxequipo.values())\r\nfor i in range(len(equipos)):\r\n    if puntosxequipo[equipos[i]]== max:\r\n        print(f\"{equipos[i]} es la alianza campeona con {puntosxequipo[equipos[i]]} puntos!\")',1804),
