(1810,'n = int(input(\"Ingresa un número: \"))\r\nes_primo = [True] * (n + 1)\r\nes_primo[0] = es_primo[1] = False\r\n\r\nfor i in range(2, int(n ** 0.5) + 1):\r\n    if es_primo[i]:\r\n        for j in range(i * i, n + 1, i):\r\n            es_primo[j] = False\r\n\r\nlistadeprimos = [i for i, primo in enumerate(es_primo) if primo]\r\nprint(len(listadeprimos))',1810),
(1811,'n = int(input(\"\"))\r\nes_primo = [True] * (n + 1)\r\nes_primo[0] = es_primo[1] = False\r\n\r\nfor i in range(2, int(n ** 0.5) + 1):\r\n    if es_primo[i]:\r\n        for j in range(i * i, n + 1, i):\r\n            es_primo[j] = False\r\n\r\nlistadeprimos = [i for i, primo in enumerate(es_primo) if primo]\r\nprint(len(listadeprimos))',1811),
(1812,'notas = {}\r\nganadores = []\r\nwhile True:\r\n    try:\r\n        nombre, nota = input().strip().split()\r\n        nota = int(nota)\r\n        if nombre not in notas:\r\n            notas[nombre]=[]\r\n        notas[nombre].append(nota)\r\n        #print(notas[nombre])\r\n    except:\r\n        break\r\n    \r\nfor nombre in notas:\r\n    notas[nombre] = [sum(notas[nombre])]\r\n    if notas[nombre] == max(notas.values()):\r\n        ganadores.append(nombre)\r\n    ganadores.sort()\r\nprint(ganadores[0], notas[ganadores[0]][0])',1812),
(1813,'notas = {}\r\nganadores = []\r\nwhile True:\r\n    try:\r\n        nombre, nota = input().strip().split()\r\n        nota = int(nota)\r\n        if nombre not in notas:\r\n            notas[nombre]=[]\r\n        notas[nombre].append(nota)\r\n        #print(notas[nombre])\r\n    except:\r\n        break\r\n    \r\nfor nombre in notas:\r\n    notas[nombre] = [sum(notas[nombre])]\r\n    if notas[nombre] == max(notas.values()):\r\n        ganadores.append(nombre)\r\n    ganadores.sort()\r\nprint(f\"{ganadores[0]} es la alianza campeona con {notas[ganadores[0]][0]} puntos!\")',1813),
(1814,'notas = {}\r\n\r\nwhile True:\r\n    try:\r\n        nombre, nota = input().strip().split()\r\n        nota = int(nota)\r\n        if nombre not in notas:\r\n            notas[nombre] = []\r\n        notas[nombre].append(nota)\r\n    except:\r\n        break\r\n\r\nfor nombre in notas:\r\n    notas[nombre] = sum(notas[nombre])\r\nmax_puntos = max(notas.values())\r\n\r\nganadores = [nombre for nombre, total in notas.items() if total == max_puntos]\r\n\r\nganadores.sort()\r\nfor nombre in ganadores:\r\n    print(f\"{nombre} es la alianza campeona con {max_puntos} puntos!\")',1814),
(1815,'entrada = input()\r\nN, C = map(int, entrada.split()) #N Filas y C Colunas\r\nB = [list(input()) for _ in range(N)] #Lista de listas\r\nV = True #La variable V es para ver cuando dejara de cambiar de lugar\r\nwhile V:\r\n    V = False\r\n    for i in range(N-2, -1, -1): #El -2 es porque cuenta de la penultima fila.\r\n                                 #El primer -1 es porque las listas empiezan de 0\r\n                                 #El ultimo -1 es porque es de arriba para abajo\r\n        for j in range(C+2):\r\n            if B[i][j] != \" \" and B[i+1][j] == \" \": #Si hay un espacio en \" \" hace que cambie de lugar, es decir\r\n#Si tenemos  j\r\n            #\r\n            #.            \r\n#Entonces hace que el \" \"=j y que j=\" \" por lo tanto el j baja\r\n                B[i+1][j] = B[i][j]\r\n                B[i][j] = \" \" \r\n                V = True #Si hubo un cambio de lugar, V vuelve a ser True\r\nfor i in B:\r\n    print(\"\".join(i)) #.join() permite escribir elemento por elemento, y lo junta en una cadena sin especies',1815),
(1816,'Disponibles=set(input())\r\nObligatorias=set(input())\r\nProhibidas=set(input())\r\nCantidad=int(input())\r\nT=[]\r\nfor i in range(Cantidad):\r\n    palabra_original= input().strip()\r\n    Harry=set(palabra_original)\r\n    if Harry.issubset(Disponibles) and Obligatorias.issubset(Harry) and not (Harry and Prohibidas):\r\n      T.append(palabra_original)\r\nif T:\r\n  for k in T:\r\n     print(k)\r\nelse:\r\n  print(\"-\")',1816),
(1817,'casos=int(input())\r\ndiccionario=dict()\r\nfor _ in range(casos):\r\n\r\n    nombre,nota=input().split()\r\n\r\n    nota=float(nota)\r\n    if nombre not in diccionario:\r\n       lista = diccionario[nombre]=[nota]\r\n    else:\r\n        diccionario[nombre].append(nota)\r\ndiccionario_ordenado=dict(sorted(diccionario.items()))\r\nfor nombre,notas in diccionario_ordenado.items():\r\n    \r\n    if len(diccionario[nombre])==3:\r\n        suma=sum(notas)\r\n        promedio=suma/3\r\n        print(f\"{nombre} {promedio:.2f}\")\r\n    else:\r\n        print(f\"{nombre} p\")',1817),
(1818,'# CompletaPalabras — Validador de palabras para el aniversario de Ingeniería de Matemática\r\n# Enunciado (resumen operativo):\r\n# - Dado un conjunto de letras disponibles (L), un conjunto de letras obligatorias (O) y un conjunto de letras prohibidas (P),\r\n#   debemos filtrar una lista de palabras candidatas y mostrar solo las que:\r\n#   (1) usan exclusivamente letras de L,\r\n#   (2) contienen todas las letras de O al menos una vez,\r\n#   (3) no contienen ninguna letra de P.\r\n# - Si no hay palabras válidas, imprimir un guion \"-\".\r\n\r\n# --- Entrada ---\r\n# 1) Cadena con letras disponibles (no vacía).\r\nletras_disponibles = input().strip()\r\n# 2) Cadena con letras obligatorias (puede ser vacía).\r\nletras_obligatorias = input().strip()\r\n# 3) Cadena con letras prohibidas (puede ser vacía).\r\nletras_prohibidas = input().strip()\r\n# 4) Entero n: cantidad de palabras candidatas.\r\nn = int(input().strip())\r\n\r\n# --- Normalización a conjuntos ---\r\n# Usamos \'set\' para operaciones de pertenencia y contención en tiempo eficiente.\r\n# L: universo permitido; O: debe estar contenido en cada palabra; P: letras vetadas.\r\nL = set(letras_disponibles)\r\nO = set(letras_obligatorias)\r\nP = set(letras_prohibidas)\r\n\r\n# --- Procesamiento de palabras ---\r\nvalidas = []\r\nfor _ in range(n):\r\n    palabra = input().strip()\r\n    s = set(palabra)  # Conjunto de letras efectivamente usadas en la palabra\r\n\r\n    # Condición (1): todas las letras de la palabra están en L  → s ⊆ L\r\n    # Condición (2): todas las obligatorias están presentes     → O ⊆ s\r\n    # Condición (3): no incluye prohibidas                      → s ∩ P = ∅  (equivale a \"not (s & P)\")\r\n    if s.issubset(L) and O.issubset(s) and not (s & P):\r\n        validas.append(palabra)\r\n\r\n# --- Salida ---\r\n# Imprimir cada palabra válida en su propia línea; si no hay, imprimir \"-\"\r\nif validas:\r\n    for v in validas:\r\n        print(v)\r\nelse:\r\n    print(\"-\")',1818),
(1819,'n = int(input().strip())\r\ncartas = [set(input().strip().split()) for _ in range(n)]\r\n\r\nvalida = True\r\n\r\n# Verificar que cada carta tenga exactamente 6 símbolos distintos\r\nfor carta in cartas:\r\n    if len(carta) != 6 or len(set(carta)) != 6:\r\n        valida = False\r\n\r\n# Verificar que cada par de cartas comparta exactamente un símbolo\r\nfor i in range(n):\r\n    for j in range(1, n):  # j parte en 1\r\n        if i != j:\r\n            inter = cartas[i] & cartas[j]\r\n            if len(inter) != 1:\r\n                valida = False\r\n\r\nif valida:\r\n    print(\"VALIDA\")\r\nelse:\r\n    print(\"NO VALIDA\")',1819),
(1820,'notas = {}\r\nN = input()\r\nN = int(N)\r\nfor i in range(N):\r\n    a, b = input().split()\r\n    b = float(b)\r\n    notas.setdefault(a, []).append(b) #Crear items y los añade al dic, si no esta a crea algo vacio y si ya esta a agrega b a ese nombre\r\nsorted(notas)\r\nfor j in notas.keys():\r\n    if len(notas[j]) == 3:\r\n        n = sum(notas[j]) / 3 \r\n        print(f\"{j} {n: .2f}\")\r\n    else:\r\n        n = \"p\"\r\n        print(f\"{j} {n}\")',1820),
(1821,'notas = {}\r\nN = input()\r\nN = int(N)\r\nfor i in range(N):\r\n    a, b = input().split()\r\n    b = float(b)\r\n    notas.setdefault(a, []).append(b) #Crear items y los añade al dic, si no esta a crea algo vacio y si ya esta a agrega b a ese nombre \r\nfor a in sorted(notas):\r\n    if len(notas[a]) == 3:\r\n        n = sum(notas[a]) / 3 \r\n        print(f\"{a} {n: .2f}\")\r\n    else:\r\n        n = \"p\"\r\n        print(f\"{a} {n}\")',1821),
(1822,'n,m=map(int,input().split())\r\nhangar=[[\' \']*m for i in range(n)]\r\nfor i in range(n):\r\n    hangar[i]=list(input().strip(\"|\"))\r\n#gravedad artificial\r\nhangar_new=[[\" \"]*m for i in range(n)]\r\nfor columna in range(m):\r\n    lista_de_objetos=[]\r\n    contador=n-1\r\n    for fila in range(n-1,-1,-1):\r\n        if hangar[fila-1][columna]!=\' \':\r\n            hangar_new[contador][columna]=hangar[fila-1][columna]\r\n            contador-=1\r\nfor item in hangar_new:\r\n    print(f\"|{\"\".join(item)}|\")',1822),
(1823,'# Palabras Cruzadas - versión simple y clara (sin usar any)\r\n# Asume que la entrada es válida.\r\n# Cada línea: <H|V> <fila> <col> <palabra>\r\n\r\nimport sys\r\n\r\nN = 12\r\ngrid = [[\'.\' for _ in range(N)] for _ in range(N)]\r\n\r\nfor line in sys.stdin:\r\n    d, r, c, w = line.split()\r\n    r, c = int(r), int(c)\r\n\r\n    # Definir dirección\r\n    if d == \'H\':\r\n        dr, dc = 0, 1\r\n    else:\r\n        dr, dc = 1, 0\r\n\r\n    # Verificar si cabe en la cuadrícula\r\n    if (d == \'H\' and c + len(w) > N) or (d == \'V\' and r + len(w) > N):\r\n        continue\r\n\r\n    # Verificar conflictos letra por letra\r\n    conflicto = False\r\n    for i in range(len(w)):\r\n        rr = r + dr * i\r\n        cc = c + dc * i\r\n        letra_actual = grid[rr][cc]\r\n        if letra_actual != \'.\' and letra_actual != w[i]:\r\n            conflicto = True\r\n            break\r\n\r\n    if conflicto:\r\n        continue  # No se coloca la palabra si hay conflicto\r\n\r\n    # Colocar la palabra\r\n    for i in range(len(w)):\r\n        rr = r + dr * i\r\n        cc = c + dc * i\r\n        grid[rr][cc] = w[i]\r\n\r\n# Mostrar el tablero final\r\nfor fila in grid:\r\n    print(\'\'.join(fila))',1823),
