(1858,'n = int(input())\r\noriginal = list(input().split())\r\nsecreto = list(input().split())\r\nmensaje = []\r\nm = input()\r\nfor i in m:\r\n    mensaje.append(i)\r\n\r\nfor i in range(len(mensaje)):\r\n    if set(original) & set(mensaje) == 0:\r\n        break\r\n    for j in range(n):\r\n        if mensaje[i] == original[j] and original[j]:\r\n            mensaje[i] = secreto[j]\r\n            break\r\nprint(\"\".join(mensaje))',1858),
(1859,'def buscar_direcciones(y,x,n,m):\r\n    #esquinas\r\n    izq = (-1,0)\r\n    der = (1,0)\r\n    abj = (0,1)\r\n    arr = (0,-1)\r\n    izqabj = (-1,1)\r\n    izqarr = (-1,-1)\r\n    derabj = (1,1)\r\n    derarr = (1,-1)\r\n    if (x==0 and y==0):\r\n        return [der,abj,derabj]\r\n    elif (x==m-1 and y==0):\r\n        return [izq,abj,izqabj]\r\n    elif (x==m-1 and y==n-1):\r\n        return [izq,arr,izqarr]\r\n    elif (x==0 and y==n-1):\r\n        return [der,arr,derarr]\r\n    #aristas\r\n    elif(x==0):\r\n        return [der,arr,abj,derarr,derabj]\r\n    elif(x==m-1):\r\n        return [izq,arr,abj,izqarr,izqabj]\r\n    elif(y==0):\r\n        return [abj,izq,der,izqabj,derabj]\r\n    elif(y==n-1):\r\n        return [arr,izq,der,izqarr,derarr]\r\n    else:\r\n        return[izq,der,abj,arr,izqabj,derabj,izqarr,derarr]\r\n    \r\ndef buscar(x,y,w,n,m):\r\n    direcciones = buscar_direcciones(y,x,n,m)\r\n    minimo = float(\'inf\')\r\n    bandera = False \r\n    new_x = x\r\n    new_y = y\r\n    for dx,dy in direcciones:\r\n        if w[y+dy][x+dx]<w[y][x]:\r\n            if w[y+dy][x+dx]<minimo:\r\n                minimo = w[y+dy][x+dx]\r\n                new_x = x+dx\r\n                new_y = y+dy\r\n                bandera = True\r\n    if bandera:\r\n        buscar(new_x,new_y,w,n,m)\r\n    else:\r\n        print(y,x)\r\n    \r\nn,m = map(int,input().split())\r\ny,x = map(int,input().split())\r\nw = []\r\nfor i in range(n):\r\n    r = list(map(int,input().split()))\r\n    w.append(r)\r\nr = buscar_direcciones(y,x,4,5)\r\nbuscar(x,y,w,n,m)',1859),
(1860,'n = int(input())\r\noriginal = list(input().split())\r\nsecreto = list(input().split())\r\nmensaje = []\r\nm = input()\r\nfor i in m:\r\n    mensaje.append(i)\r\nlargo = len(mensaje)\r\nfor i in range(largo):\r\n    for j in range(n):\r\n        if mensaje[i] == original[j]:\r\n            mensaje[i] = secreto[j]\r\n            break\r\nprint(\"\".join(mensaje))',1860),
(1861,'#Cartas hexagonales\r\nEs_Valido=\"VALIDA\"\r\nn=int(input()) # cantidad de cartas\r\nmazo=[set() for j in range(n)] # mazo vacio\r\nsimbolos=set() #todos los simbolos disponibles\r\nfor k in range(n):\r\n    caras=input().split()\r\n    mazo[k]=set(caras) #mazo de cartas representado por matriz\r\n    for cara in caras:\r\n        simbolos.add(cara)\r\nfor a in range(n):\r\n    for b in range(a+1,n):\r\n        if len(mazo[a]&mazo[b])>1 or len(mazo[a]&mazo[b])==0:\r\n            Es_Valido=\"NO VALIDA\"\r\nprint(Es_Valido)',1861),
