(1865,'x = int(input())\r\nmatriz = []\r\nbandera = True\r\ncontador = 0\r\nfor i in range(x):\r\n    carta = input().split()\r\n    matriz.append(carta)\r\nlista_1 = []\r\nlista_2 = []\r\nfor i in matriz:\r\n    if i == matriz[0]:\r\n        lista_1 = i\r\n    else:\r\n        lista_2 = i+lista_1\r\n        lista_2 = set(lista_2)\r\n        lista_2 = list(lista_2)\r\n        if len(lista_2)<= 10:\r\n            bandera = False\r\n        else:\r\n            pass\r\nfor i in matriz:\r\n    if i == matriz[0]:\r\n        pass\r\n    elif i == matriz[1]:\r\n        lista_1 = i\r\n    else:\r\n        lista_2 = i+lista_1\r\n        lista_2 = set(lista_2)\r\n        lista_2 = list(lista_2)\r\n        if len(lista_2)<= 10:\r\n            bandera = False\r\n        else:\r\n            pass\r\nfor i in matriz:\r\n    if i == matriz[0] or i == matriz[1]:\r\n        pass\r\n    elif i == matriz[2]:\r\n        lista_1 = i\r\n    else:\r\n        lista_2 = i+lista_1\r\n        lista_2 = set(lista_2)\r\n        lista_2 = list(lista_2)\r\n        if len(lista_2)<= 10:\r\n            bandera = False\r\n        else:\r\n            pass\r\nfor i in matriz:\r\n    x = len(i)\r\n    if x != 6:\r\n        bandera = False\r\n    else:\r\n        pass\r\nif bandera == False:\r\n    print(\"NO VALIDA\")\r\nelse:\r\n    print(\"VALIDA\")',1865),
