(1906,'descarte = 0\r\nexportacion = 0\r\nnacional = 0\r\nwhile True:\r\n    x = input()\r\n    if x == \"G\":\r\n        y = input()\r\n        if y == \"R\" or y == \"V\":\r\n            exportacion+=1\r\n        elif y == \"A\":\r\n            nacional+=1\r\n    elif x == \"P\":\r\n        y == input()\r\n        if y == \"R\":\r\n            descarte+=1\r\n        elif y == \"v\":\r\n            descarte+=1\r\n        elif y == \"A\":\r\n            descarte+=1\r\n    else\r\n        break\r\nprint(descarte)\r\nprint(exportacion)\r\nprint(nacional)',1906),
(1907,'descarte = 0\r\nexportacion = 0\r\nnacional = 0\r\nwhile True:\r\n    x = input()\r\n    if x == \"G\":\r\n        y = input()\r\n        if y == \"R\" or y == \"V\":\r\n            exportacion+=1\r\n        elif y == \"A\":\r\n            nacional+=1\r\n    elif x == \"P\":\r\n        y == input()\r\n        if y == \"R\":\r\n            descarte+=1\r\n        elif y == \"v\":\r\n            descarte+=1\r\n        elif y == \"A\":\r\n            descarte+=1\r\n    else:\r\n        break\r\nprint(descarte)\r\nprint(exportacion)\r\nprint(nacional)',1907),
(1908,'descarte = 0\r\nexportacion = 0\r\nnacional = 0\r\nwhile True:\r\n    tamaño = input()\r\n    if tamaño == \"-1\":\r\n        break\r\n    else:\r\n        color = input()\r\n        if tamaño == \"G\":\r\n            if color == \"R\" or color == \"v\":\r\n                exportacion +=1\r\n            else:\r\n                nacional +=1\r\n        else:\r\n            descarte +=1\r\n\r\nprint(descarte)\r\nprint(exportacion)\r\nprint(nacional)',1908),
(1909,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vi v(n);\r\n    for (int i = 0  ; i<n  ; i++) cin >> v[i];\r\n    sort(all(v));\r\n    int k = n/2;\r\n    ll total = 0;\r\n    do {\r\n        ll izq = 0;\r\n        ll der = 0;\r\n        for(int i = 0 ; i<k ; i++){\r\n            izq+=v[i];\r\n        }\r\n        for(int i = k ; i < k*2 ; i++){\r\n            der+=v[i];\r\n        }\r\n        if(izq == der){\r\n            total++;\r\n        }\r\n    } while(next_permutation(all(v)));\r\n    cout << total << ENDL; \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1909),
(1910,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nconst int MAX_FACT = 20;\r\nvi fact(MAX_FACT+1);\r\nvoid init_factorial(){\r\n    fact[0] = 1 ; fact [1] = 1;\r\n    for(int i = 2 ; i<=MAX_FACT ; i++) fact[i]=fact[i-1]*i;\r\n}\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vi v(n);\r\n    for (int i = 0  ; i<n  ; i++) cin >> v[i];\r\n    sort(all(v));\r\n    int k = n/2;\r\n    ll total = 0;\r\n    do {\r\n        ll izq = 0;\r\n        ll der = 0;\r\n        for(int i = 0 ; i<k ; i++){\r\n            izq+=v[i];\r\n        }\r\n        for(int i = k ; i < k*2 ; i++){\r\n            der+=v[i];\r\n        }\r\n        if(izq == der){\r\n            // contar frecuencias ;\r\n            map<double,int> frecuencias;\r\n            for(int i = 0 ; i<k*2 ; i++){\r\n                frecuencias[v[i]]++;\r\n            }\r\n            ll multiplicador = 1;\r\n            for(auto [val,count] : frecuencias){\r\n                multiplicador *=fact[count];\r\n            }\r\n            total+=multiplicador;\r\n        }\r\n    } while(next_permutation(all(v)));\r\n    cout << total << ENDL; \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n\r\n    init_factorial();\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1910),
(1911,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nconst int MAX_FACT = 20;\r\nvi fact(MAX_FACT+1);\r\nvoid init_factorial(){\r\n    fact[0] = 1 ; fact [1] = 1;\r\n    for(int i = 2 ; i<=MAX_FACT ; i++) fact[i]=fact[i-1]*i;\r\n}\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vi v(n);\r\n    for (int i = 0  ; i<n  ; i++) cin >> v[i];\r\n    sort(all(v));\r\n    int k = n/2;\r\n    ll total = 0;\r\n    do {\r\n        ll izq = 0;\r\n        ll der = 0;\r\n        for(int i = 0 ; i<k ; i++){\r\n            izq+=v[i];\r\n        }\r\n        for(int i = k ; i < k*2 ; i++){\r\n            der+=v[i];\r\n        }\r\n        if(izq == der){\r\n            // contar frecuencias ;\r\n            map<double,int> frecuencias;\r\n            for(int i = 0 ; i<k*2 ; i++){\r\n                frecuencias[v[i]]++;\r\n            }\r\n            ll multiplicador = 1;\r\n            for(auto [val,count] : frecuencias){\r\n                multiplicador *=fact[count];\r\n            }\r\n            total+=multiplicador;\r\n        }\r\n    } while(next_permutation(all(v)));\r\n    cout << total << ENDL; \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n\r\n    init_factorial();\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1911),
(1912,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nconst int MAX_FACT = 20;\r\nvi fact(MAX_FACT+1);\r\nvoid init_factorial(){\r\n    fact[0] = 1 ; fact [1] = 1;\r\n    for(int i = 2 ; i<=MAX_FACT ; i++) fact[i]=fact[i-1]*i;\r\n}\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vi v(n);\r\n    for (int i = 0  ; i<n  ; i++) cin >> v[i];\r\n    sort(all(v));\r\n    int k = n/2;\r\n    ll total = 0;\r\n    do {\r\n        ll izq = 0;\r\n        ll der = 0;\r\n        for(int i = 0 ; i<k ; i++){\r\n            izq+=v[i];\r\n        }\r\n        for(int i = k ; i < k*2 ; i++){\r\n            der+=v[i];\r\n        }\r\n        if(izq == der){\r\n            // contar frecuencias ;\r\n            map<double,int> frecuencias;\r\n            for(int i = 0 ; i<k*2 ; i++){\r\n                frecuencias[v[i]]++;\r\n            }\r\n            ll multiplicador = 1;\r\n            for(auto par : frecuencias){\r\n                int count = par.second;\r\n                multiplicador *=fact[count];\r\n            }\r\n            total+=multiplicador;\r\n        }\r\n    } while(next_permutation(all(v)));\r\n    cout << total << ENDL; \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n\r\n    init_factorial();\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1912),
(1913,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvll fact(MAX_FACT+1);\r\nvoid init_factorial(){\r\n    fact[0] = 1 ; fact [1] = 1;\r\n    for(int i = 2 ; i<=MAX_FACT ; i++) fact[i]=fact[i-1]*i;\r\n}\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vector<double> v(n);\r\n    for (int i = 0  ; i<n  ; i++) cin >> v[i];\r\n    sort(all(v));\r\n    int k = n/2;\r\n    ll total = 0;\r\n    do {\r\n        double izq = 0;\r\n        double der = 0;\r\n        for(int i = 0 ; i<k ; i++){\r\n            izq+=v[i];\r\n        }\r\n        for(int i = k ; i < k*2 ; i++){\r\n            der+=v[i];\r\n        }\r\n        if(abs(izq - der)<EPS){\r\n            map<double,int> frecuencias;\r\n            for(int i = 0 ; i<k*2 ; i++){\r\n                frecuencias[v[i]]++;\r\n            }\r\n            ll multiplicador = 1;\r\n            for(auto par : frecuencias){\r\n                int count = par.second;\r\n                multiplicador *=fact[count];\r\n            }            \r\n            total+=multiplicador;\r\n        }\r\n    } while(next_permutation(all(v)));\r\n    cout << total << ENDL; \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    init_factorial();\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1913),
(1914,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvll fact(MAX_FACT+1);\r\nvoid init_factorial(){\r\n    fact[0] = 1 ; fact [1] = 1;\r\n    for(int i = 2 ; i<=MAX_FACT ; i++) fact[i]=fact[i-1]*i;\r\n}\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vector<double> v(n);\r\n    for (int i = 0  ; i<n  ; i++) cin >> v[i];\r\n    sort(all(v));\r\n    int k = n/2;\r\n    ll total = 0;\r\n    map<double,int> frecuencias;\r\n    for(int i = 0 ; i<n ; i++){\r\n        frecuencias[v[i]]++; \r\n    }\r\n    ll multiplicador = 1;\r\n    for(auto par : frecuencias){\r\n        int count = par.second;\r\n        multiplicador *=fact[count];\r\n    }   \r\n    do {\r\n        double izq = 0;\r\n        double der = 0;\r\n        for(int i = 0 ; i<k ; i++){\r\n            izq+=v[i];\r\n        }\r\n        for(int i = k ; i < k*2 ; i++){\r\n            der+=v[i];\r\n        }\r\n        if(abs(izq - der)<EPS){        \r\n            total+=multiplicador;\r\n        }\r\n    } while(next_permutation(all(v)));\r\n    cout << total << ENDL; \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    init_factorial();\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1914),
(1915,'entrada=int(input())\r\nmatriz=[]\r\nboleano=False\r\nfor _ in range(entrada):\r\n    letras=list(input())\r\n    matriz.append(letras)\r\nfor y in range(entrada-2):\r\n    for x in range(entrada-2):\r\n        if matriz[y][x]==\"T\" and matriz[y][x+1]==\"C\" and matriz[y][x+2]==\"P\":\r\n            boleano=True\r\n            break\r\n        elif matriz[y][x]==\"T\" and matriz[y+1][x]==\"C\" and matriz[y+2][x]==\"P\":\r\n            boleano=True\r\n            break\r\n        elif matriz[y][x]==\"T\" and matriz[y+1][x+1]==\"C\" and matriz[y+2][x+2]==\"P\":\r\n            boleano=True\r\n            break\r\nif boleano==True:\r\n    print(\"si\")\r\nelse:\r\n    print(\"no\")',1915),
(1916,'entrada=int(input())\r\nmatriz=[]\r\nboleano=False\r\nfor _ in range(entrada):\r\n    letras=list(input())\r\n    matriz.append(letras)\r\nfor y in range(entrada-2):\r\n    for x in range(entrada-2):\r\n        if matriz[y][x]==\"T\" and matriz[y][x+1]==\"C\" and matriz[y][x+2]==\"P\":\r\n            boleano=True\r\n            break\r\n        elif matriz[y][x]==\"T\" and matriz[y+1][x]==\"C\" and matriz[y+2][x]==\"P\":\r\n            boleano=True\r\n            break\r\n        elif matriz[y][x]==\"T\" and matriz[y+1][x+1]==\"C\" and matriz[y+2][x+2]==\"P\":\r\n            boleano=True\r\n            break\r\n        if boleano:\r\n            break\r\nif boleano==True:\r\n    print(\"si\")\r\nelse:\r\n    print(\"no\")',1916),
(1917,'dispnibles=set(input().strip())\r\nobligatorias=set(input().strip())\r\nproividas=set(input().strip())\r\nn=int(input())\r\nlista=[]\r\nfor _ in range(5):\r\n    n=input().strip()\r\n    set_n=set(n)\r\n    if dispnibles & set_n and obligatorias & set_n and not proividas & set_n:\r\n        lista.append(n)\r\nfor lista in lista:\r\n    print(lista)',1917),
(1918,'while True:\r\n    lista = []\r\n    x = input()\r\n    if x == \"0\":\r\n        break\r\n    numero, adn = x.split()  \r\n    numero = int(numero)\r\n    for _ in adn:\r\n        lista.append(_)\r\n    nueva_lista = lista\r\n    nueva_lista.reverse()\r\n    if lista == nueva_lista:\r\n        print(\"Eureka! Es un palindromo genetico\")\r\n    else:\r\n        print(\"Lo siento, no es un palindromo genetico\")',1918),
(1919,'while True:\r\n    lista = []\r\n    x = input()\r\n    if x == \"0\":\r\n        break\r\n    numero, adn = x.split()  \r\n    numero = int(numero)\r\n    for _ in adn:\r\n        lista.append(_)\r\n    nueva_lista = list(lista)\r\n    nueva_lista.reverse()\r\n    new_list= nueva_lista\r\n    if lista == new_list:\r\n        print(\"Eureka! Es un palindromo genetico\")\r\n    else:\r\n        print(\"Lo siento, no es un palindromo genetico\")',1919),
(1920,'while True:\r\n    lista = []\r\n    x = input()\r\n    if x == \"0\":\r\n        break\r\n    numero, adn = x.split()  \r\n    numero = int(numero)\r\n    for _ in adn:\r\n        lista.append(_)\r\n    nueva_lista = list(lista)\r\n    nueva_lista.reverse()\r\n    if lista == nueva_lista:\r\n        print(\"Eureka! Es un palindromo genetico\")\r\n    else:\r\n        print(\"Lo siento, no es un palindromo genetico\")',1920),
(1921,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nll prim(int s, int n, vvpi& ady){\r\n    ll mst_peso = 0;\r\n    vector<bool> vis(n+1,false);\r\n\r\n    priority_queue<pi,vector<pi>,greater<pi>> pq;\r\n\r\n    pq.push({0,1});\r\n    while(!pq.empty()){\r\n        int peso = pq.top().fi;\r\n        int u = pq.top().se;\r\n        pq.pop();\r\n\r\n        if (vis[u]) continue;\r\n        vis[u] = true;\r\n        mst_peso +=peso;\r\n        for(auto& edge : ady[u]){\r\n            int v = edge.fi;\r\n            int w = edge.se;\r\n            if(!vis[v]){\r\n                pq.push({w,v});\r\n            }\r\n        }\r\n    }\r\n    return mst_peso;\r\n}\r\n\r\nvoid solve(){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vvpi ady(n);\r\n    for(int i = 0 ; i<m; i++){\r\n        int x,y,p;\r\n        cin >> x >> y >> p;\r\n        ady[x].pb({y,p});\r\n        ady[y].pb({x,p});\r\n    }\r\n    cout << prim(0,n,ady) << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1921),
(1922,'import sys\r\n\r\n# Leemos la entrada\r\nn, K, r_i, c_i, r_f, c_f = map(int, sys.stdin.read().split())\r\n\r\n# Movimientos del caballo (k-ballo)\r\nmovimientos = [\r\n    (2, 1), (2, -1),\r\n    (-2, 1), (-2, -1),\r\n    (1, 2), (1, -2),\r\n    (-1, 2), (-1, -2),\r\n]\r\n\r\ninicio = (r_i, c_i)\r\nfin = (r_f, c_f)\r\n\r\n# Conjunto de casillas alcanzables en a lo más t movimientos\r\nalcanzable = {inicio}\r\n\r\n# Si ya estamos en la casilla final, es alcanzable con 0 ≤ K\r\nif inicio == fin:\r\n    print(\"SI\")\r\n    sys.exit(0)\r\n\r\n# Realizamos hasta K iteraciones\r\nfor _ in range(K):\r\n    auxiliar = set()\r\n    for (r, c) in alcanzable:\r\n        for dr, dc in movimientos:\r\n            nr, nc = r + dr, c + dc\r\n            if 1 <= nr <= n and 1 <= nc <= n:\r\n                auxiliar.add((nr, nc))\r\n    alcanzable |= auxiliar\r\n    if fin in alcanzable:\r\n        print(\"SI\")\r\n        break\r\nelse:\r\n    # Si el for termina sin hacer break\r\n    print(\"NO\")',1922),
(1923,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nvoid solve(){\r\n    vector<float> v;\r\n    while(true){\r\n        float x;\r\n        cin >> x;\r\n        if (x==-1){\r\n            break;\r\n        }\r\n        v.pb(x);\r\n    }\r\n    vi final;\r\n    for(int i = 1 ; i<sz(v) ; i++){\r\n        if(v[i-1]<v[i] && v[i]>v[i+1]){\r\n            final.pb(i);\r\n        }\r\n    }\r\n    cout << \"Las cumbres de la ruta 1 estan en:\";\r\n    for(int i : final) cout << \" \" << i;\r\n    cout << ENDL;\r\n    \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1923),
(1924,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nvoid solve(){\r\n    \r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    for(int q = 1 ; q<=t ; q++){\r\n        vector<float> v;\r\n        while(true){\r\n            float x;\r\n            cin >> x;\r\n            if (x==-1){\r\n                break;\r\n            }\r\n            v.pb(x);\r\n        }\r\n        vi final;\r\n        for(int i = 1 ; i<sz(v) ; i++){\r\n            if(v[i-1]<v[i] && v[i]>v[i+1]){\r\n                final.pb(i);\r\n            }\r\n        }\r\n        cout << \"Las cumbres de la ruta \" << q << \" estan en:\";\r\n        for(int i : final) cout << \" \" << i;\r\n        cout << ENDL;\r\n    }\r\n    return 0;\r\n}',1924),
(1925,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nbool encontrar_ganador(char letra, vector<string>& v){\r\n    //filas\r\n    for(int i = 0 ; i<3 ; i++){\r\n        if(v[i][0] == letra && v[i][1] == letra && v[i][2] == letra){\r\n            return true;\r\n        }\r\n    }\r\n    //columnas\r\n    for(int i = 0 ; i<3 ; i++){\r\n        if(v[0][i] == letra && v[1][i] == letra && v[2][i] == letra){\r\n            return true;\r\n        }\r\n    }\r\n    //diagonales\r\n    if(v[0][0] == letra && v[1][1] == letra && v[2][2] == letra){\r\n        return true;\r\n    }\r\n    if(v[2][0] == letra && v[1][1] == letra && v[0][2] == letra){\r\n        return true;\r\n    }\r\n    return false;\r\n}\r\n\r\n\r\nvoid solve(){\r\n    vector<string> v;\r\n    for(int i = 0 ; i<3 ; i++){\r\n        string s;\r\n        cin >> s;\r\n        v.pb(s);\r\n    }\r\n    // contar cantidad de circulos y x\r\n    int cant_o = 0;\r\n    int cant_x = 0;\r\n    for(int i = 0; i<3 ; i++){\r\n        for(int k = 0 ; k<3 ; k++){\r\n            if(v[i][k]==\'X\') cant_x++;\r\n            if(v[i][k]==\'O\') cant_o++;\r\n        }\r\n    }\r\n    if(cant_x>cant_o) {cout << \"Juego incorrecto.\" << ENDL ; return ; }\r\n    if(cant_o>cant_x+1) {cout << \"Juego incorrecto.\" << ENDL ; return ; }\r\n    bool gana_x = encontrar_ganador(\'X\',v);\r\n    bool gana_o = encontrar_ganador(\'O\',v);\r\n    if(gana_x && gana_o) {cout << \"Juego incorrecto.\" << ENDL ; return ; }\r\n    if(gana_x){\r\n        cout << \"Gana X.\" << ENDL;\r\n        return;\r\n    }\r\n    if(gana_o){\r\n        cout << \"Gana O.\" << ENDL;\r\n        return;\r\n    }\r\n    if(cant_x+cant_o==9){\r\n        cout << \"Juego empatado.\" << ENDL;\r\n        return;\r\n    }\r\n    if(cant_x==cant_o){\r\n        cout << \"Juego inconcluso, juega O.\" << ENDL;\r\n    } else {\r\n        cout << \"Juego inconcluso, juega X.\" << ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1925),
(1926,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    for(int q = 1 ; q<=t ; q++){\r\n        vector<float> v;\r\n        while(true){\r\n            float x;\r\n            cin >> x;\r\n            if (x==-1){\r\n                break;\r\n            }\r\n            v.pb(x);\r\n        }\r\n        vi final;\r\n        for(int i = 1 ; i<sz(v)-1 ; i++){\r\n            if(v[i-1]<v[i] && v[i]>v[i+1]){\r\n                final.pb(i);\r\n            }\r\n        }\r\n        cout << \"Las cumbres de la ruta \" << q << \" estan en:\";\r\n        for(int i : final) cout << \" \" << i;\r\n        cout << ENDL;\r\n    }\r\n    return 0;\r\n}',1926),
