(1934,'F = int(input()\r\nrutas = []\r\n\r\nfor _ in range(F):\r\n    ruta = []\r\n    while True:\r\n        valor = input().strip()\r\n        if valor == \"-1\":\r\n            break\r\n        ruta.append(float(valor))\r\n    rutas.append(ruta)\r\n\r\nfor i in range(N):\r\n    alturas = rutas[i]\r\n    print(f\"Las cumbres de la ruta {i + 1} estan en:\", end=\"\")\r\n    cumbre = False\r\n    for j in range(1, len(alturas) - 1):\r\n        if alturas[j - 1] < alturas[j] > alturas[j + 1]:\r\n            if not hay_cumbre:\r\n                print(\" \", end=\"\")\r\n                cumbre = True\r\n            print(j, end=\" \")\r\n    print()',1934),
(1935,'F = int(input())\r\nrutas = []\r\n\r\nfor _ in range(F):\r\n    ruta = []\r\n    while True:\r\n        valor = input().strip()\r\n        if valor == \"-1\":\r\n            break\r\n        ruta.append(float(valor))\r\n    rutas.append(ruta)\r\n\r\nfor i in range(N):\r\n    alturas = rutas[i]\r\n    print(f\"Las cumbres de la ruta {i + 1} estan en:\", end=\"\")\r\n    cumbre = False\r\n    for j in range(1, len(alturas) - 1):\r\n        if alturas[j - 1] < alturas[j] > alturas[j + 1]:\r\n            if not hay_cumbre:\r\n                print(\" \", end=\"\")\r\n                cumbre = True\r\n            print(j, end=\" \")\r\n    print()',1935),
(1936,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nbool seg (vi& a , vi&b){\r\n    return a[1] < b[1];\r\n}\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if (n==-1 and m==-1 and c==-1) return -1;\r\n    vvi cajas;\r\n    for(int i = 0 ; i<c ; i++){\r\n        vi x;\r\n        for(int k = 0; k<3 ; k++){\r\n            int r;\r\n            cin >> r;\r\n            x.pb(r);\r\n        }\r\n        cajas.pb(x);\r\n    }\r\n    sort(all(cajas),seg);\r\n    cout << \"En la bodega \" << z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    set<int> pilas_malas;\r\n    int pila_actual = -1;\r\n    int altura_actual = -1;\r\n    int peso_actual = -1;\r\n    for(int i = 0 ; i<c ; i++){\r\n        // primera de la pila encontrada\r\n        if(pila_actual!=cajas[i][1]){\r\n            pila_actual=cajas[i][1];\r\n            if(cajas[i][0]!=0) {\r\n                pilas_malas.insert(pila_actual);\r\n                int altura_actual = -1;\r\n                int peso_actual = -1;\r\n                continue;\r\n            }\r\n            altura_actual = 0;\r\n            peso_actual = cajas[i][2];\r\n            continue;\r\n        }\r\n        // comparación de altura y pesos\r\n        // concuerda la altura?\r\n        if(altura_actual+1 != cajas[i][0]){\r\n            pilas_malas.insert(pila_actual);\r\n        }\r\n        // concuerda el peso?\r\n        if(peso_actual<=cajas[i][2]){\r\n            pilas_malas.insert(pila_actual);\r\n        }\r\n        altura_actual = cajas[i][0];\r\n        peso_actual = cajas[i][2];\r\n    }\r\n    for(int i : pilas_malas) cout << \" \" << i;\r\n    cout << ENDL;\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1936),
(1937,'import sys\r\nsys.stdin = open(\"entrada.txt\", \"r\")\r\nsys.stdout = open(\"salida.txt\", \"w\")\r\n\r\n#################################################\r\n#################################################\r\n\'\'\'\r\nProblema:\r\n\'\'\'\r\nfrom collections import deque\r\n\r\ndef bfs_grid(n,start_r,start_c):\r\n    distancias = [[-1]*n for _ in range(n)]\r\n    cola = deque([(start_r,start_c)])\r\n    distancias[start_r][start_c] = 0\r\n    movs = [(2,1),(2,-1),(-2,1),(-2,-1),(1,-2),(1,2),(-1,2),(-1,-2)]\r\n    while cola:\r\n        r,c = cola.popleft()\r\n        for dr,dc in movs:\r\n            nr, nc = r+dr,c+dc\r\n            if 0<=nr and nr < n and 0 <= nc and nc < n:\r\n                if distancias[nr][nc] ==-1:\r\n                    distancias[nr][nc] = distancias[r][c]+1\r\n                    cola.append((nr,nc))\r\n    return distancias\r\n                \r\nn,kk,ri,ci,rf,cf = map(int,input().split())\r\nri -=1\r\nci -=1\r\nrf -=1\r\ncf -=1\r\nx = bfs_grid(n,ri,ci)\r\nif(x[rf][cf]<=kk):\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1937),
(1938,'from collections import deque\r\n\r\ndef bfs_grid(n,start_r,start_c):\r\n    distancias = [[-1]*n for _ in range(n)]\r\n    cola = deque([(start_r,start_c)])\r\n    distancias[start_r][start_c] = 0\r\n    movs = [(2,1),(2,-1),(-2,1),(-2,-1),(1,-2),(1,2),(-1,2),(-1,-2)]\r\n    while cola:\r\n        r,c = cola.popleft()\r\n        for dr,dc in movs:\r\n            nr, nc = r+dr,c+dc\r\n            if 0<=nr and nr < n and 0 <= nc and nc < n:\r\n                if distancias[nr][nc] ==-1:\r\n                    distancias[nr][nc] = distancias[r][c]+1\r\n                    cola.append((nr,nc))\r\n    return distancias\r\n                \r\nn,kk,ri,ci,rf,cf = map(int,input().split())\r\nri -=1\r\nci -=1\r\nrf -=1\r\ncf -=1\r\nx = bfs_grid(n,ri,ci)\r\nif(x[rf][cf]<=kk):\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',1938),
(1939,'n = int(input())\r\nfor i in range(1, n+1):\r\n    h = []\r\n    while True:\r\n        m=float(input())\r\n        if m == -1:\r\n            break\r\n        h.append(m) \r\n    c = []\r\n    for j in range(1, len(h)-1):\r\n        if h[j] > h[j-1] and h[j] > h[j+1]:\r\n            c.append(j)\r\n     print(f\"Las cumbres de la ruta {i} estan en:\", *c)',1939),
(1940,'n = int(input())\r\nfor i in range(1, n+1):\r\n    h = []\r\n    while True:\r\n        m=float(input())\r\n        if m == -1:\r\n            break\r\n        h.append(m) \r\n    c = []\r\n    for j in range(1, len(h)-1):\r\n        if h[j] > h[j-1] and h[j] > h[j+1]:\r\n            c.append(j)\r\n    print(f\"Las cumbres de la ruta {i} estan en:\", *c)',1940),
(1941,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nbool seg (vi& a , vi&b){\r\n    return a[1] < b[1];\r\n}\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if (n==-1 and m==-1 and c==-1) return -1;\r\n    cout << \"En la bodega \"<< z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    vector<vector<pair<int,int>>> pilas(m);\r\n    for(int i = 0 ; i<c ; i++){\r\n        int h,p,w;\r\n        cin >> h >> p >> w;\r\n        pilas[p].pb({h,w});\r\n    }\r\n    vi pilas_malas;\r\n    for(int i = 0 ; i<m ; i++){\r\n        if(sz(pilas[i])==0) continue;\r\n        sort(all(pilas[i]));\r\n        bool inestable = false;\r\n        if(pilas[i][0].fi !=0){\r\n            pilas_malas.pb(i);\r\n            continue;\r\n        }\r\n        for(int k = 0 ; k<sz(pilas[i])-1; k++){\r\n            int wab = pilas[i][k].se;\r\n            int war = pilas[i][k+1].se;\r\n            if(wab <= war){\r\n                inestable = true;\r\n                break;\r\n            }\r\n            int hab = pilas[i][k].fi;\r\n            int har = pilas[i][k+1].fi;\r\n            if(hab+1!=har){\r\n                inestable = true;\r\n                break;\r\n            }\r\n        }\r\n        if(inestable) pilas_malas.pb(i);\r\n    }\r\n    for(int i : pilas_malas) cout << \" \" << i;\r\n    cout << ENDL;\r\n\r\n\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1941),
(1942,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nbool seg (vi& a , vi&b){\r\n    return a[1] < b[1];\r\n}\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if (n==-1 and m==-1 and c==-1) return -1;\r\n    cout << \"En la bodega \"<< z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    vector<vector<pair<int,int>>> pilas(m);\r\n    for(int i = 0 ; i<c ; i++){\r\n        int h,p,w;\r\n        cin >> h >> p >> w;\r\n        pilas[p].pb({h,w});\r\n    }\r\n    vi pilas_malas;\r\n    for(int i = 0 ; i<m ; i++){\r\n        if(sz(pilas[i])==0) continue;\r\n        sort(all(pilas[i]));\r\n        bool inestable = false;\r\n        if(pilas[i][0].fi !=0){\r\n            pilas_malas.pb(i);\r\n            continue;\r\n        }\r\n        for(int k = 0 ; k<sz(pilas[i])-1; k++){\r\n            int wab = pilas[i][k].se;\r\n            int war = pilas[i][k+1].se;\r\n            if(wab <= war){\r\n                inestable = true;\r\n                break;\r\n            }\r\n            int hab = pilas[i][k].fi;\r\n            int har = pilas[i][k+1].fi;\r\n            if(hab+1!=har){\r\n                inestable = true;\r\n                break;\r\n            }\r\n            if(har > n){\r\n                inestable = true;\r\n                break;\r\n            }\r\n        }\r\n        if(inestable) pilas_malas.pb(i);\r\n    }\r\n    for(int i : pilas_malas) cout << \" \" << i;\r\n    cout << ENDL;\r\n\r\n\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1942),
(1943,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nbool seg (vi& a , vi&b){\r\n    return a[1] < b[1];\r\n}\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if (n==-1 and m==-1 and c==-1) return -1;\r\n    cout << \"En la bodega \"<< z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    vector<vector<pair<int,int>>> pilas(m);\r\n    for(int i = 0 ; i<c ; i++){\r\n        int h,p,w;\r\n        cin >> h >> p >> w;\r\n        pilas[p].pb({h,w});\r\n    }\r\n    vi pilas_malas;\r\n    for(int i = 0 ; i<m ; i++){\r\n        if(sz(pilas[i])==0) continue;\r\n        sort(all(pilas[i]));\r\n        bool inestable = false;\r\n        if(pilas[i][0].fi !=0){\r\n            pilas_malas.pb(i);\r\n            continue;\r\n        }\r\n        if(pilas[i].back().fi>=n){\r\n            pilas_malas.pb(i);\r\n            continue;\r\n        }\r\n        for(int k = 0 ; k<sz(pilas[i])-1; k++){\r\n            int wab = pilas[i][k].se;\r\n            int war = pilas[i][k+1].se;\r\n            if(wab <= war){\r\n                inestable = true;\r\n                break;\r\n            }\r\n            int hab = pilas[i][k].fi;\r\n            int har = pilas[i][k+1].fi;\r\n            if(hab+1!=har){\r\n                inestable = true;\r\n                break;\r\n            }\r\n        }\r\n        if(inestable) pilas_malas.pb(i);\r\n    }\r\n    for(int i : pilas_malas) cout << \" \" << i;\r\n    cout << ENDL;\r\n\r\n\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1943),
