\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1944),
(1945,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nbool seg (vi& a , vi&b){\r\n    return a[1] < b[1];\r\n}\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if (n==-1 and m==-1 and c==-1) return -1;\r\n    cout << \"En la bodega \"<< z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    vector<vector<pair<int,int>>> pilas(m);\r\n    for(int i = 0 ; i<c ; i++){\r\n        int h,p,w;\r\n        cin >> h >> p >> w;\r\n        pilas[p].pb({h,w});\r\n    }\r\n    vi pilas_malas;\r\n    for(int i = 0 ; i<m ; i++){\r\n        if(sz(pilas[i])==0) continue;\r\n        sort(all(pilas[i]));\r\n        bool inestable = false;\r\n        if(pilas[i][0].fi !=0){\r\n            pilas_malas.pb(i);\r\n            continue;\r\n        }\r\n        for(int k = 0 ; k<sz(pilas[i])-1; k++){\r\n            int wab = pilas[i][k].se;\r\n            int war = pilas[i][k+1].se;\r\n            if(wab < war){\r\n                inestable = true;\r\n                break;\r\n            }\r\n            int hab = pilas[i][k].fi;\r\n            int har = pilas[i][k+1].fi;\r\n            if(hab+1!=har){\r\n                inestable = true;\r\n                break;\r\n            }\r\n        }\r\n        if(inestable) pilas_malas.pb(i);\r\n    }\r\n    for(int i : pilas_malas) cout << \" \" << i;\r\n    cout << ENDL;\r\n\r\n\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1945),
(1946,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nbool seg (vi& a , vi&b){\r\n    return a[1] < b[1];\r\n}\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    // CAMBIO 1: Protección de lectura EOF\r\n    if(!(cin >> n >> m >> c)) return -1; \r\n    \r\n    if (n==-1 and m==-1 and c==-1) return -1;\r\n    \r\n    // Protección extra por si m viene 0 o negativo\r\n    if (m <= 0) m = 1; \r\n\r\n    cout << \"En la bodega \"<< z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    vector<vector<pair<int,int>>> pilas(m);\r\n    \r\n    for(int i = 0 ; i<c ; i++){\r\n        int h,p,w;\r\n        cin >> h >> p >> w;\r\n        // CAMBIO 2: Protección de índice para evitar crash\r\n        if(p >= 0 && p < m) {\r\n            pilas[p].pb({h,w});\r\n        }\r\n    }\r\n    \r\n    vi pilas_malas;\r\n    for(int i = 0 ; i<m ; i++){\r\n        if(pilas[i].empty()) continue;\r\n        sort(all(pilas[i]));\r\n        bool inestable = false;\r\n        \r\n        if(pilas[i][0].fi !=0){\r\n            pilas_malas.pb(i);\r\n            continue;\r\n        }\r\n        \r\n        for(int k = 0 ; k<sz(pilas[i])-1; k++){\r\n            int wab = pilas[i][k].se;\r\n            int war = pilas[i][k+1].se;\r\n\r\n            if(wab <= war){ \r\n                inestable = true;\r\n                break;\r\n            }\r\n            \r\n            int hab = pilas[i][k].fi;\r\n            int har = pilas[i][k+1].fi;\r\n            if(hab+1!=har){\r\n                inestable = true;\r\n                break;\r\n            }\r\n        }\r\n        if(inestable) pilas_malas.pb(i);\r\n    }\r\n    for(int i : pilas_malas) cout << \" \" << i;\r\n    cout << ENDL;\r\n\r\n\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1946),
(1947,'x = int(input())\r\nfor i in range (1,x+1):\r\n    nose = []\r\n    while True:\r\n        y = float(input())\r\n        nose.append(y)\r\n        if y == -1:\r\n            nose.remove(y)\r\n            break\r\n    lista = []\r\n    for j in range(1, len(nose)-1):\r\n        if nose[j-1]<nose[j] and nose[j]>nose[j+1]:\r\n            lista.append(j)\r\n    print(f\"Las cumbres de la ruta {i} estan en:\", *lista)',1947),
(1948,'#avance\r\nnumeros = input()\r\na, b, x1, y1, x2, y2 = numeros.split()\r\na = int(a)\r\nb = int(b)\r\nx1 = int(x1)\r\ny1 = int(y1)\r\nx2 = int(x2)\r\ny2 = int(y2)\r\nmatriz = [[0]*a for _ in range (a)]',1948),
(1949,'for _ in range(N):\r\n    ruta = []\r\n    while True:\r\n        valor = input().strip()\r\n        if valor == \"-1\":\r\n            break\r\n        ruta.append(float(valor))\r\n    rutas.append(ruta)\r\n    \r\nfor i in range(N):\r\n    alturas = rutas[i]\r\n    print(f\"Las cumbres de la ruta {i + 1} estan en:\", end=\"\")\r\n    hay_cumbre = False\r\n    for j in range(1, len(alturas) - 1):\r\n        if alturas[j - 1] < alturas[j] > alturas[j + 1]:\r\n            if not hay_cumbre:\r\n                print(\" \", end=\"\")\r\n                hay_cumbre = True\r\n            print(j, end=\" \")\r\n    print()',1949),
(1950,'for _ in range(N):\r\n    ruta = []\r\n    while True:\r\n        valor = input().strip()\r\n        if valor == \"-1\":\r\n            break\r\n        ruta.append(float(valor))\r\n    rutas.append(ruta)\r\n    \r\nfor i in range(N):\r\n    alturas = rutas[i]\r\n    print(f\"Las cumbres de la ruta {i + 1} estan en:\", end=\"\")\r\n    hay_cumbre = False\r\n    for j in range(1, len(alturas) - 1):\r\n        if alturas[j - 1] < alturas[j] > alturas[j + 1]:\r\n            if not hay_cumbre:\r\n                print(\" \", end=\"\")\r\n                hay_cumbre = True\r\n            print(j, end=\" \")',1950),
(1951,'bodega_id = 0\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    if entrada == \"-1 -1 -1\":\r\n        break\r\n\r\n    n, m, c = map(int, entrada.split())\r\n    pilas = {i: {} for i in range(m)}\r\n\r\n    for _ in range(c):\r\n        h, p, w = map(int, input().strip().split())\r\n        pilas[p][h] = w\r\n\r\n    pilas_inestables = []\r\n\r\n    for p in range(m):\r\n        alturas = sorted(pilas[p].keys())\r\n        pesos = [pilas[p][h] for h in alturas]\r\n        for i in range(1, len(pesos)):\r\n            if pesos[i] >= pesos[i - 1]:\r\n                pilas_inestables.append(p)\r\n                break\r\n\r\n    if pilas_inestables:\r\n        pilas_str = \" \".join(str(p) for p in sorted(pilas_inestables))\r\n        print(f\"En la bodega {bodega_id}, las torres donde hay cajas mal ordenadas son: {pilas_str}\")\r\n    else:\r\n        print(f\"En la bodega {bodega_id}, las torres donde hay cajas mal ordenadas son:\")\r\n    \r\n    bodega_id += 1',1951),
