(1953,'bodega_id = 0\r\n\r\nwhile True:\r\n    entrada = input().strip()\r\n    if entrada == \"-1 -1 -1\":\r\n        break\r\n\r\n    n, m, c = map(int, entrada.split())\r\n    pilas = {i: {} for i in range(m)}\r\n\r\n    for _ in range(c):\r\n        h, p, w = map(int, input().strip().split())\r\n        pilas[p][h] = w\r\n\r\n    pilas_inestables = []\r\n\r\n    for p in range(m):\r\n        alturas = sorted(pilas[p].keys())\r\n        pesos = [pilas[p][h] for h in alturas]\r\n        for i in range(1, len(pesos)):\r\n            if pesos[i] >= pesos[i - 1]:\r\n                pilas_inestables.append(p)\r\n                break\r\n\r\n    if pilas_inestables:\r\n        pilas_str = \" \".join(str(p) for p in sorted(pilas_inestables))\r\n        print(f\"En la bodega {bodega_id}, las torres donde hay cajas mal ordenadas son: {pilas_str}\")\r\n    else:\r\n        bodega_id+=1\r\n        print(f\"En la bodega {bodega_id}, las torres donde hay cajas mal ordenadas son:{pilas_str}\")',1953),
(1954,'#AVANCE\r\ncasos_de_prueba = int(input())\r\ngano_O= False\r\ngano_X= False\r\nfor i in range(casos_de_prueba):\r\n    tablero =[]\r\n    for _ in range(3):\r\n        fila = input()\r\n        tablero.append(fila)\r\n    for i in range(3):\r\n            if tablero[i][0] == \"O\" and tablero[i][1] == \"O\" and tablero[i][2] == \"O\":\r\n                gano_O = True\r\n                break\r\n            if tablero[i][0] == \"X\" and tablero[i][1] == \"X\"and tablero[i][2] == \"X\":\r\n                gano_X = True\r\n    for j in range (3):\r\n            if tablero[0][j]== \"O\" and tablero[1][j]== \"O\"  and tablero[2][j] == \"O\":\r\n                gano_O = True\r\n                break\r\n            if tablero[0][j]== \"X\" and tablero[1][j]== \"X\" and tablero[2][j] == \"X\":\r\n                gano_X = True\r\n    if tablero[0][0] == \"O\"and tablero[1][1] == \"O\"and tablero[2][2] == \"O\" or tablero[1][3] == \"O\"and tablero[2][2] == \"O\"and tablero[3][1] == \"O\":\r\n            gano_O = True\r\n            break\r\n    if tablero[0][0] == \"X\"and tablero[1][1] == \"X\"and tablero[2][2] == \"X\" or tablero[1][3] == \"X\"and tablero[2][2] == \"X\"and tablero[3][1] == \"X\":\r\n            gano_X = True\r\n            break\r\n    \r\nif gano_X == True:\r\n      print(\"Gana X.\")\r\nif gano_O == True:\r\n      print(\"Gana O.\")',1954),
(1955,'casos_de_prueba = int(input())\r\nfor i in range(casos_de_prueba):\r\n    gano_O= False\r\n    gano_X= False\r\n    inconcluso = False\r\n    tablero =[]\r\n    for _ in range(3):\r\n        fila = input()\r\n        tablero.append(fila)\r\n    cant_O = sum(fila.count(\"O\") for fila in tablero) \r\n    cant_X = sum(fila.count(\"X\") for fila in tablero)\r\n    for i in range(3):\r\n            if tablero[i][0] == \"O\" and tablero[i][1] == \"O\" and tablero[i][2] == \"O\":\r\n                gano_O = True\r\n            if tablero[i][0] == \"X\" and tablero[i][1] == \"X\"and tablero[i][2] == \"X\":\r\n                gano_X = True\r\n    for j in range (3):\r\n            if tablero[0][j]== \"O\" and tablero[1][j]== \"O\"  and tablero[2][j] == \"O\":\r\n                gano_O = True\r\n            if tablero[0][j]== \"X\" and tablero[1][j]== \"X\" and tablero[2][j] == \"X\":\r\n                gano_X = True\r\n    if tablero[0][0] == \"O\"and tablero[1][1] == \"O\"and tablero[2][2] == \"O\" or tablero[0][2] == \"O\"and tablero[1][1] == \"O\"and tablero[2][0] == \"O\":\r\n            gano_O = True\r\n    if tablero[0][0] == \"X\"and tablero[1][1] == \"X\"and tablero[2][2] == \"X\" or tablero[0][2] == \"X\"and tablero[1][1] == \"X\"and tablero[2][0] == \"X\":\r\n            gano_X = True\r\n    for i in range(3):\r\n        for j in range(3):\r\n            if tablero[i][j] == \"-\":\r\n                 inconcluso = True\r\n    if gano_X == True:\r\n      print(\"Gana X.\")\r\n    elif gano_O == True:\r\n      print(\"Gana O.\")\r\n    elif inconcluso ==True and cant_O > cant_X:\r\n     print(\"Juego inconcluso, juega X.\")\r\n    elif inconcluso ==True and cant_O == cant_X:\r\n     print(\"Juego inconcluso, juega O.\")\r\n    if cant_X>cant_O or gano_X == True and gano_O==True:\r\n     print(\"Juego incorrecto\")\r\n    else:\r\n      print(\"Juego empatado.\")',1955),
(1956,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nint solve(int z){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if (n==-1 and m== -1 and c==-1) return -1;\r\n    vvi pilas;\r\n    for(int i = 0 ; i<m ; i++){\r\n        vi p(n,-INF_INT);\r\n        pilas.pb(p);\r\n    }\r\n    for(int i = 0 ; i<c ; i++){\r\n        int h,p,w;\r\n        cin >> h >> p >> w;\r\n        pilas[p][h]=w;\r\n    }\r\n    cout << \"En la bodega \" << z << \", las torres donde hay cajas mal ordenadas son:\";\r\n    for(int i = 0 ; i<m ; i++){\r\n        vi p = pilas[i];\r\n        for(int k = 0 ; k<n-1 ; k++){\r\n            if(p[k]<=p[k+1]){\r\n                if(p[k]!=-INF_INT or p[k+1]!=-INF_INT){\r\n                    cout << \" \" << i;\r\n                    break;\r\n                }\r\n            }\r\n        }\r\n    }\r\n    cout << ENDL;\r\n    return 0;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    //cin >> t;\r\n    int i = 0;\r\n    while(true){\r\n        if(solve(i)==-1){\r\n            break;\r\n        }\r\n        i++;\r\n    }\r\n    return 0;\r\n}',1956),
(1957,'casos_de_prueba = int(input())\r\nfor i in range(casos_de_prueba):\r\n    gano_O= False\r\n    gano_X= False\r\n    inconcluso = False\r\n    tablero =[]\r\n    for _ in range(3):\r\n        fila = input()\r\n        tablero.append(fila)\r\n    cant_O = sum(fila.count(\"O\") for fila in tablero) \r\n    cant_X = sum(fila.count(\"X\") for fila in tablero)\r\n    for i in range(3):\r\n            if tablero[i][0] == \"O\" and tablero[i][1] == \"O\" and tablero[i][2] == \"O\":\r\n                gano_O = True\r\n            if tablero[i][0] == \"X\" and tablero[i][1] == \"X\"and tablero[i][2] == \"X\":\r\n                gano_X = True\r\n    for j in range (3):\r\n            if tablero[0][j]== \"O\" and tablero[1][j]== \"O\"  and tablero[2][j] == \"O\":\r\n                gano_O = True\r\n            if tablero[0][j]== \"X\" and tablero[1][j]== \"X\" and tablero[2][j] == \"X\":\r\n                gano_X = True\r\n    if tablero[0][0] == \"O\"and tablero[1][1] == \"O\"and tablero[2][2] == \"O\" or tablero[0][2] == \"O\"and tablero[1][1] == \"O\"and tablero[2][0] == \"O\":\r\n            gano_O = True\r\n    if tablero[0][0] == \"X\"and tablero[1][1] == \"X\"and tablero[2][2] == \"X\" or tablero[0][2] == \"X\"and tablero[1][1] == \"X\"and tablero[2][0] == \"X\":\r\n            gano_X = True\r\n    for i in range(3):\r\n        for j in range(3):\r\n            if tablero[i][j] == \"-\":\r\n                 inconcluso = True\r\n    incorrecto = False\r\n    if cant_X > cant_O:\r\n        incorrecto= True\r\n    if gano_X == True and gano_O==True:\r\n        incorrecto= True\r\n    if gano_O == True and cant_O <= cant_X:\r\n        incorrecto = True\r\n    if gano_X == True and cant_X < cant_O:\r\n        incorrecto = True\r\n\r\n    if incorrecto==True:\r\n     print(\"Juego incorrecto\")\r\n    elif gano_X == True:\r\n      print(\"Gana X.\")\r\n    elif gano_O == True:\r\n      print(\"Gana O.\")\r\n    elif inconcluso ==True and cant_O > cant_X:\r\n     print(\"Juego inconcluso, juega X.\")\r\n    elif inconcluso ==True and cant_O == cant_X:\r\n     print(\"Juego inconcluso, juega O.\")\r\n    else:\r\n      print(\"Juego empatado.\")',1957),
(1958,'casos_de_prueba = int(input())\r\nfor i in range(casos_de_prueba):\r\n    gano_O= False\r\n    gano_X= False\r\n    inconcluso = False\r\n    tablero =[]\r\n    for _ in range(3):\r\n        fila = input()\r\n        tablero.append(fila)\r\n    cant_O = sum(fila.count(\"O\") for fila in tablero) \r\n    cant_X = sum(fila.count(\"X\") for fila in tablero)\r\n    for i in range(3):\r\n            if tablero[i][0] == \"O\" and tablero[i][1] == \"O\" and tablero[i][2] == \"O\":\r\n                gano_O = True\r\n            if tablero[i][0] == \"X\" and tablero[i][1] == \"X\"and tablero[i][2] == \"X\":\r\n                gano_X = True\r\n    for j in range (3):\r\n            if tablero[0][j]== \"O\" and tablero[1][j]== \"O\"  and tablero[2][j] == \"O\":\r\n                gano_O = True\r\n            if tablero[0][j]== \"X\" and tablero[1][j]== \"X\" and tablero[2][j] == \"X\":\r\n                gano_X = True\r\n    if (tablero[0][0] == \"O\"and tablero[1][1] == \"O\"and tablero[2][2] == \"O\") or (tablero[0][2] == \"O\"and tablero[1][1] == \"O\"and tablero[2][0] == \"O\"):\r\n            gano_O = True\r\n    if (tablero[0][0] == \"X\"and tablero[1][1] == \"X\"and tablero[2][2] == \"X\") or (tablero[0][2] == \"X\"and tablero[1][1] == \"X\"and tablero[2][0] == \"X\"):\r\n            gano_X = True\r\n    for i in range(3):\r\n        for j in range(3):\r\n            if tablero[i][j] == \"-\":\r\n                 inconcluso = True\r\n    incorrecto = False\r\n    if cant_X > cant_O:\r\n        incorrecto= True\r\n    if gano_X == True and gano_O==True:\r\n        incorrecto= True\r\n    if gano_X == True and cant_X < cant_O:\r\n        incorrecto = True\r\n    if gano_O == True and cant_O <= cant_X:\r\n        incorrecto = True\r\n\r\n    if incorrecto==True:\r\n     print(\"Juego incorrecto\")\r\n    elif gano_X == True:\r\n      print(\"Gana X.\")\r\n    elif gano_O == True:\r\n      print(\"Gana O.\")\r\n    elif inconcluso ==True and cant_O > cant_X:\r\n     print(\"Juego inconcluso, juega X.\")\r\n    elif inconcluso ==True and cant_O == cant_X:\r\n     print(\"Juego inconcluso, juega O.\")\r\n    else:\r\n      print(\"Juego empatado.\")',1958),
(1959,'i = 0\r\nwhile True:\r\n    n,m,c = map(int,input().split())\r\n    if n==-1 and m==-1 and c==-1: break\r\n    b = [[-1 for _ in range(n)]for o in range(m)]\r\n    print(end=f\"En la bodega {i}, las torres donde hay cajas mal ordenadas son:\")\r\n    for k in range(c):\r\n        h,p,w = map(int,input().split())\r\n        b[p][h] = w\r\n    ki = 0\r\n    for k in b:\r\n        for z in range(len(k)-1):\r\n            if(k[z]<=k[z+1]):\r\n                if(k[z]!=-1 or k[z+1]!=-1):\r\n                    print(end=f\" {ki}\")\r\n                    break\r\n        ki+=1\r\n    i+=1\r\n    print(\"\")',1959),
(1960,'i = 0\r\nwhile True:\r\n    n,m,c = map(int,input().split())\r\n    if n==-1 and m==-1 and c==-1:\r\n        break\r\n    b = [[-1 for _ in range(n)] for o in range(m)]\r\n    print(end=f\"En la bodega {i}, las torres donde hay cajas mal ordenadas son:\")\r\n    for k in range(c):\r\n        h,p,w = map(int,input().split())\r\n        b[p][h] = w\r\n    for k in range(len(b)):\r\n        p = b[k]\r\n        for z in range(len(p)-1):\r\n            if(p[z]<=p[z+1]):\r\n                if(p[z]!=-1 or p[z+1]!=-1):\r\n                    print(end=f\" {k}\")\r\n                    break\r\n    i+=1\r\n    print(\"\")',1960),
(1961,'i = 0\r\nwhile True:\r\n    x = input()\r\n    if x == \"-1 -1 -1\":\r\n        break\r\n    n,m,c = map(int,x.split())\r\n    b = [[-1 for _ in range(n)] for o in range(m)]\r\n    print(end=f\"En la bodega {i}, las torres donde hay cajas mal ordenadas son:\")\r\n    for k in range(c):\r\n        h,p,w = map(int,input().split())\r\n        b[p][h] = w\r\n    for k in range(len(b)):\r\n        p = b[k]\r\n        for z in range(len(p)-1):\r\n            if(p[z]<=p[z+1]):\r\n                if(p[z]!=-1 or p[z+1]!=-1):\r\n                    print(end=f\" {k}\")\r\n                    break\r\n    i+=1\r\n    print(\"\")',1961),
(1962,'casos_de_prueba = int(input())\r\nfor i in range(casos_de_prueba):\r\n    gano_O= False\r\n    gano_X= False\r\n    inconcluso = False\r\n    tablero =[]\r\n    for _ in range(3):\r\n        fila = input()\r\n        tablero.append(fila)\r\n    cant_O = sum(fila.count(\"O\") for fila in tablero) \r\n    cant_X = sum(fila.count(\"X\") for fila in tablero)\r\n    for i in range(3):\r\n            if tablero[i][0] == \"O\" and tablero[i][1] == \"O\" and tablero[i][2] == \"O\":\r\n                gano_O = True\r\n            if tablero[i][0] == \"X\" and tablero[i][1] == \"X\"and tablero[i][2] == \"X\":\r\n                gano_X = True\r\n    for j in range (3):\r\n            if tablero[0][j]== \"O\" and tablero[1][j]== \"O\"  and tablero[2][j] == \"O\":\r\n                gano_O = True\r\n            if tablero[0][j]== \"X\" and tablero[1][j]== \"X\" and tablero[2][j] == \"X\":\r\n                gano_X = True\r\n    if (tablero[0][0] == \"O\"and tablero[1][1] == \"O\"and tablero[2][2] == \"O\") or (tablero[0][2] == \"O\"and tablero[1][1] == \"O\"and tablero[2][0] == \"O\"):\r\n            gano_O = True\r\n    if (tablero[0][0] == \"X\"and tablero[1][1] == \"X\"and tablero[2][2] == \"X\") or (tablero[0][2] == \"X\"and tablero[1][1] == \"X\"and tablero[2][0] == \"X\"):\r\n            gano_X = True\r\n    for i in range(3):\r\n        for j in range(3):\r\n            if tablero[i][j] == \"-\":\r\n                 inconcluso = True\r\n    incorrecto = False\r\n    if cant_X > cant_O:\r\n        incorrecto= True\r\n    if gano_X == True and gano_O==True:\r\n        incorrecto= True\r\n    if gano_X == True and cant_X != cant_O:\r\n        incorrecto = True\r\n    if gano_O == True and cant_O <= cant_X:\r\n        incorrecto = True\r\n    if cant_O > cant_X +1:\r\n        incorrecto = True\r\n\r\n    if incorrecto==True:\r\n     print(\"Juego incorrecto\")\r\n    elif gano_X == True:\r\n      print(\"Gana X.\")\r\n    elif gano_O == True:\r\n      print(\"Gana O.\")\r\n    elif inconcluso ==True and cant_O > cant_X:\r\n     print(\"Juego inconcluso, juega X.\")\r\n    elif inconcluso ==True and cant_O == cant_X:\r\n     print(\"Juego inconcluso, juega O.\")\r\n    else:\r\n      print(\"Juego empatado.\")',1962),
(1963,'i = 0\r\nwhile True:\r\n    try:\r\n        x = input()\r\n        if x == \"-1 -1 -1\":\r\n            break\r\n        n,m,c = map(int,x.split())\r\n        b = [[-1 for _ in range(n)] for o in range(m)]\r\n        print(end=f\"En la bodega {i}, las torres donde hay cajas mal ordenadas son:\")\r\n        for k in range(c):\r\n            h,p,w = map(int,input().split())\r\n            b[p][h] = w\r\n        for k in range(len(b)):\r\n            p = b[k]\r\n            for z in range(len(p)-1):\r\n                if(p[z]<=p[z+1]):\r\n                    if(p[z]!=-1 or p[z+1]!=-1):\r\n                        print(end=f\" {k}\")\r\n                        break\r\n        i+=1\r\n        print(\"\")\r\n    except ValueError:\r\n        pass',1963),
(1964,'import sys\r\nsys.stdin = open(\"entrada.txt\", \"r\")\r\nsys.stdout = open(\"salida.txt\", \"w\")\r\n\r\n#################################################\r\n#################################################\r\n\'\'\'\r\nProblema:\r\n\'\'\'\r\ndef solve():\r\n    i = 0\r\n    while True:\r\n        x = input()\r\n        if x == \"-1 -1 -1\":\r\n            return\r\n        n,m,c = map(int,x.split())\r\n        b = [[-1 for _ in range(n)] for o in range(m)]\r\n        print(end=f\"En la bodega {i}, las torres donde hay cajas mal ordenadas son:\")\r\n        for k in range(c):\r\n            h,p,w = map(int,input().split())\r\n            b[p][h] = w\r\n        for k in range(len(b)):\r\n            p = b[k]\r\n            for z in range(len(p)-1):\r\n                if(p[z]<=p[z+1]):\r\n                    if(p[z]!=-1 or p[z+1]!=-1):\r\n                        print(end=f\" {k}\")\r\n                        break\r\n        i+=1\r\n        print(\"\")\r\nsolve()',1964),
