o ==True: \r\n        if cant_O > cant_X:\r\n            print(\"Juego inconcluso, juega X.\")\r\n        else:\r\n            print(\"Juego inconcluso, juega O.\")\r\n    if gano_O == False and gano_X== False and inconcluso==False and cant_O>cant_X:\r\n      print(\"Juego empatado.\")',1974),
(1975,'casos_de_prueba = int(input())\r\n\r\nfor _ in range(casos_de_prueba):\r\n    tablero = [input() for _ in range(3)]\r\n\r\n    cant_O = sum(f.count(\"O\") for f in tablero)\r\n    cant_X = sum(f.count(\"X\") for f in tablero)\r\n\r\n\r\n    gano_O = False\r\n    gano_X = False\r\n\r\n    for i in range(3):\r\n        if tablero[i][0] == tablero[i][1] == tablero[i][2] == \"O\":\r\n            gano_O = True\r\n        if tablero[i][0] == tablero[i][1] == tablero[i][2] == \"X\":\r\n            gano_X = True\r\n\r\n    for j in range(3):\r\n        if tablero[0][j] == tablero[1][j] == tablero[2][j] == \"O\":\r\n            gano_O = True\r\n        if tablero[0][j] == tablero[1][j] == tablero[2][j] == \"X\":\r\n            gano_X = True\r\n\r\n    if tablero[0][0] == tablero[1][1] == tablero[2][2] == \"O\" or tablero[0][2] == tablero[1][1] == tablero[2][0] == \"O\":\r\n        gano_O = True\r\n    if tablero[0][0] == tablero[1][1] == tablero[2][2] == \"X\" or tablero[0][2] == tablero[1][1] == tablero[2][0] == \"X\":\r\n        gano_X = True\r\n\r\n    inconcluso = False\r\n    for a in range(3):\r\n        for b in range(3):\r\n            if tablero[a][b] == \"-\":\r\n                inconcluso = True\r\n\r\n    incorrecto = False\r\n\r\n\r\n    if not (cant_O == cant_X or cant_O == cant_X + 1):\r\n        incorrecto = True\r\n\r\n    if gano_X and gano_O:\r\n        incorrecto = True\r\n\r\n    if gano_O and cant_O != cant_X + 1:\r\n        incorrecto = True\r\n    if gano_X and cant_O != cant_X:\r\n        incorrecto = True\r\n    if incorrecto:\r\n        print(\"Juego incorrecto.\")\r\n    elif gano_X:\r\n        print(\"Gana X.\")\r\n    elif gano_O:\r\n        print(\"Gana O.\")\r\n    elif inconcluso:\r\n        if cant_O == cant_X:\r\n            print(\"Juego inconcluso, juega O.\")\r\n        else:\r\n            print(\"Juego inconcluso, juega X.\")\r\n    else:\r\n        print(\"Juego empatado.\")',1975),
(1976,'n = int(input())\r\nMATRIZ = [[],[],[]]\r\nfor i in range(n):\r\n    linea_1 = input().strip()\r\n    linea_2 = input().strip()\r\n    linea_3 = input().strip()\r\n    MATRIZ = linea_1+linea_2+linea_3\r\n    \r\n    #CASO EN GANA X\r\n    GANA_X = False\r\n    if MATRIZ[0] == MATRIZ[1] and MATRIZ[1] == MATRIZ[2] and MATRIZ[2] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[3] == MATRIZ[4] and MATRIZ[4] == MATRIZ[5] and MATRIZ[5] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[6] == MATRIZ[7] and MATRIZ[7] == MATRIZ[8] and MATRIZ[8] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[0] == MATRIZ[3] and MATRIZ[3] == MATRIZ[6] and MATRIZ[6] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[1] == MATRIZ[4] and MATRIZ[4] == MATRIZ[7] and MATRIZ[7] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[2] == MATRIZ[5] and MATRIZ[5] == MATRIZ[8] and MATRIZ[8] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[0] == MATRIZ[4] and MATRIZ[4] == MATRIZ[8] and MATRIZ[8] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[2] == MATRIZ[4] and MATRIZ[4] == MATRIZ[6] and MATRIZ[6] == \"X\":\r\n        GANA_X = True\r\n\r\n    #CASO EN QUE GANA O\r\n    GANA_O = False\r\n    if MATRIZ[0] == MATRIZ[1] and MATRIZ[1] == MATRIZ[2] and MATRIZ[2] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[3] == MATRIZ[4] and MATRIZ[4] == MATRIZ[5] and MATRIZ[5] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[6] == MATRIZ[7] and MATRIZ[7] == MATRIZ[8] and MATRIZ[8] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[0] == MATRIZ[3] and MATRIZ[3] == MATRIZ[6] and MATRIZ[6] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[1] == MATRIZ[4] and MATRIZ[4] == MATRIZ[7] and MATRIZ[7] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[2] == MATRIZ[5] and MATRIZ[5] == MATRIZ[8] and MATRIZ[8] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[0] == MATRIZ[4] and MATRIZ[4] == MATRIZ[8] and MATRIZ[8] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[2] == MATRIZ[4] and MATRIZ[4] == MATRIZ[6] and MATRIZ[6] == \"O\":\r\n        GANA_O = True\r\n    \r\n    JUEGO_INCONCLUSO = False\r\n    if GANA_O == False and GANA_X == False:\r\n        JUEGO_INCONCLUSO = True\r\n    else:\r\n        pass\r\n\r\n    O = 0\r\n    X = 0\r\n    vacio = 0\r\n    for i in MATRIZ:\r\n        if i ==\"X\":\r\n            X +=1\r\n        elif i == \"O\":\r\n            O +=1\r\n        else:\r\n            vacio +=1\r\n    if X>O or (GANA_O == GANA_X and GANA_X==True):\r\n        print(\"Juego incorrecto.\")\r\n    elif X+1 == O and vacio == 0:\r\n        print(\"Juego empatado.\")\r\n    elif GANA_X == True:\r\n        print(\"Gana X.\")\r\n    elif GANA_O == True:\r\n        print(\"Gana O.\")\r\n    elif X == O and vacio != 0:\r\n        print(\"Juego inconcluso, juega O.\")\r\n    elif (X+1) == O and vacio !=0:\r\n        print(\"Juego inconcluso, juega X.\")',1976),
