(1985,'a = input().strip()\r\nb = input().strip()\r\nc = input().strip()\r\n\r\nn = int(input().strip())\r\n\r\nset_disponibles = set(a)\r\nset_obligatorias = set(b)\r\nset_prohibidas = set(c)\r\n\r\npalabras_validas = []\r\n\r\nfor _ in range(n):\r\n    palabra = input().strip()\r\n    set_palabra = set(palabra)\r\n\r\n    if (set_palabra <= set_disponibles and \r\n        set_obligatorias <= set_palabra and \r\n        set_palabra.isdisjoint(set_prohibidas)):\r\n        \r\n        palabras_validas.append(palabra)\r\n\r\nif len(palabras_validas) > 0:\r\n    for p in palabras_validas:\r\n        print(p)\r\nelse:\r\n    print(\"-\")',1985),
