(1991,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nvoid solve(){\r\n    int a;\r\n    cin >> a;\r\n    if(a>100) cout << \"El agua estara en estado gaseoso\" << ENDL;\r\n    else if(a<0) cout << \"El agua estara en estado solido \" << ENDL;\r\n    else cout << \"El agua estara en estado liquido\" << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1991),
(1992,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\nvoid solve(){\r\n    float a,b,c,d,e;\r\n    while(cin>>a>>b>>c>>d>>e){\r\n        if(a<=b and b<=c and c<=d and d<=e){\r\n            cout << \"Creciente\" << ENDL;\r\n            continue;\r\n        }\r\n        if(a>=b and b>=c and c>=d and d>=e){\r\n            cout << \"Decreciente\" << ENDL;\r\n            continue;\r\n        }\r\n        cout << \"Ninguno\" << ENDL;\r\n    }\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1992),
(1993,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    const double PI = 3.14159265;\r\n    double r;\r\n    cin >> r;\r\n    r/=2.0;\r\n    cout << setprecision(2) << fixed << r*r*PI << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1993),
(1994,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vi v(n);\r\n    for(int i = 0 ; i<n ; i++){\r\n        cin >> v[i];  \r\n    }\r\n    reverse(all(v));\r\n    for(int i : v) cout << i << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1994),
(1995,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    const float iva = 0.19;\r\n    float n;\r\n    cin >> n;\r\n    if(n>150000) n*=0.75;\r\n    cout << setprecision(2) << fixed << n*iva << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1995),
(1996,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int cc = 0;\r\n    while(true){\r\n        int a;\r\n        cin >> a;\r\n        if(a==0) break;\r\n        cc+=a;\r\n    }\r\n    cout << \"Juanito ha ahorrado:\" << ENDL;\r\n    cout << cc << ENDL;\r\n    cout << \"pesos\" << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1996),
(1997,'/******************************************************************************\r\n\r\n                              Online C++ Compiler.\r\n               Code, Compile, Run and Debug C++ program online.\r\nWrite your code in this editor and press \"Run\" button to compile and execute it.\r\n\r\n*******************************************************************************/\r\n\r\n#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int cc = 0;\r\n    while(true){\r\n        int a;\r\n        cin >> a;\r\n        if(a==0) break;\r\n        bool b3 = false;\r\n        bool b5 = false;\r\n        if(a%3==0) b3 = true;\r\n        if(a%5==0) b5 = true;\r\n        if(b3 && b5){\r\n            cout << \"MÚLTIPLO DE AMBOS\" << ENDL;\r\n            continue;\r\n        }\r\n        if(b3){\r\n            cout << \"MÚLTIPLO DE 3\" << ENDL;\r\n            continue;\r\n        }\r\n        if(b5){\r\n            cout << \"MÚLTIPLO DE 5\" << ENDL;\r\n            continue;\r\n        }\r\n        cout << \"NO ES MÚLTIPLO DE 3 NI DE 5\" << ENDL;\r\n    }\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1997),
(1998,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int a,b;\r\n    cin >> a >> b;\r\n    for(int i = a ; i<=a*b ; i+=a) cout << i << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1998),
(1999,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    float a,b;\r\n    cin >> a >> b;\r\n    cout << setprecision(2) << fixed << b/a << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',1999),
(2000,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    for(int i = 1 ; i<=n  ; i++){\r\n        if (n%i==0) cout << i << ENDL;\r\n    }\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2000),
(2001,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    float M=0;\r\n    int idx = 0;\r\n    for(int i = 1 ; i<=n  ; i++){\r\n        float x;\r\n        cin >> x;\r\n        if(M<x){\r\n            M = x;\r\n            idx = i;\r\n        }\r\n    }\r\n    cout << idx << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2001),
(2002,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n \r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n \r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\n \r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    float c;\r\n    for(int i = 0 ; i<n ; i++){\r\n        float x;\r\n        cin >> x;\r\n        c+=x;\r\n    }\r\n    cout << setprecision(2) << fixed << c/n << ENDL;\r\n}\r\n \r\n \r\n \r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n \r\n    int t=1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2002),
(2003,'n, k, r_i, c_i, r_fin, c_fin = map(int, input().split())\r\n\r\nr_i -= 1\r\nc_i -= 1\r\nr_fin -= 1\r\nc_fin -= 1\r\n\r\n\r\nif r_i == r_fin and c_i == c_fin:\r\n    print(\"SI\")\r\nelse:\r\n    cola = [(r_i, c_i, 0)]\r\n    indice = 0\r\n    visitado = [[False] * n for _ in range(n)]\r\n    visitado[r_i][c_i] = True\r\n\r\n    movimientos = [\r\n        (2, 1), (2, -1), (-2, 1), (-2, -1),\r\n        (1, 2), (1, -2), (-1, 2), (-1, -2)\r\n    ]\r\n\r\n    encontrado = False\r\n\r\n    while indice < len(cola):\r\n        r, c, dist = cola[indice]\r\n        indice += 1\r\n\r\n        if dist >= k:\r\n            continue\r\n\r\n        for dr, dc in movimientos:\r\n            nr, nc = r + dr, c + dc\r\n\r\n            if 0 <= nr < n and 0 <= nc < n:\r\n                if not visitado[nr][nc]:\r\n                    if nr == r_fin and nc == c_fin:\r\n                        print(\"SI\")\r\n                        encontrado = True\r\n                        indice = len(cola) + 1\r\n                        break\r\n                    visitado[nr][nc] = True\r\n                    cola.append((nr, nc, dist + 1))\r\n        \r\n        if encontrado:\r\n            break\r\n    if not encontrado:\r\n        print(\"NO\")',2003),
(2004,'entrada=int(input())\r\nfor _ in range(entrada):\r\n    peso_maximo=int(input())\r\n    lista=list(map(int, input().split()))\r\n    nueva=[]\r\n    for i in lista:\r\n        if i<=peso_maximo:\r\n            nueva.append(i)\r\n    if nueva:\r\n        print(max(nueva))\r\n    else:\r\n        print(0)',2004),
(2005,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int des = 0,exp = 0,nac = 0;\r\n    while(true){\r\n        string t,c;\r\n        cin >> t;\r\n        if(t==\"-1\") break;\r\n        cin >> c;\r\n        if(c==\"-1\") break;\r\n        if(t==\"P\"){\r\n            des++;\r\n            continue;\r\n        }\r\n        if(c==\"A\"){\r\n            nac++;\r\n            continue;\r\n        }\r\n        exp++;\r\n    }\r\n    cout << des << ENDL << nac << ENDL << exp << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2005),
(2006,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int x;\r\n    cin >> x;\r\n    if(x%2==0) cout << \"PAR\" << ENDL;\r\n    else cout << \"IMPAR\" << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2006),
(2007,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int x;\r\n    cin >> x;\r\n    if(x>=10) cout << x*3 << ENDL;\r\n    else cout << x/4 << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2007),
(2008,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    float x,h;\r\n    cin >> x >> h;\r\n    if(h>40) cout << setprecision(1) << fixed << 40*x + (h-40)*x*1.5 << ENDL;\r\n    else cout << setprecision(1) << fixed << h*x << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2008),
(2009,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if(n+m==c) cout << c << ENDL;\r\n    else cout << \"ALERTA\" << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2009),
(2010,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n,m,c;\r\n    cin >> n >> m >> c;\r\n    if(n+m==c) cout << c << ENDL;\r\n    else cout << \"Alerta\" << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2010),
(2011,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    double a,b,c;\r\n    cin >> a >> b >> c;\r\n    double dis = pow(b,2)-4*a*c;\r\n    if(0>dis){\r\n        cout << \"No tiene raices reales\" << ENDL;\r\n        return;\r\n    }\r\n    double x1 = (-b-pow(dis,1.0/2.0))/(2.0*a);\r\n    double x2 = (-b+pow(dis,1.0/2.0))/(2.0*a);\r\n    cout << setprecision(6) << fixed << x1 << \" \" << x2 << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2011),
(2012,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    int po = 0,ng = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        int x;\r\n        cin >> x;\r\n        if(x>0)po++;\r\n        else if(x<0) ng++;\r\n    }\r\n    cout << po << \" \" << ng << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2012),
(2013,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    for(int i = n ; i<=m ; i+=n) cout << i << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2013),
(2014,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    if (n<6){\r\n        cout << \"Sin numeros perfectos\"<< ENDL;\r\n        return;\r\n    }\r\n    for(int i = 6 ; i<=n ; i++){\r\n        int t = 0;\r\n        for(int k = 1 ; k<i ; k++){\r\n            if(i%k==0) t+=k;\r\n        }\r\n        if(t==i) cout << i << ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2014);
