(2015,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    vector<double> r(4);\r\n    vector<double> p(4);\r\n    for(int i = 0 ; i < 4 ; i++) cin >> r[i];\r\n    for(int i = 0 ; i < 4 ; i++) cin >> p[i];\r\n    double M = 0;\r\n    int idx = 0;\r\n    for(int i = 0 ; i<4  ; i++){\r\n        double x = pow(r[i],2.0)/p[i];\r\n        if(x>M){\r\n            M = x;\r\n            idx = i;\r\n        }\r\n    }\r\n    vector<string> t = { \"pequeña\", \"mediana\", \"grande\" , \"familiar\"};\r\n    cout << t[idx] << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2015),
(2016,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int a = 0 , b = 0 , c = 0;\r\n    while(true){\r\n        string x;\r\n        cin >> x;\r\n        if(x==\"Tiempo\") break;\r\n        if(x==\"A\") a++;\r\n        if(x==\"B\") b++;\r\n        if(x==\"C\") c++;\r\n    }\r\n    cout << \"Andrea \" << a << ENDL << \"Bruno \" << b << ENDL<< \"Camila \" << c << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2016),
(2017,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int idx = 0;\r\n    int i = 1;\r\n    int M = 0;\r\n    while(true){\r\n        int a,b,c;\r\n        cin >> a >> b >> c;\r\n        if(a+b+c==0) break;\r\n        if(a+b+c>M){\r\n            M = a+b+c;\r\n            idx = i;\r\n        }\r\n        i++;\r\n    }\r\n    cout << idx << \" \" << M << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2017),
(2018,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int hr = 0 ,ml = 0,sp = 0;\r\n    while(true){\r\n        string p;\r\n        cin >> p;\r\n        if(p==\"FIN\") break;\r\n        int edad;\r\n        cin >> edad;\r\n        if(p== \"SueñosDePapel\"){\r\n            if(edad<12) sp+=3000;\r\n            else sp+=5000;\r\n        }\r\n        if(p==\"ElMisterioDelLago\"){\r\n            if(edad>=13) ml +=5000;\r\n        }\r\n        if(p==\"HorizonteRojo\"){\r\n            if(edad>=18) hr +=5000;\r\n        }\r\n    }\r\n    cout << \"HorizonteRojo: \" << hr << ENDL << \"ElMisterioDelLago: \" << ml << ENDL << \"SueñosDePapel: \"<< sp << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2018),
(2019,'matriz=[[\".\" for i in range(12)]for j in range(12)]\r\nentrada=int(input())\r\nfor _ in range(entrada):\r\n    inicio=input()\r\n    dir,fila,columna,palabra=inicio.split()\r\n    fila=int(fila)\r\n    columna=int(columna)\r\n \r\n    if dir==\"H\":\r\n     for i in range(len(palabra)):\r\n             if columna+len(palabra)<12:\r\n              matriz[fila][columna+i]=palabra[i]\r\n    elif dir==\"V\":\r\n        for i in range(len(palabra)):\r\n             if fila+len(palabra)<12:\r\n              matriz[fila+i][columna]=palabra[i]\r\n\r\n    \r\nfor i in matriz:\r\n    print(i)',2019),
(2020,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    while(true){\r\n        int x;\r\n        cin >> x;\r\n        if(x==0) break;\r\n        int i = 1;\r\n        while(x%2==0){\r\n            i++;\r\n            x/=2;\r\n        }\r\n        cout << x << \" \" << i << ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2020),
(2021,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int pm;\r\n    cin >> pm;\r\n    int mc = 0;\r\n    for(int i = 0 ; i<4 ; i++){\r\n        int x;\r\n        cin >> x;\r\n        if(mc<x && x<=pm) mc = x;\r\n    }\r\n    cout << mc << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2021),
(2022,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int a,b;\r\n    cin >> a >> b;\r\n    cout << b/a << \" \" << b%a << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2022),
(2023,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int total = 0;\r\n    int n;\r\n    cin >> n;\r\n    for(int i = 0 ; i<n ; i++){\r\n        char c;\r\n        int d;\r\n        cin >> c >> d;\r\n        total+=d*500;\r\n        if(c==\'D\') total+=2000;\r\n        if(c==\'P\') total+=5000;\r\n    }\r\n    cout << total << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2023),
(2024,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    vi v(3,0);\r\n    int i = 0;\r\n    while(true){\r\n        char c;\r\n        cin >> c;\r\n        if(c==\'R\') break;\r\n        if(c==\'T\'){\r\n            i++;\r\n            i=i%3;\r\n        }\r\n        if(c==\'F\') v[i]++;\r\n    }\r\n    cout << v[0] << \" \" << v[1 ] << \" \" << v[2] << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2024),
(2025,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n,t;\r\n    cin >> n >> t;\r\n    vi v;\r\n    for(int i = 0 ; i<n ; i++){\r\n        int x;\r\n        cin >> x;\r\n        v.pb(x);\r\n    }\r\n    float total_alertas = 0;\r\n    int num_alertas = 0;\r\n    for(int i = 1 ; i<n ; i++){\r\n        if(abs(v[i]-v[i-1])>t){\r\n            cout << \"ALERTA\" << ENDL;\r\n            total_alertas+=abs(v[i]-v[i-1]);\r\n            num_alertas++;\r\n        } else cout << \"OK\" << ENDL;\r\n    }\r\n    cout << num_alertas << ENDL;\r\n    if(num_alertas==0){\r\n        float x = 0 ;\r\n        cout << setprecision(2) << fixed << x << ENDL;\r\n    }\r\n    else {\r\n        cout << setprecision(2) << fixed << total_alertas/num_alertas << ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2025),
(2026,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    cout << \"# Collatz para n = \";\r\n    int n;\r\n    cin >> n;\r\n    cout << n << ENDL;\r\n    cout << n << ENDL;\r\n    while(true){\r\n        if(n==1){\r\n            return;\r\n        }\r\n        if(n%2==0){\r\n            n/=2;\r\n            cout << n << ENDL;\r\n        } else{\r\n            n = 3*n+1;\r\n            cout << n << ENDL;\r\n        }\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2026),
(2027,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    if(n%400 == 0){\r\n        cout << \"BISIESTO\" <<ENDL;\r\n        return;\r\n    }\r\n    if(n%100 == 0){\r\n        cout << \"NO BISIESTO\" << ENDL;\r\n        return;\r\n    }\r\n    if(n%4 == 0){\r\n        cout << \"BISIESTO\" <<ENDL;\r\n        return;\r\n    }\r\n    cout << \"NO BISIESTO\" << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2027),
(2028,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    vi v;\r\n    while(true){\r\n        float x;\r\n        cin >> x;\r\n        if(x==-1) break;\r\n        v.pb(x);\r\n    }\r\n    cout << \"Las cumbres de la ruta \" << z << \" estan en:\";\r\n    for(int i = 1 ; i<sz(v)-1 ; i++){\r\n        if(v[i-1] < v[i] and v[i]>v[i+1]) cout << \" \" << i;\r\n    }\r\n    cout << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2028),
(2029,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    vector<float> v;\r\n    while(true){\r\n        float x;\r\n        cin >> x;\r\n        if(x==-1) break;\r\n        v.pb(x);\r\n    }\r\n    cout << \"Las cumbres de la ruta \" << z << \" estan en:\";\r\n    for(int i = 1 ; i<sz(v)-1 ; i++){\r\n        if(v[i-1] < v[i] and v[i]>v[i+1]) cout << \" \" << i;\r\n    }\r\n    cout << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2029),
(2030,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    int n1,n2,k;\r\n    cin >> n1 >> n2 >> k;\r\n    int Min = 2*n1;\r\n    int Max = 2*n2;\r\n    if(Max<k){\r\n        cout << \"SI\" << ENDL;\r\n        return;\r\n    }\r\n    if(Min>=k){\r\n        cout << \"SI\" << ENDL;\r\n        return;\r\n    }\r\n    cout << \"NO\" << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2030),
(2031,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    while(true){\r\n        int n;\r\n        cin >> n;\r\n        if(n==0) break;\r\n        string s;\r\n        cin >> s;\r\n        string s_i = s;\r\n        reverse(all(s_i));\r\n        if(s_i==s) cout << \"Eureka! Es un palindromo genetico\" << ENDL;\r\n        else cout << \"Lo siento, no es un palindromo genetico\" << ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2031),
(2032,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    vector<pair<pair<int,int>,string>> v;\r\n    int i = 0;\r\n    while(true){\r\n        int n;\r\n        cin >> n;\r\n        if(n==0) break;\r\n        string s;\r\n        cin >> s;\r\n        v.pb({{n,i},s});\r\n        i++;\r\n    }\r\n    sort(all(v));\r\n    for(auto x : v){\r\n        cout << x.second << ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2032),
(2033,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vvi m;\r\n    for(int i = 0 ; i < n ; i++){\r\n        vi l;\r\n        for(int k = 0 ; k<n ; k++){\r\n            int x;\r\n            cin >> x;\r\n            l.pb(x);\r\n        }\r\n        m.pb(l);\r\n    }\r\n    for(int i = 0 ; i<n ; i++){\r\n        for(int k = 0 ; k<n ; k++){\r\n            if(m[i][k]!=m[k][i]){\r\n                cout << \"NO\" << ENDL;\r\n                return;\r\n            }\r\n        }\r\n    }\r\n    cout << \"SI\" << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2033),
(2034,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vector<char> v = {\'a\',\'e\',\'i\',\'o\',\'u\'};\r\n    float tv = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        cin >> s;\r\n        for(int c : s){\r\n            if(find(all(v),c)!=v.end()) tv++;\r\n        }\r\n    }\r\n    cout << setprecision(2) << fixed << tv / n << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2034),
