(2036,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vector<char> v = {\'a\',\'e\',\'i\',\'o\',\'u\'};\r\n    float tv = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        cin >> s;\r\n        for(char c : s){\r\n            if(find(all(v),c)!=v.end()) tv++;\r\n        }\r\n    }\r\n    cout << setprecision(2) << fixed << tv / n << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2036),
(2037,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    cin.ignore();\r\n    vector<char> v = {\'a\',\'e\',\'i\',\'o\',\'u\'};\r\n    float tv = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        for(char c : s){\r\n            if(find(all(v),c)!=v.end()) tv++;\r\n        }\r\n    }\r\n    cout << setprecision(2) << fixed << tv / n << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2037),
(2038,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    cin.ignore();\r\n    float tv = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        cin >> s;\r\n        for(char c : s){\r\n            if(c==\'a\' || c==\'e\' || c==\'i\' || c==\'o\' || c==\'u\') tv++;\r\n        }\r\n    }\r\n    cout << setprecision(2) << fixed << tv / n << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2038),
(2039,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    while(true){\r\n        vi w1;\r\n        int n,m;\r\n        cin >> n >> m;\r\n        if (n==0 && m==0) break;\r\n        int t = n*m;\r\n        for(int i = 0 ; i<t ; i++){\r\n            int x;\r\n            cin >> x;\r\n            w1.pb(x);\r\n        }\r\n        float c = 0;\r\n        for(int i = 0 ; i<t ; i++){\r\n            int x;\r\n            cin >> x;\r\n            if(x!=w1[i]) c++;\r\n        }\r\n        if(c/t>0.1) cout << \"La pintura no es original\" << ENDL;\r\n        else cout << \"La pintura es original\" <<ENDL;\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2039),
(2040,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    set<string> v;\r\n    string s;\r\n    while(cin >> s) v.insert(s);\r\n    for(string x : v) cout << x << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2040),
(2041,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    map<string,vector<float>> mp;\r\n    int n;\r\n    cin >> n;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        float x;\r\n        cin >> s >> x;\r\n        mp[s].pb(x);\r\n    }\r\n    for(auto edge : mp){\r\n        if(sz(edge.se)<3) cout << edge.fi << \" \" << \"p\" << ENDL;\r\n        else{\r\n            cout << edge.fi << \" \" << setprecision(2) << fixed << (edge.se[0]+edge.se[1]+edge.se[2])/3.0 << ENDL;\r\n        }\r\n    }\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2041),
(2042,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid solve(){\r\n    set<pair<int,int>> ana,beto;\r\n    int a,b;\r\n    cin >> a >> b;\r\n    for(int i = 0 ; i<a ; i++){\r\n        int x,y;\r\n        cin >> x >> y;\r\n        ana.insert({x,y});\r\n    }\r\n    int c = 0;\r\n    for(int i = 0 ; i<b ; i++){\r\n        int x,y;\r\n        cin >> x >> y;\r\n        beto.insert({x,y});\r\n    }\r\n    for(pi edge : ana){\r\n        if(beto.find(edge)!=beto.end()) c++;\r\n    }\r\n    cout << c << ENDL;\r\n}\r\n\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2042),
(2043,'numero_de_casos = int(input())\r\nmatriz = []\r\nfor _ in range (numero_de_casos):\r\n    lista = []\r\n    y = input()\r\n    a, b, c = y.split()\r\n    a = int(a)\r\n    b = int(b)\r\n    c = int(c)\r\n    lista.append(a)\r\n    lista.append(b)\r\n    lista.append(c)\r\n    matriz.append(lista)\r\nbandera = True\r\nfor i in range(len(matriz)):\r\n    for j in range(len(matriz)):\r\n        if matriz[i][j] != matriz[j][i]:\r\n            bandera= False\r\nif bandera:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',2043),
(2044,'N = int(input())\r\nT = int(input())\r\n\r\nanterior= int(input())\r\n\r\n#conteo de repeticiones \r\nalertas = 0\r\ndiferencias = 0\r\n\r\n#calculo de diferencias\r\nfor _ in range(N - 1):\r\n    act= int(input())\r\n    diferencia = act - anterior\r\n\r\n    if diferencia > T:\r\n        print(\"ALERTA\")\r\n        alertas += 1\r\n        diferencias += diferencia\r\n    else:\r\n        print(\"OK\")\r\n\r\n    anterior = act\r\n\r\n#calculo de promedio\r\nif alertas > 0:\r\n    promedio = diferencias / alertas\r\nelse:\r\n    promedio = 0.0\r\n\r\nprint(alertas)\r\nprint(f\"{promedio:.2f}\")',2044),
(2045,'N = int(input())\r\nT = int(input())\r\n\r\nanterior= int(input())\r\n\r\nalertas = 0\r\ndiferencias = 0\r\n\r\nfor _ in range(N - 1):\r\n    act= int(input())\r\n    diferencia = act - anterior\r\n\r\n    if diferencia > T:\r\n        print(\"ALERTA\")\r\n        alertas += 1\r\n        diferencias += diferencia\r\n    else:\r\n        print(\"OK\")\r\n        diferencias += diferencia\r\n\r\n    anterior = act\r\n\r\n# Cálculo del promedio\r\nif alertas > 0:\r\n    promedio = diferencias / alertas\r\nelse:\r\n    promedio = 0.0\r\n\r\nprint(alertas)\r\nprint(f\"{promedio:.2f}\")',2045),
