(2049,'x= input()\r\ny = input()\r\nz= input()\r\ndispo = set(x)\r\nobli = set(y)\r\nprohi = set(z)\r\n\r\nn = int(input())\r\npermitidas =[]\r\nfor _ in range(n):\r\n    palabra= input()\r\n    verificar = set(palabra)\r\n    if obli.issubset(verificar) and prohi.intersection(verificar)==set() and dispo.issuperset(verificar):\r\n        permitidas.append(palabra)\r\n\r\nfor _ in permitidas:\r\n    print(_)',2049),
