(2064,'diccionario = dict()\r\nwhile True:\r\n    x = input()\r\n    if x == \"Fin de los juegos\":\r\n        break\r\n    else:\r\n        alianza,puntaje = x.split()\r\n        puntaje = int(puntaje)\r\n        if alianza not in diccionario:\r\n            diccionario[alianza] = puntaje\r\n        else:\r\n            punt = diccionario[alianza]\r\n            punt = punt+puntaje\r\n            diccionario[alianza] = punt\r\ndiccionario_ordenado = dict(sorted(diccionario.items()))\r\nfor i in diccionario_ordenado:\r\n    c = diccionario_ordenado[i]\r\n    p = i\r\n    break\r\nlista = []\r\nfor j in diccionario_ordenado:\r\n    if c == diccionario_ordenado[j]:\r\n        lista.append(j)\r\n    else:\r\n        break\r\nlista.sort()\r\nfor k in lista:\r\n    print(f\"{k} es la alianza campeona con {diccionario[k]} puntos!\")',2064),
(2065,'diccionario = dict()\r\nwhile True:\r\n    x = input()\r\n    if x == \"Fin de los juegos\":\r\n        break\r\n    else:\r\n        *alianza_partes, puntaje = x.split()\r\n        alianza = \" \".join(alianza_partes)\r\n        puntaje = int(puntaje)\r\n        diccionario[alianza] = diccionario.get(alianza, 0) + puntaje\r\ndiccionario_ordenado = dict(sorted(diccionario.items()))\r\nprint(diccionario_ordenado)\r\nmax_puntaje = max(diccionario.values())\r\nlista = sorted([nombre for nombre, punt in diccionario.items() if punt == max_puntaje])\r\nfor k in lista:\r\n    print(f\"{k} es la alianza campeona con {diccionario[k]} puntos!\")',2065),
