(2067,'x = int(input())\r\ndiccionario = dict()\r\ndic = dict()\r\nlista = []\r\nlista_2 = []\r\nfor i in range(x):\r\n    nombre, nota = input().split()\r\n    nota = float(nota)\r\n    if nombre not in diccionario:\r\n        diccionario[nombre] = nota\r\n        dic[nombre] = 1\r\n        lista.append(nombre)\r\n    else:\r\n        diccionario[nombre] += nota\r\n        dic[nombre] +=1\r\n        lista.append(nombre)\r\nfor i in diccionario:\r\n    if lista.count(i) == 3:\r\n        p = diccionario[i]\r\n        q = p/3\r\n        lista_2.append(f\"{i} {q:.2f}\")\r\n    else:\r\n        lista_2.append(f\"{i} p\")\r\nlista_2.sort()\r\nfor i in lista_2:\r\n    print(i)',2067),
(2068,'x = int(input())\r\ndiccionario = dict()\r\ndic = dict()\r\nlista = []\r\nlista_2 = []\r\nfor i in range(x):\r\n    nombre, nota = input().split()\r\n    nota = float(nota)\r\n    if nombre not in diccionario:\r\n        diccionario[nombre] = nota\r\n        dic[nombre] = 1\r\n        lista.append(nombre)\r\n    else:\r\n        diccionario[nombre] += nota\r\n        dic[nombre] +=1\r\n        lista.append(nombre)\r\nfor i in diccionario:\r\n    if dic[i] == 3:\r\n        p = diccionario[i]\r\n        q = p/3\r\n        lista_2.append(f\"{i} {q:.2f}\")\r\n    else:\r\n        lista_2.append(f\"{i} p\")\r\nlista_2.sort()\r\nfor i in lista_2:\r\n    print(i)',2068),
(2069,'letras_disponibles = input()\r\nlista_letras_disponibles = list(letras_disponibles)\r\nletras_obligatorias = input()\r\nletras_obligatorias_lista = list(letras_obligatorias)\r\nletras_prohibidas = input()\r\nletras_prohibidas_lista = list(letras_prohibidas)\r\ncantidad_de_palabras = int(input())\r\nfor i in range(cantidad_de_palabras):\r\n    palabra_candidata = input()\r\n    lista_palabra_candidata = list(palabra_candidata)\r\n    bandera = True\r\n    for i in lista_palabra_candidata:\r\n        if i in letras_prohibidas_lista:\r\n            bandera = False\r\n            break\r\n        elif i not in lista_letras_disponibles:\r\n            bandera = False\r\n            break\r\n        else:\r\n            pass\r\n    for j in letras_prohibidas_lista:\r\n        if j in lista_palabra_candidata:\r\n            bandera = False\r\n            break\r\n        else:\r\n            pass\r\n    if bandera == True:\r\n        print(palabra_candidata)\r\n    else:\r\n        pass',2069),
