(2077,'x = int(input())\r\nfor i in range(x):\r\n    lista = []\r\n    num = int(input())\r\n    for j in range(10):\r\n        for k in range(10):\r\n            for m in range(10):\r\n                for l in range(10):\r\n                    p = j + k + m + l\r\n                    palabra = \"\"\r\n                    palabra += j\r\n                    palabra += k\r\n                    palabra += m\r\n                    palabra += l\r\n                    if num == p:\r\n                        lista.append(palabra)\r\n                    else:\r\n                        pass\r\n    for q in lista:\r\n        print(f\"{q} es una clave de la suerte que suma {num}\")',2077),
(2078,'x = int(input())\r\nfor i in range(x):\r\n    lista = []\r\n    num = int(input())\r\n    for j in range(10):\r\n        for k in range(10):\r\n            for m in range(10):\r\n                for l in range(10):\r\n                    p = j + k + m + l\r\n                    lista_2 = [str(j),str(k),str(m),str(l)]\r\n                    palabra = \"\".join(lista_2)\r\n                    if num == p:\r\n                        lista.append(palabra)\r\n                    else:\r\n                        pass\r\n    for q in lista:\r\n        print(f\"{q} es una clave de la suerte que suma {num}\")',2078),
(2079,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\nvoid primos(vector<bool>& visitados, int n){\r\n    visitados[0]=false;\r\n    visitados[1]=false;\r\n    for(int i = 2 ; i*i<=n ; i++){\r\n        if(visitados[i]){\r\n            for(int k = i*i ; k<=n ; k+=i) visitados[k]=false;\r\n        }\r\n    }\r\n}\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    vector<bool> visitados(n+1,true);\r\n    primos(visitados,n);\r\n    int s = 0;\r\n    for(int i : visitados) s+=i;\r\n    cout << s << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2079),
(2080,'# Leer dimensiones\r\nR,C = map(int,input().split())\r\n\r\n# Inicializar grilla vacía\r\ngrid = [[\'.\' for _ in range(C)] for _ in range(R)]\r\n\r\n# Leer espejos\r\nK = int(input())\r\nfor _ in range(K):\r\n    r,c,t = input().split()\r\n    r = int(r)-1 # coordenadas a 0...R-1\r\n    c = int(c)-1 # coordenadas a 0...C-1\r\n    grid[r][c] = t\r\n\r\n# Posición del emisor\r\nsr, sc = map(int,input().split())\r\nsr, sc = sr-1, sc-1\r\ngrid[sr][sc] = \'*\'\r\n\r\n# Dirección inicial\r\nd = input()\r\n\r\n# Mapas de dirección\r\n# U, D, L, R -> (dr, dc)\r\ndir_vec = {\r\n    \'U\': (-1, 0),\r\n    \'D\': (1, 0),\r\n    \'L\': (0, -1),\r\n    \'R\': (0, 1)\r\n}\r\n\r\n# Funciones de \"giro a la derecha\" y \"giro a la izquierda\"\r\nright_turn = {\r\n    \'U\': \'R\',\r\n    \'R\': \'D\',\r\n    \'D\': \'L\',\r\n    \'L\': \'U\'\r\n}\r\n\r\nleft_turn = {\r\n    \'U\': \'L\',\r\n    \'L\': \'D\',\r\n    \'D\': \'R\',\r\n    \'R\': \'U\'\r\n}\r\n\r\n# Estado inicial del láser (en la celda del emisor)\r\nr, c = sr, sc\r\ndirection = d\r\n\r\nwhile True:\r\n    # Mover un paso\r\n    dr, dc = dir_vec[direction]\r\n    r += dr\r\n    c += dc\r\n\r\n    # Verificar límites\r\n    if not (0 <= r < R and 0 <= c < C):\r\n        break  # El láser sale de la grilla\r\n\r\n    cell = grid[r][c]\r\n\r\n    # Primero, reflejar si es espejo\r\n    if cell == \'/\':\r\n        # \'/\' : vertical -> derecha, horizontal -> izquierda\r\n        if direction in (\'U\', \'D\'):  # vertical\r\n            direction = right_turn[direction]\r\n        else:  # horizontal\r\n            direction = left_turn[direction]\r\n        # La celda sigue siendo \'/\'\r\n        continue  # no se marca trayectoria sobre el espejo\r\n\r\n    elif cell == \'\\\\\':\r\n        # \'\\\' : vertical -> izquierda, horizontal -> derecha\r\n        if direction in (\'U\', \'D\'):  # vertical\r\n            direction = left_turn[direction]\r\n        else:  # horizontal\r\n            direction = right_turn[direction]\r\n        # La celda sigue siendo \'\\\'\r\n        continue  # no se marca trayectoria sobre el espejo\r\n\r\n    # Si no es espejo, marcamos trayectoria\r\n    # Nota: la celda del emisor \'*\' nunca se sobrescribe\r\n    if cell == \'.\':\r\n        # Celda vacía: marcamos según dirección\r\n        if direction in (\'L\', \'R\'):\r\n            grid[r][c] = \'-\'\r\n        else:  # \'U\' o \'D\'\r\n            grid[r][c] = \'|\'\r\n    elif cell == \'-\':\r\n        # Ya hay trayectoria horizontal\r\n        if direction in (\'U\', \'D\'):\r\n            grid[r][c] = \'+\'\r\n        # si viene horizontal, se deja igual\r\n    elif cell == \'|\':\r\n        # Ya hay trayectoria vertical\r\n        if direction in (\'L\', \'R\'):\r\n            grid[r][c] = \'+\'\r\n        # si viene vertical, se deja igual\r\n    elif cell == \'+\':\r\n        # Ya hay cruce, no cambia\r\n        pass\r\n    elif cell == \'*\':\r\n        # El emisor no se modifica, pero el láser puede \"pasar\" por ahí\r\n        # (no cambia el símbolo)\r\n        pass\r\n\r\n\r\n# Imprimir la grilla final\r\nfor row in grid:\r\n    print(\'\'.join(row))',2080),
(2081,'# Leer dimensiones\r\nR,C = map(int,input().split())\r\n\r\n# Inicializar grilla vacía\r\ngrid = [[\'.\' for _ in range(C)] for _ in range(R)]\r\n\r\n# Leer espejos\r\nK = int(input())\r\nfor _ in range(K):\r\n    r,c,t = input().split()\r\n    r = int(r)-1 # coordenadas a 0...R-1\r\n    c = int(c)-1 # coordenadas a 0...C-1\r\n    grid[r][c] = t\r\n\r\n# Posición del emisor\r\nsr, sc = map(int,input().split())\r\nsr, sc = sr-1, sc-1\r\ngrid[sr][sc] = \'*\'\r\n\r\n# Dirección inicial\r\nd = input()\r\n\r\n# Mapas de dirección\r\n# U, D, L, R -> (dr, dc)\r\ndir_vec = {\r\n    \'U\': (-1, 0),\r\n    \'D\': (1, 0),\r\n    \'L\': (0, -1),\r\n    \'R\': (0, 1)\r\n}\r\n\r\n# Funciones de \"giro a la derecha\" y \"giro a la izquierda\"\r\nright_turn = {\r\n    \'U\': \'R\',\r\n    \'R\': \'D\',\r\n    \'D\': \'L\',\r\n    \'L\': \'U\'\r\n}\r\n\r\nleft_turn = {\r\n    \'U\': \'L\',\r\n    \'L\': \'D\',\r\n    \'D\': \'R\',\r\n    \'R\': \'U\'\r\n}\r\n\r\n# Estado inicial del láser (en la celda del emisor)\r\nr, c = sr, sc\r\ndirection = d\r\n\r\nwhile True:\r\n    # Mover un paso\r\n    dr, dc = dir_vec[direction]\r\n    r += dr\r\n    c += dc\r\n\r\n    # Verificar límites\r\n    if not (0 <= r < R and 0 <= c < C):\r\n        break  # El láser sale de la grilla\r\n\r\n    cell = grid[r][c]\r\n\r\n    # Primero, reflejar si es espejo\r\n    if cell == \'/\':\r\n        # \'/\' : vertical -> derecha, horizontal -> izquierda\r\n        if direction in (\'U\', \'D\'):  # vertical\r\n            direction = right_turn[direction]\r\n        else:  # horizontal\r\n            direction = left_turn[direction]\r\n        # La celda sigue siendo \'/\'\r\n        continue  # no se marca trayectoria sobre el espejo\r\n\r\n    elif cell == \'\\\\\':\r\n        # \'\\\' : vertical -> izquierda, horizontal -> derecha\r\n        if direction in (\'U\', \'D\'):  # vertical\r\n            direction = left_turn[direction]\r\n        else:  # horizontal\r\n            direction = right_turn[direction]\r\n        # La celda sigue siendo \'\\\'\r\n        continue  # no se marca trayectoria sobre el espejo\r\n\r\n    \r\n\r\n\r\n# Imprimir la grilla final\r\nfor row in grid:\r\n    print(\'\'.join(row))',2081),
