(2111,'n = int(input())\r\n\r\nEs_valida = True\r\nlista = []\r\n\r\nfor _ in range(n):\r\n    cartas = input().split()\r\n    lista.append(cartas)        \r\n\r\nconjuntos = [set(carta) for carta in lista]\r\nn_cartas = len(conjuntos)\r\nfor i in range(n_cartas):\r\n    for j in range(i + 1, n_cartas):\r\n        inter = conjuntos[i].intersection(conjuntos[j])\r\n        if len(inter) != 1:\r\n            Es_valida = False\r\n            exit()\r\n        \r\nif Es_valida:\r\n    print(\"VALIDA\")\r\nelse:\r\n    print(\"NO VALIDA\")',2111),
(2112,'n = int(input())\r\n\r\nEs_valida = True\r\nlista = []\r\n\r\nfor _ in range(n):\r\n    cartas = input().split()\r\n    lista.append(cartas)        \r\n\r\nconjuntos = [set(carta) for carta in lista]\r\nn_cartas = len(conjuntos)\r\nfor i in range(n_cartas):\r\n    for j in range(i + 1, n_cartas):\r\n        inter = conjuntos[i].intersection(conjuntos[j])\r\n        if len(inter) != 1:\r\n            Es_valida = False\r\n            break\r\n    if not Es_valida:\r\n        break\r\n        \r\nif Es_valida:\r\n    print(\"VALIDA\")\r\nelse:\r\n    print(\"NO VALIDA\")',2112),
(2113,'N,M = map(int,input().split())\r\n \r\n\r\ngrid = [list(input()) for _ in range(N)]\r\n\r\n# Desplazamientos para los 4 vecinos ortogonales\r\ndirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]\r\n\r\nwhile True:\r\n    changed = False\r\n    new_grid = [row[:] for row in grid]\r\n    \r\n    for i in range(N):\r\n        for j in range(M):\r\n            cell = grid[i][j]\r\n\r\n            # Contar vecinos \'u\' y existencia de vecino \'*\'\r\n            count_u = 0\r\n            has_star_neighbor = False\r\n\r\n            for di, dj in dirs:\r\n                ni, nj = i + di, j + dj\r\n                if 0 <= ni < N and 0 <= nj < M:\r\n                    neighbor = grid[ni][nj]\r\n                    if neighbor == \'u\':\r\n                        count_u += 1\r\n                    if neighbor == \'*\':\r\n                        has_star_neighbor = True\r\n\r\n            new_cell = cell\r\n\r\n            if cell == \'*\':\r\n                new_cell = \'*\'\r\n            elif cell == \'.\':\r\n                # Regla 3: \'.\' -> \'U\' si tiene al menos dos vecinos \'u\'\r\n                if count_u >= 2:\r\n                    new_cell = \'U\'\r\n                else:\r\n                    new_cell = \'.\'\r\n            elif cell == \'u\':\r\n                # Regla 2: \'u\' -> \'.\' si no tiene al menos un vecino \'*\'\r\n                if not has_star_neighbor:\r\n                    new_cell = \'.\'\r\n                else:\r\n                    new_cell = \'u\'\r\n            elif cell == \'U\':\r\n                # Regla 4: \'U\' se mantiene si tiene al menos dos vecinos \'u\', de lo contrario \'.\'\r\n                if count_u >= 2:\r\n                    new_cell = \'U\'\r\n                else:\r\n                    new_cell = \'.\'\r\n\r\n            if new_cell != cell:\r\n                changed = True\r\n            new_grid[i][j] = new_cell\r\n\r\n    if not changed:\r\n        break\r\n\r\n    grid = new_grid\r\n\r\n# Imprimir grilla final\r\nfor row in grid:\r\n    print(\"\".join(row))',2113),
(2114,'## OMMMMM\r\n## f: filas\r\n## c: columnas\r\n## n: longitud de la palabra\r\n## dir: direccion (H o V)\r\n\r\ngrid = [[\'.\' for _ in range(12)] for _ in range(12)]\r\n\r\nn = int(input(\"\"))\r\n\r\nfor _ in range(n):\r\n    dir, f, c, palabra = input().split()\r\n    f = int(f)\r\n    c = int(c)\r\n    n = len(palabra)\r\n\r\n    insertar = True\r\n################################ Margenes ################################\r\n    if dir == \'H\':\r\n        if c + n > 12:\r\n            insertar = False\r\n    elif dir == \'V\':\r\n        if f + n > 12:\r\n            insertar = False\r\n    else:\r\n        insertar = False\r\n\r\n    if insertar and dir == \'H\':\r\n        for i in range(n):\r\n            celda = grid[f][c+i]\r\n            if celda != \'.\' and celda != palabra[i]:\r\n                insertar = False\r\n                break\r\n\r\n    if insertar and dir == \'V\':\r\n        for i in range(n):\r\n            celda = grid[f+i][c]\r\n            if celda != \'.\' and celda != palabra[i]:\r\n                insertar = False\r\n                break\r\n\r\n    if insertar:\r\n        if dir == \'H\':\r\n            for i in range(n):\r\n                grid[f][c+i] = palabra[i]\r\n\r\n        elif dir == \'V\':\r\n            for i in range(n):\r\n                grid[f+i][c] = palabra[i]\r\n\r\nfor fila in grid:\r\n    print(\'\'.join(fila))',2114),
(2115,'n = int(input().strip())\r\na = input().strip()\r\nb = input().strip()\r\nmensaje = input().strip()\r\nTabCod = str.maketrans(a, b)\r\nMenCod = mensaje.translate(TabCod)\r\nprint(MenCod)',2115),
(2116,'numero_de_cartas = int(input())\r\nbaraja = []\r\nfor _ in range (numero_de_cartas):\r\n    simbolos = set(input().split())\r\n    baraja.append(simbolos)\r\nbandera = False\r\nfor simbolos in range(len(baraja)):\r\n    if range(simbolos) != 6:\r\n        bandera = True\r\n        break\r\nfor i in range(len(baraja)):\r\n    for j in range(1, len(baraja)):\r\n        if range((i&j))!=1:\r\n            bandera= True\r\n            break\r\nif bandera: \r\n    print(\"NO VALIDA\")\r\nelse:\r\n    print(\"VALIDA\")',2116),
(2117,'numero_de_cartas = int(input())\r\nbaraja = []\r\nfor _ in range (numero_de_cartas):\r\n    simbolos = set(input().split())\r\n    baraja.append(simbolos)\r\nbandera = False\r\nfor simbolos in range(len(baraja)):\r\n    if range(simbolos) != 6:\r\n        bandera = True\r\n        break\r\nfor i in range(len(baraja)):\r\n    for j in range(1, len(baraja)):\r\n        if i != j:\r\n            if range((i&j))!=1:\r\n                bandera= True\r\n                break\r\nif bandera: \r\n    print(\"NO VALIDA\")\r\nelse:\r\n    print(\"VALIDA\")',2117),
(2118,'numero_de_cartas = int(input())\r\nbaraja = []\r\nfor _ in range (numero_de_cartas):\r\n    simbolos = set(input().split())\r\n    baraja.append(simbolos)\r\nbandera = False\r\nfor carta in range(len(baraja)):\r\n    if len(simbolos) != 6:\r\n        bandera = True\r\n        break\r\nfor i in range(len(baraja)):\r\n    for j in range(i+1, len(baraja)):\r\n        if i != j:\r\n            if len((baraja[i]&baraja[j]))!=1:\r\n                bandera= True\r\n                break\r\nif bandera: \r\n    print(\"NO VALIDA\")\r\nelse:\r\n    print(\"VALIDA\")',2118),
(2119,'N, M = map(int, input().split())\r\ny, x = map(int, input().split())\r\n\r\ngrid = [list(map(int, input().split())) for _ in range(N)]\r\n\r\ndir = [\r\n    (-1, -1),  # arriba izquierda\r\n    (-1, 0),   # arriba\r\n    (-1, 1),   # arriba derecha\r\n    (0, -1),   # izquierda\r\n    (0, 1),    # derecha\r\n    (1, -1),   # abajo izquierda\r\n    (1, 0),    # abajo\r\n    (1, 1)     # abajo derecha\r\n]\r\n\r\nwhile True:\r\n    actual = grid[y][x]\r\n    menor = actual\r\n    mejor = None\r\n\r\n    for dy, dx in dir:\r\n        ny = y + dy\r\n        nx = x + dx\r\n\r\n        if 0 <= ny < N and 0 <= nx < M:\r\n            if grid[ny][nx] < menor:\r\n                menor = grid[ny][nx]\r\n                mejor = (ny, nx)\r\n\r\n    if mejor is None:\r\n        break\r\n\r\n    y, x = mejor\r\n\r\nprint(y, x)',2119),
(2120,'N = int(input())\r\n\r\nfor ruta_num in range(1, N + 1):\r\n\r\n    alturas = []\r\n    while True:\r\n        valor = input().strip()\r\n        if valor == \"-1\":\r\n            break\r\n        alturas.append(float(valor))\r\n\r\n    indices_cumbres = []\r\n\r\n    for i in range(1, len(alturas) - 1):\r\n        if alturas[i-1] < alturas[i] and alturas[i] > alturas[i+1]:\r\n            indices_cumbres.append(i)\r\n\r\n    print(f\"Las cumbres de la ruta {ruta_num} están en:\", end=\"\")\r\n\r\n    if len(indices_cumbres) > 0:\r\n        print(\" \", end=\"\")\r\n        print(\" \".join(map(str, indices_cumbres)))\r\n    else:\r\n        print()',2120),
