(2125,'diccionario=dict()\r\nwhile True:\r\n    entrada=input()\r\n    if entrada==\"Fin de los juegos\":\r\n        break\r\n    alianza,puntos=entrada.split()\r\n    puntos=int(puntos)\r\n    if alianza not in diccionario:\r\n        diccionario.setdefault(alianza,puntos) \r\n    elif alianza in diccionario:\r\n        diccionario[alianza]+=puntos\r\nmaximo_puntaje=max(diccionario.values())\r\nganadadores=[]\r\nfor alianza,puntos in diccionario.items():\r\n    if maximo_puntaje==puntos:\r\n       ganadadores.append((alianza,puntos))\r\nganadadores.sort()\r\nfor alianza,puntos in ganadadores:\r\n     print(f\"{alianza} es la alianza campeona con {puntos} puntos!\")',2125),
(2126,'m, n = map(int, input().split())\r\n\r\n# Lectura de la matriz A (m x n)\r\nA = []\r\nfor _ in range(m):\r\n    fila = list(map(int, input().split()))\r\n    A.append(fila)\r\n\r\n# Lectura de dimensiones de la matriz B\r\nn2, p = map(int, input().split())\r\n\r\n# Lectura de la matriz B (n2 x p)\r\nB = []\r\nfor _ in range(n2):\r\n    fila = list(map(int, input().split()))\r\n    B.append(fila)\r\n\r\n# Verificar compatibilidad: columnas de A (n) = filas de B (n2)\r\nif n != n2:\r\n    print(\"DimensionError\")\r\nelse:\r\n    # Crear matriz resultado C de tamaño m x p inicializada en ceros\r\n    C = [[0] * p for _ in range(m)]\r\n\r\n    # Multiplicación de matrices\r\n    # C[i][j] = sum(A[i][k] * B[k][j] for k in range(n))\r\n    for i in range(m):\r\n        for k in range(n):\r\n            aik = A[i][k]\r\n            for j in range(p):\r\n                C[i][j] += aik * B[k][j]\r\n\r\n    # Imprimir la matriz resultado\r\n    for i in range(m):\r\n        print(\" \".join(str(x) for x in C[i]))',2126),
