(2128,'m, r, e = int (input().split())\r\nfor i in range (m):\r\n    a, b, c = input().split()\r\n    if r*c>e:\r\n        print (\"SI\")\r\nfor i in range (r):\r\n    x,y,k = input().split()',2128),
(2129,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    map<string,map<string,int>> mp;\r\n    int m,r,e;\r\n    cin >> m >> r >> e;\r\n    for(int i = 0 ; i<m ; i++){\r\n        string a,b;\r\n        int c;\r\n        cin >> a >> b >> c;\r\n        mp[a][b]=c;\r\n    }\r\n    cin.ignore();\r\n    string s;\r\n    while(getline(cin,s)){\r\n        int costo_ruta = 0;\r\n\r\n        if(s.empty()) continue;\r\n        stringstream ss(s);\r\n        vector<string> v;\r\n        string x;\r\n        while(ss >> x){\r\n            v.pb(x);\r\n        }\r\n        bool b = false;\r\n        for(int i = 1 ; i<sz(v) ; i++){\r\n            if(mp[v[i-1]][v[i]]==0){\r\n                b = true;\r\n                break;\r\n            }\r\n            costo_ruta+=mp[v[i-1]][v[i]];\r\n        }\r\n        if(b) cout << \"NO\" << ENDL;\r\n        else if(costo_ruta<=e) cout << \"SI\" << ENDL;\r\n        else cout << \"NO\" << ENDL;\r\n    }\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2129),
(2130,'#MATRIZ A\r\ndimensiones_matriz_A= input()\r\na, b = dimensiones_matriz_A.split()\r\na  = int(a)\r\nb = int(b)\r\nmatriz_A = []\r\nfor _  in range (a):\r\n    fila = []\r\n    valor_fila = input().split()\r\n    matriz_A.append(valor_fila)\r\n\r\n#MATRIZ B\r\ndimensiones_matriz_B= input()\r\nc, d = dimensiones_matriz_B.split()\r\nc  = int(c)\r\nd = int(d)\r\nmatriz_B = []\r\nfor _  in range (c):\r\n    filab = []\r\n    valor_filab = input().split()\r\n    matriz_B.append(valor_filab)\r\n\r\n# MULTIPLICACION\r\nbandera = True\r\nif b!=c:\r\n    bandera=False\r\n\r\nmatriz_C=[[\".\"for i in range(a)for j in range(d)]]\r\n\r\nif b==c:\r\n    for i in matriz_A:\r\n        suma = 0\r\n        for j in matriz_A:\r\n            parcial = (matriz_A[i][j])*(matriz_B[j][i])\r\n            suma = suma + parcial\r\n        matriz_C[i][j]=suma\r\nif bandera:\r\n    print(matriz_C)\r\nif bandera==False:\r\n    print(\"DimensionError\")',2130),
(2131,'m, r, e = int (input().split())\r\nfor i in range (m):\r\n    a, b, c = input().split()\r\n    if c*r<e:\r\n        print (\"SI\")\r\nfor i in range (r):\r\n    x,y,k = input().split()',2131),
(2132,'#MATRIZ A\r\ndimensiones_matriz_A= input()\r\na, b = dimensiones_matriz_A.split()\r\na  = int(a)\r\nb = int(b)\r\nmatriz_A = []\r\nfor _  in range (a):\r\n    fila = []\r\n    valor_fila = input().split()\r\n    matriz_A.append(valor_fila)\r\n\r\n#MATRIZ B\r\ndimensiones_matriz_B= input()\r\nc, d = dimensiones_matriz_B.split()\r\nc  = int(c)\r\nd = int(d)\r\nmatriz_B = []\r\nfor _  in range (c):\r\n    filab = []\r\n    valor_filab = input().split()\r\n    matriz_B.append(valor_filab)\r\n\r\n# MULTIPLICACION\r\nbandera = True\r\nif b!=c:\r\n    bandera=False\r\n\r\nmatriz_C=[[\".\"for i in range(a)for j in range(d)]]\r\n\r\nif b==c:\r\n    for i in range(len(matriz_A)):\r\n        suma = 0\r\n        for j in range(len(matriz_A)):\r\n            parcial = (matriz_A[i][j])*(matriz_B[j][i])\r\n            suma = suma + parcial\r\n        matriz_C[i][j]=suma\r\nif bandera:\r\n    print(matriz_C)\r\nif bandera==False:\r\n    print(\"DimensionError\")',2132),
(2133,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nvoid solve(int z){\r\n    int m1,n1;\r\n    cin >> m1 >> n1;\r\n    vvi w1;\r\n    for(int i = 0 ; i<m1 ; i++){\r\n        vi v(n1);\r\n        for(int k = 0 ; k<n1 ; k++){\r\n            cin >> v[k];\r\n        }\r\n        w1.pb(v);\r\n    }\r\n    int m2,n2;\r\n    cin >> m2 >> n2;\r\n    vvi w2;\r\n    for(int i = 0 ; i<m2 ; i++){\r\n        vi v(n2);\r\n        for(int k = 0 ; k<n2 ; k++){\r\n            cin >> v[k];\r\n        }\r\n        w2.pb(v);\r\n    }\r\n    if(n1!=m2){\r\n        cout << \"DimensionError\" << ENDL;\r\n        return;\r\n    }\r\n    // multiplicar\r\n    for(vi v : w1){\r\n        vi fila;\r\n        // añadir por columna\r\n        for(int x = 0 ; x<n2 ; x++){\r\n            int s = 0;\r\n            for(int i = 0 ; i<m2 ; i++){\r\n                s+=v[i]*w2[i][x];\r\n            }\r\n            fila.pb(s);\r\n        }\r\n        for(int i = 0 ; i<sz(fila)-1 ;i++) cout << fila[i] << \" \";\r\n        cout << fila[sz(fila)-1] << ENDL;\r\n    }\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2133),
(2134,'tamaño= input()\r\na,b = tamaño.split()\r\na = int(a)\r\nb = int(b)\r\nmatriz = [[\".\"for i in range(a)]for j in range(b)]\r\nespejos = int(input())\r\ncoordenada = input()\r\nn, m = coordenada.split()\r\nn = int(n)\r\nm = int(m)\r\nmatriz [n-1][m-1] = \"*\"\r\nfor _ in range(b-m):\r\n    matriz[n-1][m] = \"-\"\r\nprint(matriz)',2134),
(2135,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nvoid simulacion(vector<vector<char>>& v, int dr, int dc , int ri , int ci, int r, int c){\r\n    // verificación límites\r\n    if(ri+dr<0 or ri+dr >= r) return;\r\n    if(ci+dc<0 or ci+dc >= c) return;\r\n    ri=ri+dr;\r\n    ci=ci+dc;\r\n    //si es / o \\, solo cambiar la dirección, no hacer nada más\r\n    bool XD = false;\r\n    bool b = true;\r\n    for(int i = 0 ; i<1 ; i++){\r\n        if(v[ri][ci]==\'/\'){\r\n            //abajo\r\n            if(dr==-1 and b){\r\n                dr = 0;\r\n                dc = 1;\r\n                break;\r\n            }\r\n            //arriba\r\n            if(dr==1 and b){\r\n                dr = 0;\r\n                dc = -1;\r\n                break;\r\n            }\r\n            //derecha\r\n            if(dc==1 and b){\r\n                dr = -1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n            //izquierda\r\n            if(dc==-1 and b){\r\n                dr = 1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n            \r\n        }\r\n    }\r\n    for(int i = 0 ; i<1 ; i++){\r\n        if(v[ri][ci]==\'\\\\\'){\r\n            if(dr==-1 and b){\r\n                dr = 0;\r\n                dc = -1;\r\n                break;\r\n            }\r\n            //arriba\r\n            if(dr==1 and b){\r\n                dr = 0;\r\n                dc = 1;\r\n                break;\r\n            }\r\n            //derecha\r\n            if(dc==1 and b){\r\n                dr = 1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n            //izquierda\r\n            if(dc==-1 and b){\r\n                dr = -1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    // cambios de dirección ya hechos.\r\n    if(v[ri][ci]==\'|\' or v[ri][ci]==\'-\'){\r\n        v[ri][ci]=\'+\';\r\n    }\r\n    if(v[ri][ci]==\'.\'){\r\n        if(dr!=0)v[ri][ci]=\'|\';\r\n        else v[ri][ci]=\'-\';\r\n    }\r\n    simulacion(v,dr,dc,ri,ci,r,c);\r\n}\r\n\r\nvoid solve(int z){\r\n    int r,c;\r\n    cin >> r >> c;\r\n    vector<vector<char>> v;\r\n    for(int i = 0 ; i<r ; i++){\r\n        vector<char> row(c,\'.\');\r\n        v.pb(row);\r\n    }\r\n    // obstaculos\r\n    int o;\r\n    cin >> o;\r\n    for(int i = 0 ; i<o ; i++){\r\n        int x,y;\r\n        cin >> x >> y;\r\n        x--;\r\n        y--;\r\n        cin >> v[x][y];\r\n    }\r\n    //emisor\r\n    int ri,ci;\r\n    cin >> ri >> ci;\r\n    ri--;\r\n    ci--;\r\n    v[ri][ci]=\'*\';\r\n\r\n    char direccion;\r\n    cin >> direccion;\r\n    int dr,dc;\r\n    if(direccion = \'U\'){\r\n        dr = -1;\r\n        dc = 0;\r\n    }\r\n    if(direccion = \'D\'){\r\n        dr = 1;\r\n        dc = 0;\r\n    }\r\n    if(direccion = \'L\'){\r\n        dr = 0;\r\n        dc = -1;\r\n    }\r\n    if(direccion = \'R\'){\r\n        dr = 0;\r\n        dc = 1;\r\n    }\r\n    //Simulación\r\n    simulacion(v,dr,dc,ri,ci,r,c);\r\n    for(int i = 0 ; i<r ; i++){\r\n        for(int k = 0 ; k<c ; k++){\r\n            cout << v[i][k];\r\n        }\r\n        cout << ENDL;\r\n    }\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2135),
(2136,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n\r\nvoid simulacion(vector<vector<char>>& v, int dr, int dc , int ri , int ci, int r, int c){\r\n    // verificación límites\r\n    if(ri+dr<0 or ri+dr >= r) return;\r\n    if(ci+dc<0 or ci+dc >= c) return;\r\n    ri=ri+dr;\r\n    ci=ci+dc;\r\n    //si es / o \\, solo cambiar la dirección, no hacer nada más\r\n    bool b = true;\r\n    for(int i = 0 ; i<1 ; i++){\r\n        if(v[ri][ci]==\'/\'){\r\n            //abajo\r\n            if(dr==-1 and b){\r\n                dr = 0;\r\n                dc = 1;\r\n                break;\r\n            }\r\n            //arriba\r\n            if(dr==1 and b){\r\n                dr = 0;\r\n                dc = -1;\r\n                break;\r\n            }\r\n            //derecha\r\n            if(dc==1 and b){\r\n                dr = -1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n            //izquierda\r\n            if(dc==-1 and b){\r\n                dr = 1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n            \r\n        }\r\n    }\r\n    for(int i = 0 ; i<1 ; i++){\r\n        if(v[ri][ci]==\'\\\\\'){\r\n            if(dr==-1 and b){\r\n                dr = 0;\r\n                dc = -1;\r\n                break;\r\n            }\r\n            //arriba\r\n            if(dr==1 and b){\r\n                dr = 0;\r\n                dc = 1;\r\n                break;\r\n            }\r\n            //derecha\r\n            if(dc==1 and b){\r\n                dr = 1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n            //izquierda\r\n            if(dc==-1 and b){\r\n                dr = -1;\r\n                dc = 0;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    // cambios de dirección ya hechos.\r\n    if(v[ri][ci]==\'|\' or v[ri][ci]==\'-\'){\r\n        v[ri][ci]=\'+\';\r\n    }\r\n    if(v[ri][ci]==\'.\'){\r\n        if(dr!=0)v[ri][ci]=\'|\';\r\n        else v[ri][ci]=\'-\';\r\n    }\r\n    simulacion(v,dr,dc,ri,ci,r,c);\r\n}\r\n\r\nvoid solve(int z){\r\n    int r,c;\r\n    cin >> r >> c;\r\n    vector<vector<char>> v;\r\n    for(int i = 0 ; i<r ; i++){\r\n        vector<char> row(c,\'.\');\r\n        v.pb(row);\r\n    }\r\n    // obstaculos\r\n    int o;\r\n    cin >> o;\r\n    for(int i = 0 ; i<o ; i++){\r\n        int x,y;\r\n        cin >> x >> y;\r\n        x--;\r\n        y--;\r\n        cin >> v[x][y];\r\n    }\r\n    //emisor\r\n    int ri,ci;\r\n    cin >> ri >> ci;\r\n    ri--;\r\n    ci--;\r\n    v[ri][ci]=\'*\';\r\n\r\n    char direccion;\r\n    cin >> direccion;\r\n    int dr,dc;\r\n    if(direccion == \'U\'){\r\n        dr = -1;\r\n        dc = 0;\r\n    }\r\n    if(direccion == \'D\'){\r\n        dr = 1;\r\n        dc = 0;\r\n    }\r\n    if(direccion == \'L\'){\r\n        dr = 0;\r\n        dc = -1;\r\n    }\r\n    if(direccion == \'R\'){\r\n        dr = 0;\r\n        dc = 1;\r\n    }\r\n    //Simulación\r\n    simulacion(v,dr,dc,ri,ci,r,c);\r\n    for(int i = 0 ; i<r ; i++){\r\n        for(int k = 0 ; k<c ; k++){\r\n            cout << v[i][k];\r\n        }\r\n        cout << ENDL;\r\n    }\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2136),
(2137,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -- Main -- //\r\n\r\n// la idea es hacer una simulación, con una función\r\n// se crea una nueva grilla, a partir de la anterior con las reglas\r\n// si es * nunca cambia\r\n// si es . si tiene  al menos 2 vecinos u se cambia a U\r\n// si es u desaparece si no hay *\r\n// si es U desaparece si tiene menos de 2 vecinos u.\r\n\r\n//Esto se hace para todas las coordenadas de la grilla\r\n//Si ambas grillas son iguales, detener, de lo contrario, simular la nueva grilla\r\n// pongo borde? SI\r\nvoid simulacion(int n , int m , vector<vector<char>> v){\r\n    vector<vector<char>> nueva_grilla;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> fila;\r\n        for(int k = 0 ; k<m ; k++){\r\n            char x = \'.\';\r\n            fila.pb(x);\r\n        }\r\n        nueva_grilla.pb(fila);\r\n    }\r\n\r\n\r\n    // centro\r\n\r\n\r\n\r\n    for(int i = 1 ; i<n-1; i++){\r\n        for(int k = 1 ; k<m-1 ; k++){\r\n            if(v[i][k]==\'*\') nueva_grilla[i][k]=\'*\';\r\n            if(v[i][k]==\'.\'){\r\n                int c = 0;\r\n                if(v[i+1][k]==\'u\') c++;\r\n                if(v[i-1][k]==\'u\') c++;\r\n                if(v[i][k+1]==\'u\') c++;\r\n                if(v[i][k-1]==\'u\') c++;\r\n                if(c>=2) nueva_grilla[i][k]=\'U\';\r\n                else nueva_grilla[i][k]=\'.\';\r\n            }\r\n            if(v[i][k]==\'u\'){\r\n                int c = 0;\r\n                if(v[i+1][k]==\'*\') c++;\r\n                if(v[i-1][k]==\'*\') c++;\r\n                if(v[i][k+1]==\'*\') c++;\r\n                if(v[i][k-1]==\'*\') c++;\r\n                if(c==0) nueva_grilla[i][k]=\'.\';\r\n                else nueva_grilla[i][k]=\'u\';\r\n            }\r\n            if(v[i][k]==\'U\'){\r\n                int c = 0;\r\n                if(v[i+1][k]==\'u\') c++;\r\n                if(v[i-1][k]==\'u\') c++;\r\n                if(v[i][k+1]==\'u\') c++;\r\n                if(v[i][k-1]==\'u\') c++;\r\n                if(c<2) nueva_grilla[i][k]=\'.\';\r\n                else nueva_grilla[i][k]=\'U\';\r\n            }\r\n        }\r\n    }\r\n    //bordes\r\n    // izq\r\n    for(int i = 1 ; i<n-1 ; i++){\r\n        int k = 0;\r\n        if(v[i][k]==\'*\') nueva_grilla[i][k]=\'*\';\r\n        if(v[i][k]==\'.\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'u\') c++;\r\n            if(v[i-1][k]==\'u\') c++;\r\n            if(v[i][k+1]==\'u\') c++;\r\n            if(c>=2) nueva_grilla[i][k]=\'U\';\r\n            else nueva_grilla[i][k]=\'.\';\r\n        }\r\n        if(v[i][k]==\'u\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'*\') c++;\r\n            if(v[i-1][k]==\'*\') c++;\r\n            if(v[i][k+1]==\'*\') c++;\r\n            if(c==0) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'u\';\r\n        }\r\n        if(v[i][k]==\'U\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'u\') c++;\r\n            if(v[i-1][k]==\'u\') c++;\r\n            if(v[i][k+1]==\'u\') c++;\r\n            if(c<2) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'U\';\r\n        }\r\n    }\r\n\r\n    for(int i = 1 ; i<n-1 ; i++){\r\n        int k = m-1;\r\n        if(v[i][k]==\'*\') nueva_grilla[i][k]=\'*\';\r\n        if(v[i][k]==\'.\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'u\') c++;\r\n            if(v[i-1][k]==\'u\') c++;\r\n            if(v[i][k-1]==\'u\') c++;\r\n            if(c>=2) nueva_grilla[i][k]=\'U\';\r\n            else nueva_grilla[i][k]=\'.\';\r\n        }\r\n        if(v[i][k]==\'u\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'*\') c++;\r\n            if(v[i-1][k]==\'*\') c++;\r\n            if(v[i][k-1]==\'*\') c++;\r\n            if(c==0) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'u\';\r\n        }\r\n        if(v[i][k]==\'U\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'u\') c++;\r\n            if(v[i-1][k]==\'u\') c++;\r\n            if(v[i][k-1]==\'u\') c++;\r\n            if(c<2) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'U\';\r\n        }\r\n    }\r\n    for(int k = 1 ; k<m-1 ; k++){\r\n        int i = 0;\r\n        if(v[i][k]==\'*\') nueva_grilla[i][k]=\'*\';\r\n        if(v[i][k]==\'.\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'u\') c++;\r\n            if(v[i][k+1]==\'u\') c++;\r\n            if(v[i][k-1]==\'u\') c++;\r\n            if(c>=2) nueva_grilla[i][k]=\'U\';\r\n            else nueva_grilla[i][k]=\'.\';\r\n        }\r\n        if(v[i][k]==\'u\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'*\') c++;\r\n            if(v[i][k+1]==\'*\') c++;\r\n            if(v[i][k-1]==\'*\') c++;\r\n            if(c==0) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'u\';\r\n        }\r\n        if(v[i][k]==\'U\'){\r\n            int c = 0;\r\n            if(v[i+1][k]==\'u\') c++;\r\n            if(v[i][k+1]==\'u\') c++;\r\n            if(v[i][k-1]==\'u\') c++;\r\n            if(c<2) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'U\';\r\n        }\r\n    }\r\n\r\n    for(int k = 1 ; k<m-1 ; k++){\r\n        int i = n-1;\r\n        if(v[i][k]==\'*\') nueva_grilla[i][k]=\'*\';\r\n        if(v[i][k]==\'.\'){\r\n            int c = 0;\r\n            if(v[i-1][k]==\'u\') c++;\r\n            if(v[i][k+1]==\'u\') c++;\r\n            if(v[i][k-1]==\'u\') c++;\r\n            if(c>=2) nueva_grilla[i][k]=\'U\';\r\n            else nueva_grilla[i][k]=\'.\';\r\n        }\r\n        if(v[i][k]==\'u\'){\r\n            int c = 0;\r\n            if(v[i-1][k]==\'*\') c++;\r\n            if(v[i][k+1]==\'*\') c++;\r\n            if(v[i][k-1]==\'*\') c++;\r\n            if(c==0) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'u\';\r\n        }\r\n        if(v[i][k]==\'U\'){\r\n            int c = 0;\r\n            if(v[i-1][k]==\'u\') c++;\r\n            if(v[i][k+1]==\'u\') c++;\r\n            if(v[i][k-1]==\'u\') c++;\r\n            if(c<2) nueva_grilla[i][k]=\'.\';\r\n            else nueva_grilla[i][k]=\'U\';\r\n        }\r\n    }\r\n\r\n    if(nueva_grilla==v){\r\n        for(vector<char> x : v){\r\n            for(char i : x){\r\n                cout << i;\r\n            }\r\n            cout << ENDL;\r\n        }\r\n    } else {\r\n        simulacion(n,m,nueva_grilla);\r\n    }\r\n}\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> v;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> fila;\r\n        for(int k = 0 ; k<m ; k++){\r\n            char x;\r\n            cin >> x;\r\n            fila.pb(x);\r\n        }\r\n        v.pb(fila);\r\n    }\r\n\r\n\r\n    // la idea es hacer una simulación, con una función\r\n    // se crea una nueva grilla, a partir de la anterior con las reglas\r\n    // si es * nunca cambia\r\n    // si es . si tiene 2 vecinos se cambia a U\r\n    // si es u desaparece si no hay *\r\n    // si es U desaparece si tiene menos de 2 vecinos u.\r\n\r\n    //Esto se hace para todas las coordenadas de la grilla\r\n    //Si ambas grillas son iguales, detener, de lo contrario, simular la nueva grilla\r\n    \r\n    simulacion(n,m,v);\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2137),
(2138,'#MATRIZ A\r\ndimensiones_matriz_A= input()\r\na, b = dimensiones_matriz_A.split()\r\na  = int(a)\r\nb = int(b)\r\nmatriz_A = []\r\nfor _  in range (a):\r\n    fila = []\r\n    valor_fila = input().split()\r\n    matriz_A.append(valor_fila)\r\n\r\n#MATRIZ B\r\ndimensiones_matriz_B= input()\r\nc, d = dimensiones_matriz_B.split()\r\nc  = int(c)\r\nd = int(d)\r\nmatriz_B = []\r\nfor _  in range (c):\r\n    filab = []\r\n    valor_filab = input().split()\r\n    matriz_B.append(valor_filab)\r\n\r\n# MULTIPLICACION\r\nbandera = True\r\nif b!=c:\r\n    bandera=False\r\n\r\nmatriz_C=[[\".\"for i in range(a)for j in range(d)]]\r\n\r\nif b==c:\r\n    for _ in range(0, len(matriz_A)):\r\n        suma = 0\r\n        for j in range(_):\r\n            parcial = (matriz_A[_][j])*(matriz_B[j][_])\r\n            suma = suma + parcial\r\n        print(suma)\r\n        matriz_C[_][0]=suma\r\nif bandera:\r\n    print(matriz_C)\r\nif bandera==False:\r\n    print(\"DimensionError\")',2138),
