(2147,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nbool dentro_de_limites(int i,  int k, int n , int m){\r\n    return (i>=0 and i<n and k>=0 and k<m);\r\n}\r\n\r\nconst int dk[] = {-1,0,1,0};\r\nconst int di[] = {0,1,0,-1};\r\nvoid simulacion(int n , int m , vector<vector<char>>& v){\r\n    vector<vector<char>> nueva_grilla = v;\r\n    for(int i = 0 ; i<n ; i++){\r\n        for(int k = 0 ; k<m ; k++){\r\n            int vu = 0;\r\n            int vstr = 0;\r\n            for(int j = 0 ; j<4 ; j++){\r\n                int dkk = k + dk[j];\r\n                int dii = i + di[j];\r\n                if(dentro_de_limites(dii,dkk,n,m)){\r\n                    if(v[dii][dkk]==\'u\') vu++;\r\n                    if(v[dii][dkk]==\'*\') vstr++;\r\n                }\r\n            }\r\n            if(v[i][k]==\'.\'){\r\n                if(vu>=2) nueva_grilla[i][k]=\'U\';\r\n            } else if (v[i][k]==\'u\'){\r\n                if(vstr<1) nueva_grilla[i][k]=\'.\';\r\n            } else if(v[i][k]==\'U\'){\r\n                if(vu<2) nueva_grilla[i][k]=\'.\';\r\n            }\r\n        }\r\n    }\r\n    if(v==nueva_grilla){\r\n        for(int i = 0 ; i<n ; i++){\r\n            for(int k = 0 ; k<m ; k++){\r\n                cout << nueva_grilla[i][k];\r\n            }\r\n            cout << ENDL;\r\n        }\r\n    } else {\r\n        v = nueva_grilla;\r\n        simulacion(n,m,v);\r\n    }\r\n}\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> v;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> fila;\r\n        for(int k = 0 ; k<m ; k++){\r\n            char x;\r\n            cin >> x;\r\n            fila.pb(x);\r\n        }\r\n        v.pb(fila);\r\n    }\r\n    \r\n    simulacion(n,m,v);\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nbool dentro_de_limites(int i,  int k, int n , int m){\r\n    return (i>=0 and i<n and k>=0 and k<m);\r\n}\r\n\r\nconst int dk[] = {-1,0,1,0};\r\nconst int di[] = {0,1,0,-1};\r\nvoid simulacion(int n , int m , vector<vector<char>>& v){\r\n    vector<vector<char>> nueva_grilla = v;\r\n    for(int i = 0 ; i<n ; i++){\r\n        for(int k = 0 ; k<m ; k++){\r\n            int vu = 0;\r\n            int vstr = 0;\r\n            for(int j = 0 ; j<4 ; j++){\r\n                int dkk = k + dk[j];\r\n                int dii = i + di[j];\r\n                if(dentro_de_limites(dii,dkk,n,m)){\r\n                    if(v[dii][dkk]==\'u\') vu++;\r\n                    if(v[dii][dkk]==\'*\') vstr++;\r\n                }\r\n            }\r\n            if(v[i][k]==\'.\'){\r\n                if(vu>=2) nueva_grilla[i][k]=\'U\';\r\n            } else if (v[i][k]==\'u\'){\r\n                if(vstr<1) nueva_grilla[i][k]=\'.\';\r\n            } else if(v[i][k]==\'U\'){\r\n                if(vu<2) nueva_grilla[i][k]=\'.\';\r\n            }\r\n        }\r\n    }\r\n    if(v==nueva_grilla){\r\n        for(int i = 0 ; i<n ; i++){\r\n            for(int k = 0 ; k<m ; k++){\r\n                cout << nueva_grilla[i][k];\r\n            }\r\n            cout << ENDL;\r\n        }\r\n    } else {\r\n        v = nueva_grilla;\r\n        simulacion(n,m,v);\r\n    }\r\n}\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> v;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> fila;\r\n        for(int k = 0 ; k<m ; k++){\r\n            char x;\r\n            cin >> x;\r\n            fila.pb(x);\r\n        }\r\n        v.pb(fila);\r\n    }\r\n    \r\n    simulacion(n,m,v);\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    // cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2147),
