(2161,'cantidad_de_vitrales = int(input())\r\nfor i in range(cantidad_de_vitrales):\r\n    tamaño_del_vitral = int(input())\r\n    vitral = []\r\n    c = 0\r\n    for _ in range(tamaño_del_vitral):\r\n        linea_del_viitral = input().split()\r\n        vitral.append(linea_del_viitral)\r\n    ############################\r\n    #     SIMETRIA VETICAL     #\r\n    ############################\r\n    Vertical = True\r\n    for fila in vitral:\r\n        if fila == list(reversed(fila)):\r\n            pass\r\n        else:\r\n            Vertical = False\r\n            break\r\n    if Vertical:\r\n        print(f\"El vitral {i} tiene simetria vertical\")\r\n        c +=1\r\n    else:\r\n        pass\r\n    #############################\r\n    #    SIMETRIA HORIZONTAL    #\r\n    #############################\r\n    vitral_horizontal = vitral.copy()\r\n    vitral_horizontal = list(vitral_horizontal)\r\n    vitral_horizontal.reverse()\r\n    if vitral_horizontal == vitral:\r\n        print(f\"El vitral {i} tiene simetria horizontal\")\r\n        c +=1\r\n    else:\r\n        pass\r\n    ############################\r\n    #      SIMTERIA EN LA      #\r\n    #    DIAGONAL PRINCIPAL    #\r\n    ############################\r\n    DIAGONAL_PRINCIPAL = True\r\n    for l in range(tamaño_del_vitral):\r\n        for j in range(tamaño_del_vitral):\r\n            if vitral[l][j] == vitral[j][l]:\r\n                pass\r\n            else:\r\n                DIAGONAL_PRINCIPAL = False\r\n                break\r\n        if not DIAGONAL_PRINCIPAL:\r\n            break\r\n        else:\r\n            pass\r\n    if DIAGONAL_PRINCIPAL:\r\n        print(f\"El vitral {i} tiene simetria en la diagonal principal\")\r\n        c +=1\r\n    else:\r\n        pass\r\n    ############################\r\n    #      SIMTERIA EN LA      #\r\n    #    DIAGONAL SECUNDARIA   #\r\n    ############################\r\n    DIAGONAL_SECUNDARIA = True\r\n    vitral2 = []\r\n    for s in vitral:\r\n        s = list(s)\r\n        s.reverse()\r\n        vitral2.append(s)\r\n    for t in range(tamaño_del_vitral):\r\n        for p in range(tamaño_del_vitral):\r\n            if vitral2[t][p] == vitral2[p][t]:\r\n                pass\r\n            else:\r\n                DIAGONAL_SECUNDARIA = False\r\n                break\r\n        if not DIAGONAL_SECUNDARIA:\r\n            break\r\n        else:\r\n            pass\r\n    if DIAGONAL_SECUNDARIA:\r\n        print(f\"El vitral {i} tiene simetria en la diagonal secundaria\")\r\n        c +=1\r\n    else:\r\n        pass\r\n\r\n    if c == 0:\r\n        print(f\"El vitral {i} no tiene simetrias\")',2161),
(2162,'while True:\r\n    tamaño = input()\r\n    if tamaño == \"0 0\":\r\n        break\r\n    else:\r\n        pintura1 = []\r\n        pintura2 = []\r\n        fila,columna = map(int,tamaño.split())\r\n        diferencias = 0\r\n        for _ in range(fila):\r\n            columna1 = input().split()\r\n            pintura1.append(columna1)\r\n        for _ in range(fila):\r\n            columna2 = input().split()\r\n            pintura2.append(columna2)\r\n        for i in range(fila):\r\n            for k in range(columna):\r\n                if pintura1[i][k] != pintura2[i][k]:\r\n                    diferencias +=1\r\n                else:\r\n                    pass\r\n        pint = fila*columna\r\n        pint = float(pint)\r\n        diferencias = float(diferencias)\r\n        error = diferencias/pint\r\n        if error > 0.10:\r\n            print(\"La pintura no es original\")\r\n        else:\r\n            print(\"La pintura es original\")',2162),
