(2188,'while True:\r\n    tamaño = input()\r\n    if tamaño == \"0 0\":\r\n        break\r\n    else:\r\n        altura,ancho = map(int,tamaño.split())\r\n        pintura1 = []\r\n        for i in range(altura):\r\n            coso = map(int,input().split())\r\n            coso = list(coso)\r\n            pintura1.append(coso)\r\n        \r\n        pintura2 = []\r\n        for i in range(altura):\r\n            coso2 = map(int,input().split())\r\n            coso2 = list(coso2)\r\n            pintura2.append(coso2)\r\n        igualdad = 0\r\n        desigualdad = 0\r\n        pintura = 0\r\n        for i in range(altura):\r\n            for j in range(ancho):\r\n                if pintura1[i][j] == pintura2[i][j]:\r\n                    igualdad += 1\r\n                    pintura +=1\r\n                else:\r\n                    desigualdad += 1\r\n                    pintura += 1\r\n\r\n        porcentaje = pintura/10\r\n        if desigualdad>porcentaje:\r\n            print(\"La pintura no es original\")\r\n        else:\r\n            print(\"La pintura es original\")',2188),
