(2205,'tamaño, cantidad_de_cosas = map(int, input().split())\r\ntablero = []\r\nlista = []\r\nfor i in range(tamaño+2):\r\n    lista.append(\"w\")\r\ntablero.append(lista)\r\nfor i in range(tamaño):\r\n    coso = []\r\n    coso.append(\"w\")\r\n    for j in range(tamaño):\r\n        coso.append(\".\")\r\n\r\n    coso.append(\"w\")\r\n    tablero.append(coso)\r\nlista = []\r\nfor i in range(tamaño+2):\r\n    lista.append(\"w\")\r\ntablero.append(lista)\r\nfor i in range(cantidad_de_cosas):\r\n    a,b,c = input().split()\r\n    b = int(b)\r\n    c = int(c)\r\n    b += 1\r\n    c += 1\r\n    tablero[b][c] = a\r\nPX = 0\r\nPO = 0\r\ndef vecinos(k,l,z,x):\r\n    lsta = []\r\n    lsta.append(k[z][x+1])\r\n    lsta.append(k[z][x-1])\r\n    lsta.append(k[z+1][x])\r\n    lsta.append(k[z-1][x])\r\n    q = lsta.count(l)\r\n    return q\r\nfor i in range(1,tamaño+1):\r\n    for j in range(1,tamaño+1):\r\n        if tablero[i][j] == \".\":\r\n            if vecinos(tablero,\"X\",i,j) == 3:\r\n                PX += 2\r\n            elif vecinos(tablero,\"O\",i,j) == 3:\r\n                PO += 2\r\n        elif tablero[i][j] == \"X\":\r\n            if vecinos(tablero,\"O\",i,j) == 4:\r\n                PO += 1\r\n        else:\r\n            if vecinos(tablero,\"X\",i,j) == 4:\r\n                PX += 1\r\n\r\nif PX >PO:\r\n    print(PX,PO,\"X\")\r\nelif PO > PX:\r\n    print(PX,PO,\"O\")\r\nelse:\r\n    print(PX,PO,\"Empate\")',2205),
(2206,'# Lectura de datos\r\n\r\n\r\nN= int(input())\r\nbag={\'N\':0, \'R\':0, \'V\':0, \'I\':0, \'A\':0, \'D\':0, \'G\':0, \'C\':0, \'H\':0}\r\npuntos=[0]*N\r\n\r\nfor d in range(N):\r\n    duende_str=input()\r\n    for letra in duende_str:\r\n        if letra in bag.keys(): \r\n            bag[letra]+=1 \r\n        if (bag[\'N\']>=1 and bag[\'A\']>=2 and bag[\'V\']>=1 and bag[\'I\']>=1 and bag[\'D\']>=2):\r\n            puntos[d]+=1\r\n            bag[\'N\']-=1\r\n            bag[\'A\']-=2\r\n            bag[\'V\']-=1\r\n            bag[\'I\']-=1\r\n            bag[\'D\']-=2\r\n        if (bag[\'G\']>=1 and bag[\'R\']>=1 and bag[\'I\']>=1 and bag[\'N\']>=1 and bag[\'C\']>=1 and bag[\'H\']>=1):\r\n            puntos[d]-=1\r\n            bag[\'G\']-=1\r\n            bag[\'R\']-=1\r\n            bag[\'I\']-=1\r\n            bag[\'N\']-=1\r\n            bag[\'C\']-=2\r\n            bag[\'H\']-=1\r\n# print(puntos)  # --- IGNORE ---\r\nprint(f\"Gana el duende {max(range(len(puntos)), key=lambda x : puntos[x])}\")',2206),
(2207,'n = int(input().strip())\r\nW = 2 * n + 1\r\n\r\n# Estrella (3 líneas)\r\ns = r\"\\ | /\"\r\nleft = (W - len(s)) // 2\r\nprint(\" \" * left + s)\r\n\r\ns = r\"--- * ---\"\r\nleft = (W - len(s)) // 2\r\nprint(\" \" * left + s)\r\n\r\ns = \"/ | \\\\\"\r\nleft = (W - len(s)) // 2\r\nprint(\" \" * left + s)\r\n\r\n# Copa (n líneas)\r\nfor i in range(1, n + 1):\r\n    s = \"/\" + (\"*\" * (2 * i - 1)) + \"\\\\\"\r\n    left = (W - len(s)) // 2\r\n    print(\" \" * left + s)\r\n\r\n# Tronco (2 líneas)\r\ns = \"|||||\"\r\nleft = (W - len(s)) // 2\r\nprint(\" \" * left + s)\r\nprint(\" \" * left + s)',2207),
(2208,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    for(int i = 0 ; i<n-4 ; i++) cout << \" \";\r\n    cout << \"  \\\\ | /\" << ENDL;\r\n    for(int i = 0 ; i<n-4 ; i++) cout << \" \";\r\n    cout << \"--- * ---\" << ENDL;\r\n    for(int i = 0 ; i<n-4 ; i++) cout << \" \";\r\n    cout << \"  / | \\\\\" << ENDL;\r\n    if(n>=4){\r\n        for(int i = 1 ; i<=n ; i++){\r\n            int cant_esp = n-i;\r\n            for(int j = 0; j<cant_esp ; j++) cout << \" \";\r\n            cout << \"/\";\r\n            int cant_s = 2*i-1;\r\n            for(int j = 0; j<cant_s ;j++) cout << \"*\";\r\n            cout << \"\\\\\" << ENDL;\r\n        }\r\n        for(int k = 0 ; k<2 ; k++){\r\n            for(int i = 1 ; i<=n-2 ; i++) cout << \" \";\r\n            cout << \"|||||\" << ENDL;\r\n        }\r\n        return;\r\n    }\r\n    int k = 3;\r\n    for(int i = 1 ; i<=n ; i++){\r\n        for(int j = 0 ; j<k ; j++) cout << \" \";\r\n        int cant_esp = n-i;\r\n        cout << \"/\";\r\n        int cant_s = 2*i-1;\r\n        for(int j = 0; j<cant_s ;j++) cout << \"*\";\r\n        cout << \"\\\\\" << ENDL;\r\n        k--;\r\n    }\r\n    for(int k = 0 ; k<2 ; k++){\r\n        cout << \"  |||||\" << ENDL;\r\n    }\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2208),
(2209,'tamaño = int(input())\r\nmatriz = []\r\nprimera_fila = []\r\nfor i in range(tamaño-2):\r\n    primera_fila.append(\" \")\r\nprimera_fila.append(\"\\\\\")\r\nprimera_fila.append(\" \")\r\nprimera_fila.append(\"|\")\r\nprimera_fila.append(\" \")\r\nprimera_fila.append(\"/\")\r\nfor i in range(tamaño-2):\r\n    primera_fila.append(\" \")\r\nprint(\"\".join(primera_fila))\r\nsegunda_fila = []\r\nfor i in range(tamaño-4):\r\n    segunda_fila.append(\" \")\r\nsegunda_fila.append(\"-\")\r\nsegunda_fila.append(\"-\")\r\nsegunda_fila.append(\"-\")\r\nsegunda_fila.append(\" \")\r\nsegunda_fila.append(\"*\")\r\nsegunda_fila.append(\" \")\r\nsegunda_fila.append(\"-\")\r\nsegunda_fila.append(\"-\")\r\nsegunda_fila.append(\"-\")\r\nfor i in range(tamaño-4):\r\n    segunda_fila.append(\" \")\r\nprint(\"\".join(segunda_fila))\r\ntercera_fila = []\r\nfor i in range(tamaño-2):\r\n    tercera_fila.append(\" \")\r\ntercera_fila.append(\"/\")\r\ntercera_fila.append(\" \")\r\ntercera_fila.append(\"|\")\r\ntercera_fila.append(\" \")\r\ntercera_fila.append(\"\\\\\")\r\nfor i in range(tamaño-2):\r\n    tercera_fila.append(\" \")\r\nprint(\"\".join(tercera_fila))\r\nfor i in range(tamaño):\r\n    lista = []\r\n    for j in range(tamaño-i-1):\r\n        lista.append(\" \")\r\n    lista.append(\"/\")\r\n    for j in range(i+1):\r\n        lista.append(\"*\")\r\n    if i == 0:\r\n        lista.append(\"\\\\\")\r\n        for j in range(tamaño-i-1):\r\n            lista.append(\" \")\r\n    else:\r\n        for j in range(i):\r\n            lista.append(\"*\")\r\n        lista.append(\"\\\\\")\r\n        for j in range(tamaño-i-1):\r\n            lista.append(\" \")\r\n    matriz.append(lista)\r\nfor i in matriz:\r\n    print(\"\".join(i))\r\ntronco = []\r\nfor i in range(tamaño-2):\r\n    tronco.append(\" \")\r\ntronco.append(\"|\")\r\ntronco.append(\"|\")\r\ntronco.append(\"|\")\r\ntronco.append(\"|\")\r\ntronco.append(\"|\")\r\nfor i in range(tamaño-2):\r\n    tronco.append(\" \")\r\nprint(\"\".join(tronco))\r\nprint(\"\".join(tronco))\r\n#######################\r\n#   MERRY CHRISTMAS   #\r\n#######################',2209),
(2210,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(string s){\r\n    int p = 0 ;\r\n    map<char,int> frec;\r\n    for(char c : s) frec[c]++;\r\n    while(true){\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'A\']<2) break;\r\n        if(frec[\'V\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'D\']<2) break;\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(true){\r\n        if(frec[\'G\']<1) break;\r\n        if(frec[\'R\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'C\']<1) break;\r\n        if(frec[\'H\']<1) break;\r\n        frec[\'G\']=frec[\'G\']-1;\r\n        frec[\'R\']=frec[\'R\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'C\']=frec[\'C\']-1;\r\n        frec[\'H\']=frec[\'H\']-1;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    int p_max = -INF_INT;\r\n    int ganador;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        cin >> s;\r\n        int x = obtener_p(s);\r\n        if(x>p_max){\r\n            p_max = x;\r\n            ganador = i;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2210),
(2211,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(string s){\r\n    int p = 0 ;\r\n    map<char,int> frec;\r\n    for(char c : s) frec[c]++;\r\n    while(true){\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'A\']<2) break;\r\n        if(frec[\'V\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'D\']<2) break;\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(true){\r\n        if(frec[\'G\']<1) break;\r\n        if(frec[\'R\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'C\']<1) break;\r\n        if(frec[\'H\']<1) break;\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    string salto; \r\n    getline(cin, salto);\r\n    int p_max = -INF_INT;\r\n    int ganador;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        int x = obtener_p(s);\r\n        if(x>p_max){\r\n            p_max = x;\r\n            ganador = i;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2211),
(2212,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(string s){\r\n    int p = 0 ;\r\n    vector<int> frec(300, 0);\r\n    for (unsigned char c : s) {\r\n        frec[c]++;\r\n    }\r\n\r\n    while(true){\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'A\']<2) break;\r\n        if(frec[\'V\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'D\']<2) break;\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(true){\r\n        if(frec[\'G\']<1) break;\r\n        if(frec[\'R\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'C\']<1) break;\r\n        if(frec[\'H\']<1) break;\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        int x = obtener_p(s);\r\n        if(x>p_max){\r\n            p_max = x;\r\n            ganador = i;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2212),
