(2216,'from collections import Counter\r\nn = int(input())\r\np_max = -float(\'inf\')\r\nganador = 0\r\nfor i in range(n):\r\n    x = input()\r\n    p = 0\r\n    f= Counter(x)\r\n    while(True):\r\n        navidad = False\r\n        grinch = False\r\n        if(f[\'N\']>=1 and f[\'A\']>=2 and f[\'V\']>=1 and f[\'I\']>=1 and f[\'D\']>=2): navidad = True\r\n        if(f[\'G\']>=1 and f[\'R\']>=1 and f[\'I\']>=1 and f[\'N\']>=1 and f[\'C\']>=1 and f[\'H\']>=1): grinch = True\r\n        if(navidad and grinch):\r\n            p+=1\r\n            f[\'N\']-=1\r\n            f[\'A\']-=2\r\n            f[\'V\']-=1\r\n            f[\'I\']-=1\r\n            f[\'D\']-=2\r\n            if(f[\'G\']>=1 and f[\'R\']>=1 and f[\'I\']>=1 and f[\'N\']>=1 and f[\'C\']>=1 and f[\'H\']>=1):\r\n                f[\'G\']-=1\r\n                f[\'R\']-=1\r\n                f[\'I\']-=1\r\n                f[\'N\']-=1\r\n                f[\'C\']-=1\r\n                f[\'H\']-=1\r\n        else: break               \r\n    while(f[\'N\']>=1 and f[\'A\']>=2 and f[\'V\']>=1 and f[\'I\']>=1 and f[\'D\']>=2):\r\n        p+=1\r\n        f[\'N\']-=1\r\n        f[\'A\']-=2\r\n        f[\'V\']-=1\r\n        f[\'I\']-=1\r\n        f[\'D\']-=2\r\n    while(f[\'G\']>=1 and f[\'R\']>=1 and f[\'I\']>=1 and f[\'N\']>=1 and f[\'C\']>=1 and f[\'H\']>=1):\r\n        p-=1\r\n        f[\'G\']-=1\r\n        f[\'R\']-=1\r\n        f[\'I\']-=1\r\n        f[\'N\']-=1\r\n        f[\'C\']-=1\r\n        f[\'H\']-=1\r\n    if(p>p_max):\r\n        p_max = p\r\n        ganador = i\r\nprint(\"Gana el duende\",ganador)',2216),
