(2220,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(string s){\r\n    int p = 0 ;\r\n    vector<int> frec(300, 0);\r\n    for (unsigned char c : s) {\r\n        if(\'A\'<= c && c <= \'Z\'){\r\n            frec[c]++;\r\n        }\r\n    }\r\n\r\n    while(true){\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'A\']<2) break;\r\n        if(frec[\'V\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'D\']<2) break;\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(true){\r\n        if(frec[\'G\']<1) break;\r\n        if(frec[\'R\']<1) break;\r\n        if(frec[\'I\']<1) break;\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'C\']<1) break;\r\n        if(frec[\'H\']<1) break;\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        int x = obtener_p(s);\r\n        if(x>p_max){\r\n            p_max = x;\r\n            ganador = i;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2220),
