if(frec[\'I\']<1) break;\r\n        if(frec[\'N\']<1) break;\r\n        if(frec[\'C\']<1) break;\r\n        if(frec[\'H\']<1) break;\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        int x = obtener_p(s);\r\n        if(x>p_max){\r\n            p_max = x;\r\n            ganador = i;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}',2221),
