(2223,'tamaño = int(input())\r\ndiccionario = {}\r\nfor i in range(tamaño):\r\n    pam = list(set(map(int,input().split())))\r\n    pam.sort()\r\n    pam.reverse()\r\n    c = len(pam)\r\n    diccionario[c] = pam\r\ndiccionario_ordenado = dict(sorted(diccionario.items()))\r\nfor i in diccionario_ordenado:\r\n    a = diccionario_ordenado[i]\r\n    a = str(a)\r\n    a = a.replace(\"[\",\"\")\r\n    a = a.replace(\"]\",\"\")\r\n    q = a.count(\",\")\r\n    for j in range(q):\r\n        a = a.replace(\",\",\"\")\r\n    print(a)',2223),
