(2249,'def vecino(matriz,y,x,d):\r\n    lista = []\r\n    lista.append(matriz[y][x+1])\r\n    lista.append(matriz[y][x-1])\r\n    lista.append(matriz[y+1][x])\r\n    lista.append(matriz[y-1][x])\r\n    a = lista.count(d)\r\n    return a\r\naltura,ancho = map(int, input().split())\r\nurbanik = []\r\nlista = []\r\nfor i in range(ancho+2):\r\n    lista.append(\"w\")\r\nurbanik.append(lista)\r\nfor i in range(altura):\r\n    fila = input()\r\n    fila = \"w\"+fila+\"w\"\r\n    fila = list(fila)\r\n    urbanik.append(fila)\r\nurbanik.append(lista)\r\nurbanik_1 = [fila.copy() for fila in urbanik]\r\nwhile True:\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if urbanik[i+1][j+1] == \".\":\r\n                if vecino(urbanik,i+1,j+1,\"u\") >= 2:\r\n                    urbanik_1[i+1][j+1] = \"U\"\r\n                else:\r\n                    pass\r\n            elif urbanik[i+1][j+1] == \"u\":\r\n                if vecino(urbanik,i+1,j+1,\"*\") == 0:\r\n                    urbanik_1[i+1][j+1] = \".\"\r\n                else:\r\n                    pass\r\n            elif urbanik[i+1][j+1] == \"U\":\r\n                if vecino(urbanik,i+1,j+1,\"u\") >= 2:\r\n                    pass\r\n                else:\r\n                    urbanik_1[i+1][j+1] = \".\"\r\n            else:\r\n                pass\r\n    if urbanik == urbanik_1:\r\n        break\r\n    else:\r\n        urbanik = [fila.copy() for fila in urbanik_1]\r\nurbanik.pop()\r\nurbanik.pop(0)\r\nfor i in range(altura):\r\n    pam = []\r\n    for j in range(ancho+2):\r\n        if urbanik[i][j] == \"w\":\r\n            pass\r\n        else:\r\n            pam.append(urbanik[i][j])\r\n    print(\"\".join(pam))',2249),
(2250,'while True:\r\n    altura,ancho = map(int,input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n    else:\r\n        vitral = []\r\n        for i in range(altura):\r\n            fila = input()\r\n            fila = list(fila)\r\n            vitral.append(fila)\r\n        vitrol = []\r\n        for i in range(altura):\r\n            fila = input()\r\n            fila = list(fila)\r\n            vitrol.append(fila)\r\n        igualdad = 0\r\n        error = 0\r\n        for i in range(altura):\r\n            for j in range(ancho):\r\n                if vitral[i][j] == vitrol[i][j]:\r\n                    igualdad += 1\r\n                else:\r\n                    error += 1\r\n\r\n        tamaño = igualdad+error\r\n        ten = tamaño/10\r\n        if error <= ten:\r\n            print(\"La pintura es original\")\r\n        else:\r\n            print(\"La pintura no es original\")',2250),
(2251,'while True:\r\n    altura, ancho = map(int, input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n\r\n    vitral = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitral.append(fila)\r\n\r\n    vitrol = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitrol.append(fila)\r\n\r\n    error = 0\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if vitral[i][j] != vitrol[i][j]:\r\n                error += 1\r\n\r\n    tamaño = altura * ancho\r\n\r\n    if error <= tamaño * 0.1:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2251),
(2252,'while True:\r\n    altura, ancho = map(int, input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n    vitral = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitral.append(fila)\r\n    vitrol = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitrol.append(fila)\r\n    error = 0\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if vitral[i][j] != vitrol[i][j]:\r\n                error += 1\r\n    tamaño = altura * ancho\r\n    if error <= tamaño * 0.1:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2252),
(2253,'import math\r\nn,K,ri,ci,rj,cj = map(int,input().split())\r\na = abs(rj-ri)\r\nb = abs(cj-ci)\r\nif a >= b:\r\n    if a == 0 and b == 0:\r\n        cantidad = 0\r\n    elif a == 1 and b == 0:\r\n        cantidad = 3\r\n    elif a == 2 and b == 2:\r\n        cantidad = 2\r\n    else:\r\n        dx = math.ceil(a/2)\r\n        dy = math.ceil((a+b)/2)\r\n        maximo = max(a,b)\r\n        if (maximo % 2 == 0 and (a+b) % 2 == 0) or (maximo % 2 != 0 and (a+b) % 2 != 0):\r\n            cantidad = maximo\r\n        else:\r\n            cantidad = maximo + 1\r\nelse:\r\n    a,b = b,a\r\n    if a == 0 and b == 0:\r\n        cantidad = 0\r\n    elif a == 1 and b == 0:\r\n        cantidad = 3\r\n    elif a == 2 and b == 2:\r\n        cantidad = 2\r\n    else:\r\n        dx = math.ceil(a/2)\r\n        dy = math.ceil((a+b)/2)\r\n        maximo = max(a,b)\r\n        if (maximo % 2 == 0 and (a+b) % 2 == 0) or (maximo % 2 != 0 and (a+b) % 2 != 0):\r\n            cantidad = maximo + 1\r\n        else:\r\n            cantidad = maximo\r\n\r\nif K <= cantidad:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',2253),
