(2259,'import math\r\nn,K,ri,ci,rj,cj = map(int, input().split())\r\na = abs(rj - ri)\r\nb = abs(cj - ci)\r\na, b = max(a, b), min(a, b)\r\nif a == 0 and b == 0:\r\n    cantidad = 0\r\nelif a == 1 and b == 0:\r\n    cantidad = 3\r\nelif a == 2 and b == 2:\r\n    cantidad = 2\r\nelse:\r\n    k = max(math.ceil(a / 2), math.ceil((a + b) / 3))\r\n    if (k % 2) != ((a + b) % 2):\r\n        k += 1\r\n    cantidad = k\r\nif K <= cantidad:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',2259),
(2260,'import math\r\nn,K,ri,ci,rj,cj = map(int, input().split())\r\na = abs(rj - ri)\r\nb = abs(cj - ci)\r\na, b = max(a, b), min(a, b)\r\nif a == 0 and b == 0:\r\n    cantidad = 0\r\nelif a == 1 and b == 0:\r\n    cantidad = 3\r\nelif a == 2 and b == 2:\r\n    cantidad = 2\r\nelse:\r\n    k = max(math.ceil(a / 2), math.ceil((a + b) / 3))\r\n    if (k % 2) != ((a + b) % 2):\r\n        k += 1\r\n    cantidad = k\r\nif K >= cantidad:\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',2260),
