(2270,'N= int(input())\r\nbag={\'N\':0, \'R\':0, \'V\':0, \'I\':0, \'A\':0, \'D\':0, \'G\':0, \'C\':0, \'H\':0}\r\npuntos=[0]*N\r\n\r\nfor d in range(N):\r\n    duende_str=input()\r\n    for letra in duende_str:\r\n        if letra in bag.keys(): \r\n            bag[letra]+=1 \r\n        if (bag[\'N\']>=1 and bag[\'A\']>=2 and bag[\'V\']>=1 and bag[\'I\']>=1 and bag[\'D\']>=2):\r\n            puntos[d]+=1\r\n            bag[\'N\']-=1\r\n            bag[\'A\']-=2\r\n            bag[\'V\']-=1\r\n            bag[\'I\']-=1\r\n            bag[\'D\']-=2\r\n        if (bag[\'G\']>=1 and bag[\'R\']>=1 and bag[\'I\']>=1 and bag[\'N\']>=1 and bag[\'C\']>=1 and bag[\'H\']>=1):\r\n            puntos[d]-=1\r\n            bag[\'G\']-=1\r\n            bag[\'R\']-=1\r\n            bag[\'I\']-=1\r\n            bag[\'N\']-=1\r\n            bag[\'C\']-=1\r\n            bag[\'H\']-=1\r\n# print(puntos)  # --- IGNORE ---\r\nprint(f\"Gana el duende {max(range(len(puntos)), key=lambda x : puntos[x])}\")',2270),
(2271,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(vi&  frec, int p){\r\n    if(frec[\'N\']>=1 && frec[\'A\']>=2 && frec[\'V\']>=1 && frec[\'I\']>=1 && frec[\'D\']>=2){\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    if(frec[\'G\']>=1 && frec[\'R\']>=1 && frec[\'I\']>=1 && frec[\'N\']>=1 && frec[\'C\']>=1 && frec[\'H\']>=1){\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        vector<int> frec(300, 0);\r\n        int p = 0;\r\n        for (unsigned char c : s) {\r\n            if(\'A\'<= c && c <= \'Z\'){\r\n               frec[c]++;\r\n               p = obtener_p(frec,p);\r\n            }\r\n        }\r\n        if(p_max<p){\r\n            ganador = i;\r\n            p_max = p;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL; \r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2271),
(2272,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(vi&  frec, int p){\r\n    while(frec[\'N\']>=1 && frec[\'A\']>=2 && frec[\'V\']>=1 && frec[\'I\']>=1 && frec[\'D\']>=2){\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(frec[\'G\']>=1 && frec[\'R\']>=1 && frec[\'I\']>=1 && frec[\'N\']>=1 && frec[\'C\']>=1 && frec[\'H\']>=1){\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        vector<int> frec(300, 0);\r\n        int p = 0;\r\n        for (unsigned char c : s) {\r\n            if(\'A\'<= c && c <= \'Z\'){\r\n               frec[c]++;\r\n               p = obtener_p(frec,p);\r\n            }\r\n        }\r\n        if(p_max<p){\r\n            ganador = i;\r\n            p_max = p;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2272),
(2273,'n = int(input())\r\nganador = [0]\r\ndic = dict()\r\nfor i in range(n):\r\n    ASCII = input()\r\n    puntaje = 0\r\n    while True:\r\n        if \"N\" in ASCII and ASCII.count(\"A\") >= 2 and \"V\" in ASCII and \"I\" in ASCII and ASCII.count(\"D\") >= 2:\r\n            puntaje += 1\r\n            ASCII = ASCII.replace(\"N\",\"\",1)\r\n            ASCII = ASCII.replace(\"A\",\"\",2)\r\n            ASCII = ASCII.replace(\"V\",\"\",1)\r\n            ASCII = ASCII.replace(\"I\",\"\",1)\r\n            ASCII = ASCII.replace(\"D\",\"\",2)\r\n        else:\r\n            break\r\n    while True:\r\n        if \"G\" in ASCII and \"R\" in ASCII and \"I\" in ASCII and \"N\" in ASCII and \"C\" in ASCII and \"H\" in ASCII:\r\n            puntaje -= 1\r\n            ASCII = ASCII.replace(\"G\",\"\",1)\r\n            ASCII = ASCII.replace(\"R\",\"\",1)\r\n            ASCII = ASCII.replace(\"I\",\"\",1)\r\n            ASCII = ASCII.replace(\"N\",\"\",1)\r\n            ASCII = ASCII.replace(\"C\",\"\",1)\r\n            ASCII = ASCII.replace(\"H\",\"\",1)\r\n        else:\r\n            break\r\n    dic[i] = puntaje\r\n    if i == 0:\r\n        ganador[0] = i\r\n    else:\r\n        if dic[ganador[0]] > dic[i]:\r\n            pass\r\n        else:\r\n            ganador[0] = i\r\n\r\nprint(f\"Gana el duende {ganador[0]}\")',2273),
