(2284,'a,b = map(int,input().split())\r\ncon = []\r\ncop = []\r\ncriticos = []\r\nfor i in range(b):\r\n    c, d = map(int,input().split())\r\n    if (c in cop or c in con) and c not in criticos:\r\n        criticos.append(c)\r\n    else:\r\n        pass\r\n    if (d in cop or d in con) and d not in criticos:\r\n        criticos.append(d)\r\n    else:\r\n        pass\r\n    con.append(c)\r\n    cop.append(d)\r\ncriticos.sort()\r\nfor i in criticos:\r\n    print(f\"{i} es critico\")',2284),
(2285,'def puntos_articulacion_matriz(matriz):\r\n    n = len(matriz)\r\n    tiempo = 0\r\n    disc = [-1] * n\r\n    low = [-1] * n\r\n    parent = [-1] * n\r\n    visitado = [False] * n\r\n    articulaciones = set()\r\n    def dfs(u):\r\n        nonlocal tiempo\r\n        visitado[u] = True\r\n        disc[u] = low[u] = tiempo\r\n        tiempo += 1\r\n        hijos = 0\r\n        for v in range(n):\r\n            if matriz[u][v] == 1:\r\n                if not visitado[v]:\r\n                    parent[v] = u\r\n                    hijos += 1\r\n                    dfs(v)\r\n                    low[u] = min(low[u], low[v])\r\n                    if parent[u] != -1 and low[v] >= disc[u]:\r\n                        articulaciones.add(u)\r\n                    else:\r\n                        pass\r\n                    if parent[u] == -1 and hijos > 1:\r\n                        articulaciones.add(u)\r\n                    else:\r\n                        pass\r\n                elif v != parent[u]:\r\n                    low[u] = min(low[u], disc[v])\r\n    for i in range(n):\r\n        if not visitado[i]:\r\n            dfs(i)\r\n    return articulaciones\r\nequipos, conexiones = map(int, input().split())\r\nconex = dict()\r\nmatriz = [[0]*equipos for _ in range(equipos)]\r\nfor i in range(equipos):\r\n    lista = []\r\n    conex[i] = lista\r\nfor i in range(conexiones):\r\n    con1,con2 = map(int, input().split())\r\n    conex[con1] += [con2]\r\nfor i in conex:\r\n    for j in conex[i]:\r\n        matriz[i][j] = 1\r\ncoso = list(puntos_articulacion_matriz(matriz))\r\nfor i in coso:\r\n    print(f\"{i} es critico\")',2285),
(2286,'def puntos_articulacion_matriz(matriz):\r\n    n = len(matriz)\r\n    tiempo = 0\r\n    disc = [-1] * n\r\n    low = [-1] * n\r\n    parent = [-1] * n\r\n    visitado = [False] * n\r\n    articulaciones = set()\r\n    def dfs(u):\r\n        nonlocal tiempo\r\n        visitado[u] = True\r\n        disc[u] = low[u] = tiempo\r\n        tiempo += 1\r\n        hijos = 0\r\n        for v in range(n):\r\n            if matriz[u][v] == 1:\r\n                if not visitado[v]:\r\n                    parent[v] = u\r\n                    hijos += 1\r\n                    dfs(v)\r\n                    low[u] = min(low[u], low[v])\r\n                    if parent[u] != -1 and low[v] >= disc[u]:\r\n                        articulaciones.add(u)\r\n                    else:\r\n                        pass\r\n                    if parent[u] == -1 and hijos > 1:\r\n                        articulaciones.add(u)\r\n                    else:\r\n                        pass\r\n                elif v != parent[u]:\r\n                    low[u] = min(low[u], disc[v])\r\n    for i in range(n):\r\n        if not visitado[i]:\r\n            dfs(i)\r\n    return articulaciones\r\nequipos, conexiones = map(int, input().split())\r\nconex = dict()\r\nmatriz = [[0]*equipos for _ in range(equipos)]\r\nfor i in range(equipos):\r\n    lista = []\r\n    conex[i] = lista\r\nfor i in range(conexiones):\r\n    con1,con2 = map(int, input().split())\r\n    conex[con1] += [con2]\r\nfor i in conex:\r\n    for j in conex[i]:\r\n        matriz[i][j] = 1\r\ncoso = list(puntos_articulacion_matriz(matriz))\r\ncoso.sort()\r\nfor i in coso:\r\n    print(f\"{i} es critico\")',2286),
(2287,'matriz = [[\".\"]*12 for i in range(12)]\r\nmatriz2 = [[\".\"]*12 for i in range(12)]\r\na = int(input())\r\nfor i in range(a):\r\n    direccion, altura, ancho, palabra = input().split()\r\n    altura = int(altura)\r\n    ancho = int(ancho)\r\n    z = len(palabra)\r\n    if direccion == \"H\":\r\n        matriz2 = [fila.copy() for fila in matriz]\r\n        if z+ancho <= 12:\r\n            for i in range(z):\r\n                if matriz[altura][ancho+i] == palabra[i] or matriz[altura][ancho+i] == \".\":\r\n                    matriz[altura][ancho+i] = palabra[i]\r\n                else:\r\n                    matriz = [AM.copy() for AM in matriz2]\r\n                    break\r\n        else:\r\n            pass\r\n    else:\r\n        matriz2 = [fila.copy() for fila in matriz]\r\n        if z + altura <= 12:\r\n            z = len(palabra)\r\n            for i in range(z):\r\n                if matriz[altura+i][ancho] == palabra[i] or matriz[altura+i][ancho] == \".\":\r\n                    matriz[altura+i][ancho] = palabra[i]\r\n                else:\r\n                    matriz = [pom.copy() for pom in matriz2]\r\n                    break\r\n        else:\r\n            pass\r\nfor i in matriz:\r\n    print(\"\".join(i))',2287),
