(2295,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(vi&  frec, int p){\r\n    while(frec[\'N\']>=1 && frec[\'A\']>=2 && frec[\'V\']>=1 && frec[\'I\']>=1 && frec[\'D\']>=2){\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(frec[\'G\']>=1 && frec[\'R\']>=1 && frec[\'I\']>=1 && frec[\'N\']>=1 && frec[\'C\']>=1 && frec[\'H\']>=1){\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        vector<int> frec(300, 0);\r\n        int p = 0;\r\n        for (unsigned char c : s) {\r\n            if(\'A\'<= c && c <= \'Z\'){\r\n               frec[c]++;\r\n               p = obtener_p(frec,p);\r\n            }\r\n        }\r\n        if(p_max<=p){\r\n            ganador = i;\r\n            p_max = p;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2295),
(2296,'#include <stdio.h>\r\n\r\nint main() {\r\n    FILE *f = fopen(\"datos.txt\", \"r\");\r\n    char linea[100];\r\n    int a, b;\r\n\r\n    if (f == NULL) {\r\n        printf(\"Error al abrir el archivo\\n\");\r\n        return 1;\r\n    }\r\n\r\n    while (fgets(linea, sizeof(linea), f) != NULL) {\r\n        sscanf(linea, \"%d %d\", &a, &b);\r\n        printf(\"%d\\n\", a + b);\r\n    }\r\n\r\n    fclose(f);\r\n    return 0;\r\n}',2296),
(2297,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint obtener_p(vi&  frec, int p){\r\n    while(frec[\'N\']>=1 && frec[\'A\']>=2 && frec[\'V\']>=1 && frec[\'I\']>=1 && frec[\'D\']>=2){\r\n        frec[\'N\']=frec[\'N\']-1;\r\n        frec[\'A\']=frec[\'A\']-2;\r\n        frec[\'V\']=frec[\'V\']-1;\r\n        frec[\'I\']=frec[\'I\']-1;\r\n        frec[\'D\']=frec[\'D\']-2;\r\n        p++;\r\n    }\r\n    while(frec[\'G\']>=1 && frec[\'R\']>=1 && frec[\'I\']>=1 && frec[\'N\']>=1 && frec[\'C\']>=1 && frec[\'H\']>=1){\r\n        frec[\'G\']--;\r\n        frec[\'R\']--;\r\n        frec[\'I\']--;\r\n        frec[\'N\']--;\r\n        frec[\'C\']--;\r\n        frec[\'H\']--;\r\n        p--;\r\n    }\r\n    return p;\r\n}\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    cin.ignore(numeric_limits<streamsize>::max(), \'\\n\');\r\n    int p_max = -2000000000;\r\n    int ganador = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        string s;\r\n        getline(cin,s);\r\n        cout << s << ENDL;\r\n        vector<int> frec(300, 0);\r\n        int p = 0;\r\n        for (unsigned char c : s) {\r\n            if(\'A\'<= c && c <= \'Z\'){\r\n               frec[c]++;\r\n               p = obtener_p(frec,p);\r\n            }\r\n        }\r\n        if(p_max<=p){\r\n            ganador = i;\r\n            p_max = p;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2297),
(2298,'#include <stdio.h>\r\n\r\nint main() {\r\n    FILE *f = fopen(\"datos.txt\", \"r\");\r\n    char linea[100];\r\n    int a, b;\r\n\r\n    if (f == NULL) {\r\n        printf(\"\");\r\n        return 1;\r\n    }\r\n\r\n    while (fgets(linea, sizeof(linea), f) != NULL) {\r\n        sscanf(linea, \"%d %d\", &a, &b);\r\n        printf(\"%d\\n\", a + b);\r\n    }\r\n\r\n    fclose(f);\r\n    return 0;\r\n}',2298),
