(2301,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    string dum;\r\n    getline(cin,dum);\r\n    ll m_pje = -1e18;\r\n    int ganador = -1;\r\n    for(int i = 0 ; i<n ;i++){\r\n        string s;\r\n        getline(cin,s);\r\n        ll pje = 0;\r\n        int frec[26] = {0};\r\n        for(char c : s){\r\n            if(c>=\'A\' && c<=\'Z\'){\r\n                bool cambio = true;\r\n                frec[c-\'A\']++;\r\n                while(cambio){\r\n                    cambio = false;\r\n                    if( frec[\'N\'-\'A\']>=1 && frec[\'A\'-\'A\']>=2 && \r\n                        frec[\'V\'-\'A\']>=1 && frec[\'I\'-\'A\']>=1 && \r\n                        frec[\'D\'-\'A\']>=2   \r\n                    ){\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'A\'-\'A\']-=2;\r\n                        frec[\'V\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'D\'-\'A\']-=2;\r\n                        pje++;\r\n                        cambio = true;\r\n                    } else if ( frec[\'G\'-\'A\']>=1 && frec[\'R\'-\'A\']>=1 && \r\n                        frec[\'I\'-\'A\']>=1 && frec[\'N\'-\'A\']>=1 && \r\n                        frec[\'C\'-\'A\']>=1 && frec[\'H\'-\'A\']>=1\r\n                    ){\r\n                        frec[\'G\'-\'A\']--;\r\n                        frec[\'R\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'C\'-\'A\']--;\r\n                        frec[\'H\'-\'A\']--;\r\n                        pje--;\r\n                        cambio = true;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if(pje>m_pje){\r\n            ganador = i;\r\n            m_pje = pje;\r\n        }\r\n        cout << pje << ENDL;\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2301),
(2302,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    if(!(cin>>n)) return;\r\n    string dum;\r\n    getline(cin,dum);\r\n    ll m_pje = -1e18;\r\n    int ganador = -1;\r\n    for(int i = 0 ; i<n ;i++){\r\n        string s;\r\n        getline(cin,s);\r\n        ll pje = 0;\r\n        int frec[26] = {0};\r\n        for(char c : s){\r\n            if(c>=\'A\' && c<=\'Z\'){\r\n                bool cambio = true;\r\n                frec[c-\'A\']++;\r\n                while(cambio){\r\n                    cambio = false;\r\n                    if( frec[\'N\'-\'A\']>=1 && frec[\'A\'-\'A\']>=2 && \r\n                        frec[\'V\'-\'A\']>=1 && frec[\'I\'-\'A\']>=1 && \r\n                        frec[\'D\'-\'A\']>=2   \r\n                    ){\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'A\'-\'A\']-=2;\r\n                        frec[\'V\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'D\'-\'A\']-=2;\r\n                        pje++;\r\n                        cambio = true;\r\n                    } else if ( frec[\'G\'-\'A\']>=1 && frec[\'R\'-\'A\']>=1 && \r\n                        frec[\'I\'-\'A\']>=1 && frec[\'N\'-\'A\']>=1 && \r\n                        frec[\'C\'-\'A\']>=1 && frec[\'H\'-\'A\']>=1\r\n                    ){\r\n                        frec[\'G\'-\'A\']--;\r\n                        frec[\'R\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'C\'-\'A\']--;\r\n                        frec[\'H\'-\'A\']--;\r\n                        pje--;\r\n                        cambio = true;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if(pje>m_pje){\r\n            ganador = i;\r\n            m_pje = pje;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2302),
