r\n                        frec[\'G\'-\'A\']--;\r\n                        frec[\'R\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'C\'-\'A\']--;\r\n                        frec[\'H\'-\'A\']--;\r\n                        pje--;\r\n                        cambio = true;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if(pje>m_pje){\r\n            ganador = i;\r\n            m_pje = pje;\r\n        }\r\n        cout << pje << ENDL;\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2303),
