       frec[\'I\'-\'A\']--;\r\n                frec[\'N\'-\'A\']--;\r\n                frec[\'C\'-\'A\']--;\r\n                frec[\'H\'-\'A\']--;\r\n                pje--;\r\n                cambio = true;\r\n            }\r\n        }\r\n        if(pje>m_pje){\r\n            ganador = i;\r\n            m_pje = pje;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2306),
(2307,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    string dum;\r\n    getline(cin,dum);\r\n    ll m_pje = -1e18;\r\n    int ganador = -1;\r\n    for(int i = 0 ; i<n ;i++){\r\n        string s;\r\n        if(!(getline(cin,s))) s = \"\";\r\n        ll pje = 0;\r\n        int frec[26] = {0};\r\n        for(char c : s){\r\n            if(c>=\'A\' && c<=\'Z\'){\r\n                bool cambio = true;\r\n                frec[c-\'A\']++;\r\n                while(cambio){\r\n                    cambio = false;\r\n                    if( frec[\'N\'-\'A\']>=1 && frec[\'A\'-\'A\']>=2 && \r\n                        frec[\'V\'-\'A\']>=1 && frec[\'I\'-\'A\']>=1 && \r\n                        frec[\'D\'-\'A\']>=2   \r\n                    ){\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'A\'-\'A\']-=2;\r\n                        frec[\'V\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'D\'-\'A\']-=2;\r\n                        pje++;\r\n                        cambio = true;\r\n                    } else if ( frec[\'G\'-\'A\']>=1 && frec[\'R\'-\'A\']>=1 && \r\n                        frec[\'I\'-\'A\']>=1 && frec[\'N\'-\'A\']>=1 && \r\n                        frec[\'C\'-\'A\']>=1 && frec[\'H\'-\'A\']>=1\r\n                    ){\r\n                        frec[\'G\'-\'A\']--;\r\n                        frec[\'R\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'C\'-\'A\']--;\r\n                        frec[\'H\'-\'A\']--;\r\n                        pje--;\r\n                        cambio = true;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if(pje>m_pje){\r\n            ganador = i;\r\n            m_pje = pje;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2307),
(2308,'import sys\r\n\r\ndef solve(z: int):\r\n    data = sys.stdin\r\n\r\n    line = data.readline()\r\n    if not line:\r\n        return\r\n    n = int(line.strip())\r\n\r\n    m_pje = -10**18\r\n    ganador = -1\r\n\r\n    for i in range(n):\r\n        s = data.readline()\r\n        if s == \"\":\r\n            s = \"\"\r\n        else:\r\n            s = s.rstrip(\"\\n\")\r\n\r\n        pje = 0\r\n        frec = [0] * 26  # frecuencias A..Z\r\n\r\n        for c in s:\r\n            if \'A\' <= c <= \'Z\':\r\n                frec[ord(c) - ord(\'A\')] += 1\r\n\r\n                cambio = True\r\n                while cambio:\r\n                    cambio = False\r\n\r\n                    # Si se puede formar: NAVIDAD  (N A A V I D D)\r\n                    if (frec[ord(\'N\') - 65] >= 1 and frec[ord(\'A\') - 65] >= 2 and\r\n                        frec[ord(\'V\') - 65] >= 1 and frec[ord(\'I\') - 65] >= 1 and\r\n                        frec[ord(\'D\') - 65] >= 2):\r\n                        frec[ord(\'N\') - 65] -= 1\r\n                        frec[ord(\'A\') - 65] -= 2\r\n                        frec[ord(\'V\') - 65] -= 1\r\n                        frec[ord(\'I\') - 65] -= 1\r\n                        frec[ord(\'D\') - 65] -= 2\r\n                        pje += 1\r\n                        cambio = True\r\n\r\n                    # Si no, si se puede formar: GRINCH (G R I N C H)\r\n                    elif (frec[ord(\'G\') - 65] >= 1 and frec[ord(\'R\') - 65] >= 1 and\r\n                          frec[ord(\'I\') - 65] >= 1 and frec[ord(\'N\') - 65] >= 1 and\r\n                          frec[ord(\'C\') - 65] >= 1 and frec[ord(\'H\') - 65] >= 1):\r\n                        frec[ord(\'G\') - 65] -= 1\r\n                        frec[ord(\'R\') - 65] -= 1\r\n                        frec[ord(\'I\') - 65] -= 1\r\n                        frec[ord(\'N\') - 65] -= 1\r\n                        frec[ord(\'C\') - 65] -= 1\r\n                        frec[ord(\'H\') - 65] -= 1\r\n                        pje -= 1\r\n                        cambio = True\r\n\r\n        if pje > m_pje:\r\n            ganador = i\r\n            m_pje = pje\r\n\r\n    sys.stdout.write(f\"Gana el duende {ganador}\\n\")\r\n\r\n\r\ndef main():\r\n    solve(1)\r\n\r\nif __name__ == \"__main__\":\r\n    main()',2308),
(2309,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    string dum;\r\n    getline(cin,dum);\r\n    ll m_pje = -1e18;\r\n    int ganador = -1;\r\n    for(int i = 0 ; i<n ;i++){\r\n        string s;\r\n        if(!(getline(cin,s))) s = \"\";\r\n        ll pje = 0;\r\n        int frec[26] = {0};\r\n        for(char c : s){\r\n            if(c>=\'A\' && c<=\'Z\'){\r\n                bool cambio = true;\r\n                frec[c-\'A\']++;\r\n                while(cambio){\r\n                    cambio = false;\r\n                    if( frec[\'N\'-\'A\']>=1 && frec[\'A\'-\'A\']>=2 && \r\n                        frec[\'V\'-\'A\']>=1 && frec[\'I\'-\'A\']>=1 && \r\n                        frec[\'D\'-\'A\']>=2   \r\n                    ){\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'A\'-\'A\']-=2;\r\n                        frec[\'V\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'D\'-\'A\']-=2;\r\n                        pje++;\r\n                        cambio = true;\r\n                    } \r\n                    if ( frec[\'G\'-\'A\']>=1 && frec[\'R\'-\'A\']>=1 && \r\n                        frec[\'I\'-\'A\']>=1 && frec[\'N\'-\'A\']>=1 && \r\n                        frec[\'C\'-\'A\']>=1 && frec[\'H\'-\'A\']>=1\r\n                    ){\r\n                        frec[\'G\'-\'A\']--;\r\n                        frec[\'R\'-\'A\']--;\r\n                        frec[\'I\'-\'A\']--;\r\n                        frec[\'N\'-\'A\']--;\r\n                        frec[\'C\'-\'A\']--;\r\n                        frec[\'H\'-\'A\']--;\r\n                        pje--;\r\n                        cambio = true;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if(pje>m_pje){\r\n            ganador = i;\r\n            m_pje = pje;\r\n        }\r\n    }\r\n    cout << \"Gana el duende \" << ganador << ENDL;\r\n}\r\n\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        freopen(\"entrada.txt\", \"r\", stdin);\r\n        freopen(\"salida.txt\", \"w\", stdout);\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    return 0;\r\n}',2309),
(2310,'#include <stdio.h>\r\nint main(){\r\n    int a;\r\n    scanf(\"%d\", &a);\r\n    if (a > 100){\r\n        printf(\"El agua estara en estado gaseoso\");\r\n    }\r\n    else if (a < 0){\r\n        printf(\"El agua estara en estado solido\");\r\n    }\r\n    else {\r\n        printf(\"El agua estara en estado liquido\");\r\n    }\r\n    return 0;\r\n}',2310),
(2311,'#include <stdio.h>\r\nint main(){\r\n    int año,casos;\r\n    scanf(\"%d\", &casos);\r\n    for (int i=0; i < casos; i++){\r\n        scanf(\"%d\", &año);\r\n        if ( año % 4 == 0 ){\r\n            if ( año % 100 == 0){\r\n                if ( año %  400 == 0){\r\n                    printf(\"BISIESTO\\n\");\r\n                }\r\n                else {\r\n                    printf(\"NO BISIESTO\\n\");\r\n                }\r\n            }\r\n            else {\r\n                printf(\"BISIESTO\\n\");\r\n            }\r\n        }\r\n        else {\r\n            printf(\"NO BISIESTO\\n\");\r\n        }\r\n    }\r\n    return 0;\r\n}',2311),
(2312,'#include <stdio.h>\r\nint main(){\r\n    int a, b, c;\r\n    scanf(\"%d\", &c);\r\n    for (int i=0;i<3;i++){\r\n        scanf(\"%d %d\", &a, &b);\r\n        printf(\"%d\\n\", a+b);\r\n    }\r\n    return 0;\r\n}',2312),
(2313,'#include <stdio.h>\r\nint main(){\r\n    int a, b, c;\r\n    scanf(\"%d\", &c);\r\n    for (int i=0;i<c;i++){\r\n        scanf(\"%d %d\", &a, &b);\r\n        printf(\"%d\\n\", a+b);\r\n    }\r\n    return 0;\r\n}',2313),
(2314,'#include <stdio.h>\r\nint main(){\r\n    int casos, colaz;\r\n    scanf(\"%d\",&casos);\r\n    for (int i=0;i<casos;i++){\r\n        scanf(\"%d\", &colaz);\r\n        printf(\"# Collatz para n = \");\r\n        printf(\"%d\\n\",colaz);\r\n        printf(\"%d\\n\",colaz);\r\n        while (colaz != 1){\r\n            if (colaz % 2 == 0){\r\n                colaz = colaz/2;\r\n                printf(\"%d\\n\",colaz);\r\n            }\r\n            else {\r\n                colaz = (colaz*3)+1;\r\n                printf(\"%d\\n\",colaz);\r\n            }\r\n        }\r\n    }\r\n    return 0;\r\n}',2314),
(2315,'casos = int(input())\r\nlista = []\r\ndesface = int(input())\r\nfor i in range(casos):\r\n    caso = int(input())\r\n    lista.append(caso)\r\nerrores = 0\r\nsumadedesfaces = 0\r\nfor i in range(len(lista)-1):\r\n    c = lista[i] - lista[i+1]\r\n    if c > 0 and c > desface:\r\n        errores +=1\r\n        sumadedesfaces += c\r\n        print(\"ALERTA\")\r\n    elif c < 0 and c*(-1) > desface:\r\n        errores += 1\r\n        sumadedesfaces -= c\r\n        print(\"ALERTA\")\r\n    else:\r\n        print(\"OK\")\r\nif errores == 0:\r\n    print(0)\r\n    print(\"0.00\")\r\nelse:\r\n    promedio = sumadedesfaces/errores\r\n    print(errores)\r\n    print(\"{:.2f}\".format(promedio))',2315),
(2316,'a,b = map(int,input().split())\r\nfor i in range(a,a*b+a,a):\r\n    print(i)',2316),
