(2321,'#include <stdio.h>\r\n#include <math.h>\r\nint main(){\r\n    double a,b,c;\r\n    double valor1, valor2;\r\n    scanf(\"%lf %lf %lf\", &a, &b, &c);\r\n    double discriminante = b*b -4*a*c;\r\n    if (discriminante<0){\r\n        printf(\"No tiene raices reales\");\r\n    } else {\r\n        valor1 = (-b-sqrt(discriminante))/(2*a);\r\n        valor2 = (-b+sqrt(discriminante))/(2*a);\r\n        if (valor1>=valor2){\r\n            printf(\"%.6f %.6f\", valor2, valor1);\r\n        }\r\n        else {\r\n            printf(\"%.6f %.6f\", valor1, valor2);\r\n        }\r\n    }\r\n    return 0;\r\n}',2321),
(2322,'#include <stdio.h>\r\nint main(){\r\n    int a,b,c;\r\n    scanf(\"%d %d %d\", &a, &b, &c);\r\n    if (a+b >= c){\r\n        printf(\"SI\");\r\n    } else {\r\n        if (2*b >= c){\r\n            printf(\"NO\");\r\n        } else {\r\n            printf(\"SI\");\r\n        }\r\n    }\r\n    return 0;\r\n}',2322),
(2323,'#include <stdio.h>\r\nint main(){\r\n    int a;\r\n    scanf(\"%d\", &a);\r\n    if (a%2==0){\r\n        printf(\"PAR\")\r\n    }\r\n    else{\r\n        printf(\"IMPAR\")\r\n    }\r\n}',2323),
