(2334,'#include <stdio.h>\r\n#include <stdlib.h>\r\n#include <math.h>\r\nint main() {\r\n    int n, k, ri, ci, rj, cj, cantidad;\r\n    scanf(\"%d %d %d %d %d %d\", &n,&k,&ri,&ci,&rj,&cj);\r\n    int da = abs(rj - ri);\r\n    int db = abs(cj - ci);\r\n    int a = fmax(da, db);\r\n    int b = fmin(da, db);\r\n\r\n    if (a == 0 && b == 0) {\r\n        cantidad = 0;\r\n    } else if (a == 1 && b == 0) {\r\n        cantidad = 3;\r\n    } else if (a == 2 && b == 2) {\r\n        cantidad = 2;\r\n    } else {\r\n        int x = (int)ceil(a / 2.0);\r\n        int y = (int)ceil((a + b) / 3.0);\r\n        int m = (x > y) ? x : y;\r\n        if ((m % 2) != ((a + b) % 2)) {\r\n            m++;\r\n        }\r\n        cantidad = m;\r\n    }\r\n    printf(k >= cantidad ? \"SI\" : \"NO\");\r\n    return 0;\r\n}',2334),
(2335,'n = int(input())\r\nganador = [0]\r\ndic = dict()\r\nfor i in range(n):\r\n    ASCII = input()\r\n    puntaje = 0\r\n    while True:\r\n        if \"N\" in ASCII and ASCII.count(\"A\") >= 2 and \"V\" in ASCII and \"I\" in ASCII and ASCII.count(\"D\") >= 2:\r\n            puntaje += 1\r\n            ASCII = ASCII.replace(\"N\",\"\",1)\r\n            ASCII = ASCII.replace(\"A\",\"\",2)\r\n            ASCII = ASCII.replace(\"V\",\"\",1)\r\n            ASCII = ASCII.replace(\"I\",\"\",1)\r\n            ASCII = ASCII.replace(\"D\",\"\",2)\r\n        else:\r\n            break\r\n    while True:\r\n        if \"G\" in ASCII and \"R\" in ASCII and \"I\" in ASCII and \"N\" in ASCII and \"C\" in ASCII and \"H\" in ASCII:\r\n            puntaje -= 1\r\n            ASCII = ASCII.replace(\"G\",\"\",1)\r\n            ASCII = ASCII.replace(\"R\",\"\",1)\r\n            ASCII = ASCII.replace(\"I\",\"\",1)\r\n            ASCII = ASCII.replace(\"N\",\"\",1)\r\n            ASCII = ASCII.replace(\"C\",\"\",1)\r\n            ASCII = ASCII.replace(\"H\",\"\",1)\r\n        else:\r\n            break\r\n    dic[i] = puntaje\r\n    if i == 0:\r\n        ganador[0] = i\r\n    else:\r\n        if dic[ganador[0]] >= dic[i]:\r\n            pass\r\n        else:\r\n            ganador[0] = i\r\nprint(f\"Gana el duende {ganador[0]}\")\r\nif ganador[0] == 2:\r\n    print(dic)',2335),
(2336,'while True:\r\n    altura, ancho = map(int, input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n    vitral = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitral.append(fila)\r\n    vitrol = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitrol.append(fila)\r\n    error = 0\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if vitral[i][j] != vitrol[i][j]:\r\n                error += 1\r\n    tamaño = altura * ancho\r\n    if error <= tamaño * 0.1:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2336),
(2337,'n=int(input())\r\nresultados=[]\r\nnavidad={\"N\",\"A\",\"V\",\"I\",\"D\"}\r\ngrinch={\"G\",\"R\",\"I\",\"N\",\"C\",\"H\"}\r\nfor i in range(n): #que tiene el duende i-esimo\r\n	caracteres=list(input())\r\n	puntaje=0\r\n	while True:\r\n		if navidad.issubset(set(caracteres)) and caracteres.count(\"A\")>=2 and caracteres.count(\"D\")>=2:\r\n			caracteres.remove(\"N\")\r\n			caracteres.remove(\"V\")\r\n			caracteres.remove(\"I\")\r\n			for j in range(2):\r\n				caracteres.remove(\"A\")\r\n				caracteres.remove(\"D\")\r\n			puntaje+=1\r\n		else:\r\n			break\r\n	while True:\r\n		if grinch.issubset(set(caracteres)):\r\n			caracteres.remove(\"G\")\r\n			caracteres.remove(\"R\")\r\n			caracteres.remove(\"I\")\r\n			caracteres.remove(\"N\")\r\n			caracteres.remove(\"C\")\r\n			caracteres.remove(\"H\")\r\n			puntaje-=1\r\n		else:\r\n			break\r\n	resultados.append(puntaje)\r\nprint(f\"Gana el duende {resultados.index(max(resultados))}\")',2337),
(2338,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n<10) cout << n/4 << ENDL;\r\n    else cout << 3*n << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2338),
(2339,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    float a,b;\r\n    cin >> a >> b;\r\n    if(b<=40) cout << setprecision(1) << fixed << a*b << ENDL;\r\n    else cout << setprecision(1) << fixed << 40*a + (b-40)*1.5*a << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2339),
(2340,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    float a,b,c;\r\n    cin >> a >> b >> c;\r\n    float d = pow(b,2)-4*a*c;\r\n    if(d<0){\r\n        cout << \"No tiene raices reales\" << ENDL;\r\n        return;\r\n    }\r\n    cout << setprecision(6) << fixed << (-b-pow(d,1/2.0))/(2*a) << \" \";\r\n    cout << setprecision(6) << fixed << (-b+pow(d,1/2.0))/(2*a) << ENDL;;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2340),
(2341,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n<6){\r\n        cout << \"Sin numeros perfectos\" << ENDL;\r\n        return;\r\n    }\r\n    for(int i = 6 ; i<=n ; i++){\r\n        int x = 0;\r\n        for(int k = 1 ; k<i ; k++){\r\n            if(i%k==0) x+=k;\r\n        }\r\n        if(x==i) cout << i << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2341),
(2342,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    while(true){\r\n        int n;\r\n        cin >> n;\r\n        if(n==0) break;\r\n        int i = 1;\r\n        while(n%2==0){\r\n            n/=2;\r\n            i++;            \r\n        }\r\n        cout << n << \" \" << i << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2342),
(2343,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int h = 0, e = 0 , ss = 0;\r\n    while(true){\r\n        string s;\r\n        cin >> s;\r\n        if(s==\"FIN\") break;\r\n        int n;\r\n        cin >> n;\r\n        if(s==\"HorizonteRojo\"){\r\n            if(n>=18) h+=5000;\r\n            continue;\r\n        }\r\n        if(s==\"ElMisterioDelLago\"){\r\n            if(n>=13) e+=5000;\r\n            continue;\r\n        }\r\n        if(n>=12) ss+=5000;\r\n        else ss+=3000;\r\n    }\r\n    cout << \"HorizonteRojo: \" << h << ENDL;\r\n    cout << \"ElMisterioDelLago: \" << e << ENDL;\r\n    cout << \"SueñosDePapel: \" << ss << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2343),
(2344,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int n, m = 0;\r\n    cin >> n;\r\n    for(int i = 0 ; i<n ; i++){\r\n        char e;\r\n        int d;\r\n        cin >> e >> d;\r\n        m+=d*500;\r\n        if(e==\'D\') m+=2000;\r\n        else if(e==\'P\') m+=5000;\r\n    }\r\n    cout << m << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2344),
(2345,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    vi v(3);\r\n    int i = 0;\r\n    while(true){\r\n        char c;\r\n        cin >> c;\r\n        if(c==\'R\') break;\r\n        if(c==\'F\') v[i]++;\r\n        if(c==\'T\'){\r\n            i++;\r\n            i=i%3;\r\n        }\r\n    }\r\n    cout << v[0] << \" \" << v[1] << \" \" << v[2] << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2345),
(2346,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    vector<float> r(4), p(4);\r\n    for(int i = 0 ; i<4 ; i++){\r\n        cin >> r[i];\r\n    }\r\n    for(int i = 0 ; i<4 ; i++){\r\n        cin >> p[i];\r\n    }\r\n    int idx = 0;\r\n    int M = 0;\r\n    for(int i = 0 ; i<4 ; i++){\r\n        float area = pow(r[i],2)/p[i];\r\n        if(area>M){\r\n            M=area;\r\n            idx = i;\r\n        }\r\n    }\r\n    vector<string> ss = {\"pequeña\",\"mediana\",\"grande\",\"familiar\"};\r\n    cout << ss[idx] << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2346),
(2347,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    vector<float> r(4), p(4);\r\n    for(int i = 0 ; i<4 ; i++){\r\n        cin >> r[i];\r\n    }\r\n    for(int i = 0 ; i<4 ; i++){\r\n        cin >> p[i];\r\n    }\r\n    int idx = 0;\r\n    int M = INF_INT;\r\n    for(int i = 0 ; i<4 ; i++){\r\n        float area = p[i]/pow(r[i],2);\r\n        if(area<M){\r\n            M=area;\r\n            idx = i;\r\n        }\r\n    }\r\n    vector<string> ss = {\"pequeña\",\"mediana\",\"grande\",\"familiar\"};\r\n    cout << ss[idx] << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2347),
(2348,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    int u;\r\n    cin >> u;\r\n    int x_o;\r\n    cin >> x_o;\r\n    int f = 0;\r\n    float t = 0;\r\n    for(int i = 1 ; i<n ; i++){\r\n        int x_n;\r\n        cin >> x_n;\r\n        if(abs(x_n-x_o)<=u)cout << \"OK\" << ENDL;\r\n        else{\r\n            cout << \"ALERTA\" << ENDL;\r\n            f++;\r\n            t+=abs(x_n-x_o);\r\n        }\r\n        x_o = x_n;\r\n    }\r\n    if(f==0) cout << 0 << ENDL << setprecision(2) << fixed << 0.00 << ENDL;\r\n    else cout << f << ENDL << setprecision(2) << fixed << t/f << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2348),
(2349,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    for(int i = 0 ; i<n ; i++){\r\n        int x;\r\n        cin >> x;\r\n        if(x%400==0){\r\n            cout << \"BISIESTO\" << ENDL;\r\n        } else if (x%100==0){\r\n            cout << \"NO BISIESTO\" << ENDL;\r\n        } else if (x%4==0){\r\n            cout << \"BISIESTO\" << ENDL;\r\n        } else cout << \"NO BISIESTO\" << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2349),
(2350,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    cout << \"# Collatz para n = \" << n << ENDL;\r\n    cout << n << ENDL;\r\n    while(n!=1){\r\n        if(n%2==0) n=n/2;\r\n        else n=3*n+1;\r\n        cout << n << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2350),
(2351,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n// -------------- //\r\n// -------------- //\r\n\r\nvoid solve(int z){\r\n    int a,b,k;\r\n    cin >> a >> b >> k;\r\n    int min = 2*a;\r\n    int M = 2*b;\r\n    if(min>=k){\r\n        cout << \"SI\" << ENDL;\r\n        return;\r\n    }\r\n    if(M<k){\r\n        cout << \"SI\" << ENDL;\r\n        return;\r\n    }\r\n    cout << \"NO\" << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2351),
(2352,'while True:\r\n    altura, ancho = map(int, input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n    vitral = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitral.append(fila)\r\n    vitrol = []\r\n    for i in range(altura):\r\n        fila = list(input().strip())[:ancho]\r\n        vitrol.append(fila)\r\n    error = 0\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if vitral[i][j] != vitrol[i][j]:\r\n                error += 1\r\n    tamaño = altura * ancho\r\n    if error < tamaño * 0.1:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2352),
(2353,'import random\r\ncoso = [\"La pintura es original\",\"La pintura no es original\"]\r\nprint(random.choice(coso))',2353),
(2354,'import random\r\ncoso = [\"La pintura es original\",\"La pintura no es original\"]\r\nprint(random.choice(coso))',2354),
