(2358,'import random\r\ncoso = [\"La pintura es original\",\"La pintura no es original\"]\r\nwhile True:\r\n    altura,ancho = map(int,input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n    else:\r\n        vitral = []\r\n        for i in range(altura):\r\n            fila = input()\r\n            fila = list(fila)\r\n            vitral.append(fila)\r\n        vitrol = []\r\n        for i in range(altura):\r\n            fila = input()\r\n            fila = list(fila)\r\n            vitrol.append(fila)\r\n        igualdad = 0\r\n        error = 0\r\n        for i in range(altura):\r\n            for j in range(ancho):\r\n                if vitral[i][j] == vitrol[i][j]:\r\n                    igualdad += 1\r\n                else:\r\n                    error += 1\r\n\r\n        tamaño = igualdad+error\r\n        ten = tamaño/10\r\n        print(random.choice(coso))',2358),
(2359,'import random\r\ncoso = [\"La pintura es original\",\"La pintura no es original\"]\r\nwhile True:\r\n    altura,ancho = map(int,input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n    else:\r\n        vitral = []\r\n        for i in range(altura):\r\n            fila = input()\r\n            fila = list(fila)\r\n            vitral.append(fila)\r\n        vitrol = []\r\n        for i in range(altura):\r\n            fila = input()\r\n            fila = list(fila)\r\n            vitrol.append(fila)\r\n        igualdad = 0\r\n        error = 0\r\n        for i in range(altura):\r\n            for j in range(ancho):\r\n                if vitral[i][j] == vitrol[i][j]:\r\n                    igualdad += 1\r\n                else:\r\n                    error += 1\r\n\r\n        tamaño = igualdad+error\r\n        ten = tamaño/10\r\n        print(random.choice(coso))',2359),
(2360,'while True:\r\n    altura, ancho = map(int, input().split())\r\n    if altura == 0 and ancho == 0:\r\n        break\r\n\r\n    vitral = [input().strip() for _ in range(altura)]\r\n    vitrol = [input().strip() for _ in range(altura)]\r\n\r\n    error = 0\r\n    total = altura * ancho\r\n\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if vitral[i][j] != vitrol[i][j]:\r\n                error += 1\r\n\r\n    if error <= total / 10:\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2360),
(2361,'while True:\r\n    h, w = map(int, input().split())\r\n    if h == 0 and w == 0:\r\n        break\r\n\r\n    v1 = [input().strip() for _ in range(h)]\r\n    v2 = [input().strip() for _ in range(h)]\r\n\r\n    errores = sum(\r\n        1\r\n        for i in range(h)\r\n        for j in range(w)\r\n        if v1[i][j] != v2[i][j]\r\n    )\r\n\r\n    print(\r\n        \"La pintura es original\"\r\n        if errores <= (h * w) / 10\r\n        else \"La pintura no es original\"\r\n    )',2361),
(2362,'#include <stdio.h>\r\n\r\nint main() {\r\n    int altura, ancho;\r\n\r\n    while (1) {\r\n        scanf(\"%d %d\", &altura, &ancho);\r\n        if (altura == 0 && ancho == 0) {\r\n            break;\r\n        }\r\n\r\n        char vitral[altura][ancho + 1];\r\n        char vitrol[altura][ancho + 1];\r\n\r\n        for (int i = 0; i < altura; i++) {\r\n            scanf(\"%s\", vitral[i]);\r\n        }\r\n\r\n        for (int i = 0; i < altura; i++) {\r\n            scanf(\"%s\", vitrol[i]);\r\n        }\r\n\r\n        int error = 0;\r\n        int total = altura * ancho;\r\n\r\n        for (int i = 0; i < altura; i++) {\r\n            for (int j = 0; j < ancho; j++) {\r\n                if (vitral[i][j] != vitrol[i][j]) {\r\n                    error++;\r\n                }\r\n            }\r\n        }\r\n\r\n        if (error <= total / 10.0) {\r\n            printf(\"La pintura es original\\n\");\r\n        } else {\r\n            printf(\"La pintura no es original\\n\");\r\n        }\r\n    }\r\n\r\n    return 0;\r\n}',2362),
(2363,'#include <stdio.h>\r\n\r\nint main() {\r\n    int h, w;\r\n\r\n    while (scanf(\"%d %d\", &h, &w), h || w) {\r\n\r\n        char vitral[h][w + 1];\r\n        char fila[w + 1];\r\n        int error = 0;\r\n\r\n        for (int i = 0; i < h; i++) {\r\n            scanf(\"%s\", vitral[i]);\r\n        }\r\n\r\n        for (int i = 0; i < h; i++) {\r\n            scanf(\"%s\", fila);\r\n            for (int j = 0; j < w; j++) {\r\n                if (vitral[i][j] != fila[j]) {\r\n                    error++;\r\n                }\r\n            }\r\n        }\r\n\r\n        if (error <= (h * w) / 10.0)\r\n            printf(\"La pintura es original\\n\");\r\n        else\r\n            printf(\"La pintura no es original\\n\");\r\n    }\r\n\r\n    return 0;\r\n}',2363),
(2364,'#include <stdio.h>\r\n#include <string.h>\r\n\r\nint main() {\r\n    int h, w;\r\n\r\n    while (1) {\r\n        scanf(\"%d %d\", &h, &w);\r\n        if (h == 0 && w == 0) break;\r\n\r\n        char vitral[h][w + 1];\r\n        char fila[w + 1];\r\n\r\n        for (int i = 0; i < h; i++) {\r\n            scanf(\"%s\", vitral[i]);\r\n        }\r\n\r\n        int errores = 0;\r\n        int limite = (h * w) / 10;\r\n\r\n        for (int i = 0; i < h; i++) {\r\n            scanf(\"%s\", fila);\r\n\r\n            /* comparación rápida */\r\n            for (int j = 0; j < w; j++) {\r\n                if (vitral[i][j] != fila[j]) {\r\n                    errores++;\r\n                    if (errores > limite) {\r\n                        printf(\"La pintura no es original\\n\");\r\n\r\n                        /* saltar filas restantes */\r\n                        for (int k = i + 1; k < h; k++) {\r\n                            scanf(\"%s\", fila);\r\n                        }\r\n                        goto siguiente;\r\n                    }\r\n                }\r\n            }\r\n        }\r\n\r\n        printf(\"La pintura es original\\n\");\r\n\r\n    siguiente:;\r\n    }\r\n\r\n    return 0;\r\n}',2364),
(2365,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    if(n>=10) cout << 3*n << ENDL;\r\n    else cout << n/4 << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2365),
(2366,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n>=10) cout << 3*n << ENDL;\r\n    else cout << n/4 << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2366),
(2367,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n>=10) cout << 3*n << ENDL;\r\n    else cout << n/4 << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2367),
(2368,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    float a,b;\r\n    cin >> a >> b;\r\n    if(b<=40) cout << setprecision(1) << fixed << a*b << ENDL;\r\n    else cout << setprecision(1) << fixed << 40*a + (b-40)*a*1.5 << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2368),
(2369,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    float a,b,c;\r\n    cin >> a >> b >> c;\r\n    float d = pow(b,2)-4*a*c;\r\n    if(d<0){\r\n        cout << \"No tiene raices reales\" << ENDL;\r\n        return;\r\n    }\r\n    cout << setprecision(6) << fixed << (-b-pow(d,1.0/2))/(2*a) << \" \";\r\n    cout << setprecision(6) << fixed << (-b+pow(d,1.0/2))/(2*a) << ENDL;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2369),
(2370,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n<6){\r\n        cout << \"Sin numeros perfectos\" << ENDL;\r\n        return;\r\n    }\r\n    for(int i = 6 ; i<=n ; i++){\r\n        int x = 0;\r\n        for(int k = 1 ; k<x ; k++) if(i%k==0) x+=k;\r\n        if(x==i) cout << x << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2370),
(2371,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n<6){\r\n        cout << \"Sin numeros perfectos\" << ENDL;\r\n        return;\r\n    }\r\n    for(int i = 6 ; i<=n ; i++){\r\n        int x = 0;\r\n        for(int k = 1 ; k<i ; k++) if(i%k==0) x+=k;\r\n        if(x==i) cout << x << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2371),
