(2375,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nvoid solve(int z){\r\n    int n;\r\n    cin >> n;\r\n    if(n<6){\r\n        cout << \"Sin numeros perfectos\" << ENDL;\r\n        return;\r\n    }\r\n    for(int i = 6 ; i<n ; i++){\r\n        int x = 0;\r\n        for(int k = 1 ; k<i ; k++) if(i%k==0) x+=k;\r\n        if(x==i) cout << i << ENDL;\r\n    }\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2375),
(2376,'n = int(input())\r\nancho = 2*n+1\r\nmedio = ancho//2\r\n\r\n\r\nestrella = [[\' \']*ancho for _ in range(3)]\r\nestrella[0][medio-2:medio+3] = [\'\\\\\', \' \', \'|\', \' \', \'/\']\r\nestrella[1][medio-4:medio+5] = [\'-\', \'-\', \'-\', \' \', \'*\', \' \', \'-\', \'-\', \'-\']\r\nestrella[2][medio-2:medio+3] = [\'/\', \' \', \'|\', \' \', \'\\\\\']\r\n\r\ncuerpo = []\r\nfor i in range(1, n+1):\r\n    linea = [\' \'] * ancho\r\n    linea[medio - i] = \'/\'\r\n    linea[medio + i] = \'\\\\\'\r\n    linea[medio - i + 1 : medio + i] = [\'*\'] * (2*i - 1)\r\n    cuerpo.append(linea)\r\n\r\n\r\ntronco = [[\' \']*ancho for _ in range(2)]\r\ntronco[0][medio-2:medio+3] = [\'|\', \'|\', \'|\', \'|\', \'|\']\r\ntronco[1][medio-2:medio+3] = [\'|\', \'|\', \'|\', \'|\', \'|\']\r\n\r\n\r\narbol = []\r\nfor linea in estrella:\r\n    arbol.append(linea)\r\nfor linea in cuerpo:\r\n    arbol.append(linea)\r\nfor linea in tronco:\r\n    arbol.append(linea)\r\n\r\nfor linea in arbol:\r\n    print(\'\'.join(linea))',2376),
(2377,'while True:\r\n    tamño = input()\r\n    if tamño == \"0 0\":\r\n        break\r\n    else:\r\n        altura, ancho = map(int, tamño.split())\r\n        pintura1 = []\r\n        for _ in range(altura):\r\n            fila1 = input().split()\r\n            pintura1.append(fila1)\r\n        pintura2 = []\r\n        for _ in range(altura):\r\n            fila2 = input().split()\r\n            pintura2.append(fila2)\r\n        errores = 0\r\n        aciertos = 0\r\n        for i in range(altura):\r\n            for j in range(ancho):\r\n                if pintura1[i][j] == pintura2[i][j]:\r\n                    aciertos += 1\r\n                else:\r\n                    errores += 1\r\n        tamaño = errores + aciertos\r\n        if tamaño/10 >errores:\r\n            print(\"La pintura es original\")\r\n        else:\r\n            print(\"La pintura no es original\")',2377),
(2378,'altura, ancho = map(int, input().split())\r\nmatriz = []\r\nfor _ in range(altura):\r\n    fila = map(int, input().split())\r\n    coso = list(fila)\r\n    matriz.append(fila)\r\ncompar = []\r\nfor _ in range(altura):\r\n    fil = []\r\n    for _ in range(ancho):\r\n        fil.append(\"w\")\r\n    compar.append(fil)\r\nresultado = []\r\narriba = 0\r\nabajo = altura-1\r\nizquierda = 0\r\nderecha = ancho-1\r\nprint(matriz,compar)\r\nwhile True:\r\n    for i in range(ancho):\r\n        if matriz[arriba][i] == \"w\":\r\n            pass\r\n        else:\r\n            resultado.append(matriz[arriba][i])\r\n            matriz[arriba][i] = \"w\"\r\n    arriba += 1\r\n    for i in range(altura):\r\n        if matriz[i][derecha] == \"w\":\r\n            pass\r\n        else:\r\n            resultado.append(matriz[i][derecha])\r\n            matriz[i][derecha] = \"w\"\r\n    derecha -= 1\r\n    for i in range(0,ancho,-1):\r\n        if matriz[abajo][i] == \"w\":\r\n            pass\r\n        else:\r\n            resultado.append(matriz[abajo][i])\r\n            matriz[abajo][i] = \"w\"\r\n    abajo -= 1\r\n    for i in range(0,altura,-1):\r\n        if matriz[i][izquierda] == \"w\":\r\n            pass\r\n        else:\r\n            resultado.append(matriz[i][izquierda])\r\n            matriz[i][izquierda] = \"w\"\r\n    izquierda += 1\r\n    if matriz == compar:\r\n        break\r\n    else:\r\n        pass\r\nprint(resultado)',2378),
(2379,'x = int(input())\r\nfor i in range(x):\r\n    a,b = map(int, input().split())\r\n    print(a+b)',2379),
(2380,'t = int(input())\r\nfor _ in range(t):\r\n    n = int(input())\r\n    c = 0\r\n    dic = dict()\r\n    arreglo_a = list(map(int, input().split()))\r\n    arreglo_b = list(map(int, input().split()))\r\n    for i in range(n):\r\n        for j in range(i+1,n):\r\n            if arreglo_a[i]*arreglo_a[j] == arreglo_b[i]+arreglo_b[j]:\r\n                print(f\"({i+1},{j+1})\")\r\n                c+=1\r\n    print(c)',2380),
(2381,'import itertools\r\n\r\nn = int(input())\r\nedades = list(map(int,input().split()))\r\norden = edades.copy()\r\norden.sort()\r\npermutaciones = list(itertools.permutations(orden))\r\nfor i in permutaciones:\r\n    booleano = True\r\n    for j in range(len(i)):\r\n        if i[j] >= 18:\r\n            pass\r\n        else:\r\n            if j == 0:\r\n                if i[j+1] >=18:\r\n                    pass\r\n                else:\r\n                    booleano = False\r\n            elif j == (len(i)-1):\r\n                if i[j-1] >=18:\r\n                    pass\r\n                else:\r\n                    booleano = False\r\n            else:\r\n                if (i[j+1]>=18 or i[j-1]>=18):\r\n                    pass\r\n                else:\r\n                    booleano = False\r\n    if booleano:\r\n        a = \"\"\r\n        for k in i:\r\n            k = str(k)\r\n            a+= k\r\n            a+=\" \"\r\n        print(a)',2381),
(2382,'#Juego de gato. (Tres en ralla, Tic tac toe)\r\nn=int(input()) #casos de prueba\r\ntablero=[[\"\" for j in range(3)] for k in range(3)] #tablero 3x3\r\nfor i in range(n):\r\n    contador_o=0\r\n    contador_x=0\r\n    hay_vacio=False\r\n    for l in range(3):\r\n        tablero[l]=list(input())\r\n    for fila in range(3):\r\n        for columna in range(3):\r\n            if tablero[fila][columna]==\"O\":\r\n                contador_o+=1\r\n            elif tablero[fila][columna]==\"X\":\r\n                contador_x+=1\r\n            else:\r\n                hay_vacio=True\r\n\r\n    #Caso 1: El juego es valido?\r\n    if (contador_o-contador_x)!=1 and (contador_o-contador_x)!=0:\r\n        print(\"Juego incorrecto.\")\r\n    else:\r\n        #Caso 2: Juegos validos\r\n        if contador_o>=3: #Desde tres circulos, ya existe la posibilidad de ganar\r\n            #revisar filas\r\n            ganador_o=False\r\n            ganador_x=False\r\n            for a in range(3):\r\n                if tablero[a]==[\"O\",\"O\",\"O\"]:\r\n                    ganador_o=True\r\n                elif tablero[a]==[\"X\",\"X\",\"X\"]:\r\n                    ganador_x=True\r\n            if ganador_o==True and ganador_x==True:\r\n                print(\"Juego incorrecto.\")\r\n                continue\r\n            elif ganador_x==True:\r\n                print(\"Gana X.\")\r\n                continue\r\n            elif ganador_o==True:\r\n                print(\"Gana O.\")\r\n                continue\r\n            \r\n            #revisar columnas\r\n            for b in range(3):\r\n                columna=list()\r\n                for c in range(3):\r\n                    columna.append(tablero[c][b])\r\n                if columna==[\"O\",\"O\",\"O\"]:\r\n                    ganador_o=True\r\n                elif columna==[\"X\",\"X\",\"X\"]:\r\n                    ganador_x=True\r\n            if ganador_o==True and ganador_x==True:\r\n                print(\"Juego incorrecto.\")\r\n                continue\r\n            elif ganador_x==True:\r\n                print(\"Gana X.\")\r\n                continue\r\n            elif ganador_o==True:\r\n                print(\"Gana O.\")\r\n                continue\r\n            \r\n            #revisar diagonales\r\n            diagonal_1=[tablero[0][0],tablero[1][1],tablero[2][2]]\r\n            diagonal_2=[tablero[0][2],tablero[1][1],tablero[2][0]]\r\n            if diagonal_1==[\"X\",\"X\",\"X\"] or diagonal_2==[\"X\",\"X\",\"X\"]:\r\n                ganador_x=True\r\n            elif diagonal_1==[\"O\",\"O\",\"O\"] or diagonal_2==[\"O\",\"O\",\"O\"]:\r\n                ganador_o=True\r\n            if ganador_o==True and ganador_x==True:\r\n                print(\"Juego incorrecto.\")\r\n                continue\r\n            elif ganador_x==True:\r\n                print(\"Gana X.\")\r\n                continue\r\n            elif ganador_o==True:\r\n                print(\"Gana O.\")\r\n                continue\r\n        \r\n        #Caso 3: empate?\r\n        if hay_vacio==False:\r\n            print(\"Juego empatado.\")\r\n            continue\r\n        if (contador_o-contador_x)==1:\r\n            print(\"Juego inconcluso, juega X.\")\r\n        if (contador_o-contador_x)==0:\r\n            print(\"Juego inconcluso, juega O.\")',2382),
(2383,'#Multiplicacion de matrices\r\nm,n=map(int,input().split())\r\nmatriz_A=[[\"\" for a in range(n)] for b in range(m)]\r\nfor i in range(m):\r\n    matriz_A[i]=list(map(int,input().split()))\r\no,p=map(int,input().split())\r\nmatriz_B=[[\"\" for c in range(p)] for d in range(o)]\r\nfor j in range(o):\r\n    matriz_B[j]=list(map(int,input().split()))\r\nif n!=o:\r\n    print(\"DimensionError\")\r\nelse:\r\n    matriz_C=[[\"\" for e in range(p)] for f in range(m)]\r\n    #multiplicacion de matrices\r\n    for fila in range(m):\r\n        for repeticiones in range(p): #Cuantas veces operamos con la fila de la matriz A\r\n            resultado=0\r\n            for columnas in range(n):\r\n                resultado=resultado+(matriz_A[fila][columnas]*matriz_B[columnas][repeticiones])\r\n            matriz_C[fila][repeticiones]=resultado\r\n    for item in matriz_C:\r\n        print(*item)',2383),
(2384,'#Las cumbres de Nahuelbuta\r\n#Consideramos como cumbre, aquel punto donde sus vecinos\r\n#son menores al punto actual\r\nn=int(input()) #cantidad de rutas\r\nfor i in range(n):\r\n    ruta=list()\r\n    while True:\r\n        altura=float(input())\r\n        if altura==-1:\r\n            break\r\n        ruta.append(altura)\r\n    #Luego revisaremos las alturas vecinas\r\n    cumbres=list()\r\n    for j in range(1,len(ruta)-1): #llegaremos al penultimo\r\n        if ruta[j-1]<ruta[j] and ruta[j]>ruta[j+1]:\r\n            cumbres.append(j)\r\n    print(f\"Las cumbres de la ruta {n} estan en:\",*cumbres)',2384),
(2385,'#Las cumbres de Nahuelbuta\r\n#Consideramos como cumbre, aquel punto donde sus vecinos\r\n#son menores al punto actual\r\nn=int(input()) #cantidad de rutas\r\nfor i in range(n):\r\n    ruta=list()\r\n    while True:\r\n        altura=float(input())\r\n        if altura==-1:\r\n            break\r\n        ruta.append(altura)\r\n    #Luego revisaremos las alturas vecinas\r\n    cumbres=list()\r\n    for j in range(1,len(ruta)-1): #llegaremos al penultimo\r\n        if ruta[j-1]<ruta[j] and ruta[j]>ruta[j+1]:\r\n            cumbres.append(j)\r\n    print(f\"Las cumbres de la ruta {i+1} estan en:\",*cumbres)',2385),
