(2388,'from itertools import product\r\ncolorssssssssssssssss = [\"R\",\"G\",\"B\",\"O\",\"V\",\"Y\"]\r\nmatriz = []\r\nfor secuencia in product(colorssssssssssssssss, repeat=4):\r\n    matriz.append(secuencia)\r\nn = int(input())\r\nfor _ in range(n):\r\n    bandera = False\r\n    a,b,c = input().split()\r\n    b,c = int(b),int(c)\r\n    a = list(a)\r\n    e,f,g = input().split()\r\n    f,g = int(f),int(g)\r\n    e = list(e)\r\n    for i in range(1296):\r\n        correcto_con_poscicion = 0\r\n        correcto_sin_poscicion = 0\r\n        if a[0] == matriz[i][0]:\r\n            correcto_con_poscicion += 1\r\n        elif matriz[i][0] in a:\r\n            correcto_sin_poscicion += 1\r\n        if a[1] == matriz[i][1]:\r\n            correcto_con_poscicion += 1\r\n        elif matriz[i][1] in a:\r\n            correcto_sin_poscicion += 1\r\n        if a[2] == matriz[i][2]:\r\n            correcto_con_poscicion += 1\r\n        elif matriz[i][2] in a:\r\n            correcto_sin_poscicion += 1\r\n        if a[3] == matriz[i][3]:\r\n            correcto_con_poscicion += 1\r\n        elif matriz[i][3] in a:\r\n            correcto_sin_poscicion += 1\r\n        if correcto_con_poscicion == b and correcto_sin_poscicion == c:\r\n            correcto_con_poscicion_B = 0\r\n            correcto_sin_poscicion_B = 0\r\n            if e[0] == matriz[i][0]:\r\n                correcto_con_poscicion_B += 1\r\n            elif matriz[i][0] in e:\r\n                correcto_sin_poscicion_B += 1\r\n            if e[1] == matriz[i][1]:\r\n                correcto_con_poscicion_B += 1\r\n            elif matriz[i][1] in e:\r\n                correcto_sin_poscicion_B += 1\r\n            if e[2] == matriz[i][2]:\r\n                correcto_con_poscicion_B += 1\r\n            elif matriz[i][2] in e:\r\n                correcto_sin_poscicion_B += 1\r\n            if e[3] == matriz[i][3]:\r\n                correcto_con_poscicion_B += 1\r\n            elif matriz[i][3] in e:\r\n                correcto_sin_poscicion_B += 1\r\n            \r\n            if correcto_con_poscicion_B == f and correcto_sin_poscicion_B == g:\r\n                bandera = True\r\n                break\r\n    if bandera:\r\n        print(\"possible\")\r\n    else:\r\n        print(\"cheats\")',2388),
(2389,'from itertools import permutations\r\ngrupos = int(input())\r\nfor _ in range(grupos):\r\n    cantidad_de_niños = int(input())\r\n    niños = list(map(int, input().split()))\r\n    perms = [list(p) for p in permutations(niños)]\r\n    c = 0\r\n    if cantidad_de_niños%2==0:\r\n        for p in perms:\r\n            izq = 0\r\n            der = 0\r\n            a = len(p)/2\r\n            a = int(a)\r\n            for j in range(a):\r\n                z = p.copy()\r\n                z.reverse()\r\n                izq += p[j]\r\n                der += z[j]\r\n            if izq == der:\r\n                c+=1\r\n    else:\r\n        for p in perms:\r\n            izq = 0\r\n            der = 0\r\n            a = len(p)/2\r\n            a -= 0.5\r\n            a = int(a)\r\n            for j in range(a):\r\n                z = p.copy()\r\n                z.reverse()\r\n                izq += p[j]\r\n                der += z[j]\r\n            if izq == der:\r\n                c+=1\r\n    print(c)',2389),
