(2419,'t = int(input())\r\nfor _ in range(t):\r\n    a, b = map(int, input().split())\r\n    print(a + b)',2419),
(2420,'p, t, c = map(int, input().split())\r\n\r\nsuma_notas = 0\r\nfor _ in range(p):\r\n    suma_notas += int(input())\r\n\r\nasistio_todos_talleres = True\r\nfor _ in range(t):\r\n    asistencia = input().strip().lower()\r\n    if asistencia != \"si\":\r\n        asistio_todos_talleres = False\r\n\r\nclases_asistidas = 0\r\nfor _ in range(c):\r\n    asistencia = input().strip().lower()\r\n    if asistencia == \"si\":\r\n        clases_asistidas += 1\r\n\r\npromedio = suma_notas / p\r\ncumple_clases = clases_asistidas * 100 >= 70 * c\r\n\r\nif promedio > 4 and asistio_todos_talleres and cumple_clases:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2420),
(2421,'a,b,c = map(int,input().split())\r\nn = 0\r\nfor i in range(a):\r\n    x = int(input())\r\n    n+=x\r\naprovado_talleres = True\r\nfor i in range(b):\r\n    x = input()\r\n    if(x!=\"si\"):\r\n        aprovado_talleres = False\r\nasistencia = 0\r\nfor i in range(c):\r\n    x = input()\r\n    if(x==\"si\"):\r\n        asistencia+=1\r\ncant_asistencia = asistencia/c\r\nif(n/a > 4 and aprovado_talleres and cant_asistencia>=0.7):\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2421),
(2422,'p, t, c = map(int, input().split())\r\n#p representa las pruebas, t los tallers y la cantidad de clases del curso\r\nnotas = []\r\ntalleres = []\r\nclases = []\r\nfor n in range(p):\r\n    nota = int(input())\r\n    notas.append(nota)\r\n\r\n#Calculadora promedio notas\r\npromedio = sum(notas) / len(notas)\r\nprint(promedio)\r\n\r\nfor i in range(t):\r\n    taller = input()\r\n    talleres.append(taller)\r\n#calculadora asistencia talleres\r\nasistencia = False\r\nif talleres.count(\"si\") == len(talleres):\r\n    asistencia = True\r\nfor j in range(c):\r\n    clase = input()\r\n    clases.append(clase)\r\n#asistenciaclase\r\nasistencia_clase = False\r\nif clases.count(\"si\") >= c*7/10:\r\n    asistencia_clase = True\r\n#salida\r\nif promedio > 4 and asistencia and asistencia_clase:\r\n    print(\"APRUEBA\")\r\nelse:    \r\n    print(\"REPRUEBA\")',2422),
(2423,'p, t, c = map(int, input().split())\r\n#p representa las pruebas, t los tallers y la cantidad de clases del curso\r\nnotas = []\r\ntalleres = []\r\nclases = []\r\nfor n in range(p):\r\n    nota = int(input())\r\n    notas.append(nota)\r\n\r\n#Calculadora promedio notas\r\npromedio = sum(notas) / len(notas)\r\n\r\nfor i in range(t):\r\n    taller = input()\r\n    talleres.append(taller)\r\n#calculadora asistencia talleres\r\nasistencia = False\r\nif talleres.count(\"si\") == len(talleres):\r\n    asistencia = True\r\nfor j in range(c):\r\n    clase = input()\r\n    clases.append(clase)\r\n#asistenciaclase\r\nasistencia_clase = False\r\nif clases.count(\"si\") >= c*7/10:\r\n    asistencia_clase = True\r\n#salida\r\nif promedio > 4 and asistencia and asistencia_clase:\r\n    print(\"APRUEBA\")\r\nelse:    \r\n    print(\"REPRUEBA\")',2423),
(2424,'p,t,c=map(int,input().split())\r\nestado=\"APRUEBA\"\r\npromedio=0\r\ncantidad_asistencia=0\r\nfor i in range(p):\r\n    nota=int(input())\r\n    promedio+=nota\r\nfor j in range(t):\r\n    asistencia=input()\r\n    if asistencia==\"no\":\r\n        estado=\"REPRUEBA\"\r\nfor k in range(c):\r\n    asistencia=input()\r\n    if asistencia==\"si\":\r\n        cantidad_asistencia+=1\r\npromedio_final=promedio/p\r\nasistencia_final=cantidad_asistencia/c\r\nif estado==\"REPRUEBA\":\r\n    print(estado)\r\nelse:\r\n    if promedio_final>4 or asistencia_final>=0.7:\r\n        print(\"APRUEBA\")\r\n    else:\r\n        print(\"REPRUEBA\")',2424),
(2425,'p, t, c = map(int, input())\r\nprom = 0\r\nasis= 0\r\nfor i in range(p):\r\n    prom = prom+int(input)\r\nprom= prom/(p+1)\r\nfor i in range(t):\r\n    if input()== \"no\":\r\n        reprueba = True\r\nfor i in range(c):\r\n    if input() == \"sí\":\r\n        asis=asis+1\r\nif asis/(c+1):\r\n    reprueba = True\r\nif prom < 0.7:\r\n    reprueba = True\r\nif reprueba==True:\r\n    print(\"REPRUEBA\")',2425),
(2426,'p, t, c = map(int, input().split())\r\nprom = 0\r\nasis= 0\r\nfor i in range(p):\r\n    prom = prom+int(input)\r\nprom= prom/(p+1)\r\nfor i in range(t):\r\n    if input()== \"no\":\r\n        reprueba = True\r\nfor i in range(c):\r\n    if input() == \"sí\":\r\n        asis=asis+1\r\nif asis/(c+1):\r\n    reprueba = True\r\nif prom < 0.7:\r\n    reprueba = True\r\nif reprueba==True:\r\n    print(\"REPRUEBA\")',2426),
(2427,'linea = input()\r\npartes = linea.split()\r\np = int(partes[0])\r\nt = int(partes[1])\r\nc = int(partes[2]) \r\n\r\nsuma_notas = 0\r\nfor i in range(p):\r\n    nota = int(input())\r\n    suma_notas = suma_notas + nota\r\n\r\nasistencia_talleres = 0\r\nfor i in range(t):\r\n    respuesta = input()\r\n    if respuesta == \"si\":\r\n        asistencia_talleres = asistencia_talleres + 1\r\n\r\nasistencia_clases = 0\r\nfor i in range(t):\r\n    respuesta_1 = input()\r\n    if respuesta_1 == \"si\":\r\n        asistencia_clases = asistencia_clases + 1\r\n\r\n\r\npromedio = suma_notas / p\r\nporcentaje_clases = (asistencia_clases / c) * 100\r\n\r\nif promedio >= 4.0 and asistencia_talleres == t and porcentaje_clases >= 70:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2427),
(2428,'linea = input()\r\npartes = linea.split()\r\np = int(partes[0])\r\nt = int(partes[1])\r\nc = int(partes[2]) \r\n\r\nsuma_notas = 0\r\nfor i in range(p):\r\n    nota = int(input())\r\n    suma_notas = suma_notas + nota\r\n\r\nasistencia_talleres = 0\r\nfor i in range(t):\r\n    respuesta = input()\r\n    if respuesta == \"si\":\r\n        asistencia_talleres = asistencia_talleres + 1\r\n\r\nasistencia_clases = 0\r\nfor i in range(t):\r\n    respuesta_1 = input()\r\n    if respuesta_1 == \"si\":\r\n        asistencia_clases = asistencia_clases + 1\r\n\r\n\r\npromedio = suma_notas / p\r\nporcentaje_clases = (asistencia_clases / c) * 100\r\n\r\nif promedio >= 4.0 and asistencia_talleres == t and porcentaje_clases >= 70:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2428),
(2429,'a,b,c = map(int, input().split())\r\nnotas = True\r\ntalleres = True\r\nasistencia = True\r\naa= 0\r\nbb=0\r\ncc=0\r\nfor _ in range(a):\r\n    aaa =float(input())\r\n    aa +=aaa\r\naaa = aaa/a\r\nfor_ in range(b):\r\n    bbb = input()\r\n    if bbb== \"si\":\r\n        pass\r\n    else:\r\n        talleres = False\r\n        break\r\nfor _ in range(c):\r\n    ccc = input()\r\n    if ccc == \"si\":\r\n        cc +=1\r\np = cc/c\r\np *=100\r\nif aaa >= 4.0 and talleres and p >= 70:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2429),
(2430,'a,b,c = map(int, input().split())\r\nnotas = True\r\ntalleres = True\r\nasistencia = True\r\naa= 0\r\nbb=0\r\ncc=0\r\nfor _ in range(a):\r\n    aaa =float(input())\r\n    aa +=aaa\r\naaa = aaa/a\r\nfor_ in range(b):\r\n    bbb = input()\r\n    if bbb== \"si\":\r\n        pass\r\n    else:\r\n        talleres = False\r\n        break\r\nfor _ in range(c):\r\n    ccc = input()\r\n    if ccc == \"si\":\r\n        cc +=1\r\np = cc/c\r\np *=100\r\nif aaa >= 4.0 and talleres and p >= 70:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2430),
(2431,'a,b,c = map(int, input().split())\r\nnotas = True\r\ntalleres = True\r\nasistencia = True\r\naa= 0\r\nbb=0\r\ncc=0\r\nfor _ in range(a):\r\n    aaa =float(input())\r\n    aa +=aaa\r\naaa = aaa/a\r\nfor _ in range(b):\r\n    bbb = input()\r\n    if bbb== \"si\":\r\n        pass\r\n    else:\r\n        talleres = False\r\n        break\r\nfor _ in range(c):\r\n    ccc = input()\r\n    if ccc == \"si\":\r\n        cc +=1\r\np = cc/c\r\np *=100\r\nif aaa >= 4.0 and talleres and p >= 70:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2431),
(2432,'p, t, c = map(int, input().split())\r\nSuma = 0\r\n\r\nfor i in range(p):\r\n    Nota = int(input())\r\n    Suma = Suma + Nota\r\n\r\nPromedio = Suma / p\r\nAsistenciaT = True\r\n\r\nfor i in range(t):\r\n    Asistencia = input()\r\n    if Asistencia == \"no\":\r\n        AsistenciaT = False\r\n\r\nAsistenciaC = 0\r\n\r\nfor i in range(c):\r\n    asistencia = input()\r\n    if asistencia == \"si\":\r\n        AsistenciaC = AsistenciaC + 1\r\n\r\nPorcentajeC = (AsistenciaC / c) * 100\r\n\r\nif Promedio > 4 and AsistenciaT and PorcentajeC >= 70:\r\n    print(\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2432),
