(2434,'p,t,c= map(int,input().split())\r\ncontador= 0\r\ncontador2=0\r\nLista2=[]\r\n\r\nfor a in range (p):\r\n    notas= float(input())\r\n    Lista2.append(notas)\r\npromedio= sum(Lista2)/p #esto es condicion de aprobacion\r\nfor n in range (t):\r\n    talleres= input()\r\n    if talleres== \"no\":\r\n        contador2+=1 #otra condicion\r\nfor l in range(c):\r\n    clases = input()\r\n    if clases== \"si\":\r\n        contador+=1 \r\nporcentaje= (contador/c)*100 #otra condicion\r\n\r\nif promedio<4 or porcentaje<70 or contador2>0:\r\n    print(\"REPRUEBA\")\r\nelse:\r\n    print(\"APRUEBA\")',2434),
(2435,'cuantos= int(input())\r\numbral=int(input())\r\nlista=[]\r\nvariaciones=[]\r\ncontador=0\r\nfor j in range (len(cuantos)):\r\n    casos= int(input())\r\n    lista.append(casos)\r\nfor i in range (len(lista)):\r\n    diferencia= abs(lista[i+1]-lista[i])\r\n    if diferencia > umbral:\r\n        variaciones.append(diferencia)\r\n        contador+=1\r\n        print(\"ALERTA\")\r\n    else:\r\n        print(\"OK\")\r\nprint(contador)\r\nprint((\"{:.2f}\".format(sum(variaciones)/contador)))',2435),
