(2439,'cuantos= int(input())\r\numbral=int(input())\r\nlista=[]\r\nvariaciones=[]\r\ncontador=0\r\nfor j in range (cuantos):\r\n    casos= int(input())\r\n    lista.append(casos)\r\nfor i in range (len(lista)-1):\r\n    diferencia= abs(lista[i+1]-lista[i])\r\n    if diferencia > umbral:\r\n        variaciones.append(diferencia)\r\n        contador+=1\r\n        print(\"ALERTA\")\r\n    else:\r\n        print(\"OK\")\r\nprint(contador)\r\nif contador==0:\r\n    print(\"{:.2f}\".format(contador))\r\nelse:\r\n    promedio= sum(variaciones)/contador\r\n    print(\"{:.2f}\".format(promedio))',2439),
(2440,'#include <stdio.h>\r\n#include <stdbool.h>\r\nint main() {\r\n    int a,b,c,d,p;\r\n    float nota,q;\r\n    char asistencia_a_talleres[2], asistencia_a_clases[2];\r\n    bool bandera = true;\r\n    d = 0;\r\n    p = 0;\r\n    scanf(\"%d %d %d\", &a ,&b, &c);\r\n    for (int i= 0 ; i <= a; i++){\r\n        scanf(\"%f\", &nota);\r\n        d = d+nota;\r\n    }\r\n    d = d/a;\r\n    for (int i= 0; i <= b; i++){\r\n        scanf(\"%s\", asistencia_a_talleres[2]);\r\n        if (asistencia_a_talleres == \"no\"){\r\n            bandera = false;\r\n        }\r\n    for (int i=0 ; i<=c;i++){\r\n        scanf(\"%s\", asistencia_a_clases[2]);\r\n        if (asistencia_a_clases == \"si\"){\r\n            p = p+1;\r\n        }\r\n    }\r\n    q = (p/c)*100;\r\n    if (q>=70 && bandera == true && d>=4){\r\n        printf(\"APROBADO\");\r\n    }else{\r\n        printf(\"DESAPROBADO\");\r\n    }\r\n    return 0;\r\n}',2440),
(2441,'p, t, c = [] \r\nsuma = 0 \r\nfor in range(p):\r\n    nota = int(input()) \r\n        suma = suma + nota\r\npromedio = suma/p\r\n\r\ntalleres = true\r\nfor in range(t):\r\n    x = input()\r\n    if x != \"si\":\r\n        talleres = False\r\n    \r\nasistio = 0\r\nfor in range(c):\r\n    x = input() \r\n        asistio = asistio +1\r\n    \r\nporcentaje = asistio / c\r\n\r\nif promedio > 4 and talleres and pocentaje >= 0.7:\r\n    prin (\"APRUEBA\")\r\nelse:\r\n    print(\"REPRUEBA\")',2441),
(2442,'p, t, c = map(int, input().split())\r\nprom = 0\r\nasis= 0\r\nreprueba = False\r\nfor i in range(p):\r\n    prom = prom+int(input())\r\nprom= prom/p\r\nfor i in range(t):\r\n    if input()== \"no\":\r\n        reprueba = True\r\nfor i in range(c):\r\n    if input() == \"si\":\r\n        asis=asis+1\r\nif asis/c < 0.7:\r\n    reprueba = True\r\nif prom < 0.4:\r\n    reprueba = True\r\nif reprueba==True:\r\n    print(\"REPRUEBA\")\r\nelse:\r\n    print(\"APRUEBA\")',2442),
(2443,'n = int(input())\r\nfor i in range(n):\r\n    lista = []\r\n    cumbres=[]\r\n    while True:\r\n        a = input()\r\n        if float(a) == -1:\r\n            break\r\n        lista.append(float(a))\r\n    for j in range(len(lista)-2):\r\n        if lista[j] < lista[j + 1] > lista[j + 2]:\r\n            cumbres.append(j+1)\r\n    print(\"Las cumbres de la ruta\", i+1, \"estan en:\", *cumbres)',2443),
(2444,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\nint buscar_ganador(char c, vector<vector<char>> w){\r\n    int cant_ganadas = 0;\r\n    for(int i = 0 ; i<3 ; i++){\r\n        if(w[i][0]==c and w[i][1]==c and w[i][2]==c) cant_ganadas++;\r\n    }\r\n    for(int i = 0 ; i<3 ; i++){\r\n        if(w[0][i]==c and w[1][i]==c and w[2][i]==c) cant_ganadas++;\r\n    }\r\n    if(w[0][0]==c and w[1][1]==c and w[2][2]==c) cant_ganadas++;\r\n    if(w[0][2]==c and w[1][1]==c and w[2][0]==c) cant_ganadas++;\r\n    return cant_ganadas;\r\n}\r\nvoid solve(int z){\r\n    vector<vector<char>> w;\r\n    int cant_o = 0, cant_x = 0;\r\n    for(int i = 0 ; i<3 ; i++){\r\n        vector<char> v;\r\n        for(int j = 0 ; j<3 ; j++){\r\n            char c;\r\n            cin >> c;\r\n            if(c==\'X\') cant_x++;\r\n            else if(c==\'O\') cant_o++;\r\n            v.pb(c);\r\n        }\r\n        w.pb(v);\r\n    }\r\n    if(cant_x>cant_o || cant_o>cant_x+1){\r\n        cout << \"Juego incorrecto.\" << ENDL;\r\n        return;\r\n    }\r\n    int g_x = buscar_ganador(\'X\',w);\r\n    int g_o = buscar_ganador(\'O\',w);\r\n    if(g_x>1 || g_o>1 || (g_x==1 and g_o==1)){\r\n        cout << \"Juego incorrecto.\" << ENDL;\r\n        return;\r\n    }\r\n    if(g_o==1){\r\n        cout << \"Gana O.\" << ENDL;\r\n        return;\r\n    }\r\n    if(g_x==1){\r\n        cout << \"Gana X.\" << ENDL;\r\n        return;\r\n    }\r\n    if(cant_x+cant_o==9){\r\n        cout << \"Juego empatado.\" << ENDL;\r\n        return;\r\n    }\r\n    if(cant_x<cant_o){\r\n        cout << \"Juego inconcluso, juega X.\" << ENDL;\r\n        return;\r\n    }\r\n    cout << \"Juego inconcluso, juega O.\" << ENDL;\r\n}\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2444),
(2445,'def bfs_grid(n,m,start_r,start_c):\r\n    distancias = [[-1]*m for _  in range(n)]\r\n    cola = deque([(start_r,start_c)])\r\n    distancias[start_c][start_r] = 0\r\n    movs = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(-1,2),(1,-2),(-1,-2)]\r\n    while cola:\r\n        r,c = cola.popleft()\r\n        for dr,dc in movs:\r\n            nr,nc = r+dr, c+dc\r\n            if 0 <= nr < n and 0 <= nc < m:\r\n                if distancias[nr][nc] ==-1:\r\n                    distancias[nr][nc] = distancias[r][c]+1\r\n                    cola.append((nr,nc))\r\n    return distancias\r\n\r\nn,k,ri,ci,rf,cf = map(int,input().split())\r\nri-=1\r\nci-=1\r\nrf-=1\r\ncf-=1\r\ndistancias = bfs_grid(n,n,ri,ci)\r\nif(distancias[rf][cf]<=k):\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',2445),
(2446,'from collections import deque\r\n\r\ndef bfs_grid(n,m,start_r,start_c):\r\n    distancias = [[-1]*m for _  in range(n)]\r\n    cola = deque([(start_r,start_c)])\r\n    distancias[start_c][start_r] = 0\r\n    movs = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(-1,2),(1,-2),(-1,-2)]\r\n    while cola:\r\n        r,c = cola.popleft()\r\n        for dr,dc in movs:\r\n            nr,nc = r+dr, c+dc\r\n            if 0 <= nr < n and 0 <= nc < m:\r\n                if distancias[nr][nc] ==-1:\r\n                    distancias[nr][nc] = distancias[r][c]+1\r\n                    cola.append((nr,nc))\r\n    return distancias\r\n\r\nn,k,ri,ci,rf,cf = map(int,input().split())\r\nri-=1\r\nci-=1\r\nrf-=1\r\ncf-=1\r\ndistancias = bfs_grid(n,n,ri,ci)\r\nif(distancias[rf][cf]<=k):\r\n    print(\"SI\")\r\nelse:\r\n    print(\"NO\")',2446),
(2447,'n=int(input()) # Casos de prueba\r\ntablero=[[\"\" for j in range(3)] for k in range(3)]\r\nfor i in range(n):\r\n    cantidad_x=0\r\n    cantidad_o=0\r\n    ganador_x=\"no\"\r\n    ganador_o=\"no\"\r\n    for _ in range(3): #Llenar el tablero\r\n        tablero[_]=list(input())\r\n    # analiza el juego:\r\n    # Notas:\r\n    # Como empieza O, X siempre sera uno menor o igual\r\n    # Que O\r\n\r\n    #Contemos la cantidad\r\n    for fila in range(3):\r\n        for columna in range(3):\r\n            if tablero[fila][columna]==\"X\":\r\n                cantidad_x+=1\r\n            elif tablero[fila][columna]==\"O\":\r\n                cantidad_o+=1\r\n    # Juego incorrecto\r\n    if (cantidad_o-cantidad_x)!=0 and (cantidad_o-cantidad_x)!=1:\r\n        print(\"Juego incorrecto.\")\r\n        continue # pasa a la iteracion que sigue\r\n    # Juegos validos de aca en adelante:\r\n\r\n    # Ganadores\r\n\r\n    # Filas\r\n\r\n    for a in range(3):\r\n        if tablero[a]==[\"O\",\"O\",\"O\"]:\r\n            ganador_o=\"si\"\r\n        elif tablero[a]==[\"X\",\"X\",\"X\"]:\r\n            ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego empatado.\")\r\n        continue\r\n\r\n    # columnas\r\n    for b in range(3):\r\n        simbolos_columna=[]\r\n        for c in range(3):\r\n            simbolos_columna.append(tablero[c][b])\r\n        if simbolos_columna==[\"O\",\"O\",\"O\"]:\r\n            ganador_o=\"si\"\r\n        elif simbolos_columna==[\"X\",\"X\",\"X\"]:\r\n            ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego empatado.\")\r\n        continue\r\n\r\n    # diagonal 1\r\n    simbolos_diagonal=[]\r\n    for d in range(3):\r\n        simbolos_diagonal.append(tablero[d][d])\r\n    if simbolos_diagonal==[\"O\",\"O\",\"O\"]:\r\n        ganador_o=\"si\"\r\n    elif simbolos_diagonal==[\"X\",\"X\",\"X\"]:\r\n        ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego empatado.\")\r\n        continue\r\n    simbolos_diagonal=[] # diagonal 2\r\n    for f in range(3):\r\n        simbolos_diagonal.append(tablero[2-f][f])\r\n    if simbolos_diagonal==[\"O\",\"O\",\"O\"]:\r\n        ganador_o=\"si\"\r\n    elif simbolos_diagonal==[\"X\",\"X\",\"X\"]:\r\n        ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego empatado.\")\r\n        continue\r\n    # Caso extra: tablero lleno\r\n\r\n    if cantidad_o==5:\r\n        print(\"Juego empatado.\")\r\n        continue\r\n\r\n\r\n    # quien gano?\r\n    if ganador_x==\"si\":\r\n        print(\"Gana X.\")\r\n        continue\r\n    elif ganador_o==\"si\":\r\n        print(\"Gana O.\")\r\n        continue\r\n    else: #nadie gano\r\n        if (cantidad_o-cantidad_x)==0:\r\n            print(\"Juego inconcluso, juega O.\")\r\n            continue\r\n        elif (cantidad_o-cantidad_x)==1:\r\n            print(\"Juego inconcluso, juega X.\")\r\n            continue',2447),
(2448,'n=int(input()) # Casos de prueba\r\ntablero=[[\"\" for j in range(3)] for k in range(3)]\r\nfor i in range(n):\r\n    cantidad_x=0\r\n    cantidad_o=0\r\n    ganador_x=\"no\"\r\n    ganador_o=\"no\"\r\n    for _ in range(3): #Llenar el tablero\r\n        tablero[_]=list(input())\r\n    # analiza el juego:\r\n    # Notas:\r\n    # Como empieza O, X siempre sera uno menor o igual\r\n    # Que O\r\n\r\n    #Contemos la cantidad\r\n    for fila in range(3):\r\n        for columna in range(3):\r\n            if tablero[fila][columna]==\"X\":\r\n                cantidad_x+=1\r\n            elif tablero[fila][columna]==\"O\":\r\n                cantidad_o+=1\r\n    # Juego incorrecto\r\n    if (cantidad_o-cantidad_x)!=0 and (cantidad_o-cantidad_x)!=1:\r\n        print(\"Juego incorrecto.\")\r\n        continue # pasa a la iteracion que sigue\r\n    # Juegos validos de aca en adelante:\r\n\r\n    # Ganadores\r\n\r\n    # Filas\r\n\r\n    for a in range(3):\r\n        if tablero[a]==[\"O\",\"O\",\"O\"]:\r\n            ganador_o=\"si\"\r\n        elif tablero[a]==[\"X\",\"X\",\"X\"]:\r\n            ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n\r\n    # columnas\r\n    for b in range(3):\r\n        simbolos_columna=[]\r\n        for c in range(3):\r\n            simbolos_columna.append(tablero[c][b])\r\n        if simbolos_columna==[\"O\",\"O\",\"O\"]:\r\n            ganador_o=\"si\"\r\n        elif simbolos_columna==[\"X\",\"X\",\"X\"]:\r\n            ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n\r\n    # diagonal 1\r\n    simbolos_diagonal=[]\r\n    for d in range(3):\r\n        simbolos_diagonal.append(tablero[d][d])\r\n    if simbolos_diagonal==[\"O\",\"O\",\"O\"]:\r\n        ganador_o=\"si\"\r\n    elif simbolos_diagonal==[\"X\",\"X\",\"X\"]:\r\n        ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n    simbolos_diagonal=[] # diagonal 2\r\n    for f in range(3):\r\n        simbolos_diagonal.append(tablero[2-f][f])\r\n    if simbolos_diagonal==[\"O\",\"O\",\"O\"]:\r\n        ganador_o=\"si\"\r\n    elif simbolos_diagonal==[\"X\",\"X\",\"X\"]:\r\n        ganador_x=\"si\"\r\n    if ganador_x==\"si\" and ganador_o==\"si\":\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n    # Caso extra: tablero lleno\r\n\r\n    if cantidad_o==5:\r\n        print(\"Juego empatado.\")\r\n        continue\r\n\r\n\r\n    # quien gano?\r\n    if ganador_x==\"si\":\r\n        print(\"Gana X.\")\r\n        continue\r\n    elif ganador_o==\"si\":\r\n        print(\"Gana O.\")\r\n        continue\r\n    else: #nadie gano\r\n        if (cantidad_o-cantidad_x)==0:\r\n            print(\"Juego inconcluso, juega O.\")\r\n            continue\r\n        elif (cantidad_o-cantidad_x)==1:\r\n            print(\"Juego inconcluso, juega X.\")\r\n            continue',2448),
(2449,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> w;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> v;\r\n        for(int j = 0 ; j<m ; j++){\r\n            v.pb(\'.\');\r\n        }\r\n        w.pb(v);\r\n    }\r\n    int k;\r\n    cin >> k;\r\n    for(int i = 0 ; i<k ; i++){\r\n        int r,c;\r\n        char t;\r\n        cin >> r >> c >> t;\r\n        w[r-1][c-1]=t;   \r\n    }\r\n    int r,c;\r\n    cin >> r >> c;\r\n    r--;\r\n    c--;\r\n    w[r][c]=\'*\';\r\n    // D:0,R:1,U:2,L:3\r\n    vi dr = {1,0,-1,0};\r\n    vi dc = {0,1,0,-1};\r\n    char dir;\r\n    cin >> dir;\r\n    int x;\r\n    if(dir == \'D\') x = 0;\r\n    if(dir == \'R\') x = 1;\r\n    if(dir == \'U\') x = 2;\r\n    if(dir == \'L\') x = 3;\r\n    int dirr = dr[x];\r\n    int dirc = dc[x];\r\n\r\n    while(true){\r\n        dirr = dr[x];\r\n        dirc = dc[x];\r\n        r+=dirr;\r\n        c+=dirc;\r\n        if(r<0 || c<0 || r>=n || c>=m) break;\r\n        if(w[r][c]==\'.\'){\r\n            if(dirc==0) w[r][c]=\'|\';\r\n            else w[r][c]=\'-\';\r\n            continue;\r\n        }\r\n        if(w[r][c]==\'-\' || w[r][c]==\'|\'){\r\n            w[r][c]=\'+\';\r\n            continue;\r\n        }\r\n        if(w[r][c]==\'\\\\\'){\r\n            if(x==1) x = 0;\r\n            else if(x==2) x = 3;\r\n            else if(x==0) x = 1;\r\n            else if(x==3) x = 2;\r\n        }\r\n        if(w[r][c]==\'/\'){\r\n            if(x==0) x = 3;\r\n            else if(x==3) x = 0;\r\n            else if(x==1) x = 2;\r\n            else if(x==2) x = 1;\r\n        }\r\n    }    \r\n    for(vector v : w){\r\n        for(char c : v) cout << c;\r\n        cout << ENDL;\r\n    }\r\n}\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2449),
(2450,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> w;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> v;\r\n        for(int j = 0 ; j<m ; j++){\r\n            v.pb(\'.\');\r\n        }\r\n        w.pb(v);\r\n    }\r\n    int k;\r\n    cin >> k;\r\n    for(int i = 0 ; i<k ; i++){\r\n        int r,c;\r\n        char t;\r\n        cin >> r >> c >> t;\r\n        w[r-1][c-1]=t;   \r\n    }\r\n    int r,c;\r\n    cin >> r >> c;\r\n    r--;\r\n    c--;\r\n    w[r][c]=\'*\';\r\n    // D:0,R:1,U:2,L:3\r\n    vi dr = {1,0,-1,0};\r\n    vi dc = {0,1,0,-1};\r\n    char dir;\r\n    cin >> dir;\r\n    int x;\r\n    if(dir == \'D\') x = 0;\r\n    if(dir == \'R\') x = 1;\r\n    if(dir == \'U\') x = 2;\r\n    if(dir == \'L\') x = 3;\r\n    int dirr = dr[x];\r\n    int dirc = dc[x];\r\n\r\n    while(true){\r\n        dirr = dr[x];\r\n        dirc = dc[x];\r\n        r+=dirr;\r\n        c+=dirc;\r\n        if(r<0 || c<0 || r>=n || c>=m) break;\r\n        if(w[r][c]==\'.\'){\r\n            if(dirc==0) w[r][c]=\'|\';\r\n            else w[r][c]=\'-\';\r\n            continue;\r\n        }\r\n        if(w[r][c]==\'-\' || w[r][c]==\'|\'){\r\n            w[r][c]=\'+\';\r\n            continue;\r\n        }\r\n        if(w[r][c]==\'\\\\\'){\r\n            if(x==1) x = 0;\r\n            else if(x==2) x = 3;\r\n            else if(x==0) x = 1;\r\n            else if(x==3) x = 2;\r\n        }\r\n        if(w[r][c]==\'/\'){\r\n            if(x==0) x = 3;\r\n            else if(x==3) x = 0;\r\n            else if(x==1) x = 2;\r\n            else if(x==2) x = 1;\r\n        }\r\n    }    \r\n    for(vector v : w){\r\n        for(char c : v) cout << c;\r\n        cout << ENDL;\r\n    }\r\n}\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2450),
(2451,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\n\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> w;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> v;\r\n        for(int j = 0 ; j<m ; j++){\r\n            v.pb(\'.\');\r\n        }\r\n        w.pb(v);\r\n    }\r\n    int k;\r\n    cin >> k;\r\n    for(int i = 0 ; i<k ; i++){\r\n        int r,c;\r\n        char t;\r\n        cin >> r >> c >> t;\r\n        w[r-1][c-1]=t;   \r\n    }\r\n    int r,c;\r\n    cin >> r >> c;\r\n    r--;\r\n    c--;\r\n    w[r][c]=\'*\';\r\n    // D:0,R:1,U:2,L:3\r\n    vi dr = {1,0,-1,0};\r\n    vi dc = {0,1,0,-1};\r\n    char dir;\r\n    cin >> dir;\r\n    int x;\r\n    if(dir == \'D\') x = 0;\r\n    if(dir == \'R\') x = 1;\r\n    if(dir == \'U\') x = 2;\r\n    if(dir == \'L\') x = 3;\r\n    int dirr = dr[x];\r\n    int dirc = dc[x];\r\n\r\n    while(true){\r\n        dirr = dr[x];\r\n        dirc = dc[x];\r\n        r+=dirr;\r\n        c+=dirc;\r\n        if(r<0 || c<0 || r>=n || c>=m) break;\r\n        if(w[r][c]==\'.\'){\r\n            if(dirc==0) w[r][c]=\'|\';\r\n            else w[r][c]=\'-\';\r\n            continue;\r\n        }\r\n        if(w[r][c]==\'-\' || w[r][c]==\'|\'){\r\n            w[r][c]=\'+\';\r\n            continue;\r\n        }\r\n        if(w[r][c]==\'\\\\\'){\r\n            if(x==1) x = 0;\r\n            else if(x==2) x = 3;\r\n            else if(x==0) x = 1;\r\n            else if(x==3) x = 2;\r\n        }\r\n        if(w[r][c]==\'/\'){\r\n            if(x==0) x = 3;\r\n            else if(x==3) x = 0;\r\n            else if(x==1) x = 2;\r\n            else if(x==2) x = 1;\r\n        }\r\n    }    \r\n    for(vector<char> v : w){\r\n        for(char c : v) cout << c;\r\n        cout << ENDL;\r\n    }\r\n}\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2451),
(2452,'n, k, r_i, c_i, r_fin, c_fin = map(int, input().split())\r\n\r\nr_i -= 1\r\nc_i -= 1\r\nr_fin -= 1\r\nc_fin -= 1\r\n\r\n\r\nif r_i == r_fin and c_i == c_fin:\r\n    print(\"SI\")\r\nelse:\r\n    cola = [(r_i, c_i, 0)]\r\n    indice = 0\r\n    visitado = [[False] * n for _ in range(n)]\r\n    visitado[r_i][c_i] = True\r\n\r\n    movimientos = [\r\n        (2, 1), (2, -1), (-2, 1), (-2, -1),\r\n        (1, 2), (1, -2), (-1, 2), (-1, -2)\r\n    ]\r\n\r\n    encontrado = False\r\n\r\n    while indice < len(cola):\r\n        r, c, dist = cola[indice]\r\n        indice += 1\r\n\r\n        if dist >= k:\r\n            continue\r\n\r\n        for dr, dc in movimientos:\r\n            nr, nc = r + dr, c + dc\r\n\r\n            if 0 <= nr < n and 0 <= nc < n:\r\n                if not visitado[nr][nc]:\r\n                    if nr == r_fin and nc == c_fin:\r\n                        print(\"SI\")\r\n                        encontrado = True\r\n                        indice = len(cola) + 1\r\n                        break\r\n                    visitado[nr][nc] = True\r\n                    cola.append((nr, nc, dist + 1))\r\n        \r\n        if encontrado:\r\n            break\r\n    if not encontrado:\r\n        print(\"NO\")',2452),
(2453,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n// -------------- //\r\n#ifndef ONLINE_JUDGE\r\n    #include \"debugger.h\"\r\n#endif\r\n// -------------- //\r\nusing ll = long long;\r\nusing vi = vector<int>;\r\nusing vll = vector<long long>;\r\nusing vvi = vector<vector<int>>;\r\nusing pi = pair<int, int>;\r\nusing vpi = vector<pair<int, int>>;\r\nusing vvpi = vector<vector<pair<int, int>>>;\r\n// -------------- //\r\nconst int INF_INT = 1e9;\r\nconst ll INF_LL = (ll)1e18;\r\nconst int MOD = 1e9 + 7;\r\nconst int MAX_FACT = 20;\r\nconst double EPS = 1e-9;\r\n// -------------- //\r\n#define all(x) x.begin(), x.end()\r\n#define ALL(A,B,RES) all(A),all(B),inserter(RES,RES.begin())\r\n#define sz(x) (int)x.size()\r\n#define ENDL \'\\n\'\r\n#define pb push_back\r\n#define fi first\r\n#define se second\r\n\r\nint const dr[] = {1,0,-1,0};\r\nint const dc[] = {0,1,0,-1};\r\n\r\nbool dentro_de_limites(int n, int m, int i, int j){\r\n    return(i>=0 and j>=0 and i<n and j<m);\r\n}\r\n\r\nvoid solve(int z){\r\n    int n,m;\r\n    cin >> n >> m;\r\n    vector<vector<char>> w,w_c;\r\n    for(int i = 0 ; i<n ; i++){\r\n        vector<char> v;\r\n        for(int j = 0 ; j<m ; j++){\r\n            char c;\r\n            cin >> c;\r\n            v.pb(c);\r\n        }\r\n        w.pb(v);\r\n    }\r\n    w_c = w;\r\n    while(true){\r\n        for(int i = 0 ; i<n ; i++){\r\n            for(int j = 0 ; j<m ; j++){\r\n                int cant_ast = 0;\r\n                int cant_u = 0;\r\n                for(int x = 0 ; x<4 ; x++){\r\n                    int drr = i+dr[x];\r\n                    int dcc = j+dc[x];\r\n                    if(dentro_de_limites(n,m,drr,dcc)){\r\n                        if(w[drr][dcc]==\'u\') cant_u++;\r\n                        else if(w[drr][dcc]==\'*\') cant_ast++;\r\n                    }\r\n                }\r\n                if(w[i][j]==\'u\'){\r\n                    if(cant_ast==0) w_c[i][j]=\'.\';\r\n                } else if(w[i][j]==\'.\'){\r\n                    if(cant_u>=2) w_c[i][j]=\'U\';\r\n                } else if(w[i][j]==\'U\'){\r\n                    if(cant_u<2) w_c[i][j]=\'.\';\r\n                }\r\n            }\r\n        }\r\n        if(w==w_c){\r\n            for(vector<char> v : w_c){\r\n                for(char c : v) cout << c;\r\n                cout << ENDL;\r\n            }\r\n            return;\r\n        } else {\r\n            w = w_c;\r\n        }\r\n    }\r\n}\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::begin();\r\n    #endif\r\n    int t = 1;\r\n    //cin >> t;\r\n    int z = 1;\r\n    while(t--){\r\n        solve(z);\r\n        z++;\r\n    }\r\n    #ifndef ONLINE_JUDGE\r\n        LocalJudge::end();\r\n    #endif\r\n\r\n    return 0;\r\n}',2453),
(2454,'n,m=map(int,input().split()) #n filas, m caracteres\r\ngrilla=[[\"\" for i in range(m)] for j in range(n)]\r\nfor k in range(n):\r\n    grilla[k]=list(input()) # grilla inicial\r\n    # las estrellas nunca cambian pase lo que pase\r\n    grilla_nueva=grilla.copy()\r\n    def vecinos():\r\n        for fila in range(n):\r\n            for columna in range(m):\r\n                lista_vecinos=[]\r\n                elemento_actual=grilla_nueva[fila][columna]\r\n                if fila!=0:\r\n                    up=grilla_nueva[fila-1][columna]\r\n                    lista_vecinos.append(up)\r\n                if fila!=(n-1):\r\n                    down=grilla_nueva[fila+1][columna]\r\n                    lista_vecinos.append(down)\r\n                if columna!=0:\r\n                    left=grilla_nueva[fila][columna-1]\r\n                    lista_vecinos.append(left)\r\n                if columna!=(m-1):\r\n                    right=grilla_nueva[fila][columna+1]\r\n                    lista_vecinos.append(right)\r\n\r\n                if elemento_actual==\"*\":\r\n                    continue\r\n                elif elemento_actual==\"u\":\r\n                    if lista_vecinos.count(\"*\")<1:\r\n                        grilla_nueva[fila][columna]=\".\"\r\n                        continue\r\n                elif elemento_actual==\".\":\r\n                    if lista_vecinos.count(\"u\")>1:\r\n                        grilla_nueva[fila][columna]=\"U\"\r\n                        continue\r\n                elif elemento_actual==\"U\":\r\n                    if lista_vecinos.count(\"u\")<2:\r\n                        grilla_nueva[fila][columna]=\".\"\r\n                        continue\r\nvecinos()\r\nwhile grilla!=grilla_nueva:\r\n    vecinos()\r\nfor item in grilla_nueva:\r\n    print(*item)',2454),
(2455,'import copy\r\ndef vecinos(alt,anc,matriz):\r\n    lista = []\r\n    a = matriz[alt+1][anc]\r\n    b = matriz[alt-1][anc]\r\n    c = matriz[alt][anc+1]\r\n    d = matriz[alt][anc-1]\r\n    lista.append(a)\r\n    lista.append(b)\r\n    lista.append(c)\r\n    lista.append(d)\r\n    return lista\r\naltura, ancho = map(int, input().split())\r\nmatriz = []\r\nurbanik = []\r\nlin = []\r\nfor _ in range(ancho+2):\r\n    lin.append(\"w\")\r\nmatriz.append(lin)\r\nurbanik.append(lin)\r\nfor _ in range(altura):\r\n    linea = input()\r\n    linea = list(linea)\r\n    linea.append(\"w\")\r\n    linea.reverse()\r\n    linea.append(\"w\")\r\n    linea.reverse()\r\n    matriz.append(linea)\r\n    urbanik.append(linea)\r\nmatriz.append(lin)\r\nurbanik.append(lin)\r\nwhile True:\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if matriz[i][j] == \".\" and vecinos(i,j,matriz).count(\"u\") >= 2:\r\n                urbanik[i][j] = \"U\"\r\n            elif matriz[i][j] == \"u\" and vecinos(i,j,matriz).count(\"*\") == 0:\r\n                urbanik[i][j] = \".\"\r\n            elif matriz[i][j] == \"U\" and vecinos(i,j,matriz).count(\"u\") < 2:\r\n                urbanik[i][j] = \".\"\r\n            else:\r\n                pass\r\n    if matriz == urbanik:\r\n        break\r\n    else:\r\n        pass\r\n    matriz = copy.deepcopy(urbanik)\r\nmatriz.pop(0)\r\nmatriz.pop(altura)\r\nfor l in matriz:\r\n    l.pop(0)\r\n    l.pop(ancho)\r\nfor q in matriz:\r\n    print(\"\".join(q))',2455),
(2456,'casos = int(input())\r\nfor i in range(casos):\r\n    Tablero = []\r\n    Circulo = 0\r\n    Equis = 0\r\n    circulogana = False\r\n    equisgana = False\r\n\r\n    for _ in range(3):\r\n        fila = input().split()\r\n        Tablero.append(fila)\r\n    for i in Tablero:\r\n        Circulo = i.count(\"O\") + Circulo\r\n        Equis = i.count(\"X\") + Equis\r\n    if Equis>Circulo:\r\n        print(\"Juego incorrecto.\")\r\n        break\r\n    if sum(Tablero[i].count(\"O\") == 3 for i in range(3)) == 1 or sum(sum(Tablero[f][c] == \"O\" for f in range(3)) == 3 for c in range(3)) == 1 or sum(Tablero[q][q]==\"O\"for q in range(3))==3 or sum(Tablero[n][2-n]==\"O\" for n in range(3))==3:\r\n        circulogana = True\r\n    if sum(Tablero[i].count(\"X\") == 3 for i in range(3)) == 1 or sum(sum(Tablero[f][c] == \"X\" for f in range(3)) == 3 for c in range(3)) == 1 or sum(Tablero[q][q]==\"X\"for q in range(3))==3 or sum(Tablero[n][2-n]==\"X\" for n in range(3))==3:\r\n        equisgana = True\r\n    if circulogana and equisgana:\r\n        print(\"Juego incorrecto.\")\r\n        break\r\n    if all(celda != \"-\" for fila in Tablero for celda in fila) and not (circulogana or equisgana):\r\n        print(\"Juego empatado.\")\r\n    if Circulo == Equis and not (circulogana or equisgana):\r\n        print(\"Juego inconcluso, juega O.\")\r\n    if Equis < Circulo and not (circulogana or equisgana):\r\n        print(\"Juego inconcluso, juega X.\")\r\n    if circulogana:\r\n        print(\"Gana O.\")\r\n    if equisgana:\r\n        print(\"Gana X.\")',2456),
(2457,'casos = int(input())\r\nfor h in range(casos):\r\n    Tablero = []\r\n    Circulo = 0\r\n    Equis = 0\r\n    circulogana = False\r\n    equisgana = False\r\n    for _ in range(3):\r\n        fila = list(input())\r\n        Tablero.append(fila)\r\n    for i in Tablero:\r\n        Circulo = i.count(\"O\") + Circulo\r\n        Equis = i.count(\"X\") + Equis\r\n    if Equis>Circulo or Circulo >Equis+1:\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n    if sum(Tablero[i].count(\"O\") == 3 for i in range(3)) == 1 or sum(sum(Tablero[f][c] == \"O\" for f in range(3)) == 3 for c in range(3)) == 1 or sum(Tablero[q][q]==\"O\"for q in range(3))==3 or sum(Tablero[n][2-n]==\"O\" for n in range(3))==3:\r\n        circulogana = True\r\n    if sum(Tablero[i].count(\"X\") == 3 for i in range(3)) == 1 or sum(sum(Tablero[f][c] == \"X\" for f in range(3)) == 3 for c in range(3)) == 1 or sum(Tablero[q][q]==\"X\"for q in range(3))==3 or sum(Tablero[n][2-n]==\"X\" for n in range(3))==3:\r\n        equisgana = True\r\n    if circulogana and equisgana:\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n    if all(celda != \"-\" for fila in Tablero for celda in fila) and not (circulogana or equisgana):\r\n        print(\"Juego empatado.\")\r\n    if Circulo == Equis and not (circulogana or equisgana):\r\n        print(\"Juego inconcluso, juega O.\")\r\n    if Equis < Circulo and not (circulogana or equisgana):\r\n        print(\"Juego inconcluso, juega X.\")\r\n    if circulogana:\r\n        print(\"Gana O.\")\r\n    if equisgana:\r\n        print(\"Gana X.\")',2457),
(2458,'casos = int(input())\r\nfor h in range(casos):\r\n    Tablero = []\r\n    Circulo = 0\r\n    Equis = 0\r\n    circulogana = False\r\n    equisgana = False\r\n    for _ in range(3):\r\n        fila = list(input())\r\n        Tablero.append(fila)\r\n    for i in Tablero:\r\n        Circulo = i.count(\"O\") + Circulo\r\n        Equis = i.count(\"X\") + Equis\r\n    if Equis>Circulo or Circulo >Equis+1:\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n    if sum(Tablero[i].count(\"O\") == 3 for i in range(3)) == 1 or sum(sum(Tablero[f][c] == \"O\" for f in range(3)) == 3 for c in range(3)) == 1 or sum(Tablero[q][q]==\"O\"for q in range(3))==3 or sum(Tablero[n][2-n]==\"O\" for n in range(3))==3:\r\n        circulogana = True\r\n    if sum(Tablero[i].count(\"X\") == 3 for i in range(3)) == 1 or sum(sum(Tablero[f][c] == \"X\" for f in range(3)) == 3 for c in range(3)) == 1 or sum(Tablero[q][q]==\"X\"for q in range(3))==3 or sum(Tablero[n][2-n]==\"X\" for n in range(3))==3:\r\n        equisgana = True\r\n    if circulogana and equisgana:\r\n        print(\"Juego incorrecto.\")\r\n        continue\r\n    if circulogana:\r\n        print(\"Gana O.\")\r\n    elif equisgana:\r\n        print(\"Gana X.\")\r\n    elif all(celda != \"-\" for fila in Tablero for celda in fila):\r\n        print(\"Juego empatado.\")\r\n    elif Circulo == Equis:\r\n        print(\"Juego inconcluso, juega O.\")\r\n    else:\r\n        print(\"Juego inconcluso, juega X.\")',2458),
(2459,'altura, ancho = map(int, input().split())\r\nmatriz = []\r\nw = []\r\nfor i in range(ancho+2):\r\n    w.append(\"w\")\r\nmatriz.append(w)\r\nfor i in range(altura):\r\n    lista = [\"w\"]\r\n    for j in range(ancho):\r\n        lista.append(\".\")\r\n    lista.append(\"w\")\r\n    matriz.append(lista)\r\nmatriz.append(w)\r\nobstaculos = int(input())\r\nfor i in range(obstaculos):\r\n    a,b,c = input().split()\r\n    a = int(a)\r\n    b = int(b)\r\n    matriz[a][b] = c\r\n\r\np,q = map(int, input().split())\r\n\r\ndireccion = input()\r\nmatriz[p][q] = \"*\"\r\n\r\n\r\nwhile True:\r\n    if direccion == \"R\":\r\n        q += 1\r\n        if matriz[p][q] == \".\":\r\n            matriz[p][q] = \"-\"\r\n        elif matriz[p][q] == \"/\":\r\n            direccion = \"U\"\r\n        elif matriz[p][q] == \"\\\\\":\r\n            direccion = \"D\"\r\n        elif matriz[p][q] == \"|\":\r\n            matriz[p][q] = \"+\"\r\n        elif matriz[p][q] == \"w\":\r\n            break\r\n    elif direccion == \"L\":\r\n        q -=1\r\n        if matriz[p][q] == \".\":\r\n            matriz[p][q] = \"-\"\r\n        elif matriz[p][q] == \"/\":\r\n            direccion = \"D\"\r\n        elif matriz[p][q] == \"\\\\\":\r\n            direccion = \"U\"\r\n        elif matriz[p][q] == \"|\":\r\n            matriz[p][q] = \"+\"\r\n        elif matriz[p][q] == \"w\":\r\n            break\r\n    elif direccion == \"U\":\r\n        p -=1\r\n        if matriz[p][q] == \".\":\r\n            matriz[p][q] = \"|\"\r\n        elif matriz[p][q] == \"-\":\r\n            matriz[p][q] = \"+\"\r\n        elif matriz[p][q] == \"/\":\r\n            direccion = \"R\"\r\n        elif matriz[p][q] == \"\\\\\":\r\n            direccion = \"L\"\r\n        elif matriz[p][q] == \"w\":\r\n            break\r\n    elif direccion == \"D\":\r\n        p +=1\r\n        if matriz[p][q] == \".\":\r\n            matriz[p][q] = \"|\"\r\n        elif matriz[p][q] == \"-\":\r\n            matriz[p][q] = \"+\"\r\n        elif matriz[p][q] == \"/\":\r\n            direccion = \"L\"\r\n        elif matriz[p][q] == \"\\\\\":\r\n            direccion = \"R\"\r\n        elif matriz[p][q] == \"w\":\r\n            break\r\nmatriz.pop()\r\nmatriz.pop(0)\r\nnueva_matriz = []\r\nfor i in range(altura):\r\n    pan = []\r\n    for j in range(ancho+2):\r\n        c = matriz[i][j]\r\n        if c == \"w\":\r\n            pass\r\n        else:\r\n            pan.append(c)\r\n    nueva_matriz.append(pan)\r\nfor i in nueva_matriz:\r\n    print(\"\".join(i))',2459),
(2460,'def vecino(matriz,y,x,d):\r\n    lista = []\r\n    lista.append(matriz[y][x+1])\r\n    lista.append(matriz[y][x-1])\r\n    lista.append(matriz[y+1][x])\r\n    lista.append(matriz[y-1][x])\r\n    a = lista.count(d)\r\n    return a\r\naltura,ancho = map(int, input().split())\r\nurbanik = []\r\nlista = []\r\nfor i in range(ancho+2):\r\n    lista.append(\"w\")\r\nurbanik.append(lista)\r\nfor i in range(altura):\r\n    fila = input()\r\n    fila = \"w\"+fila+\"w\"\r\n    fila = list(fila)\r\n    urbanik.append(fila)\r\nurbanik.append(lista)\r\nurbanik_1 = [fila.copy() for fila in urbanik]\r\nwhile True:\r\n    for i in range(altura):\r\n        for j in range(ancho):\r\n            if urbanik[i+1][j+1] == \".\":\r\n                if vecino(urbanik,i+1,j+1,\"u\") >= 2:\r\n                    urbanik_1[i+1][j+1] = \"U\"\r\n                else:\r\n                    pass\r\n            elif urbanik[i+1][j+1] == \"u\":\r\n                if vecino(urbanik,i+1,j+1,\"*\") == 0:\r\n                    urbanik_1[i+1][j+1] = \".\"\r\n                else:\r\n                    pass\r\n            elif urbanik[i+1][j+1] == \"U\":\r\n                if vecino(urbanik,i+1,j+1,\"u\") >= 2:\r\n                    pass\r\n                else:\r\n                    urbanik_1[i+1][j+1] = \".\"\r\n            else:\r\n                pass\r\n    if urbanik == urbanik_1:\r\n        break\r\n    else:\r\n        urbanik = [fila.copy() for fila in urbanik_1]\r\nurbanik.pop()\r\nurbanik.pop(0)\r\nfor i in range(altura):\r\n    pam = []\r\n    for j in range(ancho+2):\r\n        if urbanik[i][j] == \"w\":\r\n            pass\r\n        else:\r\n            pam.append(urbanik[i][j])\r\n    print(\"\".join(pam))',2460),
(2461,'n = int(input())\r\nMATRIZ = [[],[],[]]\r\nfor i in range(n):\r\n    linea_1 = input().strip()\r\n    linea_2 = input().strip()\r\n    linea_3 = input().strip()\r\n    MATRIZ = linea_1+linea_2+linea_3\r\n    \r\n    #CASO EN GANA X\r\n    GANA_X = False\r\n    if MATRIZ[0] == MATRIZ[1] and MATRIZ[1] == MATRIZ[2] and MATRIZ[2] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[3] == MATRIZ[4] and MATRIZ[4] == MATRIZ[5] and MATRIZ[5] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[6] == MATRIZ[7] and MATRIZ[7] == MATRIZ[8] and MATRIZ[8] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[0] == MATRIZ[3] and MATRIZ[3] == MATRIZ[6] and MATRIZ[6] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[1] == MATRIZ[4] and MATRIZ[4] == MATRIZ[7] and MATRIZ[7] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[2] == MATRIZ[5] and MATRIZ[5] == MATRIZ[8] and MATRIZ[8] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[0] == MATRIZ[4] and MATRIZ[4] == MATRIZ[8] and MATRIZ[8] == \"X\":\r\n        GANA_X = True\r\n    elif MATRIZ[2] == MATRIZ[4] and MATRIZ[4] == MATRIZ[6] and MATRIZ[6] == \"X\":\r\n        GANA_X = True\r\n\r\n    #CASO EN QUE GANA O\r\n    GANA_O = False\r\n    if MATRIZ[0] == MATRIZ[1] and MATRIZ[1] == MATRIZ[2] and MATRIZ[2] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[3] == MATRIZ[4] and MATRIZ[4] == MATRIZ[5] and MATRIZ[5] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[6] == MATRIZ[7] and MATRIZ[7] == MATRIZ[8] and MATRIZ[8] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[0] == MATRIZ[3] and MATRIZ[3] == MATRIZ[6] and MATRIZ[6] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[1] == MATRIZ[4] and MATRIZ[4] == MATRIZ[7] and MATRIZ[7] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[2] == MATRIZ[5] and MATRIZ[5] == MATRIZ[8] and MATRIZ[8] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[0] == MATRIZ[4] and MATRIZ[4] == MATRIZ[8] and MATRIZ[8] == \"O\":\r\n        GANA_O = True\r\n    elif MATRIZ[2] == MATRIZ[4] and MATRIZ[4] == MATRIZ[6] and MATRIZ[6] == \"O\":\r\n        GANA_O = True\r\n    \r\n    JUEGO_INCONCLUSO = False\r\n    if GANA_O == False and GANA_X == False:\r\n        JUEGO_INCONCLUSO = True\r\n    else:\r\n        pass\r\n\r\n    O = 0\r\n    X = 0\r\n    vacio = 0\r\n    for i in MATRIZ:\r\n        if i ==\"X\":\r\n            X +=1\r\n        elif i == \"O\":\r\n            O +=1\r\n        else:\r\n            vacio +=1\r\n    if X>O or (GANA_O == GANA_X and GANA_X==True):\r\n        print(\"Juego incorrecto.\")\r\n    elif X+1 == O and vacio == 0:\r\n        print(\"Juego empatado.\")\r\n    elif GANA_X == True:\r\n        print(\"Gana X.\")\r\n    elif GANA_O == True:\r\n        print(\"Gana O.\")\r\n    elif X == O and vacio != 0:\r\n        print(\"Juego inconcluso, juega O.\")\r\n    elif (X+1) == O and vacio !=0:\r\n        print(\"Juego inconcluso, juega X.\")',2461),
