(2471,'#include <stdio.h>\r\n#include <stdbool.h>\r\n#include <string.h>\r\nint main()\r\n{\r\n    int p, t, c;\r\n    float nota, suma = 0, promedio;\r\n    char talleres[3], asis[3];\r\n    bool notas_de_prueba = true;\r\n    bool asis_taller = true;\r\n    bool asistencia = true;\r\n    scanf(\"%d %d %d\", &p, &t, &c);\r\n    for (int i = 0; i < p; i++){\r\n        scanf(\"%f\", &nota);\r\n        suma += nota;\r\n    }\r\n    promedio = suma / p;\r\n    if (promedio < 4){\r\n        notas_de_prueba = false;\r\n    }\r\n    for (int i = 0; i < t; i++){\r\n        scanf(\"%s\", talleres);\r\n        if (strcmp(talleres, \"no\") == 0){\r\n            asis_taller = false;\r\n        }\r\n    }\r\n    int presentes = 0;\r\n    for (int i = 0; i < c; i++){\r\n        scanf(\"%s\", asis);\r\n        if (strcmp(asis, \"si\") == 0){\r\n            presentes++;\r\n        }\r\n    }\r\n    if (presentes < c * 0.7){\r\n        asistencia = false;\r\n    }\r\n    if (asistencia && asis_taller && notas_de_prueba){\r\n        printf(\"APRUEBA\");\r\n    } else {\r\n        printf(\"REPRUEBA\");\r\n    }\r\n    return 0;\r\n}',2471),
