(2590,'#función de adyacentes  \r\ndef ady(I,i,j):\r\n    J=[]\r\n    if i!=0:\r\n        J.append(I[i-1][j])\r\n    if j!=0:\r\n        J.append(I[i][j-1])\r\n    if j!=len(I[0])-1:\r\n        J.append(I[i][j+1])\r\n    if i!=len(I)-1:\r\n        J.append(I[i+1][j])\r\n    return J\r\n#función de existencia en lista\r\ndef exi(I,i):\r\n    j=0\r\n    for k in range(len(I)):\r\n        if I[k]==i:\r\n            j=1\r\n    return j        \r\n    \r\n#cantidad de laberintos\r\nz=int(input())\r\nfor n in range(z):\r\n#creación de un laberinto   \r\n    x,y=map(int,input().split())\r\n    A=[]\r\n    for m in range(x):\r\n        A1=list(map(int,input().split()))\r\n        A.append(A1)\r\n        \r\n#1=3, rango 2=3\r\n    w=0\r\n    A[0][0]=3\r\n    for o in range((x+1)*(y+1)):\r\n        if w==1:\r\n            break\r\n        for n in range(x):\r\n            if w==1:\r\n                break\r\n            for m in range(y):\r\n                if w==1:\r\n                    break\r\n                if A[n][m]==1:\r\n                    B=ady(A,n,m)\r\n                    if exi(B,3)==1:\r\n                        A[n][m]=3\r\n                        if exi(B,2)==1:\r\n                            print(\"Escape exitoso\")\r\n                            w=1\r\n    if w==0:\r\n        print(\"No hay escapatoria\")',2590),
(2591,'#función factorial\r\ndef factorial(i):\r\n     if i==0:\r\n         return(1)\r\n     i=i*factorial(i-1)\r\n     return(i)\r\n\r\n#fómula del coeficiente binomial\r\nx,y=map(int,input().split())\r\nz=factorial(x)/(factorial(y)*factorial(x-y))\r\nz=int(z)\r\nprint(z)',2591),
(2592,'x=input()\r\nx=list(x)\r\nx.reverse()\r\ny=\"\".join(x)\r\nprint(y)',2592),
(2593,'x=int(input())\r\nA=[]\r\nB=[]\r\nfor n in range(x):\r\n    y,z=input().split()\r\n    z=float(z)\r\n    C=[y,z]\r\n    A.append(C)\r\n    B.append(y)\r\nB=set(B)\r\nB=sorted(list(B))\r\nD=[]\r\nfor n in range(len(B)):\r\n    D1=[B[n]]\r\n    D.append(D1)\r\nfor n in range(len(B)):\r\n    for m in range(len(A)):\r\n        if A[m][0]==B[n]:\r\n            D[n].append(A[m][1])\r\nfor n in range(len(B)):\r\n    if len(D[n])<4:\r\n        w=\"p\"\r\n    else:\r\n        w=(D[n][1]+D[n][2]+D[n][3])/3\r\n        w=f\"{w:.2f}\"\r\n    print(f\"{D[n][0]} {w}\")',2593),
(2594,'import sys\r\n\r\nfor linea in sys.stdin:\r\n    linea = linea.strip()\r\n    if not linea:\r\n        continue\r\na, b= map(int,input().split())\r\nif (a,b)!=(0,0):\r\n    pintura_1 = []\r\n    for _ in range(a):\r\n        c = list(map(int,input().split()))\r\n        pintura_1.append(c)\r\n    pintura_2 = []\r\n    for _ in range(a):\r\n        d = list(map(int,input().split()))\r\n        pintura_2.append(d)\r\n    coincidencias = 0\r\n    errores = 0\r\n    total = 0\r\n    for i in range(a):\r\n        for j in range(b):\r\n            if pintura_1[i][j] == pintura_2[i][j]:\r\n                coincidencias += 1\r\n                total += 1\r\n            else:\r\n                errores +=1\r\n                total+=1\r\n    if errores < (total/10):\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2594),
(2595,'import sys\r\n\r\nfor a in sys.stdin:\r\n    a = a.strip()\r\n    if not a:\r\n        continue\r\na, b= map(int,input().split())\r\nif (a,b)!=(0,0):\r\n    pintura_1 = []\r\n    for _ in range(a):\r\n        c = list(map(int,input().split()))\r\n        pintura_1.append(c)\r\n    pintura_2 = []\r\n    for _ in range(a):\r\n        d = list(map(int,input().split()))\r\n        pintura_2.append(d)\r\n    coincidencias = 0\r\n    errores = 0\r\n    total = 0\r\n    for i in range(a):\r\n        for j in range(b):\r\n            if pintura_1[i][j] == pintura_2[i][j]:\r\n                coincidencias += 1\r\n                total += 1\r\n            else:\r\n                errores +=1\r\n                total+=1\r\n    if errores < (total/10):\r\n        print(\"La pintura es original\")\r\n    else:\r\n        print(\"La pintura no es original\")',2595),
(2596,'n = int(input())\r\ndef factorial(n):\r\n    if n == 0:\r\n        return 1\r\n    else:\r\n        return n * factorial(n - 1)\r\nresultado = factorial(n)\r\nprint(resultado)',2596),
(2597,'n = int(input())\r\n\r\nfor i in range(n):\r\n    datos1, datos2 = input(). split()\r\n    datos1 = int(datos1)\r\n    datos2 = int(datos2)\r\n    suma = datos1 + datos2\r\n    print(suma)',2597),
(2598,'lista=[]\r\ncontador=0\r\ncontador2=0\r\nvacio= set()\r\nfor i in range(entrada):\r\n    cartas= input().split()\r\n    lista.append(cartas)\r\n\r\nconjuntos = [set(oracion) for oracion in lista]\r\ninterseccion = set.intersection(*conjuntos)\r\n\r\nfor j in range(len(lista)-1):\r\n    contador+=1\r\n    intersección= (set(lista[j]) & set(lista[j+1]))\r\n    if len(intersección)==1:\r\n        contador2+=1\r\nif contador == contador2 and interseccion==vacio:\r\n    print(\"VALIDA\")\r\nelse:\r\n    print(\"NO VALIDA\")',2598),
