(2605,'entrada= int(input())\r\n\r\nfor j in range(entrada):\r\n    lista=[]\r\n    cumbres=[]\r\n    while True:\r\n        puntos= float(input())\r\n        if puntos==-1:\r\n            break\r\n        lista.append(puntos)\r\n    for i in range(1, len(lista)-1):\r\n        if lista[i-1]<lista[i] and lista[i]>lista[i+1]:\r\n            cumbres.append(i)\r\n    print(\"Las cumbres de la ruta\", j+1, \"estan en:\", (\" \".join(str(x) for x in cumbres)))#no me sale como lista sino que como numeros separados',2605),
