(2607,'entrada= int(input())\r\nlista=[]\r\nfor i in range(entrada):\r\n    numeros= map(int, input().split())\r\n    lista.extend(numeros)\r\nconjunto= set(lista)\r\nlista_nueva= list(conjunto)\r\nlista_nueva.sort(reverse=True)\r\npunta=min(lista_nueva)\r\nprint(punta)\r\nbase= []\r\nbase.append(punta)\r\nfor j in range(1, len(lista_nueva)):\r\n    base.append(lista_nueva[len(lista_nueva)-1-j])\r\n    base.sort(reverse=True)\r\n    print((\" \".join(str(x) for x in base)))',2607),
(2608,'entrada= int(input())\r\nlista=[]\r\nfor i in range(entrada):\r\n    numeros= map(int, input().split())\r\n    lista.extend(numeros)\r\nconjunto= set(lista)\r\nlista_nueva= list(conjunto)\r\nlista_nueva.sort(reverse=True)\r\npunta=min(lista_nueva)\r\n#print(punta)\r\nbase= []\r\n#base.append(punta)\r\nfor j in range( len(lista_nueva)):\r\n    if j==entrada:\r\n        break\r\n    base.append(lista_nueva[len(lista_nueva)-1-j])\r\n    base.sort(reverse=True)\r\n    print((\" \".join(str(x) for x in base)))',2608),
(2609,'# combinatorial\r\nn,k=map(int,input().split())\r\ndef combinatoria(totales,elegidos): #n y k\r\n	#caso base:\r\n		if totales==elegidos or elegidos==0:\r\n			return 1\r\n		return combinatoria(totales-1,elegidos-1)+combinatoria(totales-1,elegidos)\r\nprint(combinatoria(n,k))',2609),
(2610,'# inversion de cadena\r\ns=list(input()) # cadena separada\r\nlargo=len(s)\r\ns_inverse=list()\r\ndef inversion(cadena,longitud):\r\n	# caso base\r\n	if longitud==0: # fin de cadena\r\n		return\r\n	s_inverse.append(s[longitud-1]) # indice\r\n	return inversion(cadena,longitud-1)\r\ninversion(s,largo)\r\nprint(\"\".join(s_inverse))',2610),
(2611,'def factorial(n):\r\n    if(n==1):\r\n        return 1\r\n    return n*factorial(n-1)\r\nn = int(input())\r\nprint(factorial(n))',2611),
(2612,'def factorial(n):\r\n    if(n==0):\r\n        return 1\r\n    return n*factorial(n-1)\r\nn = int(input())\r\nprint(factorial(n))',2612),
(2613,'def fibbonacci(n):\r\n    if(n==0):\r\n        return 0\r\n    if(n==1):\r\n        return 1\r\n    return fibbonacci(n-1)+fibbonacci(n-2)\r\n\r\nn = int(input())\r\nprint(fibbonacci(n))',2613),
(2614,'def mult(a,b):\r\n    if(b==0):\r\n        return 0\r\n    return a+mult(a,b-1)\r\n\r\na,b = map(int,input().split())\r\nprint(mult(a,b))',2614),
(2615,'n = int(input())\r\ndef fibonacci(n):\r\n    if n == 0:\r\n        return 0\r\n    elif n == 1:\r\n        return 1\r\n    else:\r\n        return fibonacci(n - 1) + fibonacci(n - 2)\r\nresultado = fibonacci(n)\r\nprint(resultado)',2615),
(2616,'def sum_hasta(n):\r\n    if(n==1):\r\n        return 1\r\n    return n+sum_hasta(n-1)\r\n    \r\n\r\nn = int(input())\r\nprint(sum_hasta(n))',2616),
(2617,'def conteo(A,x,L,i=0):\r\n    if(i==L-1):\r\n        if(A[i]==x):\r\n            return 1\r\n        return 0\r\n    return int(A[i]==x)+conteo(A,x,L,i+1)\r\n\r\nA = list(map(int,input().split()))\r\nx = int(input())\r\nprint(conteo(A,x,len(A)))',2617),
(2618,'def conteo(A,x,L,i=0):\r\n    if(i==L-1):\r\n        return int(A[i]==x)\r\n    return int(A[i]==x)+conteo(A,x,L,i+1)\r\nA = list(map(int,input().split()))\r\nx = int(input())\r\nprint(conteo(A,x,len(A)))',2618),
(2619,'n = int(input())\r\ndef sumatoria (n):\r\n    if n == 0:\r\n        return 0\r\n    else:\r\n        return n + sumatoria(n-1)\r\nresultado = sumatoria(n)\r\nprint(resultado)',2619),
(2620,'def inversion_cadena(s,i):\r\n    if(i==0):\r\n        return(s[i])\r\n    return s[i] + inversion_cadena(s,i-1)\r\ns = input()\r\nprint(inversion_cadena(s,len(s)-1))',2620),
(2621,'def C(n,k):\r\n    if(k==0 or k==n):\r\n        return 1\r\n    return C(n-1,k-1)+C(n-1,k)\r\n\r\nn,k = map(int,input().split())\r\nprint(C(n,k))',2621),
(2622,'def multi(a, b):\r\n    if a == 0 or b == 0:\r\n        return 0\r\n    else:\r\n        return a + multi(a, b - 1)\r\na, b = map(int, input(). split())\r\nresultado = multi(a, b)\r\nprint(resultado)',2622),
(2623,'n = int(input())\r\nfor i in range(n):\r\n    a = int(input())\r\n    if a % 3 == 0 and a % 5 == 0:\r\n        print(\'MÚLTIPLO DE AMBOS\')\r\n    elif a % 3 == 0:\r\n        print(\'MÚLTIPLO DE 3\')\r\n    elif a % 5 == 0:\r\n        print(\'MÚLTIPLO DE 5\')\r\n    else:\r\n        print(\'NO ES MÚLTIPLO DE 3 NI DE 5\')',2623),
(2624,'class Jugador:\r\n    def __init__(self, nombre):\r\n        self.nombre = nombre\r\n        self.dinero = 1500\r\n        self.posición = 0\r\n        self.propiedades = []\r\n        pass\r\n    # Metodos\r\n    def mostrar_propiedades(self):\r\n        if len(self.propiedades) == 0:\r\n            print(f\"Jugador {self.nombre} no tiene propiedades.\")\r\n            return\r\n        print(f\"Las propiedades de {self.nombre} son:\")\r\n        for propiedad in self.propiedades:\r\n            print(f\"- {propiedad.nombre}\")\r\n    def comprar(self, propiedad):\r\n        if self.dinero >= propiedad.costo:\r\n            self.dinero = self.dinero-propiedad.costo\r\n            self.propiedades.append(propiedad)\r\n    def venderalbanco(self, propiedad):\r\n        if propiedad in self.propiedades:\r\n            self.dinero = int(self.dinero + (propiedad.costo * 0.5))\r\n            self.propiedades.remove(propiedad)\r\n            print(f\"la propiedad {propiedad.nombre} fue vendida al banco\")\r\n#############\r\n\r\nclass Propiedad:\r\n    def __init__(self, nombre, costo, color):\r\n        self.nombre = nombre\r\n        self.costo = costo\r\n        self.color = color\r\n        pass\r\n    def __str__(self):\r\n        return f\"nombre: {self.nombre}, costo: {self.costo}, color: {self.color}\"\r\n\r\n###########\r\n\r\njugador1 = Jugador(\"Valdivieso\")\r\nprop1 = Propiedad(\"Plaza Park\", 500, \"Azul\")\r\njugador1.comprar(prop1)\r\njugador1.mostrar_propiedades()\r\nprint(prop1)',2624),
(2625,'class Pila:\r\n    def __init__(self):\r\n        self.tamaño = 3\r\n        self.arreglo = [None] * self.tamaño\r\n        self.altura = 0\r\n        pass\r\n    def apilar(self, elemento):\r\n        if self.altura < self.tamaño:\r\n            self.arreglo[self.altura] = elemento\r\n            self.altura = self.altura +1\r\n            print(F\"Elemento {elemento} fue apilado\")\r\n            return\r\n        raise IndexError(\"La pila esta llena\")\r\n    def __str__(self):\r\n        return f\"{self.arreglo} Altura: {self.altura} Tamaño: {self.tamaño}\"        \r\n        \r\npila1= Pila()\r\nprint(pila1)\r\npila1.apilar(\"plato1\")\r\npila1.apilar(\"plato2\")\r\npila1.apilar(\"plato3\")\r\nprint(pila1)',2625),
(2626,'def fight(hp, force, turn):\r\n    opponent = (turn + 1) % 2\r\n\r\n    damage = force[turn] * hp[turn]\r\n    hp[opponent] -= damage\r\n\r\n    if hp[opponent] <= 0:\r\n        return f\"Player {turn + 1}\"\r\n\r\n    return fight(hp, force, (turn + 1) % 2)\r\n\r\n\r\nh1, f1, h2, f2 = map(int, input().split())\r\n\r\nhp = [h1, h2]\r\nforce = [f1, f2]\r\n\r\nprint(fight(hp, force, 0))',2626),
(2627,'def invertir_cadena(s):\r\n    if len(s) == 0:\r\n        return \"\"\r\n    return s[-1] + invertir_cadena(s[:-1])\r\nentrada = input()\r\nresultado = invertir_cadena(entrada)\r\nprint(resultado)',2627),
(2628,'def suma_n_naturales(n):\r\n    if n == 1: \r\n        return 1\r\n    return n + suma_n_naturales(n - 1)\r\nn = int(input())\r\nprint(suma_n_naturales(n))',2628),
(2629,'def entregar_vuelto(indice, monto, monedas):\r\n    if indice == len(monedas) or monto == 0:\r\n        return\r\n\r\n    moneda = monedas[indice]\r\n    cantidad = monto // moneda\r\n\r\n    if cantidad > 0:\r\n        print(f\"{moneda}x{cantidad}\")\r\n\r\n    entregar_vuelto(indice + 1, monto - moneda * cantidad, monedas)\r\n\r\n\r\nn, monto = map(int, input().split())\r\nmonedas = list(map(int, input().split()))\r\n\r\nentregar_vuelto(0, monto, monedas)',2629),
(2630,'def limpiar(texto):\r\n    texto = texto.lower()\r\n    return texto\r\n\r\ndef dar_vuelta(frase):\r\n    limpio = limpiar(frase)\r\n    return limpio[::-1]\r\n\r\nfrase = input(str())\r\nprint(dar_vuelta(frase))',2630),
