(2638,'#lip sync\r\narreglo=list(input())\r\nabiertos=[]\r\ncerrados={\"}\",\"]\",\")\"}\r\ndef sincronizacion(indice,n):\r\n    # caso base: fin de lista\r\n    if indice==(n-1):\r\n        return \"SI\"\r\n    # si aparece un cerrado...\r\n    if arreglo[indice] in cerrados:\r\n        if len(abiertos)==0:\r\n            return \"NO\"\r\n        if arreglo[indice]==\"}\":\r\n            if abiertos[-1]!=\"{\":\r\n                return \"NO\"\r\n        if arreglo[indice]==\")\":\r\n            if abiertos[-1]!=\"(\":\r\n                return \"NO\"\r\n        if arreglo[indice]==\"]\":\r\n            if abiertos[-1]!=\"[\":\r\n                return \"NO\"\r\n        # si el cerrado coincide\r\n        del abiertos[-1]\r\n        return sincronizacion(indice+1,n)\r\n    # añadir a la lista de abiertos\r\n    abiertos.append(arreglo[indice])\r\n    return sincronizacion(indice+1,n)\r\n\r\nresultado=sincronizacion(0,len(arreglo))\r\nprint(resultado)',2638),
(2639,'def combate(HP_1,F_1,HP_2,F_2,i=1):\r\n    if HP_1 <=0 or HP_2 <= 0:\r\n        if HP_1 <=0:\r\n            return \"Player 2\"\r\n        else:\r\n            return \"Player 1\"\r\n    else:\r\n        if i%2!=0:\r\n            DAÑO_1 = HP_1*F_1\r\n            return combate(HP_1,F_1,HP_2-DAÑO_1,F_2,i+1)\r\n        else:\r\n            DAÑO_2 = HP_2*F_2\r\n            return combate(HP_1-DAÑO_2,F_1,HP_2,F_2,i+1)\r\nHP_1,F_1,HP_2,F_2 = map(int, input().split())\r\nprint(combate(HP_1,F_1,HP_2,F_2,))',2639),
(2640,'def combate(hp1,f1,hp2,f2, turno = 0):\r\n    if(turno%2==0):\r\n        hp2-=hp1*f1\r\n    else:\r\n        hp1-=hp2*f2\r\n    if(hp2<=0):\r\n        print(\"Player 1\")\r\n        return\r\n    if(hp1<=0):\r\n        print(\"Player 2\")\r\n        return\r\n    combate(hp1,f1,hp2,f2, turno+1)\r\n\r\n\r\nhp1,f1,hp2,f2 = map(int,input().split())\r\ncombate(hp1,f1,hp2,f2)',2640),
(2641,'hp1,f1,hp2,f2=map(int,input().split())\r\ndef gan(a,b,c,d):\r\n    if c<=0:\r\n        return \'Player 1\'\r\n    if a<=0:\r\n        return \'Player 2\'\r\n    return gan(a-c*d,b,c-a*b,d)\r\nprint(f\'{gan(hp1,f1,hp2,f2)}\')',2641),
(2642,'hp1,f1,hp2,f2=map(int,input().split())\r\ndef gan(a,b,c,d):\r\n    if c<=0:\r\n        return \'Player 1\'\r\n    if a<=0:\r\n        return \'Player 2\'\r\n    return gan(a-c*d,b,c-a*b,d)\r\nprint(f\'{gan(hp1,f1,hp2,f2)}\')',2642),
(2643,'# foodtruck\r\nn,m=map(int,input().split())\r\nmonedas=list(map(int,input().split()))\r\n# queremos llegar a m monedas\r\n# revisa si es posible usar la\r\n# moneda mas grande primero\r\n# las monedas ya estan ordenadas\r\nmonedas_usadas=[]\r\ntipos_monedas=[]\r\ndef vuelto(indice,resto):\r\n    #caso base\r\n    if resto==m:\r\n        return\r\n    if resto+monedas[indice]<=m:\r\n        monedas_usadas.append(monedas[indice])\r\n        if monedas[indice] not in tipos_monedas:\r\n            tipos_monedas.append(monedas[indice])\r\n        return vuelto(indice,resto+monedas[indice])\r\n    else:\r\n        # pasa a la moneda que sigue\r\n        return vuelto(indice+1,resto)\r\n\r\nvuelto(0,0)\r\nfor item in tipos_monedas:\r\n    print(f\"{item}x{monedas_usadas.count(item)}\")',2643),
(2644,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n    if vida1==1 and vida2==1:\r\n        return print(\"Player 1\")\r\n    else:\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2==vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        if contador==1:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1==vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2644),
(2645,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n    if vida1==vida2:\r\n        return print(\"Player 1\")\r\n    else:\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2==vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        if contador==1:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1==vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2645),
(2646,'def coso(m,A,i=0, cant_ac = 0):\r\n    if(i==len(A)):\r\n        return\r\n    if(m<A[i]):\r\n        if(cant_ac!=0):\r\n            print(f\"{A[i]}x{cant_ac}\")\r\n        coso(m,A,i+1)\r\n    else:\r\n        m -= A[i]\r\n        cant_ac +=1\r\n        coso(m,A,i,cant_ac)\r\n\r\nn,m = map(int,input().split())\r\nA = list(map(int,input().split()))\r\ncoso(m,A)',2646),
(2647,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n    if vida1==vida2:\r\n        return print(\"Player 1\")\r\n    else:\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2==vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        elif contador==1:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1==vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2647),
(2648,'def LISP(s, i=0,cant_p=0,cant_c=0,cant_l=0):\r\n    \r\n    if(i==len(s)):\r\n        if(cant_p ==0 and cant_c == 0 and cant_l==0):\r\n            print(\"SI\")\r\n            return\r\n        print(\"NO\")\r\n        return\r\n    \r\n    if(s[i]==\"(\"):\r\n        cant_p+=1\r\n        LISP(s,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\")\"):\r\n        if(cant_p==0):\r\n            print(\"NO\")\r\n            return\r\n        cant_p-=1\r\n        LISP(s,i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"[\"):\r\n        cant_c+=1\r\n        LISP(s,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"]\"):\r\n        if(cant_c==0):\r\n            print(\"NO\")\r\n            return\r\n        cant_c-=1\r\n        LISP(s,i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"{\"):\r\n        cant_l+=1\r\n        LISP(s,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"}\"):\r\n        if(cant_l==0):\r\n            print(\"NO\")\r\n            return\r\n        cant_l-=1\r\n        LISP(s,i+1,cant_p,cant_c,cant_l)\r\n\r\ns = input()\r\nLISP(s)',2648),
(2649,'vida1,f1,vida2,f2= map(int,input().split())\r\nprint(\"Player 2\")',2649),
(2650,'#peleas \r\nhp1,f1,hp2,f2=map(int,input().split())\r\n# el poder es siempre constante\r\ndef pelea(vida1,vida2,turno):\r\n    #siempre empieza player 1\r\n    #caso base: alguien tiene vida\r\n    # no positiva\r\n    if vida1<=0:\r\n        return \"Player 2\"\r\n    if vida2<=0:\r\n        return \"Player 1\"\r\n    if turno==1: #turno de 1\r\n        return pelea(vida1,vida2-(vida1*f1),2)\r\n    if turno==2: #turno de 2:\r\n        return pelea(vida1-(vida2*f2),vida2,1)\r\nresultado=pelea(hp1,hp2,1)\r\nprint(resultado)\r\n# revisa vida 2\r\n# si cumple entonces pasa a 1\r\n# despues vuelta 2 y etc...',2650),
(2651,'def LISP(s, abiertos = [],i=0,cant_p=0,cant_c=0,cant_l=0):\r\n\r\n    if(i==len(s)):\r\n        if(cant_p ==0 and cant_c == 0 and cant_l==0):\r\n            print(\"SI\")\r\n            return\r\n        print(\"NO\")\r\n        return\r\n    \r\n    if(s[i]==\"(\"):\r\n        abiertos.append(\"(\")\r\n        cant_p+=1\r\n        LISP(s, abiertos, i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\")\"):\r\n        if(abiertos[len(abiertos)-1]!=\"(\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        if(cant_p==0):\r\n            print(\"NO\")\r\n            return\r\n        cant_p-=1\r\n        LISP(s, abiertos, i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"[\"):\r\n        abiertos.append(\"[\")\r\n        cant_c+=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"]\"):\r\n        if(abiertos[len(abiertos)-1]!=\"[\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        if(cant_c==0):\r\n            print(\"NO\")\r\n            return\r\n        cant_c-=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"{\"):\r\n        abiertos.append(\"{\")\r\n        cant_l+=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"}\"):\r\n        if(abiertos[len(abiertos)-1]!=\"{\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        if(cant_l==0):\r\n            print(\"NO\")\r\n            return\r\n        cant_l-=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n\r\ns = input()\r\nLISP(s)',2651),
(2652,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n    if vida1>=vida2:\r\n        return print(\"Player 1\")\r\n    else:\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2==vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        elif contador==1:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1==vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2652),
(2653,'import sys\r\nsys.stdin = open(f\"entrada.txt\",\"r\")\r\nsys.stdout = open(f\"salida.txt\",\"w\")\r\n\r\n\r\ndef LISP(s, abiertos = [],i=0,cant_p=0,cant_c=0,cant_l=0):\r\n\r\n    if(i==len(s)):\r\n        if(cant_p ==0 and cant_c == 0 and cant_l==0):\r\n            print(\"SI\")\r\n            return\r\n        print(\"NO\")\r\n        return\r\n    \r\n    if(s[i]==\"(\"):\r\n        abiertos.append(\"(\")\r\n        cant_p+=1\r\n        LISP(s, abiertos, i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\")\"):\r\n        if(cant_p==0):\r\n            print(\"NO\")\r\n            return\r\n        if(abiertos[len(abiertos)-1]!=\"(\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        cant_p-=1\r\n        LISP(s, abiertos, i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"[\"):\r\n        abiertos.append(\"[\")\r\n        cant_c+=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"]\"):\r\n        if(cant_c==0):\r\n            print(\"NO\")\r\n            return\r\n        if(abiertos[len(abiertos)-1]!=\"[\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        cant_c-=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"{\"):\r\n        abiertos.append(\"{\")\r\n        cant_l+=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"}\"):\r\n        if(cant_l==0):\r\n            print(\"NO\")\r\n            return\r\n        if(abiertos[len(abiertos)-1]!=\"{\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        cant_l-=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n\r\ns = input()\r\nLISP(s)',2653),
(2654,'def LISP(s, abiertos = [],i=0,cant_p=0,cant_c=0,cant_l=0):\r\n\r\n    if(i==len(s)):\r\n        if(cant_p ==0 and cant_c == 0 and cant_l==0):\r\n            print(\"SI\")\r\n            return\r\n        print(\"NO\")\r\n        return\r\n    \r\n    if(s[i]==\"(\"):\r\n        abiertos.append(\"(\")\r\n        cant_p+=1\r\n        LISP(s, abiertos, i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\")\"):\r\n        if(cant_p==0):\r\n            print(\"NO\")\r\n            return\r\n        if(abiertos[len(abiertos)-1]!=\"(\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        cant_p-=1\r\n        LISP(s, abiertos, i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"[\"):\r\n        abiertos.append(\"[\")\r\n        cant_c+=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"]\"):\r\n        if(cant_c==0):\r\n            print(\"NO\")\r\n            return\r\n        if(abiertos[len(abiertos)-1]!=\"[\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        cant_c-=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n\r\n    if(s[i]==\"{\"):\r\n        abiertos.append(\"{\")\r\n        cant_l+=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n    if(s[i]==\"}\"):\r\n        if(cant_l==0):\r\n            print(\"NO\")\r\n            return\r\n        if(abiertos[len(abiertos)-1]!=\"{\"):\r\n            print(\"NO\")\r\n            return\r\n        else:\r\n            abiertos.pop()\r\n        cant_l-=1\r\n        LISP(s,abiertos,i+1,cant_p,cant_c,cant_l)\r\n\r\ns = input()\r\nLISP(s)',2654),
(2655,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n    if vida1>=vida2:\r\n        return print(\"Player 1\")\r\n    else:\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2==vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        else:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1==vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2655),
(2656,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2==vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        else:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1==vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2656),
(2657,'#lip sync\r\narreglo=list(input())\r\nabiertos=[]\r\ncerrados={\"}\",\"]\",\")\"}\r\ndef sincronizacion(indice,n,hubo_cerrado):\r\n    # caso especial 1: solo un elemento\r\n    if len(arreglo)==1:\r\n        return \"NO\"\r\n    # caso base: fin de lista\r\n    if indice==(n-1):\r\n        if hubo_cerrado==\"no\":\r\n            return \"NO\"\r\n        return \"SI\"\r\n    # si aparece un cerrado...\r\n    if arreglo[indice] in cerrados:\r\n        if len(abiertos)==0: # caso )\r\n            return \"NO\"\r\n        if arreglo[indice]==\"}\":\r\n            if abiertos[-1]!=\"{\":\r\n                return \"NO\"\r\n        if arreglo[indice]==\")\":\r\n            if abiertos[-1]!=\"(\":\r\n                return \"NO\"\r\n        if arreglo[indice]==\"]\":\r\n            if abiertos[-1]!=\"[\":\r\n                return \"NO\"\r\n        # si el cerrado coincide\r\n        del abiertos[-1]\r\n        return sincronizacion(indice+1,n,\"si\")\r\n    # añadir a la lista de abiertos\r\n    abiertos.append(arreglo[indice])\r\n    return sincronizacion(indice+1,n,hubo_cerrado)\r\nresultado=sincronizacion(0,len(arreglo),\"no\")\r\nprint(resultado)',2657),
(2658,'def vuelto(monedas,tope,i=0,j=0):\r\n    if tope != j:\r\n        if monedas[0] <= tope-j:\r\n            return vuelto(monedas,tope,i+1,j+monedas[0])\r\n        else:\r\n            if i != 0:\r\n                print(f\"{monedas[0]}x{i}\")\r\n            else:\r\n                pass\r\n            monedas.remove(monedas[0])\r\n            return vuelto(monedas,tope,i=0,j=j)\r\n    else:\r\n        print(f\"{monedas[0]}x{i}\")\r\n        return SyntaxError\r\nm,n = map(int,input().split())\r\nlista = list(map(int,input().split()))\r\nvuelto(lista,n)',2658),
(2659,'def codigo(vida1,f1,vida2,f2,contador=0):\r\n    if vida1>=vida2:\r\n        return print(\"Player 1\")\r\n    else:\r\n        if contador==0:\r\n            if vida2-vida1*f1<=0:\r\n                return print(\"Player 1\")\r\n            else:\r\n                vida2=vida2-vida1*f1\r\n                return codigo(vida1,f1,vida2,f2,contador+1)\r\n        else:\r\n            if vida1-vida2*f2<=0:\r\n                return print(\"Player 2\")\r\n            else:\r\n                vida1=vida1-vida2*f2\r\n                return codigo(vida1,f1,vida2,f2,contador-1)\r\n            \r\n            \r\nvida1,f1,vida2,f2= map(int,input().split())\r\ncodigo(vida1,f1,vida2,f2,0)',2659),
(2660,'def ima(HP1, F1, HP2, F2, t):\r\n    if HP1 * F1 >= HP2:\r\n        resultado = f\"Player {int(2-(t-1)%2)}\"\r\n        return resultado\r\n    HP2 = HP2 - (HP1*F1)\r\n    siguiente = ima(HP2, F2, HP1, F1, t+1)\r\n    return siguiente\r\na, b, c, d = map(int, input().split())\r\nprint(ima(a, b, c, d, 0))',2660),
(2661,'def balanceado(expresion):\r\n    pila = []\r\n    pares = {\')\': \'(\', \'}\': \'{\', \']\': \'[\'}\r\n\r\n    for c in expresion:\r\n        if c in \"({[\":\r\n            pila.append(c)\r\n        elif c in \")}]\":\r\n            if not pila or pila[-1] != pares[c]:\r\n                return \"NO\"\r\n            pila.pop()\r\n    return \"SI\" if not pila else \"NO\"\r\n    \r\nexp = input().strip()\r\nprint(balanceado(exp))',2661),
(2662,'def vuelto(m , A, t):\r\n    if m%A[t] == 0:\r\n        resultado = f\"{A[t]}x{int(m/A[t])}\"\r\n        return resultado\r\n    resto = m%A[t]\r\n    if m > A[t]:\r\n        print(f\"{A[t]}x{int(m/A[t])}\")\r\n    siguiente = vuelto(resto, A, t+1)\r\n    return siguiente\r\nn, m = map(int, input().split())\r\nA = list(map(int, input().split()))\r\nprint(vuelto(m, A, 0))',2662),
(2663,'a,b=map(int,input().split())\r\nA=input().split()\r\nc=0\r\ndef vue(y,Z,x):\r\n    if y==0:\r\n        return\r\n    if int(y/int(Z[x]))!=0:\r\n        print(f\'{int(Z[x])}x{int(y/int(Z[x]))}\')\r\n    return vue(y-int(Z[x])*int(y/int(Z[x])),Z,x+1)\r\nvue(b,A,c)',2663),
(2664,'s = input()\r\npila = []\r\n\r\nfor i in s:\r\n    if s == \"(\" or s == \"[\" or s == \"{\":\r\n        pila = pila + [s]\r\n    else:\r\n        if len(pila) == 0:\r\n            print(\"NO\")\r\n            exit()\r\n            u = pila[-1]\r\n        if (u == \")\" and u == \"(\") or (u == \"]\" and u == \"[\") or (u == \"}\" and u == \"{\"):\r\n            pila = pila[::-1]\r\n        else:\r\n            print(\"NO\")\r\n            exit()\r\n\r\nif len(pila) == 0:\r\n    print(\"NO\")\r\nelse:\r\n    print(\"SI\")',2664),
(2665,'def par(str):\r\n    if str != \"\":\r\n        if \"()\" in str:\r\n            str = str.replace(\"()\",\"\",1)\r\n            return par(str)\r\n        elif \"[]\" in str:\r\n            str = str.replace(\"[]\",\"\",1)\r\n            return par(str)\r\n        elif \"{}\" in str:\r\n            str = str.replace(\"{}\",\"\",1)\r\n            return par(str)\r\n        else:\r\n            return \"NO\"\r\n    else:\r\n        return \"SI\"\r\na = input()\r\na = str(a)\r\nprint(par(a))',2665),
(2666,'def xd():\r\n    cadena = input()\r\n    pila = []\r\n    for S in cadena:\r\n        if S == \"(\" or S == \"[\" or S == \"{\":\r\n            pila = pila + [S]\r\n        else:\r\n            if len(pila) == 0:\r\n                print(\"NO\")\r\n                return\r\n            u = pila[-1]\r\n            if (S == \")\" and u == \"(\") or (S == \"]\" and u == \"[\") or (S == \"}\" and u == \"{\"):\r\n                pila = pila[:-1]\r\n            else:\r\n                print(\"NO\")\r\n                return\r\n    if len(pila) == 0:\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")\r\n\r\nxd()',2666),
(2667,'# Aislamiento post terremoto\r\nn,m=map(int,input().split())\r\nmatriz_adjacencia=[[0 for i in range (n)] for j in range(n)]\r\nvecinos={}\r\nfor vertice in range(1,n+1):\r\n	vecinos[vertice]=[]\r\nfor k in range(m):\r\n	a,b=map(int,input().split())\r\n	matriz_adjacencia[a-1][b-1]=1\r\n	matriz_adjacencia[b-1][a-1]=1\r\n	vecinos[a].append(b)\r\n	vecinos[b].append(a)\r\nvisitados=[False]*n\r\ndef DFS(vertice):\r\n	if visitados[vertice-1]==False:\r\n		visitados[vertice-1]=True\r\n		for vecino in vecinos[vertice]:\r\n			DFS(vecino)\r\n	return\r\nDFS(1)\r\naislados=[]\r\nindice=1\r\nfor item in visitados:\r\n	if item==False:\r\n		aislados.append(indice)\r\n	indice+=1\r\nprint(*aislados)',2667),
(2668,'while True:\r\n    a = int(input())\r\n    \r\n    if a == 0:\r\n        break\r\n    \r\n    if a % 3 == 0 and a % 5 == 0:\r\n        print(\'MÚLTIPLO DE AMBOS\')\r\n    elif a % 3 == 0:\r\n        print(\'MÚLTIPLO DE 3\')\r\n    elif a % 5 == 0:\r\n        print(\'MÚLTIPLO DE 5\')\r\n    else:\r\n        print(\'NO ES MÚLTIPLO DE 3 NI DE 5\')',2668),
