(2670,'n, m = map(int, input().split())\r\n\r\nadj = [[] for _ in range(n+1)]\r\n\r\nfor i in range(m):\r\n    a, b = map(int, input().split())\r\n    adj[a].append(b)\r\n    adj[b].append(a)\r\n\r\nvisitados = set()\r\nvisitados.add(1)\r\ncola = [2]\r\n\r\nwhile cola:\r\n    u = cola.pop(0)\r\n    if u in visitados:\r\n        continue\r\n    visitados.add(u)\r\n    for v in adj[u]:\r\n        if v not in visitados:\r\n            cola.append(v)\r\n\r\naislados = [i for i in range(1, n+1) if i not in visitados]\r\nprint(*aislados)',2670),
(2671,'n, m = map(int, input().split())\r\n\r\nadj = [[] for _ in range(n+1)]\r\n\r\nfor i in range(m):\r\n    a, b = map(int, input().split())\r\n    adj[a].append(b)\r\n    adj[b].append(a)\r\n\r\nvisitados = set()\r\nvisitados.add(1)\r\ncola = [1]\r\n\r\nwhile cola:\r\n    u = cola.pop(0)\r\n    if u in visitados and u != 1:\r\n        continue\r\n    visitados.add(u)\r\n    for v in adj[u]:\r\n        if v not in visitados:\r\n            cola.append(v)\r\n\r\naislados = [i for i in range(1, n+1) if i not in visitados]\r\nprint(*aislados)',2671),
(2672,'n, m = map(int, input().split())\r\n\r\nadj = [[] for _ in range(n+1)]\r\n\r\nfor i in range(m):\r\n    a, b = map(int, input().split())\r\n    adj[a].append(b)\r\n    adj[b].append(a)\r\n\r\nT = int(input())\r\nfor i in range(T):\r\n    conex = True\r\n    t = int(input())\r\n    ruta = list(map(int, input().split()))\r\n    for j in range(t-1):\r\n        if ruta[j] not in adj[ruta[j+1]]:\r\n            conex = False\r\n    if conex == False:\r\n        print(\"NO\")\r\n    else:\r\n        print(\"SI\")',2672),
