(2677,'#Ayuda Post Terremoto\r\nn,m=map(int,input().split())\r\nlista_adyacencia={}\r\nfor i in range(1,n+1):\r\n	lista_adyacencia[i]=set()\r\nfor j in range(m):\r\n	a,b=map(int,input().split())\r\n	lista_adyacencia[a].add(b)\r\n	lista_adyacencia[b].add(a)\r\nt=int(input()) # rutas a probar (subgrafo)\r\nfor k in range(t):\r\n	sub_lista={}\r\n	l=int(input())\r\n	ciudades=set(map(int,input().split()))\r\n	for vertice in ciudades:\r\n		sub_lista[vertice]=ciudades.intersection(lista_adyacencia[vertice])\r\n	visitados=[False]*n\r\n	def DFS(vertice):\r\n		if visitados[vertice-1]==False:\r\n			visitados[vertice-1]=True\r\n			for vecino in sub_lista[vertice]:\r\n				DFS(vecino)\r\n		return\r\n	DFS(ciudades.pop())\r\n	if visitados.count(True)==l:\r\n		print(\"SI\")\r\n	else:\r\n		print(\"NO\")',2677),
