(2681,'ady = [[] for _ in range(n+1)]\r\nfor i in range(m):\r\n    a,b = map(int,input().split())\r\n    ady[a].append(b)\r\n    ady[b].append(a)\r\n\r\nvisitado = [False]*(n+1)\r\ndef dfs(u):\r\n    visitado[u]=True\r\n    for v in ady[u]:\r\n        if visitado[v]==False:\r\n            dfs(v)\r\n\r\ndfs(1)\r\nfinal = []\r\nfor i in range(1,n+1):\r\n    if(visitado[i]==False):\r\n        final.append(i)\r\nprint(*final)',2681),
(2682,'n,m = map(int,input().split())\r\n\r\nady = [[] for _ in range(n+1)]\r\nfor i in range(m):\r\n    a,b = map(int,input().split())\r\n    ady[a].append(b)\r\n    ady[b].append(a)\r\n\r\nvisitado = [False]*(n+1)\r\ndef dfs(u):\r\n    visitado[u]=True\r\n    for v in ady[u]:\r\n        if visitado[v]==False:\r\n            dfs(v)\r\n\r\ndfs(1)\r\nfinal = []\r\nfor i in range(1,n+1):\r\n    if(visitado[i]==False):\r\n        final.append(i)\r\nprint(*final)',2682),
(2683,'class Pila:\r\n    def __init__(self, tamaño):\r\n        self.tamaño = tamaño\r\n        self.arreglo = [None] * self.tamaño\r\n        self.altura = 0\r\n        pass\r\n    def apilar(self, elemento):\r\n        if self.altura < self.tamaño:\r\n            self.arreglo[self.altura] = elemento\r\n            self.altura = self.altura +1\r\n            print(F\"Elemento {elemento} fue apilado\")\r\n            return\r\n        raise IndexError(\"La pila esta llena\")\r\n    def __str__(self):\r\n        return f\"{self.arreglo} Altura: {self.altura} Tamaño: {self.tamaño}\"',2683),
(2684,'class Fila:\r\n    def __init__(self, tamaño):\r\n        self.tamaño = tamaño\r\n        self.arreglo = [None]*self.tamaño\r\n        self.largo = 0\r\n        self.cabeza = 0\r\n        self.cola = 0\r\n\r\n    def estaVacia(self):\r\n        if self.largo == 0:\r\n            return True\r\n        return False\r\n    \r\n    def encolar(self, x):\r\n        if self.largo < self.tamaño:\r\n            self.largo +=1\r\n            self.arreglo[self.cola] = x\r\n            self.cola = (self.cola+1) % self.tamaño\r\n\r\n    def desencolar(self):\r\n        if self.largo >0:\r\n            self.largo -=1\r\n            aux = self.arreglo[self.cabeza]\r\n            self.arreglo[self.cabeza] = None\r\n            self.cabeza = (self.cabeza+1) % self.tamaño\r\n            return aux\r\n\r\n    def detalles(self):\r\n        print(f\"\"\"\r\n        cabeza: {self.cabeza}\r\n        cola: {self.cola}\r\n        largo {self.largo}\r\n        \"\"\")\r\n\r\n    def __str__(self):\r\n        return str(self.arreglo)\r\n    \r\n\r\ncola = Fila(10)\r\nprint(cola.estaVacia())\r\ncola.encolar(10)\r\nprint(cola)\r\ncola.desencolar()\r\nprint(cola)\r\ncola.detalles()\r\nfor i in range(5):\r\n    cola.encolar(i)\r\nprint(cola)',2684),
(2685,'#Cursos core\r\nn,m=map(int,input().split())\r\nlista_adyacencia={}\r\nfor j in range(1,n+1):\r\n    lista_adyacencia[j]=set()\r\nfor i in range(m):\r\n    a,b=map(int,input().split())\r\n    lista_adyacencia[b].add(a)\r\n# lista al reves\r\n# quien apunta al b? el a\r\ncursos_core=set()\r\nvisitados=[False]*n\r\ndef DFS(nodo):\r\n    if visitados[nodo-1]==False:\r\n        visitados[nodo-1]=True\r\n        for vecino in lista_adyacencia[nodo]:\r\n            cursos_core.add(vecino)\r\n            DFS(vecino)\r\n    return\r\nDFS(n)\r\nprint(*cursos_core)',2685),
(2686,'class Fila:\r\n    def __init__(self):\r\n        self.tamano = 10\r\n        self.arreglo = [None]*self.tamano\r\n        self.cabeza = 0\r\n        self.cola = 0\r\n        self.largo = 0\r\n    def detalles(self):\r\n        print(f\"cabeza: {self.cabeza}\")\r\n        print(f\"cola: {self.cola}\")\r\n        print(f\"largo: {self.largo}\")\r\n    def __str__(self):\r\n        return str(self.arreglo)\r\n    def estaVacia(self):\r\n        if(self.largo==0):\r\n            return True\r\n        else:\r\n            return False\r\n    def encolar(self,x):\r\n        if(self.largo==self.tamano):\r\n            raise IndexError(\"La cola esta llena\")\r\n        self.largo +=1\r\n        self.arreglo[self.cola]=x\r\n        self.cola = (self.cola+1)%self.tamano\r\n    def desencolar(self):\r\n        if self.largo>0:\r\n            self.largo -=1\r\n            aux = self.arreglo[self.cabeza]\r\n            self.arreglo[self.cabeza]= None\r\n            self.cabeza +=1\r\n            return aux\r\n        else:\r\n            raise IndexError(\"La fila esta vacia\")\r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\nclass Nodo:\r\n    def __init__(self,dato):\r\n        self.dato = dato\r\n        self.siguiente = None\r\n    def __str__(self):\r\n        return str(self.dato)\r\n    \r\nclass Lista():\r\n    def __init__(self):\r\n        self.cabeza = None\r\n    def __str__(self):\r\n        if self.cabeza != None:\r\n            return str(self.cabeza) + \" \" + str(self.cabeza.siguiente)\r\n    def agregarInicio(self,x):\r\n        nuevoNodo = Nodo(x)\r\n        if self.cabeza == None:\r\n            self.cabeza = nuevoNodo\r\n        else:\r\n            nuevoNodo.siguiente = self.cabeza\r\n            self.cabeza = nuevoNodo',2686),
(2687,'n,m = map(int,input().split())\r\nady = [[] for _ in range(n)]\r\nfor i in range(m):\r\n    a,b = map(int,input().split())\r\n    ady[a].append(b)\r\n    ady[b].append(a)\r\n\r\nvisitados = [False]*n\r\ncant_islas = 0\r\n\r\ndef dfs(x):\r\n    visitados[x]=True\r\n    for v in ady[x]:\r\n        if(visitados[v]==False):\r\n            dfs(v)\r\n\r\nfor i in range(n):\r\n    if visitados[i]==False:\r\n        cant_islas+=1\r\n        dfs(i)\r\n\r\nprint(cant_islas-1)',2687),
(2688,'n, m = map(int, input().split())\r\n\r\nadj = [[] for _ in range(n+1)]\r\n\r\nfor i in range(m):\r\n    a, b = map(int, input().split())\r\n    adj[b].append(a)\r\n\r\nT = len(adj[n])\r\n\r\nvisitados= set()\r\ncola = [n]\r\n\r\nwhile cola:\r\n    u = cola.pop(0)\r\n    if u in visitados:\r\n        continue\r\n    if u != n:\r\n        visitados.add(u) \r\n    for v in adj[u]:\r\n        if v not in visitados:\r\n            cola.append(v)\r\nprint(*visitados)',2688),
(2689,'n,m = map(int,input().split())\r\nady = [[] for _ in range(n+1)]\r\nfor i in range(m):\r\n    a,b = map(int,input().split())\r\n    ady[b].append(a)\r\nvisitados = [False]*(n+1)\r\ndef dfs(u):\r\n    visitados[u]=True\r\n    for i in ady[u]:\r\n        if visitados[i]==False:\r\n            dfs(i)\r\ndfs(n)\r\nfinal = []\r\nfor i in range(1,n):\r\n    if(visitados[i]):\r\n        final.append(i)\r\nprint(*final)',2689),
(2690,'class Nodo:\r\n    def __init__(self,dato):\r\n        self.dato = dato\r\n        self.siguiente = None\r\n    def __str__(self):\r\n        return str(self.dato)\r\n    \r\nclass Lista():\r\n    def __init__(self):\r\n        self.cabeza = None\r\n\r\n    def agregar_inicio(self,x):\r\n        nuevoNodo = Nodo(x)\r\n        if self.cabeza == None:\r\n            self.cabeza = nuevoNodo\r\n        else:\r\n            nuevoNodo.siguiente = self.cabeza\r\n            self.cabeza = nuevoNodo\r\n    \r\n    \r\n    def obtener_ultimo_nodo(self):\r\n        if self.cabeza == None:\r\n            raise IndexError(\"Lista Vacia\")\r\n        actual = self.cabeza\r\n        while actual.siguiente != None:\r\n            actual = actual.siguiente\r\n        return actual\r\n    \r\n    def obtener_ultimo_valor(self):\r\n        return self.obtener_ultimo_nodo().dato        \r\n\r\n    def agregar_final(self,x):\r\n        nuevoNodo = Nodo(x)\r\n        if(self.cabeza == None):\r\n            self.cabeza = nuevoNodo\r\n        else:\r\n            self.obtener_ultimo_nodo().siguiente = nuevoNodo\r\n    \r\n    def buscarValor(self,x):\r\n        if self.cabeza == None:\r\n            return False\r\n        actual = self.cabeza\r\n        if actual ==x:\r\n            return True\r\n        while actual.siguiente != None:\r\n            actual = actual.siguiente\r\n            if actual.dato==x:\r\n                return True            \r\n        return False\r\n\r\n    def eliminarValor(self,x):\r\n        \"\"\"\r\n        Quitatodos losnodos devalor x.\r\n        \"\"\"\r\n        pass\r\n    def BuscaIndice(self,x):\r\n        \"\"\"\r\n        Entrega el indice de la primera ocurriencia de x.\r\n        \"\"\"\r\n        pass\r\n    def largo(self):\r\n        \"\"\"\r\n        Entrega el número de nodos dela lista.\r\n        \"\"\"\r\n        pass\r\n\r\n    def __str__(self):\r\n        if self.cabeza == None:\r\n            return \"Lista Vacia\"\r\n        actual = self.cabeza\r\n        cadena = f\'{actual.dato}\'\r\n        while actual.siguiente != None:\r\n            actual = actual.siguiente\r\n            cadena = cadena + f\'->{actual.dato}\'\r\n        return(cadena)\r\n\r\nL = Lista()\r\nprint(L)\r\nL.agregar_inicio(10)\r\nL.agregar_inicio(20)\r\nL.agregar_inicio(30)\r\nL.agregar_inicio(40)\r\nprint(L)\r\nL.agregar_final(-10)\r\nprint(L)\r\n\r\nx1 = L.buscarValor(10)\r\nx2 = L.buscarValor(-100)\r\nprint(x1,x2)',2690),
(2691,'class NodoArbol():\r\n    def __init__(self, dato):\r\n        self.dato = dato\r\n        self.izq = None\r\n        self.der = None\r\n    \r\n    def __str__(self):\r\n        return \"Dato:\" + str(self.dato)\r\n\r\nclass ArbolBinario():\r\n    def __init__(self):\r\n        self.raiz = None\r\n    \r\n    def agregarRaiz(self, x):\r\n        if self.raiz == None:\r\n            self.raiz = NodoArbol(x)\r\n    \r\n    def agregarIzquierda(self, x):\r\n        if self.raiz == None:\r\n            self.raiz = NodoArbol(x)\r\n        actual = self.raiz\r\n        while actual.izq != None:\r\n            actual = actual.izq\r\n        actual.izq = NodoArbol(x)\r\n\r\n    def recorrerIzquierda(self):\r\n        if self.raiz == None:\r\n            print(\"El arbol esta vacio\")\r\n            return\r\n        actual = self.raiz\r\n        cadena = str(actual.dato)\r\n        while actual.izq != None:\r\n            actual = actual.izq\r\n            cadena = cadena + \"->\" + str(actual.dato)\r\n        print(cadena)\r\n        return \r\n\r\n    def agregarDerecha(self, x):\r\n        if self.raiz == None:\r\n            self.raiz = NodoArbol(x)\r\n        actual = self.raiz\r\n        while actual.der != None:\r\n            actual = actual.der\r\n        actual.der = NodoArbol(x)\r\n\r\n    def recorrerDerecha(self):\r\n        if self.raiz == None:\r\n            print(\"El arbol esta vacio\")\r\n            return\r\n        actual = self.raiz\r\n        cadena = str(actual.dato)\r\n        while actual.der != None:\r\n            actual = actual.der\r\n            cadena = cadena + \"->\" + str(actual.dato)\r\n        print(cadena)\r\n        return \r\n\r\n    def buscarDato(self, x):\r\n        if self.raiz == None:\r\n            raise IndentationError(\"Arbol vacio\")\r\n        if self.buscar(self.raiz, x):\r\n            return True\r\n        return False\r\n    \r\n    def buscar(self, nodo, x):\r\n        if nodo.dato == x:\r\n            return True\r\n        if nodo.izq != None:\r\n            if self.buscar(nodo.izq, x):\r\n                return True\r\n        if nodo.der != None:\r\n            if self.buscar(nodo.der, x):\r\n                return True\r\n\r\n    def __str__(self):\r\n        if self.raiz == None:\r\n            return \"El arbol esta vacio\"\r\n        return f\"Raiz: {self.raiz.dato}\"\r\n    \r\n    \r\n\r\nT = ArbolBinario()\r\nT.agregarRaiz(0)\r\nprint(T)\r\n\r\nT.agregarIzquierda(-10)\r\nT.agregarIzquierda(-20)\r\nT.agregarIzquierda(-30)\r\n\r\nT.agregarDerecha(10)\r\nT.agregarDerecha(20)\r\nT.agregarDerecha(30)\r\n\r\nT.recorrerIzquierda()\r\nT.recorrerDerecha()',2691),
(2692,'import sys\r\n\r\nsys.stdin = open(f\"entrada.txt\", \"r\")\r\nsys.stdout = open(f\"salida.txt\", \"w\")\r\n\r\n###################################\r\n\r\nclass NodoArbol():\r\n    def __init__(self,dato):\r\n        self.dato = dato\r\n        self.izq = None # Puntero al hijo izq\r\n        self.der = None # Puntero al hijo der\r\n    def __str__(self):\r\n        return \"Dato:\" + str(self.dato)\r\nclass ArbolBinario:\r\n    def __init__(self):\r\n        self.raiz = None\r\n    def AgregarRaiz(self,x):\r\n        if self.raiz == None:\r\n            self.raiz = NodoArbol(x)\r\n    def AgregarAlExtremoIzquierdo(self,x):\r\n        if self.raiz == None:\r\n            self.raiz = NodoArbol(x)\r\n        actual = self.raiz\r\n        while actual.izq != None:\r\n            actual = actual.izq\r\n        actual.izq = NodoArbol(x)\r\n    def AgregarAlExtremoDerecho(self,x):\r\n        if self.raiz == None:\r\n            self.raiz = NodoArbol(x)\r\n        actual = self.raiz\r\n        while actual.der != None:\r\n            actual = actual.der\r\n        actual.der = NodoArbol(x)\r\n    def recorre_a_la_izq(self):\r\n        if self.raiz == None:\r\n            return \"El arbol esta vacio\"\r\n        actual = self.raiz\r\n        cadena = str(actual.dato)\r\n        while actual.izq != None:\r\n            actual = actual.izq\r\n            cadena = cadena +\"->\"+str(actual.dato)\r\n        return cadena\r\n    def RecorreALaDerecha(self):\r\n        if self.raiz == None:\r\n            return \"El arbol esta vacio\"\r\n        actual = self.raiz\r\n        cadena = str(actual.dato)\r\n        while actual.der != None:\r\n            actual = actual.der\r\n            cadena = cadena +\"->\"+str(actual.dato)\r\n        return cadena\r\n    def BuscarUnDato(self,x):\r\n        if self.raiz == None:\r\n            raise IndentationError(\"Arbol Vacio\")\r\n    def buscar(self,nodo,x):\r\n        if nodo.dato == x:\r\n            return True\r\n        if nodo.izq != None:\r\n            self.buscar(nodo.izq,x)\r\n        if nodo.der != None:\r\n            self.buscar(nodo.der,x)\r\n\r\n\r\n\r\n            \r\n        \r\n    def __str__(self):\r\n        if self.raiz == None:\r\n            return \"El árbol está vacío\"\r\n        return f\"Raíz: {self.raiz.dato}\"\r\n    \r\nT = ArbolBinario()\r\nT.AgregarRaiz(10)\r\nT.AgregarAlExtremoIzquierdo(20)\r\nT.AgregarAlExtremoIzquierdo(30)\r\nT.AgregarAlExtremoDerecho(40)\r\nprint(T.recorre_a_la_izq())\r\nprint(T.RecorreALaDerecha())\r\nprint(T)',2692),
