(2701,'# Arqueología azteca\r\nn=int(input())# cantidad de pisos:\r\npirámide=[[] for i in range(n)] # n listas vacias\r\nfor j in range(n): # para cada piso...\r\n    piso=list(map(int,input().split()))\r\n    # primer elemento indica cuantos son (es decir, el piso)\r\n    cantidad=(piso.pop(0)-1)\r\n    pirámide[cantidad]=sorted(piso,reverse=True)\r\nfor piso in pirámide:\r\n    print(*piso)',2701),
(2702,'class Grafo_no_dirigido():\r\n    def __init__(self,n):\r\n        self.n = n\r\n        self.matriz = [[0]*n for _ in range(n)]\r\n    def agregar_arista(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=1\r\n            self.matriz[j][i]=1\r\n            return\r\n        if i==j:\r\n            raise \"No se permiten bucles.\"\r\n        raise IndexError(\"Fuera de límites.\")\r\n    \r\n    def quitar_arista(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=0\r\n            self.matriz[j][i]=0\r\n            return\r\n        if i==j:\r\n            raise \"No se permiten bucles.\"\r\n        raise IndexError(\"Fuera de límites.\")\r\n    def es_adyacente(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=1\r\n            self.matriz[j][i]=1\r\n            return\r\n        if i==j:\r\n            raise \"No se permiten bucles.\"\r\n        return self.matriz[i][j]\r\n    def vecindad(self,v):\r\n        f =self.matriz[v]\r\n        vecinos = []\r\n        for i in range(len(f)):\r\n            if f[i]==1:\r\n                vecinos.append(i)\r\n        return vecinos\r\n    def __str__(self):\r\n        cadena = \'\'\r\n        for f in self.matriz:\r\n            cadena=cadena+str(f)+\'\\n\'\r\n        return cadena\r\n    \r\nn = int(input())\r\nG = Grafo_no_dirigido(n)\r\nequipo = []\r\ncant_vecinos = []\r\nfor i in range(n):\r\n    x = list(input().split())\r\n    E = x[0]\r\n    m = int(x[1])\r\n    equipo.append(E)\r\n    cant_vecinos.append(m)\r\n    for j in range(m):\r\n        G.agregar_arista(i,int(x[j+2])-1)\r\ncadena = \"\"\r\nfor i in range(n):\r\n    vecindad = G.vecindad(i)\r\n    mismo_equipo = 0\r\n    for j in vecindad:\r\n        if(equipo[j]==equipo[i]):\r\n            mismo_equipo+=1\r\n    if (mismo_equipo/cant_vecinos[i]<0.5):\r\n        cadena+=f\"{i+1} \"\r\nprint(cadena)',2702),
(2703,'class Grafo_no_dirigido():\r\n    def __init__(self,n):\r\n        self.n = n\r\n        self.matriz = [[0]*n for _ in range(n)]\r\n    def agregar_arista(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=1\r\n            self.matriz[j][i]=1\r\n            return\r\n        if i==j:\r\n            raise \"No se permiten bucles.\"\r\n        raise IndexError(\"Fuera de límites.\")\r\n    \r\n    def quitar_arista(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=0\r\n            self.matriz[j][i]=0\r\n            return\r\n        if i==j:\r\n            raise \"No se permiten bucles.\"\r\n        raise IndexError(\"Fuera de límites.\")\r\n    def es_adyacente(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=1\r\n            self.matriz[j][i]=1\r\n            return\r\n        if i==j:\r\n            raise \"No se permiten bucles.\"\r\n        return self.matriz[i][j]\r\n    def vecindad(self,v):\r\n        f =self.matriz[v]\r\n        vecinos = []\r\n        for i in range(len(f)):\r\n            if f[i]==1:\r\n                vecinos.append(i)\r\n        return vecinos\r\n    def __str__(self):\r\n        cadena = \'\'\r\n        for f in self.matriz:\r\n            cadena=cadena+str(f)+\'\\n\'\r\n        return cadena\r\n    \r\nn = int(input())\r\nG = Grafo_no_dirigido(n)\r\nequipo = []\r\ncant_vecinos = []\r\nfor i in range(n):\r\n    x = list(input().split())\r\n    E = x[0]\r\n    m = int(x[1])\r\n    equipo.append(E)\r\n    cant_vecinos.append(m)\r\n    for j in range(m):\r\n        G.agregar_arista(i,int(x[j+2])-1)\r\ncadena = \"\"\r\nxx = False\r\nfor i in range(n):\r\n    vecindad = G.vecindad(i)\r\n    mismo_equipo = 0\r\n    for j in vecindad:\r\n        if(equipo[j]==equipo[i]):\r\n            mismo_equipo+=1\r\n    if (mismo_equipo/cant_vecinos[i]<0.5 and not xx):\r\n        cadena+=f\"{i+1}\"\r\n        xx = True\r\n    elif(mismo_equipo/cant_vecinos[i]<0.5):\r\n        cadena+=f\" {i+1}\"\r\nprint(cadena)',2703),
(2704,'# mudanzas en la ciudad futbolistica\r\nclass Grafo:\r\n    def __init__(self,n):\r\n        self.n=n # nodos\r\n        self.lista_ajd=[set() for i in range(n)]\r\n    def añadir_conexion(self,nodo_a,nodo_b):\r\n        self.lista_ajd[nodo_a].add(nodo_b)\r\n        self.lista_ajd[nodo_b].add(nodo_a)\r\nn=int(input())\r\nvecindario=Grafo(n)\r\nequipos=[] # equipo favorito en index\r\nfor i in range(n):\r\n    info_vecindario=list(input().split())\r\n    equipo_fav=info_vecindario.pop(0)\r\n    equipos.append(equipo_fav)\r\n    cantidad_casas=int(info_vecindario.pop(0))\r\n    for j in range(cantidad_casas):\r\n        vecindario.añadir_conexion(i,int(info_vecindario.pop(0))-1)\r\n\r\nvisitados=[False]*n\r\ncasas_mudanza=[] # casas que desean mudarse\r\ndef DFS(nodo):\r\n    if visitados[nodo]==False:\r\n        visitados[nodo]==True\r\n        vecinos_no_coincidentes=0\r\n        cantidad_vecinos=0\r\n        for vecino in vecindario.lista_ajd[nodo]:\r\n            # revisa el equipo de los vecinos\r\n            cantidad_vecinos+=1\r\n            equipo_vecino=equipos[vecino]\r\n            equipo_nodo=equipos[nodo]\r\n            if equipo_vecino!=equipo_nodo:\r\n                vecinos_no_coincidentes+=1\r\n        if vecinos_no_coincidentes>cantidad_vecinos/2:\r\n            casas_mudanza.append(nodo+1)\r\n    return\r\n\r\nfor _ in range(n):\r\n    DFS(_)\r\nprint(*casas_mudanza)',2704),
(2705,'class Grafo_no_dirigido():\r\n    def __init__(self,n):\r\n        self.n = n\r\n        self.matriz = [[0]*n for _ in range(n)]\r\n    def agregar_arista(self,i,j):\r\n        if 0 <= i < self.n and 0<=j < self.n and i!=j:\r\n            self.matriz[i][j]=1\r\n            self.matriz[j][i]=1\r\n    def es_adyacente(self,i,j):\r\n        return self.matriz[i][j]\r\n    def vecindad(self,v):\r\n        f =self.matriz[v]\r\n        vecinos = []\r\n        for i in range(len(f)):\r\n            if f[i]==1:\r\n                vecinos.append(i)\r\n        return vecinos\r\n    def __str__(self):\r\n        cadena = \'\'\r\n        for f in self.matriz:\r\n            cadena=cadena+str(f)+\'\\n\'\r\n        return cadena\r\n    \r\nn = int(input())\r\nG = Grafo_no_dirigido(n)\r\nequipo = []\r\ncant_vecinos = []\r\nfor i in range(n):\r\n    x = input().split()\r\n    E = x[0]\r\n    m = int(x[1])\r\n    equipo.append(E)\r\n    cant_vecinos.append(m)\r\n    for j in x[2:]:\r\n        G.agregar_arista(i,int(j)-1)\r\ncadena = \"\"\r\nxx = False\r\nfor i in range(n):\r\n    vecindad = G.vecindad(i)\r\n    mismo_equipo = 0\r\n    for j in vecindad:\r\n        if(equipo[j]==equipo[i]):\r\n            mismo_equipo+=1\r\n    if (mismo_equipo/cant_vecinos[i]<0.5 and not xx):\r\n        cadena+=f\"{i+1}\"\r\n        xx = True\r\n    elif(mismo_equipo/cant_vecinos[i]<0.5):\r\n        cadena+=f\" {i+1}\"\r\nprint(cadena)',2705),
