(2711,'n = int(input())\r\n\r\nequipos= []\r\nvecinos= []\r\n\r\nfor i in range(n):\r\n    x=input().split()\r\n    letra = x.pop(0)\r\n    l = x.pop(0)\r\n    x=list(map(int,x))\r\n    vecinos.append(x)\r\n    equipos.append(letra)\r\nXP=False\r\nfor i in range(n):\r\n    c_enemigos = 0\r\n    v=vecinos[i]\r\n    e=equipos[i]\r\n    XX=0\r\n    for k in v:\r\n        if equipos[k-1]!=e:\r\n            c_enemigos +=1\r\n            XX+=1\r\n    if c_enemigos/len(v)>0.5 and not XP:\r\n        print(end=f\"{i+1}\")\r\n        XP=True\r\n    elif c_enemigos/len(v)>0.5:\r\n        print(end=\" \"+f\"{i+1}\")',2711),
