(2734,'# Restaurando la red electrica\r\n# n nodos, m conexiones originales, y s conexiones que quedaron\r\nn,m,s=map(int,input().split())\r\n\r\nclass Grafo:\r\n    def __init__(self,nodos):\r\n        self.n=set()\r\n        self.matriz=[[0 for i in range(nodos)] for j in range(nodos)]\r\n    def crear_conexion(self,nodo_a,nodo_b,peso):\r\n        # no dirigido asi que es a ambos lados\r\n        self.matriz[nodo_a][nodo_b]=peso\r\n        self.matriz[nodo_b][nodo_a]=peso\r\n        # añadir nodo a la lista de nodos\r\n        self.n.update([nodo_a,nodo_b])\r\n    def quitar_conexion(self,nodo_a,nodo_b):\r\n        self.matriz[nodo_a][nodo_b]=0\r\n        self.matriz[nodo_b][nodo_a]=0\r\n    def vecindad(self,nodo_a):\r\n        lista_vecindad=[]\r\n        index=0 # que elemento estoy revisando\r\n        for conexion in self.matriz[nodo_a]:\r\n            if conexion!=0:\r\n                lista_vecindad.append({nodo_a,index})\r\n            index+=1\r\n        return lista_vecindad\r\n\r\nred_electrica=Grafo(n)\r\nconexiones_actuales=Grafo(n) # quienes sobrevivieron\r\nfor k in range(m):\r\n    u,v,l=map(int,input().split())\r\n    red_electrica.crear_conexion(u,v,l)\r\n    if k<s:\r\n        conexiones_actuales.crear_conexion(u,v,l)\r\n# esto requiere el algoritmo prim, pero \"ya empezado\"\r\n# pues puede succeder que ya tenemos conexiones ya hechas\r\ndef prim(peso):\r\n    while conexiones_actuales.n!=red_electrica.n:\r\n        nodos_faltantes=red_electrica.n-conexiones_actuales.n\r\n        for nodo in nodos_faltantes:\r\n            # conexiones posibles\r\n            opciones=red_electrica.matriz[nodo]\r\n            # añade el de menor peso\r\n            peso_temp=100000000 # peso \"infinito\"\r\n            conexion_elegida=None # que conexion se eligio\r\n            index_nodo=0 # contador de indice\r\n            for longitud in opciones:\r\n                if index_nodo==nodo:\r\n                    # no se admiten \"bucles\"\r\n                    index_nodo+=1\r\n                    continue\r\n                if longitud<peso_temp and longitud!=0:\r\n                    peso_temp=longitud\r\n                    conexion_elegida=index_nodo\r\n                index_nodo+=1\r\n            if conexion_elegida not in conexiones_actuales.n and len(conexiones_actuales.n)!=0:\r\n                # armaremos el grafo de forma \"conexa\"\r\n                # es decir, no añadiremos nodos que esten al \"aire\" o no conectados\r\n                # a lo que ya se tenga. aunque su peso sea el más pequeño\r\n                continue\r\n            peso+=peso_temp\r\n            conexiones_actuales.n.update([conexion_elegida,nodo])\r\n            # quitar conexion para no repetirla\r\n            red_electrica.quitar_conexion(nodo,conexion_elegida)\r\n            break\r\n    return peso\r\nprint(prim(0))',2734),
(2735,'M, R, E = map(int, input().split())\r\nrutas = {}\r\nfor i in range(M):\r\n    a, b, c = list(input().split())\r\n    c = int(c)\r\n    rutas[a+b] = c\r\nfor i in range(R):\r\n    costo = 0\r\n    hola = list(input().split())\r\n    for j in range(1, len(hola),):\r\n        costo = costo + rutas[hola[j-1]+hola[j]]\r\n    if costo <= E:\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")',2735),
(2736,'M, R, E = map(int, input().split())\r\nrutas = {}\r\nfor i in range(M):\r\n    a, b, c = list(input().split())\r\n    c = int(c)\r\n    rutas[a+b] = c\r\nfor i in range(R):\r\n    costo = 0\r\n    hola = list(input().split())\r\n    coso = True\r\n    x = len(hola)-2\r\n    while coso and x != 0:\r\n        for j in range(1, len(hola)-1):\r\n            x =x-1\r\n            if hola[j-1]+hola[j] in rutas:\r\n                costo = costo + rutas[hola[j-1]+hola[j]]\r\n            else:\r\n                coso = False\r\n    if costo <= E and coso == True:\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")',2736),
(2737,'M, R, E = map(int, input().split())\r\nrutas = {}\r\nfor i in range(M):\r\n    a, b, c = list(input().split())\r\n    c = int(c)\r\n    rutas[a+b] = c\r\nfor i in range(R):\r\n    costo = 0\r\n    hola = list(input().split())\r\n    coso = True\r\n    for j in range(1, len(hola)):\r\n        if hola[j-1]+hola[j] in rutas:\r\n            costo = costo + rutas[hola[j-1]+hola[j]]\r\n        else:\r\n            coso = False\r\n    if costo <= E and coso == True:\r\n        print(\"SI\")\r\n    else:\r\n        print(\"NO\")',2737),
(2738,'class Grafo():\r\n    def __init__(self,tamano,):\r\n        self.tamano = tamano+1\r\n        self.matriz_de_adyacencia = [[0 for _ in range(self.tamano)] for _ in range(self.tamano)]\r\n        self.visitados = [False for _ in range(self.tamano)]\r\n    def agregar(self,x,y):\r\n        self.matriz_de_adyacencia[x][y] = 1\r\n        self.matriz_de_adyacencia[y][x] = 1\r\n    def vecindad(self,i):\r\n        vecinos = []\r\n        fila_i = self.matriz_de_adyacencia[i]\r\n        for j in range(self.tamano):\r\n            if fila_i[j] == 1:\r\n                vecinos.append(j)\r\n        return vecinos\r\n    def DFS(self,v):\r\n        self.visitados[v] = True\r\n        for u in self.vecindad(v):\r\n            if not self.visitados[u]:\r\n                self.DFS(u)\r\n    def componente_conexa(self,v):\r\n        self.visitados = [False for _ in range(self.tamano)]\r\n        self.DFS(v)\r\n        salida=[]\r\n        for v in range(self.tamano):\r\n            if self.visitados[v]:\r\n                salida.append(v)\r\n        return salida\r\n    def __str__(self):\r\n        for i in self.matriz_de_adyacencia:\r\n            print(i)\r\n        return \"\"\r\nn,m = map(int, input().split())\r\nG = Grafo(n)\r\nfor i in range(m):\r\n    a,b = map(int,input().split())\r\n    G.agregar(a,b)\r\na = G.componente_conexa(1)\r\nz = []\r\nfor i in range(1,1+n):\r\n    z.append(i)\r\nfor j in a:\r\n    if j in z:\r\n        z.remove(j)\r\np = \"\"\r\nfor k in z:\r\n    k = str(k)\r\n    k+=\" \"\r\n    p+=k\r\nprint(p)',2738),
(2739,'import random\r\na = [\"Negro\",\"Empate\",\"Blanco\"]\r\nb = input()\r\nv = input()\r\ndc = input()\r\nc = input()\r\nz = int(input())\r\nfor _ in range(z):\r\n    x = input()\r\nprint(random.choice(a))',2739),
