(2742,'class Grafo():\r\n    def __init__(self,tamano):\r\n        self.tamano = tamano+1\r\n        self.matriz_de_adyacencia = [[0 for _ in range(self.tamano)] for _ in range(self.tamano)]\r\n        self.visitados = [False for _ in range(self.tamano)]\r\n    def agregar(self,x,y):\r\n        self.matriz_de_adyacencia[x][y] = 1\r\n        self.matriz_de_adyacencia[y][x] = 1\r\n    def vecindad(self,i):\r\n        vecinos = []\r\n        fila_i = self.matriz_de_adyacencia[i]\r\n        for j in range(self.tamano):\r\n            if fila_i[j] == 1:\r\n                vecinos.append(j)\r\n        return vecinos\r\n    def DFS(self,v):\r\n        self.visitados[v] = True\r\n        for u in self.vecindad(v):\r\n            if not self.visitados[u]:\r\n                self.DFS(u)\r\n    def componente_conexa(self,v):\r\n        self.visitados = [False for _ in range(self.tamano)]\r\n        self.DFS(v)\r\n        salida=[]\r\n        for v in range(self.tamano):\r\n            if self.visitados[v]:\r\n                salida.append(v)\r\n        return salida\r\n    def __str__(self):\r\n        for i in self.matriz_de_adyacencia:\r\n            print(i)\r\n        return \"\"\r\n    \r\nn,m = map(int,input().split())\r\nG = Grafo(n)\r\nfor _ in range(m):\r\n    a,b = map(int,input().split())\r\n    G.agregar(a,b)\r\nz = [a for a in range(0,n+1)]\r\nk = -2\r\nfor i in range(n+1):\r\n    if i in z:\r\n        a = G.componente_conexa(i)\r\n        k+=1\r\n        for j in a:\r\n            if j in z:\r\n                z.remove(j)\r\nprint(k)',2742),
(2743,'class Grafo():\r\n    def __init__(self,tamano):\r\n        self.tamano = tamano+1\r\n        self.matriz_de_adyacencia = [[0 for _ in range(self.tamano)] for _ in range(self.tamano)]\r\n        self.visitados = [False for _ in range(self.tamano)]\r\n    def agregar(self,x,y):\r\n        self.matriz_de_adyacencia[x][y] = 1\r\n    def vecindad(self,i):\r\n        vecinos = []\r\n        fila_i = self.matriz_de_adyacencia[i]\r\n        for j in range(self.tamano):\r\n            if fila_i[j] == 1:\r\n                vecinos.append(j)\r\n        return vecinos\r\n    def DFS(self,v):\r\n        self.visitados[v] = True\r\n        for u in self.vecindad(v):\r\n            if not self.visitados[u]:\r\n                self.DFS(u)\r\n    def componente_conexa(self,v):\r\n        self.visitados = [False for _ in range(self.tamano)]\r\n        self.DFS(v)\r\n        salida=[]\r\n        for v in range(self.tamano):\r\n            if self.visitados[v]:\r\n                salida.append(v)\r\n        return salida\r\n    def __str__(self):\r\n        for i in self.matriz_de_adyacencia:\r\n            print(i)\r\n        return \"\"\r\nn,m = map(int,input().split())\r\nG = Grafo(n)\r\nfor _ in range(m):\r\n    a,b = map(int,input().split())\r\n    G.agregar(a,b)\r\nmatriz = []\r\nfor i in range(n):\r\n    matriz.append(G.componente_conexa(i))\r\nlista = []\r\nfor j in range(n):\r\n    if n in matriz[j]:\r\n        lista.append(j)\r\nprint(*lista)',2743),
(2744,'n,m=map(int,input().split())\r\nhangar=[[\"\" for i in range(m)] for j in range(n)]\r\nfor fila in range(n):\r\n	hangar[fila]=list(input())\r\nfor _ in range(1,m+1):\r\n	contador=(n-1)\r\n	for k in range(n-1,-1,-1):\r\n		if hangar[k][_]!=\" \":\r\n			hangar[contador][_]=hangar[k][_]\r\n			hangar[k][_]=\" \"\r\n			contador=contador-1\r\nfor a in range(n):\r\n	pila=\"\".join(hangar[a])\r\n	print(pila)',2744),
(2745,'n,m=map(int,input().split())\r\nhangar=[[\"\" for i in range(m)] for j in range(n)]\r\nfor fila in range(n):\r\n	hangar[fila]=list(input())[1:m+1]\r\nfor _ in range(m):\r\n	contador=(n-1)\r\n	for k in range(n-1,-1,-1):\r\n		if hangar[k][_]!=\" \":\r\n			hangar[contador][_]=hangar[k][_]\r\n			hangar[k][_]=\" \"\r\n			contador=contador-1\r\nfor a in range(n):\r\n	pila=\"\".join(hangar[a])\r\n	print(\"|\"+pila+\"|\")',2745),
(2746,'n,m=map(int,input().split())\r\nhangar=[[\"\" for i in range(m)] for j in range(n)]\r\nfor fila in range(n):\r\n	hangar[fila]=list(input())[1:m+1]\r\nfor _ in range(m):\r\n	contador=(n-1)\r\n	for k in range(n-1,-1,-1):\r\n		if hangar[k][_]!=\" \":\r\n			hangar[contador][_]=hangar[k][_]\r\n			if k!=contador:\r\n				hangar[k][_]=\" \"\r\n			contador=contador-1\r\nfor a in range(n):\r\n	pila=\"\".join(hangar[a])\r\n	print(\"|\"+pila+\"|\")',2746),
(2747,'import matplotlib.pyplot as plt\r\nfrom sklearn.preprocessing import StandardScaler\r\nfrom sklearn.cluster import KMeans\r\n\r\ndatos = []\r\n\r\nwith open(\"datos_agrupamiento.csv\", \"r\") as f:\r\n    lineas = f.read().splitlines()\r\n    lineas.pop(0)\r\n    for linea in lineas:\r\n        x, y, z = linea.split(\",\")\r\n        x = float(x)\r\n        y = float(y)\r\n        A = (x, y)\r\n        datos.append(A)\r\n\r\nx = [dato[0] for dato in datos]\r\ny = [dato[1] for dato in datos]\r\n\r\nscaler = StandardScaler()\r\ndatos_standard = scaler.fit_transform(datos)\r\n\r\nxs = [dato[0] for dato in datos_standard]\r\nys = [dato[1] for dato in datos_standard]\r\n\r\nfig, axes = plt.subplots(1, 2, figsize=(8, 3))\r\naxes[0].scatter(x, y)\r\naxes[1].scatter(xs, ys)\r\nplt.show()\r\n\r\nmodelo = KMeans(\r\nn_clusters=4,\r\nrandom_state=42,\r\nn_init=\"auto\"\r\n)\r\n\r\netiquetas = list(modelo.fit_predict(datos_standard))\r\nprint(etiquetas)\r\nprint(modelo.cluster_centers_)\r\nprint(modelo.inertia_)',2747),
(2748,'#KMeans\r\n\r\nimport matplotlib.pyplot as plt\r\nfrom sklearn.cluster import KMeans\r\ninercias = []\r\nfor k in range(1, 9):\r\n    modelo = KMeans(n_clusters=k,random_state=42)\r\n    modelo.fit(datos_standard)\r\n    inercias.append(modelo.inertia_)\r\n    print(inercias)\r\n    valores_k = list(range(1, 9))\r\n\r\nplt.plot(valores_k, inercias, marker=\"o\")\r\nplt.xlabel(\"Número de clusters K\")\r\nplt.ylabel(\"Inercia\")\r\nplt.title(\"Método del codo\")\r\nplt.grid(True)\r\nplt.show()',2748),
(2749,'from sklearn.cluster import DBSCAN\r\nimport matplotlib.pyplot as plt\r\nfrom sklearn.preprocessing import StandardScaler\r\nfrom sklearn.metrics import silhouette_score\r\nfrom sklearn.metrics import davies_bouldin_score\r\ndatos = []\r\n\r\nwith open(\"datos_agrupamiento.csv\", \"r\") as f:\r\n    lineas = f.read().splitlines()\r\n    lineas.pop(0)\r\n    for linea in lineas:\r\n        x, y, z = linea.split(\",\")\r\n        x = float(x)\r\n        y = float(y)\r\n        A = (x, y)\r\n        datos.append(A)\r\n\r\nx = [dato[0] for dato in datos]\r\ny = [dato[1] for dato in datos]\r\n\r\nscaler = StandardScaler()\r\ndatos_standard = scaler.fit_transform(datos)\r\n\r\nxs = [dato[0] for dato in datos_standard]\r\nys = [dato[1] for dato in datos_standard]\r\n\r\nmodelo_dbscan = DBSCAN(\r\neps=0.25,\r\nmin_samples=4\r\n)\r\netiquetas_dbscan = list(modelo_dbscan.fit_predict(datos_standard))\r\nprint(etiquetas_dbscan)\r\nprint(set(etiquetas_dbscan))\r\n\r\nsin_atipicos = []\r\netiquetas_filtradas = []\r\nfor i in range(len(datos_standard)):\r\n if etiquetas_dbscan[i] != -1:\r\n  sin_atipicos.append(datos_standard[i])\r\n  etiquetas_filtradas.append(etiquetas_dbscan[i])\r\n\r\nn_etiquetas= len(set(etiquetas_filtradas))\r\n\r\nif n_etiquetas >1:\r\n sil = silhouette_score(sin_atipicos, etiquetas_filtradas)\r\n db = davies_bouldin_score(sin_atipicos, etiquetas_filtradas)\r\n print(\"Clases no ruido:\",n_etiquetas)\r\n print(\"Silhouette Score:\", sil)\r\n print(\"Davies-Bouldin Index:\", db)\r\nelse:\r\n print(\"No hay suficientes clusters para evaluar.\")\r\n\r\nxss = [dato[0] for dato in datos_standard]\r\nyss = [dato[1] for dato in datos_standard]\r\n\r\nplt.scatter(xss, yss, c=etiquetas_dbscan)\r\nplt.xlabel(\"Variable 1\")\r\nplt.ylabel(\"Variable 2\")\r\nplt.title(\"Clusters obtenidos con DBSCAN\")\r\nplt.grid(True)\r\nplt.show()',2749),
(2750,'from sklearn.cluster import DBSCAN\r\nimport matplotlib.pyplot as plt\r\nfrom sklearn.preprocessing import StandardScaler\r\ndatos = []\r\n\r\nwith open(\"datos_agrupamiento.csv\", \"r\") as f:\r\n    lineas = f.read().splitlines()\r\n    lineas.pop(0)\r\n    for linea in lineas:\r\n        x, y, z = linea.split(\",\")\r\n        x = float(x)\r\n        y = float(y)\r\n        A = (x, y)\r\n        datos.append(A)\r\n\r\nx = [dato[0] for dato in datos]\r\ny = [dato[1] for dato in datos]\r\n\r\nscaler = StandardScaler()\r\ndatos_standard = scaler.fit_transform(datos)\r\n\r\nxs = [dato[0] for dato in datos_standard]\r\nys = [dato[1] for dato in datos_standard]\r\n\r\nmodelo_dbscan = DBSCAN(\r\neps=0.25,\r\nmin_samples=4\r\n)\r\netiquetas_dbscan = list(modelo_dbscan.fit_predict(datos_standard))\r\nprint(etiquetas_dbscan)\r\nprint(set(etiquetas_dbscan))\r\n\r\n\r\nplt.scatter(xs, ys, c=etiquetas_dbscan)\r\nplt.xlabel(\"Variable 1\")\r\nplt.ylabel(\"Variable 2\")\r\nplt.title(\"Clusters obtenidos con DBSCAN\")\r\nplt.grid(True)\r\nplt.show()',2750),
(2751,'import matplotlib.pyplot as plt\r\nfrom sklearn.preprocessing import StandardScaler\r\nfrom sklearn.cluster import DBSCAN\r\nfrom  sklearn.metrics import silhouette_score\r\nfrom sklearn.metrics import davies_bouldin_score\r\n\r\ndatos = []\r\n\r\nwith open(\"datos_agrupamiento.csv\", \"r\") as f:\r\n    lineas = f.read().splitlines()\r\n    lineas.pop(0)\r\n    for linea in lineas:\r\n        x, y, z = linea.split(\",\")\r\n        x = float(x)\r\n        y = float(y)\r\n        A = (x, y)\r\n        datos.append(A)\r\n\r\nx = [dato[0] for dato in datos]\r\ny = [dato[1] for dato in datos]\r\n\r\nscaler = StandardScaler()\r\ndatos_standard = scaler.fit_transform(datos)\r\n\r\nxs = [dato[0] for dato in datos_standard]\r\nys = [dato[1] for dato in datos_standard]\r\n\r\nmodelo_dbscan = DBSCAN(\r\n    eps = 0.25,\r\n    min_samples=4\r\n)\r\netiquetas_dbscan = list(modelo_dbscan.fit_predict(datos_standard))\r\n\r\nprint(etiquetas_dbscan)\r\nprint(set(etiquetas_dbscan))\r\n\r\n\r\n\r\nsin_atipicos = []\r\netiquetas_filtradas = []\r\nfor i in range(len(datos_standard)):\r\n    if etiquetas_dbscan[i] != -1:\r\n        sin_atipicos.append(datos_standard[i])\r\n        etiquetas_filtradas.append(etiquetas_dbscan[i])\r\n\r\nn_etiquetas= len(set(etiquetas_filtradas))\r\n\r\nif n_etiquetas >1:\r\n    sil = silhouette_score(sin_atipicos, etiquetas_filtradas)\r\n    db = davies_bouldin_score(sin_atipicos, etiquetas_filtradas)\r\n    print(\"Clases no ruido:\",n_etiquetas)\r\n    print(\"Silhouette Score:\", sil)\r\n    print(\"Davies-Bouldin Index:\", db)\r\nelse:\r\n    print(\"No hay suficientes clusters para evaluar.\")\r\n\r\ndatosb = []\r\nfor i in range(len(datos_standard)):\r\n    if etiquetas_dbscan[i] != -1:\r\n        datosb.append(datos_standard[i])\r\n\r\nxsa = [dato[0] for dato in datosb]\r\nysa = [dato[1] for dato in datosb]\r\n\r\netiquetas_dbscan = list(modelo_dbscan.fit_predict(datosb))\r\n                        \r\nplt.scatter(xsa, ysa, c=etiquetas_dbscan)\r\nplt.xlabel(\"Variable 1\")\r\nplt.ylabel(\"Variable 2\")\r\nplt.title(\"Clusters obtenidos con DBSCAN\")\r\nplt.grid(True)\r\nplt.show()',2751),
(2752,'import matplotlib.pyplot as plt\r\nimport numpy as np\r\nfrom sklearn.cluster import KMeans\r\nfrom sklearn.metrics import silhouette_score\r\nfrom sklearn.metrics import davies_bouldin_score\r\nfrom sklearn.cluster import DBSCAN\r\nfrom sklearn.preprocessing import StandardScaler\r\ndatos = []\r\n\r\nwith open(\"datos_agrupamiento.csv\",\"r\") as txt:\r\n    for linea in txt:\r\n        x,y,c = linea.split(\',\')\r\n        datos.append([float(x),float(y)])\r\nscaler=StandardScaler()\r\ndatos = scaler.fit_transform(datos)\r\ndatos_x = [dato[0] for dato in datos]\r\ndatos_y = [dato[1] for dato in datos]\r\nxx = [z for z in range(2,300)]\r\nyy_sc = []\r\nyy_db = []\r\n#for jj in xx:\r\n#    #plt.scatter(datos_x,datos_y,marker = \'o\')\r\n#    modelo = KMeans(\r\n#        n_clusters=jj,\r\n#        random_state=42,\r\n#        n_init=\"auto\"\r\n#    )\r\n#    etiquetas=list(modelo.fit_predict(datos))\r\n#    c_x = [i[0] for i in modelo.cluster_centers_]\r\n#    c_y = [i[1] for i in modelo.cluster_centers_]\r\n#    #plt.plot(c_x,c_y,marker = \'*\', markersize = 10, color = \"#FF0000\",linestyle = \'\')\r\n#    silhouette=silhouette_score(datos,etiquetas)\r\n#    davies = davies_bouldin_score(datos,etiquetas)\r\n#    yy_sc.append(silhouette)\r\n#    yy_db.append(davies)\r\n#\r\n#\r\n#plt.plot(xx,yy_sc,marker = \'*\',markersize = 1,c = \"#0066ff\",label = \"Silhouette\")\r\n#plt.plot(xx,yy_db,marker = \'*\',markersize = 1,c = \"#d66320\",label = \"Davies\")\r\n#plt.legend(loc=\'upper left\')\r\n#plt.xlabel(\"K (Cantidad de Clusters)\")\r\n#plt.grid(True)\r\n#plt.show()\r\n\r\nmodelo_dbscan = DBSCAN(\r\n    eps = 0.3,\r\n    min_samples=2\r\n)\r\netiquetas_dbscan = list(modelo_dbscan.fit_predict(datos))\r\n\r\n#print(etiquedas_dbscan)\r\nprint(set(etiquetas_dbscan))\r\n\r\n#plt.scatter(datos_x,datos_y,c = etiquetas_dbscan)\r\n#plt.title(\"DBSCAN sobre datos de Papaya\")\r\n#plt.show()\r\n\r\nsil_1 = silhouette_score(datos,etiquetas_dbscan)\r\ndav_1 = davies_bouldin_score(datos,etiquetas_dbscan)\r\nprint(f\"Silhouette con atipicos: {sil_1}\")\r\nprint(f\"Davies con atipicos: {sil_1}\")\r\nsin_atipicos=[]\r\netiquetas_filtradas =[]\r\nfor i in range(len(datos)):\r\n    if etiquetas_dbscan[i]!=-1:\r\n        sin_atipicos.append(datos[i])\r\n        \r\n        etiquetas_filtradas.append(etiquetas_dbscan[i])\r\n\r\nn_etiquetas=len(set(etiquetas_filtradas))\r\n\r\nsin_atipicos = list(map(list,sin_atipicos))\r\nprint(sin_atipicos)\r\nsa_x = [i[0] for i in sin_atipicos]\r\nsa_y = [i[1] for i in sin_atipicos]\r\nplt.scatter(sa_x,sa_y,marker=\'o\',c=etiquetas_filtradas)\r\nplt.show()\r\n\r\n\r\nif n_etiquetas >1:\r\n    sil= silhouette_score(sin_atipicos, etiquetas_filtradas)\r\n    db =davies_bouldin_score(sin_atipicos, etiquetas_filtradas)\r\n    print(\"Clases noruido:\",n_etiquetas)\r\n    print(\"SilhouetteScore:\",sil)\r\n    print(\"Davies-Bouldin Index:\", db)\r\nelse:\r\n    print(\"Nohay suficientesclustersparaevaluar.\")',2752),
