(2761,'N = int(input())\r\numbral = int(input())\r\n\r\nanterior = int(input())\r\n\r\ncontador_alertas = 0\r\nsuma_diferencias = 0\r\n\r\nfor i in range(N - 1):\r\n    actual = int(input())\r\n    diferencia = abs(actual - anterior)\r\n\r\n    if diferencia > umbral:\r\n        print(\"ALERTA\")\r\n        contador_alertas += 1\r\n        suma_diferencias += diferencia\r\n    else:\r\n        print(\"OK\")\r\n\r\n    anterior = actual\r\n\r\nprint(contador_alertas)\r\n\r\nif contador_alertas > 0:\r\n    promedio = suma_diferencias / contador_alertas\r\nelse:\r\n    promedio = 0\r\n\r\nprint(f\"{promedio:.2f}\")',2761),
(2762,'import pycuda.autoinit\r\nimport pycuda.driver as drv\r\nimport numpy as np\r\nfrom pycuda.compiler import SourceModule\r\n\r\nmod = SourceModule(r\"\"\"\r\n__global__ void ShiftGPU(int n, int t, int *A){\r\n  extern __shared__ int temp[];\r\n  int i = threadIdx.x+blockIdx.x*blockDim.x;\r\n  for(int k = 1 ; k<=t ; k++){\r\n    temp[i]=A[(i+1)%n];\r\n    __syncthreads();\r\n    A[i] = temp[i];\r\n    __syncthreads();\r\n  }\r\n}\r\n\"\"\")\r\n\r\nn = 127\r\nt = 2**28\r\n\r\nA = np.array(range(0,n),dtype = np.int32)\r\nShift = mod.get_function(\"ShiftGPU\")\r\n\r\n\r\ngdim = (1,1,1)\r\nbdim = (n,1,1)\r\n\r\nprint(\"Viejo Array: \", A)\r\ninicio = time.perf_counter()\r\nShift(np.int32(n),np.int32(t),drv.InOut(A), block=bdim, grid = gdim, shared = A.nbytes)\r\nfin = time.perf_counter()\r\ntiempo_total = fin - inicio\r\nprint(\"Nuevo Array: \", A)',2762),
