(2770,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    freopen(\"entrada.txt\",\"r\",stdin);\r\n    freopen(\"salida.txt\",\"w\",stdout);\r\n\r\n    while(true){\r\n        int n;\r\n        cin >> n;\r\n        if(n==0) break;\r\n        int ans = 1;\r\n        while(n%2==0){\r\n            n/=2;\r\n            ans++;\r\n        }\r\n        cout << n << \" \" << ans << ENDL;\r\n    }\r\n    return 0;\r\n}',2770),
