(2773,'HorizonteRojo = 0\r\nElMisterioDelLago = 0\r\nSueñosDePapel = 0\r\nwhile True:\r\n    entrada = input()\r\n    if entrada==\"FIN\":\r\n        break\r\n    pelicula,edad=entrada.split()\r\n    edad=int(edad)\r\n    if pelicula==\"HorizonteRojo\":\r\n        if edad>=18:\r\n            HorizonteRojo=HorizonteRojo+5000\r\n    if pelicula==\"ElMisterioDelLago\":\r\n        if edad>=13:\r\n            ElMisterioDelLago=ElMisterioDelLago+5000\r\n        else:\r\n            pass\r\n    if pelicula==\"SueñosDePapel\":\r\n        if edad>=12:\r\n            SueñosDePapel=SueñosDePapel+5000\r\n        else:\r\n            SueñosDePapel=SueñosDePapel+3000\r\nprint(\"HorizonteRojo:\", HorizonteRojo)\r\nprint(\"ElMisterioDelLago:\",ElMisterioDelLago)\r\nprint(\"SueñosDePapel:\",SueñosDePapel)',2773),
(2774,'while True:\r\n    a = int(input())\r\n    if a == 0:\r\n        break\r\n    c = 1\r\n    while a%2==0:\r\n        a = a//2\r\n        c+=1\r\n    print(a,c)',2774),
(2775,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    freopen(\"entrada.txt\",\"r\",stdin);\r\n    freopen(\"salida.txt\",\"w\",stdout);\r\n    int hr = 0;\r\n    int el = 0;\r\n    int sp = 0;\r\n    while(true){\r\n        string s;\r\n        cin >> s;\r\n        if(s==\"FIN\") break;\r\n        int n;\r\n        cin >> n;\r\n        if(s==\"SueñosDePapel\"){\r\n            if(n>=12) sp+=5000;\r\n            else sp+=3000;\r\n        }\r\n        if(s==\"HorizonteRojo\"){\r\n            if(n>=18) hr+=5000;\r\n        }\r\n        if(s==\"ElMisterioDelLago\"){\r\n            if(n>=13) el+=5000;\r\n        }\r\n    }\r\n    cout << \"HorizonteRojo: \" << hr << ENDL;\r\n    cout << \"ElMisterioDelLago: \" << el << ENDL;\r\n    cout << \"SueñosDePapel: \" << sp << ENDL;\r\n    return 0;\r\n}',2775),
(2776,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int hr = 0;\r\n    int el = 0;\r\n    int sp = 0;\r\n    while(true){\r\n        string s;\r\n        cin >> s;\r\n        if(s==\"FIN\") break;\r\n        int n;\r\n        cin >> n;\r\n        if(s==\"SueñosDePapel\"){\r\n            if(n>=12) sp+=5000;\r\n            else sp+=3000;\r\n        }\r\n        if(s==\"HorizonteRojo\"){\r\n            if(n>=18) hr+=5000;\r\n        }\r\n        if(s==\"ElMisterioDelLago\"){\r\n            if(n>=13) el+=5000;\r\n        }\r\n    }\r\n    cout << \"HorizonteRojo: \" << hr << ENDL;\r\n    cout << \"ElMisterioDelLago: \" << el << ENDL;\r\n    cout << \"SueñosDePapel: \" << sp << ENDL;\r\n    return 0;\r\n}',2776),
(2777,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    int ans = 0;\r\n    for(int i = 0 ; i<n ; i++){\r\n        char c;\r\n        cin >> c;\r\n        int x;\r\n        cin >> x;\r\n        ans+=x*500;\r\n        if(c==\'D\') ans+=2000;\r\n        if(c==\'P\') ans+=5000;\r\n    }\r\n    cout << ans << ENDL;\r\n}\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int t = 1;\r\n    while(t--){\r\n        solve();\r\n    }\r\n    return 0;\r\n}',2777),
(2778,'a = int(input())\r\nk = 0\r\nfor _ in range(a):\r\n    a,b = input().split()\r\n    b = int(b)\r\n    if a == \"D\":\r\n        k +=2000\r\n    elif a == \"P\":\r\n        k+=5000\r\n    k = k+(b*500)\r\nprint(k)',2778),
(2779,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    vi v(3);\r\n    int n = 0;\r\n    while(true){\r\n        char c;\r\n        cin >> c;\r\n        if(c==\'R\') break;\r\n        if(c==\'F\') v[n]++;\r\n        if(c==\'T\'){\r\n            n++;\r\n            n = n%3;\r\n        }\r\n    }\r\n    cout << v[0] << \" \" << v[1] << \" \" << v[2] << ENDL;\r\n    return 0;\r\n}',2779),
(2780,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    \r\n    vi v(3);\r\n    int n = 0;\r\n    while(true){\r\n        char c;\r\n        cin >> c;\r\n        if(c==\'R\') break;\r\n        if(c==\'F\') v[n]++;\r\n        if(c==\'T\'){\r\n            n++;\r\n            n = n%3;\r\n        }\r\n    }\r\n    cout << v[0] << \" \" << v[1] << \" \" << v[2] << ENDL;\r\n    return 0;\r\n}',2780),
