(2783,'lista = [0,0,0]\r\nturno = 0\r\nwhile True:\r\n    a = input()\r\n    if a == \"F\":\r\n        lista[turno] +=1\r\n    elif a == \"T\":\r\n        if turno == 2:\r\n            turno = 0\r\n        else:\r\n            turno+=1\r\n    elif a == \"R\":\r\n        break\r\nprint(*lista)',2783),
(2784,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define vi vector<int>\r\n#define ll long long\r\n#define pb push_back\r\n#define ENDL \"\\n\"\r\n\r\n\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    vi r(4);\r\n    for(int i = 0 ; i<4 ; i++){\r\n        cin >> r[i];\r\n    }\r\n    vi p(4);\r\n    for(int i = 0 ; i<4 ; i++){\r\n        cin >> p[i];\r\n    }\r\n    double pi = 3.141592;\r\n    vector<double> pp(4);\r\n    for(int i = 0 ; i<4 ; i++){\r\n        pp[i] = p[i]/(r[i]*r[i]*pi);\r\n    }\r\n    int m = INT32_MAX;\r\n    int ans = 0;\r\n    for(int i = 0 ; i<4 ; i++){\r\n        if(m>pp[i]){\r\n            m = pp[i];\r\n            ans = i;\r\n        }\r\n    }\r\n    vector<string> respuesta = {\"pequeña\",\"mediana\",\"grande\",\"familiar\"};\r\n    cout << respuesta[ans] << ENDL;\r\n}',2784),
(2785,'import math\r\npi = math.pi\r\nrp,rm,rg,rf=map(float,input().split())\r\npp,pm,pg,pf =mpa(float,input().split())\r\npequeña = pp/(rp*rp*pi)\r\nmediana = pm/(rm*rm*pi)\r\ngrande = pg/(rg*rg*pi)\r\nfamiliar = pf/(rf*rf*pi)\r\nlista =[pequeña,mediana,grande,familiar]\r\nlista.sort()\r\nif lista.index(pequeña) == 0:\r\n    print(\"pequeña\")\r\nelif lista.index(mediana) == 0:\r\n    print(\"mediana\")\r\nelif lista.index(grande) == 0:\r\n    print(\"grande\")\r\nelif lista.index(familiar) == 0:\r\n    print(\"familiar\")',2785),
(2786,'import math\r\npi = math.pi\r\nradios = input()\r\nrp , rm , rg , rf = radios.split()\r\nrp = float(rp)\r\nrm = float(rm)\r\nrg = float(rg)\r\nrf = float(rf)\r\nprecios = input()\r\npp , pm, pg , pf = precios.split()\r\npp = float(pp)\r\npm = float(pm)\r\npg = float(pg)\r\npf = float(pf)\r\npequeña = pp/(rp*rp*pi)\r\nmediana = pm/(rm*rm*pi)\r\ngrande = pg/(rg*rg*pi)\r\nfamiliar = pf/(rf*rf*pi)\r\nlista = [pequeña,mediana,grande,familiar]\r\nlista.sort()\r\nif lista.index(pequeña) == 0:\r\n    print(\"pequeña\")\r\nelif lista.index(mediana) == 0:\r\n    print(\"mediana\")\r\nelif lista.index(grande) == 0:\r\n    print(\"grande\")\r\nelif lista.index(familiar) == 0:\r\n    print(\"familiar\")',2786),
(2787,'a,b = map(int, input().split())\r\nmatriz = []\r\nfor _ in range(a):\r\n  c = list(map(int,input().split()))\r\n  matriz.append(c)\r\nfilas = len(matriz)\r\ncolumnas = len(matriz[0])\r\n\r\n# Límites\r\narriba = 0\r\nabajo = filas - 1\r\nizquierda = 0\r\nderecha = columnas - 1\r\n\r\nx = 0\r\ny = 0\r\n\r\ndireccion = \"derecha\"\r\nsolucion = []\r\n\r\nfor _ in range(filas * columnas):\r\n    solucion.append(matriz[x][y])\r\n\r\n    if direccion == \"derecha\":\r\n        if y == derecha:\r\n            direccion = \"abajo\"\r\n            arriba += 1\r\n            x += 1\r\n        else:\r\n            y += 1\r\n    elif direccion == \"abajo\":\r\n        if x == abajo:\r\n            direccion = \"izquierda\"\r\n            derecha -= 1\r\n            y -= 1\r\n        else:\r\n            x += 1\r\n\r\n    elif direccion == \"izquierda\":\r\n        if y == izquierda:\r\n            direccion = \"arriba\"\r\n            abajo -= 1\r\n            x -= 1\r\n        else:\r\n            y -= 1\r\n\r\n    elif direccion == \"arriba\":\r\n        if x == arriba:\r\n            direccion = \"derecha\"\r\n            izquierda += 1\r\n            y += 1\r\n        else:\r\n            x -= 1\r\n\r\nprint(solucion)',2787),
(2788,'a,b = map(int, input().split())\r\nmatriz = []\r\nfor _ in range(a):\r\n  c = list(map(int,input().split()))\r\n  matriz.append(c)\r\nfilas = len(matriz)\r\ncolumnas = len(matriz[0])\r\n\r\n# Límites\r\narriba = 0\r\nabajo = filas - 1\r\nizquierda = 0\r\nderecha = columnas - 1\r\n\r\nx = 0\r\ny = 0\r\n\r\ndireccion = \"derecha\"\r\nsolucion = []\r\n\r\nfor _ in range(filas * columnas):\r\n    solucion.append(matriz[x][y])\r\n\r\n    if direccion == \"derecha\":\r\n        if y == derecha:\r\n            direccion = \"abajo\"\r\n            arriba += 1\r\n            x += 1\r\n        else:\r\n            y += 1\r\n    elif direccion == \"abajo\":\r\n        if x == abajo:\r\n            direccion = \"izquierda\"\r\n            derecha -= 1\r\n            y -= 1\r\n        else:\r\n            x += 1\r\n\r\n    elif direccion == \"izquierda\":\r\n        if y == izquierda:\r\n            direccion = \"arriba\"\r\n            abajo -= 1\r\n            x -= 1\r\n        else:\r\n            y -= 1\r\n\r\n    elif direccion == \"arriba\":\r\n        if x == arriba:\r\n            direccion = \"derecha\"\r\n            izquierda += 1\r\n            y += 1\r\n        else:\r\n            x -= 1\r\nz = \" \".join(str(solucion).split(\",\"))\r\nz = z.replace(\"[\",\"\")\r\nz = z.replace(\"]\",\"\")\r\nprint(z)',2788),
(2789,'while True:\r\n  n,m = map(int,input().split())\r\n  if n== 0 and m == 0:\r\n    break\r\n  else:\r\n    p1 = []\r\n    p2 = []\r\n    C = 0\r\n    E = 0\r\n    T = 0\r\n    for i in range(n):\r\n      a = list(map(int,input().split()))\r\n      p1.append(a)\r\n    for i in range(n):\r\n      a = list(map(int,input().split()))\r\n      p2.append(a)\r\n    \r\n    for i in range(n):\r\n      for j in range(m):\r\n        T+=1\r\n        if p1[n][m] == p2[n][m]:\r\n          C+=1\r\n        else:\r\n          E+=1\r\n    if E> T*0.1:\r\n      print(\"La pintura no es original\")\r\n    else:\r\n      print(\"La pintura es original\")',2789),
(2790,'while True:\r\n  n,m = map(int,input().split())\r\n  if n== 0 and m == 0:\r\n    break\r\n  else:\r\n    p1 = []\r\n    p2 = []\r\n    C = 0\r\n    E = 0\r\n    T = 0\r\n    for i in range(n):\r\n      a = list(map(int,input().split()))\r\n      p1.append(a)\r\n    for i in range(n):\r\n      a = list(map(int,input().split()))\r\n      p2.append(a)\r\n    \r\n    for i in range(n):\r\n      for j in range(m):\r\n        T+=1\r\n        if p1[m][n] == p2[m][n]:\r\n          C+=1\r\n        else:\r\n          E+=1\r\n    if E> T*0.1:\r\n      print(\"La pintura no es original\")\r\n    else:\r\n      print(\"La pintura es original\")',2790),
(2791,'while True:\r\n  n,m = map(int,input().split())\r\n  if n== 0 and m == 0:\r\n    break\r\n  else:\r\n    p1 = []\r\n    p2 = []\r\n    C = 0\r\n    E = 0\r\n    T = 0\r\n    for i in range(n):\r\n      a = list(map(int,input().split()))\r\n      p1.append(a)\r\n    for i in range(n):\r\n      a = list(map(int,input().split()))\r\n      p2.append(a)\r\n    \r\n    for i in range(n):\r\n      for j in range(m):\r\n        T+=1\r\n        if p1[i][j] == p2[i][j]:\r\n          C+=1\r\n        else:\r\n          E+=1\r\n    if E> T*0.1:\r\n      print(\"La pintura no es original\")\r\n    else:\r\n      print(\"La pintura es original\")',2791),
(2792,'T  = int(input())\r\n\r\nif T<0:\r\n    print(\"El agua estara en estado solido \")\r\nelif 0<T<100:\r\n    print(\"El agua estara en estado liquido\")\r\nelse:\r\n    print(\"El agua estara en estado gaseoso\")',2792),
(2793,'T  = int(input())\r\n\r\nif T<0:\r\n    print(\"El agua estara en estado solid \")\r\nelif 0<T<100:\r\n    print(\"El agua estara en estado liquido\")\r\nelse:\r\n    print(\"El agua estara en estado gaseoso\")',2793),
(2794,'# Solución simple al problema\r\n\r\n# Leer la cantidad de gotas\r\nn = int(input())\r\n\r\n# Contadores:\r\n# C = gotas dentro o sobre el círculo\r\n# S = gotas dentro o sobre el cuadrado\r\ndentro_circulo = 0\r\ndentro_cuadrado = 0\r\n\r\n# Leer las coordenadas de cada gota\r\nfor _ in range(n):\r\n    x, y = map(float, input().split())\r\n\r\n    # Verificar si la gota está dentro o sobre el cuadrado\r\n    if -1 <= x <= 1 and -1 <= y <= 1:\r\n        dentro_cuadrado += 1\r\n\r\n        # Verificar si también está dentro o sobre el círculo\r\n        if x * x + y * y <= 1:\r\n            dentro_circulo += 1\r\n\r\n# Calcular la estimación de pi\r\nestimacion_pi = 4.0 * dentro_circulo / dentro_cuadrado\r\n\r\n# Imprimir suficientes decimales para cumplir con la tolerancia\r\nprint(f\"{estimacion_pi:.10f}\")',2794),
