(2814,'valor_venta = float(input())\r\nif valor_venta>150000:\r\n    valor_venta = valor_venta*0.75\r\n    iva = valor_venta*0.19\r\n    print(\"%.2f\" % iva)\r\nelse:\r\n    iva = valor_venta*0.19\r\n    print(\"%.2f\" % iva)',2814),
(2815,'pago, horas = map(int, input().split())\r\nif horas <=40:\r\n    dinero = pago*horas\r\n    print(\"%.1f\" % dinero)\r\nelif horas>=40:\r\n    dinero = pago*40 + pago*1.5*(horas-40)\r\n    print(\"%.1f\" % dinero)',2815),
(2816,'descartes= 0\r\nexportacion = 0\r\nnacional = 0\r\nwhile True:\r\n    tamaño = input()\r\n    if tamaño == \"-1\":\r\n        break\r\n    color = input()\r\n    if tamaño ==\"P\":\r\n        descartes= descartes +1\r\n    if tamaño == \"G\" and color ==\"R\":\r\n        exportacion = exportacion+1\r\n    if tamaño == \"G\" and color ==\"V\":\r\n        exportacion = exportacion+1\r\n    if color == \"A\" and tamaño==\"G\":\r\n        nacional = nacional +1\r\nprint(descartes)\r\nprint(exportacion)\r\nprint(nacional)',2816),
(2817,'descartes= 0\r\nexportacion = 0\r\nnacional = 0\r\nwhile True:\r\n    tamaño = input()\r\n    if tamaño == \"-1\":\r\n        break\r\n    color = input()\r\n    if tamaño ==\"P\":\r\n        descartes= descartes +1\r\n    if tamaño == \"G\" and color ==\"R\":\r\n        exportacion = exportacion+1\r\n    if tamaño == \"G\" and color ==\"V\":\r\n        exportacion = exportacion+1\r\n    if color == \"A\" and tamaño==\"G\":\r\n        nacional = nacional +1\r\nprint(descartes)\r\nprint(nacional)\r\nprint(exportacion)',2817),
(2818,'while True:\r\n    numero = int(input())\r\n    if numero == 0:\r\n            break\r\n    if numero%3==0 and numero%5!=0:\r\n        print(\"MÚLTIPLO DE 3\")\r\n    if numero%3!=0 and numero%5==0:\r\n            print(\"MÚLTIPLO DE 5\")\r\n    if numero%3==0 and numero%5==0:\r\n                print(\"MÚLTIPLO DE AMBOS\")\r\n    if numero%3!=0 and numero%5!=0:\r\n                print(\"NO ES MÚLTIPLO NI DE 3 NI DE 5\")',2818),
(2819,'while True:\r\n    numero = int(input())\r\n    if numero == 0:\r\n            break\r\n    if numero%3==0 and numero%5!=0:\r\n        print(\"MÚLTIPLO DE 3\")\r\n    if numero%3!=0 and numero%5==0:\r\n            print(\"MÚLTIPLO DE 5\")\r\n    if numero%3==0 and numero%5==0:\r\n                print(\"MÚLTIPLO DE AMBOS\")\r\n    if numero%3!=0 and numero%5!=0:\r\n                print(\"NO ES MÚLTIPLO DE 3 NI DE 5\")',2819),
(2820,'print(\"%.2f\" % (3.14159265*(float(input())/2)**2))',2820),
(2821,'print(\"%.2f\" % (0.7853981625*(float(input()))**2))',2821),
(2822,'def es_primo(x):\r\n    if x < 2:\r\n        return False\r\n    if x == 2:\r\n        return True\r\n    if x % 2 == 0:\r\n        return False\r\n\r\n    limite = math.isqrt(x)\r\n    d = 3\r\n    while d*d <= x:\r\n        if x % d == 0:\r\n            return False\r\n        d += 2\r\n    return True\r\n\r\n\r\nt = int(input())\r\n\r\nfor _ in range(t):\r\n    n = int(input())\r\n\r\n    # La única carta que puede ganar contra todas las demás es n + 1.\r\n    # Esto sucede exactamente cuando n + 1 es primo.\r\n    if es_primo(n + 1):\r\n        print(\"YES\")\r\n    else:\r\n        print(\"NO\")',2822),
(2823,'def es_primo(x):\r\n    if x < 2:\r\n        return False\r\n    if x == 2:\r\n        return True\r\n    if x % 2 == 0:\r\n        return False\r\n\r\n    limite = math.isqrt(x)\r\n    d = 3\r\n    while d*d <= x:\r\n        if x % d == 0:\r\n            return False\r\n        d += 2\r\n    return True\r\n\r\n\r\nt = int(input())\r\n\r\nfor _ in range(t):\r\n    n = int(input())\r\n\r\n    # La única carta que puede ganar contra todas las demás es n + 1.\r\n    # Esto sucede exactamente cuando n + 1 es primo.\r\n    if es_primo(n + 1):\r\n        print(\"YES\")\r\n    else:\r\n        print(\"NO\")',2823),
(2824,'import math\r\n\r\ndef es_primo(x):\r\n    if x < 2:\r\n        return False\r\n    if x == 2:\r\n        return True\r\n    if x % 2 == 0:\r\n        return False\r\n\r\n    limite = math.isqrt(x)\r\n    d = 3\r\n    while d <= limite:\r\n        if x % d == 0:\r\n            return False\r\n        d += 2\r\n    return True\r\n\r\n\r\nt = int(input())\r\n\r\nfor _ in range(t):\r\n    n = int(input())\r\n\r\n    # La única carta que puede ganar contra todas las demás es n + 1.\r\n    # Esto sucede exactamente cuando n + 1 es primo.\r\n    if es_primo(n + 1):\r\n        print(\"YES\")\r\n    else:\r\n        print(\"NO\")',2824),
(2825,'def es_primo(x):\r\n    if x < 2:\r\n        return False\r\n    if x == 2:\r\n        return True\r\n    if x % 2 == 0:\r\n        return False\r\n\r\n\r\n    d = 3\r\n    while d**2 <= x:\r\n        if x % d == 0:\r\n            return False\r\n        d += 2\r\n    return True\r\n\r\n\r\nt = int(input())\r\n\r\nfor _ in range(t):\r\n    n = int(input())\r\n\r\n    # La única carta que puede ganar contra todas las demás es n + 1.\r\n    # Esto sucede exactamente cuando n + 1 es primo.\r\n    if es_primo(n + 1):\r\n        print(\"YES\")\r\n    else:\r\n        print(\"NO\")',2825),
(2826,'n = int(input())\r\n\r\nsesiones = []\r\n\r\nfor _ in range(n):\r\n    inicio, fin = map(int, input().split())\r\n    sesiones.append((inicio, fin))\r\n\r\n# Ordenamos por hora de finalización\r\nsesiones.sort(key=lambda x: x[1])\r\n\r\n# dp[i] = máxima cantidad de sesiones si la última sesión\r\n# a la que asistimos es la sesión i\r\ndp = [1] * n\r\n\r\nrespuesta = 1\r\n\r\nfor i in range(n):\r\n    inicio_i, fin_i = sesiones[i]\r\n\r\n    for j in range(i):\r\n        inicio_j, fin_j = sesiones[j]\r\n\r\n        # Podemos asistir a i después de j si j termina\r\n        # antes o exactamente cuando comienza i\r\n        if fin_j <= inicio_i:\r\n            dp[i] = max(dp[i], dp[j] + 1)\r\n\r\n    respuesta = max(respuesta, dp[i])\r\n\r\nprint(respuesta)',2826),
(2827,'n = int(input())\r\n\r\nsesiones = []\r\n\r\nfor _ in range(n):\r\n    inicio, fin = map(int, input().split())\r\n    sesiones.append((fin, inicio))\r\n\r\n# Para maximizar la cantidad de sesiones, conviene elegir siempre\r\n# la sesión disponible que termina más temprano.\r\nsesiones.sort()\r\n\r\nrespuesta = 0\r\nultimo_fin = -1\r\n\r\nfor fin, inicio in sesiones:\r\n    # Se puede entrar si la sesión comienza justo cuando terminó\r\n    # la anterior, o en cualquier momento posterior.\r\n    if inicio >= ultimo_fin:\r\n        respuesta += 1\r\n        ultimo_fin = fin\r\n\r\nprint(respuesta)',2827),
(2828,'#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\nvoid solve(){\r\n    int n;\r\n    cin >> n;\r\n    vector<pair<int,int>> v;\r\n    for(int i = 0 ; i< n ; i++){\r\n        int in,fn;\r\n        cin >> in >> fn;\r\n        v.push_back({fn,in});\r\n    }\r\n    sort(v.begin(),v.end());\r\n    int M = 1;\r\n    int f_ac = v[0].first;\r\n    for(int i = 1 ; i<n ; i++){\r\n        if(v[i].second >= f_ac){\r\n            M++;\r\n            f_ac = v[i].first;\r\n        }\r\n    }\r\n    cout << M << \"\\n\";\r\n}\r\nint main(){\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n    solve();\r\n    return 0;\r\n}',2828),
(2829,'#include <iostream>\r\n#sing namespace std;\r\n\r\nint main() {\r\n    cout<<\"Hola Mundo\";\r\n    return 0;\r\n    \r\n}',2829),
