INSERT INTO `judge_ticketmessage` VALUES
(1,'en el primer caso la salida de 250000 es 35625.00 lo cual es incorrecto porque a los montos sobre 150000 se le debe aplicar un descuento del 25% y luego al nuevo monto aplicarle el IVA tomándolo como 19% \r\nel monto de 250000 con el 25% de descuento es 187500 y al aplicarle el IVA al nuevo monto nos da 223125','2025-09-06 23:18:19.488153',1,27),
(2,'Lea bien lo que se pregunta','2025-09-07 05:21:09.492278',1,2),
