(2,'2','json','[{\"model\": \"judge.organization\", \"pk\": 2, \"fields\": {\"name\": \"Universidad Católica del Maule\", \"slug\": \"universidad-catolica-del-maule\", \"short_name\": \"UCM\", \"about\": \"La Universidad Católica del Maule (UCM) es una institución de educación superior fundada el 10 de julio de 1991, derivada de la antigua Sede Regional de la Pontificia Universidad Católica de Chile, con orígenes que se remontan a las Escuelas Normales de la década de 1950. Su casa central se encuentra en Talca y cuenta con sedes en Curicó y Los Niches, integrándose al Consejo de Rectores de las Universidades Chilenas (CRUCH), a la Red G9 de universidades públicas no estatales y a la Agrupación de Universidades Regionales de Chile.\", \"creation_date\": \"2025-08-05T19:56:21.352Z\", \"is_open\": false, \"slots\": null, \"access_code\": null, \"logo_override_image\": \"\", \"class_required\": false, \"admins\": [2]}}]','Universidad Católica del Maule',17,2,'default'),
(3,'8','json','[{\"model\": \"judge.problem\", \"pk\": 8, \"fields\": {\"code\": \"areacirculo\", \"name\": \"Área de un círculo\", \"description\": \"# Área de una circunferencia #\\r\\n\\r\\nDado el diámetro de una circunferencia, se pide calcular su área. Se debe utilizar ~\\\\pi~ con 8 decimales.\\r\\n\\r\\n**Descripción de la entrada:**\\r\\nUn número real positivo que representa el diámetro de la circunferencia.\\r\\n\\r\\n**Descripción de la salida:**\\r\\nUn número real con 2 decimales que representa el área de la circunferencia.\\r\\n\\r\\n## Casos de prueba: ##\\r\\n**Caso de prueba 1:**\\r\\n<table> \\r\\n<tr><th>Entrada</th> \\r\\n<th>Salida</th></tr> \\r\\n<tr><td>\\r\\n<pre>\\r\\n10.0\\r\\n</pre>\\r\\n  </td> \\r\\n<td><pre>\\r\\n78.54\\r\\n</pre></td></tr>\\r\\n</table>\\r\\n**Caso de prueba 2:**\\r\\n<table> \\r\\n<tr><th>Entrada</th> \\r\\n<th>Salida</th></tr> \\r\\n<tr><td>\\r\\n<pre>\\r\\n15.75\\r\\n</pre>\\r\\n  </td> \\r\\n<td><pre>\\r\\n194.83\\r\\n</pre></td></tr>\\r\\n</table>\\r\\n**Caso de prueba 3:**\\r\\n<table> \\r\\n<tr><th>Entrada</th> \\r\\n<th>Salida</th></tr> \\r\\n<tr><td>\\r\\n<pre>\\r\\n5678.90\\r\\n</pre>\\r\\n  </td> \\r\\n<td><pre>\\r\\n25329016.29\\r\\n</pre></td></tr>\\r\\n</table>\", \"group\": 2, \"time_limit\": 1.5, \"memory_limit\": 102400, \"short_circuit\": false, \"points\": 1.0, \"partial\": false, \"is_public\": true, \"is_manually_managed\": false, \"date\": \"2023-08-21T19:22:54-04:00\", \"license\": null, \"og_image\": \"\", \"summary\": \"\", \"user_count\": 0, \"ac_rate\": 0.0, \"is_full_markup\": false, \"submission_source_visibility_mode\": \"F\", \"is_organization_private\": true, \"authors\": [], \"curators\": [], \"testers\": [], \"types\": [3], \"allowed_languages\": [3, 17, 4, 16, 5, 6, 13, 15, 18, 11, 2, 9, 14, 7, 1, 8, 12, 10], \"banned_users\": [], \"organizations\": [2]}}]','Área de un círculo',19,3,'default'),
