d>\\r\\n<td>\\r\\n<pre>\\r\\n# Collatz para n = 8\\r\\n8\\r\\n4\\r\\n2\\r\\n1\\r\\n# Collatz para n = 5\\r\\n5\\r\\n16\\r\\n8\\r\\n4\\r\\n2\\r\\n1\\r\\n</pre>\\r\\n</td>\\r\\n</tr>\\r\\n</table>\\r\\n\\r\\n**Casos de prueba:**  \\r\\n**Caso de prueba 2:**  \\r\\n<table>\\r\\n<tr>\\r\\n<th>Entrada</th>\\r\\n<th>Salida</th>\\r\\n</tr>\\r\\n<tr>\\r\\n<td>\\r\\n<pre>\\r\\n3\\r\\n6\\r\\n3\\r\\n7\\r\\n</pre>\\r\\n</td>\\r\\n<td>\\r\\n<pre>\\r\\n# Collatz para n = 6\\r\\n6\\r\\n3\\r\\n10\\r\\n5\\r\\n16\\r\\n8\\r\\n4\\r\\n2\\r\\n1\\r\\n# Collatz para n = 3\\r\\n3\\r\\n10\\r\\n5\\r\\n16\\r\\n8\\r\\n4\\r\\n2\\r\\n1\\r\\n# Collatz para n = 7\\r\\n7\\r\\n22\\r\\n11\\r\\n34\\r\\n17\\r\\n52\\r\\n26\\r\\n13\\r\\n40\\r\\n20\\r\\n10\\r\\n5\\r\\n16\\r\\n8\\r\\n4\\r\\n2\\r\\n1\\r\\n</pre>\\r\\n</td>\\r\\n</tr>\\r\\n</table>\", \"group\": 2, \"time_limit\": 2.0, \"memory_limit\": 102400, \"short_circuit\": false, \"points\": 1.0, \"partial\": false, \"is_public\": false, \"is_manually_managed\": false, \"date\": \"2025-10-08T12:22:03-04:00\", \"license\": null, \"og_image\": \"\", \"summary\": \"\", \"user_count\": 3, \"ac_rate\": 60.0, \"is_full_markup\": false, \"submission_source_visibility_mode\": \"F\", \"is_organization_private\": true, \"authors\": [2], \"curators\": [2], \"testers\": [2], \"types\": [10, 3], \"allowed_languages\": [3, 17, 4, 16, 5, 6, 13, 15, 18, 11, 2, 9, 14, 7, 1, 8, 12, 10], \"banned_users\": [], \"organizations\": [2]}}]','Secuencia de Collatz',19,282,'default'),
