(1613,'37','json','[{\"model\": \"judge.profile\", \"pk\": 37, \"fields\": {\"user\": 41, \"about\": \"a, b = map(int, input().split())\\r\\nfilas = [list(input()) for _ in range(a)]\\r\\n\\r\\ncambio=True\\r\\nwhile cambio:\\r\\n    cambio = False\\r\\n    for i in range(a-2, -1, -1):\\r\\n        for j in range(b+2):\\r\\n            if filas[i][j]!=\\\" \\\" and filas[i+1][j]==\\\" \\\":\\r\\n                filas[i+1][j]=filas[i][j]\\r\\n                filas[i][j]=\\\" \\\"\\r\\n                cambio=True\\r\\nfor i in filas:\\r\\n    print(\\\"\\\".join(i))\", \"timezone\": \"America/Toronto\", \"language\": 8, \"performance_points\": 47.59984537488809, \"problem_count\": 36, \"ace_theme\": \"github\", \"display_rank\": \"user\", \"mute\": false, \"is_unlisted\": false, \"is_banned_from_problem_voting\": false, \"user_script\": \"\", \"current_contest\": null, \"math_engine\": \"auto\", \"is_totp_enabled\": false, \"is_webauthn_enabled\": false, \"totp_key\": null, \"scratch_codes\": null, \"last_totp_timecode\": 0, \"api_token\": null, \"notes\": \"\", \"data_last_downloaded\": null, \"username_display_override\": \"\", \"organizations\": [2]}}]','carlos.nava',26,480,'default'),
