(1940,'29','json','[{\"model\": \"judge.profile\", \"pk\": 29, \"fields\": {\"user\": 33, \"about\": \"n1,m1 = map(int, input().split())\\r\\ngrid1 = [list(map(int, input().split())) for i in range(n1)]\\r\\nn2,m2 = map(int, input().split())\\r\\ngrid2 = [list(map(int, input().split())) for j in range(n2)]\\r\\n\\r\\n\\r\\nprint(grid1,grid2)\\r\\nif m1 == n2:\\r\\n    lista2=[]\\r\\n\\r\\n    for c in range(2):\\r\\n        for a in range(2):\\r\\n\\r\\n            lista3=[]\\r\\n            if a%2 == 0:\\r\\n                lista1=[]\\r\\n                for b in range(3):\\r\\n                    print(\\\"En que grid estamos:\\\",grid2[b][a],grid1[a][b])\\r\\n                    multd = grid1[a][b]*grid2[b][a]\\r\\n                    lista1.append(multd)\\r\\n                    print(\\\"multd: \\\",lista1)\\r\\n                lista2.append([sum(lista1)])\\r\\n            else:\\r\\n                lista1=[]\\r\\n                for b in range(3):\\r\\n                    print(\\\"Estamos en el else\\\\n\\\",grid2[b][a],grid1[a][b])\\r\\n                    multd = grid1[-a][b]*grid2[b][-a]\\r\\n                    lista1.append(multd)\\r\\n                lista2.append([sum(lista1)])\\r\\n\\r\\n        print(lista2)\\r\\nprint((grid1[0][0] * grid2[0][0]) + (grid1[0][1] * grid2[1][0]) + (grid1[0][2] * grid2[2][0]))\\r\\nprint(lista1)\\r\\nprint(lista2)\", \"timezone\": \"America/Toronto\", \"language\": 8, \"performance_points\": 70.94460046114752, \"problem_count\": 63, \"ace_theme\": \"monokai\", \"display_rank\": \"user\", \"mute\": false, \"is_unlisted\": false, \"is_banned_from_problem_voting\": false, \"user_script\": \"\", \"current_contest\": null, \"math_engine\": \"auto\", \"is_totp_enabled\": false, \"is_webauthn_enabled\": false, \"totp_key\": null, \"scratch_codes\": \"[\\\"NWVVMK7M36ZHKMET\\\", \\\"ZILWF4HWGGJMONYC\\\", \\\"GCWD36M5S3CYDFFM\\\", \\\"MSXGINJTXF6UDRTT\\\", \\\"SOKYDKMCQK5K4QAA\\\"]\", \"last_totp_timecode\": 0, \"api_token\": null, \"notes\": \"\", \"data_last_downloaded\": null, \"username_display_override\": \"\", \"organizations\": [2, 3]}}]','agustin.fraile',26,561,'default'),
