(2490,'26','json','[{\"model\": \"judge.profile\", \"pk\": 26, \"fields\": {\"user\": 30, \"about\": \"while True:\\r\\n    tamo = input()\\r\\n    if tamo == \\\"0 0\\\":\\r\\n        break\\r\\n    else:\\r\\n        altura, ancho = map(int, tamo.split())\\r\\n        pintura1 = []\\r\\n        for _ in range(altura):\\r\\n            fila1 = input().split()\\r\\n            pintura1.append(fila1)\\r\\n        pintura2 = []\\r\\n        for _ in range(altura):\\r\\n            fila2 = input().split()\\r\\n            pintura2.append(fila2)\\r\\n        errores = 0\\r\\n        aciertos = 0\\r\\n        for i in range(altura):\\r\\n            for j in range(ancho):\\r\\n                if pintura1[i][j] == pintura2[i][j]:\\r\\n                    aciertos += 1\\r\\n                else:\\r\\n                    errores += 1\\r\\n        tamao = errores + aciertos\\r\\n        if tamao/10 >errores:\\r\\n            print(\\\"La pintura es original\\\")\\r\\n        else:\\r\\n            print(\\\"La pintura no es original\\\")\", \"timezone\": \"America/Toronto\", \"language\": 8, \"performance_points\": 85.21194628082945, \"problem_count\": 82, \"ace_theme\": \"github\", \"display_rank\": \"user\", \"mute\": false, \"is_unlisted\": false, \"is_banned_from_problem_voting\": false, \"user_script\": \"\", \"current_contest\": null, \"math_engine\": \"auto\", \"is_totp_enabled\": false, \"is_webauthn_enabled\": false, \"totp_key\": null, \"scratch_codes\": \"[\\\"Q3Z2JHVNAT53AOTU\\\", \\\"TTWJIVNPWGNRZR3P\\\", \\\"56BVOI4443TTII5B\\\", \\\"M5JUXJ7XNHABALEL\\\", \\\"SFNRJA47TIIDETR7\\\"]\", \"last_totp_timecode\": 0, \"api_token\": \"b10f0b754a9d4ae4aa0f8a2fe1adf5726f605976412a8f8ecee8ad1ee76caf01\", \"notes\": null, \"data_last_downloaded\": null, \"username_display_override\": \"\", \"organizations\": [2]}}]','cristobal.contreras',26,674,'default'),
(2491,'30','json','[{\"model\": \"judge.profile\", \"pk\": 30, \"fields\": {\"user\": 34, \"about\": \"wena nelson wena benja wena cris wena camilardo wena moises wena profe wena pedro wena alexa wena wena lucho wena dieglock\", \"timezone\": \"America/Toronto\", \"language\": 8, \"performance_points\": 66.14383381139538, \"problem_count\": 57, \"ace_theme\": \"github\", \"display_rank\": \"user\", \"mute\": false, \"is_unlisted\": false, \"is_banned_from_problem_voting\": false, \"user_script\": \"\", \"current_contest\": null, \"math_engine\": \"auto\", \"is_totp_enabled\": false, \"is_webauthn_enabled\": false, \"totp_key\": null, \"scratch_codes\": null, \"last_totp_timecode\": 0, \"api_token\": null, \"notes\": null, \"data_last_downloaded\": null, \"username_display_override\": \"\", \"organizations\": [2]}}]','sergio.garcia',26,675,'default'),
